"use strict";
const ENVIRONMENT_VERSION="environment-a8356aa65014";
const ENVIRONMENT_SEED=[{"id":"env838-2e272b372586cb81","subject":"环境学导论","chapter":"第1章 绪论","originalChapter":"第1章 绪论","originalChapterNumber":1,"section":"第1节 环境的概念及其组成","originalSection":"第1节 环境的概念及其组成","category":"knowledge","title":"环境的概念","question":"环境的概念","type":"简答题","answer":"环境学所研究的环境，是以人类为主体的外部世界，即人类赖以\n生存和发展的物质条件的综合体，包括自然环境和社会环境。\n①自然环境：直接或间接影响到人类的、一切自然形成的物质及\n其能量的总体。\n②人工环境：人类生存及活动范围内的社会物质、精神条件的总\n和。\n学长提示 : “环境 \"的范畴并非国定不变 ， 而是随着人类社会 、 科学技术的发展不断深\n化的 。 例如 ， 随着空间科学的发展 ， 现阶段不属于人类生邢环境的月球 ， 未来也有可\n能成为其组成部分 。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2000,2007,2026],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。","含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":19,"sourceRange":{"startPage":19,"startY":551.09,"endPage":20,"endY":159.82},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":["2000(名)、2007(名)、2026(简, 【重要程度:"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":1,"excerpts":[{"page":19,"src":"./assets/environment/env838-2e272b372586cb81-19.webp"},{"page":20,"src":"./assets/environment/env838-2e272b372586cb81-20.webp"}]},{"id":"env838-38ece10231ea1f1f","subject":"环境学导论","chapter":"第1章 绪论","originalChapter":"第1章 绪论","originalChapterNumber":1,"section":"第1节 环境的概念及其组成","originalSection":"第1节 环境的概念及其组成","category":"knowledge","title":"环境要素的概念","question":"环境要素的概念","type":"简答题","answer":"环境要素也称环境基质，是构成人类环境整体的各个独立的、性\n质不同的而又服从整体演化规律的基本物质组分。环境要素分为自然\n环境要素和人工环境要素。\n其属性可概括如下：最差(小)限制定律；等值性；整体性大于\n各个体之和；互相联系、相互依赖。\n①最差(小)限制律。整体环境的质量不是由环境诸要素的平均状态\n决定，而是受环境诸要素中那个与最优状态差距最大的要素的控制。\n这就是说，环境质量的好坏，取决于诸要素中处于“最差状态”的那个\n要素，而不能够因其他要素处于优良状态而得到弥补。因此，环境要\n素之间是不能相互替代的。\n②等值性。即各个环境要素，无论他们本身在规模上或者数量上如何\n不同，但只要是一个独立的要素，那么对于环境质量的限制作用无质\n的差异。也就是说任何一个环境要素，对于环境质量的限制，只有在\n他们处于最差状态时才具有等值性。\n③整体性大于个体之和。即一处环境的性质，不等于组成该环境各个\n要素性质之和，而是更丰富复杂。\n④相互联系，相互依赖。环境要素在地球演化史上先后出现，并相互\n联系相互依赖。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2005],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":20,"sourceRange":{"startPage":20,"startY":159.82,"endPage":21,"endY":69.12},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":["2005( 名), 【重要程度:"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":1,"excerpts":[{"page":20,"src":"./assets/environment/env838-38ece10231ea1f1f-20.webp"},{"page":21,"src":"./assets/environment/env838-38ece10231ea1f1f-21.webp"}]},{"id":"env838-d50ca123ad9338bb","subject":"环境学导论","chapter":"第1章 绪论","originalChapter":"第1章 绪论","originalChapterNumber":1,"section":"第1节 环境的概念及其组成","originalSection":"第1节 环境的概念及其组成","category":"knowledge","title":"环境质量","question":"环境质量","type":"简答题","answer":"环境质量，是在一个具体的环境内环境的总体或环境的某些要素\n对人类的生存和繁衍以及社会经济发展的适宜程度，是反映人类的具\n体要求而形成的对环境评定的一种概念。包括自然环境质量和社会环\n境质量。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2002,2014,2020,2021],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":21,"sourceRange":{"startPage":21,"startY":69.12,"endPage":21,"endY":266.89},"sourceKind":"original","originalOrdinal":"3","sourceMetadata":["2002(名、2014(名、2020 (名、2021(名,【重要程度:"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":1,"excerpts":[{"page":21,"src":"./assets/environment/env838-d50ca123ad9338bb-21.webp"}]},{"id":"env838-7a3f62f56a33fe33","subject":"环境学导论","chapter":"第1章 绪论","originalChapter":"第1章 绪论","originalChapterNumber":1,"section":"第1节 环境的概念及其组成","originalSection":"第1节 环境的概念及其组成","category":"knowledge","title":"环境容量与环境承载力","question":"环境容量与环境承载力","type":"简答题","answer":"环境容量，是在人类生存和自然生态系统不致受害的前提下某一\n环境所能容纳的污染物的最大负荷量，或一个生态系统在维持生命机\n体的再生能力、适应能力和更新能力的前提下承受有机体数量的最大\n限度。\n环境承载力，又称环境承受力或环境忍耐力，指在一定时期内，\n在维持相对稳定的前提下，环境资源所能容纳的人口规模和经济规模\n的大小。地球的面积和空间是有限的，资源也是有限的，显然它的承\n载力也是有限的。\n二者关系：环境容量强调的是环境系统对自然和人文系统排污的\n容纳能力，侧重体现和反映环境系统的自然属性，即内在的自然秉性\n和特质。环境承载力则强调在环境系统正常结构和功能的前提下，环\n境系统所能承受的人类社会经济活动的能力，侧重体现和反映环境系\n统的社会属性，即外在的社会秉性和特质。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2001,2006,2012,2015,2016],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":21,"sourceRange":{"startPage":21,"startY":266.89,"endPage":21,"endY":722.53},"sourceKind":"original","originalOrdinal":"4","sourceMetadata":["2001(填、2006(填、2012(名、2015(名、2016(名,【重要程度: 】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":1,"excerpts":[{"page":21,"src":"./assets/environment/env838-7a3f62f56a33fe33-21.webp"}]},{"id":"env838-5bcf970844666a99","subject":"环境学导论","chapter":"第1章 绪论","originalChapter":"第1章 绪论","originalChapterNumber":1,"section":"第1节 环境的概念及其组成","originalSection":"第1节 环境的概念及其组成","category":"knowledge","title":"环境污染的概念","question":"环境污染的概念","type":"简答题","answer":"环境污染指自然的或人类活动产生的有害物质或因子进入环境\n而超过环境的自净能力所引起环境系统的结构与功能发生变化，从而\n使环境的质量降低，对人类的生存与发展、生态系统和财产造成不利\n影响的现象。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2008,2009,2022],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":21,"sourceRange":{"startPage":21,"startY":722.53,"endPage":22,"endY":207.53},"sourceKind":"original","originalOrdinal":"5","sourceMetadata":["2008(名、2009(名、2022(名, 【重要程度:"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":1,"excerpts":[{"page":21,"src":"./assets/environment/env838-5bcf970844666a99-21.webp"},{"page":22,"src":"./assets/environment/env838-5bcf970844666a99-22.webp"}]},{"id":"env838-6021382c4bb89d61","subject":"环境学导论","chapter":"第1章 绪论","originalChapter":"第1章 绪论","originalChapterNumber":1,"section":"第1节 环境的概念及其组成","originalSection":"第1节 环境的概念及其组成","category":"knowledge","title":"环境污染的特点","question":"环境污染的特点","type":"简答题","answer":"它的特点可归纳为：复杂性、潜伏性、持久性、广泛性。\n①复杂性：首先，由于环境污染的源来自生产生活的各个领域，\n产生的污染物种类繁多，并且这些污染物常常是经过转化、代谢、富\n集等各种反应后，才导致污染损害。其次，与一般民事违法行为所造\n成损害不同，污染环境行为造成他人损害的过程非常复杂。\n②潜伏性：环境本身具有消化污染物的自净能力，但如果某种污\n染物的排放量超过环境的自净能力，环境不能消化掉的那部分污染物\n会慢慢地蓄积起来，最终导致损害的发生。\n③持续性：环境损害常常透过广大的空间和长久的时间，经过多\n种因素的复合积累后才形成，因此造成的损害是持续不断的。同时，\n由于受科学技术水平的制约，对一些污染损害缺乏有效的防治方法。\n因此，环境污染损害并不因为污染物的停止排放而立即消除，具有持\n续性。\n④广泛性：一是受害地域的广泛性，如海洋污染往往涉及周边的\n数个国家；二是受害对象的广泛性，包括全人类及其生存的环境；三\n是受害利益的广泛性，环境污染往往同时侵害人们的生命、健康、财\n产等。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":22,"sourceRange":{"startPage":22,"startY":207.53,"endPage":23,"endY":73.24},"sourceKind":"original","originalOrdinal":"6","sourceMetadata":["【重要程度："],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":1,"excerpts":[{"page":22,"src":"./assets/environment/env838-6021382c4bb89d61-22.webp"},{"page":23,"src":"./assets/environment/env838-6021382c4bb89d61-23.webp"}]},{"id":"env838-ed490ee4b73252b3","subject":"环境学导论","chapter":"第1章 绪论","originalChapter":"第1章 绪论","originalChapterNumber":1,"section":"第1节 环境的概念及其组成","originalSection":"第1节 环境的概念及其组成","category":"knowledge","title":"环境污染的危害","question":"环境污染的危害","type":"简答题","answer":"①大气污染与人体健康。大气污染主要是指大气的化学性污染。\n大气中化学污染物的种类很多，对人体危害严重的多达几十种。我国\n的大气污染属于煤炭型污染，主要污染物是烟尘和 ，此外还有NOx\n和CO等。这些污染物主要通过呼吸道进入人体，不经肝脏的解毒作用\n，直接由血液运输到全身。所以，大气的化学污染对人体健康的危害\n很大。\n②水污染与人体健康。河流、湖泊等水体被污染后，对人体健康\n会造成严重危害，主要表现在三个方面。第一，饮用污染的水和食用\n污水中的生物，能使人中毒，甚至死亡。第二，被人畜粪便和生活垃\n圾污染的水体，能够引起病毒性肝炎、细菌性痢疾等传染病，以及血\n吸虫病等寄生虫疾病。第三，一些具有致癌作用的化学物质，如As、\nCr、苯胺等污染水体后，可在水体中的悬浮物、底泥和水生生物体内\n蓄积。长期饮用这样的污水，容易诱发癌症。\n③固体废物污染与人体健康。固体废物是指人类在生产和生活中\n丢弃的固体物质。应当认识到，固体废物只是在某一过程或某一方面\n没有使用价值，实际上往往可作为另一生产过程的原料被利用，因此\n，固体废物又叫“放在错误地点的原料”。但是，这些“原料”往往含有\n多种对人体健康有害的物质，如不及时加以处理或利用，长期堆放，\n就会污染生态环境，对人体健康造成危害。\n④噪声污染与人体健康。噪声对人的危害是多方面的。第一，损\n伤听力。长期在强噪声中工作，听力就会下降，甚至造成噪声性耳聋\n。第二，干扰睡眠。当人的睡眠受到噪声干扰时，就不能消除疲劳、\n恢复体力。第三，诱发多种疾病。噪声会使人处在紧张状态，心率加\n快、血压升高，甚至诱发胃肠溃疡和内分泌系统功能紊乱等疾病。第\n四，影响心理健康。噪声使人心情烦躁，不能集中精力学习和工作，\n并且容易引发工伤和交通事故。\n学长提示 : 本书中大量出现类似于这种关于危害的综合性的说法 ， 即综合了很多章节\n的知识点 ， 比如环境污染的危害 ， 水体污染的危害等等 ， 对于这种类似的问题 ， 大家\n只需要记住他们的框架 ， 把握住答题的套路 ， 即便是没背到相应的知识点也知道大概\n的答题方向 ， 大概都是要涉及到人体的健康 ， 生物 〈 水生生物 、 陆生生物 ) 的健康 ，\n环境 〈 水环境 、 土环境 、 大气环境 ) 的健康","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":0,"pastExamYears":[2026],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。","含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":23,"sourceRange":{"startPage":23,"startY":73.24,"endPage":24,"endY":285.91},"sourceKind":"original","originalOrdinal":"7","sourceMetadata":["2026 (论--环境污染类型及对群众健康的影响)【重要程度：☆☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":1,"excerpts":[{"page":23,"src":"./assets/environment/env838-ed490ee4b73252b3-23.webp"},{"page":24,"src":"./assets/environment/env838-ed490ee4b73252b3-24.webp"}]},{"id":"env838-f27a7bacbe7447bd","subject":"环境学导论","chapter":"第1章 绪论","originalChapter":"第1章 绪论","originalChapterNumber":1,"section":"第1节 环境的概念及其组成","originalSection":"第1节 环境的概念及其组成","category":"knowledge","title":"环境的自净","question":"环境的自净","type":"简答题","answer":"环境受到污染后，在物理、化学和生物的作用下，逐步消除污染\n物达到自然净化的过程。环境自净按发生机理可分为物理净化、化\n学净化和生物净化三类。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2004],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":24,"sourceRange":{"startPage":24,"startY":285.91,"endPage":24,"endY":449.83},"sourceKind":"original","originalOrdinal":"8","sourceMetadata":["2004 (名,【重要程度:"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":1,"excerpts":[{"page":24,"src":"./assets/environment/env838-f27a7bacbe7447bd-24.webp"}]},{"id":"env838-27523f7fdcbab417","subject":"环境学导论","chapter":"第1章 绪论","originalChapter":"第1章 绪论","originalChapterNumber":1,"section":"第1节 环境的概念及其组成","originalSection":"第1节 环境的概念及其组成","category":"knowledge","title":"环境的组成","question":"环境的组成","type":"简答题","answer":"环境有自然环境与人工环境之分。自然环境是环绕人们周围的各\n种自然因素的总和，如大气、水、植物、动物、土壤、岩石矿物、太\n阳辐射等。人工环境是由人为设置边界面围合成的空间环境。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":24,"sourceRange":{"startPage":24,"startY":449.83,"endPage":24,"endY":615.25},"sourceKind":"original","originalOrdinal":"9","sourceMetadata":["【重要程度："],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":1,"excerpts":[{"page":24,"src":"./assets/environment/env838-27523f7fdcbab417-24.webp"}]},{"id":"env838-ed37c9e00b865b24","subject":"环境学导论","chapter":"第1章 绪论","originalChapter":"第1章 绪论","originalChapterNumber":1,"section":"第1节 环境的概念及其组成","originalSection":"第1节 环境的概念及其组成","category":"knowledge","title":"自然环境","question":"自然环境","type":"简答题","answer":"自然环境按人类对它们的影响程度以及它们所保存的结构形态、\n能量平衡，可分为原生环境和次生环境。\n原生环境受人类影响较少，物质的交换、迁移和转化，能量、信\n息的传递和物种的演化，基本上仍按自然界的规律进行，如某些原始\n森林地区、荒漠、冻原地区、大洋中心区等都是原生环境。\n次生环境是指人类活动影响下，物质的交换、迁移和转化，能\n量、信息的传递等都发生重大变化的环境，如耕地、种植园、城市、\n工业区等。\n自然环境又可分为非生物环境和生物环境。\n非生物环境：太阳、大气、水体以及土壤以各种不同的方式为生\n物组合成多种多样的无机环境，包括生物生存和生长所需的能源——\n太阳能和其他能源，气候——光照、温度、降水、风等，基质和介质\n——岩石、土壤、水、空气等，物质代谢原料—— 、水、 、\n、无机盐、有机质等。\n生物环境：包括植物、动物和微生物，按它们在环境中的功能\n与作用，可划分为生产者、消费者和分解者。生产者是指能以简单无\n机物制造食物的自养生物，包括所有绿色植物和能够进行光能和化\n能自养的细菌。消费者是指不能用无机物直接制造有机物，而是直接\n或间接依赖有机物的异养生物。分解者都是异养生物，包括细菌、真\n菌、放线菌以及原生动物和一些小型无脊椎动物等。它们把动物残体\n的复杂有机物分解为生产者能重新利用的简单化合物，并释放能量\n1-1 自然环境分类示意图","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。","含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":24,"sourceRange":{"startPage":24,"startY":615.25,"endPage":26,"endY":346.03},"sourceKind":"original","originalOrdinal":"10","sourceMetadata":["【重要程度："],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":1,"excerpts":[{"page":24,"src":"./assets/environment/env838-ed37c9e00b865b24-24.webp"},{"page":25,"src":"./assets/environment/env838-ed37c9e00b865b24-25.webp"},{"page":26,"src":"./assets/environment/env838-ed37c9e00b865b24-26.webp"}]},{"id":"env838-d9cf523531a2e752","subject":"环境学导论","chapter":"第1章 绪论","originalChapter":"第1章 绪论","originalChapterNumber":1,"section":"第1节 环境的概念及其组成","originalSection":"第1节 环境的概念及其组成","category":"knowledge","title":"人工环境","question":"人工环境","type":"简答题","answer":"广义的人工环境，是指为满足人类的需要，在自然物质的基础上\n通过人类长期有意识的社会劳动，加工和改造自然物质，创造物质生\n产体系，积累物质文化等所形成的环境体系。狭义的人工环境，是指\n由人为设置边界围合成的空间环境，如房屋围护结构围合成的民用\n建筑环境、生产环境和交通运输外壳围合成的交通运输环\n境( 如车厢环境、船舱环境) 等。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":1,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":26,"sourceRange":{"startPage":26,"startY":346.03,"endPage":26,"endY":595.1},"sourceKind":"original","originalOrdinal":"11","sourceMetadata":["【重要程度: ★☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":1,"excerpts":[{"page":26,"src":"./assets/environment/env838-d9cf523531a2e752-26.webp"}]},{"id":"env838-72fed20604f8615a","subject":"环境学导论","chapter":"第1章 绪论","originalChapter":"第1章 绪论","originalChapterNumber":1,"section":"第1节 环境的概念及其组成","originalSection":"第1节 环境的概念及其组成","category":"knowledge","title":"环境的几个特点","question":"环境的几个特点","type":"简答题","answer":"①整体性：环境中的各种因素(物理的、化学的、生物的、社\n会的)不是孤立存在的，而是互相依存、互相影响、互相联系的。\n②综合性：环境的综合性表现在两个方面。一是任何一个环境\n问题的产生，都是环境系统内多因素综合作用的结果，其中既有自然\n因素如温度、湿度及风的作用，更有人为因素如污染物的排放等作用\n，而且这些因素之间相互影响、相互制约。二是为了解决某一环境问\n题.往往需要综合涉及各个领域的学科，在一个总体目标或方案的构\n架下，有针对性地将涉及的各学科问题逐一解决。\n③区域性：不同地区的环境呈现明显的地域差异，形成不同的\n地域单元，称为环境的区域性。这也是由于环境中物质和能量的地域\n分异规律而形成的。\n④有限性：自然环境中蕴藏着大量的物质与能量，但这些资源\n都是有限的。\n⑤稳定性：环境的稳定性是指在无外界因素影响的条件下，环\n境内部保持相对平衡的状态。环境的稳定性是一种动态平衡，因此它\n是一种状态的物质循环、能量传递、信息交换的权衡。\n⑥滞后性：自然环境受到外界影响后，其变化及影响往往是滞\n后的。环境受到破坏后，产生的后果很难及时反映出来，有些甚至是\n难以预测的；环境一旦破坏，所需要的恢复时间长，尤其是超过阈值\n后，很难恢复。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2026],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":26,"sourceRange":{"startPage":26,"startY":595.1,"endPage":27,"endY":566.85},"sourceKind":"original","originalOrdinal":"12","sourceMetadata":["2026 (简-环境的定义和特点，【重要程度： l"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":1,"excerpts":[{"page":26,"src":"./assets/environment/env838-72fed20604f8615a-26.webp"},{"page":27,"src":"./assets/environment/env838-72fed20604f8615a-27.webp"}]},{"id":"env838-2cd82d45ba7dbb6e","subject":"环境学导论","chapter":"第1章 绪论","originalChapter":"第1章 绪论","originalChapterNumber":1,"section":"第2节 环境问题的产生","originalSection":"第2节 环境问题的产生","category":"knowledge","title":"环境问题的概念","question":"环境问题的概念","type":"简答题","answer":"环境问题，是指由于人类活动作用于周围环境所引起的环境质量\n变化，以及这种变化对人类的生产、生活和健康造成的影响。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2005,2013,2015,2019],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":27,"sourceRange":{"startPage":27,"startY":610.24,"endPage":27,"endY":755.52},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":["2005(选、2013(名、2015(名、2019(论,【重要程度:"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":1,"excerpts":[{"page":27,"src":"./assets/environment/env838-2cd82d45ba7dbb6e-27.webp"}]},{"id":"env838-0c77123bdfbf8e40","subject":"环境学导论","chapter":"第1章 绪论","originalChapter":"第1章 绪论","originalChapterNumber":1,"section":"第2节 环境问题的产生","originalSection":"第2节 环境问题的产生","category":"knowledge","title":"环境问题的分类","question":"环境问题的分类","type":"简答题","answer":"环境问题多种多样，归纳起来有两大类。\n一类是自然演变和自然灾害引起的原生环境问题，也叫第一环\n境问题，如地震、洪涝、干旱、台风、崩塌、滑坡、泥石流等导致的\n自然灾害，以及特殊的自然环境导致的地方病。\n另一类是人类活动引起的次生环境问题，也叫第二环境问题。次\n生环境问题一般又分为环境污染和环境破坏两大类，如乱砍滥伐引\n起的森林植被的破坏、过度放牧引起的草原退化、大面积开垦草原引\n起的沙漠化和土地沙化、工业生产造成大气、水环境恶化等。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2002,2021],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":27,"sourceRange":{"startPage":27,"startY":755.52,"endPage":28,"endY":314.49},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":["2002(填、2021 (论, 【重要程度: 】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":1,"excerpts":[{"page":27,"src":"./assets/environment/env838-0c77123bdfbf8e40-27.webp"},{"page":28,"src":"./assets/environment/env838-0c77123bdfbf8e40-28.webp"}]},{"id":"env838-e5a932de8adaa338","subject":"环境学导论","chapter":"第1章 绪论","originalChapter":"第1章 绪论","originalChapterNumber":1,"section":"第2节 环境问题的产生","originalSection":"第2节 环境问题的产生","category":"knowledge","title":"环境问题的产生与变化","question":"环境问题的产生与变化","type":"简答题","answer":"(1 )早期环境问题阶段\n环境问题的早期阶段，包括从人类诞生到工业革命之前的漫长历\n史时期。局部环境问题主要表现在土地方面，包括大量伐树、过度破\n坏草原、水土流失和土壤沙化。这一阶段的人类活动对环境的影响还\n是局部的，主要体现在生态退化，没有达到影响整个生物圈的程度。\n(2)近代环境问题阶段\n此阶段包括从工业革命时期到1984 年英国科学家发现、1985\n年美国科学家证实南极上空出现“臭氧层空洞”的这段时期。这一阶\n段的环境问题与工业和城市同步发展。\n近代环境问题阶段的特点，体现为由工业污染向城市污染和农业\n污染发展、点源污染向面源污染发展、局部污染向区域性和全球性污\n染发展，构成了第一次环境问题高潮。震惊世界的“八大公害”就发\n生在这一阶段。\n(3 )当代环境问题阶段\n从科学家证实南极上空出现“臭氧洞”开始，人类环境问题发展\n到当代环境问题阶段，引发了第二次世界环境问题的高潮。\n这一阶段环境问题的特征是，在全球范围内出现了不利于人类生\n存和发展的征兆，集中体现为酸雨、臭氧层破坏和全球变暖三大全球\n性大气环境问题。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2003,2007],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":28,"sourceRange":{"startPage":28,"startY":314.49,"endPage":29,"endY":240.4},"sourceKind":"original","originalOrdinal":"3","sourceMetadata":["2003 (填、2007 (填, 【重要程度: 】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":1,"excerpts":[{"page":28,"src":"./assets/environment/env838-e5a932de8adaa338-28.webp"},{"page":29,"src":"./assets/environment/env838-e5a932de8adaa338-29.webp"}]},{"id":"env838-ad0415114ea3d772","subject":"环境学导论","chapter":"第1章 绪论","originalChapter":"第1章 绪论","originalChapterNumber":1,"section":"第2节 环境问题的产生","originalSection":"第2节 环境问题的产生","category":"knowledge","title":"环境问题的实质","question":"环境问题的实质","type":"简答题","answer":"环境问题就是一个经济问题和社会问题，是人类自然的而且是自\n觉的建设人类文明的问题。当代人类面临的所谓环境污染，以及自然\n资源的不合理开发利用造成的森林的破坏、水土流失的加剧和资源的\n枯竭，都是人类经济活动的直接或间接的结果，而且环境污染和破坏\n的治理和控制，又必须有相当的经济实力。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":29,"sourceRange":{"startPage":29,"startY":240.4,"endPage":29,"endY":466.82},"sourceKind":"original","originalOrdinal":"4","sourceMetadata":["【重要程度："],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":1,"excerpts":[{"page":29,"src":"./assets/environment/env838-ad0415114ea3d772-29.webp"}]},{"id":"env838-83d6baf1175800c6","subject":"环境学导论","chapter":"第1章 绪论","originalChapter":"第1章 绪论","originalChapterNumber":1,"section":"第2节 环境问题的产生","originalSection":"第2节 环境问题的产生","category":"knowledge","title":"环境问题的六大特点","question":"环境问题的六大特点","type":"简答题","answer":"(1)全球化：近年来，一些环境污染具有跨国、跨地区的流\n动性的特点。一些国际河流，上游国家造成的污染，可能危及下游国\n家；一个国家大气污染造成的酸雨，可能会降到别国。\n(2)综合化：当代环境问题涉及人类生存环境的各个方面，\n包括森林锐减、草原退化、沙漠扩展、土壤侵蚀、物种减少、水源危\n机、气候异常、城市化问题等，已深入到人类生产、生活的各个方面\n(3)高技术化：随着当代科技的迅猛发展，由高新技术引\n发的环境问题日渐增多，如原子弹、导弹试验，核反应堆的使用及\n其事故，电磁波引起的环境问题，超音速飞机带来的臭氧层破坏、航\n天飞行的太空污染等。生物工程技术的潜在影响以及大型工程技术的\n开发利用都可能产生难以预测的生态灾难。这些环境问题技术含量\n高、影响范围广、控制难、后果严重，已引起世界各国的普遍关注。\n(4 )累积化：虽然人类已进入现代文明时期，进入后工业化\n、信息化时代，但历史上不同阶段所产生的环境问题，在当今地球上\n依然存在；同时，现代社会又滋生出一系列的环境问题，导致了从人\n类社会出现以来各种环境问题在地球上的积累、组合、集中暴发的复\n杂局面。\n(5 )社会化：由于当代环境问题已影响到社会的各个方面，\n影响到每个人的生存与发展。因此，当代环境问题已不是限于少数人\n、少数部门关心的问题，而成为全社会共同关心的问题。\n(6 )政治化：当代的环境问题已不再是单纯的技术问题，\n而成为国际、各国国内政治的重要问题。环境问题的政治化主要表\n现包括：①成为国际合作和交往的重要内容；②成为国际政治斗争\n的导火索之一，如各国在环境义务的承担、污染转嫁等问题上经常产\n生矛盾并引起激烈的政治斗争；③世界上出现一些以环境保护为宗\n旨的组织，如绿色和平组织等，这些组织在国际政治舞台上已占有一\n席之地，成为一股新的政治势力。\n学长提示 : 本书中大量出现类似于这种关于特点的综合性的说法 ， 而且篇幅都比较长\n， 我的建议就是混个眼部 ， 答得时候尽量都宏观一点","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。","含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":29,"sourceRange":{"startPage":29,"startY":466.82,"endPage":30,"endY":663.7},"sourceKind":"original","originalOrdinal":"5","sourceMetadata":["【重要程度： 】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":1,"excerpts":[{"page":29,"src":"./assets/environment/env838-83d6baf1175800c6-29.webp"},{"page":30,"src":"./assets/environment/env838-83d6baf1175800c6-30.webp"}]},{"id":"env838-23f35188593c9b9e","subject":"环境学导论","chapter":"第1章 绪论","originalChapter":"第1章 绪论","originalChapterNumber":1,"section":"第3节 环境学的任务","originalSection":"第3节 环境学的任务","category":"knowledge","title":"环境学研究的主要内容","question":"环境学研究的主要内容","type":"简答题","answer":"环境科学是一门研究人类社会发展活动与环境演化规律之间相\n互作用关系，寻求人类社会与环境协同演化、持续发展途径与方法的\n科学。\n①环境质量的基础理论：包括环境质量状况的综合评价，污染物\n质在环境中的迁移、转化、增大和消失的规律，环境自净能力的研究\n，环境被污染、破坏对生态的影响等；\n②环境质量的控制与防治：包括改革生产工艺，综合利用，尽量\n减少或不产生污染物质以及净化处理技术；合理利用和保护自然资源\n；环境区域规划和综合防治等；\n③环境监测分析技术和环境质量预报技术；\n④环境污染与人体健康的关系，特别是环境污染所引起的致癌、\n致畸和致突变的研究及防治。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2001,2019,2021],"needsReview":false,"reviewReasons":[],"verified":false,"page":30,"sourceRange":{"startPage":30,"startY":704.1,"endPage":31,"endY":443.04},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":["2001(环境科学名词解释、2019(环境科学名词解释,2019(简、2021 (简, 【重要程度"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":1,"excerpts":[{"page":30,"src":"./assets/environment/env838-23f35188593c9b9e-30.webp"},{"page":31,"src":"./assets/environment/env838-23f35188593c9b9e-31.webp"}]},{"id":"env838-3647c6f2fd886485","subject":"环境学导论","chapter":"第1章 绪论","originalChapter":"第1章 绪论","originalChapterNumber":1,"section":"第3节 环境学的任务","originalSection":"第3节 环境学的任务","category":"knowledge","title":"基本任务","question":"基本任务","type":"简答题","answer":"(1 )探索全球范围内自然环境演化的规律\n(2)探索全球范围内人与环境的相互依存关系\n(3 )协调人类的生产、消费活动同生态要求之间的关系\n(4)探索区域污染综合防治的途径","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":0,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":31,"sourceRange":{"startPage":31,"startY":443.04,"endPage":32,"endY":79.96},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":["【重要程度:☆☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":1,"excerpts":[{"page":31,"src":"./assets/environment/env838-3647c6f2fd886485-31.webp"},{"page":32,"src":"./assets/environment/env838-3647c6f2fd886485-32.webp"}]},{"id":"env838-1c4c963940e7ca5d","subject":"环境学导论","chapter":"第1章 绪论","originalChapter":"第1章 绪论","originalChapterNumber":1,"section":"第4节 课后习题","originalSection":"第4节 课后习题","category":"exercise","title":"什么是环境?环境具有哪些特点?","question":"什么是环境?环境具有哪些特点?","type":"简答题","answer":"整理答案（按教材对应知识点摘录）：\n\n环境的概念：\n环境学所研究的环境，是以人类为主体的外部世界，即人类赖以\n生存和发展的物质条件的综合体，包括自然环境和社会环境。\n①自然环境：直接或间接影响到人类的、一切自然形成的物质及\n其能量的总体。\n②人工环境：人类生存及活动范围内的社会物质、精神条件的总\n和。\n学长提示 : “环境 \"的范畴并非国定不变 ， 而是随着人类社会 、 科学技术的发展不断深\n化的 。 例如 ， 随着空间科学的发展 ， 现阶段不属于人类生邢环境的月球 ， 未来也有可\n能成为其组成部分 。\n\n环境的几个特点：\n①整体性：环境中的各种因素(物理的、化学的、生物的、社\n会的)不是孤立存在的，而是互相依存、互相影响、互相联系的。\n②综合性：环境的综合性表现在两个方面。一是任何一个环境\n问题的产生，都是环境系统内多因素综合作用的结果，其中既有自然\n因素如温度、湿度及风的作用，更有人为因素如污染物的排放等作用\n，而且这些因素之间相互影响、相互制约。二是为了解决某一环境问\n题.往往需要综合涉及各个领域的学科，在一个总体目标或方案的构\n架下，有针对性地将涉及的各学科问题逐一解决。\n③区域性：不同地区的环境呈现明显的地域差异，形成不同的\n地域单元，称为环境的区域性。这也是由于环境中物质和能量的地域\n分异规律而形成的。\n④有限性：自然环境中蕴藏着大量的物质与能量，但这些资源\n都是有限的。\n⑤稳定性：环境的稳定性是指在无外界因素影响的条件下，环\n境内部保持相对平衡的状态。环境的稳定性是一种动态平衡，因此它\n是一种状态的物质循环、能量传递、信息交换的权衡。\n⑥滞后性：自然环境受到外界影响后，其变化及影响往往是滞\n后的。环境受到破坏后，产生的后果很难及时反映出来，有些甚至是\n难以预测的；环境一旦破坏，所需要的恢复时间长，尤其是超过阈值\n后，很难恢复。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["根据所列知识点摘录整理，未逐题人工审定。"],"verified":false,"page":32,"sourceRange":{"startPage":32,"startY":116.92,"endPage":32,"endY":193.29},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":1,"references":[{"id":"env838-2e272b372586cb81","title":"环境的概念","source":"环境学导论.pdf","page":19},{"id":"env838-72fed20604f8615a","title":"环境的几个特点","source":"环境学导论.pdf","page":26}],"excerpts":[{"page":32,"src":"./assets/environment/env838-1c4c963940e7ca5d-32.webp"}]},{"id":"env838-b53132c021a7b16a","subject":"环境学导论","chapter":"第1章 绪论","originalChapter":"第1章 绪论","originalChapterNumber":1,"section":"第4节 课后习题","originalSection":"第4节 课后习题","category":"exercise","title":"简要解释与环境学相关名词的概念。","question":"简要解释与环境学相关名词的概念。","type":"简答题","answer":"①环境：以人类为主体，影响人类生存和发展的外部条件的总体，包括自然环境和社会环境。\n②环境要素：构成环境整体、性质不同且相互联系的基本组分，如水、大气、土壤和生物。\n③环境质量：环境整体或某些要素对人类生活、生产与生态系统的适宜程度。\n④环境容量：在规定环境目标和条件下，环境能够容纳的污染物最大负荷。\n⑤环境承载力：在维持环境结构、功能及资源持续利用的条件下，环境所能支持的人口和经济活动规模。\n⑥环境污染：有害物质或能量进入环境，超过环境可承受程度，造成环境质量下降及不利影响。\n⑦环境自净：环境通过物理、化学、生物作用降低污染物浓度或危害的过程。\n答题时应依题目范围补充“环境问题”“生态系统”等名词，不能把环境容量与人口承载力混为一谈。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":32,"sourceRange":{"startPage":32,"startY":193.29,"endPage":32,"endY":269.24},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":1,"excerpts":[{"page":32,"src":"./assets/environment/env838-b53132c021a7b16a-32.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=19"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-a24b8d62f5e2c3bd","subject":"环境学导论","chapter":"第1章 绪论","originalChapter":"第1章 绪论","originalChapterNumber":1,"section":"第4节 课后习题","originalSection":"第4节 课后习题","category":"exercise","title":"环境问题是如何产生的?当前人类所面临的主要环境问题有哪些?","question":"环境问题是如何产生的?当前人类所面临的主要环境问题有哪些?","type":"简答题","answer":"一、产生：自然演变及地震、洪涝等灾害可引起原生环境问题；人口增长、资源过度开发、粗放生产与消费、污染排放等引起次生环境问题。社会经济活动超过资源更新能力、环境容量及生态恢复能力，是问题加剧的重要机制。\n二、主要问题：气候变化、臭氧层破坏、酸沉降；水、大气和土壤污染；固体废物及危险化学品污染；森林减少、土地退化和荒漠化；生物多样性丧失；资源过度消耗及海洋污染等。\n三、认识：问题具有跨介质、跨区域和累积特征，应协调发展与保护，实行源头预防、全过程控制和生态修复。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":32,"sourceRange":{"startPage":32,"startY":269.24,"endPage":32,"endY":372.53},"sourceKind":"original","originalOrdinal":"3","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":1,"excerpts":[{"page":32,"src":"./assets/environment/env838-a24b8d62f5e2c3bd-32.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=19"},{"title":"生态环境部：2024中国生态环境状况公报","url":"https://www.mee.gov.cn/ywgz/sthjjcgl/hjzljcypj/202506/t20250605_1120773.shtml","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-f796c73811e0cdb3","subject":"环境学导论","chapter":"第1章 绪论","originalChapter":"第1章 绪论","originalChapterNumber":1,"section":"第4节 课后习题","originalSection":"第4节 课后习题","category":"exercise","title":"环境问题具有哪些特点?其实质是什么?","question":"环境问题具有哪些特点?其实质是什么?","type":"简答题","answer":"整理答案（按教材对应知识点摘录）：\n\n环境问题的六大特点：\n(1)全球化：近年来，一些环境污染具有跨国、跨地区的流\n动性的特点。一些国际河流，上游国家造成的污染，可能危及下游国\n家；一个国家大气污染造成的酸雨，可能会降到别国。\n(2)综合化：当代环境问题涉及人类生存环境的各个方面，\n包括森林锐减、草原退化、沙漠扩展、土壤侵蚀、物种减少、水源危\n机、气候异常、城市化问题等，已深入到人类生产、生活的各个方面\n(3)高技术化：随着当代科技的迅猛发展，由高新技术引\n发的环境问题日渐增多，如原子弹、导弹试验，核反应堆的使用及\n其事故，电磁波引起的环境问题，超音速飞机带来的臭氧层破坏、航\n天飞行的太空污染等。生物工程技术的潜在影响以及大型工程技术的\n开发利用都可能产生难以预测的生态灾难。这些环境问题技术含量\n高、影响范围广、控制难、后果严重，已引起世界各国的普遍关注。\n(4 )累积化：虽然人类已进入现代文明时期，进入后工业化\n、信息化时代，但历史上不同阶段所产生的环境问题，在当今地球上\n依然存在；同时，现代社会又滋生出一系列的环境问题，导致了从人\n类社会出现以来各种环境问题在地球上的积累、组合、集中暴发的复\n杂局面。\n(5 )社会化：由于当代环境问题已影响到社会的各个方面，\n影响到每个人的生存与发展。因此，当代环境问题已不是限于少数人\n、少数部门关心的问题，而成为全社会共同关心的问题。\n(6 )政治化：当代的环境问题已不再是单纯的技术问题，\n而成为国际、各国国内政治的重要问题。环境问题的政治化主要表\n现包括：①成为国际合作和交往的重要内容；②成为国际政治斗争\n的导火索之一，如各国在环境义务的承担、污染转嫁等问题上经常产\n生矛盾并引起激烈的政治斗争；③世界上出现一些以环境保护为宗\n旨的组织，如绿色和平组织等，这些组织在国际政治舞台上已占有一\n席之地，成为一股新的政治势力。\n学长提示 : 本书中大量出现类似于这种关于特点的综合性的说法 ， 而且篇幅都比较长\n， 我的建议就是混个眼部 ， 答得时候尽量都宏观一点\n\n环境问题的实质：\n环境问题就是一个经济问题和社会问题，是人类自然的而且是自\n觉的建设人类文明的问题。当代人类面临的所谓环境污染，以及自然\n资源的不合理开发利用造成的森林的破坏、水土流失的加剧和资源的\n枯竭，都是人类经济活动的直接或间接的结果，而且环境污染和破坏\n的治理和控制，又必须有相当的经济实力。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["根据所列知识点摘录整理，未逐题人工审定。"],"verified":false,"page":32,"sourceRange":{"startPage":32,"startY":372.53,"endPage":32,"endY":448.01},"sourceKind":"original","originalOrdinal":"4","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":1,"references":[{"id":"env838-83d6baf1175800c6","title":"环境问题的六大特点","source":"环境学导论.pdf","page":29},{"id":"env838-ad0415114ea3d772","title":"环境问题的实质","source":"环境学导论.pdf","page":29}],"excerpts":[{"page":32,"src":"./assets/environment/env838-f796c73811e0cdb3-32.webp"}]},{"id":"env838-d150a09529eb158a","subject":"环境学导论","chapter":"第1章 绪论","originalChapter":"第1章 绪论","originalChapterNumber":1,"section":"第4节 课后习题","originalSection":"第4节 课后习题","category":"exercise","title":"环境学研究的对象和任务是什么?","question":"环境学研究的对象和任务是什么?","type":"简答题","answer":"整理答案（按教材对应知识点摘录）：\n\n环境学研究的主要内容：\n环境科学是一门研究人类社会发展活动与环境演化规律之间相\n互作用关系，寻求人类社会与环境协同演化、持续发展途径与方法的\n科学。\n①环境质量的基础理论：包括环境质量状况的综合评价，污染物\n质在环境中的迁移、转化、增大和消失的规律，环境自净能力的研究\n，环境被污染、破坏对生态的影响等；\n②环境质量的控制与防治：包括改革生产工艺，综合利用，尽量\n减少或不产生污染物质以及净化处理技术；合理利用和保护自然资源\n；环境区域规划和综合防治等；\n③环境监测分析技术和环境质量预报技术；\n④环境污染与人体健康的关系，特别是环境污染所引起的致癌、\n致畸和致突变的研究及防治。\n\n基本任务：\n(1 )探索全球范围内自然环境演化的规律\n(2)探索全球范围内人与环境的相互依存关系\n(3 )协调人类的生产、消费活动同生态要求之间的关系\n(4)探索区域污染综合防治的途径","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["根据所列知识点摘录整理，未逐题人工审定。"],"verified":false,"page":32,"sourceRange":{"startPage":32,"startY":448.01,"endPage":32,"endY":523.9},"sourceKind":"original","originalOrdinal":"5","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":1,"references":[{"id":"env838-23f35188593c9b9e","title":"环境学研究的主要内容","source":"环境学导论.pdf","page":30},{"id":"env838-3647c6f2fd886485","title":"基本任务","source":"环境学导论.pdf","page":31}],"excerpts":[{"page":32,"src":"./assets/environment/env838-d150a09529eb158a-32.webp"}]},{"id":"env838-d5096ed47e50505c","subject":"环境学导论","chapter":"第1章 绪论","originalChapter":"第1章 绪论","originalChapterNumber":1,"section":"第4节 课后习题","originalSection":"第4节 课后习题","category":"exercise","title":"简述环境容量和环境承载力的联系与区别?","question":"简述环境容量和环境承载力的联系与区别?","type":"简答题","answer":"整理答案（按教材对应知识点摘录）：\n\n环境容量与环境承载力：\n环境容量，是在人类生存和自然生态系统不致受害的前提下某一\n环境所能容纳的污染物的最大负荷量，或一个生态系统在维持生命机\n体的再生能力、适应能力和更新能力的前提下承受有机体数量的最大\n限度。\n环境承载力，又称环境承受力或环境忍耐力，指在一定时期内，\n在维持相对稳定的前提下，环境资源所能容纳的人口规模和经济规模\n的大小。地球的面积和空间是有限的，资源也是有限的，显然它的承\n载力也是有限的。\n二者关系：环境容量强调的是环境系统对自然和人文系统排污的\n容纳能力，侧重体现和反映环境系统的自然属性，即内在的自然秉性\n和特质。环境承载力则强调在环境系统正常结构和功能的前提下，环\n境系统所能承受的人类社会经济活动的能力，侧重体现和反映环境系\n统的社会属性，即外在的社会秉性和特质。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["根据所列知识点摘录整理，未逐题人工审定。"],"verified":false,"page":32,"sourceRange":{"startPage":32,"startY":523.9,"endPage":33,"endY":84.4},"sourceKind":"original","originalOrdinal":"6","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":1,"references":[{"id":"env838-7a3f62f56a33fe33","title":"环境容量与环境承载力","source":"环境学导论.pdf","page":21}],"excerpts":[{"page":32,"src":"./assets/environment/env838-d5096ed47e50505c-32.webp"},{"page":33,"src":"./assets/environment/env838-d5096ed47e50505c-33.webp"}]},{"id":"env838-9ad1e210b13ac063","subject":"环境学导论","chapter":"第2章 全球环境问题","originalChapter":"第2章 全球环境问题","originalChapterNumber":2,"section":"第1节 全球环境问题","originalSection":"第1节 全球环境问题","category":"knowledge","title":"温室效应的概念","question":"温室效应的概念","type":"简答题","answer":"温室效应又称花房效应，是大气保温效应的俗称，大气能使太阳\n的短波辐射到达地面，使地面温度升高，但地面向外释放出的长波辐\n射却被大气吸收。由于大气吸收热量多，散失少，这样就使得地表和\n低层大气温度升高，其作用类似于栽培农作物的温室，故称为温室效\n应。\n图 2-1 温室效应示意图","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2000,2002,2003,2012],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。","含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":34,"sourceRange":{"startPage":34,"startY":152.79,"endPage":34,"endY":543.63},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":["2000 (名、2002(名、2003(名、2012(名,【重要程度:"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":2,"excerpts":[{"page":34,"src":"./assets/environment/env838-9ad1e210b13ac063-34.webp"}]},{"id":"env838-6360dda5dadc5764","subject":"环境学导论","chapter":"第2章 全球环境问题","originalChapter":"第2章 全球环境问题","originalChapterNumber":2,"section":"第1节 全球环境问题","originalSection":"第1节 全球环境问题","category":"knowledge","title":"温室气体","question":"温室气体","type":"简答题","answer":"温室气体，即大气中的一些微量气体，这些气体可以让太阳短波\n辐射自由通过，同时吸收地面发出的长波辐射，当他们在大气中的浓\n度增加时，就会加剧温室效应，引起地球表面和大气层下沿的温度升\n高。主要包括 、 、 、氟利昂、 ，其中 是最主要的温\n室气体。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2007,2009,2011,2020],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":34,"sourceRange":{"startPage":34,"startY":543.63,"endPage":35,"endY":63.68},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":["2007(论、2009(名--氟利昂、2011(判、2011 (名-大气窗、2020(填--含H的CFs的优点",", 【重要程度："],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":2,"excerpts":[{"page":34,"src":"./assets/environment/env838-6360dda5dadc5764-34.webp"},{"page":35,"src":"./assets/environment/env838-6360dda5dadc5764-35.webp"}]},{"id":"env838-2284b804f54ac87a","subject":"环境学导论","chapter":"第2章 全球环境问题","originalChapter":"第2章 全球环境问题","originalChapterNumber":2,"section":"第1节 全球环境问题","originalSection":"第1节 全球环境问题","category":"knowledge","title":"全球变暖","question":"全球变暖","type":"简答题","answer":"指全球的气候变化以及这种变化对自然和人类生存环境的影响。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2022],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":35,"sourceRange":{"startPage":35,"startY":63.68,"endPage":35,"endY":180.98},"sourceKind":"original","originalOrdinal":"3","sourceMetadata":["2022(名,【重要程度:"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":2,"excerpts":[{"page":35,"src":"./assets/environment/env838-2284b804f54ac87a-35.webp"}]},{"id":"env838-4ad99f204b945005","subject":"环境学导论","chapter":"第2章 全球环境问题","originalChapter":"第2章 全球环境问题","originalChapterNumber":2,"section":"第1节 全球环境问题","originalSection":"第1节 全球环境问题","category":"knowledge","title":"全球变暖的危害","question":"全球变暖的危害","type":"简答题","answer":"①沿海地区的海岸线变化。随着温室效应的增强，气温升高，海\n水温度也随之升高，海水将会由于升温而膨胀，促使海水平面升高。\n海水平面上升主要使沿海地区受到威胁，沿海低地有被淹的危险。另\n外还会引起海水倒灌、洪水排泄不畅、土地盐渍化等后果。航运、水\n产养殖业也会受到影响。\n②气候带移动。气候带移动包括温度带的移动和降水带的移动。\n全球变暖会引起温度带北移，温度带的移动会使大气运动发生相应的\n变化，全球降水也将改变。气候带的移动会引起一系列的环境变化，\n影响人类生产生活。\n③气候变暖对中国的影响。气候变暖使中国农业生产的不稳定性\n增大，海水平面上升使中国沿海经济发展受到威胁，同时气候变暖会\n对中国生物的多样化产生影响。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2004,2007,2016,2018],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":35,"sourceRange":{"startPage":35,"startY":180.98,"endPage":35,"endY":629.01},"sourceKind":"original","originalOrdinal":"4","sourceMetadata":["2004(论、2007(论、2016(论、2018(论,【重要程度:"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":2,"excerpts":[{"page":35,"src":"./assets/environment/env838-4ad99f204b945005-35.webp"}]},{"id":"env838-b60191ccfb28a2db","subject":"环境学导论","chapter":"第2章 全球环境问题","originalChapter":"第2章 全球环境问题","originalChapterNumber":2,"section":"第1节 全球环境问题","originalSection":"第1节 全球环境问题","category":"knowledge","title":"臭氧层","question":"臭氧层","type":"简答题","answer":"大气平流层中 浓度相对较高的部分，主要作用是吸收短波紫外\n线。自然界中的臭氧层大多分布在离地20~50km的高空。\n图 2-2 REETEA","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。","含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":35,"sourceRange":{"startPage":35,"startY":629.01,"endPage":36,"endY":337.85},"sourceKind":"original","originalOrdinal":"5","sourceMetadata":["【重要程度："],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":2,"excerpts":[{"page":35,"src":"./assets/environment/env838-b60191ccfb28a2db-35.webp"},{"page":36,"src":"./assets/environment/env838-b60191ccfb28a2db-36.webp"}]},{"id":"env838-a9fe8707f0e1f235","subject":"环境学导论","chapter":"第2章 全球环境问题","originalChapter":"第2章 全球环境问题","originalChapterNumber":2,"section":"第1节 全球环境问题","originalSection":"第1节 全球环境问题","category":"knowledge","title":"臭氧层的作用","question":"臭氧层的作用","type":"简答题","answer":"1.保护作困：臭氧层能够吸收波长小于306.3nm的紫外线(UV\n) , 主要是一部分中波紫外线(UV-B, 波长290~300  nm) 和全部\n的短波紫外线(UV-C，波长<290nm )，保护人类和动植物免遭短波\n紫外线的伤害。经过臭氧层后，只有长波紫外线(UV-A)和少量的\nUV-B能够辐射到地面，UV-A对生物细胞的伤害要比UV-B轻微得多\n2.加热作用： 吸收太阳光中的UV并将其转换为热能，从而加热\n大气。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":36,"sourceRange":{"startPage":36,"startY":337.85,"endPage":36,"endY":647.77},"sourceKind":"original","originalOrdinal":"6","sourceMetadata":["【重要程度："],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":2,"excerpts":[{"page":36,"src":"./assets/environment/env838-a9fe8707f0e1f235-36.webp"}]},{"id":"env838-51ca0c4074a3aaf1","subject":"环境学导论","chapter":"第2章 全球环境问题","originalChapter":"第2章 全球环境问题","originalChapterNumber":2,"section":"第1节 全球环境问题","originalSection":"第1节 全球环境问题","category":"knowledge","title":"臭氧层破坏的原因","question":"臭氧层破坏的原因","type":"简答题","answer":"当氟氯碳化物飘浮在空气中时，因受到紫外线的影响而分解释\n出氯原子。氯原子的活性极大，易与其他物质结合。氯原子遇到 时\n，便开始产生化学变化。 被分解成一个氧原子和一个 分子，氯原\n子就与氧原子相结合。当其他氧原子遇到氯氧化合分子，就又把氧\n原子抢回来，组成一个 分子，而恢复成单身的氯原子又可破坏其他\n臭氧。\nAT CFCs 光解产生的 C1 ,CIO\n[待核对] 及 NIONONO? 分解 0 产生 O:\n[待核对] 7% On SRE DO 候化剂破坏\n[待核对] 流 \\O 级世转移吸收 UV S894\n[待核对] 层 {240-2500m\n| 290~320nm《 部分 )\n[待核对] YorawocnnKe ~~ «paces\n[待核对] i 缓慢迁移\n[待核对] | | 人\n[待核对] CO, 8\n[待核对] CFCs,CO, matt HAE CFCs 排放\n[待核对] 二自然前站 ah (汽车尾气 ) (工业与生活\n(生物作用 ) 成用过程 )\n图 2-3 臭氧层破坏的原因","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2004,2010],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。","含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":36,"sourceRange":{"startPage":36,"startY":647.77,"endPage":37,"endY":481.4},"sourceKind":"original","originalOrdinal":"7","sourceMetadata":["2004(选、2010 (选, 【重要程度:"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":2,"excerpts":[{"page":36,"src":"./assets/environment/env838-51ca0c4074a3aaf1-36.webp"},{"page":37,"src":"./assets/environment/env838-51ca0c4074a3aaf1-37.webp"}]},{"id":"env838-fa5bc3f3018ce8ed","subject":"环境学导论","chapter":"第2章 全球环境问题","originalChapter":"第2章 全球环境问题","originalChapterNumber":2,"section":"第1节 全球环境问题","originalSection":"第1节 全球环境问题","category":"knowledge","title":"臭氧层破坏的影响","question":"臭氧层破坏的影响","type":"简答题","answer":"(1) 对健康的影响\nUV-B的增加对人类健康有严重的危害作用，潜在危险包括引发\n和加剧眼部疾病、皮肤癌和传染性疾病。\n(2) 对植物的影响\n在已研究过的植物品种中，超过50%的植物出现UV-B的负影响，\n如豆类、瓜类等作物；植物的生理和进化过程受UV-B辐射的影响。对\n森林和草地，臭氧层损耗可能会改变物种的组成，进而影响不同生态\n系统的生物多样性分布。\n(3) 对生态的影响\n世界上30%以上的动物蛋白质来自海洋。浮游植物暴露于UV-B\n下时，定向分布和移动会受到影响，生物的存活率降低。浮游植物生\n产力下降与 减少造成的UV-B辐射增加直接有关。\nUV-B辐射对鱼、虾、蟹、两栖动物和其他动物的早期发育阶段都\n有危害作用，最严重的影响是繁殖力下降和幼体发育不全。\n(4 )对循环的影响\n对陆生生态系统，UV增加会改变植物的生成和分解，进而改变\n大气中重要气体的吸收和释放。\n对水生生态系统，UV-B会影响水生生态系统中的碳循环、氮循\n环和硫循环。此外，紫外辐射还会抑制海洋表层浮游细菌的生长，从\n而对海洋生物地球化学循环产生重要的潜在影响。\n(5 )对材料的影响\n因平流层 损耗导致阳光紫外辐射的增加会加速建筑、喷涂、包\n装及电线电缆等所用材料尤其是高分子材料的降解和老化变质。短波\nUV-B辐射对材料的变色和机械完整性的损失有直接影响，特别是在\n高温和阳光充足的热带地区，这种破坏作用更为严重，造成的损失全\n球每年达数十亿美元。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":1,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":37,"sourceRange":{"startPage":37,"startY":481.4,"endPage":38,"endY":589.04},"sourceKind":"original","originalOrdinal":"8","sourceMetadata":["【重要程度: ★☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":2,"excerpts":[{"page":37,"src":"./assets/environment/env838-fa5bc3f3018ce8ed-37.webp"},{"page":38,"src":"./assets/environment/env838-fa5bc3f3018ce8ed-38.webp"}]},{"id":"env838-1302b4f8e5af8cf4","subject":"环境学导论","chapter":"第2章 全球环境问题","originalChapter":"第2章 全球环境问题","originalChapterNumber":2,"section":"第1节 全球环境问题","originalSection":"第1节 全球环境问题","category":"knowledge","title":"酸雨的概念","question":"酸雨的概念","type":"简答题","answer":"正式名称为酸沉降，指pH值小于5.6的雨雪或其他形式的降水\n，可分为湿沉降与干沉降。湿沉降指所有气状污染物或粒状污染物随\n着雨、雪、雾或雹等降水型态而落到地面；干沉降指在不下雨雪等的\n时间以降尘形式而落到地面。\n小贴士 :“ 酸雨 \"之所以得名 ， 是因为工业革命后大量燃烧煤迪排放的二氧化硫\n和氮气化物在高空中被雨雪冲刷溶解 ， 导致降水本身带有酸性 ; 1872 年 ， 英国\n科学家史密斯通过分析证实了伦敦市区雨水中含有硫酸等酸性物质后 , 首次在\n其著作 《空气和降雨 ; 化学气候学的开端 》 中正式提出了 “酸雨 ?这一专有名词\n来描述该现象 。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2007,2012,2016,2020],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。","含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":38,"sourceRange":{"startPage":38,"startY":589.04,"endPage":39,"endY":221.29},"sourceKind":"original","originalOrdinal":"9","sourceMetadata":["2016(名、2012 (名、2007(名、2020(名,【重要程度:"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":2,"excerpts":[{"page":38,"src":"./assets/environment/env838-1302b4f8e5af8cf4-38.webp"},{"page":39,"src":"./assets/environment/env838-1302b4f8e5af8cf4-39.webp"}]},{"id":"env838-59dc6ec470d99810","subject":"环境学导论","chapter":"第2章 全球环境问题","originalChapter":"第2章 全球环境问题","originalChapterNumber":2,"section":"第1节 全球环境问题","originalSection":"第1节 全球环境问题","category":"knowledge","title":"酸雨的类型","question":"酸雨的类型","type":"简答题","answer":"根据 和 离子的浓度比值可将酸雨分为3类，分别为硫\n酸型或燃煤型 ( >3)、混合型( ) 和硝酸\n型或燃油型 ≤0.5)。燃煤多的地区，酸雨属硫酸型酸雨，\n燃石油多的地区常下硝酸型酸雨。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":39,"sourceRange":{"startPage":39,"startY":221.29,"endPage":39,"endY":423.17},"sourceKind":"original","originalOrdinal":"10","sourceMetadata":["【重要程度："],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":2,"excerpts":[{"page":39,"src":"./assets/environment/env838-59dc6ec470d99810-39.webp"}]},{"id":"env838-aac53a87a3cdc4e2","subject":"环境学导论","chapter":"第2章 全球环境问题","originalChapter":"第2章 全球环境问题","originalChapterNumber":2,"section":"第1节 全球环境问题","originalSection":"第1节 全球环境问题","category":"knowledge","title":"酸雨的危害","question":"酸雨的危害","type":"简答题","answer":"土壤酸化：酸雨会加速酸性土壤酸化，虽碱性土壤有缓冲和稀释\n能力，但酸雨仍会使土壤矿物质营养元素流失、改变土壤结构，导致\n土壤贫瘠化，影响植物发育、诱发病虫害，造成农作物减产。此外，\n酸雨会使土壤中活性铝增加，抑制林木生长，还会抑制某些土壤微生\n物繁殖、降低酶活性。\n植被损害：降水pH值小于3.0时，会直接损害植物叶片；pH值小\n于4.5的地区，马尾松、华山松和冷杉等林木出现大量黄叶并脱落。中\n国长江以南省份森林受酸雨危害严重，如四川盆地、贵州等地，酸雨\n还造成西南地区森林生产力下降，损失大量木材。森林生态价值远超\n经济价值。\n建材腐蚀：酸雨会使非金属建筑材料表面硬化、水泥溶解，出现\n空洞和裂缝，还会与建筑物表面的 反应生成可溶于水的\n被雨水冲刷掉，酸雨会腐蚀文物古迹，也会加快金属建筑的防腐处理\n频率。\n健康危害：酸雨会使水源酸化、导致金属溶出，危害饮用者健康\n。酸雨还会使儿童免疫功能下降、呼吸道疾病发病率增加，老人眼部\n和呼吸道患病率增加","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2004,2007,2012,2015],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":39,"sourceRange":{"startPage":39,"startY":423.17,"endPage":40,"endY":293.03},"sourceKind":"original","originalOrdinal":"11","sourceMetadata":["2004(简、2007(简、2012 (简、2015(简,【重要程度:"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":2,"excerpts":[{"page":39,"src":"./assets/environment/env838-aac53a87a3cdc4e2-39.webp"},{"page":40,"src":"./assets/environment/env838-aac53a87a3cdc4e2-40.webp"}]},{"id":"env838-5da7aeb0f07c2a8b","subject":"环境学导论","chapter":"第2章 全球环境问题","originalChapter":"第2章 全球环境问题","originalChapterNumber":2,"section":"第1节 全球环境问题","originalSection":"第1节 全球环境问题","category":"knowledge","title":"海洋污染的概念","question":"海洋污染的概念","type":"简答题","answer":"海洋污染通常是指人类改变海洋原来的状态，使海洋生态系统\n遭到破坏。海洋污染会损害生物资源，危害人类健康，.妨碍人类的海\n上活动，损坏海水质量和环境质量等。\n学长提示 : 本书中所有有关 xX 污染的定义都是有选可循的 ， 一般的解释套路为 :\n人类活动一改变了原本的平衡状态 /排出的污染物浓度超过了本底值一进而引发的一\n系列危害人体健康 、 环境健康 、 生物健康的风险 ， 称之为 Xx 污染 。 注意一定要沾到庆\n害人类健康的边 。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2013,2019],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。","含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":40,"sourceRange":{"startPage":40,"startY":293.03,"endPage":40,"endY":548.8},"sourceKind":"original","originalOrdinal":"12","sourceMetadata":["2013(简、2019(名,【重要程度:"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":2,"excerpts":[{"page":40,"src":"./assets/environment/env838-5da7aeb0f07c2a8b-40.webp"}]},{"id":"env838-aa2da8afdec7b339","subject":"环境学导论","chapter":"第2章 全球环境问题","originalChapter":"第2章 全球环境问题","originalChapterNumber":2,"section":"第1节 全球环境问题","originalSection":"第1节 全球环境问题","category":"knowledge","title":"海洋污染的类型","question":"海洋污染的类型","type":"简答题","answer":"①石油污染，包括原油和从原油中分馏出来的溶剂油、汽油、煤\n油、柴油、润滑油、石蜡、沥青等，以及经过裂化、催化而成的各种\n产品；\n②重金属和酸碱污染, 包括 Hg、Cu、Zn、Co、Zr、Cr等重金属\n，As、S、P等非金属及各种酸和碱；\n③农药污染，包括有农业上大量使用含有 Hg、Cu以及有机氯等\n成分的除草剂、灭虫剂，以及工业上应用的多氯酸苯等；\n④有机物质和营养盐类污染，包括工业排出的纤维素、糖醛、油\n脂、粪便、洗涤剂和食物残渣，以及化肥的残液等；\n⑤放射性核素，是由核武器试验、核工业和核动力设施释放出来\n的人工放射性物质，主要是 Sr-90、Cs-137等半衰期为30年左右的同位\n素；\n⑥固体废物，主要是工业和城市垃圾、船舶废弃物、工程渣土和\n疏浚物等；\n⑦工业废热，造成海洋的热污染，在局部海域，如比正常水温高\n以上的热废水常年流入时，就会产生热污染；\n⑧赤潮，是在特定的环境条件下，海水中某些浮游植物、原生动\n物或细菌爆发性增殖或高度聚集而引起水体变色的一种有害生态现\n象；\n⑨海洋倾倒，通过船舶、平台或其他载运工具向海洋处置废弃物\n或其他有害物质的行为。\n[待核对] QREMAMMER ey\n[待核对] A SN\n海洋污染","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2013],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。","含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":40,"sourceRange":{"startPage":40,"startY":548.8,"endPage":42,"endY":79.93},"sourceKind":"original","originalOrdinal":"13","sourceMetadata":["2013(简,【重要程度:"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":2,"excerpts":[{"page":40,"src":"./assets/environment/env838-aa2da8afdec7b339-40.webp"},{"page":41,"src":"./assets/environment/env838-aa2da8afdec7b339-41.webp"},{"page":42,"src":"./assets/environment/env838-aa2da8afdec7b339-42.webp"}]},{"id":"env838-f3ab900f58d34957","subject":"环境学导论","chapter":"第2章 全球环境问题","originalChapter":"第2章 全球环境问题","originalChapterNumber":2,"section":"第1节 全球环境问题","originalSection":"第1节 全球环境问题","category":"knowledge","title":"森林锐减","question":"森林锐减","type":"简答题","answer":"森林锐减有两个原因，一是人类对森林的过度采伐，导致森\n林资源在迅速减少。另一个原因是毁林开荒。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":0,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":42,"sourceRange":{"startPage":42,"startY":79.93,"endPage":42,"endY":213.41},"sourceKind":"original","originalOrdinal":"14","sourceMetadata":["【重要程度: ☆☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":2,"excerpts":[{"page":42,"src":"./assets/environment/env838-f3ab900f58d34957-42.webp"}]},{"id":"env838-2b1147f0051ec5be","subject":"环境学导论","chapter":"第2章 全球环境问题","originalChapter":"第2章 全球环境问题","originalChapterNumber":2,"section":"第1节 全球环境问题","originalSection":"第1节 全球环境问题","category":"knowledge","title":"荒漠化","question":"荒漠化","type":"简答题","answer":"指包括气候变异和人类活动在内的种种因素造成的干旱、半干旱\n和亚湿润干旱地区的土地退化。\n狭义的荒漠化(即沙漠化)是指在脆弱的生态系统下，由于人为\n过度的经济活动，破坏其平衡，使非沙漠地区出现类似沙漠景观的环\n境变化过程。广义荒漠化则是指由于人为和自然因素的综合作用，使\n得干旱、半干旱甚至半湿润地区自然环境退化的总过程。\n学长提示 : 这里的说法和上面的提示就吻合了 ， 但凡是污染 ， 一定是有人类的干预 ，\n没有人类干预的地方都是保持着平衡状态的 。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。","含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":42,"sourceRange":{"startPage":42,"startY":213.41,"endPage":42,"endY":502.6},"sourceKind":"original","originalOrdinal":"15","sourceMetadata":["【重要程度："],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":2,"excerpts":[{"page":42,"src":"./assets/environment/env838-2b1147f0051ec5be-42.webp"}]},{"id":"env838-d718cd8763099eb9","subject":"环境学导论","chapter":"第2章 全球环境问题","originalChapter":"第2章 全球环境问题","originalChapterNumber":2,"section":"第1节 全球环境问题","originalSection":"第1节 全球环境问题","category":"knowledge","title":"物种灭绝","question":"物种灭绝","type":"简答题","answer":"物种灭绝泛指植物或动物的种类不可再生性地消失或破坏。物种\n灭绝一直是生命进程中的一部分。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":42,"sourceRange":{"startPage":42,"startY":502.6,"endPage":42,"endY":639.06},"sourceKind":"original","originalOrdinal":"16","sourceMetadata":["【重要程度："],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":2,"excerpts":[{"page":42,"src":"./assets/environment/env838-d718cd8763099eb9-42.webp"}]},{"id":"env838-8090a1831d837c12","subject":"环境学导论","chapter":"第2章 全球环境问题","originalChapter":"第2章 全球环境问题","originalChapterNumber":2,"section":"第1节 全球环境问题","originalSection":"第1节 全球环境问题","category":"knowledge","title":"生物多样性的概念","question":"生物多样性的概念","type":"简答题","answer":"生物多样性是指在一定时间和一定地区所有生物物种及其遗传\n变异和生态系统的复杂性的总称。它包括基因多样性、物种多样性和\n生态系统多样性三个层次。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2006],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":42,"sourceRange":{"startPage":42,"startY":639.06,"endPage":43,"endY":76.51},"sourceKind":"original","originalOrdinal":"17","sourceMetadata":["2006( 名, 【重要程度:"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":2,"excerpts":[{"page":42,"src":"./assets/environment/env838-8090a1831d837c12-42.webp"},{"page":43,"src":"./assets/environment/env838-8090a1831d837c12-43.webp"}]},{"id":"env838-1589a89f93b2fd34","subject":"环境学导论","chapter":"第2章 全球环境问题","originalChapter":"第2章 全球环境问题","originalChapterNumber":2,"section":"第1节 全球环境问题","originalSection":"第1节 全球环境问题","category":"knowledge","title":"土壤侵蚀的相关概念","question":"土壤侵蚀的相关概念","type":"简答题","answer":"水土流失：在水力作用下，土壤表层及其母质被剥蚀、冲刷搬运\n而流失的过程。\n土壤侵蚀：土壤及其母质在水力、风力、冻融或重力等外营力作\n用下，被破坏、剥蚀、搬运和沉积的过程。\n土壤侵蚀量：土壤在外营力作用下产生位移的物质量。\n土壤侵蚀模数：衡量土壤侵蚀的数量指标，指每年每平方千米土\n壤流失量。\n土壤侵蚀速度(速率)：单位面积单位时间内的侵蚀量。\n土壤流失量：土壤侵蚀量中被输移出特定地段的泥沙量。\n流域产沙量：在特定时段内，通过小流域出口某一观测断面的泥\n沙总量。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":0,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":43,"sourceRange":{"startPage":43,"startY":76.51,"endPage":43,"endY":505.34},"sourceKind":"original","originalOrdinal":"18","sourceMetadata":["【重要程度:☆☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":2,"excerpts":[{"page":43,"src":"./assets/environment/env838-1589a89f93b2fd34-43.webp"}]},{"id":"env838-ee6721a86a802379","subject":"环境学导论","chapter":"第2章 全球环境问题","originalChapter":"第2章 全球环境问题","originalChapterNumber":2,"section":"第1节 全球环境问题","originalSection":"第1节 全球环境问题","category":"knowledge","title":"影响土壤侵蚀的因素","question":"影响土壤侵蚀的因素","type":"简答题","answer":"1.自然因素\n季风气候与土壤侵蚀密切相关，其降雨量大而集中、多暴雨，加\n剧土壤侵蚀，其中降水影响最直接，暴雨强度越大，水土流失量越多\n。地形是影响水土流失的重要因素，坡度、坡长、坡形等都有影响，\n坡度影响最大，它是决定径流冲刷能力的主要因素。植被破坏使土壤\n失去天然保护屏障，是加速土壤侵蚀的先导因子。\n2.人为因素\n人为活动是造成土壤流失的主要原因，表现为植被破坏(滥垦、\n滥伐、滥牧)、坡耕地垦植(陡坡开荒、顺坡耕作、过度放牧)，以\n及开矿、修路未采取必要预防措施等，都会加剧水土流失","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":1,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":43,"sourceRange":{"startPage":43,"startY":505.34,"endPage":44,"endY":183.42},"sourceKind":"original","originalOrdinal":"19","sourceMetadata":["【重要程度:★☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":2,"excerpts":[{"page":43,"src":"./assets/environment/env838-ee6721a86a802379-43.webp"},{"page":44,"src":"./assets/environment/env838-ee6721a86a802379-44.webp"}]},{"id":"env838-6577c14b7e887466","subject":"环境学导论","chapter":"第2章 全球环境问题","originalChapter":"第2章 全球环境问题","originalChapterNumber":2,"section":"第2节 中国的主要环境问题","originalSection":"第2节 中国的主要环境问题","category":"knowledge","title":"中国主要环境问题的种类","question":"中国主要环境问题的种类","type":"简答题","answer":"水污染、大气污染、土壤污染、固体废物污染、土地荒漠化、石\n质荒漠化、食品污染、生物多样性减少","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":44,"sourceRange":{"startPage":44,"startY":224.6,"endPage":44,"endY":364.53},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":["【重要程度： 】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":2,"excerpts":[{"page":44,"src":"./assets/environment/env838-6577c14b7e887466-44.webp"}]},{"id":"env838-993df37d3f43ec1f","subject":"环境学导论","chapter":"第2章 全球环境问题","originalChapter":"第2章 全球环境问题","originalChapterNumber":2,"section":"第2节 中国的主要环境问题","originalSection":"第2节 中国的主要环境问题","category":"knowledge","title":"煤烟及粉煤灰的概念","question":"煤烟及粉煤灰的概念","type":"简答题","answer":"煤烟型污染是指由煤炭燃烧排放出的烟尘、 等一次污染物以\n及由这些污染物发生化学反应而生成二次污染物所构成的污染。从\n燃煤烟气中收集下来的细灰称为粉煤灰(也称飞灰)，是燃煤电厂排\n出的主要固体废物。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":0,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":44,"sourceRange":{"startPage":44,"startY":364.53,"endPage":44,"endY":561.63},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":["【重要程度:☆☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":2,"excerpts":[{"page":44,"src":"./assets/environment/env838-993df37d3f43ec1f-44.webp"}]},{"id":"env838-a52bab462ac7c1c0","subject":"环境学导论","chapter":"第2章 全球环境问题","originalChapter":"第2章 全球环境问题","originalChapterNumber":2,"section":"第2节 中国的主要环境问题","originalSection":"第2节 中国的主要环境问题","category":"knowledge","title":"雾霾的概念","question":"雾霾的概念","type":"简答题","answer":"雾霾是指空气中因悬浮着大量微粒而形成的大气混浊现象。\n霾，是空气中的灰尘、硫酸、硝酸、有机碳氢化合物等粒子使大气\n混浊，视野模糊并导致能见度恶化。如果水平能见度小于10km时，这\n种非水成物组成的气溶胶系统造成的视程障碍称为霾或灰霾。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2026],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":44,"sourceRange":{"startPage":44,"startY":561.63,"endPage":45,"endY":78.47},"sourceKind":"original","originalOrdinal":"3","sourceMetadata":["2026(名—雾霾,【重要程度:"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":2,"excerpts":[{"page":44,"src":"./assets/environment/env838-a52bab462ac7c1c0-44.webp"},{"page":45,"src":"./assets/environment/env838-a52bab462ac7c1c0-45.webp"}]},{"id":"env838-d30f36098e914e51","subject":"环境学导论","chapter":"第2章 全球环境问题","originalChapter":"第2章 全球环境问题","originalChapterNumber":2,"section":"第2节 中国的主要环境问题","originalSection":"第2节 中国的主要环境问题","category":"knowledge","title":"土壤污染的类型","question":"土壤污染的类型","type":"简答题","answer":"(1 )土壤盐渍化\n土壤盐渍化是指土壤底层或地下水的盐分随毛细管水上升到地\n表，水分蒸发后，使盐分积累在表层土壤中的过程。\n土壤次生盐渍化的形成很大程度上给地下水带来诸多影响。由于\n地下水超采使地下水位持续下降，沿渤海、黄海的沙质和基岩裂隙海\n岸地带，发生海水入侵，在有咸水分布的地区出现咸水边界向淡水区\n移动。\n(2) 土壤板结\n土壤团粒结构是土壤肥力的重要指标，土壤团粒结构的破坏会导\n致土壤的保水、保肥能力及通透性降低，造成土壤板结。\n向土壤中过量施入氮肥后，微生物的氮素供应增加1份，消耗的\n碳素相应增加25份。碳素来源于土壤有机质，有机质含量低，会影响\n微生物的活性，从而影响土壤团粒结构的形成。\n向土壤中过量施入磷肥时，磷酸根离子与钙、镁等阳离子结合形\n成难溶性磷酸盐，这样既浪费磷肥，又破坏土壤团粒结构。\n向土壤中过量施入钾肥时，钾离子置换性特别强，能将形成土壤\n团粒结构的多价阳离子置换出来，而钾离子不具有键桥作用，土壤团\n粒结构的键桥被破坏，也就破坏了团粒结构。\n(3 )黑土地减少\n黑土地是一种性状好、肥力高、非常适合植物生长的土壤。以弯\n月状分布于黑龙江、吉林两省的黑土带，是中国最肥沃的土地。东北\n黑土区在近百年的开发垦殖过程中，水土流失正使肥沃的东北黑土地\n变得又“薄”又“黄”。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":2,"pastExamYears":[2023],"needsReview":false,"reviewReasons":[],"verified":false,"page":45,"sourceRange":{"startPage":45,"startY":78.47,"endPage":46,"endY":77.41},"sourceKind":"original","originalOrdinal":"4","sourceMetadata":["2023 (简--类型, 【重要程度:★★☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":2,"excerpts":[{"page":45,"src":"./assets/environment/env838-d30f36098e914e51-45.webp"},{"page":46,"src":"./assets/environment/env838-d30f36098e914e51-46.webp"}]},{"id":"env838-003f77bd8f20290b","subject":"环境学导论","chapter":"第2章 全球环境问题","originalChapter":"第2章 全球环境问题","originalChapterNumber":2,"section":"第2节 中国的主要环境问题","originalSection":"第2节 中国的主要环境问题","category":"knowledge","title":"固体废物的分类、来源","question":"固体废物的分类、来源","type":"简答题","answer":"固体废物按来源可分为生活垃圾、一般工业固体废物和危险废\n物三种。此外，还有农业固体废物、建筑废料及弃土。\n固体废物的来源主要包括生活垃圾、工业固体废物和危险废物。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2015,2020],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":46,"sourceRange":{"startPage":46,"startY":77.41,"endPage":46,"endY":238.95},"sourceKind":"original","originalOrdinal":"5","sourceMetadata":["2015 (简, 2020 (论, 【重要程度:"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":2,"excerpts":[{"page":46,"src":"./assets/environment/env838-003f77bd8f20290b-46.webp"}]},{"id":"env838-83dc5199f93c1601","subject":"环境学导论","chapter":"第2章 全球环境问题","originalChapter":"第2章 全球环境问题","originalChapterNumber":2,"section":"第2节 中国的主要环境问题","originalSection":"第2节 中国的主要环境问题","category":"knowledge","title":"固体废物的两重性/特点","question":"固体废物的两重性/特点","type":"简答题","answer":"固体废物具有两重性，在一定时间、地点，某些物品对用户不再\n有用或暂不需要而被丢弃，成为废物，但对另一些用户或者在某种特\n定条件下，废物可能成为有用的甚至是必要的原料。\n学长提示 : 固废的特点 ， 以下可作为拓展补充\n[待核对] OBA Kite Fo RT AR\n@ 长期潜在的危害性 : 在自然条件的影响下 ， 固体废物中的一些有害成分会进入大气\n、 水体和土壤中参与生态形态的物质循环\n加全过程管理 : 固体废物的上述两个特点 ， 决定了从其产生到运输 、 储存 、 处置及处\n理的每个环节都要妥善控制 ， 使其不危害生态环境","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2022],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。","含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":46,"sourceRange":{"startPage":46,"startY":238.95,"endPage":46,"endY":534.57},"sourceKind":"original","originalOrdinal":"6","sourceMetadata":["2022 (简, 【重要程度:"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":2,"excerpts":[{"page":46,"src":"./assets/environment/env838-83dc5199f93c1601-46.webp"}]},{"id":"env838-11ddd4c042a0fab0","subject":"环境学导论","chapter":"第2章 全球环境问题","originalChapter":"第2章 全球环境问题","originalChapterNumber":2,"section":"第2节 中国的主要环境问题","originalSection":"第2节 中国的主要环境问题","category":"knowledge","title":"危险废物的定义","question":"危险废物的定义","type":"简答题","answer":"危险废物是指列入国家危险废物名录或者根据国家规定的危险\n废物鉴别标准和鉴别方法认定的具有危险特性的废物，即指具有毒性\n、腐蚀性、反应性、易燃性、浸出毒性等特性之一，它对人体健康和\n环境保护潜伏着巨大危害，如引起或助长死亡率增高，或使严重疾病\n的发病率增高，或在管理不当时会给人类健康或环境造成重大急性或\n潜在危害等。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2004,2005,2006,2009,2010,2011,2013,2017,2022],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":46,"sourceRange":{"startPage":46,"startY":534.57,"endPage":47,"endY":77.87},"sourceKind":"original","originalOrdinal":"7","sourceMetadata":["2004 (选、2005 (选、2006 (简、2009 (名、2010 (选、2011 (名)、2013 (论、2017(","论) 、2022 (名) ,【重要程度:"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":2,"excerpts":[{"page":46,"src":"./assets/environment/env838-11ddd4c042a0fab0-46.webp"},{"page":47,"src":"./assets/environment/env838-11ddd4c042a0fab0-47.webp"}]},{"id":"env838-c313e5d0890ed261","subject":"环境学导论","chapter":"第2章 全球环境问题","originalChapter":"第2章 全球环境问题","originalChapterNumber":2,"section":"第2节 中国的主要环境问题","originalSection":"第2节 中国的主要环境问题","category":"knowledge","title":"土地荒漠化的定义及危害","question":"土地荒漠化的定义及危害","type":"简答题","answer":"荒漠化是指由于自然原因或人为因素导致的土地退化。荒漠化包\n括土地沙漠化，石漠化和土壤盐渍化。\n土地荒漠化、沙化的危害主要表现在以下三个方面：\n(1)可利用土地资源减少\n20世纪50年代以来，中国有67万公顷耕地、235 万公顷草地和639\n万公顷林地变成沙地。中国国家林业局提供的资料显示，20世纪末沙\n化每年以3436平方千米的速度扩展，每5年就有一个相当于北京市行\n政区大小的国土面积因沙化而失去利用价值。\n(2)土地生产力严重衰退\n土壤风蚀不仅是沙漠化的主要组成部分，而且是首要环节。风蚀\n会造成土壤中有机质和细粒物质的流失，导致土壤粗化，肥力下降。\n(3) 自然灾害加剧\n土地荒漠化是最能让人类有直接感受的危害，导致自然灾害加剧\n。北方地区沙尘暴越来越频繁，且强度大，范围广。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":2,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":47,"sourceRange":{"startPage":47,"startY":77.87,"endPage":47,"endY":551.85},"sourceKind":"original","originalOrdinal":"8","sourceMetadata":["【重要程度:★★☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":2,"excerpts":[{"page":47,"src":"./assets/environment/env838-c313e5d0890ed261-47.webp"}]},{"id":"env838-106df18020474b32","subject":"环境学导论","chapter":"第2章 全球环境问题","originalChapter":"第2章 全球环境问题","originalChapterNumber":2,"section":"第2节 中国的主要环境问题","originalSection":"第2节 中国的主要环境问题","category":"knowledge","title":"石质荒漠化的定义","question":"石质荒漠化的定义","type":"简答题","answer":"石质荒漠化是指在热带、亚热带湿润、半湿润气候条件和岩溶\n极其发育的自然背景下，受人为活动干扰，使地表植被遭受破坏，导\n致土壤严重流失，基岩大面积裸露或砾石堆积的土地退化现象，也是\n岩溶地区土地退化的极端形式，简称“石漠化”。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":0,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":47,"sourceRange":{"startPage":47,"startY":551.85,"endPage":48,"endY":80.15},"sourceKind":"original","originalOrdinal":"9","sourceMetadata":["【重要程度:☆☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":2,"excerpts":[{"page":47,"src":"./assets/environment/env838-106df18020474b32-47.webp"},{"page":48,"src":"./assets/environment/env838-106df18020474b32-48.webp"}]},{"id":"env838-942ec1afeb3c582f","subject":"环境学导论","chapter":"第2章 全球环境问题","originalChapter":"第2章 全球环境问题","originalChapterNumber":2,"section":"第2节 中国的主要环境问题","originalSection":"第2节 中国的主要环境问题","category":"knowledge","title":"食品污染的定义","question":"食品污染的定义","type":"简答题","answer":"食品污染是指食品及其原料在生产和加工过程中，因农药、废水\n、污水、各种食品添加剂及病虫害和家畜疫病所引起的污染，以及霉\n菌毒素引起的食品霉变，运输、包装材料中有毒物质和多氯联苯、苯\n并芘所造成的污染的总称。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":48,"sourceRange":{"startPage":48,"startY":80.15,"endPage":48,"endY":270.8},"sourceKind":"original","originalOrdinal":"10","sourceMetadata":["【重要程度：、—"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":2,"excerpts":[{"page":48,"src":"./assets/environment/env838-942ec1afeb3c582f-48.webp"}]},{"id":"env838-4960d453bdba2361","subject":"环境学导论","chapter":"第2章 全球环境问题","originalChapter":"第2章 全球环境问题","originalChapterNumber":2,"section":"第2节 中国的主要环境问题","originalSection":"第2节 中国的主要环境问题","category":"knowledge","title":"食品污染的类型","question":"食品污染的类型","type":"简答题","answer":"食品污染分为生物性、化学性、物理性及放射性污染四类。\n(1) 生物性污染\n生物性污染是指有害的病毒、细菌、真菌以及寄生虫污染食品。\n鸡蛋变臭，蔬菜烂掉，主要是细菌、真菌在起作用。\n(2) 化学性污染\n化学性污染是由有害、有毒的化学物质污染食品引起的。农药是\n造成食品化学性污染的一大来源，还有含 Pb、Cd、Cr、Hg、硝基化合\n物等有害物质的工业废水、废气及废渣，食用色素、防腐剂、发色剂\n、甜味剂、固化剂、抗氧化剂食品添加剂，作食品包装用的塑料、纸\n张、金属容器等。\n(3) 物理性污染\n主要来源于非化学性的杂物，虽然有的污染物可能并不威胁消费\n者的健康，但会严重影响食品应有的感官性状或营养价值，使食品质\n量得不到保证，主要包括：①来自食品产、储、运、销的污染物，如\n粮食收割时混入的草籽、液体食品容器池中的杂物、食品运销过程中\n的灰尘等；②食品中掺假，如粮食中掺入沙石、肉中注入水、奶粉中\n掺入大量的糖，小麦粉生产过程中混入磁性金属物等。\n(4) 放射性污染\n食品中的放射性物质有来自地壳中的放射性物质，称为天然本底\n；也有来自核武器试验或和平利用放射能所产生的放射性物质，即人\n为的放射性污染。某些鱼类能富集金属同位素，如铯和锶等，后者半\n衰期较长，多富集于骨组织中，而且不易排出。某些海产动物，如软\n体动物能富集锶，牡蛎能富集大量锌，某些鱼类能富集铁。放射性核\n素对食品的污染有三种途径：①核试验的降沉物；②核电站和核工业\n废物的排放；③意外事故泄漏。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":0,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":48,"sourceRange":{"startPage":48,"startY":270.8,"endPage":49,"endY":384.18},"sourceKind":"original","originalOrdinal":"11","sourceMetadata":["【重要程度:☆☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":2,"excerpts":[{"page":48,"src":"./assets/environment/env838-4960d453bdba2361-48.webp"},{"page":49,"src":"./assets/environment/env838-4960d453bdba2361-49.webp"}]},{"id":"env838-f0575e16606d9671","subject":"环境学导论","chapter":"第2章 全球环境问题","originalChapter":"第2章 全球环境问题","originalChapterNumber":2,"section":"第2节 中国的主要环境问题","originalSection":"第2节 中国的主要环境问题","category":"knowledge","title":"生物多样性危机产生的原因","question":"生物多样性危机产生的原因","type":"简答题","answer":"(1 )生境碎片化和丧失\n对大多数物种而言，最严重的威胁来自生境减少和碎片化，是造\n成生物多样性丧失的主要原因之一，其主要原因是人类的影响和破坏\n，如大面积森林的乱砍滥伐、围湖造田、毁林开荒、过度放牧等，都\n会破坏和改变生物生存的生态环境，降低生态多样性。\n(2)生物资源不合理利用\n乱捕滥猎和乱采滥挖现象始终没有得到有效控制。例如，猕猴在\n20世纪50年代因过度捕捉出口，造成种群数量剧减，迄今尚未得到恢\n复。我国淡水鱼资源由于不断加大捕捞强度和不控制时间，产量急剧\n下降的同时，种群数量也很难回升。许多传统的中药和经济植物由于\n长期过量采挖和开发利用，致使种群数量急剧缩减。许多物种因被认\n为对人造成危害而被捕杀。\n(3) 环境污染\n环境污染也是造成生物多样性下降的原因之一。有机农药、重金\n属等有害物质不仅可以通过食物链积聚于生物体内，同时也破坏生态\n系统和生态平衡，使物种濒危或灭绝。\n(4) 外来物种引入\n一个外来物种引入后，有可能因不能适应新环境而被排斥在系统\n之外；也有可能因新的环境中没有相抗衡或制约它的生物，这个引进\n种可能成为真正的入侵者，打破平衡，改变或破坏当地的生态环境、\n严重破坏生物多样性。\n(5) 人口膨胀\n人为干扰因素的本质原因是人与野生动植物争夺生活空间，人口\n的膨胀必然导致人类对生物资源的需求加剧。\n(6) 全球影响\n一方面，温室效应、酸雨等全球气候变化造成中国气候的改变，\n引起一些物种生存环境的变化。另一方面，经济发达国家对中国国内\n资源的掠夺也造成很大的损害，如日本用做卫生筷的木材70%以上来\n自中国，使得我国大面积的森林被盲目采伐以换取经济价值，造成生\n态的恶化。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":0,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":49,"sourceRange":{"startPage":49,"startY":384.18,"endPage":51,"endY":72.92},"sourceKind":"original","originalOrdinal":"12","sourceMetadata":["【重要程度:☆☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":2,"excerpts":[{"page":49,"src":"./assets/environment/env838-f0575e16606d9671-49.webp"},{"page":50,"src":"./assets/environment/env838-f0575e16606d9671-50.webp"},{"page":51,"src":"./assets/environment/env838-f0575e16606d9671-51.webp"}]},{"id":"env838-4566a6c9fce40e4e","subject":"环境学导论","chapter":"第2章 全球环境问题","originalChapter":"第2章 全球环境问题","originalChapterNumber":2,"section":"第3节 课后习题","originalSection":"第3节 课后习题","category":"exercise","title":"全球环境问题主要有哪几种类型?其主要危害分别是什么?","question":"全球环境问题主要有哪几种类型?其主要危害分别是什么?","type":"简答题","answer":"①全球变暖：改变温度、降水和极端天气，导致海平面上升、生态系统与农业受损。\n②臭氧层破坏：增加到达地面的有害紫外线，损害人体健康、作物和水生生态系统。\n③酸沉降：使水体和土壤酸化，损伤森林、农作物、建筑和文物。\n④森林减少、土地退化及荒漠化：削弱水土保持与碳汇功能，降低土地生产力。\n⑤生物多样性丧失：损害遗传资源、生态系统稳定性和生态服务。\n⑥海洋污染、持久性有机污染物及危险废物跨境转移：造成长期、跨境和食物链风险。\n全球性问题往往相互促进，应同时分析其共同驱动因素。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":51,"sourceRange":{"startPage":51,"startY":111.75,"endPage":51,"endY":192.38},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":2,"excerpts":[{"page":51,"src":"./assets/environment/env838-4566a6c9fce40e4e-51.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=33"},{"title":"NASA：温室效应的原理","url":"https://science.nasa.gov/climate-change/faq/what-is-the-greenhouse-effect/","accessedOn":"2026-11-09"},{"title":"中国生物多样性保护战略与行动计划（2023—2030年）发布说明","url":"https://www.mee.gov.cn/xxgk/hjyw/202401/t20240118_1064111.shtml","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-35f6f7f3655d1f95","subject":"环境学导论","chapter":"第2章 全球环境问题","originalChapter":"第2章 全球环境问题","originalChapterNumber":2,"section":"第3节 课后习题","originalSection":"第3节 课后习题","category":"exercise","title":"全球环境问题的主要防治对策有哪些?","question":"全球环境问题的主要防治对策有哪些?","type":"简答题","answer":"①转变生产消费方式：提高资源利用效率，发展清洁生产、循环经济和绿色消费，减少污染物与温室气体的源头产生。\n②分类治理：推进节能和低碳能源转型；控制消耗臭氧层物质；减少SO₂、NOₓ等排放；治理海洋及危险化学品污染。\n③生态保护：保护森林、湿地和重要生境，修复退化生态系统，促进生物多样性保护。\n④制度与科技：完善环境法律、标准、监测预警、经济政策和公众参与，提高治理及风险管理能力。\n⑤国际合作：履行有关环境公约，推进资金、技术和信息合作，并兼顾不同国家的发展阶段与能力。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":51,"sourceRange":{"startPage":51,"startY":192.38,"endPage":51,"endY":274.31},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":2,"excerpts":[{"page":51,"src":"./assets/environment/env838-35f6f7f3655d1f95-51.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=33"},{"title":"中国生物多样性保护战略与行动计划（2023—2030年）发布说明","url":"https://www.mee.gov.cn/xxgk/hjyw/202401/t20240118_1064111.shtml","accessedOn":"2026-11-09"},{"title":"中国的能源转型白皮书（英文全文）","url":"https://english.www.gov.cn/archive/whitepaper/202408/29/content_WS66d012e8c6d0868f4e8ea52e.html","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-b23fdfb65af80548","subject":"环境学导论","chapter":"第2章 全球环境问题","originalChapter":"第2章 全球环境问题","originalChapterNumber":2,"section":"第3节 课后习题","originalSection":"第3节 课后习题","category":"exercise","title":"中国主要的环境问题有哪些?产生的影响分别体现在哪些方面?","question":"中国主要的环境问题有哪些?产生的影响分别体现在哪些方面?","type":"简答题","answer":"我国环境问题可概括为污染问题与生态破坏问题并存。\n①大气：颗粒物与臭氧等复合污染，影响健康和区域空气质量。\n②水：部分河湖富营养化、局部水体及地下水污染、近岸海域陆源污染，影响供水与水生态。\n③土壤及固废：重金属、有机物等污染及废物不当处置，威胁农产品和人居环境安全。\n④生态：水土流失、局部荒漠化、生境破碎化、生物多样性受损，削弱生态服务。\n⑤资源与气候：资源消耗强度、能源结构和碳排放带来转型压力。\n动态认识：2024年公报显示全国生态环境质量持续改善，但地区、流域及污染类型差异仍然存在；不能把历史污染描述直接当作当前全部状况。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":51,"sourceRange":{"startPage":51,"startY":274.31,"endPage":51,"endY":386.65},"sourceKind":"original","originalOrdinal":"3","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":2,"excerpts":[{"page":51,"src":"./assets/environment/env838-b23fdfb65af80548-51.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=33"},{"title":"生态环境部：2024中国生态环境状况公报","url":"https://www.mee.gov.cn/ywgz/sthjjcgl/hjzljcypj/202506/t20250605_1120773.shtml","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-b7061618811db6ef","subject":"环境学导论","chapter":"第2章 全球环境问题","originalChapter":"第2章 全球环境问题","originalChapterNumber":2,"section":"第3节 课后习题","originalSection":"第3节 课后习题","category":"exercise","title":"你对目前我国环境保护持何种态度，有何观点?","question":"你对目前我国环境保护持何种态度，有何观点?","type":"简答题","answer":"本题可按“肯定成效—识别短板—提出对策—个人行动”展开。\n①态度：支持生态优先、绿色发展，以改善生态环境质量和保障公众健康为目标。\n②成效：治理投入与制度建设持续加强，空气和地表水质量总体改善。\n③短板：复合污染、土壤和地下水风险、生态系统退化以及部分地区治理能力不足，仍需长期解决。\n④建议：强化源头减排、依法监管、科学监测和区域协同，推动产业与能源转型，完善公众监督和信息公开。\n⑤行动：节能节水、绿色出行、减少一次性用品、规范分类投放，并依法参与环境保护。\n这是讨论题，关键是观点明确、有事实依据并形成可实施的建议。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":51,"sourceRange":{"startPage":51,"startY":386.65,"endPage":51,"endY":468.08},"sourceKind":"original","originalOrdinal":"4","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":2,"excerpts":[{"page":51,"src":"./assets/environment/env838-b7061618811db6ef-51.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=33"},{"title":"生态环境部：2024中国生态环境状况公报","url":"https://www.mee.gov.cn/ywgz/sthjjcgl/hjzljcypj/202506/t20250605_1120773.shtml","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-ec875c894cb4b915","subject":"环境学导论","chapter":"第2章 全球环境问题","originalChapter":"第2章 全球环境问题","originalChapterNumber":2,"section":"第3节 课后习题","originalSection":"第3节 课后习题","category":"exercise","title":"了解环境保护法的修订背景及修订内容。","question":"了解环境保护法的修订背景及修订内容。","type":"简答题","answer":"按题目教材背景，重点回答2014年环境保护法修订：\n一、背景：旧法与快速变化的污染形势、监管需求不完全适应，违法成本偏低，执法、信息公开及公众参与等制度需要加强。\n二、主要内容：强化保护优先、预防为主等原则；明确政府、企业和公众责任；完善环境监测、信息公开及公众参与；建立按日连续处罚等更有力的责任机制，规定查封扣押、限产停产等措施，并完善环境公益诉讼。\n三、时间区分：2014年修订法自2015年1月1日起施行。按2026年11月检索的现行法律，生态环境法典已于2026年8月15日起施行，相关旧法同时废止。本题的“修订内容”属于历史考点，不能把旧法仍称为现行法。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":51,"sourceRange":{"startPage":51,"startY":468.08,"endPage":52,"endY":78.56},"sourceKind":"original","originalOrdinal":"5","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":2,"excerpts":[{"page":51,"src":"./assets/environment/env838-ec875c894cb4b915-51.webp"},{"page":52,"src":"./assets/environment/env838-ec875c894cb4b915-52.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=33"},{"title":"环境保护法2014年修订文本（历史资料）","url":"https://jjjcz.mee.gov.cn/djfg/gjflfg/fl/201404/t20140401_444481.html","accessedOn":"2026-11-09"},{"title":"生态环境部：2026年生态环境法典及施行说明","url":"https://www.mee.gov.cn/xxgk2018/xxgk/xxgk03/202604/t20260408_1148465.html","accessedOn":"2026-11-09"},{"title":"中华人民共和国生态环境法典","url":"https://www.mee.gov.cn/ywgz/fgbz/fl/202603/t20260313_1146496.shtml","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-b9539fa9a356457d","subject":"环境学导论","chapter":"第2章 全球环境问题","originalChapter":"第2章 全球环境问题","originalChapterNumber":2,"section":"第1节","originalSection":"第1节","category":"supplement","title":"有毒有害化学品污染","question":"有毒有害化学品污染","type":"简答题","answer":"随着全球有毒化学品种类和数量不断增加、国际贸易规模扩大，化学品对环\n境和人体的危害尚未完全明确，其在环境中的迁移也难以控制。为防止危险化学\n品和农药通过国际贸易造成危害，国际上通过《鹿特丹公约》实行事先知情同意\n程序。\n有毒有害化学品进入环境的途径主要有四种：人为施用直接进入环境；在生\n产、加工和储存过程中以废物形式排入环境；在生产、储存和运输过程中因突发\n事故进入环境；在燃料燃烧和日常生活使用过程中直接排入环境，或使用后作为\n废物进入环境。\nDDT、多氯联苯、二噁英等属于持久性有机污染物。这类物质在环境中化学\n性质稳定，容易蓄积在鱼类、鸟类及其他生物体内，最终通过食物链进入人体，\n对人类和环境构成威胁。具有慢性毒性、易挥发、难降解、高残留以及能够通过\n食物链危害健康等特征的化学品，尤其受到关注。\n有毒有害化学品的危害主要包括环境激素类损害、致癌致畸致突变损害，以\n及突发污染类损害。环境激素类化学品进入人体后，可干扰雄性激素分泌，损害\n生殖功能；部分化学品能够引起癌症、畸形和基因突变；有毒有害化学品突发污\n染事故则会严重威胁人民生命财产安全和社会稳定，有时还会造成重大生态灾难。","source":"环导变动137718728584015123.1eae00877280d3e.pdf","sourceUrl":"https://drive.google.com/file/d/11CjvWmrS4poAVMmBBWnsJPRCmD1-JkRJ/view","version":"new","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":1,"sourceRange":{"startPage":1,"startY":598.98,"endPage":2,"endY":352.96},"sourceKind":"changes","originalOrdinal":"20","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":2,"excerpts":[{"page":1,"src":"./assets/environment/env838-b9539fa9a356457d-1.webp"},{"page":2,"src":"./assets/environment/env838-b9539fa9a356457d-2.webp"}]},{"id":"env838-cd1685f702c06107","subject":"环境学导论","chapter":"第2章 全球环境问题","originalChapter":"第2章 全球环境问题","originalChapterNumber":2,"section":"第1节","originalSection":"第1节","category":"supplement","title":"太空污染","question":"太空污染","type":"简答题","answer":"一、定义\n太空垃圾又称空间碎片或轨道碎片，是宇宙空间中除正在工作的航天器以外\n的人造物体。其来源主要包括航天器发射过程中产生的碎片与报废卫星、航天器\n表面脱落的材料、涂层老化掉落的油漆斑块、航天器泄漏的固体和液体材料，以\n及火箭和航天器爆炸、碰撞产生的碎片。\n二、危害\n太空垃圾运行速度快，与航天器发生碰撞时具有巨大的破坏力。在距地面约\n300～450 km 的近地轨道上，太空垃圾的运行速度可达7～8 km/s，碰撞时的相\n对速度可高达10 km/s 以上。太空垃圾与运行中的人造卫星、载人飞船或空间站\n相撞，会危及设备乃至宇航员的生命。直径约10 cm 的太空垃圾就可使航天器完\n全损毁，毫米级碎片也可能使其无法继续工作。\n三、解决对策\n太空污染的解决对策主要包括太空清洁、监测控制、雷达跟踪和躲避垃圾。\n①太空清洁是将停止工作的卫星推送到其他轨道，避免与正常工作的卫星发生碰\n撞，或利用航天飞机将损坏的卫星带回地球，以减少太空中的人造垃圾；还可采\n用激光武器直接烧毁太空垃圾。②监测控制和雷达跟踪则通过雷达、光学或光电\n感应器等设备，监测太空垃圾的位置和运动情况，为识别、跟踪及避让提供依据。\n③太空垃圾飞行速度很快，航天器一旦被撞击，可能遭受损毁；为躲避太空垃圾，\n空间站的位置也可能需要调整。","source":"环导变动137718728584015123.1eae00877280d3e.pdf","sourceUrl":"https://drive.google.com/file/d/11CjvWmrS4poAVMmBBWnsJPRCmD1-JkRJ/view","version":"new","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":2,"sourceRange":{"startPage":2,"startY":352.96,"endPage":3,"endY":183.01},"sourceKind":"changes","originalOrdinal":"21","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":2,"excerpts":[{"page":2,"src":"./assets/environment/env838-cd1685f702c06107-2.webp"},{"page":3,"src":"./assets/environment/env838-cd1685f702c06107-3.webp"}]},{"id":"env838-660d02906a90bb1e","subject":"环境学导论","chapter":"第3章 水环境","originalChapter":"第3章 水环境","originalChapterNumber":3,"section":"第1节 地球上的水","originalSection":"第1节 地球上的水","category":"knowledge","title":"水圈的定义","question":"水圈的定义","type":"简答题","answer":"地球是由水圈、土壤圈、大气圈、岩石圈和生物圈组成的，而水\n圈又是最活跃的一个圈层。水圈是由地球地壳表层、表面和围绕地球\n的大气层中液态、气态和固态的水组成的圈层。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":52,"sourceRange":{"startPage":52,"startY":602.32,"endPage":53,"endY":76.52},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":["【重要程度："],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":3,"excerpts":[{"page":52,"src":"./assets/environment/env838-660d02906a90bb1e-52.webp"},{"page":53,"src":"./assets/environment/env838-660d02906a90bb1e-53.webp"}]},{"id":"env838-bd7d816942406e75","subject":"环境学导论","chapter":"第3章 水环境","originalChapter":"第3章 水环境","originalChapterNumber":3,"section":"第1节 地球上的水","originalSection":"第1节 地球上的水","category":"knowledge","title":"淡水的储量","question":"淡水的储量","type":"简答题","answer":"在地球水圈中淡水仅占总水量的2.53% ，且主要分布在冰\n川与永久积雪和地下。扣除目前暂时无法取用的冰川积雪及深层地\n下水，理论上可以开发利用的淡水不到地球总水量的1% 。实际上，\n人类可以利用的淡水量远低于这一理论值，因为许多淡水人们还无\n法利用。\n学长提示 : 曾经这个 1% 特别爱作为选择题去考 ， 后面没有选择题了 ， 这个点就不是很\n重要了","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":1,"pastExamYears":[2005,2007,2010],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。","含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":53,"sourceRange":{"startPage":53,"startY":76.52,"endPage":53,"endY":348.69},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":["2005(选、2005(选、2007 ( 简、2010( 选、2010( 选, 【重要程度: ★☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":3,"excerpts":[{"page":53,"src":"./assets/environment/env838-bd7d816942406e75-53.webp"}]},{"id":"env838-47f05fef551d714a","subject":"环境学导论","chapter":"第3章 水环境","originalChapter":"第3章 水环境","originalChapterNumber":3,"section":"第2节 水循环","originalSection":"第2节 水循环","category":"knowledge","title":"水循环的定义和作用","question":"水循环的定义和作用","type":"简答题","answer":"在太阳入射能和地球表面热能的共同作用下，地表水不断被\n蒸发成为水蒸气，进入大气。水蒸气遇冷凝结成水或冰，在地球重\n力的作用下，以降水形式落至地表。水的这个周而复始的运动过程称\n为水循环。水循环是地球上最重要的物质循环之一，它不仅实现全球\n的水量转移，而且推动全球能量交换和生物地球化学循环，并为人类\n提供不断再生的淡水资源。\n水循环的主要作用表现在：水循环联系着地球的各个圈层，并在\n各个圈层间进行物质和能量交换，直接涉及自然界中一系列的物理\n、化学和生物过程。在垂直方向上，通过蒸发、降水、下渗、植物\n蒸腾等环节，把大气圈、水圈、生物圈、岩石圈联系起来；在水\n平方向上，通过水汽输送和径流输送，把陆地和海洋联系起来。\n图 3-1 水循环示意图","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2003],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。","含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":53,"sourceRange":{"startPage":53,"startY":391.26,"endPage":54,"endY":327.87},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":["2003(简,【重要程度:"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":3,"excerpts":[{"page":53,"src":"./assets/environment/env838-47f05fef551d714a-53.webp"},{"page":54,"src":"./assets/environment/env838-47f05fef551d714a-54.webp"}]},{"id":"env838-c5caf851b9d0ae7b","subject":"环境学导论","chapter":"第3章 水环境","originalChapter":"第3章 水环境","originalChapterNumber":3,"section":"第2节 水循环","originalSection":"第2节 水循环","category":"knowledge","title":"社会水循环","question":"社会水循环","type":"简答题","answer":"水的社会循环指在水的自然循环中，人类不断利用地下径流或地\n表径流满足生活与生产活动之需，使用后又排回自然水体的人工循环\n。最典型的社会水循环莫过于城市用水。城市从自然水体中取水，净\n化后供给工业、商业、市政和居民使用，用后的污水经排水系统输送\n到污水处理厂，处理后又排回自然水体。\n水的社会循环系统可分为给水系统和排水系统两大部分，两者是\n不可分割的统一有机体。给水系统是自然水的提取、加工、供应和使\n用过程，好比是水社会循环的动脉，用后污水的收集、处理与排放这\n一排水系统则是水社会循环的静脉。在水的社会循环中，污水的收集\n与处理系统是能否维持水社会循环可持续性的关键，是连接水社会循\n环与自然循环的纽带。\n城市 4\n[待核对] | 供水 】 (4x J)\nSS 水体了\n图 3-2 社会水循环示意图","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。","含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":54,"sourceRange":{"startPage":54,"startY":327.87,"endPage":55,"endY":263.45},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":["【重要程度："],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":3,"excerpts":[{"page":54,"src":"./assets/environment/env838-c5caf851b9d0ae7b-54.webp"},{"page":55,"src":"./assets/environment/env838-c5caf851b9d0ae7b-55.webp"}]},{"id":"env838-9ea2089f9af59ad6","subject":"环境学导论","chapter":"第3章 水环境","originalChapter":"第3章 水环境","originalChapterNumber":3,"section":"第3节 水污染及其主要来源","originalSection":"第3节 水污染及其主要来源","category":"knowledge","title":"水污染的定义","question":"水污染的定义","type":"简答题","answer":"水污染是指水体因某种物质的介入，导致水的物理、化学、\n生物或者放射性等方面特性的改变，从而影响水的有效利用，危害\n人体健康或者破坏生态环境，造成水质恶化的现象。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":55,"sourceRange":{"startPage":55,"startY":305.53,"endPage":55,"endY":475.12},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":["【重要程度："],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":3,"excerpts":[{"page":55,"src":"./assets/environment/env838-9ea2089f9af59ad6-55.webp"}]},{"id":"env838-262799098d41e1d5","subject":"环境学导论","chapter":"第3章 水环境","originalChapter":"第3章 水环境","originalChapterNumber":3,"section":"第3节 水污染及其主要来源","originalSection":"第3节 水污染及其主要来源","category":"knowledge","title":"水体富营养化及其危害","question":"水体富营养化及其危害","type":"简答题","answer":"在人类活动的影响下，氮、磷等营养物质大量排入河口、湖泊、\n海湾等缓流水体，导致藻类和浮游植物迅速繁殖，水体溶解氧下降，\n水质恶化，导致鱼类和其他生物大量死亡的现象称为水体富营养化。\n富营养化会影响水质，导致水的透明度降低，使得阳光难以穿透\n水层，从而影响植物的光合作用，导致溶解氧的过饱和状态，溶解氧\n的过饱和以及水中溶解氧的减少，都会对水生动物有害，造成鱼类大\n量死亡；同时，在水体表面生长着以蓝、绿藻为优势种的大量水藻，\n形成一道绿色浮渣，致使堆积底层的有机物质在厌氧条件下分解产生\n的有害气体和一些浮游生物产生的生物毒素也会伤害鱼类；因富营养\n化水中含有的硝酸盐和亚硝酸盐，人畜长期饮用这些物质含量超过一\n定标准的水，也会中毒致病。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2002,2004,2011,2013,2015,2016,2017,2018,2019],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":55,"sourceRange":{"startPage":55,"startY":475.12,"endPage":56,"endY":173.49},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":["2002(名、2004(名、2013(名、2016 (名、2018(名2002(简、2011(简、2015(简、","2017(论、2019(简, 【重要程度:"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":3,"excerpts":[{"page":55,"src":"./assets/environment/env838-262799098d41e1d5-55.webp"},{"page":56,"src":"./assets/environment/env838-262799098d41e1d5-56.webp"}]},{"id":"env838-b9993fa5c75167ae","subject":"环境学导论","chapter":"第3章 水环境","originalChapter":"第3章 水环境","originalChapterNumber":3,"section":"第4节 水污染控制","originalSection":"第4节 水污染控制","category":"knowledge","title":"水污染物来源","question":"水污染物来源","type":"简答题","answer":"水污染源可分为自然污染源和人为污染源两类。按污染物进入水\n环境的空间分布方式，人为污染源又可分为点污染源和面污染源。\n(1) 点污染源\n指集中由排污口排入水体的污染源，主要是生活污水和工业废水\n生活污水主要来自家庭、机关、商业以及城市公用设施的污水，\n包括冲厕排水、洗浴排水、厨房排水、洗涤排水等。生活污水的成分\n，99%为水，固体杂质不到1%，污染物以悬浮态或溶解态的有机物、\n无机物为主, 此外含有部分微量金属(Zn、Cu、Cr、Mn、Ni和 Pb等\n)，以及多种致病菌等。特性包括：\n①含氮、磷、硫高\n②在生活污水中有机物质主要有纤维素、淀粉、糖类、脂肪、蛋\n白质和尿素等。在厌氧细菌作用下，易产生恶臭物质，如硫化氢等。\n③含有大量的合成洗涤剂，对人体可能有一定的危害。\n④含有多种微生物，每毫升污水中可含有几百万个细菌，病原菌\n也多。\n工业废水是水中最重要的污染源，它量大、面广，含污染物多，\n成分复杂，在水中不易净化，处理也比较困难。特性包括：\n①悬浮物质含量高,最高可达30000 mg/L\n②需氧量高，有机物一般难于降解。对微生物起毒害作用\n③COD为400-10000 mg/L\n④BOD为200-50000 mg/L\n⑤PH值变化幅度大, pH =2-13\n⑥温度较高，排入水体可引起热污染\n⑦易燃，常含有低燃点的挥发性液体如汽油等\n⑧含多种多样的有害成分，如硫化物、氰化物等。\n(2)面污染源\n面污染源又称非点污染源，指以大面积范围排放污染物输入水体\n的污染源，通常表现为无组织性，主要包括农村灌溉水形成的径流、\n农村废水和地面雨水径流等。量小而分布很广的点污染源，也可视为\n面污染源。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2025],"needsReview":false,"reviewReasons":[],"verified":false,"page":56,"sourceRange":{"startPage":56,"startY":213.39,"endPage":57,"endY":537.97},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":["2025(简) , 【重要程度:"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":3,"excerpts":[{"page":56,"src":"./assets/environment/env838-b9993fa5c75167ae-56.webp"},{"page":57,"src":"./assets/environment/env838-b9993fa5c75167ae-57.webp"}]},{"id":"env838-e48772c5cac35aff","subject":"环境学导论","chapter":"第3章 水环境","originalChapter":"第3章 水环境","originalChapterNumber":3,"section":"第4节 水污染控制","originalSection":"第4节 水污染控制","category":"knowledge","title":"水污染物","question":"水污染物","type":"简答题","answer":"学长提示 ; 这个知识点很重要 ， 可以作为一个整体考简答或者论述 ， 下面的各小类污\n染物尤其是需氧污染物 ， 出题频率很高 ， 可以考名词解释 、 简答\n造成水体水质、水中生物群落以及水体底泥质量恶化的各种有害\n物质(或能量)都可叫做水体污染物。常见的污染物种类如下。\n[1]固体污染物\n固体物质在水中有三种存在形态：溶解态、胶体态和悬浮态。主\n要来自于矿石处理、冶金、化工、化肥、造纸和食品加工等过程，还\n来自农田排水和水土流失等。\n悬浮物会使水体浑浊，影响水生植物的光合作用，而且水体中的\n悬浮物沉积淤塞河道，危害水体底栖生物的繁殖，影响渔业生产。灌\n溉时悬浮物会堵塞土壤的孔隙，不利于作物的生长。严重的是当水体\n中含有有毒物质时，会因悬浮物的吸附作用使污染程度加深。\n[2]耗氧有机物\n生活污水和印染、造纸、食品、餐饮、石化等工业废水中含有碳\n水化合物、蛋白质、氨基酸、脂肪酸、油脂等有机物和其他可被生物\n降解的人工合成有机物。这些物质本身无毒，但排入水体后在微生物\n作用下分解，会消耗水体大量的氧，使水中溶解氧降低，故称为耗氧\n有机物。\n学长提示 :; 书上的注释性文字可以帮助大家理解 : 在标准状况下 , 水中溶解气约 9mg/L\n。 溶解氧降至 4mg/L 以下时 ， 将严重影响鱼类和水生生物的生存 ; 溶解氧降低到 lmg/L\n时 ， 大部分鱼类会室息死亡 ; 溶解氧降至零时 ， 水中厌氧微生物占据优势 ， 有机物将\n进行厌氧分解 ， 产生 CH4s、H2S、NH4 和硫醇等难闻 、 有毒气体 ， 造成水体发黑发奥 ，\n影响甚至室息水中鱼类及其他水生生物 ， 还会影响城市供水及工农业用水 、 景观用水","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2003,2005,2008],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。","含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":57,"sourceRange":{"startPage":57,"startY":537.97,"endPage":58,"endY":603.06},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":["2005(论--各污染物的来源和影响、2008(简-各污染物的类型和来源","【重要程度：","2003 ( 填, 【重要程度:"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":3,"excerpts":[{"page":57,"src":"./assets/environment/env838-e48772c5cac35aff-57.webp"},{"page":58,"src":"./assets/environment/env838-e48772c5cac35aff-58.webp"}]},{"id":"env838-bfc002bb8c7166d1","subject":"环境学导论","chapter":"第3章 水环境","originalChapter":"第3章 水环境","originalChapterNumber":3,"section":"第4节 水污染控制","originalSection":"第4节 水污染控制","category":"knowledge","title":"河流遭到需氧有机污染物污染后BOD₅和DO（溶解氧）的变化规律","question":"河流遭到需氧有机污染物污染后BOD₅和DO（溶解氧）的变化规律","type":"简答题","answer":"氧垂曲线说明水体对需氧有机废物的天然净化过程 。 河流遭到需所有机污染物污染后\nBOD5 和 DO (溶解氧 ) 的变化规律如下所示 :\n首先当有机污染物排入河流中时 ， 由于细菌等微生物对有机污染物的分解作用 ， 使得\n溶解所逐渐降低 ，BOD5 迅速上升 ， 同时有机污染物逐渐减少 。 随着反应的不断进行 ，\n溶解所逐渐减少 ， 当溶解气越来越低于氧在水中的溶解度时 ， 再充气过程开始加快 ，\n使得空气中更多的氧进入水体中弥补氧的不足 ， 则溶解氧下降逮度减慢 , BOD5 上升的\n速度也减慢 。 当好气与需气两种相反作用达到平衡时 ， 溶解氧下降与上升的速度相等 |\n时 ， 氧验曲线不再降低 ， 溶解氧不再减少 ， 随着反应的继续进行 ， 溶解气不断增加 ，\n有机污染物逐渐减少 , 氧驮曲线开始回升 ， 直至溶解氧恢复到正常为止 ， 而 BOD5 则开\n始下降并最终达到未被污染前的水平 。 此时 ， 河流完成自净过程 。\n河流流向\n图 3-3 需氧有机污染物污染水体后 BODs 和 DO 关系图","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2005,2010],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。","含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":58,"sourceRange":{"startPage":58,"startY":603.06,"endPage":59,"endY":371.57},"sourceKind":"original","originalOrdinal":"supp-1","sourceMetadata":["2005 (名 -- 溶解氧 、2010〈 简 -分析 BODs 和 DO 的变化 ，【 重要程度 ， 妇妇女女六 】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":3,"excerpts":[{"page":58,"src":"./assets/environment/env838-bfc002bb8c7166d1-58.webp"},{"page":59,"src":"./assets/environment/env838-bfc002bb8c7166d1-59.webp"}]},{"id":"env838-0b06c5ddb834c59b","subject":"环境学导论","chapter":"第3章 水环境","originalChapter":"第3章 水环境","originalChapterNumber":3,"section":"第4节 水污染控制","originalSection":"第4节 水污染控制","category":"knowledge","title":"氧垂曲线的定义及形成","question":"氧垂曲线的定义及形成","type":"简答题","answer":"在河流受到大量有机物污染时 ， 由于微生物对有机物的氧化分解作用 ， 水体溶解\n氧发生变化 ， 随着污染源到河流下游一定距离内 ， 溶解氧由高到低 ， 再到原来溶解所\n水平 ， 可绘制成一条溶解气变化曲线 ， 称之为气短曲线 。\n该图反应了耗氧和复氧的协同作用 。 图中 a 为有机物分解的耗氧曲线 ，b 为水体复\n氨曲线 ，C 为氧重曲线， 了最低点 Cp 为最大缺气点 。 若 Cp 点的溶解氧量大于有关规定的量\n， 从溶解氧的角度看 ， 说明污水的排放未超过水体的自净能力 。 若排入有机污染物过\n多 ， 超过水体的自净能力 ， 则 Cp 点低于规定的最低溶解氧含量 ， 甚至在排放点下的某\n一段会出现无氧状态 ， 此时氧生曲线中断 ， 说明水体已经污染 。 在无氧情况下 ， 水中\n[待核对] AMA REMADE AT RED, FRR, PRE, KHER, BURR\n[待核对] | eee\nDs\n[待核对] 7B MEA (meg/T.)\n[待核对] 3-4 thew\n[3] 植物性营养物\n植物营养物主要指氮、磷化合物，主要来源是化肥、农业废弃物\n、生活污水和造纸制革、印染、食品、洗毛等工业废水。植物营养物\n污染主要表现为水体富营养化。\nN和P的浓度分别超过0.2mg/L和0.02mg/L时，会引起富营养化，促使藻类迅\n速繁殖，在水面上形成大片水华或赤潮。当藻类大量死亡时，水中BOD猛增，导\n致生物腐败，恶化环境卫生，危害水产业。此外，生活污水经过处理以后，含氮\n、磷的有机物转化为无机的氮、磷，也是造成营养性污染的主要途径。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2011,2015],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。","含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":59,"sourceRange":{"startPage":59,"startY":371.57,"endPage":60,"endY":505.33},"sourceKind":"original","originalOrdinal":"supp-2","sourceMetadata":["2011 (fi. 2015 (%, [BRBE: kkkinr]"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":3,"excerpts":[{"page":59,"src":"./assets/environment/env838-0b06c5ddb834c59b-59.webp"},{"page":60,"src":"./assets/environment/env838-0b06c5ddb834c59b-60.webp"}]},{"id":"env838-59d2a6afa3d59754","subject":"环境学导论","chapter":"第3章 水环境","originalChapter":"第3章 水环境","originalChapterNumber":3,"section":"第4节 水污染控制","originalSection":"第4节 水污染控制","category":"knowledge","title":"植物营养素的来源","question":"植物营养素的来源","type":"简答题","answer":"天然水中过量的植物营养物质主要三个途径 : 第一个途径 ， 也是主要方面 ， 来源\n于化肥 ; 第二个途径 ， 来自生活污水中 〈 和氮的主要来源 ) 和含磷洗涤剂 ; 第三个途径\n， 由于雨 、 雪对大气的淋洗和对磷灰石 、 硝石 、 鸟粪层的冲刷 ， 大量的植物营养物质\n汇入水体 。\n[4] 重金属\n作为水污染物的重金属，主要指 Hg、Cd、Pb、Cr以及类金属砷等\n生物毒性显著的元素，也包括具有一定毒性的一般重金属(如Zn、Ni\n、Co、Sn等)。从重金属对生物与人体的毒性危害来看，重金属污染\n的特点表现为：\n①微量致毒性，一般重金属产生毒性的浓度范围在1~10mg/L之\n间, 毒性较强的金属 Hg、Cd等为0.01~0.001 mg/L;\n②生物放大性，重金属不能被生物降解，生物从环境中摄取的重\n金属会通过食物链发生生物放大、富集，在大体内不断积蓄造成慢性\n中毒；\n③重金属的毒性与金属的形态有关，水体中的某些重金属可在微\n生物的作用下化为毒性更强的金属化合物。\n[5]难降解有机物\n难降解有机物是指那些难以被自然降解的有机物，大多为人工合\n成化学物质，如有机氯化合物、有机重金属化合物以及多环有机物等\n。这些化学物质的特点是能在水中长期稳定地存留，并在食物链中进\n行生化积累。\n[6]石油类物质\n石油污染，指在开发、炼制、储运和使用中，原油或石油制品因\n泄漏、渗透而进入水体。沿海及河口石油的开发、油轮运输、炼油工\n业废水的排放以及生活污水的大量排放等都会导致水体受到石油的\n污染。石油类物质除会引起火灾外，它的危害还在于原油或其他油类\n在水面形成油膜，隔绝氧气与水体的气体交换，堵塞鱼类等动物\n的呼吸器官，黏附在水生植物或浮游生物上，导致水鸟和水生生物的\n死亡。\n[7]酸碱污染物\n酸碱污染主要是酸类和碱类物质进入废水引起的，一般用pH值\n反映其效应。酸性废水主要来自于湿法冶金厂、金属酸洗工艺、矿山\n及化工厂等；碱性废水来自印染厂、炼铝工艺、制碱厂等。酸碱污染\n会改变水体的pH值，破坏水体的自然缓冲作用和水体生态系统的平\n衡。\n[8] 病原体\n病原体指可造成人或动物感染疾病的微生物(包括细菌、病毒、\n立克次氏体、寄生虫、真菌)或其他媒介(微生物重组体包括杂交体\n或突变体)。生活污水、医院污水、皮毛、制革、屠宰、生物制品等\n工业行业废水，常常含有各种病原体，如病毒、寄生虫、病菌、霍乱\n、伤寒、肠炎、胃炎、痢疾及其他多种病毒传染病及寄生虫病。受污\n染后的水体，微生物的数量剧增，以病虫卵、致病菌和病毒为主，它\n们常常与其他细菌和大肠杆菌共存，因此一般规定用细菌总数和大肠\n杆菌指数及菌值数作为病原体污染的直接指标。传统的二级生化污水\n处理以及消毒后，某些病毒、病原微生物仍可以存活。\n[9] 热污染\n工矿企业排放的高温废水使水体的温度升高，称为热污染。热污\n染为一种能量污染。水体的温度升高会使水中溶解氧含量降低，影响\n鱼类的生存和繁殖，加快一些细菌和藻类的繁殖，使厌氧菌发酵，水\n体恶臭。同时，热污染会加快生化反应和化学反应的速度，还会提高\n某些有毒物质的毒性，破坏生态系统的平衡。\n鱼类的生长都有一个最佳的温度区间。水温过高或者过低都不适\n合鱼类的生长，严重时会导致鱼类的死亡。而且，鱼的种类不同所适\n应的温度也是不一样。\n[10] 放射性污染\n水体放射性污染是放射性物质进入水体后造成的，对人体有危害\n的有X射线、α射线、β射线、γ射线及质子束等。这类物质主要来\n自核电厂的冷却水、核爆炸物体的散落物、放射性废物、原子能发电\n、生产以及使用放射性物质的机构。水体中的放射性物质可被生物体\n的表面吸附，也可以进入生物体内蓄积起来，还可以通过食物链对人\n体产生内照射。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2000,2001,2004,2005,2010,2019],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。","含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":60,"sourceRange":{"startPage":60,"startY":505.33,"endPage":63,"endY":190.34},"sourceKind":"original","originalOrdinal":"supp-3","sourceMetadata":["2000 ( 填 、2001 (HE. 2005 GH. 2010 ( 选 、2019〈 简 ，【 重要程度 ， 文妇女女六 】","2004(选、2010(选, 【重要程度;"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":3,"excerpts":[{"page":60,"src":"./assets/environment/env838-59d2a6afa3d59754-60.webp"},{"page":61,"src":"./assets/environment/env838-59d2a6afa3d59754-61.webp"},{"page":62,"src":"./assets/environment/env838-59d2a6afa3d59754-62.webp"},{"page":63,"src":"./assets/environment/env838-59d2a6afa3d59754-63.webp"}]},{"id":"env838-1e3315ad96de154c","subject":"环境学导论","chapter":"第3章 水环境","originalChapter":"第3章 水环境","originalChapterNumber":3,"section":"第4节 水污染控制","originalSection":"第4节 水污染控制","category":"knowledge","title":"污水水质指标","question":"污水水质指标","type":"简答题","answer":"①悬浮物，是指污水中呈固体状的不溶解物质，是水体污染基本指标之一。\n②有机物浓度，一般采用下面几个指标来表示有机物浓度：\n生化需氧量BOD，表示水中的有机污染物经微生物分解所需的氧量(单位体积的\n污水所消耗的氧量)，BOD越高，表示需氧有机物越多。\n化学需氧量COD，即用化学氧化剂氧化水中有机污染物所需的氧量，COD越高，\n表示需氧有机物越多。\n、2008 ( 名—BOD 、2011 ( 名—COD 、2016 、简--BOD测定原理\n总有机碳TOC，表示污水中有机污染物的总含碳量。\n总需氧量TOD，有机物中C、H、N、S元素在有机物被完全氧化时分别被氧化成各\n自对应的氧化物所消耗的氧的总量。\n③PH值。PH值对污水处理及综合利用，水中生物的繁殖等都有很大影响。其中生活污\n水PH值为7.2-7.6，工业废水变化较大。\n④污水的细菌污染指标。用1ml水中细菌总数，水中大肠杆菌的多少来计。\n⑤污水中有毒物质指标","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2000,2001,2002,2003,2005,2022,2025],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":63,"sourceRange":{"startPage":63,"startY":190.34,"endPage":63,"endY":631.49},"sourceKind":"original","originalOrdinal":"supp-4","sourceMetadata":["2003(填、2005(选、2022 (简,2025(名—生化需氧量) 【重要程度:","2000 (简--测定BOD为何选用 、2001 ( 名—BOD 、2001 ( 简— 简述BOD 、2002 (名","【重要程度："],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":3,"excerpts":[{"page":63,"src":"./assets/environment/env838-1e3315ad96de154c-63.webp"}]},{"id":"env838-902c031b3854179d","subject":"环境学导论","chapter":"第3章 水环境","originalChapter":"第3章 水环境","originalChapterNumber":3,"section":"第4节 水污染控制","originalSection":"第4节 水污染控制","category":"knowledge","title":"典型水体污染","question":"典型水体污染","type":"简答题","answer":"水体污染指进入水体的污染物质的数量超过水体的自净能力，使水\n质变劣，影响甚至失去水的原来价值和作用。\n水体污染有河流污染、湖泊污染、海洋污染以及地下水污染。\n一、 河流污染\n[1] 河流污染控制的主要措施\n①控制污染源。控制污染源是控制河流污染最为直接的方法。工\n业废水、生活污水和雨水径流进入河道是形成河流污染的主要原因。\n污染源的控制应从河流水质的现状出发，追踪调查污染物的主要来源\n，确定各类污染物的排放情况，研究企业的排放规律，从而确定污染\n源的消减量，利用行政手段、经济手段以及市场机制来进行污染源的\n削减。\n②加强法制建设，完善奖惩制度。对于违法排污的企业加大惩罚\n力度，并建立统一有序、分工负责的工作机制，严肃查处擅自停运污\n染治理设备、偷排污染物的不法行为，确保水污染防治设施的运行。\n还可与税务部门协调联合，使企业在治污当中增加利益，建立激励企\n业治污体制，使企业受益，以增加企业治污的积极性。\n③大力推行清洁生产。工业部门要加快产业结构调整，合理调整\n工业布局，推动资源消耗小、效益高的高新技术产业的发展。推行清\n洁生产，要把清洁生产当作在可持续发展战略指导下的一次工业企业\n的全面改造。\n④加强人们环保意识。为人们讲解环保知识，进行多种形式的宣\n传，使人们对河流污染的来源、途径以及危害有一个直观的认识，人\n人从自身做起，减少对河流的危害。\n二、湖泊污染\n三、海洋污染\n[1]海洋污染的特点\n①污染源广。不仅人类在海洋的活动可以污染海洋，而且人类在\n陆地和其他活动方面所产生的污染物，也会通过江河径流、大气扩散\n和降水等形式，最终汇入海洋。\n②持续性强。海洋不可能像大气和江河那样，通过一次暴雨或一\n个汛期，使污染物转移或消除。污染物一旦进入海洋，就很难再转移\n出去，往往通过生物的富集作用和食物链传递，对人类造成潜在威胁\n③扩散范围广。全球海洋是相互连通的一个整体，一个海域遭到\n污染，往往会扩散到周边海域，甚至有的后期效应还会波及全球。\n④防治难、危害大。海洋污染有很长的积累过程，往往不易及时\n发现。一旦形成污染，治理费用大，需要长期治理才能消除影响，特\n别是对人体产生的毒害难以彻底清除干净。\n四、地下水污染\n[1]地下水污染的概念\n地下水污染的定义是指地下水的污染物质超过地下水的自净能\n力，从而使地下水的组成及其性质发生变化的现象。\n[2]地下水污染的防治措施\n①减少污染物的排放。对产生的废水加强无害化处理，严禁未经\n处理的污水排向地下；利用高效、低毒的农药，减轻农药的污染。\n②防止污水入渗。在选择废料堆放地等污染地带，修建防渗构筑\n物；加强下水道封闭性，减少渗漏，堵塞并截留污染水体的扩散。\n③合理布局。排污量大的工矿企业要远离地面水体和地下水补给\n区；污染物需要深埋处理时，要研究地质和水文地质条件。\n④加强监管措施。严格设置戒严带，取水构筑物附近不得存在污\n染源；限制带即戒严带以外抽水影响半径以内，禁用污灌和剧毒农药\n，不得修建厕所、粪坑、垃圾坑、污水管道，不得破坏深层土壤；监\n视带如存在潜在污染源，要对其进行监视并进行流行病学观察，以便\n及时采取治疗。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":0,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":63,"sourceRange":{"startPage":63,"startY":631.49,"endPage":66,"endY":86.28},"sourceKind":"original","originalOrdinal":"3","sourceMetadata":["【重要程度: ☆☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":3,"excerpts":[{"page":63,"src":"./assets/environment/env838-902c031b3854179d-63.webp"},{"page":64,"src":"./assets/environment/env838-902c031b3854179d-64.webp"},{"page":65,"src":"./assets/environment/env838-902c031b3854179d-65.webp"},{"page":66,"src":"./assets/environment/env838-902c031b3854179d-66.webp"}]},{"id":"env838-9ed9eea3d4d0b1f4","subject":"环境学导论","chapter":"第3章 水环境","originalChapter":"第3章 水环境","originalChapterNumber":3,"section":"第4节 水污染控制","originalSection":"第4节 水污染控制","category":"knowledge","title":"水污染控制技术","question":"水污染控制技术","type":"简答题","answer":"学长提示 : 本书新增了几个章节非常有趣 ， 一个是本章中的水污染控制技术 ， 一个是\n下一章中的大气污染控制技术 ， 还有一个是第六章的固废处理技术 ， 这些在何强版的\n节里面均不涉及 ， 单论知识点归属来说 ， 分别属于水污染控制工程 、 大气污染控制工\n程和轿体废物处理与处置 ， 这些也都是大家的初复试科目 ， 我猜测这也是为什么要更\n换参考书的原因 ， 考察的可能性还是比较大 ; 还有第五章土壤的组成和基本性质 ， 这\n一章基本上是全部照搬于环境化学中的内容 ， 所以在第五章 ， 我很多说法都沿用了环\n境化学中的说法 。\n知识点 4、5 的内容可以先不看 ， 在水控中都会再次出现 ， 且更详细 。\n废水的处理就是利用物理、化学、生物的方法对废水进行处理，\n使废水进行净化，减少污染，以达到排放、利用、回用的标准。废水\n处理技术按照其作用的原理可以分为物理处理法、化学处理法、物理\n化学处理法和生物处理法四大类。\n一、物理处理法\n物理处理法是通过物理作用分离水中不溶解的呈悬浮状态的污\n染物(包括油膜和油珠)的废水处理方法，常用的有筛滤截留法、重\n力分离法、气浮法以及离心分离法等。\n[1]筛滤截留法\n利用带孔眼的装置或由某种介质组成的滤层截留废水中悬浮固\n体的方法，这种方法使用的设备有以下几种。\n①格栅：由一排平行的金属栅条做成的金属框架，斜置在废水流\n过的渠道上，用以截阻大块的固体物；\n②筛网：用以截阻、去除水中的纤维、纸浆等较细小的悬浮物。\n筛网一般用薄铁皮钻孔制成，或用金属丝编成，孔眼直径为0.5~\n1.0mm。筛网有转鼓式、圆盘式和帘带式等。\n③布滤设备：以帆布、尼龙布或毛毡为过滤介质，用以截阻、去\n除水中的细小悬浮物，也用于污泥脱水。常用的布滤设备为真空转筒\n滤机。\n④砂滤设备：以石英砂为滤料，用以过滤截留微细的悬浮物，一\n般作为保证后续处理单元稳定运行的装置。\n[2]重力分离( 即沉淀) 法\n重力分离法是利用水中悬浮的污染物和水的密度差的原理，通过\n重力作用使悬浮物质沉淀或上浮，从而净化废水的一种废水处理方法\n。常见的处理设备有沉砂池、沉淀池和隔油池。\n在污水的处理与再利用过程中，沉淀或上浮一般常被作为其他处\n理的预处理。在生物处理设备前设初次沉淀池，去除大部分的悬浮物\n，以减轻后继处理设备的负荷，保证生物处理设备净化功能的正常发\n挥。而且，在生物处理设备后设二次沉淀池，用以分离生物污泥，使\n处理水得到澄清，保证出水水质。\n[3] 气浮法\n气浮法是一种有效的固液和液液分离方法，常用于那些颗粒密度\n接近或小于水的细小颗粒分离。气浮法处理技术是在水中形成微小气\n泡形式，使微小气泡与悬浮颗粒黏附，形成水—气—颗粒三相混合体\n系，颗粒黏附上气泡后，形成表观密度小于水的漂浮絮体，絮体上浮\n至水面，形成浮渣层被刮除，实现固液分离。为了提高处理效果，有\n时需要向废水中投加混凝剂。\n[4]离心分离法\n离心分离法是利用装有废水的容器高速旋转形成的离心力，悬浮\n颗粒因和废水受到的离心力大小不同而被分离的方法。按离心力产生\n的方式，可分为水旋分离器和离心机两种类型。在分离过程中，悬浮\n颗粒质量按由小到大分布，受到离心力的作用被分离后，按由外到内\n分布，通过不同的液体排出口，使悬浮颗粒从废水中分离出来。\n二、化学处理方法\n化学处理法是通过化学反应和传质作用来分离、去除水中呈溶解\n、胶体状态的污染物或将其转化为无害物质的废水处理法。常用的化\n学处理方法有混凝法、化学沉淀法、中和法、氧化还原法(包括电解\n) 等。\n[1] 混凝法\n混凝处理法是通过向废水中投加混凝剂，使水中的胶体和颗粒失\n去稳定性，发生凝聚和絮凝而分离出来，以净化废水的方法。混凝法\n主要是处理废水中微小的悬浮物和胶体。常用的混凝剂有\n3、碱式氯化铝、铁盐[主要指 3、 ,FeCl ₃]等。混凝法\n可以降低废水的色度和浊度，大幅度提高有机污染物的去除效率，同\n时还能取得较好的除磷效果，改善污泥的脱水性能。\n[2]化学沉淀法\n化学沉淀法是向废水中投加某些化学物质，使它和废水中欲去除\n的污染物发生直接的化学反应，生成难溶于水的沉淀物而使污染物分\n离除去的方法。化学沉淀法经常用于处理含有 Hg、Pb、Cu、Zn、\n、S、CN-、F、As等有毒化合物的废水。向废水中投加氢氧化物、硫\n化物、碳酸盐等生成金属盐沉淀，向废水中投加钡盐生成铬酸盐沉淀\n处理含六价铬的工业废水，向废水中投加石灰生成氟化钙沉淀等。\n[3] 中和法\n中和处理法是利用化学酸碱中和消除水中过量的酸和碱。中和法\n主要用于处理酸性废水和碱性废水。对于酸性废水，可与碱性废水中\n和，“以废治废”，如电镀厂的酸性废水和印染厂的碱性废水相互混\n合，达到中和的目的；在酸性废水中还可以投加药剂，如石灰、苛性\n钠和碳酸钠等，酸性废水也可以通过碱性滤料过滤得到中和。碱性废\n水处理常用酸性废水中和，或者采用投酸中和(如 、HCl等)或\n与烟道气(含 、 )中和。\n[4]氧化还原法\n氧化还原法是通过化学药剂与废水中的污染物进行氧化还原反\n应或利用电解时的阳极反应，将废水中的有毒有害污染物转化为无毒\n或者低毒物质的方法，可分为药剂氧化法和药剂还原法两大类。在废\n水处理中常采用的氧化剂有：空气、 、 、 、漂白粉、NaCIO、\n等。例如，氰化物在pH值大于8.5的条件下用氯气进行氧化，可\n被氧化成无毒物质。常用的还原剂有 、 、铁屑、锌粉、\n等。药剂还原法主要用于处理含铬、含汞废水，通过还原可将 转\n化为 ，大大降低铬的毒性。\n三、物理化学处理方法\n物理化学处理方法即运用物理和化学的综合作用使废水得到净\n化的方法。它是由物理方法和化学方法组成的废水处理系统，或是包\n括物理过程和化学过程的单项处理方法，如浮选、吹脱、结晶、吸附\n、萃取、电解、电渗析、离子交换、反渗透等。常用于工业废水处理\n的物理化学法有离子交换法、萃取法、膜分离法和吸附法等。\n[1]离子交换法\n离子交换法是借助于离子交换剂中的可交换离子同废水中的离\n子进行交换而去除废水中有害离子的方法。离子交换剂有无机和有机\n质两类，前者如天然物质海绿砂或合成沸石，后者如磺化煤或树脂。\n随着离子交换树脂的生产和实用技术的发展，近年来在处理和回收工\n业废水中有毒物质方面效果良好，且操作方便。在使用树脂处理污水\n时必须考虑树脂的性质及选择性，即树脂对不同离子的交换能力是不\n同的。离子交换法可用来处理各种金属表面加工产生的废水，如含 Au\n、Ni、Cd、Cu的废水等。此外，从核反应器、医院和实验室废水中回\n收和去除放射性物质，也可采用离子交换法。\n[2] 萃取法\n萃取法是一种向废水中加入不溶于水或难溶于水的溶剂(萃取剂\n)，使溶解于废水中的污染物经过萃取剂和废水两液相间界面转入萃\n取剂中去，然后利用萃取剂和水的密度差，将污染物分离出来，以净\n化废水的方法。利用溶剂与溶质的沸点差，将溶质蒸馏回收，再生后\n的溶剂继续循环利用。萃取处理法一般用于处理浓度较高的含酚或含\n苯胺、苯、醋酸等工业废水。\n[3]膜分离法\n膜分离法是利用一种特殊的半透膜使溶液中的某些组分隔开，某\n些溶质和溶剂渗透而达到分离的目的。水处理中膜分离法通常可以分\n为电渗析、反渗透、超滤、微滤等。\n电渗析法是指在外加直流电场的作用下，利用阴离子交换膜和阳\n离子交换膜的选择透过性，使溶液中的部分离子透过离子交换膜而迁\n移到另一部分溶液中，达到浓缩、纯化、分离的目的。电渗析法最先\n用于海水淡化制取饮用水和工业用水，海水浓缩制取食盐，以及与其\n他单元技术组合制取高纯水。目前，电渗析法在废水处理实践中应用\n最普遍的有：处理碱法造纸废液，从浓液中回收碱；处理电镀废水和\n废液等。\n反渗透法是利用一种特殊的半透膜，在一定压力下促使水分子反\n向渗透，而溶解在水中的污染物被膜截留，污水被浓缩，而透过膜的\n水即为处理过的水。目前，该方法主要用于高纯度水的制备；化工工\n艺的浓缩、分离、提纯及配水制备；锅炉补给水除盐软水；海水、苦\n咸水淡化；造纸、电镀、印染、食品等行业用水及废水处理；城市污\n水深度处理。\n超滤法也是利用特殊半渗透膜的一种膜分离技术，以压力为推动\n力，使水溶液中的大分子物质与水分离，将溶液净化、分离或者浓缩\n。该方法常用于分离有机溶解物，如蛋白质、淀粉、树胶、油漆等。\n微滤也称微孔过滤，它属于精密过滤，截留溶液中的砂砾、淤泥\n、黏土等颗粒以及贾第虫、隐孢子虫、藻类和一些细菌等，而大量溶\n剂、小分子及大量大分子溶质都能透过膜的分离过程。\n三、生物处理法\n生物处理法是利用微生物的代谢作用，使水中溶解态或胶体态的\n有机物被降解并转化为无害物质，以去除废水中有机污染物的一种方\n法。根据参与反应的微生物的种类以及耗氧情况，生物处理法分为好\n氧生物处理法和厌氧生物处理法两大类。\n[1]好氧生物处理法\n好氧生物处理法是利用好氧微生物在有氧条件下将废水中复杂\n的有机物分解的方法。根据好氧微生物存在的处理系统所呈现的不同\n状态，好氧生物处理法可以分为活性污泥法、生物膜法、氧化塘法等\n①活性污泥法：是处理城市污水最广泛使用的方法。该法是在人\n工充氧条件下，对污水和各种微生物群体进行连续混合培养，形成活\n性污泥。利用活性污泥的生物凝聚、吸附和氧化作用，以分解去除污\n水中的有机污染物。然后使污泥与水分离，大部分污泥再回流到曝气\n池，多余部分则排出活性污泥系统。它能从污水中去除溶解性的和胶\n体状态的可生化有机物以及能被活性污泥吸附的悬浮固体和其他一\n些物质，同时也能去除一部分磷素和氮素。\n②生物膜法：是微生物附着在作为介质的滤料表面，生长成为一\n层由微生物构成的膜。污水流过滤料表面，溶解性有机污染物被生物\n膜吸附，进而被微生物氧化分解，转化为 、 、 和微生物细\n胞质，使污水得以净化。生物膜法通常无需曝气，微生物所需氧气直\n接来自大气。生物膜法常采用的构筑物有生物滤池、生物转盘、生物\n接触氧化池和生物流化床等。\n③氧化塘法：属于生物处理法中的自然生物处理范畴。氧化塘是\n利用藻类和细菌的共生系统来处理污水的一种方法。污水中存在着大\n量的好氧菌和耐污的藻类，污水中的有机物被细菌利用，分解成简单\n的含有氮、磷的物质，这些物质又为藻类的生长提供必要的营养物质\n，藻类白天利用阳光进行的光合作用，释放氧气，供细菌消耗和生长\n，这种相互共存的关系成为藻菌共生系统。氧化塘就是利用这一系统\n使污水得到净化。氧化塘便于因地制宜，基建投资少，运行维护方便\n，能耗较低，但占地面积过多，处理效果受气候影响较大。\n[2]厌氧生物处理法\n厌氧生物处理法是利用兼性厌氧菌和专性厌氧菌将污水中大分\n子有机物降解为低分子化合物，进而转化为CH4、 的有机污水处\n理方法。该方法中有机物转化分为三部分：一部分被氧化分解为简单\n无机物，一部分转化为甲烷，剩下少量有机物则被转化、合成为新的\n细胞物质。与好氧生物处理法相比，用于合成细胞物质的有机物较少\n，因而厌氧生物处理法的污泥增长率要小得多。\n厌氧生物处理法具有处理过程消耗的能量少、有机物的去除率高\n，沉淀的污泥少且易脱水、可杀死病原菌、不需投加氮、磷等营养物\n质等优点，近年来日益受到人们的关注。它不但可用于处理高浓度和\n中浓度的有机污水，还可以用于低浓度有机污水的处理。常见的处理\n工艺中的构筑物有厌氧接触池、厌氧生物滤池、厌氧流化床、厌氧膨\n胀床、上流式厌氧污泥床反应器和生物转盘等。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。","含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":66,"sourceRange":{"startPage":66,"startY":86.28,"endPage":73,"endY":220.11},"sourceKind":"original","originalOrdinal":"4","sourceMetadata":["重要程度："],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":3,"excerpts":[{"page":66,"src":"./assets/environment/env838-9ed9eea3d4d0b1f4-66.webp"},{"page":67,"src":"./assets/environment/env838-9ed9eea3d4d0b1f4-67.webp"},{"page":68,"src":"./assets/environment/env838-9ed9eea3d4d0b1f4-68.webp"},{"page":69,"src":"./assets/environment/env838-9ed9eea3d4d0b1f4-69.webp"},{"page":70,"src":"./assets/environment/env838-9ed9eea3d4d0b1f4-70.webp"},{"page":71,"src":"./assets/environment/env838-9ed9eea3d4d0b1f4-71.webp"},{"page":72,"src":"./assets/environment/env838-9ed9eea3d4d0b1f4-72.webp"},{"page":73,"src":"./assets/environment/env838-9ed9eea3d4d0b1f4-73.webp"}]},{"id":"env838-8453ab1cc2929890","subject":"环境学导论","chapter":"第3章 水环境","originalChapter":"第3章 水环境","originalChapterNumber":3,"section":"第4节 水污染控制","originalSection":"第4节 水污染控制","category":"knowledge","title":"污水处理的分级","question":"污水处理的分级","type":"简答题","answer":"污水处理一般来说包含三级处理：一级处理主要是通过机械处理\n，二级处理是生物处理，三级处理是污水的深度处理。\n一级处理指去除漂浮物及悬浮状态的污染物质，调节pH值，减轻\n污水的腐化程度和后处理工艺负荷的处理方法。一般作为污水处理的\n预处理手段。只有一级处理出水水质符合要求，才能保证二级生物处\n理运行平稳，进而确保二级出水水质达标。常见的一级处理设备有沉\n砂池、气浮池、隔油池等。\n二级处理，以去除不可沉悬浮物和溶解性可生物降解有机物为主\n要目的，工艺构成多种多样，可分成活性污泥法、AB法、A/O法、A²/O\n法、SBR法、氧化沟法、稳定塘法、土地处理法等多种处理方法。大\n多数城市污水处理厂都采用活性污泥法。\n三级处理即深度处理，是指废水经二级处理后，主要去除营养性\n污染物及其他溶解物质或者残留的细小悬浮物、难生物降解的有机物\n、盐分等。它将经过二级处理的水进行脱氮、脱磷处理，用活性炭吸\n附法或反渗透法等去除水中的剩余污染物，并用臭氧或氯消毒杀灭细\n菌和病毒，然后将处理水送入中水道，作为冲洗厕所、喷洒街道\n浇灌绿化带、工业用水、防火等水源。常用方法有过滤、膜处理、","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":73,"sourceRange":{"startPage":73,"startY":220.11,"endPage":74,"endY":72.67},"sourceKind":"original","originalOrdinal":"5","sourceMetadata":["【重要程度： 】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":3,"excerpts":[{"page":73,"src":"./assets/environment/env838-8453ab1cc2929890-73.webp"},{"page":74,"src":"./assets/environment/env838-8453ab1cc2929890-74.webp"}]},{"id":"env838-56302dd692767e3c","subject":"环境学导论","chapter":"第3章 水环境","originalChapter":"第3章 水环境","originalChapterNumber":3,"section":"第5节 课后习题","originalSection":"第5节 课后习题","category":"exercise","title":"什么是水循环?水循环的类型有哪些?","question":"什么是水循环?水循环的类型有哪些?","type":"简答题","answer":"整理答案（按教材对应知识点摘录）：\n\n水循环的定义和作用：\n在太阳入射能和地球表面热能的共同作用下，地表水不断被\n蒸发成为水蒸气，进入大气。水蒸气遇冷凝结成水或冰，在地球重\n力的作用下，以降水形式落至地表。水的这个周而复始的运动过程称\n为水循环。水循环是地球上最重要的物质循环之一，它不仅实现全球\n的水量转移，而且推动全球能量交换和生物地球化学循环，并为人类\n提供不断再生的淡水资源。\n水循环的主要作用表现在：水循环联系着地球的各个圈层，并在\n各个圈层间进行物质和能量交换，直接涉及自然界中一系列的物理\n、化学和生物过程。在垂直方向上，通过蒸发、降水、下渗、植物\n蒸腾等环节，把大气圈、水圈、生物圈、岩石圈联系起来；在水\n平方向上，通过水汽输送和径流输送，把陆地和海洋联系起来。\n图 3-1 水循环示意图\n\n社会水循环：\n水的社会循环指在水的自然循环中，人类不断利用地下径流或地\n表径流满足生活与生产活动之需，使用后又排回自然水体的人工循环\n。最典型的社会水循环莫过于城市用水。城市从自然水体中取水，净\n化后供给工业、商业、市政和居民使用，用后的污水经排水系统输送\n到污水处理厂，处理后又排回自然水体。\n水的社会循环系统可分为给水系统和排水系统两大部分，两者是\n不可分割的统一有机体。给水系统是自然水的提取、加工、供应和使\n用过程，好比是水社会循环的动脉，用后污水的收集、处理与排放这\n一排水系统则是水社会循环的静脉。在水的社会循环中，污水的收集\n与处理系统是能否维持水社会循环可持续性的关键，是连接水社会循\n环与自然循环的纽带。\n城市 4\n[待核对] | 供水 】 (4x J)\nSS 水体了\n图 3-2 社会水循环示意图","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["根据所列知识点摘录整理，未逐题人工审定。"],"verified":false,"page":74,"sourceRange":{"startPage":74,"startY":111.1,"endPage":74,"endY":188.35},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":3,"references":[{"id":"env838-47f05fef551d714a","title":"水循环的定义和作用","source":"环境学导论.pdf","page":53},{"id":"env838-c5caf851b9d0ae7b","title":"社会水循环","source":"环境学导论.pdf","page":54}],"excerpts":[{"page":74,"src":"./assets/environment/env838-56302dd692767e3c-74.webp"}]},{"id":"env838-4a2152bf1dd0f44d","subject":"环境学导论","chapter":"第3章 水环境","originalChapter":"第3章 水环境","originalChapterNumber":3,"section":"第5节 课后习题","originalSection":"第5节 课后习题","category":"exercise","title":"水中有哪些污染物?简要说明其危害。","question":"水中有哪些污染物?简要说明其危害。","type":"简答题","answer":"整理答案（按教材对应知识点摘录）：\n\n水污染物：\n学长提示 ; 这个知识点很重要 ， 可以作为一个整体考简答或者论述 ， 下面的各小类污\n染物尤其是需氧污染物 ， 出题频率很高 ， 可以考名词解释 、 简答\n造成水体水质、水中生物群落以及水体底泥质量恶化的各种有害\n物质(或能量)都可叫做水体污染物。常见的污染物种类如下。\n[1]固体污染物\n固体物质在水中有三种存在形态：溶解态、胶体态和悬浮态。主\n要来自于矿石处理、冶金、化工、化肥、造纸和食品加工等过程，还\n来自农田排水和水土流失等。\n悬浮物会使水体浑浊，影响水生植物的光合作用，而且水体中的\n悬浮物沉积淤塞河道，危害水体底栖生物的繁殖，影响渔业生产。灌\n溉时悬浮物会堵塞土壤的孔隙，不利于作物的生长。严重的是当水体\n中含有有毒物质时，会因悬浮物的吸附作用使污染程度加深。\n[2]耗氧有机物\n生活污水和印染、造纸、食品、餐饮、石化等工业废水中含有碳\n水化合物、蛋白质、氨基酸、脂肪酸、油脂等有机物和其他可被生物\n降解的人工合成有机物。这些物质本身无毒，但排入水体后在微生物\n作用下分解，会消耗水体大量的氧，使水中溶解氧降低，故称为耗氧\n有机物。\n学长提示 :; 书上的注释性文字可以帮助大家理解 : 在标准状况下 , 水中溶解气约 9mg/L\n。 溶解氧降至 4mg/L 以下时 ， 将严重影响鱼类和水生生物的生存 ; 溶解氧降低到 lmg/L\n时 ， 大部分鱼类会室息死亡 ; 溶解氧降至零时 ， 水中厌氧微生物占据优势 ， 有机物将\n进行厌氧分解 ， 产生 CH4s、H2S、NH4 和硫醇等难闻 、 有毒气体 ， 造成水体发黑发奥 ，\n影响甚至室息水中鱼类及其他水生生物 ， 还会影响城市供水及工农业用水 、 景观用水","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["根据所列知识点摘录整理，未逐题人工审定。"],"verified":false,"page":74,"sourceRange":{"startPage":74,"startY":188.35,"endPage":74,"endY":267.13},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":3,"references":[{"id":"env838-e48772c5cac35aff","title":"水污染物","source":"环境学导论.pdf","page":57}],"excerpts":[{"page":74,"src":"./assets/environment/env838-4a2152bf1dd0f44d-74.webp"}]},{"id":"env838-fa6577095cf60221","subject":"环境学导论","chapter":"第3章 水环境","originalChapter":"第3章 水环境","originalChapterNumber":3,"section":"第5节 课后习题","originalSection":"第5节 课后习题","category":"exercise","title":"我国江河湖库以及海洋污染的特点有哪些?","question":"我国江河湖库以及海洋污染的特点有哪些?","type":"简答题","answer":"①江河：污染具有流域性和上下游关联，城镇生活、工业与农业面源排放共同影响水质；不同区域和支流差异明显。\n②湖泊、水库：水交换较慢，氮磷等营养盐容易累积；在适宜条件下发生富营养化和藻类水华，并可能存在底泥内源释放。\n③海洋：污染压力多集中在河口、海湾和近岸海域，具有陆源输入、海水交换和沿岸开发共同作用的特点，可出现富营养化、赤潮及垃圾污染等。\n④治理：统筹水资源、水环境和水生态，联控点源、面源与内源污染，推进流域—河口—海湾协同治理。\n现状数据须标明年份。例如2024年全国地表水Ⅰ—Ⅲ类断面比例为90.4%，不宜概括为“全国水质持续恶化”。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":74,"sourceRange":{"startPage":74,"startY":267.13,"endPage":74,"endY":346.52},"sourceKind":"original","originalOrdinal":"3","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":3,"excerpts":[{"page":74,"src":"./assets/environment/env838-fa6577095cf60221-74.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=52"},{"title":"生态环境部：2024中国生态环境状况公报","url":"https://www.mee.gov.cn/ywgz/sthjjcgl/hjzljcypj/202506/t20250605_1120773.shtml","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-2c4033218e3f2016","subject":"环境学导论","chapter":"第3章 水环境","originalChapter":"第3章 水环境","originalChapterNumber":3,"section":"第5节 课后习题","originalSection":"第5节 课后习题","category":"exercise","title":"我国地下水污染的特点有哪些?","question":"我国地下水污染的特点有哪些?","type":"简答题","answer":"①隐蔽性：污染常在地下发生，难以凭感官及时发现。\n②滞后性和累积性：污染物渗入、迁移通常较慢，影响可能在多年后出现。\n③难恢复：地下水更新与稀释能力受含水层条件限制，一旦形成污染羽，治理周期长、成本高。\n④来源多样：工业场地、垃圾和危废不当处置、生活污水、农业施肥及矿业活动等均可能造成污染。\n⑤空间差异：水文地质条件决定污染物迁移路径与范围，局部还存在地质背景造成的水质问题，须与人为污染区分。\n防治上应保护补给区与水源地，防渗控源，开展分层监测和风险管控，避免单纯依靠末端抽水处理。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":74,"sourceRange":{"startPage":74,"startY":346.52,"endPage":74,"endY":425.85},"sourceKind":"original","originalOrdinal":"4","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":3,"excerpts":[{"page":74,"src":"./assets/environment/env838-2c4033218e3f2016-74.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=52"},{"title":"生态环境部：2024中国生态环境状况公报","url":"https://www.mee.gov.cn/ywgz/sthjjcgl/hjzljcypj/202506/t20250605_1120773.shtml","accessedOn":"2026-11-09"},{"title":"生态环境部：土壤污染风险管控与绿色低碳修复解读","url":"https://www.mee.gov.cn/ywdt/zbft/202405/t20240506_1072343.shtml","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-36a02b816f5b7f97","subject":"环境学导论","chapter":"第3章 水环境","originalChapter":"第3章 水环境","originalChapterNumber":3,"section":"第5节 课后习题","originalSection":"第5节 课后习题","category":"exercise","title":"简述水处理的“三级控制”模式。","question":"简述水处理的“三级控制”模式。","type":"简答题","answer":"按本资料“水处理模式／污水处理的分级”的上下文，三级模式指一级、二级和三级处理：\n①一级处理：以物理去除为主，利用格栅、沉砂、沉淀、隔油等去除漂浮物、砂粒和部分悬浮物，并进行必要调节。\n②二级处理：以生物处理为核心，去除可生物降解的溶解性及胶体有机物，常用活性污泥法、生物膜法等；按工艺需要结合脱氮除磷。\n③三级处理：在二级处理后进一步去除残余悬浮物、氮磷、难降解有机物或盐分等，采用过滤、吸附、膜分离、深度脱氮除磷及消毒等，以满足更严格排放或回用要求。\n三级不是每种污水都必须采用完全相同的设备串联，应按水质、标准和用途确定。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["题干使用“三级控制”，按本PDF和变动资料的“三级处理”解释；考试应核对命题语境。"],"verified":false,"page":74,"sourceRange":{"startPage":74,"startY":425.85,"endPage":74,"endY":505.23},"sourceKind":"original","originalOrdinal":"5","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":3,"excerpts":[{"page":74,"src":"./assets/environment/env838-36a02b816f5b7f97-74.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=52"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-2b7519483d7e2a46","subject":"环境学导论","chapter":"第3章 水环境","originalChapter":"第3章 水环境","originalChapterNumber":3,"section":"第5节 课后习题","originalSection":"第5节 课后习题","category":"exercise","title":"在污水处理过程中常用的控制技术有哪些?","question":"在污水处理过程中常用的控制技术有哪些?","type":"简答题","answer":"整理答案（按教材对应知识点摘录）：\n\n水污染控制技术：\n学长提示 : 本书新增了几个章节非常有趣 ， 一个是本章中的水污染控制技术 ， 一个是\n下一章中的大气污染控制技术 ， 还有一个是第六章的固废处理技术 ， 这些在何强版的\n节里面均不涉及 ， 单论知识点归属来说 ， 分别属于水污染控制工程 、 大气污染控制工\n程和轿体废物处理与处置 ， 这些也都是大家的初复试科目 ， 我猜测这也是为什么要更\n换参考书的原因 ， 考察的可能性还是比较大 ; 还有第五章土壤的组成和基本性质 ， 这\n一章基本上是全部照搬于环境化学中的内容 ， 所以在第五章 ， 我很多说法都沿用了环\n境化学中的说法 。\n知识点 4、5 的内容可以先不看 ， 在水控中都会再次出现 ， 且更详细 。\n废水的处理就是利用物理、化学、生物的方法对废水进行处理，\n使废水进行净化，减少污染，以达到排放、利用、回用的标准。废水\n处理技术按照其作用的原理可以分为物理处理法、化学处理法、物理\n化学处理法和生物处理法四大类。\n一、物理处理法\n物理处理法是通过物理作用分离水中不溶解的呈悬浮状态的污\n染物(包括油膜和油珠)的废水处理方法，常用的有筛滤截留法、重\n力分离法、气浮法以及离心分离法等。\n[1]筛滤截留法\n利用带孔眼的装置或由某种介质组成的滤层截留废水中悬浮固\n体的方法，这种方法使用的设备有以下几种。\n①格栅：由一排平行的金属栅条做成的金属框架，斜置在废水流\n过的渠道上，用以截阻大块的固体物；\n②筛网：用以截阻、去除水中的纤维、纸浆等较细小的悬浮物。\n筛网一般用薄铁皮钻孔制成，或用金属丝编成，孔眼直径为0.5~\n1.0mm。筛网有转鼓式、圆盘式和帘带式等。\n③布滤设备：以帆布、尼龙布或毛毡为过滤介质，用以截阻、去\n除水中的细小悬浮物，也用于污泥脱水。常用的布滤设备为真空转筒\n滤机。\n④砂滤设备：以石英砂为滤料，用以过滤截留微细的悬浮物，一\n般作为保证后续处理单元稳定运行的装置。\n[2]重力分离( 即沉淀) 法\n重力分离法是利用水中悬浮的污染物和水的密度差的原理，通过\n重力作用使悬浮物质沉淀或上浮，从而净化废水的一种废水处理方法\n。常见的处理设备有沉砂池、沉淀池和隔油池。\n在污水的处理与再利用过程中，沉淀或上浮一般常被作为其他处\n理的预处理。在生物处理设备前设初次沉淀池，去除大部分的悬浮物\n，以减轻后继处理设备的负荷，保证生物处理设备净化功能的正常发\n挥。而且，在生物处理设备后设二次沉淀池，用以分离生物污泥，使\n处理水得到澄清，保证出水水质。\n[3] 气浮法\n气浮法是一种有效的固液和液液分离方法，常用于那些颗粒密度\n接近或小于水的细小颗粒分离。气浮法处理技术是在水中形成微小气\n泡形式，使微小气泡与悬浮颗粒黏附，形成水—气—颗粒三相混合体\n系，颗粒黏附上气泡后，形成表观密度小于水的漂浮絮体，絮体上浮\n至水面，形成浮渣层被刮除，实现固液分离。为了提高处理效果，有\n时需要向废水中投加混凝剂。\n[4]离心分离法\n离心分离法是利用装有废水的容器高速旋转形成的离心力，悬浮\n颗粒因和废水受到的离心力大小不同而被分离的方法。按离心力产生\n的方式，可分为水旋分离器和离心机两种类型。在分离过程中，悬浮\n颗粒质量按由小到大分布，受到离心力的作用被分离后，按由外到内\n分布，通过不同的液体排出口，使悬浮颗粒从废水中分离出来。\n二、化学处理方法\n化学处理法是通过化学反应和传质作用来分离、去除水中呈溶解\n、胶体状态的污染物或将其转化为无害物质的废水处理法。常用的化\n学处理方法有混凝法、化学沉淀法、中和法、氧化还原法(包括电解\n) 等。\n[1] 混凝法\n混凝处理法是通过向废水中投加混凝剂，使水中的胶体和颗粒失\n去稳定性，发生凝聚和絮凝而分离出来，以净化废水的方法。混凝法\n主要是处理废水中微小的悬浮物和胶体。常用的混凝剂有\n3、碱式氯化铝、铁盐[主要指 3、 ,FeCl ₃]等。混凝法\n可以降低废水的色度和浊度，大幅度提高有机污染物的去除效率，同\n时还能取得较好的除磷效果，改善污泥的脱水性能。\n[2]化学沉淀法\n化学沉淀法是向废水中投加某些化学物质，使它和废水中欲去除\n的污染物发生直接的化学反应，生成难溶于水的沉淀物而使污染物分\n离除去的方法。化学沉淀法经常用于处理含有 Hg、Pb、Cu、Zn、\n、S、CN-、F、As等有毒化合物的废水。向废水中投加氢氧化物、硫\n化物、碳酸盐等生成金属盐沉淀，向废水中投加钡盐生成铬酸盐沉淀\n处理含六价铬的工业废水，向废水中投加石灰生成氟化钙沉淀等。\n[3] 中和法\n中和处理法是利用化学酸碱中和消除水中过量的酸和碱。中和法\n主要用于处理酸性废水和碱性废水。对于酸性废水，可与碱性废水中\n和，“以废治废”，如电镀厂的酸性废水和印染厂的碱性废水相互混\n合，达到中和的目的；在酸性废水中还可以投加药剂，如石灰、苛性\n钠和碳酸钠等，酸性废水也可以通过碱性滤料过滤得到中和。碱性废\n水处理常用酸性废水中和，或者采用投酸中和(如 、HCl等)或\n与烟道气(含 、 )中和。\n[4]氧化还原法\n氧化还原法是通过化学药剂与废水中的污染物进行氧化还原反\n应或利用电解时的阳极反应，将废水中的有毒有害污染物转化为无毒\n或者低毒物质的方法，可分为药剂氧化法和药剂还原法两大类。在废\n水处理中常采用的氧化剂有：空气、 、 、 、漂白粉、NaCIO、\n等。例如，氰化物在pH值大于8.5的条件下用氯气进行氧化，可\n被氧化成无毒物质。常用的还原剂有 、 、铁屑、锌粉、\n等。药剂还原法主要用于处理含铬、含汞废水，通过还原可将 转\n化为 ，大大降低铬的毒性。\n三、物理化学处理方法\n物理化学处理方法即运用物理和化学的综合作用使废水得到净\n化的方法。它是由物理方法和化学方法组成的废水处理系统，或是包\n括物理过程和化学过程的单项处理方法，如浮选、吹脱、结晶、吸附\n、萃取、电解、电渗析、离子交换、反渗透等。常用于工业废水处理\n的物理化学法有离子交换法、萃取法、膜分离法和吸附法等。\n[1]离子交换法\n离子交换法是借助于离子交换剂中的可交换离子同废水中的离\n子进行交换而去除废水中有害离子的方法。离子交换剂有无机和有机\n质两类，前者如天然物质海绿砂或合成沸石，后者如磺化煤或树脂。\n随着离子交换树脂的生产和实用技术的发展，近年来在处理和回收工\n业废水中有毒物质方面效果良好，且操作方便。在使用树脂处理污水\n时必须考虑树脂的性质及选择性，即树脂对不同离子的交换能力是不\n同的。离子交换法可用来处理各种金属表面加工产生的废水，如含 Au\n、Ni、Cd、Cu的废水等。此外，从核反应器、医院和实验室废水中回\n收和去除放射性物质，也可采用离子交换法。\n[2] 萃取法\n萃取法是一种向废水中加入不溶于水或难溶于水的溶剂(萃取剂\n)，使溶解于废水中的污染物经过萃取剂和废水两液相间界面转入萃\n取剂中去，然后利用萃取剂和水的密度差，将污染物分离出来，以净\n化废水的方法。利用溶剂与溶质的沸点差，将溶质蒸馏回收，再生后\n的溶剂继续循环利用。萃取处理法一般用于处理浓度较高的含酚或含\n苯胺、苯、醋酸等工业废水。\n[3]膜分离法\n膜分离法是利用一种特殊的半透膜使溶液中的某些组分隔开，某\n些溶质和溶剂渗透而达到分离的目的。水处理中膜分离法通常可以分\n为电渗析、反渗透、超滤、微滤等。\n电渗析法是指在外加直流电场的作用下，利用阴离子交换膜和阳\n离子交换膜的选择透过性，使溶液中的部分离子透过离子交换膜而迁\n移到另一部分溶液中，达到浓缩、纯化、分离的目的。电渗析法最先\n用于海水淡化制取饮用水和工业用水，海水浓缩制取食盐，以及与其\n他单元技术组合制取高纯水。目前，电渗析法在废水处理实践中应用\n最普遍的有：处理碱法造纸废液，从浓液中回收碱；处理电镀废水和\n废液等。\n反渗透法是利用一种特殊的半透膜，在一定压力下促使水分子反\n向渗透，而溶解在水中的污染物被膜截留，污水被浓缩，而透过膜的\n水即为处理过的水。目前，该方法主要用于高纯度水的制备；化工工\n艺的浓缩、分离、提纯及配水制备；锅炉补给水除盐软水；海水、苦\n咸水淡化；造纸、电镀、印染、食品等行业用水及废水处理；城市污\n水深度处理。\n超滤法也是利用特殊半渗透膜的一种膜分离技术，以压力为推动\n力，使水溶液中的大分子物质与水分离，将溶液净化、分离或者浓缩\n。该方法常用于分离有机溶解物，如蛋白质、淀粉、树胶、油漆等。\n微滤也称微孔过滤，它属于精密过滤，截留溶液中的砂砾、淤泥\n、黏土等颗粒以及贾第虫、隐孢子虫、藻类和一些细菌等，而大量溶\n剂、小分子及大量大分子溶质都能透过膜的分离过程。\n三、生物处理法\n生物处理法是利用微生物的代谢作用，使水中溶解态或胶体态的\n有机物被降解并转化为无害物质，以去除废水中有机污染物的一种方\n法。根据参与反应的微生物的种类以及耗氧情况，生物处理法分为好\n氧生物处理法和厌氧生物处理法两大类。\n[1]好氧生物处理法\n好氧生物处理法是利用好氧微生物在有氧条件下将废水中复杂\n的有机物分解的方法。根据好氧微生物存在的处理系统所呈现的不同\n状态，好氧生物处理法可以分为活性污泥法、生物膜法、氧化塘法等\n①活性污泥法：是处理城市污水最广泛使用的方法。该法是在人\n工充氧条件下，对污水和各种微生物群体进行连续混合培养，形成活\n性污泥。利用活性污泥的生物凝聚、吸附和氧化作用，以分解去除污\n水中的有机污染物。然后使污泥与水分离，大部分污泥再回流到曝气\n池，多余部分则排出活性污泥系统。它能从污水中去除溶解性的和胶\n体状态的可生化有机物以及能被活性污泥吸附的悬浮固体和其他一\n些物质，同时也能去除一部分磷素和氮素。\n②生物膜法：是微生物附着在作为介质的滤料表面，生长成为一\n层由微生物构成的膜。污水流过滤料表面，溶解性有机污染物被生物\n膜吸附，进而被微生物氧化分解，转化为 、 、 和微生物细\n胞质，使污水得以净化。生物膜法通常无需曝气，微生物所需氧气直\n接来自大气。生物膜法常采用的构筑物有生物滤池、生物转盘、生物\n接触氧化池和生物流化床等。\n③氧化塘法：属于生物处理法中的自然生物处理范畴。氧化塘是\n利用藻类和细菌的共生系统来处理污水的一种方法。污水中存在着大\n量的好氧菌和耐污的藻类，污水中的有机物被细菌利用，分解成简单\n的含有氮、磷的物质，这些物质又为藻类的生长提供必要的营养物质\n，藻类白天利用阳光进行的光合作用，释放氧气，供细菌消耗和生长\n，这种相互共存的关系成为藻菌共生系统。氧化塘就是利用这一系统\n使污水得到净化。氧化塘便于因地制宜，基建投资少，运行维护方便\n，能耗较低，但占地面积过多，处理效果受气候影响较大。\n[2]厌氧生物处理法\n厌氧生物处理法是利用兼性厌氧菌和专性厌氧菌将污水中大分\n子有机物降解为低分子化合物，进而转化为CH4、 的有机污水处\n理方法。该方法中有机物转化分为三部分：一部分被氧化分解为简单\n无机物，一部分转化为甲烷，剩下少量有机物则被转化、合成为新的\n细胞物质。与好氧生物处理法相比，用于合成细胞物质的有机物较少\n，因而厌氧生物处理法的污泥增长率要小得多。\n厌氧生物处理法具有处理过程消耗的能量少、有机物的去除率高\n，沉淀的污泥少且易脱水、可杀死病原菌、不需投加氮、磷等营养物\n质等优点，近年来日益受到人们的关注。它不但可用于处理高浓度和\n中浓度的有机污水，还可以用于低浓度有机污水的处理。常见的处理\n工艺中的构筑物有厌氧接触池、厌氧生物滤池、厌氧流化床、厌氧膨\n胀床、上流式厌氧污泥床反应器和生物转盘等。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["根据所列知识点摘录整理，未逐题人工审定。"],"verified":false,"page":74,"sourceRange":{"startPage":74,"startY":505.23,"endPage":75,"endY":73.4},"sourceKind":"original","originalOrdinal":"6","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":3,"references":[{"id":"env838-9ed9eea3d4d0b1f4","title":"水污染控制技术","source":"环境学导论.pdf","page":66}],"excerpts":[{"page":74,"src":"./assets/environment/env838-2b7519483d7e2a46-74.webp"},{"page":75,"src":"./assets/environment/env838-2b7519483d7e2a46-75.webp"}]},{"id":"env838-d212eec9d13e6866","subject":"环境学导论","chapter":"第3章 水环境","originalChapter":"第3章 水环境","originalChapterNumber":3,"section":"第4节","originalSection":"第4节","category":"supplement","title":"水环境标准","question":"水环境标准","type":"简答题","answer":"水环境标准体系是对水环境标准工作全面规划，统筹协调相互关系，明确其\n作用、功能、适用范围而逐步形成的一个完整的管理体系。我国的水环境标准体\n系可概括为“五类三级”，“五类”指水环境质量标准、水污染物排放标准、水环\n境基础标准、水监测分析标准和水环境标准品标准五类， “三级”指国家级标准、\n行业级标准和地方级标准三级。","source":"环导变动137718728584015123.1eae00877280d3e.pdf","sourceUrl":"https://drive.google.com/file/d/11CjvWmrS4poAVMmBBWnsJPRCmD1-JkRJ/view","version":"new","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":3,"sourceRange":{"startPage":3,"startY":213.01,"endPage":3,"endY":391.0},"sourceKind":"changes","originalOrdinal":"1","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":3,"excerpts":[{"page":3,"src":"./assets/environment/env838-d212eec9d13e6866-3.webp"}]},{"id":"env838-5fcb4047662a19ef","subject":"环境学导论","chapter":"第3章 水环境","originalChapter":"第3章 水环境","originalChapterNumber":3,"section":"第4节","originalSection":"第4节","category":"supplement","title":"水处理模式","question":"水处理模式","type":"简答题","answer":"即水控中的“三级处理”，这里不再赘述","source":"环导变动137718728584015123.1eae00877280d3e.pdf","sourceUrl":"https://drive.google.com/file/d/11CjvWmrS4poAVMmBBWnsJPRCmD1-JkRJ/view","version":"new","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":3,"sourceRange":{"startPage":3,"startY":391.0,"endPage":3,"endY":481.02},"sourceKind":"changes","originalOrdinal":"2","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":3,"excerpts":[{"page":3,"src":"./assets/environment/env838-5fcb4047662a19ef-3.webp"}]},{"id":"env838-82d6d9a9b7883579","subject":"环境学导论","chapter":"第3章 水环境","originalChapter":"第3章 水环境","originalChapterNumber":3,"section":"第4节","originalSection":"第4节","category":"supplement","title":"水体污染的源头控制","question":"水体污染的源头控制","type":"简答题","answer":"源头控制的实质是污染预防，预防比通过“末端治理”解决水污染问题更加\n经济有效。对于农村面源、城市径流及大气沉降等并非来自单一、可确定污染源\n的污染，“末端治理”法并不适用，因此，加强水污染预防尤为重要。\n生活污水污染控制主要包括合理规划和宣传教育。生活污水具有源头分散、\n发生不均匀的特点，难以从源头上逐一治理。通过合理规划居民小区，使分散人\n口适度集中，有利于污水的集中治理与控制。同时，应加强“绿色生活”宣传教\n育，增强公众环保意识，养成节约用水的习惯，减少家庭水污染物排放，降低城\n市污水处理负担。\n工业废水污染控制主要包括优化结构与合理布局、清洁生产、就地处理以及\n政策鼓励和法律严控。通过产业规划优化产业结构、明确产业导向，限制高能耗、\n高水污染行业发展，并引导工业企业向工业区集中，为工业水污染集中控制创造\n条件。清洁生产是采用避免或最大限度减少污染物产生的工艺流程、方法、材料\n和能源，将污染物尽可能消除在生产过程中，从根本上减少污染物排放。\n工业废水成分复杂，应采取工业污染源就地处理或工业废水联合预处理，使\n其达到污水处理厂的接管标准，并对工业污泥中的有益物质进行回收利用。同时，\n应完善工业废水排放标准和相关控制法规，建立积极的刺激与激励机制，通过产\n品收费、税收、排污交易和公众参与等方式，促进企业提高资源利用效率。\n农村农业面源污染种类繁多、布局分散，控制的首要任务是控源。主要措施\n包括发展节水农业，降低农业用水量和农田排水量；减少土壤侵蚀，通过改善耕\n作方式、科学施肥、增施有机肥和实行作物轮作等，减少水土流失；合理利用农\n药，推广病虫害综合管理制度，结合物理、栽培和生物防治技术，合理使用高效、\n低毒、低残留农药，减少农药施用量。\n农村面源污染控制还应重视截流农业污水、处理畜禽粪污和建设集中处理设\n施。通过恢复水塘、生态沟、天然湿地及前置库等，截留农业径流，并在径流进\n入河道前拦截、沉淀和去除污染物；加强畜禽粪尿的综合处理与利用，发展有机\n肥和沼气等利用方式；合理规划乡镇企业布局，建设集约化污水处理设施，提高\n污染集中治理能力。\n城市径流污染控制主要包括雨水收集利用、减少硬质地面和增加绿化用地。\n通过雨水收集桶、收集池等设施，将雨水用于道路浇洒、绿化或补充地下水；采\n用多孔、透水表面替代水泥和沥青地面，促进雨水下渗，减少径流量并去除部分\n污染物；增加公园、绿地等绿化用地，利用植被和土壤吸收、过滤雨水，减轻城\n市径流污染。","source":"环导变动137718728584015123.1eae00877280d3e.pdf","sourceUrl":"https://drive.google.com/file/d/11CjvWmrS4poAVMmBBWnsJPRCmD1-JkRJ/view","version":"new","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":3,"sourceRange":{"startPage":3,"startY":481.02,"endPage":4,"endY":611.01},"sourceKind":"changes","originalOrdinal":"3","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":3,"excerpts":[{"page":3,"src":"./assets/environment/env838-82d6d9a9b7883579-3.webp"},{"page":4,"src":"./assets/environment/env838-82d6d9a9b7883579-4.webp"}]},{"id":"env838-2d70d3d76da2f7cb","subject":"环境学导论","chapter":"第4章 大气环境","originalChapter":"第4章 大气环境","originalChapterNumber":4,"section":"第1节 大气的组成与大气圈的结构","originalSection":"第1节 大气的组成与大气圈的结构","category":"knowledge","title":"空气和大气的区别与联系","question":"空气和大气的区别与联系","type":"简答题","answer":"在自然科学中、大气和空气两词并没有实质性的差别。在环境科\n学中，习惯上空气是指室内或者特指某个地方(如车间、厂区等)供\n生物生存的气体。大气一词常用在大气物理、气象和自然地理的研究\n中，以区域或全球性的气流作为研究对象。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":1,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":76,"sourceRange":{"startPage":76,"startY":111.75,"endPage":76,"endY":300.11},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":["【重要程度:★☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":4,"excerpts":[{"page":76,"src":"./assets/environment/env838-2d70d3d76da2f7cb-76.webp"}]},{"id":"env838-f6cb32cc86f1505c","subject":"环境学导论","chapter":"第4章 大气环境","originalChapter":"第4章 大气环境","originalChapterNumber":4,"section":"第1节 大气的组成与大气圈的结构","originalSection":"第1节 大气的组成与大气圈的结构","category":"knowledge","title":"大气的组成","question":"大气的组成","type":"简答题","answer":"大气或空气是多种气体的混合物，就其组成可以分为恒定的、可\n变的和不定的三种组分。\n(1)恒定组分：是指氮、氧、氩及微量的氦、氖、氩、氪、氙、\n氡等稀有气体。\n(2)可变组分：是指空气中的二氧化碳和水蒸气。\n(3)不定组分：主要是指尘埃、悬浮物、硫氧化物、氮氧化物等\n污染物质，主要来自人类生产生活不合理的排放。\n含有恒定组分和可变组分的空气，我们认为是清洁纯净的空气。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2004,2005,2010],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":76,"sourceRange":{"startPage":76,"startY":300.11,"endPage":76,"endY":604.83},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":["2004(选、2005(选、2010(选, 【重要程度:"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":4,"excerpts":[{"page":76,"src":"./assets/environment/env838-f6cb32cc86f1505c-76.webp"}]},{"id":"env838-a5265536dfbd4270","subject":"环境学导论","chapter":"第4章 大气环境","originalChapter":"第4章 大气环境","originalChapterNumber":4,"section":"第1节 大气的组成与大气圈的结构","originalSection":"第1节 大气的组成与大气圈的结构","category":"knowledge","title":"大气中不定组分的来源","question":"大气中不定组分的来源","type":"简答题","answer":"大气中组分含量变化的不定组成气体主要有两个来源：一是自然\n过程所带来的，如火山爆发、海啸、森林火灾、地震等，由此产生的\n污染物有尘埃、 、 、 、盐类、恶臭气体等，当这些组分进\n入大气中之后，会造成局部和暂时性的污染；二是由人类活动过程带\n来的，随着经济的发展、人口的增长和城市的扩张，大量工业生产排\n出的废气，汽车尾气等气体，使大气中增加了许多不确定组分，如煤\n烟、尘、 、 等。空气中的不定组分主要来自于人类活动，即人\n类活动是造成大气污染的主要原因。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":1,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":76,"sourceRange":{"startPage":76,"startY":604.83,"endPage":77,"endY":226.37},"sourceKind":"original","originalOrdinal":"3","sourceMetadata":["【重要程度: ★☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":4,"excerpts":[{"page":76,"src":"./assets/environment/env838-a5265536dfbd4270-76.webp"},{"page":77,"src":"./assets/environment/env838-a5265536dfbd4270-77.webp"}]},{"id":"env838-aa04eac996a181fd","subject":"环境学导论","chapter":"第4章 大气环境","originalChapter":"第4章 大气环境","originalChapterNumber":4,"section":"第1节 大气的组成与大气圈的结构","originalSection":"第1节 大气的组成与大气圈的结构","category":"knowledge","title":"大气层的结构","question":"大气层的结构","type":"简答题","answer":"大气层分为均质层和非均质层\n均质层：从地球表面以上大约到90km的高度。大气主要成分氮和\n氧的组成比例几乎没有什么变化。\n非均质层：均质层以上和外层空间的大气层。其气体组成随高度\n的增加而有很大的变化。\n在均质层中，根据气体的温度沿地球表面垂直方向的变化，该层\n又分为对流层、平流层、中间层。该层包括电离层和散逸层。\n[待核对] N2,03,0'.0 、\n[待核对] 热层 (电离层 ) NO\".O;.e\n中问层质\n[待核对] N2.02,03,NO°\n高度 km\n160 200 240 280 320\n[待核对] 温度 AK\n图 4-1 大气结构示意图\n①对流层的特点：对流层最接近地表，直接与水圈和岩石圈靠近\n，因此受地形和生物的影响较大。该层集中了整个大气圈质量的80%-\n95%，其厚度平均为12km，是大气圈中最低的一层，其温度随着高度\n的增加而下降。此外，对流层内空气对流显著，天气现象复杂多变，\n对人类的影响较大。引起对流的原因是由于岩石圈和水圈的表面被太\n阳晒热，而热辐射将下层空气烤热，冷、热空气发生垂直混合的对流\n现象。同时，空气与水圈和岩石圈接触的另一内容，是导致水蒸汽和\n尘埃、微生物等固态物质进入空气层，成为扬尘飞沙的来源。水汽形\n成雨、雪、露、雹等气象。\n②平流层的特点：平流层位于对流层上面，厚度约为38km，其温\n度随高度的增加而上升，并且经常保持稳定。平流层内气流稳定，很\n少有复杂的天气现象，飞机一般在此高度飞行；\n③中间层的特点：平流层以上的大气层，厚度约为35km，温度随\n高度增加而下降，几乎没有水蒸汽和尘埃，因而一般气流稳定，大气\n透明度好，极少有狂风暴雨等现象；\n④电离层的特点；电离层即热层，其中的原子氧吸收太阳能而使\n温度急剧上升，而且有一个带电粒子的稠密带，它能使无线电波反射\n回地面，这对远距离通信极为重要，本层厚度约为630km;\n⑤散逸层的特点：热层上面即外大气层，这里气体极为稀薄，以\n致一个气体质点被碰撞出这一层就很难被上层的气体质点再碰撞回\n来，而进入星际空间了，故此层又被称为散逸层，厚度约为15000-\n24000km.","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2003,2008,2010],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。","含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":77,"sourceRange":{"startPage":77,"startY":226.37,"endPage":79,"endY":387.27},"sourceKind":"original","originalOrdinal":"4","sourceMetadata":["2008 (简, 2010 (简---对流层特点, 2003、2010 (简--平流层特点, 【重要程度:"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":4,"excerpts":[{"page":77,"src":"./assets/environment/env838-aa04eac996a181fd-77.webp"},{"page":78,"src":"./assets/environment/env838-aa04eac996a181fd-78.webp"},{"page":79,"src":"./assets/environment/env838-aa04eac996a181fd-79.webp"}]},{"id":"env838-959bb791fa09e620","subject":"环境学导论","chapter":"第4章 大气环境","originalChapter":"第4章 大气环境","originalChapterNumber":4,"section":"第2节 大气污染及其危害","originalSection":"第2节 大气污染及其危害","category":"knowledge","title":"大气污染的概念","question":"大气污染的概念","type":"简答题","answer":"自然界中局部的质能变化和人类的生产和生活活动，改变大气圈\n中某些原有成分，以致使大气质量恶化，影响原来有利的生态平衡体\n系，严重威胁着人们的健康和正常的工农业生产，以及对建筑物和设\n备财产等构成损害即为大气污染。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":2,"pastExamYears":[2003],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":79,"sourceRange":{"startPage":79,"startY":430.95,"endPage":79,"endY":660.84},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":["2003( 填, 【重要程度: ★★☆☆☆"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":4,"excerpts":[{"page":79,"src":"./assets/environment/env838-959bb791fa09e620-79.webp"}]},{"id":"env838-00d48fee1e5543de","subject":"环境学导论","chapter":"第4章 大气环境","originalChapter":"第4章 大气环境","originalChapterNumber":4,"section":"第2节 大气污染及其危害","originalSection":"第2节 大气污染及其危害","category":"knowledge","title":"大气污染物的种类","question":"大气污染物的种类","type":"简答题","answer":"大气污染物，按属性一般分为物理性(如噪声、电离辐射、电磁\n辐射等)、化学性和生物性三类。其中，化学性污染物种类最多、污\n染范围最广。按存在状态，大气污染物可概括为两大类：颗粒污染物\n和气态污染物。\n(1 ) 颗粒污染物\n在大气污染中，颗粒污染物指沉降速度可以忽略的固体粒子、液\n体粒子或它们在气体介质中的悬浮体系。从大气污染控制的角度，按\n照其来源和物理性质，可分为粉尘、烟、飞灰、黑烟和雾。\n粉尘是指在一段时间内悬浮于气体介质中的小固体颗粒，但在重\n力作用下会发生沉降。它通常是在固体物质的破碎、研磨、分级、输\n送等机械过程，或土壤、岩石的风化等自然过程中形成的。其尺寸范\n围一般为1~200 μm。属于粉尘类的大气污染物的种类很多，如黏土粉\n尘、石英粉尘、煤粉、水泥粉尘、各种金属粉尘等。\n烟一般指由冶金过程形成的固体颗粒的气溶胶。它是熔融物质挥\n发后生成的气态物质的冷凝物，在生成过程中总是伴有氧化反应。烟\n颗粒的尺寸很小，一般为0.01~lum。产生烟是一种较为普遍的现象，\n如有色金属冶炼过程中产生的氧化铅烟、氧化锌烟等。\n飞灰指随燃料燃烧产生的烟气排出的分散较细的灰分。\n黑烟一般指由燃料燃烧产生的能见气溶胶，不包括水蒸气。黑烟\n的粒度范围为0.05~ 1 μm.\n雾是气体中液滴悬浮体的总称。在气象中指造成能见度小于1km\n的小水滴悬浮体。在工程中，雾一般泛指小液体粒子悬浮体，它可能\n是由于液体蒸汽的凝结、液体的雾化及化学反应等过程形成的，如水\n雾、酸雾、碱雾、油雾等。\n(2) 气态污染物\n硫氧化物主要指 ，它主要来自化石燃料的燃烧过程，以及硫\n化物矿石的焙烧、冶炼等过程。火力发电厂、有色金属冶炼厂、硫酸\n厂、炼油厂以及所有烧煤或油的工业炉窑等都排放 烟气。\nNOx有 ,NO, 、 、 和 ，用NOx表示，其中\n污染大气的主要是NO和 e\n含碳化合物包括碳氧化物和有机化合物。碳氧化物中的CO和\n是大气污染物中产生量最大的一类污染物，主要来自燃料燃烧和机动\n车尾气；有机化合物种类很多，包括从甲烷到长链聚合物的烃类。\n硫酸烟雾是大气中的 等硫氧化物，在水雾、含有重金属的悬\n浮颗粒物或 存在时，发生一系列化学或光化学反应而产生的硫酸\n雾或硫酸盐气溶胶。硫酸烟雾引起的刺激作用和生理反应等危害，要\n比 气体大得多。\n光化学烟雾是在阳光照射下，大气中的NO、碳氢化合物和氧化\n剂之间发生一系列光化学反应产生的蓝色烟雾(有时带些紫色和黄褐\n色)，主要成分有臭氧、过氧乙酰硝酸酯、酮类和醛类等。光化学烟\n雾的刺激性和危害要比一次污染物强烈得多。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2025],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":79,"sourceRange":{"startPage":79,"startY":660.84,"endPage":82,"endY":76.13},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":["2025(名—颗粒污染物)【重要程度: ★★☆"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":4,"excerpts":[{"page":79,"src":"./assets/environment/env838-00d48fee1e5543de-79.webp"},{"page":80,"src":"./assets/environment/env838-00d48fee1e5543de-80.webp"},{"page":81,"src":"./assets/environment/env838-00d48fee1e5543de-81.webp"},{"page":82,"src":"./assets/environment/env838-00d48fee1e5543de-82.webp"}]},{"id":"env838-63b6584de508f35c","subject":"环境学导论","chapter":"第4章 大气环境","originalChapter":"第4章 大气环境","originalChapterNumber":4,"section":"第2节 大气污染及其危害","originalSection":"第2节 大气污染及其危害","category":"knowledge","title":"一次污染物 、 二次污染物的定义","question":"一次污染物 、 二次污染物的定义","type":"简答题","answer":"2004〔〈 名一一次 、2002 (HM. 2005 (4—— UM. 2008 (名一二次 、201T《〈 判 、2016 (和名\n[待核对] —=k, [BEBE took)\n[待核对] KF RM RAMS RIG RE Do GRAOA— HMR, MA, HA\n、 碳氨化合物 、 颗粒物等 。\n一次污染物又可分为\n人 @ 反应性污染物 ， 性质不稳定 ， 在大气中常与某些其他物质发生化学反应 ， 或作为供\n化剂促进其他污染物产生化学反应 ;\n@ 非反应性污染物 ， 性质稳定 ， 它不发生化学反应 ， 或反应速度很缓慢 。\n二次污染物是指由一次污染物在大气中互相作用经化学反应或光化学反应形成的 ， 与\n一次污染物物理 、 化学性质完全不同的新的大气污染物 。 常见的二次污染物有奥乞 、\n过和气乙酰硝酸醋 、 硫酸及硫酸盐气溶胶 、 硝酸及而酸盐气溶胶 ， 以及一些活性中间产\n物 ， 如过氧产基 、 关基和活性氧原子等 。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。"],"verified":false,"page":82,"sourceRange":{"startPage":82,"startY":76.13,"endPage":82,"endY":379.98},"sourceKind":"original","originalOrdinal":"supp-1","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":4,"excerpts":[{"page":82,"src":"./assets/environment/env838-63b6584de508f35c-82.webp"}]},{"id":"env838-88220d7250448915","subject":"环境学导论","chapter":"第4章 大气环境","originalChapter":"第4章 大气环境","originalChapterNumber":4,"section":"第2节 大气污染及其危害","originalSection":"第2节 大气污染及其危害","category":"knowledge","title":"大气污染源分类","question":"大气污染源分类","type":"简答题","answer":"一、按污染源的存在的形式划分\n①固定污染源\n②移动污染源\n二、按污染物排放的方式划分\n①高架源，污染物通过高烟囱排放\n②面源，许多低烟囱集合起来而构成一个区域性的污染源\n③线源，移动污染源在一定街道上造成的污染\n三、按污染物排放的时间划分\n①连续源，污染物连续排放\n②间断源，排放源时断时续\n③瞬间源，排放时间很短\n四、按污染物产生的类型划分\n①工业污染源，这里包括燃料燃烧排放的污染物，生产过程中的\n排气以及生产过程中排放的各类矿物和金属粉尘。\n②家庭炉灶排气，在我国这是一种排放量大、分布广、排放高度\n低、危险性不容忽视的空气污染源。\n③汽车排气。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":82,"sourceRange":{"startPage":82,"startY":379.98,"endPage":83,"endY":245.74},"sourceKind":"original","originalOrdinal":"3","sourceMetadata":["【重要程度："],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":4,"excerpts":[{"page":82,"src":"./assets/environment/env838-88220d7250448915-82.webp"},{"page":83,"src":"./assets/environment/env838-88220d7250448915-83.webp"}]},{"id":"env838-4b64f180ce5e7254","subject":"环境学导论","chapter":"第4章 大气环境","originalChapter":"第4章 大气环境","originalChapterNumber":4,"section":"第2节 大气污染及其危害","originalSection":"第2节 大气污染及其危害","category":"knowledge","title":"大气污染物各论","question":"大气污染物各论","type":"简答题","answer":"一、一氧化碳\n[1] 性质\n一氧化碳是一种无色、无臭、无味的气体。\n[2] 危害\n一氧化碳能与血红蛋白作用生成碳氧血红蛋白，而使血液携带氧\n的能力降低引起缺氧，导致人类出现头痛、晕眩、心血管工作困难直\n至死亡。\n[3] 来源\n一氧化碳是碳氢化合物燃烧不完全的产物，氧气不足，火焰温度\n不高等都能使其产生。一氧化碳是城市大气中数量最多的污染物，其\n占大气污染物的三分之一，主要来自于汽车尾气排放，且车速越高，\n一氧化碳排出越少。\n二、氮氧化物\n[1] 来源\n造成空气污染的氮氧化物主要是一氧化氮和二氧化氮，它们大部\n分来源于矿物燃料的燃烧过程，也有来自于生产或使用硝酸的工厂排\n放的尾气，还有氮肥厂、有机中间体厂、黑色及有色金属冶炼厂等。\n即汽车排出、火力发电站、工业燃烧排出为空气中氮氧化物的三大来\n源。\n[2]危害\nNO对人体无害，但当他转变为 时，就具有腐蚀性和生理刺激\n作用。 的危害如下：\n损坏棉花、尼龙等织物，破坏染料，使其褪色，并腐蚀镍青铜材\n料：损害植物；引起急性呼吸道病变。\n三、碳氢化合物\n[1]来源\n人为的碳氢化合物来源有二：即不完全的燃烧和有机化合物的蒸\n发。\n[2]危害\n城市空气中碳氢化合物能导致有害的光化学烟雾。\n四、硫氧化物\n[1]来源\n硫氧化物主要来自于矿物燃料的燃烧。\n[2]危害\n其中二氧化硫的腐蚀性极大，二氧化硫能使空气中的动力线硬化\n和拉锁刚绳的使用寿命缩短。它还使皮革失去强度，建筑材料变色破\n坏，塑像及艺术品损坏。它能损害植物叶片，影响其生长并降低其产\n量。它能刺激人的呼吸系统。他还有促癌作用，当空气中有微粒物质\n共存时，其危害更大。\n五、微粒\n[1] 含义\n微粒是指空气中分散的液态或固态物质，具体包括气溶胶、烟、\n尘、雾和炭烟等。气溶胶是悬浮于空气中的固液微粒，其直径一般小\n于1微米。尘是大于10微米的固体微粒迅速沉降而成的。烟是小于1微\n米的固体微粒。雾是液体微粒，其直径可达100微米。此外还有极细\n的，可集成一串的炭烟。\n尘埃中颗粒大于10微米的物质，几乎可被鼻腔和咽喉所捕集，不\n进入肺泡。但10微米以下的浮游状颗粒对人体的危害最大。\n[2] 危害\n遮挡阳光，使气温降低，或形成冷凝核心，使云雾和雨水增多，\n以致影响气候。使可见度降低，交通不便，航空和汽车事故增加。\n可见度差，照明耗电增加，燃料消耗随之增多，因此空气污染也\n更严重，形成恶性循环。燃煤使生成的硫氧化物。再加上微粒的作用\n对呼吸系统的危害特别大。\n用四乙基铅做汽油的防爆剂排入空气中的铅大部分为直径小于\n0.5微米的微粒，分布很广，危害很大。\n运输排出源，即机动车辆，是CO、HC和NOx的最大来源；固定\n的燃烧排出源，主要是发电站，是SOx的主要来源，也是很大一部分\n微粒的来源。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":1,"pastExamYears":[2020,2021,2022,2026],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":83,"sourceRange":{"startPage":83,"startY":245.74,"endPage":86,"endY":68.72},"sourceKind":"original","originalOrdinal":"4","sourceMetadata":["2020(填--CO消除途径, 【重要程度: 】","2021 (简--燃烧过程中氮氧化物的形成机制、 量的影响、2022 ( 简-- 危害、2026( 简-- 二","氧化硫的二次效应的污染，并列举两例烟气脱硫工艺，【重要程度：★☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":4,"excerpts":[{"page":83,"src":"./assets/environment/env838-4b64f180ce5e7254-83.webp"},{"page":84,"src":"./assets/environment/env838-4b64f180ce5e7254-84.webp"},{"page":85,"src":"./assets/environment/env838-4b64f180ce5e7254-85.webp"},{"page":86,"src":"./assets/environment/env838-4b64f180ce5e7254-86.webp"}]},{"id":"env838-a4d3ffc343d2dee1","subject":"环境学导论","chapter":"第4章 大气环境","originalChapter":"第4章 大气环境","originalChapterNumber":4,"section":"第2节 大气污染及其危害","originalSection":"第2节 大气污染及其危害","category":"knowledge","title":"PM2.5的来源、成分、危害、对雾霾的贡献、治理思路","question":"PM2.5的来源、成分、危害、对雾霾的贡献、治理思路","type":"简答题","answer":"[待核对] 2013 CH. 2015 CG, 2016 (, (BRB: tok ktk]\n一 、 来源\nPM2.5 (空气动力学直径入 2.5 微米的颗粒物 ) 的来源可分为自然源和人为源\nBRR: 包括风扬人尘土、 火山灰 、 森林火灾 、 海盐飞沫 、 植物花粉等 。\nAAR: 直接排放 : 化石燃料 〈 煤 、 石油 、 天然气 ) 燃烧 〈 如燃煤电厂 、 机动车尾气\n) 、 生物质燃烧 〈 秸秆焚烧 ) 、 工业粉尘 、 建筑扬尘等 。\n二 、 成分\nPM2.5 成分复杂 ， 主要包括 :\n无机成分 : 硫酸盐 、 确酸盐 、 铵盐 〈 占比约 69%) ， 以及地壳元素 〈 钠 、 镁 、 铝等 ) 。\n有机成分 : SRG (CHR, AMR) 、 多环芳烃等 。\n金属元素 : 铝 、 锅 、 砷等重金属 〈 主要来自工业污染 ) 。\n生物成分 : 细菌 、 病毒 、 真菌孢子等\n三 、 危害\n健康危害 :\n呼吸系统 : 深入肺泡 ， 引发哮喘 、 支气管炎 、 慢性阻塞性肺病 (COPD) 。\n心血管系统 : 进入血液后导致动脉硬化 、 血栓 、 心律失常等 。\n[待核对] REA: 吸附菜并芪等致冶物 ， 增加肺癌风险 。\n其他影响 : 损害免疫系统 、 生殖系统 ， 甚至影响神经功能和遗传物质 。\n环境危害 : 降低能见度 〈 雾起主因 ) ， 影响气候变化 ， 破坏生态系统 。\n[待核对] MER THAR\n[待核对] 直接降低能见度 : Md RERMPRKAR, WRB\n二次气溶胶主导 : 二次生成的硫酸盐 、 确酸盐等占 PM2.5 的 50% 以上 ， 加剧雾霜形成 。\n[待核对] 吸附污染物 ; REESE. His, HRFRHR.\n五 、 治理思路\n[待核对] RABE:\n@ 能源转型 : 减少煤炭使用 ， 推广清洁能源 〈 太阳能 、 风能 ) 。\n@ 工业减排 : 升级脱硫脱硝技术 ， 严控高污染行业排放 。\n@ 交通优化 : 发展公共交通 ， 推广新能源汽车 ， 限制柴油车 。\n[待核对] THREE:\n@ 扬尘治理 : 工地覆盖防尘网 、 洒水降尘 ， 加强道路清扫 。\n@ 农业管控 : 禁止秸秆葡烧 ， 推广秸秆资源化利用 。\n朱端治理 :\n@ 空气净化技术 : 应用生物酶治理剂 、 高效过滤设备 。\n© ”监测预警 : 完善空气质量监测网络 ， 实时发布数据 。\n政策与公众参与\n四 ”法规完善 : 制定严格排放标准 ， 实施区域联防联控 。\n入 ”公众教育 : 倡导绿色出行 、 侈碳生活 ， 鼓励环保举报 。\n六、光化学烟雾\n[1] 定义\n光化学烟雾是指大气中的氮氧化物和碳氢化合物等一次污染物\n及其受紫外线照射后产生的以臭氧为主的二次污染物所组成的混合\n污染物。光化学烟雾包括以下几种物质：氮氧化物(如二氧化氮)、\n对流层臭氧、挥发性有机污染物(VOCs)、过氧化乙酰硝酸酯(PAN\n)、酮类和醛类。\n[2] 危害\n①刺激人的眼睛，这是由具有刺激性的二次污染物甲醛、过氧化\n乙酰硝酸酯(PAN)、过氧化苯甲酰硝酸酯(PBN)和丙烯醛引起的\n②臭氧会引起胸部压缩、刺激粘膜、头痛、咳嗽、疲倦等症状：\n③臭氧能损害有机物质；\n④影响植物生长，导致哮喘病增多，影响材料质量(使橡胶开裂\n，腐蚀建筑物和衣物，缩短其使用寿命)，并降低大气能见度。\n污染高峰出现在中午或稍后。光化学烟雾是一种循环过程，白天\n产生、傍晚消失。\n[3]形成机理\n污染空气中的NO2的光解是光化学烟雾形成的起始反应\nNO₂=光照=NO+O· (氧原子自由基)\n碳氢化合物被HO·、O·等自由基和臭氧氧化，导致醛、酮、醇\n、酸等产物以及重要的中间产物 、 ,RCO· (过氧烷基自\n由基，过氧羟基自由基，酰基自由基)等自由基的生成。\n过氧自由基引起NO向 的转化，并导致 和PAN等的形成。\n[4]光化学烟雾的形成条件\n光化学烟雾的形成条件是大气中的氮氧化物和碳氢化合物的存\n在，大气湿度较低，而且有较强的阳光照射，这样在大气中就会发生\n一系列复杂的反应，生成一些二次污染物，如 、醛、酮、PAN以及\n等。故光化学烟雾一般发生在太气相对湿度较低、气温为24-32\n的夏季晴天。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2000,2002,2003,2012,2014,2016,2022],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。","含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":86,"sourceRange":{"startPage":86,"startY":68.72,"endPage":88,"endY":440.55},"sourceKind":"original","originalOrdinal":"supp-2","sourceMetadata":["2000(名、2002 (名、2012(名、2014(名、2016(简一定义、2022 (名、2003(简--机","理、条件、2016(简—机理、条件，【重要程度："],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":4,"excerpts":[{"page":86,"src":"./assets/environment/env838-a4d3ffc343d2dee1-86.webp"},{"page":87,"src":"./assets/environment/env838-a4d3ffc343d2dee1-87.webp"},{"page":88,"src":"./assets/environment/env838-a4d3ffc343d2dee1-88.webp"}]},{"id":"env838-2e1d4f04932a86fc","subject":"环境学导论","chapter":"第4章 大气环境","originalChapter":"第4章 大气环境","originalChapterNumber":4,"section":"第3节 大气污染的主要类型","originalSection":"第3节 大气污染的主要类型","category":"knowledge","title":"大气污染的主要类型","question":"大气污染的主要类型","type":"简答题","answer":"[1] 煤烟型污染\n煤烟型污染指由煤炭燃烧排放出烟尘、 等一次污染物及其二\n次污染物所构成的污染。我国的大气污染以煤烟型污染为主，主要污\n染物是烟尘和 ，此外还有 和CO等。\n[2] 交通型污染\n交通型污染是各种交通工具在行驶过程中排出的尾气造成的大\n气污染。污染物大部分来自燃料的不完全燃烧所排出的尾气。主要污\n染物有烟尘、NOx、CO、 、碳氢化合物、苯并[a]芘、铅化合物、\n石油和石油制品以及有害有毒运输品。随着汽车工业的发展，现代城\n市光化学烟雾的成因几乎无一例外是汽车尾气。\n[3] 酸沉降\n酸沉降是指大气中的酸性物质以降水的形式或者在气流作用下\n迁移到地面的过程。酸沉降包括“湿沉降”和“干沉降”。湿沉降通\n常指pH值低于5.6的降水，包括雨、雪、雾、冰雹等各种降水形式，最\n常见的是酸雨。干沉降指大气中的酸性物质在气流的作用下直接迁移\n到地面的过程。目前，人们对酸雨的研究较多，常把酸沉降与酸雨的\n概念等同起来。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":0,"pastExamYears":[2025],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":88,"sourceRange":{"startPage":88,"startY":481.02,"endPage":89,"endY":359.37},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":["2025(简— 出自课后题) , 【重要程度:☆☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":4,"excerpts":[{"page":88,"src":"./assets/environment/env838-2e1d4f04932a86fc-88.webp"},{"page":89,"src":"./assets/environment/env838-2e1d4f04932a86fc-89.webp"}]},{"id":"env838-0bb9dae257199eb0","subject":"环境学导论","chapter":"第4章 大气环境","originalChapter":"第4章 大气环境","originalChapterNumber":4,"section":"第3节 大气污染的主要类型","originalSection":"第3节 大气污染的主要类型","category":"knowledge","title":"酸雨的相关考点","question":"酸雨的相关考点","type":"简答题","answer":"[1] 来源与形成\n①天然排放源。硫化合物与氮化合物的天然排放源可分为非生物\n源和生物源。非生物源排放，包括海浪溅沫、地热排放气体与颗粒物\n、火山喷发等。生物源排放主要来自有机物腐败、细菌分解有机物的\n过程，以排放 、DMS、Cos为主，它们可以被氧化为 、NO而进\n入大气。\n②人为排放源。大气中硫和氮的化合物大部分是由人为活动产生\n的，化石燃料造成的 与 排放是产生酸雨的根本原因。\n③酸雨的形成。硫化合物和氮化合物进入大气后，会经历扩散、\n转化、输运以及被雨水吸收、冲刷、清除等过程。气态的NO、 在\n大气中可以被催化氧化或光化学氧化成不易挥发的硝酸和硫酸，并溶\n于云滴或雨滴而成为降水成分。\n[2] 酸雨的危害\n酸沉降以不同方式危害水生生态系统、陆生生态系统、材料和人\n体健康。\n①对水生生态系统的影响。酸雨危害水生生态系统，一方面是通\n过湖水pH值降低导致鱼类死亡，另一方面是酸雨浸渍土壤，侵蚀矿物\n，使铝元素和重金属元素沿着基岩裂缝流入附近水体，影响水生生物\n生长或使其死亡。水中铝含量达到0.2mg/L时，就会致鱼类死亡。同\n时，对浮游植物和其他水生植物起营养作用的磷酸盐，由于附着在铝\n上，难于被生物吸收，其营养价值就会降低，并使赖以生存的水生生\n物的初级生产力降低。\n②对陆生生态系统的影响。酸雨对森林的危害可分为四个阶段。\n第一阶段，酸雨增加硫和氮，使树木生长呈现受益倾向。第二阶段，\n长年酸雨使土壤中和能力下降，以及K、Ca、Mg、Al等元素淋溶，使\n土壤贫瘠。第三阶段，土壤中的铝和重金属被活化，对树木生长生成\n毒害，当根部的 Ca/Al比率小于0.15时，溶出的铝具有毒性，抑制树木\n生长。而且，酸性条件有利于病虫害的扩散，危害树木，这时生态系\n统已失去恢复力。第四阶段，如树木遇到持续干旱等诱发因素，土壤\n酸化程度加剧，会引起根系严重枯萎，致使树木死亡。\n③对各种材料的影响。酸雨会加速许多用于建筑结构、桥梁、水\n坝、工业装备、供水管网、地下贮罐、水轮发电机以及动力和通讯电\n缆等材料的腐蚀。酸雨能严重损害古迹。\n④对人体健康的影响。酸雨对人体健康产生间接的影响。酸雨使\n地面水变成酸性，地下水中金属量会增高，饮用这种水或食用酸性河\n水中的鱼类会对人体健康产生危害。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2004,2005,2007,2008,2010,2012,2015],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":89,"sourceRange":{"startPage":89,"startY":359.37,"endPage":91,"endY":75.88},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":["【重要程度：","2004(选-形成、2005(选--形成、2008(简、2010(选--形成、2015(简, 【重要程度:","2004(简、2007(简、2012 (简、2015 (简, 【重要程度: )】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":4,"excerpts":[{"page":89,"src":"./assets/environment/env838-0bb9dae257199eb0-89.webp"},{"page":90,"src":"./assets/environment/env838-0bb9dae257199eb0-90.webp"},{"page":91,"src":"./assets/environment/env838-0bb9dae257199eb0-91.webp"}]},{"id":"env838-c5eb91b470fa7fe4","subject":"环境学导论","chapter":"第4章 大气环境","originalChapter":"第4章 大气环境","originalChapterNumber":4,"section":"第3节 大气污染的主要类型","originalSection":"第3节 大气污染的主要类型","category":"knowledge","title":"防治酸雨的对策","question":"防治酸雨的对策","type":"简答题","answer":"①降低煤炭中含硫量\n②减少 的排放\n我国洗煤能力应当优先安排洗选高硫煤，回收精硫矿。对于无法洗选的有机硫，可在\n煤炭燃烧过程中采用回收技术，制取硫酸。在生产和生活用煤中，要尽量采用热电联\n产，集中供热，实行燃煤气化和成型化，甚至可以安装消除烟尘和脱硫设备。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2012,2015],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":91,"sourceRange":{"startPage":91,"startY":75.88,"endPage":91,"endY":253.83},"sourceKind":"original","originalOrdinal":"supp-3","sourceMetadata":["2012 (简、2015 ( 简, 【重要程度:"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":4,"excerpts":[{"page":91,"src":"./assets/environment/env838-c5eb91b470fa7fe4-91.webp"}]},{"id":"env838-3da77d72157f124d","subject":"环境学导论","chapter":"第4章 大气环境","originalChapter":"第4章 大气环境","originalChapterNumber":4,"section":"第3节 大气污染的主要类型","originalSection":"第3节 大气污染的主要类型","category":"knowledge","title":"影响空气污染的气象因素","question":"影响空气污染的气象因素","type":"简答题","answer":"[1] 风\n风对空气污染的影响包括风向和风速的大小两个方面。风向影响着污染物的扩散\n方向，风速的大小决定着污染物的扩散和稀释状况。\n[2] 大气的稳定性\n①大气的稳定性与大气降温率的关系\na.垂直降温率γ：大气温度沿垂直方向随高度变化的速率称为垂直降温率\nb.垂直绝热降温率γd：垂直绝热降温率是指空气在绝热条件下上升时，由于上升气块\n所受的压力降低而膨胀，消耗了内能，使气块温度随之下降的速率。\nYd=0.98 ℃/100m≈1 ℃/100m\nγ>1 ℃/100m, 就是超绝热降温率。此时气块上升的降温率大于绝热降温率，造\n成气块的温度低于理想的温度。冷者下沉，下沉后受到地表的辐射热又上升，以致发\n生垂直混合。显然，此时大气是不稳定的，它有利于空中的污染物扩散开来。从控制\n空气污染的角度出发这是我们所期待的气象条件。\n与此相反，当0< γ <1℃/100m，即次绝热降温时空气是稳定的，此时空气上升的\n降温率低于绝热降温率，以致气块的温度稍高于理想的温度。这样，不同高度的空气\n层之间，就很难发生垂直混合，因此空气基本上是稳定的，这会使空中污染物积累起\n来。\n图 4-2 不同的降温率的联系\n@ 不同降温率对烟向的排烟的影响\na. 超绝热降温时 ， 大气不稳定 ， 出现波浪型排烟 ， 能使污染物随风速扩散 ;\nb. 逆温时 ， 由于大气稳定 ， 形成扁型排烟 ,严重地妨碍空中污染物的熏直运动 ， 只能朝\n水平方向扩散 ;\nc. 当大气的上层为北温 ， 下层是超绝热降温 ， 即上层稳定 ， 下层不稳定时 ， 形成请烟型\n排烟 ， 空气中污染物被二烟带回地面 ， 使污染更为严重 。\n[待核对] Fy Ran\n[待核对] fe\n4-3 大气稳定度与排烟类型\n[3] 降水\n[4] ¥","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":1,"pastExamYears":[2001,2002,2003,2019,2022],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。","含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":91,"sourceRange":{"startPage":91,"startY":253.83,"endPage":93,"endY":63.32},"sourceKind":"original","originalOrdinal":"supp-4","sourceMetadata":["2001 (简、2002 ( 简, 【重要程度:","2003 (填、2019 (名、2022 ( 填, 【重要程度: ★☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":4,"excerpts":[{"page":91,"src":"./assets/environment/env838-3da77d72157f124d-91.webp"},{"page":92,"src":"./assets/environment/env838-3da77d72157f124d-92.webp"},{"page":93,"src":"./assets/environment/env838-3da77d72157f124d-93.webp"}]},{"id":"env838-8fec45902dc3f7f9","subject":"环境学导论","chapter":"第4章 大气环境","originalChapter":"第4章 大气环境","originalChapterNumber":4,"section":"第3节 大气污染的主要类型","originalSection":"第3节 大气污染的主要类型","category":"knowledge","title":"逆温的类型","question":"逆温的类型","type":"简答题","answer":"[待核对] fU-SENN. 2006 Cf. 2011 Cf. 2016 (AG, LBBB: toldtolok]\nBR: 当高度增大时 ， 气温反而上升 ， 即 Y <0， 则该空气层便成为逆温层 。 此时\n上层空气密度低 ， 下层空气密度高 ， 空气在径直方向上不存在任何运动 ， 气层异常稳\n定 ， 以致常常发生空气污染事故 。\n[I] 辐射逆温\n例如在经过一个寒冷而晴朗的夜晚后 ， 次日早晨地表就会出现辐射逆温现象 。 这\n是国为在夜里地表将热量辐射到空间后变冷了 。 如果当时有云 ， 则有些能量可借云层\n反射回地面 ， 使地表温度不致降得太多 。 但如晴朗无云 ， 则地表会迅速冷下来 ， 紧接\n着使地面的空气也变冷了 ， 以至其温度低于其上部空气的温度 ， 从而产生逆温现象\n到了和白天， 太阳晒热地表后 ， 逆温现象才消失 。\n[2] 海岸逆温\n海岸逆温是由于白天陆地被太阳晒热后 ， 地面的热空气上升将海上的冷空气吸入\n， 使沿岸子面产生逆温 。 当海风移动到内地时 ， 逆温层变罕 ， 最后消失 。\n[待核对] 海风\n[待核对] nL. /\n[待核对] id\n冷海风\n图 4-4 海岸逆温形成过程\n[待核对] [3] sea ese\n地形逆温是因局部地区地理条件的特点而形成的 。 例如在山区 ， 晚上稠密寒冷的\n空气沿山坡流聚在山谷中 ， 上层虽有热气流通过 ， 也不会影响山谷中停滞的冷气团 ，\n因此 ， 山谷中便形成了上温下冷的逆温层 。 这种状况有时可以保持一整天之久 ， 不到\n阳光直射山谷 ， 或热风劲吹 ， 是不会消失的 。\n热风\n[待核对] \\ ef\n4-5 地形逆温的形成过程","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2000,2001,2002,2003,2008,2015,2016,2021],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。","含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":93,"sourceRange":{"startPage":93,"startY":63.32,"endPage":95,"endY":75.92},"sourceKind":"original","originalOrdinal":"supp-5","sourceMetadata":["2008 (4. 2015 (44. 2016 (4, 2021 CL. 2000 CK, 2001 CH. 2002 CX. 2003 ¢"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":4,"excerpts":[{"page":93,"src":"./assets/environment/env838-8fec45902dc3f7f9-93.webp"},{"page":94,"src":"./assets/environment/env838-8fec45902dc3f7f9-94.webp"},{"page":95,"src":"./assets/environment/env838-8fec45902dc3f7f9-95.webp"}]},{"id":"env838-56eb28ea2135338c","subject":"环境学导论","chapter":"第4章 大气环境","originalChapter":"第4章 大气环境","originalChapterNumber":4,"section":"第4节 大气污染防治","originalSection":"第4节 大气污染防治","category":"knowledge","title":"静电除尘技术的原理与优点","question":"静电除尘技术的原理与优点","type":"简答题","answer":"静电除尘器的工作原理：含粉尘的气体，在接有高压直流电源的\n阴极线(又称电晕极)和接地的阳极板之间形成的高压电场通过时，\n由于阴极发生电晕放电，气体被电离，带负电的气体离子在电场力的\n作用下向阳极板运动，在运动中与粉尘颗粒相碰，使尘粒荷带负电，\n尘粒在电场力的作用下亦向阳极运动，到达阳极后放出所带的电子，\n尘粒则沉积于阳极板上，净化的气体排出防尘器外。\n优点：与其他除尘设备相比，静电除尘器耗能少，效率高，适用\n于去除0.01~50μm的粉尘，而且可用于烟气温度高、压力大的场合\n。处理的烟气量越大，静电除尘器的投资和运行费用越经济。\n图 4-6 电除尘原理示意图\n分尘由于重\n过滤料时，\n体尘含量每\n级效率；处\n方便；对粉\n图 4-8 石灰石 /石膏法脱硫技术示意图\n脱硫吸收剂采用价廉易得的石灰石或石灰。石灰石经破碎磨成细\n粉状与水混合搅拌成吸收浆液，当采用石灰为吸收剂时，石灰粉经消\n化处理后加水制成吸收剂浆液。\n在吸收塔内，吸收浆液与烟气接触混合， 与浆液中的碳酸钙\n以及鼓入的空气进行化学反应被脱除，最终反应产物为石膏。脱硫后\n的烟气经除雾器除去带出的细小液滴，经换热器加热升温后排人烟囱\n，脱硫石膏浆经脱水后回收。\n优点：系统运行稳定，变负荷运行特性优良；可靠性高，脱硫效\n率高，可达95%以上；原料来源广泛、易取得、价格优惠，吸收剂利\n用率高(可大于90%)；容量可大可小，应用范围广；废物排放量少，\n并且可实现无废物排放。\n缺点：初期投资费用太高、运行费用高、占地面积大，系统管理\n操作复杂、磨损腐蚀现象较为严重，副产物——石膏很难处理(由于\n销路问题只能堆放)，废水较难处理。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。","含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":95,"sourceRange":{"startPage":95,"startY":206.76,"endPage":98,"endY":159.91},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":4,"excerpts":[{"page":95,"src":"./assets/environment/env838-56eb28ea2135338c-95.webp"},{"page":96,"src":"./assets/environment/env838-56eb28ea2135338c-96.webp"},{"page":97,"src":"./assets/environment/env838-56eb28ea2135338c-97.webp"},{"page":98,"src":"./assets/environment/env838-56eb28ea2135338c-98.webp"}]},{"id":"env838-07d4361acebf5911","subject":"环境学导论","chapter":"第4章 大气环境","originalChapter":"第4章 大气环境","originalChapterNumber":4,"section":"第4节 大气污染防治","originalSection":"第4节 大气污染防治","category":"knowledge","title":"干法喷钙脱硫技术","question":"干法喷钙脱硫技术","type":"简答题","answer":"干法喷钙脱硫技术工艺在除尘器前加装活化反应器，喷水增湿，\n使未反应的石灰转化成氢氧化钙，加快硫分转化成硫酸盐的速度，使\n脱硫效率显著提高。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":98,"sourceRange":{"startPage":98,"startY":159.91,"endPage":98,"endY":305.19},"sourceKind":"original","originalOrdinal":"4","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":4,"excerpts":[{"page":98,"src":"./assets/environment/env838-07d4361acebf5911-98.webp"}]},{"id":"env838-c2c8130c294c65cb","subject":"环境学导论","chapter":"第4章 大气环境","originalChapter":"第4章 大气环境","originalChapterNumber":4,"section":"第4节 大气污染防治","originalSection":"第4节 大气污染防治","category":"knowledge","title":"选择性脱硝技术","question":"选择性脱硝技术","type":"简答题","answer":"(1 )选择性催化还原脱硝技术\n选择性催化还原法(Selectiveatalytieeduction,SCR) 是指在催化\n剂的作用下，利用还原剂(如 、液氨、尿素)有选择性地与 反\n应并生成氮气和水。该工艺运行稳定可靠，脱硝效率高，是应用最广\n泛的脱硝技术，世界大部分火电厂都用此工艺脱硝。\n(2)选择性非催化还原脱硝技术\n选择性非催化还原法(Selectiveon—  Catalyticeduction,SNCR) 技\n术是一种不用催化剂，在850~ 1100 还原NO的方法，还原剂常用氨\n或尿素。\n小黄学长-\n脱硝\nSNCR 选择性非催化还原\n方法 项 SCR 选择性催化还原法\n法\n目\n催化剂 使用( 成份主为TTO2,V2O5,WO3) 不使用\n还原剂 尿素或NH3 尿素或NH3\n系统压力损失 增大 无\n多选择于省煤器与SCR 反应器间烟道\n反应剂喷射位置 通常炉膛内喷射\n内\nS02/ S03 氧化 会 不会\nNH3 逃逸 <3ppm 5~10ppm\n除NOX温度 300~400 850~1100\nNOx 脱除效率 80~95 % 40~80%\n除NOX终产物 氮气和水 氮气、CO2和水\n下游设备造成影响 造成空预器堵塞 无\n催化剂中的V、Mn、Fe等多种金属会对\nS02 的氧化起催化作用,S02/S03氧化\n对空气预热器影响 不会造成堵塞或腐蚀\n率较高,而NH3 与SO3 易形成\n造成堵塞或腐蚀\n高灰分会磨耗催化剂，碳全属氧化物会\n燃料的影响 无影响\n使催化剂钝化\n受炉膛内烟气流速、温度\n锅炉的影响 受省煤器出口细气温度的影响\n分布及NOx分布的影响\n预留空间 需要 不需要\n大(需增加大型催化剂反应器和供氨或 小(锅炉无需增加催化\n设备占地面积\n尿素系统) 剂反应器)\n安装设备 时间长 时间短\n检修、维护 麻烦 简单\n图4-9SCR与SNCR技术对比\n(3) 生物法脱硝\n生物法脱硝是利用微生物将 转变为氮气、 ヽ 以及微生\n物的细胞质。作为一种新型的脱硝方式，此法实际应用很少。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":98,"sourceRange":{"startPage":98,"startY":305.19,"endPage":100,"endY":74.35},"sourceKind":"original","originalOrdinal":"5","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":4,"excerpts":[{"page":98,"src":"./assets/environment/env838-c2c8130c294c65cb-98.webp"},{"page":99,"src":"./assets/environment/env838-c2c8130c294c65cb-99.webp"},{"page":100,"src":"./assets/environment/env838-c2c8130c294c65cb-100.webp"}]},{"id":"env838-646cbdc493ece6fc","subject":"环境学导论","chapter":"第4章 大气环境","originalChapter":"第4章 大气环境","originalChapterNumber":4,"section":"第5节 课后习题","originalSection":"第5节 课后习题","category":"exercise","title":"简述大气对人类生活的重要性。","question":"简述大气对人类生活的重要性。","type":"简答题","answer":"①生命条件：提供呼吸所需氧气、植物光合作用所需CO₂及氮循环的重要物质基础。\n②热量调节：大气参与太阳辐射和地面长波辐射交换，维持适合生命的温度条件。\n③保护作用：平流层臭氧吸收大部分有害紫外线，大气也使许多小型流星体在进入时烧蚀。\n④物质与能量输送：通过风、云、降水和水循环调节气候，影响水资源、农业和生态系统。\n⑤生活生产：与交通、通信、风能利用和污染物扩散等密切相关。\n因此，大气质量下降不仅影响呼吸健康，也影响气候、生态及社会经济活动。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":100,"sourceRange":{"startPage":100,"startY":112.55,"endPage":100,"endY":189.69},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":4,"additionalSources":[{"source":"环导变动137718728584015123.1eae00877280d3e.pdf","page":7,"sourceRange":{"startPage":7,"startY":459.54,"endPage":7,"endY":475.14}}],"excerpts":[{"page":100,"src":"./assets/environment/env838-646cbdc493ece6fc-100.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=75"},{"title":"NASA：温室效应的原理","url":"https://science.nasa.gov/climate-change/faq/what-is-the-greenhouse-effect/","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-fe50777528add545","subject":"环境学导论","chapter":"第4章 大气环境","originalChapter":"第4章 大气环境","originalChapterNumber":4,"section":"第5节 课后习题","originalSection":"第5节 课后习题","category":"exercise","title":"什么是大气污染?请结合现实生活中的污染情况谈谈你对大气污染的认识。","question":"什么是大气污染?请结合现实生活中的污染情况谈谈你对大气污染的认识。","type":"简答题","answer":"大气污染是有害物质进入大气，其浓度和持续时间达到足以危害人体、生态系统或财产，或造成不良环境效应的状态。\n认识时要联系“污染源—污染物—气象扩散—暴露与影响”：例如机动车和工业排放NOₓ与VOCs，在日照下生成近地面臭氧；燃烧与扬尘可增加颗粒物，在静稳、逆温等条件下积累。\n污染包括直接排放的一次污染，也包括大气化学反应形成的二次污染；看不见烟尘不等于没有污染。防治既要削减排放，也要进行区域协同和公众暴露防护。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":100,"sourceRange":{"startPage":100,"startY":189.69,"endPage":100,"endY":295.63},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":4,"additionalSources":[{"source":"环导变动137718728584015123.1eae00877280d3e.pdf","page":7,"sourceRange":{"startPage":7,"startY":475.14,"endPage":7,"endY":506.34}}],"excerpts":[{"page":100,"src":"./assets/environment/env838-fe50777528add545-100.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=75"},{"title":"NASA：近地面臭氧的形成","url":"https://airquality.gsfc.nasa.gov/surface-level-ozone","accessedOn":"2026-11-09"},{"title":"生态环境部：重点行业挥发性有机物综合治理方案","url":"https://www.mee.gov.cn/xxgk2018/xxgk/xxgk03/201907/t20190703_708395.html","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-a8754b3d448dd184","subject":"环境学导论","chapter":"第4章 大气环境","originalChapter":"第4章 大气环境","originalChapterNumber":4,"section":"第5节 课后习题","originalSection":"第5节 课后习题","category":"exercise","title":"大气污染中主要污染物有哪些，主要来源和主要处理措施是什么?","question":"大气污染中主要污染物有哪些，主要来源和主要处理措施是什么?","type":"简答题","answer":"①颗粒物：来自燃烧、工业过程、道路及施工扬尘，也可由气态前体物二次生成；采用清洁燃料、密闭集气、抑尘及袋式／电除尘等。\n②SO₂：主要与含硫燃料燃烧、冶炼有关；采用低硫原料、燃料替代及烟气脱硫。\n③NOₓ：来自高温燃烧、机动车等；采用低氮燃烧、SCR／SNCR及车辆尾气治理。\n④VOCs：来自溶剂使用、石化和储运等；采用原辅料替代、密闭收集与吸附、回收或氧化处理。\n⑤CO：主要由不完全燃烧产生，应改善燃烧条件并采用适当尾气催化处理。\n⑥臭氧：是NOₓ和VOCs在日照下反应形成的二次污染物，应协同控制前体物。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":100,"sourceRange":{"startPage":100,"startY":295.63,"endPage":100,"endY":400.7},"sourceKind":"original","originalOrdinal":"3","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":4,"additionalSources":[{"source":"环导变动137718728584015123.1eae00877280d3e.pdf","page":7,"sourceRange":{"startPage":7,"startY":506.34,"endPage":7,"endY":521.94}}],"excerpts":[{"page":100,"src":"./assets/environment/env838-a8754b3d448dd184-100.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=75"},{"title":"生态环境部：重点行业挥发性有机物综合治理方案","url":"https://www.mee.gov.cn/xxgk2018/xxgk/xxgk03/201907/t20190703_708395.html","accessedOn":"2026-11-09"},{"title":"NASA：近地面臭氧的形成","url":"https://airquality.gsfc.nasa.gov/surface-level-ozone","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-ac2b46c84bfc9286","subject":"环境学导论","chapter":"第4章 大气环境","originalChapter":"第4章 大气环境","originalChapterNumber":4,"section":"第5节 课后习题","originalSection":"第5节 课后习题","category":"exercise","title":"大气污染物有哪几种分类?其危害是什么?","question":"大气污染物有哪几种分类?其危害是什么?","type":"简答题","answer":"一、按形态：颗粒态污染物（烟尘、粉尘、雾滴等）与气态污染物（SO₂、NOₓ、CO、VOCs等）。\n二、按形成过程：一次污染物由污染源直接排放；二次污染物由一次污染物反应形成，如臭氧和部分二次颗粒物。\n三、按来源：自然源和人为源，也可区分固定源、移动源与面源。\n四、危害：颗粒物及多种气体损害人体呼吸和心血管系统；SO₂、NOₓ等参与酸沉降，臭氧损伤作物和植被，颗粒物降低能见度；部分污染物还参与气候变化或损害材料。\n分类角度不同可以交叉，不能把同一污染物限定为一种唯一类别。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":100,"sourceRange":{"startPage":100,"startY":400.7,"endPage":100,"endY":476.78},"sourceKind":"original","originalOrdinal":"4","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":4,"additionalSources":[{"source":"环导变动137718728584015123.1eae00877280d3e.pdf","page":7,"sourceRange":{"startPage":7,"startY":521.94,"endPage":7,"endY":537.54}}],"excerpts":[{"page":100,"src":"./assets/environment/env838-ac2b46c84bfc9286-100.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=75"},{"title":"NASA：近地面臭氧的形成","url":"https://airquality.gsfc.nasa.gov/surface-level-ozone","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-d1f9f5da09a7963e","subject":"环境学导论","chapter":"第4章 大气环境","originalChapter":"第4章 大气环境","originalChapterNumber":4,"section":"第5节 课后习题","originalSection":"第5节 课后习题","category":"exercise","title":"大气污染的主要类型有哪些?","question":"大气污染的主要类型有哪些?","type":"简答题","answer":"①煤烟型污染：以燃煤形成的烟尘、SO₂等为突出特征，常受静稳、逆温等条件影响。\n②光化学烟雾：NOₓ和VOCs等在阳光作用下形成臭氧及其他氧化性产物。\n③酸沉降：SO₂、NOₓ等转化为酸性物质，以湿沉降或干沉降进入环境。\n④颗粒物／灰霾污染：一次颗粒排放与二次颗粒形成共同作用，降低能见度并产生健康影响。\n从更大尺度还可讨论温室气体增加与臭氧层破坏。实际城市经常存在多种污染共同作用的复合污染，不能仅按历史“煤烟型”解释全部问题。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":100,"sourceRange":{"startPage":100,"startY":476.78,"endPage":101,"endY":70.42},"sourceKind":"original","originalOrdinal":"5","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":4,"additionalSources":[{"source":"环导变动137718728584015123.1eae00877280d3e.pdf","page":7,"sourceRange":{"startPage":7,"startY":537.54,"endPage":7,"endY":553.14}}],"excerpts":[{"page":100,"src":"./assets/environment/env838-d1f9f5da09a7963e-100.webp"},{"page":101,"src":"./assets/environment/env838-d1f9f5da09a7963e-101.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=75"},{"title":"NASA：近地面臭氧的形成","url":"https://airquality.gsfc.nasa.gov/surface-level-ozone","accessedOn":"2026-11-09"},{"title":"NASA：温室效应的原理","url":"https://science.nasa.gov/climate-change/faq/what-is-the-greenhouse-effect/","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-647ba774002ffd67","subject":"环境学导论","chapter":"第4章 大气环境","originalChapter":"第4章 大气环境","originalChapterNumber":4,"section":"第3节","originalSection":"第3节","category":"supplement","title":"雾霾的相关考点","question":"雾霾的相关考点","type":"简答题","answer":"一、定义\n雾霾是雾和霾的组合，常见于城市，是特定气候条件与人类活动相互作用的\n结果，主要涉及二氧化硫、氮氧化物和可吸入颗粒物，其中，颗粒物是加重雾霾\n污染的重要因素。当细颗粒物排放超过大气的循环能力和承载能力时，污染物会\n持续积累，遇到静稳天气等不利气象条件，容易形成大范围雾霾。\n二、成因\n①人为因素\n人为因素主要包括：工业生产排放的废气、机动车排放的尾气、冬季取暖烧\n煤产生的烟气、建筑工地和道路交通产生的扬尘、装修过程中产生的粉尘等，这\n些因素导致大气中的PM10 和PM2.5 浓度增加，从而导致雾霾天气。\n②气象因素\n在秋冬季节，大气环流异常导致的静稳天气多。在静稳天气条件下，气压场\n较为均匀、风速较小，湍流受到抑制，特别是若出现逆温层，低空水汽和颗粒物\n不易扩散，极易形成雾霾天气。\n三、危害\n①对人体健康的危害。雾霾中含有各种对人体有害的细颗粒和有毒物质，特\n别是直径在0.01μm 以下的悬浮颗粒物，可直接通过呼吸系统进入支气管，甚至\n肺部，造成呼吸道疾病、脑血管疾病和鼻腔炎症等。雾霾天气时，由于空气流动\n性差，对有害细菌和病毒的稀释能力大大降低，还会导致疾病传播风险升高。\n②对交通的不利影响。雾霾天气时，空气质量差，能见度低，易导致交通堵\n塞，引发交通事故，造成较严重的人身安全伤害和经济损失。","source":"环导变动137718728584015123.1eae00877280d3e.pdf","sourceUrl":"https://drive.google.com/file/d/11CjvWmrS4poAVMmBBWnsJPRCmD1-JkRJ/view","version":"new","importance":5,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":4,"sourceRange":{"startPage":4,"startY":641.01,"endPage":5,"endY":577.02},"sourceKind":"changes","originalOrdinal":"3","sourceMetadata":["【重要程度：★★★★★】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":4,"excerpts":[{"page":4,"src":"./assets/environment/env838-647ba774002ffd67-4.webp"},{"page":5,"src":"./assets/environment/env838-647ba774002ffd67-5.webp"}]},{"id":"env838-7681637c28641beb","subject":"环境学导论","chapter":"第4章 大气环境","originalChapter":"第4章 大气环境","originalChapterNumber":4,"section":"第4节","originalSection":"第4节","category":"supplement","title":"CO2 治理技术","question":"CO2 治理技术","type":"简答题","answer":"CO2 常见的治理方法主要包括碳捕集与贮存、碳捕集与能源化利用、碳捕集\n与资源化利用、CO₂资源化利用、发展清洁能源技术等。\n（1）碳捕集与贮存\n通过化学吸收和物理吸附等方法，将CO₂从各种燃烧和工业过程中分离出来，\n然后通过管道将其注入地下岩层中封存，贮存地点常为废弃油田或气田，防止其\n重新进入大气环境中。\n（2）碳捕集与能源化利用\n将CO₂通过捕集技术从废气中分离出来以后，再将碳转化为燃料，实现其再\n次利用获取能量的目的。目前这一技术多限于实验研究阶段，也有少量在工业示\n范阶段。\n（3）CO₂资源化利用\nCO₂可以应用于化学品合成、造纸、石油开采等多个领域，通过将其转化为\n有用的化学品和能源，实现减排。例如CO₂作为水处理pH 控制剂、焊接气体、\n植物生长刺激剂；CO₂作为碳酸饮料、啤酒添加剂以及食品加工过程中的惰性保\n护气体等。","source":"环导变动137718728584015123.1eae00877280d3e.pdf","sourceUrl":"https://drive.google.com/file/d/11CjvWmrS4poAVMmBBWnsJPRCmD1-JkRJ/view","version":"new","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":5,"sourceRange":{"startPage":5,"startY":607.05,"endPage":6,"endY":369.04},"sourceKind":"changes","originalOrdinal":"6","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":4,"excerpts":[{"page":5,"src":"./assets/environment/env838-7681637c28641beb-5.webp"},{"page":6,"src":"./assets/environment/env838-7681637c28641beb-6.webp"}]},{"id":"env838-c576a8fe4a4cbc38","subject":"环境学导论","chapter":"第4章 大气环境","originalChapter":"第4章 大气环境","originalChapterNumber":4,"section":"第4节","originalSection":"第4节","category":"supplement","title":"CCUS","question":"CCUS","type":"简答题","answer":"CCUS 英文全称为 Carbon Capture Utilization and Storage, 指 CO2 捕集、利\n用与封存，是应对全球气候变化、控制温室气体排放的重要技术手段。联合国政\n府间气候变化专门委员会指出，如果没有CCUS 技术，几乎所有气候模式都不能\n实现《巴黎协定》目标，且全球碳减排成本将成倍增加。","source":"环导变动137718728584015123.1eae00877280d3e.pdf","sourceUrl":"https://drive.google.com/file/d/11CjvWmrS4poAVMmBBWnsJPRCmD1-JkRJ/view","version":"new","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":6,"sourceRange":{"startPage":6,"startY":369.04,"endPage":6,"endY":525.06},"sourceKind":"changes","originalOrdinal":"7","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":4,"excerpts":[{"page":6,"src":"./assets/environment/env838-c576a8fe4a4cbc38-6.webp"}]},{"id":"env838-e94ba747fedf05db","subject":"环境学导论","chapter":"第4章 大气环境","originalChapter":"第4章 大气环境","originalChapterNumber":4,"section":"第4节","originalSection":"第4节","category":"supplement","title":"VOCs 治理技术","question":"VOCs 治理技术","type":"简答题","answer":"VOCs 治理包括：源头减量、中间控制和末端治理。目前，我国已经由末端\n治理为主转化为源头削减、过程控制、末端治理三方面协同推进，进而实现全面\n减排。\n（1）焚烧法\n焚烧法是将VOCs 直接投入火炬、焚烧炉等系统中进行充分燃烧，最终生成\nCO₂和H₂O。若VOCs 浓度较低，则需加入辅助燃料，才能使VOCs 充分燃烧。\n这种方法成本低，适用范围广，技术路线也比较成熟。\n（2）吸附法\n吸附法是利用吸附剂的微孔结构，将VOCs 气体吸附在表面，使其与气流主\n体分离。吸附剂可分为化学吸附剂和物理吸附剂两类，其中化学吸附剂多用于治\n理水相污染物，物理吸附剂如活性炭和沸石则在处理有机废气方面更有效。目前，\n吸附法常用于较低浓度废气的净化。\n（3）吸收法\n吸收法是使用吸收剂与废气充分接触，对废气中的VOCs 进行吸收。物理吸\n收剂主要凭借相似相溶特性，而化学吸收剂则是通过与VOCs 发生化学反应，以\n达到净化废气的目的。利用直接回收、压缩冷凝回收等技术还可实现吸收剂处理\n后循环使用。\n（4）生物法\n生物法利用厌氧菌和好氧菌对VOCs 废气的分解能力，降低VOCs 对大气环\n境的污染，是目前VOCs 处理领域关注的重点。低浓度的VOCs 在生物滤床中被\n生物膜填料吸附，分解成的CO₂和H₂O 气体，最终排空。","source":"环导变动137718728584015123.1eae00877280d3e.pdf","sourceUrl":"https://drive.google.com/file/d/11CjvWmrS4poAVMmBBWnsJPRCmD1-JkRJ/view","version":"new","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":6,"sourceRange":{"startPage":6,"startY":525.06,"endPage":7,"endY":435.06},"sourceKind":"changes","originalOrdinal":"8","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":4,"excerpts":[{"page":6,"src":"./assets/environment/env838-e94ba747fedf05db-6.webp"},{"page":7,"src":"./assets/environment/env838-e94ba747fedf05db-7.webp"}]},{"id":"env838-2cdcc03cd207c931","subject":"环境学导论","chapter":"第4章 大气环境","originalChapter":"第4章 大气环境","originalChapterNumber":4,"section":"课后习题","originalSection":"课后习题","category":"exercise","title":"针对各类大气污染问题，还有哪些新的治理技术？","question":"针对各类大气污染问题，还有哪些新的治理技术？","type":"简答题","answer":"①颗粒物：高效袋式除尘、电袋复合除尘及湿式电除尘等可用于不同粒径和性质的颗粒物控制。\n②SO₂、NOₓ：结合低硫原料、低氮燃烧、脱硫及选择性催化还原等，并开展多污染物协同控制。\n③VOCs：低挥发原料替代、LDAR、密闭收集、吸附浓缩—催化／蓄热氧化及适用的回收技术。\n④温室气体：提高能效、可再生能源替代、电气化、CO₂捕集利用与封存（CCUS）等。\n⑤管理技术：在线监测、排放清单与源解析帮助精准治理。\n技术选择应考虑浓度、组分、风量、能耗及二次污染；不能把一种新技术宣传为适合全部废气。","source":"环导变动137718728584015123.1eae00877280d3e.pdf","sourceUrl":"https://drive.google.com/file/d/11CjvWmrS4poAVMmBBWnsJPRCmD1-JkRJ/view","version":"new","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":7,"sourceRange":{"startPage":7,"startY":553.14,"endPage":7,"endY":568.74},"sourceKind":"changes","originalOrdinal":"6","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":4,"excerpts":[{"page":7,"src":"./assets/environment/env838-2cdcc03cd207c931-7.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=75"},{"title":"生态环境部：重点行业挥发性有机物综合治理方案","url":"https://www.mee.gov.cn/xxgk2018/xxgk/xxgk03/201907/t20190703_708395.html","accessedOn":"2026-11-09"},{"title":"中国的能源转型白皮书（英文全文）","url":"https://english.www.gov.cn/archive/whitepaper/202408/29/content_WS66d012e8c6d0868f4e8ea52e.html","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-14d19633ac31e92a","subject":"环境学导论","chapter":"第4章 大气环境","originalChapter":"第4章 大气环境","originalChapterNumber":4,"section":"课后习题","originalSection":"课后习题","category":"exercise","title":"酸雨是如何形成的？它对环境有什么影响？","question":"酸雨是如何形成的？它对环境有什么影响？","type":"简答题","answer":"形成：含硫燃料燃烧等排放SO₂，燃烧和交通等排放NOₓ；它们在大气中经氧化及水相反应形成硫酸、硝酸等，随雨雪雾沉降。教学上通常将pH低于5.6的降水称为酸雨，该值不是所有地区天然降水的绝对分界。\n影响：①土壤与水体酸化，养分淋失、某些金属活性增加；②损伤森林和农作物，影响水生生物；③腐蚀金属及建筑材料，损害文物；④相关酸性气溶胶及污染物还可造成健康风险。\n防治：减少SO₂、NOₓ排放，优化能源结构，实施脱硫脱硝及区域协同治理。","source":"环导变动137718728584015123.1eae00877280d3e.pdf","sourceUrl":"https://drive.google.com/file/d/11CjvWmrS4poAVMmBBWnsJPRCmD1-JkRJ/view","version":"new","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":7,"sourceRange":{"startPage":7,"startY":568.74,"endPage":7,"endY":584.34},"sourceKind":"changes","originalOrdinal":"7","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":4,"excerpts":[{"page":7,"src":"./assets/environment/env838-14d19633ac31e92a-7.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=75"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-7ae32c9dc4e92bef","subject":"环境学导论","chapter":"第4章 大气环境","originalChapter":"第4章 大气环境","originalChapterNumber":4,"section":"课后习题","originalSection":"课后习题","category":"exercise","title":"“温室效应”的原理和机制是什么？","question":"“温室效应”的原理和机制是什么？","type":"简答题","answer":"太阳辐射主要以短波形式进入地表—大气系统，地表吸收能量后释放长波红外辐射。CO₂、CH₄、水汽等温室气体吸收部分长波辐射并向各方向再辐射，减少地表向外净散热，使地表和低层大气维持较高温度。\n自然温室效应是地球适宜生命的重要条件；人为增加温室气体，会改变辐射收支，造成增暖，并通过水汽、冰雪反照率等反馈进一步影响气候。\n要点：大气对不同波长辐射的作用不同，关键是长波辐射交换和能量平衡，不能只用“挡住热空气”解释。","source":"环导变动137718728584015123.1eae00877280d3e.pdf","sourceUrl":"https://drive.google.com/file/d/11CjvWmrS4poAVMmBBWnsJPRCmD1-JkRJ/view","version":"new","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":7,"sourceRange":{"startPage":7,"startY":584.34,"endPage":7,"endY":599.94},"sourceKind":"changes","originalOrdinal":"8","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":4,"excerpts":[{"page":7,"src":"./assets/environment/env838-7ae32c9dc4e92bef-7.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=75"},{"title":"NASA：温室效应的原理","url":"https://science.nasa.gov/climate-change/faq/what-is-the-greenhouse-effect/","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-bd8d14b6413f732f","subject":"环境学导论","chapter":"第4章 大气环境","originalChapter":"第4章 大气环境","originalChapterNumber":4,"section":"课后习题","originalSection":"课后习题","category":"exercise","title":"气候变化对地球生态系统的影响有哪些？请结合现实生活列举其中一种影响。","question":"气候变化对地球生态系统的影响有哪些？请结合现实生活列举其中一种影响。","type":"简答题","answer":"主要影响：①改变物种适生区、物候及迁徙时间，造成种间关系失配；②增加热浪、干旱、火灾及部分强降水风险，影响生态系统稳定性；③海平面上升损害滨海湿地等生境；④海洋增暖与酸化影响珊瑚等海洋生物；⑤改变水循环、农业生产和生态系统碳收支。\n实例：海洋热浪可造成珊瑚热应激和白化，持续或反复发生时，会降低珊瑚礁生物多样性及其渔业、海岸防护功能。\n答题可围绕“气候因子变化—生物响应—生态服务及人类影响”组织。","source":"环导变动137718728584015123.1eae00877280d3e.pdf","sourceUrl":"https://drive.google.com/file/d/11CjvWmrS4poAVMmBBWnsJPRCmD1-JkRJ/view","version":"new","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":7,"sourceRange":{"startPage":7,"startY":599.94,"endPage":7,"endY":631.17},"sourceKind":"changes","originalOrdinal":"9","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":4,"excerpts":[{"page":7,"src":"./assets/environment/env838-bd8d14b6413f732f-7.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=75"},{"title":"NASA：温室效应的原理","url":"https://science.nasa.gov/climate-change/faq/what-is-the-greenhouse-effect/","accessedOn":"2026-11-09"},{"title":"中国生物多样性保护战略与行动计划（2023—2030年）发布说明","url":"https://www.mee.gov.cn/xxgk/hjyw/202401/t20240118_1064111.shtml","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-4dd92010f2f9fc8a","subject":"环境学导论","chapter":"第4章 大气环境","originalChapter":"第4章 大气环境","originalChapterNumber":4,"section":"课后习题","originalSection":"课后习题","category":"exercise","title":"为了改善空气质量，个人应该怎么做？请列举两条具体建议。","question":"为了改善空气质量，个人应该怎么做？请列举两条具体建议。","type":"简答题","answer":"①绿色出行：优先步行、骑行和公共交通，合理合乘、减少不必要的机动车出行，降低燃油消耗及尾气排放。\n②节能与低VOCs消费：合理使用空调、减少能源浪费；装修或清洁时选择符合要求的低挥发产品，减少不必要的溶剂使用。\n还可做到不露天焚烧垃圾、秸秆，不违规燃放烟花，发现污染依法反馈。个人行为需要与产业、能源及交通治理配合，不能代替污染源的法定治理责任。","source":"环导变动137718728584015123.1eae00877280d3e.pdf","sourceUrl":"https://drive.google.com/file/d/11CjvWmrS4poAVMmBBWnsJPRCmD1-JkRJ/view","version":"new","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":7,"sourceRange":{"startPage":7,"startY":631.17,"endPage":7,"endY":646.77},"sourceKind":"changes","originalOrdinal":"10","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":4,"excerpts":[{"page":7,"src":"./assets/environment/env838-4dd92010f2f9fc8a-7.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=75"},{"title":"生态环境部：重点行业挥发性有机物综合治理方案","url":"https://www.mee.gov.cn/xxgk2018/xxgk/xxgk03/201907/t20190703_708395.html","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-5602d514143746be","subject":"环境学导论","chapter":"第4章 大气环境","originalChapter":"第4章 大气环境","originalChapterNumber":4,"section":"课后习题","originalSection":"课后习题","category":"exercise","title":"请列举大气保护的法律法规，并简要介绍其中一项法律法规。","question":"请列举大气保护的法律法规，并简要介绍其中一项法律法规。","type":"简答题","answer":"按2026年11月的现行法律背景，可列举生态环境法典、相关大气污染防治规章、排污许可管理法规及地方条例等。\n以生态环境法典为例：它将大气等污染防治纳入统一法律体系，强调源头预防、全过程控制，要求协同控制颗粒物、SO₂、NOₓ、VOCs等污染物和温室气体，并规定排放监管及法律责任。\n教材历史背景可列出环境保护法、大气污染防治法等；但生态环境法典已于2026年8月15日施行，包括这两部法律在内的相关旧法同时废止。考试回答历史修法问题与现行法问题时，应注明时间，避免混用。","source":"环导变动137718728584015123.1eae00877280d3e.pdf","sourceUrl":"https://drive.google.com/file/d/11CjvWmrS4poAVMmBBWnsJPRCmD1-JkRJ/view","version":"new","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":7,"sourceRange":{"startPage":7,"startY":646.77,"endPage":7,"endY":662.37},"sourceKind":"changes","originalOrdinal":"11","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":4,"excerpts":[{"page":7,"src":"./assets/environment/env838-5602d514143746be-7.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=75"},{"title":"生态环境部：2026年生态环境法典及施行说明","url":"https://www.mee.gov.cn/xxgk2018/xxgk/xxgk03/202604/t20260408_1148465.html","accessedOn":"2026-11-09"},{"title":"中华人民共和国生态环境法典","url":"https://www.mee.gov.cn/ywgz/fgbz/fl/202603/t20260313_1146496.shtml","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-177a123dda29e846","subject":"环境学导论","chapter":"第4章 大气环境","originalChapter":"第4章 大气环境","originalChapterNumber":4,"section":"课后习题","originalSection":"课后习题","category":"exercise","title":"请解释“碳中和”的概念和意义。","question":"请解释“碳中和”的概念和意义。","type":"简答题","answer":"碳中和是指在规定边界和时间尺度内，人为CO₂排放量与人为移除量达到净平衡。国家、地区或组织的核算边界及气体范围应明确；讨论所有温室气体净零时，要区分于仅CO₂的碳中和。\n实现路径首先是减少排放，包括节能提效、能源与产业低碳转型，再对难以避免的剩余排放采用经核证的碳汇或其他移除方式。\n意义：降低气候变化风险，推动技术创新与经济转型，带来空气污染协同减排，并促进能源系统长期可持续发展。碳中和并不等于任何活动都绝对没有排放。","source":"环导变动137718728584015123.1eae00877280d3e.pdf","sourceUrl":"https://drive.google.com/file/d/11CjvWmrS4poAVMmBBWnsJPRCmD1-JkRJ/view","version":"new","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":7,"sourceRange":{"startPage":7,"startY":662.37,"endPage":7,"endY":677.97},"sourceKind":"changes","originalOrdinal":"12","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":4,"excerpts":[{"page":7,"src":"./assets/environment/env838-177a123dda29e846-7.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=75"},{"title":"中国的能源转型白皮书（英文全文）","url":"https://english.www.gov.cn/archive/whitepaper/202408/29/content_WS66d012e8c6d0868f4e8ea52e.html","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-b27c0207b6999ce0","subject":"环境学导论","chapter":"第4章 大气环境","originalChapter":"第4章 大气环境","originalChapterNumber":4,"section":"课后习题","originalSection":"课后习题","category":"exercise","title":"什么是光化学烟雾？请简述它的产生原理和危害。","question":"什么是光化学烟雾？请简述它的产生原理和危害。","type":"简答题","answer":"光化学烟雾是NOₓ、VOCs等前体物在阳光作用下经过一系列光化学反应，形成以臭氧和其他氧化性物质为特征的污染现象。\n机理要点：NO₂光解参与臭氧生成；VOCs氧化形成的过氧自由基可使NO转化为NO₂，从而促使臭氧净累积，并生成醛类、过氧酰基硝酸酯等产物。高温、强日照及不利扩散条件有利于形成。\n危害：刺激眼睛和呼吸道，损伤植物、降低作物产量，破坏橡胶等材料，并影响区域空气质量。\n防治应根据臭氧生成的敏感性协同削减NOₓ与VOCs。","source":"环导变动137718728584015123.1eae00877280d3e.pdf","sourceUrl":"https://drive.google.com/file/d/11CjvWmrS4poAVMmBBWnsJPRCmD1-JkRJ/view","version":"new","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":7,"sourceRange":{"startPage":7,"startY":677.97,"endPage":7,"endY":693.57},"sourceKind":"changes","originalOrdinal":"13","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":4,"excerpts":[{"page":7,"src":"./assets/environment/env838-b27c0207b6999ce0-7.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=75"},{"title":"NASA：近地面臭氧的形成","url":"https://airquality.gsfc.nasa.gov/surface-level-ozone","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-278be2d9dd746e75","subject":"环境学导论","chapter":"第4章 大气环境","originalChapter":"第4章 大气环境","originalChapterNumber":4,"section":"课后习题","originalSection":"课后习题","category":"exercise","title":"请简述全球变暖对人类的影响。","question":"请简述全球变暖对人类的影响。","type":"简答题","answer":"①健康：增加高温暴露及热相关疾病风险，影响部分传染病传播条件，并可通过灾害和空气污染产生间接影响。\n②水与粮食：改变降水、径流和蒸散，影响水资源供需、农业产量及食品安全。\n③沿海与城市：海平面上升、风暴潮及极端降水风险影响居民、基础设施和财产。\n④经济社会：增加防灾、健康和基础设施维护成本，对脆弱地区及人群造成更大负担。\n⑤生态服务：森林、湿地、海洋等受损会削弱碳汇、供水和生计支持。\n应同时采取减缓与适应措施；具体区域的变化方向及程度需要依据监测和评估。","source":"环导变动137718728584015123.1eae00877280d3e.pdf","sourceUrl":"https://drive.google.com/file/d/11CjvWmrS4poAVMmBBWnsJPRCmD1-JkRJ/view","version":"new","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":7,"sourceRange":{"startPage":7,"startY":693.57,"endPage":7,"endY":709.17},"sourceKind":"changes","originalOrdinal":"14","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":4,"excerpts":[{"page":7,"src":"./assets/environment/env838-278be2d9dd746e75-7.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=75"},{"title":"NASA：温室效应的原理","url":"https://science.nasa.gov/climate-change/faq/what-is-the-greenhouse-effect/","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-46d5a279725fd6d4","subject":"环境学导论","chapter":"第4章 大气环境","originalChapter":"第4章 大气环境","originalChapterNumber":4,"section":"课后习题","originalSection":"课后习题","category":"exercise","title":"请简述颗粒污染物和气态污染物控制方法和设备。","question":"请简述颗粒污染物和气态污染物控制方法和设备。","type":"简答题","answer":"一、颗粒物控制：重力沉降去除较大颗粒；旋风除尘利用离心作用；袋式除尘利用过滤；电除尘利用荷电及电场力；湿式洗涤利用液滴捕集。设备选择取决于粒径、粉尘性质、温湿度和排放要求。\n二、气态污染物控制：吸收法使污染物转入液相；吸附法使其富集于固体表面；冷凝法适用于可回收组分；燃烧、催化及生物方法使其转化或降解。\n三、典型应用：SO₂采用脱硫，NOₓ采用低氮燃烧与SCR／SNCR，VOCs采用回收或适当氧化处理。\n还要处理废液、废吸附剂及反应副产物，防止污染转移。","source":"环导变动137718728584015123.1eae00877280d3e.pdf","sourceUrl":"https://drive.google.com/file/d/11CjvWmrS4poAVMmBBWnsJPRCmD1-JkRJ/view","version":"new","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":7,"sourceRange":{"startPage":7,"startY":709.17,"endPage":7,"endY":724.77},"sourceKind":"changes","originalOrdinal":"15","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":4,"excerpts":[{"page":7,"src":"./assets/environment/env838-46d5a279725fd6d4-7.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=75"},{"title":"生态环境部：重点行业挥发性有机物综合治理方案","url":"https://www.mee.gov.cn/xxgk2018/xxgk/xxgk03/201907/t20190703_708395.html","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-99c4e706e24bce36","subject":"环境学导论","chapter":"第4章 大气环境","originalChapter":"第4章 大气环境","originalChapterNumber":4,"section":"课后习题","originalSection":"课后习题","category":"exercise","title":"影响大气污染物的地理因素有哪些？","question":"影响大气污染物的地理因素有哪些？","type":"简答题","answer":"①地形：山谷、盆地及复杂地形可限制通风，造成污染滞留；山坡和谷地风又可能改变输送路径。\n②下垫面：城市建筑、地表粗糙度、植被与水体影响湍流、热量交换和局地环流。\n③海陆位置：海陆风有时有利于通风，也可能造成污染往返输送；沿海不能被简单视为“不会积累污染”。\n④地理位置与气候：纬度、季节及区域环流影响日照、降水、温度和扩散条件。\n⑤相邻区域与源布局：污染源位置、输送通道及上风向排放共同决定区域影响。\n应将地理条件与风速、稳定度、逆温等气象因素结合分析。","source":"环导变动137718728584015123.1eae00877280d3e.pdf","sourceUrl":"https://drive.google.com/file/d/11CjvWmrS4poAVMmBBWnsJPRCmD1-JkRJ/view","version":"new","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":7,"sourceRange":{"startPage":7,"startY":724.77,"endPage":7,"endY":740.36},"sourceKind":"changes","originalOrdinal":"16","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":4,"excerpts":[{"page":7,"src":"./assets/environment/env838-99c4e706e24bce36-7.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=75"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-0355c35fd994da77","subject":"环境学导论","chapter":"第4章 大气环境","originalChapter":"第4章 大气环境","originalChapterNumber":4,"section":"课后习题","originalSection":"课后习题","category":"exercise","title":"请简述大气污染综合防治的含义和措施。","question":"请简述大气污染综合防治的含义和措施。","type":"简答题","answer":"含义：把污染源控制、区域规划、能源和产业调整、工程治理与管理措施结合起来，在一定区域内整体改善空气质量，而非只治理单个烟囱。\n措施：①优化能源结构，推广节能及清洁能源；②调整产业、交通和空间布局；③实施清洁生产及多污染物协同减排；④治理燃煤、工业、机动车、扬尘和VOCs等重点源；⑤健全监测、预警、排污许可及执法；⑥加强区域联防联控，防范跨界输送；⑦完善公众参与和重污染应急措施。\n评价应关注环境质量改善、暴露降低和持续运行效果。","source":"环导变动137718728584015123.1eae00877280d3e.pdf","sourceUrl":"https://drive.google.com/file/d/11CjvWmrS4poAVMmBBWnsJPRCmD1-JkRJ/view","version":"new","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":7,"sourceRange":{"startPage":7,"startY":740.36,"endPage":8,"endY":73.45},"sourceKind":"changes","originalOrdinal":"17","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":4,"excerpts":[{"page":7,"src":"./assets/environment/env838-0355c35fd994da77-7.webp"},{"page":8,"src":"./assets/environment/env838-0355c35fd994da77-8.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=75"},{"title":"生态环境部：重点行业挥发性有机物综合治理方案","url":"https://www.mee.gov.cn/xxgk2018/xxgk/xxgk03/201907/t20190703_708395.html","accessedOn":"2026-11-09"},{"title":"中华人民共和国生态环境法典","url":"https://www.mee.gov.cn/ywgz/fgbz/fl/202603/t20260313_1146496.shtml","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-2b99d51813894316","subject":"环境学导论","chapter":"第4章 大气环境","originalChapter":"第4章 大气环境","originalChapterNumber":4,"section":"课后习题","originalSection":"课后习题","category":"exercise","title":"臭氧层破坏会带来什么危害？应对措施是什么？","question":"臭氧层破坏会带来什么危害？应对措施是什么？","type":"简答题","answer":"危害：平流层臭氧减少使到达地表的UV-B增加，可能增加皮肤和眼部损伤风险，影响植物生长、水生初级生产及部分材料的寿命。\n原因：部分含氯、含溴的消耗臭氧层物质进入平流层后释放活性卤素，催化臭氧分解。\n对策：履行蒙特利尔议定书及相关国际安排，淘汰受控消耗臭氧层物质，采用合适替代技术，管理制冷剂泄漏及废弃设备回收，加强监测和公众防护。\n应区分平流层保护性臭氧与近地面污染性臭氧，也应区分臭氧层破坏与温室效应。","source":"环导变动137718728584015123.1eae00877280d3e.pdf","sourceUrl":"https://drive.google.com/file/d/11CjvWmrS4poAVMmBBWnsJPRCmD1-JkRJ/view","version":"new","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":8,"sourceRange":{"startPage":8,"startY":73.45,"endPage":8,"endY":89.05},"sourceKind":"changes","originalOrdinal":"18","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":4,"excerpts":[{"page":8,"src":"./assets/environment/env838-2b99d51813894316-8.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=75"},{"title":"NASA：近地面臭氧的形成","url":"https://airquality.gsfc.nasa.gov/surface-level-ozone","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-6b8b5e8501d67dd5","subject":"环境学导论","chapter":"第4章 大气环境","originalChapter":"第4章 大气环境","originalChapterNumber":4,"section":"课后习题","originalSection":"课后习题","category":"exercise","title":"我国CO₂减排面临的挑战是什么？可以采取什么控制措施实现CO₂的持续减排？","question":"我国CO₂减排面临的挑战是什么？可以采取什么控制措施实现CO₂的持续减排？","type":"简答题","answer":"挑战：①能源需求和产业规模较大；②煤炭在能源结构中仍有重要地位；③钢铁、水泥、化工等行业深度减排困难；④可再生能源并网、储能、基础设施与技术成本仍有约束；⑤地区发展及资源禀赋差异较大。\n措施：节能提效并抑制不合理高耗能需求；发展非化石能源和新型电力系统；推动工业、建筑、交通电气化及低碳工艺；完善碳市场、核算与标准；在适用领域发展CCUS；保护提升生态系统碳汇，并推动公正、有序的转型。\n持续减排要同时关注排放总量、强度和产业结构，避免只靠末端抵消。","source":"环导变动137718728584015123.1eae00877280d3e.pdf","sourceUrl":"https://drive.google.com/file/d/11CjvWmrS4poAVMmBBWnsJPRCmD1-JkRJ/view","version":"new","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":8,"sourceRange":{"startPage":8,"startY":89.05,"endPage":8,"endY":125.77},"sourceKind":"changes","originalOrdinal":"19","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":4,"excerpts":[{"page":8,"src":"./assets/environment/env838-6b8b5e8501d67dd5-8.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=75"},{"title":"中国的能源转型白皮书（英文全文）","url":"https://english.www.gov.cn/archive/whitepaper/202408/29/content_WS66d012e8c6d0868f4e8ea52e.html","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-49db5e0c838369c9","subject":"环境学导论","chapter":"第4章 大气环境","originalChapter":"第4章 大气环境","originalChapterNumber":4,"section":"课后习题","originalSection":"课后习题","category":"exercise","title":"VOCs 末端治理的主要技术有哪些？","question":"VOCs 末端治理的主要技术有哪些？","type":"简答题","answer":"①吸附：利用活性炭、沸石等富集VOCs，常与脱附回收或氧化组合；需防吸附剂失效和着火。\n②吸收：用适宜液体溶剂吸收，适合相容性好、可回收的组分，并处理废液。\n③冷凝：降低温度使VOCs冷凝回收，通常更适合较高浓度、具有回收价值的废气。\n④氧化：热力燃烧、RTO、催化氧化或RCO，使有机物转化，须满足安全、温度与停留时间等条件。\n⑤生物处理：适合某些低浓度、易生物降解且不抑制微生物的废气。\n末端设施之前必须做好源头替代、密闭收集及过程控制，不能只看设备名称判断治理有效性。","source":"环导变动137718728584015123.1eae00877280d3e.pdf","sourceUrl":"https://drive.google.com/file/d/11CjvWmrS4poAVMmBBWnsJPRCmD1-JkRJ/view","version":"new","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":8,"sourceRange":{"startPage":8,"startY":125.77,"endPage":8,"endY":185.77},"sourceKind":"changes","originalOrdinal":"20","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":4,"excerpts":[{"page":8,"src":"./assets/environment/env838-49db5e0c838369c9-8.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=75"},{"title":"生态环境部：重点行业挥发性有机物综合治理方案","url":"https://www.mee.gov.cn/xxgk2018/xxgk/xxgk03/201907/t20190703_708395.html","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-dfae2954c3073509","subject":"环境学导论","chapter":"第4章 大气环境","originalChapter":"第7章 物理环境","originalChapterNumber":7,"section":"第4节 大气污染防治","originalSection":"第2节","category":"supplement","title":"温室气体CO2 固定和捕集技术","question":"温室气体CO2 固定和捕集技术","type":"简答题","answer":"（1）CO₂固定技术\nCO₂在特殊催化体系下，与其他化学原料发生化学反应，从而可固定为高分\n子化合物。该技术的关键是利用适当的催化体系使惰性CO₂活化，从而作为碳或\n碳氢资源加以利用。目前，CO₂的活化方式主要有生物活化、配位活化、光化学\n辐射活化、电化学还原活化、热解活化及化学还原活化等。\n（2）CO₂捕集技术\nCO₂的捕集和封存（CCS）是利用吸附、吸收、低温及膜系统等较为成熟的\n工艺技术将废气中的CO₂捕集下来，并进行长期或永久性的储存。目前，正在大\n力开发的碳捕集技术主要有三种，即燃烧后捕集、燃烧前捕集和富氧燃烧捕集。\n① 燃烧后捕集，指利用化学吸收剂的CO₂吸收性能，在化石燃料燃烧后的\n烟气中分离捕集CO₂。\n② 燃烧前捕集，指化石燃料在燃烧前分离捕集CO₂，该技术被寄望与整体\n煤气化联合循环电厂（IGCC）整合，以实现高效、低碳的绿色能源转换。\n③ 富氧燃烧捕集，指化石燃料在接近纯氧的环境中燃烧，并辅以烟气循环，\n该技术得到的烟气主要成分为CO₂和H₂O。","source":"环导变动137718728584015123.1eae00877280d3e.pdf","sourceUrl":"https://drive.google.com/file/d/11CjvWmrS4poAVMmBBWnsJPRCmD1-JkRJ/view","version":"new","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["变动PDF标为第七章第二节；按CO₂治理内容映射至大气环境第四节，需核对原书。"],"verified":false,"page":12,"sourceRange":{"startPage":12,"startY":447.42,"endPage":13,"endY":213.01},"sourceKind":"changes","originalOrdinal":"6","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":4,"excerpts":[{"page":12,"src":"./assets/environment/env838-dfae2954c3073509-12.webp"},{"page":13,"src":"./assets/environment/env838-dfae2954c3073509-13.webp"}]},{"id":"env838-53051b75fe5b7577","subject":"环境学导论","chapter":"第5章 土壤的组成和基本性质","originalChapter":"第5章 土壤的组成和基本性质","originalChapterNumber":5,"section":"第1节 土壤的组成和基本性质","originalSection":"第1节 土壤的组成和基本性质","category":"knowledge","title":"土壤的定义","question":"土壤的定义","type":"简答题","answer":"土壤是指处于岩石圈最外层可支持植物和微生物生长繁殖的疏\n松部分。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2004],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":102,"sourceRange":{"startPage":102,"startY":112.06,"endPage":102,"endY":246.84},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":["2004( 名, 【重要程度: 】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":5,"excerpts":[{"page":102,"src":"./assets/environment/env838-53051b75fe5b7577-102.webp"}]},{"id":"env838-c3d9a4df9da873da","subject":"环境学导论","chapter":"第5章 土壤的组成和基本性质","originalChapter":"第5章 土壤的组成和基本性质","originalChapterNumber":5,"section":"第1节 土壤的组成和基本性质","originalSection":"第1节 土壤的组成和基本性质","category":"knowledge","title":"土壤的组成","question":"土壤的组成","type":"简答题","answer":"土壤的组成课大致分为土壤固相、土壤液相、土壤气相。\n进一步说土壤是由岩石风化而成的土壤矿物质、动植物和微生物\n残体腐解产生的土壤有机质、土壤生物(固相物质)以及水分(液\n相物质) 、空气(气相物质)、氧化的腐殖质等组成。\n图5-1土壤的组成思维导图\n学长提示 : 2020 年考过一个填空题 ， 属于环境化学的范畴 ， 土壤中两个最活跃的组分\n是土壤胶体和土壤微生物 ， 尽管现在不涉及环境化学了 ， 但这部分是与环导重合的 ，\n作为一个拓展点给大家科普一下 。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":1,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。","含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":102,"sourceRange":{"startPage":102,"startY":246.84,"endPage":103,"endY":156.57},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":["【重要程度: ★☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":5,"excerpts":[{"page":102,"src":"./assets/environment/env838-c3d9a4df9da873da-102.webp"},{"page":103,"src":"./assets/environment/env838-c3d9a4df9da873da-103.webp"}]},{"id":"env838-4b2fd51653fe045e","subject":"环境学导论","chapter":"第5章 土壤的组成和基本性质","originalChapter":"第5章 土壤的组成和基本性质","originalChapterNumber":5,"section":"第1节 土壤的组成和基本性质","originalSection":"第1节 土壤的组成和基本性质","category":"knowledge","title":"土壤的形成","question":"土壤的形成","type":"简答题","answer":"土壤的最初来源是在地球形成以后，地壳表面坚硬的岩石在漫长\n的地质年代中，经过极其复杂的风化过程和成土过程而形成的。岩石\n或矿物要变成土壤，需经历两个过程。首先，由岩石、矿物风化分解\n，产生土壤母质。然后，土壤母质经成土过程形成土壤。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":0,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":103,"sourceRange":{"startPage":103,"startY":156.57,"endPage":103,"endY":358.48},"sourceKind":"original","originalOrdinal":"3","sourceMetadata":["【重要程度: ☆☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":5,"excerpts":[{"page":103,"src":"./assets/environment/env838-4b2fd51653fe045e-103.webp"}]},{"id":"env838-8e7d3d79092e7d54","subject":"环境学导论","chapter":"第5章 土壤的组成和基本性质","originalChapter":"第5章 土壤的组成和基本性质","originalChapterNumber":5,"section":"第1节 土壤的组成和基本性质","originalSection":"第1节 土壤的组成和基本性质","category":"knowledge","title":"土壤的粒级分组","question":"土壤的粒级分组","type":"简答题","answer":"颗粒名称 粒径/ mm 颗检名称 粒径/  mm\n石块 枌粒\n石砾 粗粉粒 0.05~0.01\n粗砾 10~3 细粉粒 0.01~0.005\n细砾 3~1 黏粒\n砂粒 粗黏粒 0.005~0.001\n粗砂砾 1~0.25 细粘粒 <0.001\n细砂砾 0.25~0.05\n矿物成分 理化特性\n多为岩石碎块，直径大于1mm。土壤中含石块和石砾多时，其孔隙过大，\n石块和石砾\n水和养分易流失\n王要为原生矿物，大多为石英、长石、云母、角闪石等，其中以石英为主，\n砂砾 粒径为1~0，05mm。土壤含砂砾多时，孔隙大，通气和透水性强，毛细管\n水上升高度很低(小于33cm)，保水保肥能力弱，营养元素合量少\n主要为次生矿物，粒径小于0.001mm。含黏粒多的土壤，营养元素含量丰\n黏粒\n富，团聚能力较强，有良好的保水保肥能力，但土壤的通气和透水性较差\n又称面砂，是原生矿物与次生矿物的混合体，粒径为0.05~0.005 mm，在\n粉粒 黄土中含量较多。粉粒的物理及化学性状介于砂粒与黏粒之间，团聚、胶结\n性差，分散性强，保水保肥能力较好。\n图5-2土壤粒级分组","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":103,"sourceRange":{"startPage":103,"startY":358.48,"endPage":104,"endY":75.93},"sourceKind":"original","originalOrdinal":"4","sourceMetadata":["【重要程度："],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":5,"excerpts":[{"page":103,"src":"./assets/environment/env838-8e7d3d79092e7d54-103.webp"},{"page":104,"src":"./assets/environment/env838-8e7d3d79092e7d54-104.webp"}]},{"id":"env838-ed7b2ee8322ad568","subject":"环境学导论","chapter":"第5章 土壤的组成和基本性质","originalChapter":"第5章 土壤的组成和基本性质","originalChapterNumber":5,"section":"第1节 土壤的组成和基本性质","originalSection":"第1节 土壤的组成和基本性质","category":"knowledge","title":"土壤的胶体性质","question":"土壤的胶体性质","type":"简答题","answer":"①土壤胶体具有巨大的比表面和表面能\n比表面是单位质量物质的表面积。一定体积的物质被分割时，随\n着颗粒数的增多，比表面显著地增大。物质的比表面越大，表面能也\n越大。\n②土壤胶体的双电层结构\n土壤胶体微粒具有双电层，微粒的内部称微粒核，一般带负电荷\n，形成一个负离子层，同时电性吸引作用其外部形成一个正离子层。\n图 5-3 土壤胶体双电层结构示意图\n③土壤胶体的凝聚性和分散性\n为减少表面能，胶体具有互相吸引、凝聚的趋势。但在土壤溶液\n中，胶体常带负电荷，即具有负的电动电位，胶体微粒又因相同电荷\n而相互排斥，电动电位越高，相互排斥力越强，胶体微粒呈现出的分\n散性也越强。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。","含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":104,"sourceRange":{"startPage":104,"startY":75.93,"endPage":105,"endY":72.34},"sourceKind":"original","originalOrdinal":"5","sourceMetadata":["【重要程度："],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":5,"excerpts":[{"page":104,"src":"./assets/environment/env838-ed7b2ee8322ad568-104.webp"},{"page":105,"src":"./assets/environment/env838-ed7b2ee8322ad568-105.webp"}]},{"id":"env838-74d1fd21d3e71a5e","subject":"环境学导论","chapter":"第5章 土壤的组成和基本性质","originalChapter":"第5章 土壤的组成和基本性质","originalChapterNumber":5,"section":"第1节 土壤的组成和基本性质","originalSection":"第1节 土壤的组成和基本性质","category":"knowledge","title":"土壤的离子吸附与交换","question":"土壤的离子吸附与交换","type":"简答题","answer":"土壤胶体以其巨大的比表面积和带电性，使土壤具有吸附性。土\n壤颗粒表面既能通过静电吸附的离子与溶液中的离子进行交换反应，\n也能通过共价键与溶液中的离子发生配位吸附。分为阳离子交换吸附\n和阴离子交换吸附。\n土壤胶体的阳离子交换吸附是指土壤胶体吸附的阳离子与土壤\n溶液中的阳离子进行交换，阳离子交换过程是一种可逆过程，离子与\n离子之间进行等价交换并遵循质量作用定律，可交换性阳离子分为盐\n基离子和致酸离子。土壤胶体的阴离子交换吸附是指带正电荷的胶体\n所吸附的阴离子与溶液中阴离子的交换作用。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":105,"sourceRange":{"startPage":105,"startY":72.34,"endPage":105,"endY":417.84},"sourceKind":"original","originalOrdinal":"6","sourceMetadata":["【重要程度："],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":5,"excerpts":[{"page":105,"src":"./assets/environment/env838-74d1fd21d3e71a5e-105.webp"}]},{"id":"env838-bee84f52d5529bdb","subject":"环境学导论","chapter":"第5章 土壤的组成和基本性质","originalChapter":"第5章 土壤的组成和基本性质","originalChapterNumber":5,"section":"第1节 土壤的组成和基本性质","originalSection":"第1节 土壤的组成和基本性质","category":"knowledge","title":"土壤的酸度","question":"土壤的酸度","type":"简答题","answer":"土壤的酸度是土壤的重要理化性质之一，可分为活性酸度和潜\n性酸度两类。\n[1] 活性酸度\n活性酸度是土壤中氢离子浓度的直接反映，又称有效酸度，通常\n用pH表示。土壤溶液中氢离子的来源是土壤中 溶于水形成的碳酸\n和有机物质分解产生的有机酸，土壤中矿物质氧化产生的无机酸(如\n硝酸、硫酸和磷酸等)以及大气污染形成的大气酸沉降。\n[2] 潜性酸度\n潜性酸度的来源是土壤胶体吸附的可代换性 和 。 离子处于\n吸附状态时不显酸性，当通过离子交换进入土壤后，可增加土壤 的\n浓度。\n①代换性酸度\n用过量中性盐(如NaCl或KCI)溶液淋洗土壤。溶液中金属离子\n与土壤中 和 发生离子交换作用而表现出的酸度。即\n土壤胶体—H~+KCl——土壤胶体—K~+HCl\n②水解性酸度\n用弱酸强碱盐(如醋酸钠)淋洗土壤，溶液中金属离子可以将土\n壤胶体吸附的 , 代换出来，同时生成某弱酸(醋酸)。\n土壤潜性酸是活性酸的主要来源，它们始终处于动态平衡之中，\n属于一个体系。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2019],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":105,"sourceRange":{"startPage":105,"startY":417.84,"endPage":106,"endY":355.35},"sourceKind":"original","originalOrdinal":"7","sourceMetadata":["2019 (填—酸度的类别)，【重要程度："],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":5,"excerpts":[{"page":105,"src":"./assets/environment/env838-bee84f52d5529bdb-105.webp"},{"page":106,"src":"./assets/environment/env838-bee84f52d5529bdb-106.webp"}]},{"id":"env838-c0a8aef7fc5ffd42","subject":"环境学导论","chapter":"第5章 土壤的组成和基本性质","originalChapter":"第5章 土壤的组成和基本性质","originalChapterNumber":5,"section":"第1节 土壤的组成和基本性质","originalSection":"第1节 土壤的组成和基本性质","category":"knowledge","title":"土壤的碱度","question":"土壤的碱度","type":"简答题","answer":"土壤溶液中 的主要来源是碱金属(Na 、K) 和碱土金属(Ca\n、Mg)的碳酸盐与碳酸氢盐的水解作用。碳酸盐碱度与重碳酸盐碱度\n的总和称为土壤总碱度，是衡量土壤碱性强弱的核心指标，可采用中\n和滴定法进行测定。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":106,"sourceRange":{"startPage":106,"startY":355.35,"endPage":106,"endY":549.65},"sourceKind":"original","originalOrdinal":"8","sourceMetadata":["【重要程度："],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":5,"excerpts":[{"page":106,"src":"./assets/environment/env838-c0a8aef7fc5ffd42-106.webp"}]},{"id":"env838-fcd4533d05a21b76","subject":"环境学导论","chapter":"第5章 土壤的组成和基本性质","originalChapter":"第5章 土壤的组成和基本性质","originalChapterNumber":5,"section":"第1节 土壤的组成和基本性质","originalSection":"第1节 土壤的组成和基本性质","category":"knowledge","title":"土壤的缓冲性能","question":"土壤的缓冲性能","type":"简答题","answer":"土壤的缓冲性能是指土壤具有缓和其酸碱度发生激烈变化的能\n力，它可以保持土壤反应的相对稳定，为植物生长和土壤生物的活动\n创造比较稳定的生活环境。\n[1] 土壤溶液的缓冲作用\n土壤溶液中含有碳酸、硅酸、磷酸、腐殖酸和其他有机酸等弱酸\n及其盐类，构成一个良好的缓冲体系，对酸碱具有缓冲作用。\n[2] 土壤胶体的缓冲作用\n土壤胶体吸附有各种阳离子，其中盐基离子和氢离子能分别对酸\n和碱起缓冲作用。\n①对酸的缓冲作用(以M代表盐基离子)\n土壤胶体—M+HCl ═ 土壤胶体—H- ↑MCl\n②对碱的缓冲作用\n土壤胶体—H+MOH 土壤胶体 M+H ₂O\n土壤胶体的数量和盐基代换量越大，土壤的缓冲性能就越强。在\n代换量相等的条件下，盐基饱和度愈高，土壤对酸的缓冲能力愈大；反\n之，盐基饱和度愈低，土壤对碱的缓冲能力愈大。\n[3] 铝离子对碱的缓冲作用\npH<5 的酸性土壤里，聚合的铝离子团越大，解离出的H离子越多\n，对碱的缓冲能力越强。在pH>5.5 时，铝离子开始形成A1 ( OH )，\n沉淀，失去缓冲能力。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2019,2022],"needsReview":false,"reviewReasons":[],"verified":false,"page":106,"sourceRange":{"startPage":106,"startY":549.65,"endPage":107,"endY":544.83},"sourceKind":"original","originalOrdinal":"9","sourceMetadata":["2019、2022(填—分类) , 【重要程度:"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":5,"excerpts":[{"page":106,"src":"./assets/environment/env838-fcd4533d05a21b76-106.webp"},{"page":107,"src":"./assets/environment/env838-fcd4533d05a21b76-107.webp"}]},{"id":"env838-f01ee2324aaa366e","subject":"环境学导论","chapter":"第5章 土壤的组成和基本性质","originalChapter":"第5章 土壤的组成和基本性质","originalChapterNumber":5,"section":"第1节 土壤的组成和基本性质","originalSection":"第1节 土壤的组成和基本性质","category":"knowledge","title":"土壤退化","question":"土壤退化","type":"简答题","answer":"土壤退化是指在各种自然因素特别是人为因素影响下，导致土壤\n的农业生产能力或土地利用和环境调控潜力下降(包括暂时性的和永\n久性的)，即土壤质量及其可持续性下降，甚至完全丧失其物理、化\n学和生物学特征的过程，包括过去的、现在的和将来的退化过程。\n土壤退化的主要类型有土壤侵蚀、荒漠化、土壤盐碱化和土壤潜\n育化等。\n①土壤侵蚀。土壤侵蚀是指土壤在水力、风力、冻融、重力等外\n力作用下，被破坏、剥蚀、搬运和沉积的过程。主要类型有水力侵蚀\n、风力侵蚀、重力侵蚀和冻融侵蚀等。\n②荒漠化。荒漠化指由于气候变化和人类不合理的经济活动使干\n旱、半干旱和具有干旱灾害的半湿润地区发生的土地退化。荒漠化是\n一个复杂的土地退化过程，既包含土壤退化，也包括土壤生态与环境\n的退化。\n③土壤盐碱化。土壤盐碱化又称土壤盐渍化或土壤盐化，指盐分\n不断向土壤表层聚积形成盐渍土地的自然地质过程。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2009,2010],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":107,"sourceRange":{"startPage":107,"startY":544.83,"endPage":108,"endY":323.94},"sourceKind":"original","originalOrdinal":"10","sourceMetadata":["2009(简、2010(简, 【重要程度:"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":5,"excerpts":[{"page":107,"src":"./assets/environment/env838-f01ee2324aaa366e-107.webp"},{"page":108,"src":"./assets/environment/env838-f01ee2324aaa366e-108.webp"}]},{"id":"env838-92b5f76e8ada06b5","subject":"环境学导论","chapter":"第5章 土壤的组成和基本性质","originalChapter":"第5章 土壤的组成和基本性质","originalChapterNumber":5,"section":"第2节 土壤污染与自净","originalSection":"第2节 土壤污染与自净","category":"knowledge","title":"土壤的功能","question":"土壤的功能","type":"简答题","answer":"①第一，土壤具有肥力，也就是具有供应和协调植物生长所需要\n营养条件( 水分和养分) 和环境条件(温度和空气)的能力；\n②第二，土壤具有同化和代谢外界输入物质的能力，输入的物质\n在土壤中经过复杂的迁移转化，再向外界输出。\n土壤的这两个功能是相辅相成的，使其成为一种宝贵的资源。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":2,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":108,"sourceRange":{"startPage":108,"startY":365.01,"endPage":108,"endY":590.36},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":["【重要程度: ★★☆☆☆))"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":5,"excerpts":[{"page":108,"src":"./assets/environment/env838-92b5f76e8ada06b5-108.webp"}]},{"id":"env838-bf76581f0ab0956e","subject":"环境学导论","chapter":"第5章 土壤的组成和基本性质","originalChapter":"第5章 土壤的组成和基本性质","originalChapterNumber":5,"section":"第2节 土壤污染与自净","originalSection":"第2节 土壤污染与自净","category":"knowledge","title":"土壤污染的概念","question":"土壤污染的概念","type":"简答题","answer":"人类在生产和生活活动中产生的废水、废气、废渣等三废物质直\n接向土壤中排放或通过大气、水、生物等生物介质间接地向土壤中排\n放，当排入土壤的三废物质破坏了土壤系统原来的平衡，引起了土壤\n成分、结构和功能的改变，即发生土壤污染。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2005,2011,2014,2026],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":108,"sourceRange":{"startPage":108,"startY":590.36,"endPage":109,"endY":72.0},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":["2005(名、2011(名、2014(名、2026(名,【重要程度:"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":5,"excerpts":[{"page":108,"src":"./assets/environment/env838-bf76581f0ab0956e-108.webp"},{"page":109,"src":"./assets/environment/env838-bf76581f0ab0956e-109.webp"}]},{"id":"env838-9d5f35f2e8f44c50","subject":"环境学导论","chapter":"第5章 土壤的组成和基本性质","originalChapter":"第5章 土壤的组成和基本性质","originalChapterNumber":5,"section":"第2节 土壤污染与自净","originalSection":"第2节 土壤污染与自净","category":"knowledge","title":"土壤中污染物质的净化机制","question":"土壤中污染物质的净化机制","type":"简答题","answer":"污染物质进入土壤后，与土壤中固相、液相、气相之间发生一系\n列的物理、化学、物理化学和生物化学反应。\n①物理过程。利用土壤疏松多孔、多相等特点，通过挥发、稀释\n、扩散等物理过程使污染物移出土壤体外。其净化效果取决于土壤的\n温度、湿度，土壤的质地和结构，同时也与污染物的性质有关。\n②化学过程。包括溶解、氧化还原、化学降解和化学沉降作用，\n使污染物迁出土壤之外或者难溶物不被植物吸收，而不改变土壤的结\n构和功能。土壤中常常含有自由氧气、高价金属离子等氧化剂以及有\n机物质、低价金属离子等还原剂，而能使可变价的污染物质因变价发\n生氧化还原反应，并配合络合、螯合作用而溶解迁移。\n③物理化学过程。主要是通过胶体的吸附和解吸作用，使污染物\n在土壤中迁移转化；\n④生物化学过程。主要依靠土壤生物的主体，即土壤微生物，使\n土壤中的有机污染物质发生分解或化合作用而转化的过程。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":1,"pastExamYears":[2003,2004],"needsReview":false,"reviewReasons":[],"verified":false,"page":109,"sourceRange":{"startPage":109,"startY":72.0,"endPage":109,"endY":547.76},"sourceKind":"original","originalOrdinal":"3","sourceMetadata":["2003(名、2004(简, 【重要程度:★☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":5,"excerpts":[{"page":109,"src":"./assets/environment/env838-9d5f35f2e8f44c50-109.webp"}]},{"id":"env838-5d7e37922a4bfbc9","subject":"环境学导论","chapter":"第5章 土壤的组成和基本性质","originalChapter":"第5章 土壤的组成和基本性质","originalChapterNumber":5,"section":"第3节 土壤污染的危害","originalSection":"第3节 土壤污染的危害","category":"knowledge","title":"土壤污染的发生类型","question":"土壤污染的发生类型","type":"简答题","answer":"根据土壤环境主要污染物的来源和土壤环境污染的途径，可把土\n壤污染的发生类型分成水质污染型、大气污染型、固体废物污染型、\n农业污染型以及综合污染型。\n[1] 水质污染型\n水质污染型是指工矿企业废水、城市生活污水、农村生活污水和\n养殖废水等未经处理就直接排放到水体里，使水体遭到污染，这些水\n体再灌溉到农田里，造成土壤污染的过程。污水灌溉中的土壤污染物\n一般集中于土壤表层，但随着污灌时间的延长，污染物也会由土体表\n层向下部主体扩散和迁移，以致达到地下水深度而对地下水造成污染\n。\n[2] 大气污染型\n大气污染型主要指大气中的污染物通过干湿沉降的方式进入土\n壤，导致土壤污染的类型。其特点是以大气污染源为中心呈环状或带\n状分布，长轴沿主风向伸展，污染的面积、程度和扩散的距离取决于\n污染物质的种类、性质、排放量、排放形式及风力大小等。主要污染\n物包括 、NO以及含重金属、放射性物质和有毒有机物的颗粒物等\n。由大气污染造成的土壤污染物质主要集中在土壤表层。\n[3] 农业污染型\n农业污染型是指由于农业生产的需要，不断地施用化肥和农药、\n堆肥等引起的土壤污染的类型。污染物主要来自施入土壤的化学农药\n和化肥，其污染程度与化肥、农药的数量、种类、施用方式及耕作方\n式等有关。残留在土壤中的农药和氮、磷等化合物在地面径流、地下\n水迁移或土壤风蚀时，会向其他环境转移，扩大污染范围，属于面源\n污染。\n[4] 固体废物污染型\n固体废物污染型主要是指工矿企业排出的尾矿、废渣、污泥和城\n市垃圾在地表堆放或处置过程中通过扩散、降水淋滤等直接或间接地\n影响土壤，造成土壤受污染的类型。污染特征属于点源性质，主要造\n成土壤环境的重金属污染以及油类、病原菌和某些有毒有害有机物的\n污染。\n[5] 综合污染型\n上述土壤污染类型是相互联系的，它们在一定的条件下可以相互\n转化。土壤污染往往是多源性的，对于同一区域受污染的土壤，污染\n源可能同时来自受污染的地面、水体和大气，或同时遭受固体废物和\n化肥农药的污染。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":0,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":109,"sourceRange":{"startPage":109,"startY":588.86,"endPage":111,"endY":276.41},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":["【重要程度:☆☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":5,"excerpts":[{"page":109,"src":"./assets/environment/env838-5d7e37922a4bfbc9-109.webp"},{"page":110,"src":"./assets/environment/env838-5d7e37922a4bfbc9-110.webp"},{"page":111,"src":"./assets/environment/env838-5d7e37922a4bfbc9-111.webp"}]},{"id":"env838-7fb386aab227bb5b","subject":"环境学导论","chapter":"第5章 土壤的组成和基本性质","originalChapter":"第5章 土壤的组成和基本性质","originalChapterNumber":5,"section":"第3节 土壤污染的危害","originalSection":"第3节 土壤污染的危害","category":"knowledge","title":"污染物在土壤中的迁移转化","question":"污染物在土壤中的迁移转化","type":"简答题","answer":"污染物进入土壤后，与各种土壤成分发生物理反应、化学反应和\n生化作用，主要包括扩散迁移、吸附解吸、沉淀溶解、络合解络、同\n化矿化和降解转化等。影响土壤中污染物迁移转化的因素，主要有污\n染物性质、土壤理化性质、生物性状以及与土壤相关的自然因素。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":1,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":111,"sourceRange":{"startPage":111,"startY":276.41,"endPage":111,"endY":478.56},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":["【重要程度:★☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":5,"excerpts":[{"page":111,"src":"./assets/environment/env838-7fb386aab227bb5b-111.webp"}]},{"id":"env838-c6e76602f8c4e4f7","subject":"环境学导论","chapter":"第5章 土壤的组成和基本性质","originalChapter":"第5章 土壤的组成和基本性质","originalChapterNumber":5,"section":"第3节 土壤污染的危害","originalSection":"第3节 土壤污染的危害","category":"knowledge","title":"土壤污染的危害","question":"土壤污染的危害","type":"简答题","answer":"[1] 土壤污染影响土壤的结构和生态功能\n污染物进入土壤或不合理使用农药和化肥会改变土壤酸碱性，引\n起土壤板结，使农作物减产。施入农田的农药，大部分会残留于土壤\n中。农药的使用虽然可抑制病虫害，但也对农作物及土壤微动物、土\n壤微生物、昆虫、鸟类甚至鱼类产生潜在的危害，由此使生物多样性\n降低，生态系统功能下降。\n[2] 影响农作物的品质和质量\n污染物会通过植物的吸收进入植物体内，并可长期累积富集，当\n污染物含量累积到一定量时，就会对农作物的品质和质量产生影响。\n[3] 造成严重的经济损失\n土壤污染造成的经济损失，尚缺乏系统的调查资料。有学者指出\n，美国因农药使用造成土壤污染而引起的经济损失达到81.23亿美元，\n而我国有可能更高。\n[4] 人类和动物的健康\n粮食、蔬菜和畜牧作物都直接或间接来自土壤，它们是人富食物\n的主要来源，污染物在作物体内积累，并通过食物链富集到人体和动\n物体内，危害人畜健康。土壤对人畜健康的影响很复杂，一般是间接\n的长期慢性影响。\n学长再次提示 ; 本书中大量出现类似于这种关于危害的综合性的说法 ， 即综合了很多\n章节的知识点 ， 比如环境污染的危害 ， 水体污染的危害等等 ， 对于这种类似的问题 ，\n大家只需要记住他们的框架 ， 把握住葵题的套路 ， 即便是没背到相应的知识点也知道\n大概的答题方向 ， 大概都是要涉及到人体的健康 ， 生物 〈 水生生物 、 陆生生物 ) 的健\n康 ， 环境 〈 水环境 、 土环境 、 大气环境 ) 的健康","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":0,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。","含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":111,"sourceRange":{"startPage":111,"startY":478.56,"endPage":112,"endY":445.48},"sourceKind":"original","originalOrdinal":"3","sourceMetadata":["【重要程度: ☆☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":5,"excerpts":[{"page":111,"src":"./assets/environment/env838-c6e76602f8c4e4f7-111.webp"},{"page":112,"src":"./assets/environment/env838-c6e76602f8c4e4f7-112.webp"}]},{"id":"env838-d359c646c13c0f10","subject":"环境学导论","chapter":"第5章 土壤的组成和基本性质","originalChapter":"第5章 土壤的组成和基本性质","originalChapterNumber":5,"section":"第4节 土壤污染的防治与修复","originalSection":"第4节 土壤污染的防治与修复","category":"knowledge","title":"化肥污染的防治","question":"化肥污染的防治","type":"简答题","answer":"①不要长期过量使用同一种肥料，掌握施肥时间、次数和用量，\n采用分层施肥、深施肥等方法减少化肥散失，提高肥料利用率；\n②化肥与有机肥配合使用，增强土壤保肥能力和化肥利用率，减\n少水分和养分流失，使土质疏松，防止土壤板结；\n③进行测土配方施肥，合理增加磷肥、钾肥和微肥的比重，通过\n土壤中磷、钾及各种微量元素的作用，降低农作物中硝酸盐的含量，\n提高农作物品；\n④制定防止化肥污染的法律法规和无公害农产品施肥技术规范，\n使农产品生产过程中肥料的使用有章可循、有法可依，有效控制化肥\n对土壤、水源和农产品的污染。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":1,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":112,"sourceRange":{"startPage":112,"startY":487.46,"endPage":113,"endY":170.47},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":["【重要程度:★☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":5,"excerpts":[{"page":112,"src":"./assets/environment/env838-d359c646c13c0f10-112.webp"},{"page":113,"src":"./assets/environment/env838-d359c646c13c0f10-113.webp"}]},{"id":"env838-9339def0f1db0f5f","subject":"环境学导论","chapter":"第5章 土壤的组成和基本性质","originalChapter":"第5章 土壤的组成和基本性质","originalChapterNumber":5,"section":"第4节 土壤污染的防治与修复","originalSection":"第4节 土壤污染的防治与修复","category":"knowledge","title":"农药污染的防治","question":"农药污染的防治","type":"简答题","answer":"①合理使用农药\n加强技术指导，科学合理使用农药，不仅可有效控制病虫草害，\n而且可减少农药的使用，减少浪费，最重要的是可避免农药残留超标\n②推广应用无公害农药\n大力研制高效、低毒、低残留的农药新品种，积极推广应用生物\n防治措施，大力发展生物高效农药。与常规农药相比，生物农药不仅\n杀虫范围广、效率高，而且使用安全，对人畜无毒害，对环境无污染\n，对作物无残留，不杀伤益虫，使害虫不产生抗药性，并且有助于作\n物品质的提高，促进作物早熟高产。同时，应研究残留农药的微生物\n降解菌剂，使农药残留降至限制值以下。\n③改变耕作制度\n通过土壤耕作改变土壤环境条件，可消除某些污染物的危害，如\n旱田改水田。DDT与六六六在旱田中的降解速度慢，积累明显，在水\n田中DDT的降解速度加快，利用这一性质实行水旱轮作，是减轻或消\n除农药污染的有效措施。\n④加强农药残留监测\n加强对农药的监督监测，将农药监测纳入日常的例行监测中，发\n挥环境管理的监督作用。开展全面、系统的农药残留监测工作，不仅\n-95。\n能够及时掌握农产品中农药残留的状况和规律，查找农药残留形成的\n原因，而且能为政府部门提供及时有效的数据，为政府职能部门制定\n相应的规章制度和法律法规提供依据。\n⑤加强法制管理\n加强有关法律法规的贯彻执行，加强对违反有关法律法规行为的\n处罚，是防止农药残留超标的有力保障。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2022],"needsReview":false,"reviewReasons":[],"verified":false,"page":113,"sourceRange":{"startPage":113,"startY":170.47,"endPage":115,"endY":98.94},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":["2022 (简, 【重要程度:"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":5,"excerpts":[{"page":113,"src":"./assets/environment/env838-9339def0f1db0f5f-113.webp"},{"page":114,"src":"./assets/environment/env838-9339def0f1db0f5f-114.webp"},{"page":115,"src":"./assets/environment/env838-9339def0f1db0f5f-115.webp"}]},{"id":"env838-53b0f4d5d5a339d4","subject":"环境学导论","chapter":"第5章 土壤的组成和基本性质","originalChapter":"第5章 土壤的组成和基本性质","originalChapterNumber":5,"section":"第5节 课后习题","originalSection":"第5节 课后习题","category":"exercise","title":"土壤自净的定义是什么?土壤自净的主要类型有哪些?","question":"土壤自净的定义是什么?土壤自净的主要类型有哪些?","type":"简答题","answer":"土壤自净是土壤通过吸附、固定、转化、分解及生物作用等，使进入土壤的污染物迁移性、生物有效性或危害降低的过程。\n①物理／物理化学净化：过滤、吸附和离子交换等，截留或固定部分污染物。\n②化学净化：沉淀、络合、氧化还原及水解等，改变污染物形态和可迁移性。\n③生物净化：微生物降解有机物，植物吸收或富集，及生物转化等。\n自净能力受土壤组成、pH、氧化还原条件、水分和污染负荷影响。重金属不能被“降解消失”；被固定也不意味着永久无风险。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":115,"sourceRange":{"startPage":115,"startY":138.14,"endPage":115,"endY":216.37},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":5,"additionalSources":[{"source":"环导变动137718728584015123.1eae00877280d3e.pdf","page":11,"sourceRange":{"startPage":11,"startY":571.5,"endPage":11,"endY":587.1}}],"excerpts":[{"page":115,"src":"./assets/environment/env838-53b0f4d5d5a339d4-115.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=101"},{"title":"生态环境部：土壤污染风险管控与绿色低碳修复解读","url":"https://www.mee.gov.cn/ywdt/zbft/202405/t20240506_1072343.shtml","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-959c7577c394149f","subject":"环境学导论","chapter":"第5章 土壤的组成和基本性质","originalChapter":"第5章 土壤的组成和基本性质","originalChapterNumber":5,"section":"第5节 课后习题","originalSection":"第5节 课后习题","category":"exercise","title":"土壤污染的定义是什么?造成土壤污染的主要物质有哪些?","question":"土壤污染的定义是什么?造成土壤污染的主要物质有哪些?","type":"简答题","answer":"土壤污染是有害物质进入并累积于土壤，导致土壤性质、生态功能或利用安全受到不利影响的现象。\n主要物质：①镉、汞、铅、砷等金属或类金属污染物；②农药、石油烃、持久性有机物等；③过量施用带来的化肥及盐类负荷；④病原微生物；⑤放射性物质及其他新污染物。\n来源包括工业排放和沉降、污水灌溉、农业投入品、矿业、固废不当处置及生活活动等。\n污染物的总量、形态、生物有效性与土地用途共同影响风险，应避免仅凭一种浓度描述全部危害。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":115,"sourceRange":{"startPage":115,"startY":216.37,"endPage":116,"endY":76.12},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":5,"additionalSources":[{"source":"环导变动137718728584015123.1eae00877280d3e.pdf","page":11,"sourceRange":{"startPage":11,"startY":587.1,"endPage":11,"endY":602.7}}],"excerpts":[{"page":115,"src":"./assets/environment/env838-959c7577c394149f-115.webp"},{"page":116,"src":"./assets/environment/env838-959c7577c394149f-116.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=101"},{"title":"生态环境部：土壤污染风险管控与绿色低碳修复解读","url":"https://www.mee.gov.cn/ywdt/zbft/202405/t20240506_1072343.shtml","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-56d33b1e82d138de","subject":"环境学导论","chapter":"第5章 土壤的组成和基本性质","originalChapter":"第5章 土壤的组成和基本性质","originalChapterNumber":5,"section":"第2节","originalSection":"第2节","category":"supplement","title":"土壤污染物分类","question":"土壤污染物分类","type":"简答题","answer":"根据污染物性质，土壤污染物可分为有机污染物、重金属污染物、放射性物\n质、化学肥料以及病原微生物污染等。\n（1）有机污染物\n污染土壤的有机物种类很多，主要包括杀虫剂、除草剂、石油类和化工类污\n染物。在土壤中，杀虫剂毒性巨大，并会长期残留，如六六六、DDT、艾氏剂、\n狄氏剂、对硫磷、马拉硫磷、氨基甲酸酯等。在杀虫剂、杀菌剂和除草剂三者中，\n除草剂的占有率排在首位，代表物质为苯氧基醚类物质。石油类污染物主要来自\n炼油企业、采油区和油田废油，主要污染物为难降解芳烃物。石油可使土壤的含\n氮量和透气性下降，进而使土壤中微生物无法生存。化工类污染物会影响植物和\n土壤微生物的生存，主要包括苯并［a］芘和酚类等。\n（2）重金属污染物\n重金属污染物是土壤污染物中最难治理的污染物之一，主要有Hg、Cd、Pb、\nCu、Zn、Ni、Cr、Co、Se 和As 等。重金属主要通过农田污水灌溉、重金属冶炼\n厂废气的沉降和含重金属的农药化肥等途径进入土壤。实际上，重金属不能为土\n壤微生物所分解，反而可被生物所富集。因此，土壤一旦被重金属污染，就难被\n彻底消除，会对土壤环境形成长期威胁。\n（3）化学肥料\n在农业生产中化学肥料发挥着巨大作用，但同时也对农田造成严重危害。化\n学肥料的过度使用，使土壤有机质含量下降，导致土壤板结，破坏土壤结构，致\n使土壤肥力下降，影响农业的可持续发展。\n（4）放射性物质\n放射性物质是指具有较强辐射的放射性元素，如Cs、Sr、U 等，还包括一些\n放射性较强的同位素，如I。放射性物质主要来源于核工业、核爆炸、核设施泄\n漏等。放射性物质不能被微生物分解，会残留在土壤中造成潜在威胁。\n（5）病原微生物\n土壤中的病原微生物，主要来源于人畜的粪污以及用于灌溉的污水。人与污\n染的土壤接触时会被传染各种细菌及病毒，若食用被土壤污染的蔬菜、瓜果等即\n会影响人体健康。这些被污染的土壤倾倒和冲刷，又可能污染水体。","source":"环导变动137718728584015123.1eae00877280d3e.pdf","sourceUrl":"https://drive.google.com/file/d/11CjvWmrS4poAVMmBBWnsJPRCmD1-JkRJ/view","version":"new","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":8,"sourceRange":{"startPage":8,"startY":215.77,"endPage":9,"endY":286.96},"sourceKind":"changes","originalOrdinal":"3","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":5,"excerpts":[{"page":8,"src":"./assets/environment/env838-56d33b1e82d138de-8.webp"},{"page":9,"src":"./assets/environment/env838-56d33b1e82d138de-9.webp"}]},{"id":"env838-6c2f885d8efbcc4d","subject":"环境学导论","chapter":"第5章 土壤的组成和基本性质","originalChapter":"第5章 土壤的组成和基本性质","originalChapterNumber":5,"section":"第2节","originalSection":"第2节","category":"supplement","title":"土壤污染来源","question":"土壤污染来源","type":"简答题","answer":"（1）工业污染源\n工业污染源主要包括工业废水、废气和废渣，污染物浓度一般都较高，一旦\n进入农田造成土壤污染，在短期内即可引起对作物的危害\n（2）农业污染源\n农业污染源包括农药、化肥、除草剂等污染。喷洒农药时，有相当一部分直\n接落于土壤表面，一部分则通过作物落叶、降雨而进入土壤。此外，农业地膜和\n农业废物的不合理利用也会造成农膜污染和病原微生物污染等问题。\n（3）生物污染源\n生物污染源主要是指含有致病菌、病原微生物和寄生虫等物质，如生活污水、\n畜禽废弃物及屠宰废水、植物残茬、医院废水、垃圾以及不洁的河（湖）水等。\n这些物质如果不经过处理而直接施入土壤，都可能造成病原的传播，影响人畜的\n生命健康。","source":"环导变动137718728584015123.1eae00877280d3e.pdf","sourceUrl":"https://drive.google.com/file/d/11CjvWmrS4poAVMmBBWnsJPRCmD1-JkRJ/view","version":"new","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":9,"sourceRange":{"startPage":9,"startY":286.96,"endPage":9,"endY":659.01},"sourceKind":"changes","originalOrdinal":"5","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":5,"excerpts":[{"page":9,"src":"./assets/environment/env838-6c2f885d8efbcc4d-9.webp"}]},{"id":"env838-4820153568893947","subject":"环境学导论","chapter":"第5章 土壤的组成和基本性质","originalChapter":"第5章 土壤的组成和基本性质","originalChapterNumber":5,"section":"第2节","originalSection":"第2节","category":"supplement","title":"土壤污染特点","question":"土壤污染特点","type":"简答题","answer":"（1）隐蔽性\n土壤是一个以固相为主的不均质三相体系，土壤污染不像大气污染和水污染\n那样容易被人们发现。各种有害物质与土壤相结合，有的为土壤生物所分解或吸\n收，从而改变其本来面目而被隐藏在土体里，或自土体排出不易被发现。土壤还\n可以经食物链将有害物输送给人类和牲畜，并且土壤本身可能还继续保持生产能\n力，这使土壤污染具有隐蔽性而不易被人类察觉，往往要通过对土壤样品进行分\n析化验和农作物的残留检测，甚至通过研究对人畜健康状况的影响后才能确定。\n（2）累积性\n污染物在土壤中并不像在大气和水体中那样容易扩散和稀释，而会在土壤中\n不断累积，渐渐超标。\n（3）不可逆转性\n土壤污染具有不可逆转性，重金属对土壤的污染基本上是一个不可逆过程，\n而许多有机化学物质造成的污染也需要较长时间才能被降解。\n（4）难治理性\n土壤污染很难治理，累积在土壤中的难降解污染物很难靠稀释作用和净化作\n用来消除。土壤污染一旦发生，无法通过切断污染源来恢复，有时需要靠换土、\n淋洗等方法才能解决，其他技术往往见效较慢。因此，治理土壤污染通常成本高、\n周期长。","source":"环导变动137718728584015123.1eae00877280d3e.pdf","sourceUrl":"https://drive.google.com/file/d/11CjvWmrS4poAVMmBBWnsJPRCmD1-JkRJ/view","version":"new","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":9,"sourceRange":{"startPage":9,"startY":659.01,"endPage":10,"endY":495.06},"sourceKind":"changes","originalOrdinal":"6","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":5,"excerpts":[{"page":9,"src":"./assets/environment/env838-4820153568893947-9.webp"},{"page":10,"src":"./assets/environment/env838-4820153568893947-10.webp"}]},{"id":"env838-710960365b3f5c65","subject":"环境学导论","chapter":"第5章 土壤的组成和基本性质","originalChapter":"第5章 土壤的组成和基本性质","originalChapterNumber":5,"section":"第4节 土壤污染的防治与修复","originalSection":"第2节","category":"supplement","title":"重金属污染的防治","question":"重金属污染的防治","type":"简答题","answer":"（1）重金属污染源控制\n控制与消除土壤污染源是防止污染的根本措施。在工业生产中大力推广清洁\n生产、循环经济，以减少或消除工业“三废”排放。在农业生产中，加强对污灌\n区的例行监测及管理，防止因不当污灌引起土壤污染。合理施用化肥与农药，避\n免引起土壤污染和土壤理化性质恶化，降低土壤自净能力。\n（2）施加改良剂\n施加改良剂的主要目的是使重金属固定在土壤中，如施加石灰、磷酸盐、硅\n酸钙等，可与重金属生成难溶化合物，降低重金属在土壤和植物中的迁移能力。\n此方法只起临时性的抑制作用，时间过长会引起污染物的累积，同时在条件变化\n时重金属又会转成可溶性，因而只在污染较轻地区使用。\n（3）控制土壤氧化还原状况\n加强水浆管理，控制土壤氧化还原条件，可有效减少重金属的危害。例如，\n淹水可明显抑制水稻对Cd 的吸收，落干则促进水稻对Cd 的吸收。但As 则相\n反，随着土壤氧化还原电位的降低，其毒性增加。\n（4）客土翻土\n去除土壤重金属的根本办法是彻底挖除污染土层、换上新土的排土法与客土\n法。如果是地区性的污染，采用客土法是不现实的。耕翻土层，即采用深耕，将\n上下土层翻动混合，可使表层土壤重金属含量减低，这种方法动土量较少，但在\n严重污染的地区不宜采用。\n（5）农业生态工程措施\n可在污染土壤上种植非食用的经济作物或种属，从而减少污染物进入食物链\n的途径。或利用某些特殊的动植物与微生物较快地吸收或降解土壤中的污染物质，\n从而达到净化土壤的目的。\n（6）工程治理\n利用物理（机械）、物理化学原理治理污染土壤，主要有隔离法、清洗法、\n热处理、电化法等。这是一种最为彻底、稳定、治本的措施，但投资大，适于小\n面积的重度污染区。","source":"环导变动137718728584015123.1eae00877280d3e.pdf","sourceUrl":"https://drive.google.com/file/d/11CjvWmrS4poAVMmBBWnsJPRCmD1-JkRJ/view","version":"new","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":10,"sourceRange":{"startPage":10,"startY":495.06,"endPage":11,"endY":547.02},"sourceKind":"changes","originalOrdinal":"3","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":5,"excerpts":[{"page":10,"src":"./assets/environment/env838-710960365b3f5c65-10.webp"},{"page":11,"src":"./assets/environment/env838-710960365b3f5c65-11.webp"}]},{"id":"env838-ac4bedcc686fbe0e","subject":"环境学导论","chapter":"第5章 土壤的组成和基本性质","originalChapter":"第5章 土壤的组成和基本性质","originalChapterNumber":5,"section":"课后习题","originalSection":"课后习题","category":"exercise","title":"简述重金属在土壤中的生物迁移和转化过程以及防治措施。","question":"简述重金属在土壤中的生物迁移和转化过程以及防治措施。","type":"简答题","answer":"迁移转化：重金属可随灌溉水、径流和渗滤在土壤中迁移，经植物吸收进入农产品及食物链；土壤吸附、解吸、沉淀、络合和氧化还原会改变其形态与生物有效性。生物富集可增加暴露，但金属元素本身不能被微生物分解消失。\n防治：①控制冶炼、矿业和“三废”等输入，规范农业投入品；②根据pH、氧化还原状态等采取合适的钝化、农艺调控或安全利用；③污染严重地块采用隔离、土壤淋洗、工程修复等；④在适用条件下开展植物修复；⑤监测土壤、地下水及农产品，防止风险转移。\n不同金属对条件变化的响应不同，不能把同一种水分或pH措施机械套用。","source":"环导变动137718728584015123.1eae00877280d3e.pdf","sourceUrl":"https://drive.google.com/file/d/11CjvWmrS4poAVMmBBWnsJPRCmD1-JkRJ/view","version":"new","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":11,"sourceRange":{"startPage":11,"startY":602.7,"endPage":11,"endY":618.33},"sourceKind":"changes","originalOrdinal":"3","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":5,"excerpts":[{"page":11,"src":"./assets/environment/env838-ac4bedcc686fbe0e-11.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=101"},{"title":"生态环境部：土壤污染风险管控与绿色低碳修复解读","url":"https://www.mee.gov.cn/ywdt/zbft/202405/t20240506_1072343.shtml","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-6e0d450d3bf5ed11","subject":"环境学导论","chapter":"第5章 土壤的组成和基本性质","originalChapter":"第5章 土壤的组成和基本性质","originalChapterNumber":5,"section":"课后习题","originalSection":"课后习题","category":"exercise","title":"农药在土壤中的降解途径有哪些？","question":"农药在土壤中的降解途径有哪些？","type":"简答题","answer":"①生物降解：微生物或植物酶促作用使农药转化，部分可进一步矿化。\n②化学降解：水解、氧化、还原等反应，速率受农药结构、pH、温度和土壤成分影响。\n③光降解：暴露于表层的农药在日光作用下分解，受光照与遮蔽程度限制。\n④转化产物：原农药浓度下降不代表所有产物均无毒，仍应关注代谢物及其持久性。\n挥发、淋溶、径流和吸附改变污染物的位置或存在状态，通常属于迁移、分配过程，不能全部当作真正降解。治理应减少输入并控制对水、气环境的转移。","source":"环导变动137718728584015123.1eae00877280d3e.pdf","sourceUrl":"https://drive.google.com/file/d/11CjvWmrS4poAVMmBBWnsJPRCmD1-JkRJ/view","version":"new","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":11,"sourceRange":{"startPage":11,"startY":618.33,"endPage":11,"endY":633.93},"sourceKind":"changes","originalOrdinal":"4","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":5,"excerpts":[{"page":11,"src":"./assets/environment/env838-6e0d450d3bf5ed11-11.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=101"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-b8abaec17b08bf7b","subject":"环境学导论","chapter":"第5章 土壤的组成和基本性质","originalChapter":"第5章 土壤的组成和基本性质","originalChapterNumber":5,"section":"课后习题","originalSection":"课后习题","category":"exercise","title":"土壤退化的含义是什么？土壤退化的类型有哪些？","question":"土壤退化的含义是什么？土壤退化的类型有哪些？","type":"简答题","answer":"土壤退化是土壤在自然因素和人类活动作用下，生产力、生态功能及质量下降的过程。\n①物理退化：水蚀、风蚀、压实、结构破坏、表土流失等。\n②化学退化：盐渍化、酸化、养分耗竭或失衡、有毒污染物累积等。\n③生物退化：有机质减少、土壤生物多样性及生物活性下降等。\n这些类型可相互促进。例如植被破坏导致侵蚀，有机质损失又削弱团粒结构及保水保肥能力。\n防治应保护表土和植被，合理耕作与施肥，改善排灌，防控污染并开展针对性修复。","source":"环导变动137718728584015123.1eae00877280d3e.pdf","sourceUrl":"https://drive.google.com/file/d/11CjvWmrS4poAVMmBBWnsJPRCmD1-JkRJ/view","version":"new","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":11,"sourceRange":{"startPage":11,"startY":633.93,"endPage":11,"endY":649.53},"sourceKind":"changes","originalOrdinal":"5","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":5,"excerpts":[{"page":11,"src":"./assets/environment/env838-b8abaec17b08bf7b-11.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=101"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-41cab7b526e3661e","subject":"环境学导论","chapter":"第5章 土壤的组成和基本性质","originalChapter":"第5章 土壤的组成和基本性质","originalChapterNumber":5,"section":"课后习题","originalSection":"课后习题","category":"exercise","title":"简述土壤污染的防治对策。","question":"简述土壤污染的防治对策。","type":"简答题","answer":"①源头预防：严格控制工业、矿业、污水和固废向土壤输入污染物，推进清洁生产；科学施肥用药，规范污灌。\n②分类管理：调查监测与风险评估相结合，按土地用途、污染水平和暴露条件确定安全利用、风险管控或修复措施。\n③阻断暴露：采用清洁覆盖、隔离、调整作物或土地利用等方式，保护农产品、地下水及居民安全。\n④针对性修复：选择适宜物理、化学、生物或联合技术，并控制二次污染。\n⑤全过程保障：落实责任主体、修复效果评估和长期监测，防止治理后重新污染。","source":"环导变动137718728584015123.1eae00877280d3e.pdf","sourceUrl":"https://drive.google.com/file/d/11CjvWmrS4poAVMmBBWnsJPRCmD1-JkRJ/view","version":"new","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":11,"sourceRange":{"startPage":11,"startY":649.53,"endPage":11,"endY":665.13},"sourceKind":"changes","originalOrdinal":"6","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":5,"excerpts":[{"page":11,"src":"./assets/environment/env838-41cab7b526e3661e-11.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=101"},{"title":"生态环境部：土壤污染风险管控与绿色低碳修复解读","url":"https://www.mee.gov.cn/ywdt/zbft/202405/t20240506_1072343.shtml","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-9633964387a383f8","subject":"环境学导论","chapter":"第5章 土壤的组成和基本性质","originalChapter":"第5章 土壤的组成和基本性质","originalChapterNumber":5,"section":"课后习题","originalSection":"课后习题","category":"exercise","title":"土壤由哪些基本成分组成？这些成分如何影响土壤的物理、化学和生物学性质？","question":"土壤由哪些基本成分组成？这些成分如何影响土壤的物理、化学和生物学性质？","type":"简答题","answer":"基本成分：矿物质、有机质、土壤水、土壤空气及土壤生物；水和空气主要分布在孔隙中。\n①矿物颗粒及粒径组成影响质地、孔隙、通气、透水和吸附能力。\n②有机质参与团粒形成、保水保肥和缓冲作用，也是土壤生物的物质能量来源。\n③土壤水是物质溶解、迁移及生物活动的介质；过多或过少都会限制根系与微生物活动。\n④空气供应氧气，孔隙通气状况影响氧化还原条件。\n⑤生物促进有机物分解、养分循环和结构形成。\n各成分相互作用，决定土壤的物理、化学与生物性质。","source":"环导变动137718728584015123.1eae00877280d3e.pdf","sourceUrl":"https://drive.google.com/file/d/11CjvWmrS4poAVMmBBWnsJPRCmD1-JkRJ/view","version":"new","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":11,"sourceRange":{"startPage":11,"startY":665.13,"endPage":11,"endY":696.33},"sourceKind":"changes","originalOrdinal":"7","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":5,"excerpts":[{"page":11,"src":"./assets/environment/env838-9633964387a383f8-11.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=101"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-0f3180412dca7dce","subject":"环境学导论","chapter":"第5章 土壤的组成和基本性质","originalChapter":"第5章 土壤的组成和基本性质","originalChapterNumber":5,"section":"课后习题","originalSection":"课后习题","category":"exercise","title":"土壤侵蚀对土壤质量和环境健康有哪些长期影响？分析土壤侵蚀的成因、过程以及防治措施。","question":"土壤侵蚀对土壤质量和环境健康有哪些长期影响？分析土壤侵蚀的成因、过程以及防治措施。","type":"简答题","answer":"成因：强降雨、地表径流、风和地形条件是自然驱动力；毁林、过度放牧、不合理坡耕和工程扰动会放大侵蚀。\n过程：土粒被剥离，随后经水流或风搬运，再在低能量区域沉积。\n长期影响：表土、有机质及养分流失，土层变薄和生产力下降；泥沙淤积河库，携带氮磷及污染物，损害水质与水生态；严重时引发土地退化并影响生计。\n防治：保护和恢复植被，实行等高耕作、覆盖、轮作及适度放牧，结合梯田、截排水、沟道治理与水土保持工程；建设活动应落实表土保护及施工期控制。","source":"环导变动137718728584015123.1eae00877280d3e.pdf","sourceUrl":"https://drive.google.com/file/d/11CjvWmrS4poAVMmBBWnsJPRCmD1-JkRJ/view","version":"new","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":11,"sourceRange":{"startPage":11,"startY":696.33,"endPage":11,"endY":727.53},"sourceKind":"changes","originalOrdinal":"8","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":5,"excerpts":[{"page":11,"src":"./assets/environment/env838-0f3180412dca7dce-11.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=101"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-ed179d48b100c0d0","subject":"环境学导论","chapter":"第5章 土壤的组成和基本性质","originalChapter":"第5章 土壤的组成和基本性质","originalChapterNumber":5,"section":"课后习题","originalSection":"课后习题","category":"exercise","title":"土壤修复技术中，物理修复、化学修复和生物修复各有哪些优缺点？","question":"土壤修复技术中，物理修复、化学修复和生物修复各有哪些优缺点？","type":"简答题","answer":"①物理修复：如挖除换土、筛分、隔离等，见效较快、适于特定污染分布；但工程量和费用较大，可能扰动土壤或产生待处置污染土。\n②化学／物化修复：如稳定化、淋洗、化学氧化还原等，针对性和处理效率较强；但可能改变土壤性质，产生废液、副产物或长期稳定性问题。\n③生物修复：利用植物或微生物吸收、转化或降解污染物，通常扰动较小，利于生态恢复；但周期较长，受温度、毒性、污染深度等限制。\n选择应依据污染物性质、风险目标和土地用途，必要时联合应用。重金属修复重点是移除、固定或阻断暴露，不是把元素降解。","source":"环导变动137718728584015123.1eae00877280d3e.pdf","sourceUrl":"https://drive.google.com/file/d/11CjvWmrS4poAVMmBBWnsJPRCmD1-JkRJ/view","version":"new","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":11,"sourceRange":{"startPage":11,"startY":727.53,"endPage":12,"endY":73.45},"sourceKind":"changes","originalOrdinal":"9","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":5,"excerpts":[{"page":11,"src":"./assets/environment/env838-ed179d48b100c0d0-11.webp"},{"page":12,"src":"./assets/environment/env838-ed179d48b100c0d0-12.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=101"},{"title":"生态环境部：土壤污染风险管控与绿色低碳修复解读","url":"https://www.mee.gov.cn/ywdt/zbft/202405/t20240506_1072343.shtml","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-8537c48cb7663f17","subject":"环境学导论","chapter":"第5章 土壤的组成和基本性质","originalChapter":"第5章 土壤的组成和基本性质","originalChapterNumber":5,"section":"课后习题","originalSection":"课后习题","category":"exercise","title":"土壤盐渍化是如何形成的？讨论土壤盐渍化的原因、影响及其对农业和生态系统的潜在危害。","question":"土壤盐渍化是如何形成的？讨论土壤盐渍化的原因、影响及其对农业和生态系统的潜在危害。","type":"简答题","answer":"形成：土体或地下水中的可溶盐随水迁移，在蒸发强、淋洗不足或排水不畅时在根区及表层积累。\n原因：干旱气候、浅埋含盐地下水、海水影响等自然因素，以及大水漫灌、排水不良、使用含盐灌溉水和不合理土地利用等人为因素。\n影响：增加植物吸水困难，可能产生离子毒害和营养失衡，降低产量；钠化还可能破坏土壤结构、降低透水性，并影响生态系统。\n防治：完善排灌与地下水调控，采用合适水质及科学灌溉，结合覆盖、耐盐作物和必要的土壤改良；洗盐必须有排盐出路，避免把盐转移到相邻环境。","source":"环导变动137718728584015123.1eae00877280d3e.pdf","sourceUrl":"https://drive.google.com/file/d/11CjvWmrS4poAVMmBBWnsJPRCmD1-JkRJ/view","version":"new","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":12,"sourceRange":{"startPage":12,"startY":73.45,"endPage":12,"endY":104.65},"sourceKind":"changes","originalOrdinal":"10","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":5,"excerpts":[{"page":12,"src":"./assets/environment/env838-8537c48cb7663f17-12.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=101"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-c185a7f54ffd5682","subject":"环境学导论","chapter":"第5章 土壤的组成和基本性质","originalChapter":"第5章 土壤的组成和基本性质","originalChapterNumber":5,"section":"课后习题","originalSection":"课后习题","category":"exercise","title":"基于土壤污染的来源，提出一系列预防土壤污染的策略，并讨论它们的实施可行性。","question":"基于土壤污染的来源，提出一系列预防土壤污染的策略，并讨论它们的实施可行性。","type":"简答题","answer":"按来源提出策略：①工业与矿业：优化布局，采用清洁生产，控制废气沉降、渗漏和尾矿风险；②农业：测土配方施肥、综合病虫害管理，规范有机肥及农膜利用；③生活及固废：分类收集、规范处理，防止随意倾倒和不合规土地施用；④污水：控制灌溉水及再生水质量；⑤历史场地：调查评估，避免污染地块未经管理改变用途。\n可行性：源头预防一般优于污染后大规模修复，但需要明确责任、提供技术和资金支持，建立监测及可追溯制度，并与地方产业和农户条件相适应。","source":"环导变动137718728584015123.1eae00877280d3e.pdf","sourceUrl":"https://drive.google.com/file/d/11CjvWmrS4poAVMmBBWnsJPRCmD1-JkRJ/view","version":"new","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":12,"sourceRange":{"startPage":12,"startY":104.65,"endPage":12,"endY":141.37},"sourceKind":"changes","originalOrdinal":"11","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":5,"excerpts":[{"page":12,"src":"./assets/environment/env838-c185a7f54ffd5682-12.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=101"},{"title":"生态环境部：土壤污染风险管控与绿色低碳修复解读","url":"https://www.mee.gov.cn/ywdt/zbft/202405/t20240506_1072343.shtml","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-bd9c46675868c991","subject":"环境学导论","chapter":"第5章 土壤的组成和基本性质","originalChapter":"第5章 土壤的组成和基本性质","originalChapterNumber":5,"section":"课后习题","originalSection":"课后习题","category":"exercise","title":"分析当前关于土壤保护和污染治理的法律和政策，并讨论它们在实际执行中可能面临的挑战。","question":"分析当前关于土壤保护和污染治理的法律和政策，并讨论它们在实际执行中可能面临的挑战。","type":"简答题","answer":"按2026年11月法律背景，土壤保护以生态环境法典的有关规定为重要依据，并与农用地、建设用地分类管理及风险管控、修复政策配套。历史教材所列土壤污染防治法自法典2026年8月15日施行时同时废止，应注明时间。\n制度重点：污染预防、调查监测、用途和风险分类、责任追溯、受污染地块风险管控与修复、农产品及地下水安全。\n执行挑战：历史责任主体难认定，调查数据和技术能力不均衡，修复费用高且周期长，部门协同与长期监管不足，以及开发利用压力。\n改进：强化源头控制、信息共享、资金保障、质量监督与后期监测，按风险目标选择措施。","source":"环导变动137718728584015123.1eae00877280d3e.pdf","sourceUrl":"https://drive.google.com/file/d/11CjvWmrS4poAVMmBBWnsJPRCmD1-JkRJ/view","version":"new","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":12,"sourceRange":{"startPage":12,"startY":141.37,"endPage":12,"endY":253.36},"sourceKind":"changes","originalOrdinal":"12","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":5,"excerpts":[{"page":12,"src":"./assets/environment/env838-bd9c46675868c991-12.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=101"},{"title":"中华人民共和国生态环境法典","url":"https://www.mee.gov.cn/ywgz/fgbz/fl/202603/t20260313_1146496.shtml","accessedOn":"2026-11-09"},{"title":"生态环境部：土壤污染风险管控与绿色低碳修复解读","url":"https://www.mee.gov.cn/ywdt/zbft/202405/t20240506_1072343.shtml","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-38127699127d2295","subject":"环境学导论","chapter":"第6章 固体废物与环境","originalChapter":"第6章 固体废物与环境","originalChapterNumber":6,"section":"第1节 固体废物的概述","originalSection":"第1节 固体废物的概述","category":"knowledge","title":"固体废物的定义","question":"固体废物的定义","type":"简答题","answer":"固体废物，是指在生产、生活和其他活动中产生的丧失原有利用\n价值或者虽未丧失利用价值但被抛弃或者放弃的固态、半固态和置于\n容器中的气态的物品、物质以及法律、行政法规规定纳入固体废物管\n理的物品、物质。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2004,2006,2012,2013,2020],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":117,"sourceRange":{"startPage":117,"startY":102.3,"endPage":117,"endY":300.5},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":["2004(名、2006(简、2012(名、2013(论、2020(名, 【重要程度:"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":6,"excerpts":[{"page":117,"src":"./assets/environment/env838-38127699127d2295-117.webp"}]},{"id":"env838-adecc1376b7b1fae","subject":"环境学导论","chapter":"第6章 固体废物与环境","originalChapter":"第6章 固体废物与环境","originalChapterNumber":6,"section":"第2节 固体废物的来源及危害","originalSection":"第2节 固体废物的来源及危害","category":"knowledge","title":"固体废物的危害","question":"固体废物的危害","type":"简答题","answer":"①侵占土地。固体废物不加利用时必然占地堆放，堆积量越大，\n占地也越多。\n②污染土壤和地下水。废物堆置或没有适当防渗措施的垃圾填埋\n，其中的有害组分很容易随着渗滤液浸出而污染土壤及地下水。一方\n面，人类的健康受到威胁；另一方面，工业固体废物会破坏土壤生态\n平衡。\n③污染水体。除对地下水的污染外，由于不少国家把固体废物直\n接倾入河流、湖泊和海洋，使地表水受到严重影响-不仅减少水体面积\n，而且还妨害水生生物的生存和水资源的利用。\n④污染大气。固体废物污染大气环境一般通过如下途径：尾矿粉\n煤灰、污泥和垃圾中的尘粒随风飞扬；运输过程中产生的有害气体和\n粉尘；固体废物本身或在处理时散发毒气和臭味等。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2013,2015],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":117,"sourceRange":{"startPage":117,"startY":342.97,"endPage":118,"endY":64.41},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":["2013 (论、2015 ( 简, 【重要程度: ☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":6,"excerpts":[{"page":117,"src":"./assets/environment/env838-adecc1376b7b1fae-117.webp"},{"page":118,"src":"./assets/environment/env838-adecc1376b7b1fae-118.webp"}]},{"id":"env838-3c4b0117db274841","subject":"环境学导论","chapter":"第6章 固体废物与环境","originalChapter":"第6章 固体废物与环境","originalChapterNumber":6,"section":"第2节 固体废物的来源及危害","originalSection":"第2节 固体废物的来源及危害","category":"knowledge","title":"危险废物的定义和特性","question":"危险废物的定义和特性","type":"简答题","answer":"危险废物是指被列入国家危险废物名录或者根据国家规定的危\n险废物鉴别标准和鉴别方法认定的具有危险特性的废物。危险性废\n物的特性：腐蚀性、反应性、放射性、传染性、急性毒性、浸出毒性\n，只要废物具有以上一种或一种以上特性就认为是危险废物。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2004,2005,2006,2009,2010,2011,2013,2017,2022],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":118,"sourceRange":{"startPage":118,"startY":64.41,"endPage":118,"endY":274.52},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":["2004(选、2005(选、2006(简、2009(名、2010(选、2011 (名、2013(论、2017 (论","、2022(名, 【重要程度:"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":6,"excerpts":[{"page":118,"src":"./assets/environment/env838-3c4b0117db274841-118.webp"}]},{"id":"env838-c4c36a31f9227554","subject":"环境学导论","chapter":"第6章 固体废物与环境","originalChapter":"第6章 固体废物与环境","originalChapterNumber":6,"section":"第3节 固体废物的防治对策","originalSection":"第3节 固体废物的防治对策","category":"knowledge","title":"固废处理的三化原则","question":"固废处理的三化原则","type":"简答题","answer":"[1] 减量化\n减量化一般指减少固体废物的产生量或危害性。这里包括两层意\n思，一是数量的减少，另一种是固体废物对环境的危害性质下降。也\n就是说，通过适宜的手段最大限度地合理开发和利用资源与能源，减\n少固体废物数量或体积，降低危险废物的有害成分、减轻或清除其危\n险特性等，从“源头”直接减少或减轻固体废物对环境和人体健康的\n危害。\n[2] 资源化\n资源化是指将废物直接作为原料进行利用或者对废物进行再生\n利用。自然界并不存在绝对的废物，所谓废物只是失去原有使用价值\n而被弃置的物质，并不是永远没有使用价值。现在不能利用的，也许\n将来可以利用。这一生产过程的废物，可能是另一生产过程的原料，\n所以固体废物有“放错地方的原料”之称。\n[3] 无害化\n无害化是指经过适当的处理或处置，使固体废物或其中的有害成\n分无法危害环境，或转化为对环境无害的物质，这个处置过程即为固\n体废物的无害化。常用的方法有填埋法、焚烧法、堆肥法、热解法、\n化学法等。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":118,"sourceRange":{"startPage":118,"startY":316.24,"endPage":119,"endY":179.95},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":["【重要程度： 】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":6,"excerpts":[{"page":118,"src":"./assets/environment/env838-c4c36a31f9227554-118.webp"},{"page":119,"src":"./assets/environment/env838-c4c36a31f9227554-119.webp"}]},{"id":"env838-dce8b9c6bb04e739","subject":"环境学导论","chapter":"第6章 固体废物与环境","originalChapter":"第6章 固体废物与环境","originalChapterNumber":6,"section":"第3节 固体废物的防治对策","originalSection":"第3节 固体废物的防治对策","category":"knowledge","title":"清洁生产的概念","question":"清洁生产的概念","type":"简答题","answer":"清洁生产是这样一种生产产品的方法 ， 借助这种方法 ， 所有的原料和能量在原料资源\n-生产 -消费 -二次原料资源的循环中得到最合理和综合的利用 ， 同时对环境的任何作用\n都不致玻坏它的正常功能 。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2015,2016],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。"],"verified":false,"page":119,"sourceRange":{"startPage":119,"startY":179.95,"endPage":119,"endY":327.23},"sourceKind":"original","originalOrdinal":"supp-1","sourceMetadata":["2015 (4, 2016 (名 ，【 重要程度 ， 文妇六妇六 】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":6,"excerpts":[{"page":119,"src":"./assets/environment/env838-dce8b9c6bb04e739-119.webp"}]},{"id":"env838-4c95394a70d950bb","subject":"环境学导论","chapter":"第6章 固体废物与环境","originalChapter":"第6章 固体废物与环境","originalChapterNumber":6,"section":"第3节 固体废物的防治对策","originalSection":"第3节 固体废物的防治对策","category":"knowledge","title":"固体废物的预处理","question":"固体废物的预处理","type":"简答题","answer":"FERRE: 在此开始之前 ， 想请大家有意识的区分两个概念 : 处理技术和资源化技术\n， 这两个是有区别的 ， 前者是指对废物进行无害化 、 减量化的方法 ， 后者不仅要处理\n， 还要使其变为可重复利用的资源 。 大家在考场上注意审题 ， 问的是一般处理技术还\n是资源化技术 ， 再或者说是处理及资源化技术 。\n处理技术: 2002(填、2003(填、2008(简、2011 (名--堆肥化、2012(简、2019(\n简-焚烧和热解的区别、2020(论、2022(名, 2025( 简) , 2026( 简) , 【重要程\n度：\n①分选。分选是指用人工或机械的方法把固体废物分门别类地分\n开，回收利用有用物资，分离出不利于后续处理工艺物料的处理方法\n。分选是实现固体废物资源化、减量化的重要手段，通过分选可以提\n高回收物质的纯度和价值，有利于后续加工处理。分选有多种方法，\n常用的方法有筛分、重选、磁选、浮选等，一般根据固体废物的特性\n(如颗粒大小、磁性、漂浮性等)来选择。特殊情况下，人工分选作\n为辅助手段也是不可缺少的。\n②破碎。破碎是利用压实、剪切、冲击等外力作用，减小固体废\n物的颗粒尺寸，使之质地均匀，孔隙率降低、容重增大的过程。通常\n用作运输、贮存、资源化和最终处置的预处理。固体废物经破碎后直\n接进行填埋处置时，压实密度高而均匀，可加快填埋处置场的早期稳\n定化。破碎方法很多，常见的主要有冲击破碎、剪切破碎、挤压破碎\n、摩擦破碎等。针对一些特殊的较难破碎的废物，还会采用低温破碎\n和湿式破碎等。\n③压实。压实是利用外界压力作用于固体废物，达到增大容重，\n减小表观体积的目的，以降低运输成本、延长填埋场寿命的预处理技\n术。压实适用于减少体积处理的固体废物，如易拉罐、塑料瓶、松散\n废物、纸箱及纤维制品等。对于那些可能使压实设备损坏或可能引起\n操作问题的废物(如焦油、污泥等)，一般不宜作压实处理。\n④脱水。固体废物脱水主要用于污水处理厂排出的污泥，以及某\n些企业所排出的泥浆状废物的处理。这些污泥的含水率一般为96%~\n99.8%，脱水可以大大缩小污泥的体积，有利于包装和运输。常用的\n脱水机械有真空过滤机、滚带压滤机、框板脱水机、离心脱水机和造\n粒脱水机等。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2004,2005,2020,2021,2022],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。","含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":119,"sourceRange":{"startPage":119,"startY":327.23,"endPage":120,"endY":559.11},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":["资源化技术: 2020(论、2021(简、2022 (论, 【重要程度: 】","处理及资源化技术: 2004(简、2005(简, 【重要程度:"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":6,"excerpts":[{"page":119,"src":"./assets/environment/env838-4c95394a70d950bb-119.webp"},{"page":120,"src":"./assets/environment/env838-4c95394a70d950bb-120.webp"}]},{"id":"env838-5364dc7d25ff7692","subject":"环境学导论","chapter":"第6章 固体废物与环境","originalChapter":"第6章 固体废物与环境","originalChapterNumber":6,"section":"第3节 固体废物的防治对策","originalSection":"第3节 固体废物的防治对策","category":"knowledge","title":"固体废物的焚烧和热解以及各自优缺点","question":"固体废物的焚烧和热解以及各自优缺点","type":"简答题","answer":"焚烧 热解\n高温分解和深度氧化处理，通过燃烧破坏 在无氧或缺氧条件下对有机物加热，使其发生\n定义 有机废物，并利用高温熔融固化无机废物 不可逆化学分解，生成低分子化合物(如燃气\n中的重金属等成分 、燃油) 。\n有机废物 ( 如生活垃圾、医疗废物) 、无 废塑料、废橡胶、废油及油泥、有机污泥；城\n适用对象\n机废物( 需熔融固化处理) 。 市生活垃圾和农林废弃物的应用仍在研究中。\n焚烧 热解\n1.彻底分解有害有机物，实现无害化 1.回收能源(燃气、燃油)\n2.显著减少废物体积(达90%以上) 2.尾气处理简单，排放达标率高\n主要优点\n3.全封闭处理减少污染泄漏 3.残渣填埋占地少(仅为传统填埋的20%~30%\n4.热能可回收发电或供热 4.避免焚烧中二噁英生成风险\n1.设备复杂、成本高(约为填埋的10倍)\n1.技术成熟度低，工业化应用受限\n2.需严格控制污染物( 、 、二噁英\n2.需严格控氧条件 (设备密封性要求高)\n主要缺点 等\n3.对原料成分敏感(需分类预处理)\n3.对废物热值有要求(需补充燃料)\n4.经济性待验证\n4.飞灰处理难\n二氧化碳、水、飞灰、炉渣、烟气(含酸\n产物 燃气( 甲烷、CO 等)、燃油、炭黑、少量残渣\n性气体、重金属)\n能源回收\n直接热能回收(蒸汽发电) 间接燃料回收( 燃气/燃油需二次利用)\n形式\n污染物控 二噁英生成( 需850 以上高温+急冷技术 焦油处理(易堵塞管道)、热解气净化(含硫\n制难点 )、重金属挥发、酸性气体排放 化合物)\n典型应用 城市垃圾处理(尤其土地资源紧张地区) 特定工业废物(轮胎、塑料)、油泥处理、偏\n场景 医疗危废处置 远地区分散式能源回收\n技术成熟 成熟(全球广泛应用，国内主流技术为炉 发展中(实验室至中试阶段为主，部分商业化\n度 排炉和流化床) 案例)\n未来潜力 面临污染物排放标准趋严的挑战 随能源需求增长和低碳政策推进，潜力较大","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":120,"sourceRange":{"startPage":120,"startY":559.11,"endPage":121,"endY":644.11},"sourceKind":"original","originalOrdinal":"3","sourceMetadata":["【重要程度："],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":6,"excerpts":[{"page":120,"src":"./assets/environment/env838-5364dc7d25ff7692-120.webp"},{"page":121,"src":"./assets/environment/env838-5364dc7d25ff7692-121.webp"}]},{"id":"env838-5e36a4601627a958","subject":"环境学导论","chapter":"第6章 固体废物与环境","originalChapter":"第6章 固体废物与环境","originalChapterNumber":6,"section":"第3节 固体废物的防治对策","originalSection":"第3节 固体废物的防治对策","category":"knowledge","title":"固体废物的固化","question":"固体废物的固化","type":"简答题","answer":"固化是通过向废物中添加固化基材，使有害成分固定或包容在惰\n性固化基材中的一种无害化处理技术。固化技术通常较多应用于危险\n废物处置前的预处理。理想的固化产物应具有良好的抗渗透性和良好\n的机械特性、抗浸出性、抗干湿、抗冻融等特性。固化方法可分为水\n泥固化、塑性材料固化、熔融固化和自胶结固化等。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":1,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":121,"sourceRange":{"startPage":121,"startY":644.11,"endPage":122,"endY":145.03},"sourceKind":"original","originalOrdinal":"4","sourceMetadata":["【重要程度:★☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":6,"excerpts":[{"page":121,"src":"./assets/environment/env838-5e36a4601627a958-121.webp"},{"page":122,"src":"./assets/environment/env838-5e36a4601627a958-122.webp"}]},{"id":"env838-c0aabe241f729a9f","subject":"环境学导论","chapter":"第6章 固体废物与环境","originalChapter":"第6章 固体废物与环境","originalChapterNumber":6,"section":"第3节 固体废物的防治对策","originalSection":"第3节 固体废物的防治对策","category":"knowledge","title":"好氧堆肥","question":"好氧堆肥","type":"简答题","answer":"好氧堆肥是在有氧条件下利用好氧菌对废物进行吸收、氧化、分\n解的过程。即微生物通过自身的生命活动，把一部分被吸收的有机物\n氧化成简单的无机物，同时释放出可供微生物生长活动所需的能量，\n而另一部分有机物则被合成新的细胞质，使微生物不断生长繁殖，产\n生更多生物体的过程。好氧堆肥可实现废物的减量化、资源化、无害\n化处理，最终产物主要是二氧化碳、水、热量和腐殖质。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":122,"sourceRange":{"startPage":122,"startY":145.03,"endPage":122,"endY":391.81},"sourceKind":"original","originalOrdinal":"5","sourceMetadata":["【重要程度："],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":6,"excerpts":[{"page":122,"src":"./assets/environment/env838-c0aabe241f729a9f-122.webp"}]},{"id":"env838-89e8d6965c5a9d6f","subject":"环境学导论","chapter":"第6章 固体废物与环境","originalChapter":"第6章 固体废物与环境","originalChapterNumber":6,"section":"第3节 固体废物的防治对策","originalSection":"第3节 固体废物的防治对策","category":"knowledge","title":"厌氧发酵","question":"厌氧发酵","type":"简答题","answer":"厌氧发酵是废物在厌氧条件下通过微生物的代谢活动而被稳定\n化，同时伴有 和 产生。即，通过厌氧微生物的生物转化作用，\n将大部分可降解有机质分解，转化为能源产品 (或称沼气)的过\n程，所以也称沼气发酵或甲烷发酵技术。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":122,"sourceRange":{"startPage":122,"startY":391.81,"endPage":122,"endY":587.36},"sourceKind":"original","originalOrdinal":"6","sourceMetadata":["【重要程度："],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":6,"excerpts":[{"page":122,"src":"./assets/environment/env838-89e8d6965c5a9d6f-122.webp"}]},{"id":"env838-312cec10301184b3","subject":"环境学导论","chapter":"第6章 固体废物与环境","originalChapter":"第6章 固体废物与环境","originalChapterNumber":6,"section":"第3节 固体废物的防治对策","originalSection":"第3节 固体废物的防治对策","category":"knowledge","title":"固体废物处置技术","question":"固体废物处置技术","type":"简答题","answer":"固废处置的目的：使固体废物最大限度地与生物圈隔离，解决固\n体废物的最终归宿问题。\n[1] 陆地处置\n陆地处置以土地填埋为主，指利用坑洼地填埋固体废物，是一种\n既可处置废物又可覆土造地的保护环境的措施\n①卫生填埋。卫生填埋是指对城市垃圾和废物在卫生填埋场进行\n的填埋处置。卫生填埋适于处置一般固体废物。用卫生填埋来处置城\n市垃圾，不仅操作简单，施工方便，费用低廉，还可回收甲烷气体。\n所以，卫生土地填埋法已在国内外得到广泛采用。\n②安全填埋是一种改进的卫生填埋方法，主要用于处置危险废物\n，是危险废物的主要处置方法，但对防止填埋场地产生二次污染的要\n求更为严格。\n[2] 海洋处置\n①海洋倾倒。海洋倾倒是利用海洋的巨大环境容量，将废物直接\n投入海洋的处置方法。\n②远洋焚烧。远洋焚烧是利用焚烧船将固体废物运至远洋处置区\n进行船上焚烧的处置方法。目前，海洋处置已被国际公约所禁止。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":1,"pastExamYears":[2026],"needsReview":false,"reviewReasons":[],"verified":false,"page":122,"sourceRange":{"startPage":122,"startY":587.36,"endPage":123,"endY":423.7},"sourceKind":"original","originalOrdinal":"7","sourceMetadata":["2026(论--固体废物的处置技术及优缺点)【重要程度：★☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":6,"excerpts":[{"page":122,"src":"./assets/environment/env838-312cec10301184b3-122.webp"},{"page":123,"src":"./assets/environment/env838-312cec10301184b3-123.webp"}]},{"id":"env838-c406e2be6d6d478b","subject":"环境学导论","chapter":"第6章 固体废物与环境","originalChapter":"第6章 固体废物与环境","originalChapterNumber":6,"section":"第3节 固体废物的防治对策","originalSection":"第3节 固体废物的防治对策","category":"knowledge","title":"尾矿资源化的主要途径","question":"尾矿资源化的主要途径","type":"简答题","answer":"学长提示 : 下面列的一些资源化的技术是冉大老师做的比较多的方向 ， 因此考察的可\n能性比较大 ， 尤其是在复试的笔试中 ， 下面列到的这些大家都混个眼玖 ， 芍读几遍\n尾矿是采矿企业因开采条件限制，或矿石品位较低所放弃的或排\n出的“残留物”。\n①从尾矿中回收有价金属和矿物。将尾矿破碎、筛分、研磨、分\n级，再经重选、浮选或生物浸提等工艺流程，分级选出有价金属；在\n有价金属成分含量很低的情况下，可作水泥或其他建材原料。例如，\n从锡尾矿中回收 Sn、Cu及一些其他伴生元素，从铅锌尾矿中回收 Pb、\nZn、W、Ag等元素，从铜尾矿中回收萤石精矿、硫铁精矿等。\n②尾矿可以作为井下充填材料。尾矿坝是指采用当地土、石或混\n凝土等建筑材料及尾矿，借助山谷地形条件堆筑起来，形成一定容积\n，用以堆存尾矿和储水的坝体。尾矿坝区可以建造生态公园、体育娱\n乐场地等。\n③尾矿可以用于制陶器和水泥。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。","含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":123,"sourceRange":{"startPage":123,"startY":423.7,"endPage":124,"endY":171.85},"sourceKind":"original","originalOrdinal":"8","sourceMetadata":["【重要程度： 】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":6,"excerpts":[{"page":123,"src":"./assets/environment/env838-c406e2be6d6d478b-123.webp"},{"page":124,"src":"./assets/environment/env838-c406e2be6d6d478b-124.webp"}]},{"id":"env838-a4a1af739c913ab1","subject":"环境学导论","chapter":"第6章 固体废物与环境","originalChapter":"第6章 固体废物与环境","originalChapterNumber":6,"section":"第3节 固体废物的防治对策","originalSection":"第3节 固体废物的防治对策","category":"knowledge","title":"煤矸石资源化的主要途径","question":"煤矸石资源化的主要途径","type":"简答题","answer":"煤矸石是采煤和选煤过程中排出的固体废物，是一种在成煤过程\n中与煤伴生的含碳量较低、比煤坚硬的黑色岩石。\n①利用煤矸石生产建筑材料。生产的建筑材料主要包括水泥、砖\n瓦及轻骨料，该利用方向技术成熟，利用量较大。\n②填充采煤塌陷区。利用煤矸石对塌陷区进行填充复垦，既能处\n理煤矸石，减少煤矸石占地，又能恢复塌陷区土地利用价值，这是综\n合治理和恢复矿区生态环境的有效途径。\n③发电。发电是煤研石综合利用的重要途径，也是实现社会、环\n境、经济效益相统一的最有效的途径。在煤炭企业上规模的非煤产业\n项目中，煤矸石发电项目占有绝对比重。目前，全国煤矸石电厂装机\n容量已达500万千瓦以上，每年发电消耗矸石量约5000多万吨，占矸\n石综合利用量的60%以上。\n④生产化工原料。包括生产结晶 (作为净水剂)、水玻璃、\n( ) 化学肥料。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":1,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":124,"sourceRange":{"startPage":124,"startY":171.85,"endPage":124,"endY":644.09},"sourceKind":"original","originalOrdinal":"9","sourceMetadata":["【重要程度:★☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":6,"excerpts":[{"page":124,"src":"./assets/environment/env838-a4a1af739c913ab1-124.webp"}]},{"id":"env838-4fb890113325cca2","subject":"环境学导论","chapter":"第6章 固体废物与环境","originalChapter":"第6章 固体废物与环境","originalChapterNumber":6,"section":"第3节 固体废物的防治对策","originalSection":"第3节 固体废物的防治对策","category":"knowledge","title":"高炉渣资源化","question":"高炉渣资源化","type":"简答题","answer":"高炉渣是指冶炼生铁时从高炉中排放出来的废物。\n①用作建筑材料。高炉渣属于硅酸盐材料的范畴，适合于加工制\n作水泥、碎石、混凝土、骨料等建筑材料。\nY\n②显热回收。炉渣的显热回收方式大致分为两类：一类是利用循\n环空气回收炉渣显热，然后通过余热锅炉以蒸汽形式回收显热；另一\n类是将高温炉渣注入容器内，在容器周围用水循环冷却，以蒸汽形式\n回收炉渣显热。\n③提取有价组分。通过冶金工艺可以从复合矿高炉冶金渣中提取\nTi,Al,Fe, 等有价成分。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":124,"sourceRange":{"startPage":124,"startY":644.09,"endPage":125,"endY":260.72},"sourceKind":"original","originalOrdinal":"10","sourceMetadata":["【重要程度："],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":6,"excerpts":[{"page":124,"src":"./assets/environment/env838-4fb890113325cca2-124.webp"},{"page":125,"src":"./assets/environment/env838-4fb890113325cca2-125.webp"}]},{"id":"env838-b844a721679d51e7","subject":"环境学导论","chapter":"第6章 固体废物与环境","originalChapter":"第6章 固体废物与环境","originalChapterNumber":6,"section":"第3节 固体废物的防治对策","originalSection":"第3节 固体废物的防治对策","category":"knowledge","title":"钢渣资源化","question":"钢渣资源化","type":"简答题","answer":"钢渣是炼钢过程中排出的废渣，主要由铁水和废钢中的元素氧化\n后生成的氧化物、金属炉料带入的杂质、造渣剂和氧化剂、被侵蚀的\n炉衬及补炉材料等组成。\n钢渣资源化的主要途径包括以下几点。\n①用作冶金原料。钢渣含有10% ~30% 的 Fe,40%~60% 的CaO,\n2%的Mn，将钢渣回收用作冶金原料，既可以利用渣中钢粒、 、\nCaO、MgO、MnO、稀有元素等有益成分，提高钢铁生产的质量和产\n量，又能降低生产成本。\n②用作建筑材料。由于钢渣的后期强度较高，配加部分水泥熟料\n，利用熟料早期强度高的优势，制成的钢渣水泥具有强度好、耐磨、\n抗渗等优点；钢渣碎石具有相对密度大、强度高、耐磨等特点，可以\n用作筑路材料。钢渣含FeO、CaO、 等化合物，可作为生产砖、砌\n块等建材。\n③其他方面的应用。钢渣有一定的碱性和较大的比表面积，具有\n化学沉淀和吸附作用，可用作吸附剂处理废水。钢渣含 Ca、Mg、Si、\nP等元素可用来生产磷肥、硅肥，还可以用作土壤改良剂。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":125,"sourceRange":{"startPage":125,"startY":260.72,"endPage":126,"endY":71.4},"sourceKind":"original","originalOrdinal":"11","sourceMetadata":["【重要程度： 、︿"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":6,"excerpts":[{"page":125,"src":"./assets/environment/env838-b844a721679d51e7-125.webp"},{"page":126,"src":"./assets/environment/env838-b844a721679d51e7-126.webp"}]},{"id":"env838-dad8fe83f1fdb74e","subject":"环境学导论","chapter":"第6章 固体废物与环境","originalChapter":"第6章 固体废物与环境","originalChapterNumber":6,"section":"第3节 固体废物的防治对策","originalSection":"第3节 固体废物的防治对策","category":"knowledge","title":"粉煤灰资源化","question":"粉煤灰资源化","type":"简答题","answer":"粉煤灰是煤粉经高温燃烧后形成的一种类似火山灰质的混合材\n料，是燃煤电厂等企业排出的固体废物。\n粉煤灰资源化的主要途径包括以下几点。\n①制作水泥和混凝土。粉煤灰是一种理想的混凝土掺和料。在常\n温有水存在的情况下，粉煤灰中的不定型 和 能与碱金属和\n碱土金属发生“凝硬反应”，因此粉煤灰是一种优良的水泥和混凝土\n掺和料。\n②制作建筑材料。用粉煤灰制砖，工艺简单，速度快，用灰量大\n。可以利用粉煤灰制成各种大型砌块和板材，还可用于烧结制品、铺\n筑道路、构筑坝体、工程回填等方面。另外，粉煤灰还可用于制作轻\n质骨料。\n③用作农业肥料和土壤改良剂。粉煤灰具有良好的物理化学性质\n，能广泛应用于改造重黏土、生土、酸性土和盐碱土。粉煤灰含有大\n量 Si、Ca、Mg、P等农作物所必需的营养元素，故可作农业肥料用。\n④用于回收煤炭资源、回收金属物质、分选空心微珠。利用浮选\n法在含煤炭粉煤灰的灰浆水中加入浮选药剂，然后采用气浮技术，使\n煤粒黏附于气泡上，再上浮与灰渣分离达到回收煤炭的目的；粉煤灰\n含有 、 和大量稀有金属，可以从中回收有用金属；空心微\n珠具有质量小、高强度、耐高温和绝缘性好的特点，可以用作塑料的\n理想填料，广泛用于轻质耐火材料和高效保温材料，用于石油化学工\n业及军工领域。\n⑤用作环保材料。利用粉煤灰可制造分子筛、絮凝剂和吸附材料\n等环保材料；粉煤灰还可用于处理含氟废水、电镀废水与含重金属离\n子废水和含油废水；粉煤灰中含有的 、CaO等活性组分能与氟生\n产配合物或生产对氟有絮凝作用的胶体离子；粉煤灰中还含有沸石、\n莫来石、炭粒和硅胶等，具有无机离子交换特性和吸附脱色作用。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":1,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":126,"sourceRange":{"startPage":126,"startY":71.4,"endPage":127,"endY":173.67},"sourceKind":"original","originalOrdinal":"12","sourceMetadata":["【重要程度: ★☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":6,"excerpts":[{"page":126,"src":"./assets/environment/env838-dad8fe83f1fdb74e-126.webp"},{"page":127,"src":"./assets/environment/env838-dad8fe83f1fdb74e-127.webp"}]},{"id":"env838-4e6d166a9bdb0448","subject":"环境学导论","chapter":"第6章 固体废物与环境","originalChapter":"第6章 固体废物与环境","originalChapterNumber":6,"section":"第3节 固体废物的防治对策","originalSection":"第3节 固体废物的防治对策","category":"knowledge","title":"秸秆资源化技术","question":"秸秆资源化技术","type":"简答题","answer":"秸秆资源化的主要途径包括以下几点。\n①秸秆还田。秸秆含有丰富的有机质和N、P、K、Ca、Mg、S等\n有效肥力元素，因此秸秆还田一直是农民处理秸秆的一个良好方法。\n同时，秸秆还田有恢复和创造土壤团粒结构、固定和保存氮素养料以\n及促进土壤中难溶性养料溶解等作用。\n②秸秆饲料化。秸秆饲料利用技术，目前主要是以秸秆养畜、过\n腹还田的方式进行。未经处理的秸秆不仅消化率低，粗蛋白含量低，\n而且适口性差，采食量也不高，饲养牲畜的效果不好。微生物处理、\n青贮法、氨化法、热喷发等秸秆处理方法，可以提高饲料中蛋白质的\n含量，易于牲畜消化，促进牲畜生长，提高饲料的利用率。\n③秸秆能源化。秸秆能源利用技术包括直接燃烧、热解气化、厌\n氧发酵制取沼气、生产生物质压块燃料等技术。\n④秸秆的其他应用。秸秆可用于生产乙醇、可降解餐具、羧甲基\n纤维素钠，还可利用其特殊的结构构造生产吸附脱色、保温材料、吸\n声材料等。这些都是综合利用农业秸秆，提高其附加值的有效方法。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":127,"sourceRange":{"startPage":127,"startY":173.67,"endPage":127,"endY":672.07},"sourceKind":"original","originalOrdinal":"13","sourceMetadata":["【重要程度："],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":6,"excerpts":[{"page":127,"src":"./assets/environment/env838-4e6d166a9bdb0448-127.webp"}]},{"id":"env838-5ee7cdaf06a3b34e","subject":"环境学导论","chapter":"第6章 固体废物与环境","originalChapter":"第6章 固体废物与环境","originalChapterNumber":6,"section":"第3节 固体废物的防治对策","originalSection":"第3节 固体废物的防治对策","category":"knowledge","title":"畜禽粪便资源化技术","question":"畜禽粪便资源化技术","type":"简答题","answer":"①肥料化利用。畜禽粪便的肥料化再利用模式主要有直接施用、\n栽培食用菌利用和堆腐后施用三种情况。目前，加入的辅料主要为含\n碳量较高的稻草或者秸秆及无机肥料、石膏等。畜禽粪便的堆腐后施\n用是目前最为常用的肥料化方法，是在人为控制条件下进行的。\n②饲料化利用。畜禽粪便中含有未消化的粗蛋白、粗纤维、粗脂\n肪和矿物质等，经过适当处理杀死病原菌后，能提高蛋白质的消化率\n和代谢能，改善适口性，可作为饲料来利用。目前，畜禽粪便的饲料\n化主要利用模式有直接喂养、干燥法和热喷法等。用鸡粪混合垫草直\n接饲喂奶牛的方式已被许多西方国家所采用，在饲料中混入上述粪草\n饲喂奶牛，其结果与饲喂豆饼饲料的效果相同，此方法简便易行，效\n果也较好，但要做好卫生防疫工作，避免疫病的发生和传播。\n③能源化利用。能源化利用主要有直接燃烧、乙醇化利用、沼气\n化利用、发电利用和热解技术利用等。沼气化利用在我国应用较为广\n泛，即利用受控制的厌氧细菌的分解作用，将粪便中的有机物转化成\n简单的有机酸，然后再将简单的有机酸转化为甲烷和二氧化碳。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":127,"sourceRange":{"startPage":127,"startY":672.07,"endPage":128,"endY":449.35},"sourceKind":"original","originalOrdinal":"14","sourceMetadata":["【重要程度：7"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":6,"excerpts":[{"page":127,"src":"./assets/environment/env838-5ee7cdaf06a3b34e-127.webp"},{"page":128,"src":"./assets/environment/env838-5ee7cdaf06a3b34e-128.webp"}]},{"id":"env838-28e24b796be59be0","subject":"环境学导论","chapter":"第6章 固体废物与环境","originalChapter":"第6章 固体废物与环境","originalChapterNumber":6,"section":"第3节 固体废物的防治对策","originalSection":"第3节 固体废物的防治对策","category":"knowledge","title":"控制危险废物越境转移的对策","question":"控制危险废物越境转移的对策","type":"简答题","answer":"①首先，应加强宣传工作，提高世界各国的环境意识；\n加强环保宣传工作，提高环保意识对于控制危险废物越境转移是\n很重要的。各国，尤其是发展中国家，有必要利用各种宣传工具对危\n险废物的危害和巴塞尔公约的基本原则进行大力宣传。\n②其次，要加强国际间的广泛交流和合作\n合作的目的，在于使各国都建立起有效的废物管理系统，普遍推\n广清洁生产工艺、废物处置和综合利用技术及高水平的管理方法等。\n③第三，各国应建立完善的法律制度，以法律作为严格管理的依\n据；\n法律不健全，是造成危险废物管理混乱的一个主要原因。因此，\n各国政府应加快国内立法，早日予以实施，做到有法可依。\n④第四，建立并完善统一的国际公约及公约维护机构\n拓展知识点 2: 巴塞尔公约的基本原则和内容\n[待核对] OFX, MARR GR LMA LHR;\n@ 其次 ， 应尽量减少危险废物的产生量 ;\n图第三 ， 对于不可吉免而产生的危险废物 ， 应尽可能以对环境无害的方式处置 ， 并应\n尽量在产生地处置 。 须帮助发展中国家建立起最有效的管理危险废物的能力 ;\n图第四 ， 只有在特殊情况下 ， 当危险废物的产生国没有合适的处置设施时 ， 才允许将\n危险废物出口到其他国家 ， 并以对人体健康和环境更为安全的方式处置 。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2014,2020],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。","含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":128,"sourceRange":{"startPage":128,"startY":449.35,"endPage":130,"endY":76.53},"sourceKind":"original","originalOrdinal":"15","sourceMetadata":["2020(简,【重要程度:","2014 (ft, (HRB: toktoiot]"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":6,"excerpts":[{"page":128,"src":"./assets/environment/env838-28e24b796be59be0-128.webp"},{"page":129,"src":"./assets/environment/env838-28e24b796be59be0-129.webp"},{"page":130,"src":"./assets/environment/env838-28e24b796be59be0-130.webp"}]},{"id":"env838-515575c8a648b5b9","subject":"环境学导论","chapter":"第6章 固体废物与环境","originalChapter":"第6章 固体废物与环境","originalChapterNumber":6,"section":"第4节 课后习题","originalSection":"第4节 课后习题","category":"exercise","title":"固体废物的定义是什么?","question":"固体废物的定义是什么?","type":"简答题","answer":"整理答案（按教材对应知识点摘录）：\n\n固体废物的定义：\n固体废物，是指在生产、生活和其他活动中产生的丧失原有利用\n价值或者虽未丧失利用价值但被抛弃或者放弃的固态、半固态和置于\n容器中的气态的物品、物质以及法律、行政法规规定纳入固体废物管\n理的物品、物质。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["根据所列知识点摘录整理，未逐题人工审定。"],"verified":false,"page":130,"sourceRange":{"startPage":130,"startY":114.32,"endPage":130,"endY":189.38},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":6,"references":[{"id":"env838-38127699127d2295","title":"固体废物的定义","source":"环境学导论.pdf","page":117}],"excerpts":[{"page":130,"src":"./assets/environment/env838-515575c8a648b5b9-130.webp"}]},{"id":"env838-e5a4a386900442fa","subject":"环境学导论","chapter":"第6章 固体废物与环境","originalChapter":"第6章 固体废物与环境","originalChapterNumber":6,"section":"第4节 课后习题","originalSection":"第4节 课后习题","category":"exercise","title":"固体废物的危害有哪些?","question":"固体废物的危害有哪些?","type":"简答题","answer":"整理答案（按教材对应知识点摘录）：\n\n固体废物的危害：\n①侵占土地。固体废物不加利用时必然占地堆放，堆积量越大，\n占地也越多。\n②污染土壤和地下水。废物堆置或没有适当防渗措施的垃圾填埋\n，其中的有害组分很容易随着渗滤液浸出而污染土壤及地下水。一方\n面，人类的健康受到威胁；另一方面，工业固体废物会破坏土壤生态\n平衡。\n③污染水体。除对地下水的污染外，由于不少国家把固体废物直\n接倾入河流、湖泊和海洋，使地表水受到严重影响-不仅减少水体面积\n，而且还妨害水生生物的生存和水资源的利用。\n④污染大气。固体废物污染大气环境一般通过如下途径：尾矿粉\n煤灰、污泥和垃圾中的尘粒随风飞扬；运输过程中产生的有害气体和\n粉尘；固体废物本身或在处理时散发毒气和臭味等。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["根据所列知识点摘录整理，未逐题人工审定。"],"verified":false,"page":130,"sourceRange":{"startPage":130,"startY":189.38,"endPage":130,"endY":264.2},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":6,"references":[{"id":"env838-adecc1376b7b1fae","title":"固体废物的危害","source":"环境学导论.pdf","page":117}],"excerpts":[{"page":130,"src":"./assets/environment/env838-e5a4a386900442fa-130.webp"}]},{"id":"env838-91364eb6afdf5833","subject":"环境学导论","chapter":"第6章 固体废物与环境","originalChapter":"第6章 固体废物与环境","originalChapterNumber":6,"section":"第4节 课后习题","originalSection":"第4节 课后习题","category":"exercise","title":"“三化”原则指什么?具体含义?","question":"“三化”原则指什么?具体含义?","type":"简答题","answer":"整理答案（按教材对应知识点摘录）：\n\n固废处理的三化原则：\n[1] 减量化\n减量化一般指减少固体废物的产生量或危害性。这里包括两层意\n思，一是数量的减少，另一种是固体废物对环境的危害性质下降。也\n就是说，通过适宜的手段最大限度地合理开发和利用资源与能源，减\n少固体废物数量或体积，降低危险废物的有害成分、减轻或清除其危\n险特性等，从“源头”直接减少或减轻固体废物对环境和人体健康的\n危害。\n[2] 资源化\n资源化是指将废物直接作为原料进行利用或者对废物进行再生\n利用。自然界并不存在绝对的废物，所谓废物只是失去原有使用价值\n而被弃置的物质，并不是永远没有使用价值。现在不能利用的，也许\n将来可以利用。这一生产过程的废物，可能是另一生产过程的原料，\n所以固体废物有“放错地方的原料”之称。\n[3] 无害化\n无害化是指经过适当的处理或处置，使固体废物或其中的有害成\n分无法危害环境，或转化为对环境无害的物质，这个处置过程即为固\n体废物的无害化。常用的方法有填埋法、焚烧法、堆肥法、热解法、\n化学法等。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["根据所列知识点摘录整理，未逐题人工审定。"],"verified":false,"page":130,"sourceRange":{"startPage":130,"startY":264.2,"endPage":130,"endY":341.74},"sourceKind":"original","originalOrdinal":"3","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":6,"references":[{"id":"env838-c4c36a31f9227554","title":"固废处理的三化原则","source":"环境学导论.pdf","page":118}],"excerpts":[{"page":130,"src":"./assets/environment/env838-91364eb6afdf5833-130.webp"}]},{"id":"env838-a12992710f2fd23f","subject":"环境学导论","chapter":"第6章 固体废物与环境","originalChapter":"第6章 固体废物与环境","originalChapterNumber":6,"section":"第4节 课后习题","originalSection":"第4节 课后习题","category":"exercise","title":"固体废物的主要处理、处置技术有哪些?","question":"固体废物的主要处理、处置技术有哪些?","type":"简答题","answer":"处理技术：①分选、破碎、压实、脱水等预处理，便于后续利用及运输；②焚烧、热解等热处理，适于相应可燃组分；③好氧堆肥、厌氧消化等生物处理，适于可生物降解有机废物；④固化／稳定化等，降低某些有害成分的迁移性。\n资源化：材料回收、再生利用、能量回收等，应保证产品和排放安全。\n最终处置：符合要求的卫生填埋、安全填埋及其他获准方式，区别生活垃圾和危险废物的管理要求。\n应按废物性质组合工艺，优先减量、再用及资源化，处理飞灰、渗滤液和废气等二次污染。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":130,"sourceRange":{"startPage":130,"startY":341.74,"endPage":130,"endY":418.84},"sourceKind":"original","originalOrdinal":"4","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":6,"excerpts":[{"page":130,"src":"./assets/environment/env838-a12992710f2fd23f-130.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=116"},{"title":"巴塞尔公约秘书处：公约概览","url":"https://www.basel.int/Default.aspx?tabid=1271","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-ed226d199698c2af","subject":"环境学导论","chapter":"第6章 固体废物与环境","originalChapter":"第6章 固体废物与环境","originalChapterNumber":6,"section":"第4节 课后习题","originalSection":"第4节 课后习题","category":"exercise","title":"什么是危险废物越境迁移以及其控制政策?","question":"什么是危险废物越境迁移以及其控制政策?","type":"简答题","answer":"危险废物越境迁移是危险废物从一国管辖范围移往或途经另一国管辖范围，或移往无国家管辖区域的跨境转移活动。风险包括向管理能力弱地区转移污染、非法倾倒及运输事故。\n控制核心：①减少危险废物产生；②在符合环境无害化管理的条件下尽可能就近处理；③越境转移实行事先知情同意，涉及出口国、进口国和过境国的相应通知与同意程序；④保证运输、处置及责任安排合规；⑤防范并追究非法转移。\n《巴塞尔公约》构成主要国际框架；实际转移还必须满足相关国家的进口禁限规定，不能只凭合同或一方许可。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":130,"sourceRange":{"startPage":130,"startY":418.84,"endPage":130,"endY":496.77},"sourceKind":"original","originalOrdinal":"5","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":6,"excerpts":[{"page":130,"src":"./assets/environment/env838-ed226d199698c2af-130.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=116"},{"title":"巴塞尔公约秘书处：公约概览","url":"https://www.basel.int/Default.aspx?tabid=1271","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-2a85982e4df83a77","subject":"环境学导论","chapter":"第6章 固体废物与环境","originalChapter":"第6章 固体废物与环境","originalChapterNumber":6,"section":"第4节 课后习题","originalSection":"第4节 课后习题","category":"exercise","title":"了解巴塞尔公约的基本原则和基本内容。","question":"了解巴塞尔公约的基本原则和基本内容。","type":"简答题","answer":"《巴塞尔公约》主要针对危险废物及其他相关废物的越境转移和处置。\n原则：减少产生量及危害，推动环境无害化管理，减少不必要的越境转移，并开展国际合作。\n核心内容：界定受控废物范围及缔约方义务；建立事先通知与知情同意程序；要求具备相应的运输、处置及管理安排；规范非法转移的处理和有关责任；促进技术、信息与能力建设。\n理解要点：公约不是鼓励以出口代替本国污染治理，越境转移也不因形式上“可回收”就自动合法。具体废物流还需结合修正案及各国法律判断。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":130,"sourceRange":{"startPage":130,"startY":496.77,"endPage":131,"endY":73.04},"sourceKind":"original","originalOrdinal":"6","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":6,"excerpts":[{"page":130,"src":"./assets/environment/env838-2a85982e4df83a77-130.webp"},{"page":131,"src":"./assets/environment/env838-2a85982e4df83a77-131.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=116"},{"title":"巴塞尔公约秘书处：公约概览","url":"https://www.basel.int/Default.aspx?tabid=1271","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-1c4835b0e93b485d","subject":"环境学导论","chapter":"第6章 固体废物与环境","originalChapter":"第6章 固体废物与环境","originalChapterNumber":6,"section":"第1节","originalSection":"第1节","category":"supplement","title":"固体废物的分类","question":"固体废物的分类","type":"简答题","answer":"固体废物来源广泛，种类繁多，组分复杂，分类方法亦有多种。为了便于管\n理，通常按其来源分类，在《中华人民共和国固体废物污染环境防治法》中将固\n体废物分为生活垃圾、工业固体废物、建筑垃圾、农业固体废物和危险废物五类。","source":"环导变动137718728584015123.1eae00877280d3e.pdf","sourceUrl":"https://drive.google.com/file/d/11CjvWmrS4poAVMmBBWnsJPRCmD1-JkRJ/view","version":"new","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":12,"sourceRange":{"startPage":12,"startY":283.36,"endPage":12,"endY":417.4},"sourceKind":"changes","originalOrdinal":"2","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":6,"excerpts":[{"page":12,"src":"./assets/environment/env838-1c4835b0e93b485d-12.webp"}]},{"id":"env838-86dba28d3c650c13","subject":"环境学导论","chapter":"第7章 物理环境","originalChapter":"第7章 物理环境","originalChapterNumber":7,"section":"第1节 噪声污染","originalSection":"第1节 噪声污染","category":"knowledge","title":"噪声的定义","question":"噪声的定义","type":"简答题","answer":"一般认为凡是不需要的，使人厌烦的，并对人类生产和生活有妨\n碍的声音。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2004,2013],"needsReview":false,"reviewReasons":[],"verified":false,"page":132,"sourceRange":{"startPage":132,"startY":112.05,"endPage":132,"endY":249.73},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":["2004(名、2013(简, 【重要程度:"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":7,"excerpts":[{"page":132,"src":"./assets/environment/env838-86dba28d3c650c13-132.webp"}]},{"id":"env838-e083b454968ae662","subject":"环境学导论","chapter":"第7章 物理环境","originalChapter":"第7章 物理环境","originalChapterNumber":7,"section":"第1节 噪声污染","originalSection":"第1节 噪声污染","category":"knowledge","title":"噪声的来源及分类","question":"噪声的来源及分类","type":"简答题","answer":"根据物体振动的物理特性，噪声可以分为两大类：机械振动噪声\n和气体动力噪声。就城市环境噪声而言，则其大致来源可分为交通噪\n声、工厂噪声和生活噪声。\n①交通噪声：其中城市环境噪声的70%来源于交通噪声，而且汽\n车、火车、飞机等交通运输工具都是活动的噪声源，其影响面广。交\n通噪声主要来源于交通运输工具的行驶、震动和喇叭声。\n②工厂噪声：工厂噪声来自生产过程和市政施工中机械震动、摩\n擦、撞击以及气流扰动等产生的声音\n③生活噪声：即为街道和建筑物内部各种生活设施，人群活动等\n产生的声音。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":1,"pastExamYears":[2000],"needsReview":false,"reviewReasons":[],"verified":false,"page":132,"sourceRange":{"startPage":132,"startY":249.73,"endPage":132,"endY":619.16},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":["2000( 填, 【重要程度: ★☆☆☆☆"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":7,"excerpts":[{"page":132,"src":"./assets/environment/env838-e083b454968ae662-132.webp"}]},{"id":"env838-4a9759e883c879d3","subject":"环境学导论","chapter":"第7章 物理环境","originalChapter":"第7章 物理环境","originalChapterNumber":7,"section":"第1节 噪声污染","originalSection":"第1节 噪声污染","category":"knowledge","title":"噪声的特点","question":"噪声的特点","type":"简答题","answer":"①主观性：对噪声的感受因各人的感觉、习惯等而不同，因此噪\n声有时是一个主观的感受，任何声音都可能成为噪声。\n②瞬时性：噪声无残余污染物，不会积累，噪声源停止运行后，\n污染即消失。\n③局部性污染性：一般不会造成区域性和全球性污染。\n④隐蔽性：一般不直接致命或治病，危害是慢性而间接的。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":1,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":132,"sourceRange":{"startPage":132,"startY":619.16,"endPage":133,"endY":143.26},"sourceKind":"original","originalOrdinal":"3","sourceMetadata":["【重要程度:★☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":7,"excerpts":[{"page":132,"src":"./assets/environment/env838-4a9759e883c879d3-132.webp"},{"page":133,"src":"./assets/environment/env838-4a9759e883c879d3-133.webp"}]},{"id":"env838-7d43a41dadf35592","subject":"环境学导论","chapter":"第7章 物理环境","originalChapter":"第7章 物理环境","originalChapterNumber":7,"section":"第1节 噪声污染","originalSection":"第1节 噪声污染","category":"knowledge","title":"噪声的危害","question":"噪声的危害","type":"简答题","answer":"①干扰睡眠。噪声会影响人的睡眠质量和数量，老年人和病人对\n噪声干扰更敏感\n②损伤听力。噪声可以使人造成暂时性的或持久性的听力损伤，\n后者即耳聋。\n③对人体生理的影响。噪声会引起人体紧张的反应，刺激肾上素\n的分泌，因而引起心率的改变和血压升高。噪声会使人的唾液、胃液\n分泌减少，胃酸降低，从而易患胃溃疡和十二指肠溃疡。噪声对人的\n内分泌机能也会产生影响。噪声也可能是刺激癌症的病因之一。\n④对儿童和胎儿的影响。在噪声环境下，儿童的智力发育缓慢。\n噪声与胎儿的畸形有关，还影响胎儿的体重。\n⑤对动物的影响。强噪声会使鸟类羽毛脱落、不下蛋，甚至内出\n血，最终死亡\n⑥对建筑的损害。高强度的噪声可使墙震裂、瓦震落、门窗破坏。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":1,"pastExamYears":[2012],"needsReview":false,"reviewReasons":[],"verified":false,"page":133,"sourceRange":{"startPage":133,"startY":143.26,"endPage":133,"endY":588.81},"sourceKind":"original","originalOrdinal":"4","sourceMetadata":["2012( 简, 【重要程度: ★☆☆☆☆"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":7,"excerpts":[{"page":133,"src":"./assets/environment/env838-7d43a41dadf35592-133.webp"}]},{"id":"env838-cf00cf1eef57cdcc","subject":"环境学导论","chapter":"第7章 物理环境","originalChapter":"第7章 物理环境","originalChapterNumber":7,"section":"第1节 噪声污染","originalSection":"第1节 噪声污染","category":"knowledge","title":"噪声的控制","question":"噪声的控制","type":"简答题","answer":"[1] 控制噪声的原理\n噪声的传播一般分为三个阶段：噪声源、传播途径、接受者。传\n播途径包括反射、衍射等形式的声波行进过程。控制噪声的原理，就\n是在噪声到达耳膜之前，采取阻尼、隔振、吸声、隔声、消声器、个\n人防护和建筑布局等七大措施，尽力减弱或降低声源的振动，或将传\n播中的声能吸收掉，或设置障碍，使声音全部或部分反射出去，减弱\n噪声对耳膜的作用，这样即可达到控制噪声的目的。\n[2] 控制噪声的途径\n①从声源上控制噪声。这是最根本的方面，包括研制和采用噪声\n低的设备和加工工艺等措施。\n②在传输途径上控制噪声。这是采用声学处理的方法，如吸声、\n隔声、阻尼、隔振等来降低噪声；\n③在接收点控制噪声。在上述两种控制方法失效时，应采用耳塞\n、耳棉、防声蜡棉以及防护面具等个人防护措施；\n④然而控制城市噪声最有效而经济的方法，首先不是技术措施，\n而是宣传教育，把噪声的来源、危害和控制措施向公众讲解，广泛发\n动公众控制噪声；其次是加强行政管理，其中极重要的是国家制定控\n制噪声的标准和规范及其贯彻执行所必需的规章法令。区域规划则要\n合理地使居民远离噪声源，以尽量减少交通和工业噪声对居民的影响","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2019],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":133,"sourceRange":{"startPage":133,"startY":588.81,"endPage":135,"endY":74.49},"sourceKind":"original","originalOrdinal":"5","sourceMetadata":["2019(简, 【重要程度:"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":7,"excerpts":[{"page":133,"src":"./assets/environment/env838-cf00cf1eef57cdcc-133.webp"},{"page":134,"src":"./assets/environment/env838-cf00cf1eef57cdcc-134.webp"},{"page":135,"src":"./assets/environment/env838-cf00cf1eef57cdcc-135.webp"}]},{"id":"env838-8fd9e946305b84ad","subject":"环境学导论","chapter":"第7章 物理环境","originalChapter":"第7章 物理环境","originalChapterNumber":7,"section":"第1节 噪声污染","originalSection":"第1节 噪声污染","category":"knowledge","title":"噪声的几个重要的声学特性","question":"噪声的几个重要的声学特性","type":"简答题","answer":"[待核对] OF EHP EMR\n© 声压是声波传播时引起空气压强的瞬时变化量 ， 即声扰动产生的逾量压强 (声波\n作用下的压强与静态大气压的差值 ) 。 单位 : 帕斯卡 (Pa)\n© 声压级是对声压取对数后的主观量度 ， 用于将希大的声压范围压缩为更易理解的\n数值 。 单位 : RM (dB)\n@A 声级\nA 声级是通过 A 计权网络测得的声压级 ， 模拟人耳对不同频率声音的敏感特性 。\n人耳对低频 (如 20Hz) 和高频 (如 20kHz) 声音的感知较弱 ， 而对中频 〈 约 1kHz) 最\n教感 。A 计权通过滤波器降低低频和高频的权重 ， 使测量结果更接近人耳的主观感受\n@@ 等效连续 A 声级 (Leq)\n等效连续 A 声级是非稳态嗓声在时间上的能量平均值 ， 用 Leq 表示 。 它将一段时间\n内波动的 A 声级等效为单一连续声级 ， 反映噪声的总体能量强度\n图统计声级\n统计声级 〔〈 又称累积百分声级 ) 表示在测量时间内 ， 超过某一百分比时间的 A 声\n级最小值 。 常用指标包括 ;\nLio: 10% 时间超过的声级 〈 嗓声峰值 ) 。\nLoo: 50% 时间超过的声级 〈 中值声级 ) 。\nLoo: 90% 时间超过的声级 〈 背景噪声 )","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2000,2001,2005,2009,2011,2013,2014,2016,2018],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。"],"verified":false,"page":135,"sourceRange":{"startPage":135,"startY":74.49,"endPage":135,"endY":641.83},"sourceKind":"original","originalOrdinal":"supp-1","sourceMetadata":["2005 (4%, (BEBE: ktokdtok)","2011 (名 、2013〈 名 、2014〈 简 、2016〈 名 、2018 (名 ，【 重要程度 ， 友妇女衣广 】","2000 ( 填 、2001 GH. 2014 (fi. 2018 (4, (BEBE: 妇女妈妈六了","2009 (4%, [BRBE: kkk]"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":7,"excerpts":[{"page":135,"src":"./assets/environment/env838-8fd9e946305b84ad-135.webp"}]},{"id":"env838-8f08b1919799d131","subject":"环境学导论","chapter":"第7章 物理环境","originalChapter":"第7章 物理环境","originalChapterNumber":7,"section":"第2节 热污染","originalSection":"第2节 热污染","category":"knowledge","title":"热污染的定义","question":"热污染的定义","type":"简答题","answer":"热污染是指人类生产和生活中排放出的废热造成的环境热化，损\n坏环境质量，进而又影响人类生产、生活的一种增温效应，这种增温\n效应达到损害环境质量的程度，便成为热污染。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":135,"sourceRange":{"startPage":135,"startY":681.59,"endPage":136,"endY":173.63},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":["【重要程度： ^ 1"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":7,"excerpts":[{"page":135,"src":"./assets/environment/env838-8f08b1919799d131-135.webp"},{"page":136,"src":"./assets/environment/env838-8f08b1919799d131-136.webp"}]},{"id":"env838-21677479f3f21bc3","subject":"环境学导论","chapter":"第7章 物理环境","originalChapter":"第7章 物理环境","originalChapterNumber":7,"section":"第2节 热污染","originalSection":"第2节 热污染","category":"knowledge","title":"热污染的来源","question":"热污染的来源","type":"简答题","answer":"[1]水体热污染的来源\n当人类排向自然水域的温热水使受纳水域的温升超过一定限度\n时，就会破坏该水域的自然生态平衡，导致水质变化，威胁水生生物\n的生存，进而影响人类对该水域的正常利用，这种现象即为水体的热\n污染。\n工业冷却水与核电站都是水体热污染的主要热量来源。\n[2]大气热污染的来源\n能源是社会发展和人类进步的命脉。随着能源消耗的加剧，越来\n越多的副产物 、水蒸气和颗粒物被排放到大气中。水蒸气吸收从\n地面辐射的紫外线，颗粒物吸收从太阳辐射来的能量，加之人类活动\n向大气中释放的能量，使大气温度不断升高，即为大气热污染。\n大气热污染主要来源于城市大量燃料燃烧过程所产生的废热，以\n及高温产品、炉渣和化学反应产生的废热等。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":0,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":136,"sourceRange":{"startPage":136,"startY":173.63,"endPage":136,"endY":623.21},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":["【重要程度:☆☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":7,"excerpts":[{"page":136,"src":"./assets/environment/env838-21677479f3f21bc3-136.webp"}]},{"id":"env838-8c51a76f26db17aa","subject":"环境学导论","chapter":"第7章 物理环境","originalChapter":"第7章 物理环境","originalChapterNumber":7,"section":"第2节 热污染","originalSection":"第2节 热污染","category":"knowledge","title":"热岛效应的定义","question":"热岛效应的定义","type":"简答题","answer":"度：\n在人口稠密、工业集中的城市地区，由于人类活动排放的大量热\n量与其他自然条件共同作用致使城区气温普遍高于周围郊区，称为城\n市热岛效应。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2001,2005,2007,2008,2009,2012,2014],"needsReview":false,"reviewReasons":[],"verified":false,"page":136,"sourceRange":{"startPage":136,"startY":623.21,"endPage":137,"endY":103.57},"sourceKind":"original","originalOrdinal":"3","sourceMetadata":["2001(名、2005(名、2007(名、2008(名、2009(名、2012(名、2014(名,【重要程"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":7,"excerpts":[{"page":136,"src":"./assets/environment/env838-8c51a76f26db17aa-136.webp"},{"page":137,"src":"./assets/environment/env838-8c51a76f26db17aa-137.webp"}]},{"id":"env838-872b13aeb1a3993b","subject":"环境学导论","chapter":"第7章 物理环境","originalChapter":"第7章 物理环境","originalChapterNumber":7,"section":"第2节 热污染","originalSection":"第2节 热污染","category":"knowledge","title":"温室效应","question":"温室效应","type":"简答题","answer":"太阳短波辐射可以透过大气射入地面，而地面增暖后释放的长波\n辐射又被大气中的 等物质所吸收，大气中的 就像一层厚厚的\n玻璃，使地球变成了一个大暖房，使地球发生可感觉到的气温升高。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2000,2002,2003,2012],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":137,"sourceRange":{"startPage":137,"startY":103.57,"endPage":137,"endY":275.01},"sourceKind":"original","originalOrdinal":"4","sourceMetadata":["2000(名、2002(名、2003(名、2012(名,【重要程度:"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":7,"excerpts":[{"page":137,"src":"./assets/environment/env838-872b13aeb1a3993b-137.webp"}]},{"id":"env838-14e4a124637ce750","subject":"环境学导论","chapter":"第7章 物理环境","originalChapter":"第7章 物理环境","originalChapterNumber":7,"section":"第2节 热污染","originalSection":"第2节 热污染","category":"knowledge","title":"热污染对环境的影响","question":"热污染对环境的影响","type":"简答题","answer":"首先，热污染使得水体中各类无机氮的含量都增加，原因是水温\n升高使得藻类的繁殖加快和固氮藻的固氮速率增大。热污染会促使水\n体富营养化；\n其二，水温升高使得藻类种群结构发生改变。藻类种群结构的改\n变反过来又直接影响鱼类饵料的质量；\n其三，水体温度升高也会影响浮游动物的生存；\n其四，在强增温区，底栖动物的增加也十分突出；\n其五，由于水体周围气温升高，栖息在该地区的昆虫将提前苏醒\n，而远离该地区的本该苏醒的昆虫却处于休眠状态。昆虫苏醒次序的\n这种更迭，会造成有关生态系统中食物链的中断，破坏生态平衡，使\n提前苏醒的昆虫大批死亡，甚至灭绝。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":1,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":137,"sourceRange":{"startPage":137,"startY":275.01,"endPage":137,"endY":674.86},"sourceKind":"original","originalOrdinal":"5","sourceMetadata":["【重要程度:★☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":7,"excerpts":[{"page":137,"src":"./assets/environment/env838-14e4a124637ce750-137.webp"}]},{"id":"env838-716022571678a6ed","subject":"环境学导论","chapter":"第7章 物理环境","originalChapter":"第7章 物理环境","originalChapterNumber":7,"section":"第3节 电磁辐射","originalSection":"第3节 电磁辐射","category":"knowledge","title":"电磁辐射污染的定义","question":"电磁辐射污染的定义","type":"简答题","answer":"电磁辐射是以电磁波的形式向空间环境中传播能量的现象或过\n程。电磁辐射污染是指人类使用产生电磁辐射的器具泄漏的电磁能量\n传播到室内外空间中，其量超出环境本底值，引起周围受辐射影响人\n群的不适感，并使人体健康和生态环境受到损害。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":1,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":137,"sourceRange":{"startPage":137,"startY":715.08,"endPage":138,"endY":193.94},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":["【重要程度: ★☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":7,"excerpts":[{"page":137,"src":"./assets/environment/env838-716022571678a6ed-137.webp"},{"page":138,"src":"./assets/environment/env838-716022571678a6ed-138.webp"}]},{"id":"env838-e49e92cbc412e33b","subject":"环境学导论","chapter":"第7章 物理环境","originalChapter":"第7章 物理环境","originalChapterNumber":7,"section":"第3节 电磁辐射","originalSection":"第3节 电磁辐射","category":"knowledge","title":"电磁辐射对人体健康的危害","question":"电磁辐射对人体健康的危害","type":"简答题","answer":"[1]电磁辐射的致癌作用\n一些微波生物学家的实验表明，电磁辐射会促使人体内的遗传基\n因微粒细胞染色体发生突变和有丝分裂异常，而使某些组织出现病理\n性增生过程，使正常细胞变为癌细胞。\n[2]对视觉系统的影响\n长期低强度电磁辐射的作用，可促进视觉疲劳，眼感到不舒适和\n感到干燥等现象。强度更高的微波，则会傸视力完全消失。\n[3]对生殖系统和遗传的影响\n长期接触超短波发生器，会影响生育能力。\n[4]对血液系统和机体免疫功能的影响\n在电磁辐射的作用下，周围血象可出现白细胞不稳定的情况，主\n要是下降倾向，红细胞的生成受到抑制。电磁辐射会使人体的白细胞\n吞噬细菌的百分率和吞噬的细菌数均下降。\n(5)引起心血管疾病\n受电磁辐射作用的人常发生血流动力学失调，血管通透性和张力\n降低。由于植物神经调节功能受到影响，人们多数出现心动过缓症状\n，少数呈现心动过速。\n(6 )对中枢神经系统的危害\n神经系统对电磁辐射的作用很敏感，受其低强度反复作用后，中\n枢神经机能发生改变，出现神经衰弱症候群。\n(7 )对胎儿的影响","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":138,"sourceRange":{"startPage":138,"startY":193.94,"endPage":139,"endY":170.11},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":["【重要程度： 】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":7,"excerpts":[{"page":138,"src":"./assets/environment/env838-e49e92cbc412e33b-138.webp"},{"page":139,"src":"./assets/environment/env838-e49e92cbc412e33b-139.webp"}]},{"id":"env838-067f2e15c024396f","subject":"环境学导论","chapter":"第7章 物理环境","originalChapter":"第7章 物理环境","originalChapterNumber":7,"section":"第3节 电磁辐射","originalSection":"第3节 电磁辐射","category":"knowledge","title":"电磁污染防护措施","question":"电磁污染防护措施","type":"简答题","answer":"[1]执行电磁辐射安全标准\n尽快制定各种法规、标准、监察管理条例，做到依法治理。\n[2] 采取防护措施\n从城市规划、产品设计、电磁屏蔽和吸收等角度着手，采取标本\n兼治的方案防护和治理电磁污染。\n[3]加强宣传教育，提高公众认识\n广泛开展宣传教育，唤起人们防护意识。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":0,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":139,"sourceRange":{"startPage":139,"startY":170.11,"endPage":139,"endY":453.65},"sourceKind":"original","originalOrdinal":"3","sourceMetadata":["【重要程度: ☆☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":7,"excerpts":[{"page":139,"src":"./assets/environment/env838-067f2e15c024396f-139.webp"}]},{"id":"env838-650a183418c26542","subject":"环境学导论","chapter":"第7章 物理环境","originalChapter":"第7章 物理环境","originalChapterNumber":7,"section":"第4节 光污染","originalSection":"第4节 光污染","category":"knowledge","title":"光污染定义","question":"光污染定义","type":"简答题","answer":"光污染是现代社会中伴随着新技术的发展而出现的环境问题。当\n光辐射过量时，就会对人们的生活、工作环境以及人体健康产生\n不利影响，称之为光污染。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":1,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":139,"sourceRange":{"startPage":139,"startY":494.56,"endPage":139,"endY":661.02},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":["【重要程度: ★☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":7,"excerpts":[{"page":139,"src":"./assets/environment/env838-650a183418c26542-139.webp"}]},{"id":"env838-89f4e2573807a2a0","subject":"环境学导论","chapter":"第7章 物理环境","originalChapter":"第7章 物理环境","originalChapterNumber":7,"section":"第4节 光污染","originalSection":"第4节 光污染","category":"knowledge","title":"光污染的危害","question":"光污染的危害","type":"简答题","answer":"[1]对人体健康的影响\n人体受光污染危害首先是眼睛。瞬间的强光照射会使人们出现短\n暂的失明。普通光污染可对人眼的角膜和虹膜造成伤害，抑制视网膜\n感光细胞功能的发挥，引起视疲劳和视力下降。\n[2]对生态的破坏\n很多动物受到过多的人工光线的照射时，会影响它们的生活习性\n和新陈代谢，引发一些怪异的行为。\n[3]对交通系统的影响\n各种交通线路上的照明设备或附近体育场和商业照明设备发出\n的光线都会对车辆的驾驶者产生影响，降低交通的安全性。\n在烈日照射下，驾驶者和行人会遭到玻璃幕墙反射光的影响，视\n觉功能受到影响，增加交通的危险性。\n[4]对天文观测的影响\n各种照明设备发出的光线经过空气和大气中悬浮尘埃的散射，使\n夜空亮度增加，对天体观察造成不利的影响。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":0,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":139,"sourceRange":{"startPage":139,"startY":661.02,"endPage":140,"endY":478.84},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":["【重要程度: ☆☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":7,"excerpts":[{"page":139,"src":"./assets/environment/env838-89f4e2573807a2a0-139.webp"},{"page":140,"src":"./assets/environment/env838-89f4e2573807a2a0-140.webp"}]},{"id":"env838-102de4414bd689c1","subject":"环境学导论","chapter":"第7章 物理环境","originalChapter":"第7章 物理环境","originalChapterNumber":7,"section":"第5节 放射性污染","originalSection":"第5节 放射性污染","category":"knowledge","title":"放射性污染的定义","question":"放射性污染的定义","type":"简答题","answer":"放射性污染主要是指因人类的生产、生活活动排放的放射性物质\n所产生的电离辐射超过放射环境标准时，产生放射性污染而危害人体\n健康的一种现象，主要指对人体健康带来危害的人工放射性污染。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":140,"sourceRange":{"startPage":140,"startY":519.97,"endPage":140,"endY":685.18},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":["【重要程度："],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":7,"excerpts":[{"page":140,"src":"./assets/environment/env838-102de4414bd689c1-140.webp"}]},{"id":"env838-a11ae09be4c94ff3","subject":"环境学导论","chapter":"第7章 物理环境","originalChapter":"第7章 物理环境","originalChapterNumber":7,"section":"第6节 振动","originalSection":"第6节 振动","category":"knowledge","title":"震动污染","question":"震动污染","type":"简答题","answer":"振动污染是指振动超过一定的界限时，对人体的健康和设施产生\n损害，对人的生活和工作环境形成干扰，或使机器、设备和仪表不能\n正常工作。与噪声污染一样，振动污染带有强烈的主观性，是一种危\n害人体健康的感觉公害。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":140,"sourceRange":{"startPage":140,"startY":724.92,"endPage":141,"endY":204.57},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":["【重要程度：☆☆☆☆"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":7,"excerpts":[{"page":140,"src":"./assets/environment/env838-a11ae09be4c94ff3-140.webp"},{"page":141,"src":"./assets/environment/env838-a11ae09be4c94ff3-141.webp"}]},{"id":"env838-5be68c46fde4eae3","subject":"环境学导论","chapter":"第7章 物理环境","originalChapter":"第7章 物理环境","originalChapterNumber":7,"section":"第6节 振动","originalSection":"第6节 振动","category":"knowledge","title":"振动污染源","question":"振动污染源","type":"简答题","answer":"振动污染按其来源可分为自然振动和人为振动。自然振动如地震\n、海浪和风等；人为振动如运转的各种动力设备、建筑施工使用的一\n些设备、运行的交通工具、电声系统中的扬声器、人工爆破等。\n自然振动带来的灾害难以避免，只能加强预报减小损失。人为振\n动源主要包括工厂振动源、道路交通振动源、工程振动源、低频空气\n振动源等。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":0,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":141,"sourceRange":{"startPage":141,"startY":204.57,"endPage":141,"endY":460.84},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":["【重要程度:☆☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":7,"excerpts":[{"page":141,"src":"./assets/environment/env838-5be68c46fde4eae3-141.webp"}]},{"id":"env838-4e6919f3afe8f924","subject":"环境学导论","chapter":"第7章 物理环境","originalChapter":"第7章 物理环境","originalChapterNumber":7,"section":"第6节 振动","originalSection":"第6节 振动","category":"knowledge","title":"振动污染的危害","question":"振动污染的危害","type":"简答题","answer":"[1]振动对生理的影响\n振动对人类生理的影响主要体现在损伤人的机体，引起循环系统\n、消化系统、神经系统、呼吸系统、代谢系统、感官的各种急症，损\n伤脑、肺、消化系统、心、肝、肾、关节、脊髓等。\n[2]振动对心理的影响\n一般人们在感受到振动的情况下，心理上会产生烦躁、不愉快的\n感受。\n[3]振动对工作效率的影响\n振动会引起人体心理和生理的不利变化，从而导致工作效率的降\n低。振动会产生视力减退，影响反应能力和语言交谈，妨碍肌肉运动\n和加大复杂工作错误率等不利影响。\n[4]振动对机械设备的影响\n振动使机械设备本身疲劳和磨损，缩短机械设备的使用寿命，甚\n至使机械设备中的构件发生刚度和强度破坏。\n[5]振动建筑物的影响\n从振源发出的振动，以波动形式通过地基传播到周围的建筑物的\n基础、楼板或其相邻结构，可以引起它们的振动，并产生辐射声波，\n引起所谓的结构噪声。由于固体声衰减缓慢，可以传播到很远的地方\n，所以常常导致构筑物破坏，如构筑物基础和墙壁的龟裂、墙皮的剥\n落、地基变形、下沉、门窗翘曲变形等，严重者可使构筑物坍塌。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":0,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":141,"sourceRange":{"startPage":141,"startY":460.84,"endPage":143,"endY":77.94},"sourceKind":"original","originalOrdinal":"3","sourceMetadata":["【重要程度:☆☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":7,"excerpts":[{"page":141,"src":"./assets/environment/env838-4e6919f3afe8f924-141.webp"},{"page":142,"src":"./assets/environment/env838-4e6919f3afe8f924-142.webp"},{"page":143,"src":"./assets/environment/env838-4e6919f3afe8f924-143.webp"}]},{"id":"env838-30c482dd9d39a555","subject":"环境学导论","chapter":"第7章 物理环境","originalChapter":"第7章 物理环境","originalChapterNumber":7,"section":"第7节 课后习题","originalSection":"第7节 课后习题","category":"exercise","title":"什么是噪声?","question":"什么是噪声?","type":"简答题","answer":"整理答案（按教材对应知识点摘录）：\n\n噪声的定义：\n一般认为凡是不需要的，使人厌烦的，并对人类生产和生活有妨\n碍的声音。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["根据所列知识点摘录整理，未逐题人工审定。"],"verified":false,"page":143,"sourceRange":{"startPage":143,"startY":115.72,"endPage":143,"endY":190.11},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":7,"references":[{"id":"env838-86dba28d3c650c13","title":"噪声的定义","source":"环境学导论.pdf","page":132}],"excerpts":[{"page":143,"src":"./assets/environment/env838-30c482dd9d39a555-143.webp"}]},{"id":"env838-88e20c5240903254","subject":"环境学导论","chapter":"第7章 物理环境","originalChapter":"第7章 物理环境","originalChapterNumber":7,"section":"第7节 课后习题","originalSection":"第7节 课后习题","category":"exercise","title":"噪声的危害?试列举1~2个环境噪声的事例。","question":"噪声的危害?试列举1~2个环境噪声的事例。","type":"简答题","answer":"①听觉损害：较高声级或长期暴露可导致听觉疲劳、听力下降，严重暴露可能造成不可逆损害。\n②非听觉影响：干扰睡眠、交流、学习和工作，引起烦恼及应激；长期环境噪声暴露还与心血管健康风险相关。\n③安全与社会影响：妨碍报警和交流，降低工作注意力及居住舒适度。\n例子：城市道路交通噪声干扰沿线居民夜间睡眠；施工噪声影响附近学校教学。\n危害受声级、频谱、持续时间、时段及个体敏感性共同影响。控制应遵循声源、传播途径及接收者三环节。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":143,"sourceRange":{"startPage":143,"startY":190.11,"endPage":143,"endY":269.44},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":7,"excerpts":[{"page":143,"src":"./assets/environment/env838-88e20c5240903254-143.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=131"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-c850ba3d75f7de53","subject":"环境学导论","chapter":"第7章 物理环境","originalChapter":"第7章 物理环境","originalChapterNumber":7,"section":"第7节 课后习题","originalSection":"第7节 课后习题","category":"exercise","title":"什么是热污染?热污染的危害有哪些?","question":"什么是热污染?热污染的危害有哪些?","type":"简答题","answer":"整理答案（按教材对应知识点摘录）：\n\n热污染的定义：\n热污染是指人类生产和生活中排放出的废热造成的环境热化，损\n坏环境质量，进而又影响人类生产、生活的一种增温效应，这种增温\n效应达到损害环境质量的程度，便成为热污染。\n\n热污染对环境的影响：\n首先，热污染使得水体中各类无机氮的含量都增加，原因是水温\n升高使得藻类的繁殖加快和固氮藻的固氮速率增大。热污染会促使水\n体富营养化；\n其二，水温升高使得藻类种群结构发生改变。藻类种群结构的改\n变反过来又直接影响鱼类饵料的质量；\n其三，水体温度升高也会影响浮游动物的生存；\n其四，在强增温区，底栖动物的增加也十分突出；\n其五，由于水体周围气温升高，栖息在该地区的昆虫将提前苏醒\n，而远离该地区的本该苏醒的昆虫却处于休眠状态。昆虫苏醒次序的\n这种更迭，会造成有关生态系统中食物链的中断，破坏生态平衡，使\n提前苏醒的昆虫大批死亡，甚至灭绝。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["根据所列知识点摘录整理，未逐题人工审定。"],"verified":false,"page":143,"sourceRange":{"startPage":143,"startY":269.44,"endPage":143,"endY":347.07},"sourceKind":"original","originalOrdinal":"3","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":7,"references":[{"id":"env838-8f08b1919799d131","title":"热污染的定义","source":"环境学导论.pdf","page":135},{"id":"env838-14e4a124637ce750","title":"热污染对环境的影响","source":"环境学导论.pdf","page":137}],"excerpts":[{"page":143,"src":"./assets/environment/env838-c850ba3d75f7de53-143.webp"}]},{"id":"env838-cc1170bc828b5a65","subject":"环境学导论","chapter":"第7章 物理环境","originalChapter":"第7章 物理环境","originalChapterNumber":7,"section":"第7节 课后习题","originalSection":"第7节 课后习题","category":"exercise","title":"简述电磁辐射对人体的危害。","question":"简述电磁辐射对人体的危害。","type":"简答题","answer":"整理答案（按教材对应知识点摘录）：\n\n电磁辐射对人体健康的危害：\n[1]电磁辐射的致癌作用\n一些微波生物学家的实验表明，电磁辐射会促使人体内的遗传基\n因微粒细胞染色体发生突变和有丝分裂异常，而使某些组织出现病理\n性增生过程，使正常细胞变为癌细胞。\n[2]对视觉系统的影响\n长期低强度电磁辐射的作用，可促进视觉疲劳，眼感到不舒适和\n感到干燥等现象。强度更高的微波，则会傸视力完全消失。\n[3]对生殖系统和遗传的影响\n长期接触超短波发生器，会影响生育能力。\n[4]对血液系统和机体免疫功能的影响\n在电磁辐射的作用下，周围血象可出现白细胞不稳定的情况，主\n要是下降倾向，红细胞的生成受到抑制。电磁辐射会使人体的白细胞\n吞噬细菌的百分率和吞噬的细菌数均下降。\n(5)引起心血管疾病\n受电磁辐射作用的人常发生血流动力学失调，血管通透性和张力\n降低。由于植物神经调节功能受到影响，人们多数出现心动过缓症状\n，少数呈现心动过速。\n(6 )对中枢神经系统的危害\n神经系统对电磁辐射的作用很敏感，受其低强度反复作用后，中\n枢神经机能发生改变，出现神经衰弱症候群。\n(7 )对胎儿的影响","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["根据所列知识点摘录整理，未逐题人工审定。"],"verified":false,"page":143,"sourceRange":{"startPage":143,"startY":347.07,"endPage":143,"endY":423.49},"sourceKind":"original","originalOrdinal":"4","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":7,"references":[{"id":"env838-e49e92cbc412e33b","title":"电磁辐射对人体健康的危害","source":"环境学导论.pdf","page":138}],"excerpts":[{"page":143,"src":"./assets/environment/env838-cc1170bc828b5a65-143.webp"}]},{"id":"env838-d16d05532b9be4da","subject":"环境学导论","chapter":"第7章 物理环境","originalChapter":"第7章 物理环境","originalChapterNumber":7,"section":"第7节 课后习题","originalSection":"第7节 课后习题","category":"exercise","title":"简述光污染的危害。","question":"简述光污染的危害。","type":"简答题","answer":"整理答案（按教材对应知识点摘录）：\n\n光污染的危害：\n[1]对人体健康的影响\n人体受光污染危害首先是眼睛。瞬间的强光照射会使人们出现短\n暂的失明。普通光污染可对人眼的角膜和虹膜造成伤害，抑制视网膜\n感光细胞功能的发挥，引起视疲劳和视力下降。\n[2]对生态的破坏\n很多动物受到过多的人工光线的照射时，会影响它们的生活习性\n和新陈代谢，引发一些怪异的行为。\n[3]对交通系统的影响\n各种交通线路上的照明设备或附近体育场和商业照明设备发出\n的光线都会对车辆的驾驶者产生影响，降低交通的安全性。\n在烈日照射下，驾驶者和行人会遭到玻璃幕墙反射光的影响，视\n觉功能受到影响，增加交通的危险性。\n[4]对天文观测的影响\n各种照明设备发出的光线经过空气和大气中悬浮尘埃的散射，使\n夜空亮度增加，对天体观察造成不利的影响。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["根据所列知识点摘录整理，未逐题人工审定。"],"verified":false,"page":143,"sourceRange":{"startPage":143,"startY":423.49,"endPage":144,"endY":75.86},"sourceKind":"original","originalOrdinal":"5","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":7,"references":[{"id":"env838-89f4e2573807a2a0","title":"光污染的危害","source":"环境学导论.pdf","page":139}],"excerpts":[{"page":143,"src":"./assets/environment/env838-d16d05532b9be4da-143.webp"},{"page":144,"src":"./assets/environment/env838-d16d05532b9be4da-144.webp"}]},{"id":"env838-af9817ab8a159cb3","subject":"环境学导论","chapter":"第7章 物理环境","originalChapter":"第7章 物理环境","originalChapterNumber":7,"section":"第4节","originalSection":"第4节","category":"supplement","title":"光污染的分类","question":"光污染的分类","type":"简答题","answer":"根据不同的分类原则，光污染可以分为不同的类型。国际上一般将光污染分\n为三类，即白亮污染、人工白昼和彩光污染，其中彩光污染又分为激光污染、红\n外线污染、紫外线污染。\n白亮污染指建筑物外部用大块镜面或钢化玻璃、大理石装饰造成的，超出肉\n眼所能承受的亮度，会强烈刺激眼球的白花花的光束。研究表明，长期在白亮污\n染下工作和生活的人会产生心焦气躁、失眠多梦、情绪易怒、浑身乏力等类似神\n经衰弱的症状。\n人工白昼污染指夜幕降临后一些仍营业的场所以商业利益为目的进行的过\n度照明。由于夜晚的强光反射将夜空照得如同白昼，给入夜的人们造成影响，还\n会伤害鸟类和昆虫，如强光可能影响昆虫在夜间的正常繁殖过程。\n彩光污染具体是指舞厅、夜总会、夜间游乐场所的黑光灯、旋转灯、荧光灯\n和闪烁的彩色光源发出的彩光所形成的光污染，其紫外线强度远远超出太阳光中\n的紫外线。","source":"环导变动137718728584015123.1eae00877280d3e.pdf","sourceUrl":"https://drive.google.com/file/d/11CjvWmrS4poAVMmBBWnsJPRCmD1-JkRJ/view","version":"new","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":13,"sourceRange":{"startPage":13,"startY":243.01,"endPage":13,"endY":621.09},"sourceKind":"changes","originalOrdinal":"2","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":7,"excerpts":[{"page":13,"src":"./assets/environment/env838-af9817ab8a159cb3-13.webp"}]},{"id":"env838-26ea4cb9f9480e84","subject":"环境学导论","chapter":"第7章 物理环境","originalChapter":"第7章 物理环境","originalChapterNumber":7,"section":"第4节","originalSection":"第4节","category":"supplement","title":"光污染的防治","question":"光污染的防治","type":"简答题","answer":"1、加强夜景照明生态设计。2、加强对城市玻璃幕墙的建设管理。3、加强\n对建筑物装修材料的管理。4、加强城市规划和管理。5、采取必要的个人防护。","source":"环导变动137718728584015123.1eae00877280d3e.pdf","sourceUrl":"https://drive.google.com/file/d/11CjvWmrS4poAVMmBBWnsJPRCmD1-JkRJ/view","version":"new","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":13,"sourceRange":{"startPage":13,"startY":621.09,"endPage":13,"endY":703.05},"sourceKind":"changes","originalOrdinal":"4","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":7,"excerpts":[{"page":13,"src":"./assets/environment/env838-26ea4cb9f9480e84-13.webp"}]},{"id":"env838-51ddbc523aaeb11f","subject":"环境学导论","chapter":"第7章 物理环境","originalChapter":"第7章 物理环境","originalChapterNumber":7,"section":"第5节","originalSection":"第5节","category":"supplement","title":"放射性污染的特性","question":"放射性污染的特性","type":"简答题","answer":"① 长期危害性。放射性废物中的放射性活度只能随着时间推移而衰减。\n② 难处理性。放射性废物中的放射性物质不但会对人体产生内外照射的危\n害，同时放射性的热效应会使废物温度升高。因此，处理放射性废物必须采取复\n杂的屏蔽和封闭措施，并应采取远距离操作及通风冷却措施。\n③ 处理技术复杂性。废物中放射性核素含量非常小，同时也含有多种放射\n性污染物，一般都处在高度稀释状态，但其净化要求极高，因而要采取极复杂的\n处理手段进行多次处理才能达到要求。\n④ 对人类作用有累积性。经过长期深入研究，已经探明致电离辐射对人（生\n物）危害的效果（剂量）具有明显的累积性。","source":"环导变动137718728584015123.1eae00877280d3e.pdf","sourceUrl":"https://drive.google.com/file/d/11CjvWmrS4poAVMmBBWnsJPRCmD1-JkRJ/view","version":"new","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":13,"sourceRange":{"startPage":13,"startY":733.04,"endPage":14,"endY":339.04},"sourceKind":"changes","originalOrdinal":"2","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":7,"excerpts":[{"page":13,"src":"./assets/environment/env838-51ddbc523aaeb11f-13.webp"},{"page":14,"src":"./assets/environment/env838-51ddbc523aaeb11f-14.webp"}]},{"id":"env838-e333eef30c6db38c","subject":"环境学导论","chapter":"第7章 物理环境","originalChapter":"第7章 物理环境","originalChapterNumber":7,"section":"第5节","originalSection":"第5节","category":"supplement","title":"放射性污染的控制","question":"放射性污染的控制","type":"简答题","answer":"（1）放射性辐射的防护\n辐射防护的目的在于完全防止非随机性效应，并限制随机性效应的发生率。\n放射性辐射的防护按照照射类型可分为外照射的防护和内照射的防护。\n外照射的防护。外照射的防护方法主要包括时间防护、距离防护和屏蔽防护。\n① 时间防护。在具有特定辐射剂量的场所，工作人员所受到的辐射累积剂\n量与人在该场所停留的总时间成正比。因此，工作人员应尽量做到操作快速、准\n确或采取轮流操作方式，熟练掌握操作技能，缩短受照时间，这是实现防护的有\n效办法。\n② 距离防护。距离防护是指通过远离放射源，以达到防护目的的方法。点\n状放射性污染源的辐射剂量与污染源到受照者之间的距离的平方成反比，距离辐\n射源越近接受的辐射剂量越大，所以工作人员应尽可能远离放射源进行操作。\n③ 屏蔽防护。屏蔽防护是指在放射源和人体之间放置能够吸收或减弱射线\n强度的材料，以达到防护目的的方法。\n内照射的防护。主要通过防止呼吸道吸收、防止胃肠道吸收和防止由伤口吸\n收等措施进行防护。\n防护方法有：制定各种必要的规章制度；工作场所通风换气；在放射性工作\n场所严禁吸烟、吃东西和饮水；在操作放射性物质时要戴上个人防护用具；加强\n对放射性物质的管理；严密监视放射性物质的污染情况，发现情况尽早采取措施，\n防止污染范围扩大；布局设计要合理，防止交叉污染等。\n（2）控制污染源\n放射性污染的防治首先必须控制污染源，核企业厂址应选择在人口密度低、\n抗震强度高的地区，保证事故一旦发生居民所受的伤害最小，更重要的是要将核\n废料进行严格处理。\n① 放射性废液处理。处理放射性废液的方法有化学处理、离子交换、吸附\n法、膜分离法、生物处理、蒸发浓缩等。根据放射性活度的高低、废水量的大小\n及水质的不同，可选择上述一种方法或几种方法联合使用，达到理想的处理效果。\n② 放射性废气处理。放射性污染物在废气中存在的形态包括放射性气体、\n放射性气溶胶和放射性粉尘。对于放射性气体，可用吸附或者稀释的方法处理；\n对于放射性气溶胶，通常可用除尘技术进行净化；对于放射性粉尘，通常用高效\n过滤器过滤、吸附等方法处理，使空气净化后经高烟囱排放。\n③ 放射性固体废物的处理和处置。放射性固体废物种类繁多，分为湿固体\n和干固体两大类。为了减容和适于运输、贮存和最终处置，要对含放射性固体废\n物进行焚烧、压缩、固化或固定等处理。","source":"环导变动137718728584015123.1eae00877280d3e.pdf","sourceUrl":"https://drive.google.com/file/d/11CjvWmrS4poAVMmBBWnsJPRCmD1-JkRJ/view","version":"new","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":14,"sourceRange":{"startPage":14,"startY":339.04,"endPage":15,"endY":553.02},"sourceKind":"changes","originalOrdinal":"3","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":7,"excerpts":[{"page":14,"src":"./assets/environment/env838-e333eef30c6db38c-14.webp"},{"page":15,"src":"./assets/environment/env838-e333eef30c6db38c-15.webp"}]},{"id":"env838-f6b3fbdda298331e","subject":"环境学导论","chapter":"第7章 物理环境","originalChapter":"第7章 物理环境","originalChapterNumber":7,"section":"第6节","originalSection":"第6节","category":"supplement","title":"震动污染的控制","question":"震动污染的控制","type":"简答题","answer":"振动传播与声传播一样，由振动源、传递介质和接收者三个要素组成。\n（1）振源控制\n① 采用振动小的加工工艺。② 减少振源的扰动。\n（2）传递过程中振动控制\n① 加大振动源和受振对象之间的距离。② 设置隔振沟。③ 采用隔振器材。\n（3）对接收者采取控制\n① 采用黏弹性高阻尼材料。② 保证精密仪器、设备的工作台刚度。","source":"环导变动137718728584015123.1eae00877280d3e.pdf","sourceUrl":"https://drive.google.com/file/d/11CjvWmrS4poAVMmBBWnsJPRCmD1-JkRJ/view","version":"new","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":15,"sourceRange":{"startPage":15,"startY":583.02,"endPage":16,"endY":259.0},"sourceKind":"changes","originalOrdinal":"4","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":7,"excerpts":[{"page":15,"src":"./assets/environment/env838-f6b3fbdda298331e-15.webp"},{"page":16,"src":"./assets/environment/env838-f6b3fbdda298331e-16.webp"}]},{"id":"env838-647b85cafa7f7823","subject":"环境学导论","chapter":"第8章 人口与环境","originalChapter":"第8章 人口与环境","originalChapterNumber":8,"section":"第1节 世界人口的增长","originalSection":"第1节 世界人口的增长","category":"knowledge","title":"世界人口增长的特点","question":"世界人口增长的特点","type":"简答题","answer":"①人口增长两极分化：发展中国家增长较快，发达国家增长较慢\n②城市人口急剧增长；\n③人口老龄化速度加快；","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":1,"pastExamYears":[],"needsReview":true,"reviewReasons":["变动资料说明人口章已重写，但未给出这些知识点的完整新版正文；此处保留原资料，需核对新版教材。"],"verified":false,"page":145,"sourceRange":{"startPage":145,"startY":109.03,"endPage":145,"endY":275.53},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":["【重要程度: ★☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":8,"excerpts":[{"page":145,"src":"./assets/environment/env838-647b85cafa7f7823-145.webp"}]},{"id":"env838-eebc9693252d0751","subject":"环境学导论","chapter":"第8章 人口与环境","originalChapter":"第8章 人口与环境","originalChapterNumber":8,"section":"第2节 人口增长对自然环境的压力","originalSection":"第2节 人口增长对自然环境的压力","category":"knowledge","title":"人口增长对环境产生的影响","question":"人口增长对环境产生的影响","type":"简答题","answer":"①人口增长对土地资源的压力\n庞大的人口对粮食等农产品需求产生压力，迫使人们高强度的使\n用耕地，加之不合理的开发土地，导致大量耕地被毁，人均土地逐年\n下降。此外，为使食物供应跟上人口的增长，需要采取各种措施，如\n使用大量化肥与农药以提高单位面积产量，或开垦荒地以扩大耕地面\n积等，这些措施不仅会导致土壤板结，还会使土地沙漠化、盐碱化，\n更加重对土地资源的压力；\n②人口增长对森林资源的压力\n人口过分增长造成的毁林造田、毁林盖房，使越来越多的森林资\n源遭到破坏；\n③人口增长对能源的影响\n人口的增长使能源供应紧张并缩短了化石燃料的耗竭时间。而生\n产、生活所消耗的燃煤、石油等释放出大量二氧化碳，引起温室效应\n导致全球变暖；\n④人口增长对水资源的影响\n随着经济的发展和人民生活水平的提高，对水的需求量也在逐渐\n增加。人口的增长又使得人均用水量、生活用水量大大增加，导致了\n大范围的缺水现象。而为了解决人口增长对耕地的需求而产生的“围\n湖造田”现象也严重破坏了地表水资源；\n⑤人口增长对矿产资源的影响\n矿产资源的消耗是以人为主体作为消费对象的。由于人口的过度\n增长，对各种矿物的需求正在加剧。这种对矿产资源沉重的需求压力\n，不仅会造成资源供给长期紧张的局面，也会诱发出严重的生态环境\n问题；\n⑥人口对气候的影响\n人口的增长，会因呼吸、燃烧、工业发展等使排入大气中的二氧\n化碳、氮氧化物、硫氧化物等增加，可能引起酸雨和光化学烟雾事故\n，从而逐渐影响全球气候。总之，人口的增加必然要开垦土地、兴建\n住宅、采伐森林、开辟水源，结果改变了自然生态系统的结构和功能\n，使其偏离有利的平衡状态。如果偏离程度超过了生态系统自身的调\n节能力，则生态平衡受到破坏，这时自然界就要对人类进行报复。因\n此，考虑人口增长和人口密度分布问题，必须尊重自然生态规律，使\n其不断保持最优平衡。\n图 8-1 人口增长对环境产生的影响记忆脑图\n学长提示 : 本书中大量出现类似于这种关于影响的综合性的说法 ， 我个人习惯于画一\n些场景图 ， 把有关的内容都画到图上 ， 在后续背诵的时候 ， 只需要想象这幅图 ， 然后\n看图说话 ， 这个方法我很推荐 ， 大家也可以尝试着画一画 。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":2,"pastExamYears":[2011],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。","变动资料说明人口章已重写，但未给出这些知识点的完整新版正文；此处保留原资料，需核对新版教材。","含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":145,"sourceRange":{"startPage":145,"startY":317.07,"endPage":147,"endY":417.52},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":["2011( 简, 【重要程度: ★★☆☆☆)"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":8,"excerpts":[{"page":145,"src":"./assets/environment/env838-eebc9693252d0751-145.webp"},{"page":146,"src":"./assets/environment/env838-eebc9693252d0751-146.webp"},{"page":147,"src":"./assets/environment/env838-eebc9693252d0751-147.webp"}]},{"id":"env838-23c917f14189f32a","subject":"环境学导论","chapter":"第8章 人口与环境","originalChapter":"第8章 人口与环境","originalChapterNumber":8,"section":"第4节 人口增长与环境承载力","originalSection":"第4节 人口增长与环境承载力","category":"knowledge","title":"环境承载力的定义","question":"环境承载力的定义","type":"简答题","answer":"环境承载力是指在一定时期内，在维持相对稳定的前提下，环境\n资源所能容纳的人口规模和经济规模的大小。\n学长提示 : 本书中大量出现类似于这种关于了 2Z 承载力 、xX 容量 、xY 本底值的说法 ， 本\n质上和 Xx 污染的套路是一臻的， 承载力 、xXX 容量解释模板 ; 在一定时期内 ， 在不受\n人类干预的情况下 〈 即平衡体系下 ) ，xx 所能容纳的人口 /污染物等其他目标物的最大\n重 ;_xx 本底值解释模板 :在一定时期内 ， 在不受人类干预的情况下 〈 即平衡体系下 )\n，XX 中的各物质 、 元素的平衡深度 。 如土壤本底值 ， 大气本底值等 。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。","变动资料说明人口章已重写，但未给出这些知识点的完整新版正文；此处保留原资料，需核对新版教材。","含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":147,"sourceRange":{"startPage":147,"startY":499.45,"endPage":148,"endY":69.56},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":["【重要程度："],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":8,"excerpts":[{"page":147,"src":"./assets/environment/env838-23c917f14189f32a-147.webp"},{"page":148,"src":"./assets/environment/env838-23c917f14189f32a-148.webp"}]},{"id":"env838-9a638415adca84ce","subject":"环境学导论","chapter":"第8章 人口与环境","originalChapter":"第8章 人口与环境","originalChapterNumber":8,"section":"第4节 人口增长与环境承载力","originalSection":"第4节 人口增长与环境承载力","category":"knowledge","title":"经济适度人口","question":"经济适度人口","type":"简答题","answer":"环境人口容量是指一个国家或地区的环境人口容量，是在可预见\n到的时期内，利用本地资源及其他资源和智力、技术等条件，在保证\n符合社会文化准则的物质生活水平条件下，该国家或地区所能持续供\n养的人口数量。但人口容量并不是生物学上的最高人口数，而是指一\n定生活水平下能供养的最高人口数，它随所定生活水平的标准而异。\n如果把生活水平定在很低的标准上，甚至仅能维持生存水平，人口容\n量就接近生物学上的最高人口数；如果生活水平定在较高目标上，人\n口容量在一定意义上说就是经济适度人口。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":1,"pastExamYears":[2012],"needsReview":true,"reviewReasons":["变动资料说明人口章已重写，但未给出这些知识点的完整新版正文；此处保留原资料，需核对新版教材。"],"verified":false,"page":148,"sourceRange":{"startPage":148,"startY":69.56,"endPage":148,"endY":369.53},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":["2012 (名, 【重要程度: ★☆☆☆☆"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":8,"excerpts":[{"page":148,"src":"./assets/environment/env838-9a638415adca84ce-148.webp"}]},{"id":"env838-6b405c1eb954555b","subject":"环境学导论","chapter":"第8章 人口与环境","originalChapter":"第8章 人口与环境","originalChapterNumber":8,"section":"第5节 我国的人口与控制","originalSection":"第5节 我国的人口与控制","category":"knowledge","title":"我国人口的现状和特点","question":"我国人口的现状和特点","type":"简答题","answer":"①人口基数大；\n②人口增长速度减缓；\n③人口老龄化；\n④人口出生性别比提高；\n⑤人口质量堪忧；\n⑥流动人口增加。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":2,"pastExamYears":[],"needsReview":true,"reviewReasons":["变动资料说明人口章已重写，但未给出这些知识点的完整新版正文；此处保留原资料，需核对新版教材。"],"verified":false,"page":148,"sourceRange":{"startPage":148,"startY":410.1,"endPage":148,"endY":658.78},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":["【重要程度: ★★☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":8,"excerpts":[{"page":148,"src":"./assets/environment/env838-6b405c1eb954555b-148.webp"}]},{"id":"env838-223760e4b48e8fb6","subject":"环境学导论","chapter":"第8章 人口与环境","originalChapter":"第8章 人口与环境","originalChapterNumber":8,"section":"第5节 我国的人口与控制","originalSection":"第5节 我国的人口与控制","category":"knowledge","title":"人口控制的意义","question":"人口控制的意义","type":"简答题","answer":"我国人口多，人均资源少，人均国民生产总值低。因此，控制人\n口对于加速我国经济发展和保护环境都具有重大意义：\n①可以减轻国家负担，增加积累；\n②有利于提高科学文化水平，改善人民生活和就业问题；\n③有利于保护现有自然资源，防止生态环境进一步恶化。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":2,"pastExamYears":[],"needsReview":true,"reviewReasons":["变动资料说明人口章已重写，但未给出这些知识点的完整新版正文；此处保留原资料，需核对新版教材。"],"verified":false,"page":148,"sourceRange":{"startPage":148,"startY":658.78,"endPage":149,"endY":172.82},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":["【重要程度：★★☆☆☆"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":8,"excerpts":[{"page":148,"src":"./assets/environment/env838-223760e4b48e8fb6-148.webp"},{"page":149,"src":"./assets/environment/env838-223760e4b48e8fb6-149.webp"}]},{"id":"env838-677a4b9452784bd7","subject":"环境学导论","chapter":"第8章 人口与环境","originalChapter":"第8章 人口与环境","originalChapterNumber":8,"section":"第5节 我国的人口与控制","originalSection":"第5节 我国的人口与控制","category":"knowledge","title":"解决人口问题的主要对策","question":"解决人口问题的主要对策","type":"简答题","answer":"①广泛开展教育，使计划生育政策深入人心，成为人们自觉的行\n动；\n②逐级落实人口计划指标，奖惩分明；\n③积极发展医疗、保险、养老等一系列社会福利事业；\n④实行优生优育，提高人口素质。\n学长提示类似于这种措施类的 ， 希望大家站在一个更高的角度去解决问题 ， 假设自\n已是领导人 ， 换做是你 ， 你会制定哪些措施来解决这个问题 ， 一般可以分为三个层面\n来讨论 ， 一是国家层面 ， 需要推行哪些政策 ; 二是社会层面 ， 需要落实哪些政策 ; 三\n个个人层面 ， 公民应该加强何种理念 。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。","变动资料说明人口章已重写，但未给出这些知识点的完整新版正文；此处保留原资料，需核对新版教材。","含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":149,"sourceRange":{"startPage":149,"startY":172.82,"endPage":150,"endY":79.84},"sourceKind":"original","originalOrdinal":"3","sourceMetadata":["【重要程度："],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":8,"excerpts":[{"page":149,"src":"./assets/environment/env838-677a4b9452784bd7-149.webp"},{"page":150,"src":"./assets/environment/env838-677a4b9452784bd7-150.webp"}]},{"id":"env838-9e02b31a884cb33d","subject":"环境学导论","chapter":"第8章 人口与环境","originalChapter":"第8章 人口与环境","originalChapterNumber":8,"section":"第6节 课后习题","originalSection":"第6节 课后习题","category":"exercise","title":"世界人口增长有什么特点?","question":"世界人口增长有什么特点?","type":"简答题","answer":"整理答案（按教材对应知识点摘录）：\n\n世界人口增长的特点：\n①人口增长两极分化：发展中国家增长较快，发达国家增长较慢\n②城市人口急剧增长；\n③人口老龄化速度加快；","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["根据所列知识点摘录整理，未逐题人工审定。"],"verified":false,"page":150,"sourceRange":{"startPage":150,"startY":118.2,"endPage":150,"endY":192.96},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":8,"references":[{"id":"env838-647b85cafa7f7823","title":"世界人口增长的特点","source":"环境学导论.pdf","page":145}],"excerpts":[{"page":150,"src":"./assets/environment/env838-9e02b31a884cb33d-150.webp"}]},{"id":"env838-15ab54aa8b737d17","subject":"环境学导论","chapter":"第8章 人口与环境","originalChapter":"第8章 人口与环境","originalChapterNumber":8,"section":"第6节 课后习题","originalSection":"第6节 课后习题","category":"exercise","title":"人口增长对自然资源的影响有哪些?","question":"人口增长对自然资源的影响有哪些?","type":"简答题","answer":"整理答案（按教材对应知识点摘录）：\n\n人口增长对环境产生的影响：\n①人口增长对土地资源的压力\n庞大的人口对粮食等农产品需求产生压力，迫使人们高强度的使\n用耕地，加之不合理的开发土地，导致大量耕地被毁，人均土地逐年\n下降。此外，为使食物供应跟上人口的增长，需要采取各种措施，如\n使用大量化肥与农药以提高单位面积产量，或开垦荒地以扩大耕地面\n积等，这些措施不仅会导致土壤板结，还会使土地沙漠化、盐碱化，\n更加重对土地资源的压力；\n②人口增长对森林资源的压力\n人口过分增长造成的毁林造田、毁林盖房，使越来越多的森林资\n源遭到破坏；\n③人口增长对能源的影响\n人口的增长使能源供应紧张并缩短了化石燃料的耗竭时间。而生\n产、生活所消耗的燃煤、石油等释放出大量二氧化碳，引起温室效应\n导致全球变暖；\n④人口增长对水资源的影响\n随着经济的发展和人民生活水平的提高，对水的需求量也在逐渐\n增加。人口的增长又使得人均用水量、生活用水量大大增加，导致了\n大范围的缺水现象。而为了解决人口增长对耕地的需求而产生的“围\n湖造田”现象也严重破坏了地表水资源；\n⑤人口增长对矿产资源的影响\n矿产资源的消耗是以人为主体作为消费对象的。由于人口的过度\n增长，对各种矿物的需求正在加剧。这种对矿产资源沉重的需求压力\n，不仅会造成资源供给长期紧张的局面，也会诱发出严重的生态环境\n问题；\n⑥人口对气候的影响\n人口的增长，会因呼吸、燃烧、工业发展等使排入大气中的二氧\n化碳、氮氧化物、硫氧化物等增加，可能引起酸雨和光化学烟雾事故\n，从而逐渐影响全球气候。总之，人口的增加必然要开垦土地、兴建\n住宅、采伐森林、开辟水源，结果改变了自然生态系统的结构和功能\n，使其偏离有利的平衡状态。如果偏离程度超过了生态系统自身的调\n节能力，则生态平衡受到破坏，这时自然界就要对人类进行报复。因\n此，考虑人口增长和人口密度分布问题，必须尊重自然生态规律，使\n其不断保持最优平衡。\n图 8-1 人口增长对环境产生的影响记忆脑图\n学长提示 : 本书中大量出现类似于这种关于影响的综合性的说法 ， 我个人习惯于画一\n些场景图 ， 把有关的内容都画到图上 ， 在后续背诵的时候 ， 只需要想象这幅图 ， 然后\n看图说话 ， 这个方法我很推荐 ， 大家也可以尝试着画一画 。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["根据所列知识点摘录整理，未逐题人工审定。"],"verified":false,"page":150,"sourceRange":{"startPage":150,"startY":192.96,"endPage":150,"endY":267.3},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":8,"references":[{"id":"env838-eebc9693252d0751","title":"人口增长对环境产生的影响","source":"环境学导论.pdf","page":145}],"excerpts":[{"page":150,"src":"./assets/environment/env838-15ab54aa8b737d17-150.webp"}]},{"id":"env838-97a45e35b9cae74e","subject":"环境学导论","chapter":"第8章 人口与环境","originalChapter":"第8章 人口与环境","originalChapterNumber":8,"section":"第6节 课后习题","originalSection":"第6节 课后习题","category":"exercise","title":"目前我国的人口特点有哪些?","question":"目前我国的人口特点有哪些?","type":"简答题","answer":"整理答案（按教材对应知识点摘录）：\n\n我国人口的现状和特点：\n①人口基数大；\n②人口增长速度减缓；\n③人口老龄化；\n④人口出生性别比提高；\n⑤人口质量堪忧；\n⑥流动人口增加。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["根据所列知识点摘录整理，未逐题人工审定。"],"verified":false,"page":150,"sourceRange":{"startPage":150,"startY":267.3,"endPage":150,"endY":341.47},"sourceKind":"original","originalOrdinal":"3","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":8,"references":[{"id":"env838-6b405c1eb954555b","title":"我国人口的现状和特点","source":"环境学导论.pdf","page":148}],"excerpts":[{"page":150,"src":"./assets/environment/env838-97a45e35b9cae74e-150.webp"}]},{"id":"env838-e337b53ad33349d4","subject":"环境学导论","chapter":"第8章 人口与环境","originalChapter":"第8章 人口与环境","originalChapterNumber":8,"section":"第6节 课后习题","originalSection":"第6节 课后习题","category":"exercise","title":"简述我国人口控制的对策。","question":"简述我国人口控制的对策。","type":"简答题","answer":"整理答案（按教材对应知识点摘录）：\n\n解决人口问题的主要对策：\n①广泛开展教育，使计划生育政策深入人心，成为人们自觉的行\n动；\n②逐级落实人口计划指标，奖惩分明；\n③积极发展医疗、保险、养老等一系列社会福利事业；\n④实行优生优育，提高人口素质。\n学长提示类似于这种措施类的 ， 希望大家站在一个更高的角度去解决问题 ， 假设自\n已是领导人 ， 换做是你 ， 你会制定哪些措施来解决这个问题 ， 一般可以分为三个层面\n来讨论 ， 一是国家层面 ， 需要推行哪些政策 ; 二是社会层面 ， 需要落实哪些政策 ; 三\n个个人层面 ， 公民应该加强何种理念 。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["根据所列知识点摘录整理，未逐题人工审定。"],"verified":false,"page":150,"sourceRange":{"startPage":150,"startY":341.47,"endPage":150,"endY":415.08},"sourceKind":"original","originalOrdinal":"4","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":8,"references":[{"id":"env838-677a4b9452784bd7","title":"解决人口问题的主要对策","source":"环境学导论.pdf","page":149}],"excerpts":[{"page":150,"src":"./assets/environment/env838-e337b53ad33349d4-150.webp"}]},{"id":"env838-69bdaf5657f45978","subject":"环境学导论","chapter":"第8章 人口与环境","originalChapter":"第8章 人口与环境","originalChapterNumber":8,"section":"第6节 课后习题","originalSection":"第6节 课后习题","category":"exercise","title":"如何理解国家对于计划生育政策的调整?","question":"如何理解国家对于计划生育政策的调整?","type":"简答题","answer":"政策调整需联系人口发展阶段：过去强调控制人口过快增长，随后逐步调整生育政策；面对低生育、老龄化等变化，2021年实施三孩生育政策及配套支持措施。\n理解：①目标由人口数量约束拓展为人口长期均衡发展；②降低生育、养育和教育负担，完善托育、妇幼健康及相关公共服务；③保障家庭依法自主安排生育，兼顾性别平等和就业支持；④积极应对老龄化，提高人口素质与劳动生产率。\n不能把旧教材中某阶段的“严格控制增长”表述机械用于当前所有政策；应以政策时点及人口结构变化解释调整。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":150,"sourceRange":{"startPage":150,"startY":415.08,"endPage":151,"endY":48.51},"sourceKind":"original","originalOrdinal":"5","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":8,"excerpts":[{"page":150,"src":"./assets/environment/env838-69bdaf5657f45978-150.webp"},{"page":151,"src":"./assets/environment/env838-69bdaf5657f45978-151.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=144"},{"title":"优化生育政策促进人口长期均衡发展的决定","url":"https://www.mee.gov.cn/zcwj/zyygwj/202107/t20210720_849299.shtml","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-6086f8dd757df1b2","subject":"环境学导论","chapter":"第9章 食品生产与环境","originalChapter":"第9章 粮食生产与环境","originalChapterNumber":9,"section":"","originalSection":"","category":"knowledge","title":"粮食安全的概念","question":"粮食安全的概念","type":"简答题","answer":"所有人在任何时候都能够在物质和经济上获得足够、安全和富有\n营养的粮食，来满足其积极和健康生活的膳食需求及食物喜好。\n应从三个方面实现粮食安全：有充足高质量的粮食供应；家庭和\n个人可以得到这些粮食；人们可以借助洁净水、充足的卫生设施和医\n疗保健来利用其营养。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2020],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":152,"sourceRange":{"startPage":152,"startY":49.29,"endPage":152,"endY":274.17},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":["2020(名,【重要程度:"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":9,"excerpts":[{"page":152,"src":"./assets/environment/env838-6086f8dd757df1b2-152.webp"}]},{"id":"env838-2828088aaf2a51dc","subject":"环境学导论","chapter":"第9章 食品生产与环境","originalChapter":"第9章 粮食生产与环境","originalChapterNumber":9,"section":"","originalSection":"","category":"knowledge","title":"世界粮食安全问题","question":"世界粮食安全问题","type":"简答题","answer":"①发展中国家膳食结构差；\n②大量发展中国家需要国际紧急粮食援助；\n③世界粮食可供量很少。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":0,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":152,"sourceRange":{"startPage":152,"startY":274.17,"endPage":152,"endY":448.56},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":["【重要程度:☆☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":9,"excerpts":[{"page":152,"src":"./assets/environment/env838-2828088aaf2a51dc-152.webp"}]},{"id":"env838-b5bde359b99b2b83","subject":"环境学导论","chapter":"第9章 食品生产与环境","originalChapter":"第9章 粮食生产与环境","originalChapterNumber":9,"section":"","originalSection":"","category":"knowledge","title":"提高粮食产量带来的环境问题","question":"提高粮食产量带来的环境问题","type":"简答题","answer":"[1]开垦荒地对生态平衡的破坏\n通常，粮食需求的增长主要靠耕地的扩大来满足的。而耕地的增\n加是以牧地、湿地及其他生态系统特别是森林的减少为代价的，因而\n会破坏生态平衡而形成水、旱灾害，并对粮食和其他农业生产带来极\n为不利的后果。过度垦荒，盲目增加耕地还往往带来严重的生态问题\n如引发沙尘暴等。\n[2]使用化肥对环境的影响\n化肥的主要环境问题是通过径流、农田排水以及渗滤、淋洗对水\n体的污染，其次是对土壤、大气和人群健康的影响。\n①污染地表水和地下水。氨肥的流失导致水中硝酸盐含量增加；\n②导致水体富营养化。化肥中含有大量氮、磷、钾等营养物质，\n化肥随农田排水和雨水进入湖泊，是导致富营养化的原因之一；\n③大气污染。化肥对大气的污染主要是氮肥挥发氨气与释放氮氧\n化物，硝化和反硝化释放二氧化氮不仅造成温室效应，而且在光化学\n反应中消耗臭氧，破坏臭氧层；\n④土壤污染。造成土壤污染的化肥主要是磷肥，磷肥中除含有营\n养元素磷、钾、钙、锰、锌和硼，同时也含有有害物质砷、铬、镉和\n氟，其中尤以金属镉的含量高，毒性大。少量的镉随施肥进入土壤，\n分解和淋失性小，容易在土壤中积累而危及生态环境和人类；\n⑤危害人群健康。氮肥超量投入，会造成硝酸盐在农产品内的积\n累，危害人体健康。要控制化肥主要是氮肥对环境的不良影响，既要\n控制其施用量，又要严格执行使用规程，尤其是要提高磷肥和钾肥的\n使用量，合理控制氮、磷、钾的比例，其次可采用微生物肥。\n[3]农药产生的主要环境问题\n这些农药一旦进入环境，其毒性高残留性便会发生效应，造成严\n重的大气、水体以及土壤的污染。\n①农药对大气的污染：农药颗粒和蒸汽散发到空中，随风漂移，\n污染全球；\n②农药对水体的污染：残留的农药会随着雨水冲刷进入水体，对\n水体造成普遍性的污染；\n③农药对土壤的污染；农药在使用过程中，约有一半药剂下落到\n土壤中。由于农药本身不易被阳光和微生物分解，对酸和热稳定，不\n易挥发且难溶于水，故残留时间很长，尤以对粘土和富有机质的土壤\n残留性更大。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2009,2022],"needsReview":false,"reviewReasons":[],"verified":false,"page":152,"sourceRange":{"startPage":152,"startY":448.56,"endPage":154,"endY":38.6},"sourceKind":"original","originalOrdinal":"3","sourceMetadata":["2009、2022(简--农药对环境的影响, 【重要程度:"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":9,"excerpts":[{"page":152,"src":"./assets/environment/env838-b5bde359b99b2b83-152.webp"},{"page":153,"src":"./assets/environment/env838-b5bde359b99b2b83-153.webp"},{"page":154,"src":"./assets/environment/env838-b5bde359b99b2b83-154.webp"}]},{"id":"env838-e86587abb801d658","subject":"环境学导论","chapter":"第9章 食品生产与环境","originalChapter":"第9章 粮食生产与环境","originalChapterNumber":9,"section":"","originalSection":"","category":"knowledge","title":"农药和杀虫剂","question":"农药和杀虫剂","type":"简答题","answer":"农药有许多种类，包括杀虫剂、杀螨剂、杀菌剂、杀线虫剂、除\n草剂等，造成环境污染并对人体有害的农药主要是一些有机氯农药和\n含铅、砷、汞等重金属制剂以及某些除草剂。\n合成的有机杀虫剂分为三类：氯化碳氢化合物(有机氯农药)、\n有机磷酸盐(有机磷农药)和氨基甲酯。DDT是一种合成的有机氯杀\n虫剂。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"original-only","importance":null,"pastExamYears":[2003,2004,2010,2022],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":154,"sourceRange":{"startPage":154,"startY":38.6,"endPage":154,"endY":311.51},"sourceKind":"original","originalOrdinal":"4","sourceMetadata":["2003、2022(简--农药的种类, 2004、2010(选---杀虫剂的种类,【重要程度:"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":9,"versionReason":"变动PDF第17页：原知识点4—10改为旧版补充。","excerpts":[{"page":154,"src":"./assets/environment/env838-e86587abb801d658-154.webp"}]},{"id":"env838-0d54a47b69944b29","subject":"环境学导论","chapter":"第9章 食品生产与环境","originalChapter":"第9章 粮食生产与环境","originalChapterNumber":9,"section":"","originalSection":"","category":"knowledge","title":"有机杀虫剂的特性","question":"有机杀虫剂的特性","type":"简答题","answer":"①对害虫的毒性\n②广泛的毒性\n③化学稳定性和不易降解性；\n④物理分散性；\n⑤脂溶性。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"original-only","importance":1,"pastExamYears":[2009],"needsReview":false,"reviewReasons":[],"verified":false,"page":154,"sourceRange":{"startPage":154,"startY":311.51,"endPage":154,"endY":547.36},"sourceKind":"original","originalOrdinal":"5","sourceMetadata":["2009( 简, 【重要程度:★☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":9,"versionReason":"变动PDF第17页：原知识点4—10改为旧版补充。","excerpts":[{"page":154,"src":"./assets/environment/env838-0d54a47b69944b29-154.webp"}]},{"id":"env838-ff8f811403f43ad3","subject":"环境学导论","chapter":"第9章 食品生产与环境","originalChapter":"第9章 粮食生产与环境","originalChapterNumber":9,"section":"","originalSection":"","category":"knowledge","title":"农药对人群健康的影响","question":"农药对人群健康的影响","type":"简答题","answer":"农药主要通过食物链进入人体，在脂肪和肝脏中积累，从而影响\n正常的生理活动。它对人体的危害目前认为有以下几个方面：\n①对神经的影响。有机氯农药具有神经毒性。\n②致癌作用。\n③对肝脏的影响。有机氯农药能诱发肝脏酶的改变，从而改变体\n内的生理过程，使肝脏肿大以致坏死。此外还能侵犯肾脏，并引起病\n变。\n④诱发突变、遗传导致畸胎。DDT和除草剂是一种诱变物质，即\n具有遗传毒性，能导致畸胎，影响后代健康和缩短寿命。\n⑤慢性中毒。有机氯农药慢性中毒时，引起倦乏、头痛、食欲不\n振等。\n农药污染食品的途径有二：一是农药残留在作物上，使其直接受\n到污染；二是通过食物链的富集作用间接地污染食物。\n来自污水和河流\n食物链一一\n死亡腐烂 ~ 一\nRi 一一\n9-1 DDT 在全球环境中的迁移富集途径","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"original-only","importance":null,"pastExamYears":[2022],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。","含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":154,"sourceRange":{"startPage":154,"startY":547.36,"endPage":155,"endY":583.88},"sourceKind":"original","originalOrdinal":"6","sourceMetadata":["2022(简, 【重要程度: 】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":9,"versionReason":"变动PDF第17页：原知识点4—10改为旧版补充。","excerpts":[{"page":154,"src":"./assets/environment/env838-ff8f811403f43ad3-154.webp"},{"page":155,"src":"./assets/environment/env838-ff8f811403f43ad3-155.webp"}]},{"id":"env838-37668f92e87a9943","subject":"环境学导论","chapter":"第9章 食品生产与环境","originalChapter":"第9章 粮食生产与环境","originalChapterNumber":9,"section":"","originalSection":"","category":"knowledge","title":"农药对除虫害带来的问题","question":"农药对除虫害带来的问题","type":"简答题","answer":"①对害虫的天敌和其他益虫、益鸟有杀伤作用；\n②使害虫产生抗药性，因而增加用药的次数和数量，更加重了对\n环境的污染和危害","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"original-only","importance":null,"pastExamYears":[2004,2005,2008,2022],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":155,"sourceRange":{"startPage":155,"startY":583.88,"endPage":156,"endY":34.73},"sourceKind":"original","originalOrdinal":"7","sourceMetadata":["2004(简、2005(简、2008(简、2022 (简,【重要程度: 】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":9,"versionReason":"变动PDF第17页：原知识点4—10改为旧版补充。","excerpts":[{"page":155,"src":"./assets/environment/env838-37668f92e87a9943-155.webp"}]},{"id":"env838-45b7e9f4a33b640c","subject":"环境学导论","chapter":"第9章 食品生产与环境","originalChapter":"第9章 粮食生产与环境","originalChapterNumber":9,"section":"","originalSection":"","category":"knowledge","title":"防止农药污染的途径","question":"防止农药污染的途径","type":"简答题","answer":"适当的利用农药以保证农业的增产和消灭某些传染性疾病，从当\n前的趋势看来是必要的，不过，化学农药的大量使用确实引起了不少\n严重的问题。目前为了防止农药的污染和危害，有以下防治措施：\n①采取综合防治的方法，研究新的杀虫除害途径，联合或交替使\n用物理、化学、生物和其他有效方法，克服单纯依赖化学农药的方法\n②安全、合理地使用现有的农药；\n③发展高效、低毒、低残毒的化学农药来代替剧毒和残留性高的\n农药；\n④搞好农药的安全性评价和安全使用标准的制定工作。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"original-only","importance":null,"pastExamYears":[2022],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":156,"sourceRange":{"startPage":156,"startY":34.73,"endPage":156,"endY":414.25},"sourceKind":"original","originalOrdinal":"8","sourceMetadata":["2022 ( 简, 【重要程度:"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":9,"versionReason":"变动PDF第17页：原知识点4—10改为旧版补充。","excerpts":[{"page":156,"src":"./assets/environment/env838-45b7e9f4a33b640c-156.webp"}]},{"id":"env838-a5fef166cdd6f809","subject":"环境学导论","chapter":"第9章 食品生产与环境","originalChapter":"第9章 粮食生产与环境","originalChapterNumber":9,"section":"","originalSection":"","category":"knowledge","title":"微生物农药的优点","question":"微生物农药的优点","type":"简答题","answer":"微生物农药是生物防治的重要组成部分，通常是利用微生物本身\n或其产物制成的农药。\n①杀虫效率高；\n②不产生公害；\n③对人畜无毒，能增强植物的抗病性并刺激植物的生长；\n④生产简便成本低，可利用农副产品甚至工业废水为原料；\n⑤药效长，能充分发挥作用；\n⑥与化学农药相比，对害虫不易产生抗药性。\n现有微生物农药有细菌、真菌、病毒和抗菌素等四类，前三类用\n于杀虫，后一类用于防治虫害。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"original-only","importance":1,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":156,"sourceRange":{"startPage":156,"startY":414.25,"endPage":157,"endY":56.65},"sourceKind":"original","originalOrdinal":"9","sourceMetadata":["【重要程度: ★☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":9,"versionReason":"变动PDF第17页：原知识点4—10改为旧版补充。","excerpts":[{"page":156,"src":"./assets/environment/env838-a5fef166cdd6f809-156.webp"},{"page":157,"src":"./assets/environment/env838-a5fef166cdd6f809-157.webp"}]},{"id":"env838-294f0baa5cf561b7","subject":"环境学导论","chapter":"第9章 食品生产与环境","originalChapter":"第9章 粮食生产与环境","originalChapterNumber":9,"section":"","originalSection":"","category":"knowledge","title":"如何利用生物学原理提高粮食产量","question":"如何利用生物学原理提高粮食产量","type":"简答题","answer":"①植树造林、保护森林、减少水、旱灾害。\n森林具有蓄水保土的功能，破坏森林，就可能导致水旱灾害，使\n作物减产。\n②充分利用太阳能，增加初级净产量。\n在时间和空间上，增加太阳能利用率，加强光合作用，是增加植\n物初级净产量，即增加人类食物来源的另一重要途径。在一块土地上\n，同时穿插种植高度不同，对光能要求不同的植物，组成层次分明的\n人工植物群落，或合理密植，都能充分利用太阳能，增加初级净产量\n③充分发挥初级净产量转变为食物的作用\n把农业废弃物和杂草，经过加工制成饲料，喂养牲畜和家禽，生\n产肉类食品，动物产生的粪便用于生产沼气工作能源，沼气池底渣用\n作肥料还田，使土壤的养分得以循环恢复；既能充分利用净初级生产\n量，又能减少对环境的污染。\n④遵循物流平衡规律，保护土地肥力\n任何植物在其生长过程中，都要根据其自身的需要从土壤中摄取\n一定种类和数量的营养成分。在自然生态系统中，植物通过枯枝落叶\n在分解者的作用下，使等值等量的营养成分回到土壤中，形成输入输\n出的平衡体系，土壤肥力也得以保持。\n⑤合理捕捞，保护海产资源\n根据生态学规律，按照不同鱼类的生长成熟周期以及资源量，在\n有利于资源恢复的前提下，规划捕捞活动，才能持续稳定的获得最大\n的海产品产量。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"original-only","importance":null,"pastExamYears":[2012,2013,2021],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":157,"sourceRange":{"startPage":157,"startY":56.65,"endPage":158,"endY":75.61},"sourceKind":"original","originalOrdinal":"10","sourceMetadata":["2012(论、2013(简、2021( 简, 【重要程度:"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":9,"versionReason":"变动PDF第17页：原知识点4—10改为旧版补充。","excerpts":[{"page":157,"src":"./assets/environment/env838-294f0baa5cf561b7-157.webp"},{"page":158,"src":"./assets/environment/env838-294f0baa5cf561b7-158.webp"}]},{"id":"env838-200ada62032c1436","subject":"环境学导论","chapter":"第9章 食品生产与环境","originalChapter":"第9章 粮食生产与环境","originalChapterNumber":9,"section":"第2节 课后习题","originalSection":"第2节 课后习题","category":"exercise","title":"粮食安全的定义及其重要性是什么?","question":"粮食安全的定义及其重要性是什么?","type":"简答题","answer":"粮食安全强调所有人在任何时候，都能在物质和经济上获取满足健康生活所需的足够、安全及有营养的食物。\n答题可概括四个维度：供给是否充足、家庭个人是否能够获得、能否合理利用其营养，以及这些条件能否稳定持续。\n重要性：①保障基本生存与健康；②维持社会稳定和国家安全；③支持经济发展与民生保障；④提高应对灾害、市场和国际供应链冲击的能力。\n粮食安全不仅是总产量问题，还涉及分配、收入、营养、储运和生态可持续性；食品安全侧重危害控制，与粮食安全相联系但范围不同。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":158,"sourceRange":{"startPage":158,"startY":109.23,"endPage":158,"endY":182.99},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":9,"excerpts":[{"page":158,"src":"./assets/environment/env838-200ada62032c1436-158.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=151"},{"title":"FAO：粮食安全的定义","url":"https://www.fao.org/4/w4979e/w4979e05.htm","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-7d6f463c7a3472ef","subject":"环境学导论","chapter":"第9章 食品生产与环境","originalChapter":"第9章 粮食生产与环境","originalChapterNumber":9,"section":"第2节 课后习题","originalSection":"第2节 课后习题","category":"exercise","title":"简述我国粮食安全的现状。","question":"简述我国粮食安全的现状。","type":"简答题","answer":"整理答案（按教材对应知识点摘录）：\n\n我国粮食安全现状：\n（1）粮食产量稳步增长\n① 人均占有量稳定在世界平均水平。我国人均粮食占有量持续增长，较新\n中国成立初期大幅提升，高于世界平均水平。\n② 单产显著提高。我国粮食单位面积产量持续提升，稻谷、小麦、玉米等\n主要粮食品种单产均高于世界平均水平。\n③ 总产量连上新台阶。我国粮食总产量持续增长，2023 年达 6.9×10⁸t，已\n连续 9 年稳定在 6.5×10⁸t 以上。\n（2）谷物供应基本自给\n① 实现谷物基本自给。2023 年我国谷物产量占粮食总产量的 90% 以上，\n谷物自给率超过 95%，为保障国家粮食安全、促进经济社会发展和国家长治久\n安奠定了坚实的物质基础。\n② 确保口粮绝对安全。我国稻谷和小麦产需有余，完全能够自给，进出口\n主要是品种调剂；进口粮食以大豆为主，稻谷和小麦两大口粮品种合计占比不足\n6%。\n（3）粮食储备能力显著增强\n① 仓储现代化水平明显提高。全国粮食标准仓房完好仓容稳步增长，低温、\n准低温储粮仓容及气调储粮仓容规模持续扩大，国有粮库储粮周期内综合损失率\n控制在 1% 的合理范围内，安全储粮能力持续增强，总体达到世界较先进水平。\n② 物流能力大幅提升。全国粮食物流总量稳步提升，粮食物流骨干通道全\n部打通，运输方式不断优化，粮食物流效率稳步提高。\n③ 粮食储备和应急体系逐步健全。在大中城市和价格易波动地区建立了\n10～15 天的应急成品粮储备，应急储备、加工和配送体系基本形成，应急供应\n网点覆盖广泛，在应对重大自然灾害和公共突发事件等方面具有重要作用。\n（4）居民健康营养状况明显改善\n① 膳食品种丰富多样。我国居民油料、畜禽肉、水产品、果蔬等各类食物\n人均占有量均有不同程度增长；居民人均直接消费口粮减少，动物性食品、果蔬\n等非粮食食物消费增加，食物更加多样，饮食更加健康。\n② 营养水平不断提高。我国城乡居民膳食能量得到充足供给，蛋白质、脂\n肪、碳水化合物三大营养素供能充足，碳水化合物供能比下降，脂肪供能比上升，\n优质蛋白质摄入增加。\n（5）贫困人口吃饭问题有效解决\n我国有效解决了贫困人口吃不饱的问题，重点贫困群体健康营养状况明显改\n善。贫困地区农村居民收入水平提升，粮食获取能力增强，粮谷类食物摄入量稳\n定增加；各类营养改善项目广泛实施，儿童、孕妇和老年人等重点人群营养水平\n明显提高，健康状况显著改善。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["根据所列知识点摘录整理，未逐题人工审定。"],"verified":false,"page":158,"sourceRange":{"startPage":158,"startY":182.99,"endPage":158,"endY":256.46},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":9,"references":[{"id":"env838-706906eab50b4c92","title":"我国粮食安全现状","source":"环导变动137718728584015123.1eae00877280d3e.pdf","page":18}],"excerpts":[{"page":158,"src":"./assets/environment/env838-7d6f463c7a3472ef-158.webp"}]},{"id":"env838-dd5963a36fa970e7","subject":"环境学导论","chapter":"第9章 食品生产与环境","originalChapter":"第9章 粮食生产与环境","originalChapterNumber":9,"section":"第2节 课后习题","originalSection":"第2节 课后习题","category":"exercise","title":"化肥污染的主要危害及防治方法有哪些?","question":"化肥污染的主要危害及防治方法有哪些?","type":"简答题","answer":"危害：过量施肥使氮磷流失，造成地表水富营养化及地下水硝酸盐风险；不合理长期施肥可能引起土壤酸化、盐分或养分失衡；氨挥发及氧化亚氮排放还影响空气和气候。杂质及产品质量不合格的投入品也可能增加污染。\n防治：测土配方、按需和分次施肥，改进施肥位置与时机；合理利用有机肥并重视其质量；推广适宜的缓控释及水肥一体化技术；采用轮作、覆盖、生态沟渠和缓冲带，减少径流损失。\n核心是提高养分利用效率，不以降低农作物正常需肥供给为代价。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":158,"sourceRange":{"startPage":158,"startY":256.46,"endPage":158,"endY":331.47},"sourceKind":"original","originalOrdinal":"3","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":9,"excerpts":[{"page":158,"src":"./assets/environment/env838-dd5963a36fa970e7-158.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=151"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-f4ee36ef15032a3a","subject":"环境学导论","chapter":"第9章 食品生产与环境","originalChapter":"第9章 粮食生产与环境","originalChapterNumber":9,"section":"第2节 课后习题","originalSection":"第2节 课后习题","category":"exercise","title":"农药污染的主要危害及防治方法有哪些?","question":"农药污染的主要危害及防治方法有哪些?","type":"简答题","answer":"危害：农药可经漂移、径流、渗漏等污染水、气和土壤；残留及不当接触危害人体和非靶标生物；长期单一用药可产生抗药性，破坏天敌和生态平衡。具体风险取决于毒性、剂量、暴露和环境归趋。\n防治：优先综合病虫害管理，结合农业、物理及生物防治；选择合法、高效、低风险药剂，按登记用途及剂量精准施用；注意时机和安全间隔期，保护水源及敏感区域；规范储运和废包装回收，开展残留监测与人员培训。\n不能把“天然”或“生物来源”直接等同于绝对无害。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":158,"sourceRange":{"startPage":158,"startY":331.47,"endPage":158,"endY":406.71},"sourceKind":"original","originalOrdinal":"4","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":9,"excerpts":[{"page":158,"src":"./assets/environment/env838-f4ee36ef15032a3a-158.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=151"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-34a6038ef2a92979","subject":"环境学导论","chapter":"第9章 食品生产与环境","originalChapter":"第9章 粮食生产与环境","originalChapterNumber":9,"section":"第2节 课后习题","originalSection":"第2节 课后习题","category":"exercise","title":"我国实现粮食安全生产的途径是什么?","question":"我国实现粮食安全生产的途径是什么?","type":"简答题","answer":"①保护耕地和土壤质量，提高高标准农田、水利及抗灾能力，稳定生产基础。\n②依靠良种、合理栽培和农业科技提高单产与质量，避免以过量化肥农药换取短期产量。\n③推进节水、养分高效利用及生态农业，兼顾产量、资源和环境。\n④完善储备、物流与加工，减少生产、储运和消费环节损失及浪费。\n⑤通过合理贸易和多元供应提高韧性，同时保障必要的国内生产能力。\n⑥关注农民收益、家庭购买能力和营养，使“有粮”与“能获得、能健康利用”相统一。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":158,"sourceRange":{"startPage":158,"startY":406.71,"endPage":159,"endY":63.18},"sourceKind":"original","originalOrdinal":"5","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":9,"excerpts":[{"page":158,"src":"./assets/environment/env838-34a6038ef2a92979-158.webp"},{"page":159,"src":"./assets/environment/env838-34a6038ef2a92979-159.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=151"},{"title":"FAO：粮食安全的定义","url":"https://www.fao.org/4/w4979e/w4979e05.htm","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-835f251d96e0a739","subject":"环境学导论","chapter":"第9章 食品生产与环境","originalChapter":"第8章 人口与环境","originalChapterNumber":8,"section":"第1节","originalSection":"","category":"supplement","title":"粮食安全的意义","question":"粮食安全的意义","type":"简答题","answer":"(1)政治意义\n“为政之要，首在足食”。粮食是治国安邦的基础，是稳定时局的利器。一\n定的粮食储备对稳定人民心理具有重要作用。\n(2)军事意义\n“兵马未动，粮草先行”。粮食是战争的必需品，是世界性的备战备荒战略\n物资。\n(3)经济意义\n农业的健康发展是国民经济健康发展的基础，粮食安全又是农业健康发展的\n基础。","source":"环导变动137718728584015123.1eae00877280d3e.pdf","sourceUrl":"https://drive.google.com/file/d/11CjvWmrS4poAVMmBBWnsJPRCmD1-JkRJ/view","version":"new","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["变动PDF第16页标为第八章；按粮食安全主题映射至食品生产与环境，需核对原书。"],"verified":false,"page":16,"sourceRange":{"startPage":16,"startY":289.0,"endPage":16,"endY":595.02},"sourceKind":"changes","originalOrdinal":"4","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":9,"additionalSources":[{"source":"环导变动137718728584015123.1eae00877280d3e.pdf","page":19,"sourceRange":{"startPage":19,"startY":352.96,"endPage":19,"endY":629.01}}],"excerpts":[{"page":16,"src":"./assets/environment/env838-835f251d96e0a739-16.webp"}]},{"id":"env838-55fe48e6da9c2999","subject":"环境学导论","chapter":"第9章 食品生产与环境","originalChapter":"第8章 人口与环境","originalChapterNumber":8,"section":"第1节","originalSection":"","category":"supplement","title":"粮食安全面临的挑战","question":"粮食安全面临的挑战","type":"简答题","answer":"(1)自然灾害\n自然灾害会导致粮食产量急剧下降，加上各种原因造成的耕地面积不断减少，\n世界的粮食产量受到严重影响。虽然科技的发展与应用使粮食单产不断攀升，但\n增长速度明显放慢，已无法跟上粮食消耗速度的增加。\n(2)全球变暖\n由气候变暖引起的严重干旱、洪涝、冰雪等灾害，导致了世界粮食减产。\n(3)金融危机\n金融危机对世界粮食安全的影响主要体现在生产和消费两个方面。在生产方\n面，金融危机的出现使得世界重要的粮食生产国——美国和一些欧洲国家等出现\n了信贷紧缩，使得粮食生产者无法及时获得生产所需的贷款，进而会影响下一年\n度粮食作物的种植，给粮食生产前景增加了很大的不确定性。而消费方面，经济\n疲软会减少人们对肉类的消费，增加对粮食的消费。\n(4)世界生物能源工业的快速发展，加速粮食供求矛盾\n在石油价格暴涨和人们对生态环境保护日益重视的局面下，许多国家致力于\n开发生产以农作物为生产原料的生物燃料，粮食市场的供给因对农作物需求量的\n加大而日渐紧张。","source":"环导变动137718728584015123.1eae00877280d3e.pdf","sourceUrl":"https://drive.google.com/file/d/11CjvWmrS4poAVMmBBWnsJPRCmD1-JkRJ/view","version":"new","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["变动PDF第16页标为第八章；按粮食安全主题映射至食品生产与环境，需核对原书。"],"verified":false,"page":16,"sourceRange":{"startPage":16,"startY":595.02,"endPage":17,"endY":421.0},"sourceKind":"changes","originalOrdinal":"5","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":9,"additionalSources":[{"source":"环导变动137718728584015123.1eae00877280d3e.pdf","page":19,"sourceRange":{"startPage":19,"startY":629.01,"endPage":20,"endY":451.02}}],"excerpts":[{"page":16,"src":"./assets/environment/env838-55fe48e6da9c2999-16.webp"},{"page":17,"src":"./assets/environment/env838-55fe48e6da9c2999-17.webp"}]},{"id":"env838-b75c5dc09698a1b8","subject":"环境学导论","chapter":"第9章 食品生产与环境","originalChapter":"第9章 粮食生产与环境","originalChapterNumber":9,"section":"第1节","originalSection":"第1节","category":"supplement","title":"食品安全的含义","question":"食品安全的含义","type":"简答题","answer":"①从数量的角度，要求人们既能买得到、又买得起需要的基本食品。\n②从质量的角度，要求食品营养全面、结构合理、卫生健康。\n③从发展的角度，要求食品的获取注重生态环境的保护和资源利用的可持续\n性。","source":"环导变动137718728584015123.1eae00877280d3e.pdf","sourceUrl":"https://drive.google.com/file/d/11CjvWmrS4poAVMmBBWnsJPRCmD1-JkRJ/view","version":"new","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":17,"sourceRange":{"startPage":17,"startY":511.02,"endPage":17,"endY":653.01},"sourceKind":"changes","originalOrdinal":"食品安全含义","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":9,"excerpts":[{"page":17,"src":"./assets/environment/env838-b75c5dc09698a1b8-17.webp"}]},{"id":"env838-ff33cd326b5a57cd","subject":"环境学导论","chapter":"第9章 食品生产与环境","originalChapter":"第9章 粮食生产与环境","originalChapterNumber":9,"section":"第1节","originalSection":"第1节","category":"supplement","title":"全球粮食安全现状","question":"全球粮食安全现状","type":"简答题","answer":"①粮食数量仍然短缺，全球饥饿人数不断增加；\n②全球粮食和人口分布不均衡，分配和消费结构性失衡；\n③经济发展不平等导致粮食安全不平等加剧。","source":"环导变动137718728584015123.1eae00877280d3e.pdf","sourceUrl":"https://drive.google.com/file/d/11CjvWmrS4poAVMmBBWnsJPRCmD1-JkRJ/view","version":"new","importance":0,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":17,"sourceRange":{"startPage":17,"startY":653.01,"endPage":18,"endY":108.97},"sourceKind":"changes","originalOrdinal":"全球粮食安全现状","sourceMetadata":["【重要程度：☆☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":9,"excerpts":[{"page":17,"src":"./assets/environment/env838-ff33cd326b5a57cd-17.webp"},{"page":18,"src":"./assets/environment/env838-ff33cd326b5a57cd-18.webp"}]},{"id":"env838-706906eab50b4c92","subject":"环境学导论","chapter":"第9章 食品生产与环境","originalChapter":"第9章 粮食生产与环境","originalChapterNumber":9,"section":"第1节","originalSection":"第1节","category":"supplement","title":"我国粮食安全现状","question":"我国粮食安全现状","type":"简答题","answer":"（1）粮食产量稳步增长\n① 人均占有量稳定在世界平均水平。我国人均粮食占有量持续增长，较新\n中国成立初期大幅提升，高于世界平均水平。\n② 单产显著提高。我国粮食单位面积产量持续提升，稻谷、小麦、玉米等\n主要粮食品种单产均高于世界平均水平。\n③ 总产量连上新台阶。我国粮食总产量持续增长，2023 年达 6.9×10⁸t，已\n连续 9 年稳定在 6.5×10⁸t 以上。\n（2）谷物供应基本自给\n① 实现谷物基本自给。2023 年我国谷物产量占粮食总产量的 90% 以上，\n谷物自给率超过 95%，为保障国家粮食安全、促进经济社会发展和国家长治久\n安奠定了坚实的物质基础。\n② 确保口粮绝对安全。我国稻谷和小麦产需有余，完全能够自给，进出口\n主要是品种调剂；进口粮食以大豆为主，稻谷和小麦两大口粮品种合计占比不足\n6%。\n（3）粮食储备能力显著增强\n① 仓储现代化水平明显提高。全国粮食标准仓房完好仓容稳步增长，低温、\n准低温储粮仓容及气调储粮仓容规模持续扩大，国有粮库储粮周期内综合损失率\n控制在 1% 的合理范围内，安全储粮能力持续增强，总体达到世界较先进水平。\n② 物流能力大幅提升。全国粮食物流总量稳步提升，粮食物流骨干通道全\n部打通，运输方式不断优化，粮食物流效率稳步提高。\n③ 粮食储备和应急体系逐步健全。在大中城市和价格易波动地区建立了\n10～15 天的应急成品粮储备，应急储备、加工和配送体系基本形成，应急供应\n网点覆盖广泛，在应对重大自然灾害和公共突发事件等方面具有重要作用。\n（4）居民健康营养状况明显改善\n① 膳食品种丰富多样。我国居民油料、畜禽肉、水产品、果蔬等各类食物\n人均占有量均有不同程度增长；居民人均直接消费口粮减少，动物性食品、果蔬\n等非粮食食物消费增加，食物更加多样，饮食更加健康。\n② 营养水平不断提高。我国城乡居民膳食能量得到充足供给，蛋白质、脂\n肪、碳水化合物三大营养素供能充足，碳水化合物供能比下降，脂肪供能比上升，\n优质蛋白质摄入增加。\n（5）贫困人口吃饭问题有效解决\n我国有效解决了贫困人口吃不饱的问题，重点贫困群体健康营养状况明显改\n善。贫困地区农村居民收入水平提升，粮食获取能力增强，粮谷类食物摄入量稳\n定增加；各类营养改善项目广泛实施，儿童、孕妇和老年人等重点人群营养水平\n明显提高，健康状况显著改善。","source":"环导变动137718728584015123.1eae00877280d3e.pdf","sourceUrl":"https://drive.google.com/file/d/11CjvWmrS4poAVMmBBWnsJPRCmD1-JkRJ/view","version":"new","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":18,"sourceRange":{"startPage":18,"startY":108.97,"endPage":19,"endY":352.96},"sourceKind":"changes","originalOrdinal":"我国粮食安全现状","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":9,"excerpts":[{"page":18,"src":"./assets/environment/env838-706906eab50b4c92-18.webp"},{"page":19,"src":"./assets/environment/env838-706906eab50b4c92-19.webp"}]},{"id":"env838-f08e40df0ab2bbfe","subject":"环境学导论","chapter":"第9章 食品生产与环境","originalChapter":"第9章 粮食生产与环境","originalChapterNumber":9,"section":"第2节","originalSection":"第2节","category":"supplement","title":"水产品与安全","question":"水产品与安全","type":"简答题","answer":"水产品是海洋和淡水渔业生产的水产动植物产品及其加工产品的总称，主要\n通过捕捞和养殖获得。水产品原料主要包括:鱼、虾、蟹、贝、藻类、海参等几大\n类别。\n水产品安全主要指水产品不能含有损害或者威胁人体健康的有毒有害物质，\n比如微生物、寄生虫、重金属、兽药残留、农药残留和其他有机污染物。","source":"环导变动137718728584015123.1eae00877280d3e.pdf","sourceUrl":"https://drive.google.com/file/d/11CjvWmrS4poAVMmBBWnsJPRCmD1-JkRJ/view","version":"new","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":20,"sourceRange":{"startPage":20,"startY":481.02,"endPage":20,"endY":637.05},"sourceKind":"changes","originalOrdinal":"1","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":9,"excerpts":[{"page":20,"src":"./assets/environment/env838-f08e40df0ab2bbfe-20.webp"}]},{"id":"env838-7a7c8b25a6ffde9a","subject":"环境学导论","chapter":"第9章 食品生产与环境","originalChapter":"第9章 粮食生产与环境","originalChapterNumber":9,"section":"第2节","originalSection":"第2节","category":"supplement","title":"环境对水产养殖的影响","question":"环境对水产养殖的影响","type":"简答题","answer":"（1）水体 pH\npH 值是评价养殖水质的重要指标。酸性水可使鱼血液 pH 值下降，降低血\n液的载氧能力，使血液中 O₂分压降低，造成缺氧症；碱性过强的水则会腐蚀鱼\n类的鳃组织。\n水体 pH 值会影响浮游植物对营养物质的吸收利用：低 pH 值会抑制硝酸\n盐还原酶的活性，高 pH 值则会妨碍藻类对 Fe、C 的利用。pH 值偏低会阻碍\n有益微生物活动，使固氮活性下降，有机物分解矿化速率降低，物质循环效率降\n低；如果 pH 值超出生物的生理极限范围，会迅速杀死生物。\n（2）重金属\n水产品重金属污染是全球范围内普遍的食品安全问题，水体重金属污染类型\n复杂，常见污染物有 Hg、Pb、Cu、Zn、As 等重金属类以及氰化物、氟化物等。\n养殖水体被重金属污染后，水产养殖品种可通过鳃的呼吸作用、摄食饵料、\n体表与水体的渗透交换作用在体内富集重金属；重金属进入鱼体细胞后，会造成\n活性氧防御能力降低，损伤机体。\n鱼类对重金属有着极强的生物富集作用，在含重金属水体中生存时间越长，\n体内重金属浓度越高；鱼体表面黏液中的微生物有很强的甲基化作用，能把无机\n汞转化为甲基汞，鱼类体内的 Hg 几乎都以毒性极强的甲基汞形式存在，对人体\n的危害性更强。人类食用含重金属的水产养殖品种后，重金属会在体内逐步富集，\n造成急、慢性中毒，进而引发疾病、发育不完全、畸形等严重后果。\n（3）溶解氧\n养殖水体对溶解氧有严格的要求：连续 24h 中，水中溶解氧必须保持 16h\n以上大于 5mg/L，其余任何时候不得低于 3mg/L。溶解氧低于 3mg/L 会对鱼类\n的摄食、消化及健康带来较大影响；溶解氧低于 1mg/L 时，大部分鱼类会出现\n浮头现象，持续下降会造成缺氧窒息死亡。\n浮游生物的呼吸作用和水中有机物的氧化分解会消耗大量溶解氧，极易造成\n水体中氧含量不足，导致水产品 “泛塘”。\n此外，当水体中 NH₃-N 和亚硝酸盐的浓度超标时，也会影响水产品的生存\n和生长：轻则导致水产养殖品种生长缓慢、摄食减少、免疫力和抵抗力下降，易\n受致病菌入侵并发生病害；重则会引发急性、慢性中毒甚至死亡。","source":"环导变动137718728584015123.1eae00877280d3e.pdf","sourceUrl":"https://drive.google.com/file/d/11CjvWmrS4poAVMmBBWnsJPRCmD1-JkRJ/view","version":"new","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":20,"sourceRange":{"startPage":20,"startY":637.05,"endPage":21,"endY":701.01},"sourceKind":"changes","originalOrdinal":"2","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":9,"excerpts":[{"page":20,"src":"./assets/environment/env838-7a7c8b25a6ffde9a-20.webp"},{"page":21,"src":"./assets/environment/env838-7a7c8b25a6ffde9a-21.webp"}]},{"id":"env838-de2bfd14819b9f23","subject":"环境学导论","chapter":"第9章 食品生产与环境","originalChapter":"第9章 粮食生产与环境","originalChapterNumber":9,"section":"第2节","originalSection":"第2节","category":"supplement","title":"水产养殖对环境的影响","question":"水产养殖对环境的影响","type":"简答题","answer":"（1）鱼药残留\n鱼药残留是指水产品的任何可食部分中鱼药的原型化合物或（和）其代谢产\n物，并包括与药物母体有关的杂质在其组织、器官等中蓄积、贮存或以其他方式\n保留的现象。\n鱼药残留的影响有：\n① 污染生态环境。残留在环境中的鱼药及其代谢物，在多种环境因子的作\n用下，还可产生转移、转化再次进入水产动植物体内蓄积；而残留于环境中的抗\n菌类药物若不被及时降解，会破坏水质、土壤中微生物的平衡，引起生态环境失\n衡，造成环境污染。\n② 引起人类变态反应。滥用鱼药导致水产品中药物残留，在进入人体后，\n可能引起变态反应，严重时甚至造成危及生命的综合征。\n③ 产生抗药性。鱼药中常含有一定量的抗生素等药物，当人类长期食用后，\n容易产生抗药性，进而影响一些人类疾病的治疗效果。\n④ 产生 “三致” 危害。某些鱼药及其代谢物会产生致癌、致畸和致突变\n的三致作用，部分有强致癌作用的化学药品，我国目前已明文禁止使用。\n（2）微生物污染\n与其他肉类产品相比，微生物更易在水产品体内繁殖，各种致病菌、病毒和\n寄生虫会寄生于水产品的肠道、皮肤、肌肉等部位，生食这类 “带病” 的水产\n品时很可能患上食源性疾病，极大地影响消费者健康。\n（3）水体富营养化\n在养殖过程中，因养殖密度不断提高，以及大量投喂外源性饵料，使得残饵\n和水生动物排泄物在水体中大量蓄积，造成养殖水体中 N、P 等营养物质不断累\n积、浓度不断升高，当浓度达到一定限值，在水流缓慢和适宜的温度条件下就会\n形成养殖水体富营养化。\n水体富营养化具体危害有：有害藻类迅速繁殖，产生大量藻毒素；水体发黏\n致使水体纳氧力降低，溶氧严重不足；有害寄生虫大量繁殖；氨氮、亚硝酸盐、\n硫化氢等有毒有害物质大量沉积，造成养殖对象亚硝酸盐中毒。","source":"环导变动137718728584015123.1eae00877280d3e.pdf","sourceUrl":"https://drive.google.com/file/d/11CjvWmrS4poAVMmBBWnsJPRCmD1-JkRJ/view","version":"new","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":21,"sourceRange":{"startPage":21,"startY":701.01,"endPage":23,"endY":78.97},"sourceKind":"changes","originalOrdinal":"3","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":9,"excerpts":[{"page":21,"src":"./assets/environment/env838-de2bfd14819b9f23-21.webp"},{"page":22,"src":"./assets/environment/env838-de2bfd14819b9f23-22.webp"},{"page":23,"src":"./assets/environment/env838-de2bfd14819b9f23-23.webp"}]},{"id":"env838-a5263155606c5b7f","subject":"环境学导论","chapter":"第9章 食品生产与环境","originalChapter":"第9章 粮食生产与环境","originalChapterNumber":9,"section":"第3节 畜产养殖与环境","originalSection":"第3节 畜产养殖与环境","category":"supplement","title":"畜产品与安全","question":"畜产品与安全","type":"简答题","answer":"畜产品是农产品中一个很重要的组成部分，主要包括肉(猪、牛、羊、禽、兔\n等)、蛋(鸡、鸭、鹅、鹌鹑等禽蛋)、奶(牛奶、羊奶、马奶等)、蜂产品(蜂蜜、蜂\n王浆、蜂花粉等)以及其他副产品(动物内脏)。\n畜产品安全指农药残留、兽药残留、重金属污染、动物疫病传播、微生物污\n染、化学物质污染等危害因素不会对人、动植物和环境造成危害和潜在危害。","source":"环导变动137718728584015123.1eae00877280d3e.pdf","sourceUrl":"https://drive.google.com/file/d/11CjvWmrS4poAVMmBBWnsJPRCmD1-JkRJ/view","version":"new","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":23,"sourceRange":{"startPage":23,"startY":108.97,"endPage":23,"endY":295.0},"sourceKind":"changes","originalOrdinal":"1","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":9,"excerpts":[{"page":23,"src":"./assets/environment/env838-a5263155606c5b7f-23.webp"}]},{"id":"env838-610fe2810175f5ff","subject":"环境学导论","chapter":"第9章 食品生产与环境","originalChapter":"第9章 粮食生产与环境","originalChapterNumber":9,"section":"第3节 畜产养殖与环境","originalSection":"第3节 畜产养殖与环境","category":"supplement","title":"动物粪污对环境的影响","question":"动物粪污对环境的影响","type":"简答题","answer":"（1）对水体环境的污染\n畜禽粪污中含有大量有机质、N、P、K 等污染物，常会随养殖场冲洗废水\n进入江河湖泊水体中，通过畜禽排泄物进入水体的 COD 量已超过生活和工业\n污水 COD 排放量的总和。\n高浓度的畜禽有机污水排入水体会造成水体富营养化，导致水体溶解氧快速\n消耗、藻类过度繁殖、水生动物死亡、水质恶化。此外，畜禽粪污中常含有的重\n金属元素以及抗生素等，可通过土壤污染地下水，引发地下水中硝酸盐浓度超标，\n受污染水体往往难以处理，甚至造成持久性污染。\n（2）对大气环境的污染\n动物粪尿分解会产生硫醇、H₂S、有机胺等上百种有毒有害物质，既会造成\n周围空气污染、为动物疫病传播提供有利条件，也会影响周边居民的正常生活生\n产与身体健康。粪污处理产生的 CH₄和 N₂O 还会加重温室效应，在人类活动造\n成的温室气体排放中，畜牧业占比 15%。\n（3）对土壤环境的污染\n畜禽养殖对土壤的污染主要表现在过量施用畜禽粪污造成的土壤结构失衡\n和有害物质在土壤中的累积。\n未经合规处理的粪污中含有超标的病原微生物和抗生素药物残留。规模化养\n殖的粪污排放量远超土壤承载能力，无法及时消纳的粪污会造成土壤结构失衡；\n过度还田施用还会导致土壤中 N、K、P 等养分过剩，阻碍农作物生长。这些污\n染物不仅会污染农作物，还会沉积在土壤环境中，产生深远的污染问题。此外，\n过量的畜禽粪污堆放还会占用过多空间。","source":"环导变动137718728584015123.1eae00877280d3e.pdf","sourceUrl":"https://drive.google.com/file/d/11CjvWmrS4poAVMmBBWnsJPRCmD1-JkRJ/view","version":"new","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":23,"sourceRange":{"startPage":23,"startY":295.0,"endPage":24,"endY":204.97},"sourceKind":"changes","originalOrdinal":"2","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":9,"excerpts":[{"page":23,"src":"./assets/environment/env838-610fe2810175f5ff-23.webp"},{"page":24,"src":"./assets/environment/env838-610fe2810175f5ff-24.webp"}]},{"id":"env838-fca5155427b830b7","subject":"环境学导论","chapter":"第9章 食品生产与环境","originalChapter":"第9章 粮食生产与环境","originalChapterNumber":9,"section":"第3节 畜产养殖与环境","originalSection":"第3节 畜产养殖与环境","category":"supplement","title":"畜禽粪污污染防治措施","question":"畜禽粪污污染防治措施","type":"简答题","answer":"（1）粪污肥料化技术\n肥料化技术可最大限度除去粪污中的各种潜在危害，是目前应用最为广泛的\n无害化处理方法。动物粪污中含有 N、P 等微量元素及有机物等作物生长所必需\n的物质，并且具有化学肥料所不具备的改善土壤结构的效用。\n传统堆肥技术占地面积大、周期长，不能控制畜禽粪污臭气，限制了其在规\n模养殖中的应用与推广。工厂化生产模式的高温好氧堆肥有机物分解速度快、发\n酵时间短、可最大限度杀灭病原菌，成为畜禽粪污堆肥的首选方式。\n高温堆肥即将各种堆肥材料集中在一起，通过人工控制水分、温度、pH 值\n等因素，在厌氧、好氧或厌氧好氧交替的条件下对粪污进行腐解，最终转变成有\n机肥，是目前世界上较先进且粪污处理效果较好的方式之一。\n（2）粪污资源化技术\n畜禽粪污可作为生物质能源，经过开发利用可以节约和替代原生资源，减少\n对不可再生资源的依赖，实现资源可持续利用，是处理畜禽粪污的主要途径之一。\n目前常用的方法有沼气法、发电利用法等。\n沼气法利用厌氧发酵的原理除去或杀死粪污中的臭气、病原菌并产生清洁能\n源，常用在较大规模的养殖场；所生产的沼气可作为能源用于燃烧发电，副产品\n可作为肥料还田利用，最终实现沼气、沼液、沼渣的综合有效利用。\n发电利用法即将畜禽粪污集中起来燃烧并释放热能，利用热能进行发电，可\n有效实现能源的转换与利用，减少不可再生能源的消耗，燃烧后产生的灰分还可\n以加工成优质复合肥。\n沼气法在我国应用较广泛，但转换率有待提高；发电利用法在我国尚未得到\n广泛推广，还需要进一步提高转换率并加大推广力度。\n（3）粪污饲料化技术\n畜禽粪污含有丰富的粗蛋白、粗纤维、粗脂肪，以及 Ca、P 等矿物质元素，\n因此畜禽粪污再生饲料化是畜禽粪污资源利用的途径之一。目前粪污的饲料化技\n术主要有干燥法、青贮法、生物法等。\n干燥法运用自然或人工干燥的方式，将粪污与其他物质混合后进行干燥，干\n燥过程中可杀灭病原微生物、虫卵等，达到饲料的生产要求。\n青贮法将牲畜粪污与高碳水化合物含量的物料一同放入青贮窖，经过一段时\n间的厌氧发酵后压实、密封，可直接饲喂牲畜；该方法可以减少粗蛋白的流失，\n并能杀灭其中的微生物，使营养更均衡。\n生物法是指用粪污饲喂蚯蚓、蛆等生物，再将这类生物进行加工，进而将粪\n污间接转化为动物蛋白以饲喂动物；这类加工产物是优质的蛋白来源，且更经济\n实惠，是物美价廉的动物饲料。","source":"环导变动137718728584015123.1eae00877280d3e.pdf","sourceUrl":"https://drive.google.com/file/d/11CjvWmrS4poAVMmBBWnsJPRCmD1-JkRJ/view","version":"new","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":24,"sourceRange":{"startPage":24,"startY":204.97,"endPage":25,"endY":442.98},"sourceKind":"changes","originalOrdinal":"3","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":9,"excerpts":[{"page":24,"src":"./assets/environment/env838-fca5155427b830b7-24.webp"},{"page":25,"src":"./assets/environment/env838-fca5155427b830b7-25.webp"}]},{"id":"env838-7b58bd38380d84d0","subject":"环境学导论","chapter":"第10章 能源与环境","originalChapter":"第10章 能源与环境","originalChapterNumber":10,"section":"","originalSection":"","category":"knowledge","title":"能源的概念","question":"能源的概念","type":"简答题","answer":"是指可以为人类利用以获取有用能量的各种来源，如太阳能、水\n力、风力、蒸汽，化石燃料及核能、潮汐能等均可称为能源。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":160,"sourceRange":{"startPage":160,"startY":58.43,"endPage":160,"endY":195.43},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":["【重要程度： 】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":10,"excerpts":[{"page":160,"src":"./assets/environment/env838-7b58bd38380d84d0-160.webp"}]},{"id":"env838-5854641fec744d7c","subject":"环境学导论","chapter":"第10章 能源与环境","originalChapter":"第10章 能源与环境","originalChapterNumber":10,"section":"","originalSection":"","category":"knowledge","title":"能源的分类","question":"能源的分类","type":"简答题","answer":"能源分为一次能源和二次能源\n①一次能源，分为常规能源和新能源。常规能源包括水力等可再\n生能源和煤炭、石油、天然气等不可再生能源新能源包括大阳能生物\n能、风能、地热能、海洋能等可再生能源和核燃料等不可再生能源。\n②二次能源，主要是电力、焦炭、煤气、沼气、蒸汽、汽油、柴\n油、重油、氢和激光。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2001,2002,2004,2010],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":160,"sourceRange":{"startPage":160,"startY":195.43,"endPage":160,"endY":453.15},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":["2001(填、2002 (填、2004 (选、2010 (选, 【重要程度: 】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":10,"excerpts":[{"page":160,"src":"./assets/environment/env838-5854641fec744d7c-160.webp"}]},{"id":"env838-9203cfb26162270c","subject":"环境学导论","chapter":"第10章 能源与环境","originalChapter":"第10章 能源与环境","originalChapterNumber":10,"section":"","originalSection":"","category":"knowledge","title":"化石燃料利用对环境的影响","question":"化石燃料利用对环境的影响","type":"简答题","answer":"[1]化石燃料对生态环境的影响\n由于化石燃料是目前世界上使用的主要能源，其开采、运输、加\n工和燃烧耗用等方面的数量都很大，从而对环境的影响也最引人关注\n①开采对环境的影响\n井下开采煤炭破坏地壳内部原有的力学平衡，容易引起地表沉陷\n，从而导致地面工程设施的破坏和农田损坏，还会使地下水和地表水\n遭受严重的污染。露天开采占用大量农田草地等，也会对地表水和地\n下水产生不良的影响。此外，煤矿废水也对环境造成严重污染；\n原油开采过程中钻进泥浆内加入的烧碱、铁铬盐和盐酸等化学试\n剂会对井场周围水域和农田造成不良影响，同时原油开采过程中井喷\n事故会污染大片农田或海域，破坏生态平衡；\n天然气开采过程中易产生污染大气的硫化氢和污染河流的伴生\n盐水。\n②运输过程对环境的影响\n煤炭运输过程不仅需要消耗大量能源，而且在堆存和装卸过程中\n还会发生自燃或扬尘污染大气环境，并由于浸出水的流失而污染周围\n水系；\n石油运输会随着石油海运量的增加，因油船事故和油船外排洗舱\n水而进入海洋的石油量已显著增加，并对海洋造成严重污染。\n③加工过程对环境的影响\n煤在加工过程中对环境的影响很大，不但在洗选时排出大量洗煤\n水和干燥时产生灰尘、氮氧化物、硫氧化物，而且在它的气化和液化\n过程中还会排出大量污染物；\n石油加工过程或炼油厂运转过程中排放的废物更多。\n④利用过程对环境的污染\n化石燃料燃烧时产生的污染物对环境造成的影响：\n全球气候变化。化石燃料燃烧时排放大量的二氧化碳，导致温室\n效应，改变全球气候，危害生态系统。化石燃料利用过程产生的废热\n水排入水域后会使水域温度升高，明显改变原有的生态平衡。\n[2]其它污染及酸雨对环境的影响\n燃烧除对环境造成上述影响外，还向环境排放大量颗粒灰尘、硫\n氧化物、氮氧化物、一氧化碳、烃类、苯并芘和其他有机化合物等空\n气污染物等，硫酸、氟化物、磷酸盐等废水以及炉渣等固体废物。\n全球气候变化\n[待核对] FFA (WAKE) 热污染\n其他污染物及酸雨\n图 10-1 化石燃料的影响思维导图","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。","含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":160,"sourceRange":{"startPage":160,"startY":453.15,"endPage":162,"endY":303.7},"sourceKind":"original","originalOrdinal":"3","sourceMetadata":["【重要程度："],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":10,"excerpts":[{"page":160,"src":"./assets/environment/env838-9203cfb26162270c-160.webp"},{"page":161,"src":"./assets/environment/env838-9203cfb26162270c-161.webp"},{"page":162,"src":"./assets/environment/env838-9203cfb26162270c-162.webp"}]},{"id":"env838-6b83abfd76fb98bb","subject":"环境学导论","chapter":"第10章 能源与环境","originalChapter":"第10章 能源与环境","originalChapterNumber":10,"section":"","originalSection":"","category":"knowledge","title":"核电站对生态环境的影响","question":"核电站对生态环境的影响","type":"简答题","answer":"①慢性辐射的影响问题；\n②放射性废物的环境问题；\n③反应堆的安全问题。\n核电的优点：无空气污染、无漏油问题、无漏天矿坑、无酸性矿\n坑水等。缺点：存在放射性污染。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2017],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":162,"sourceRange":{"startPage":162,"startY":303.7,"endPage":162,"endY":531.05},"sourceKind":"original","originalOrdinal":"4","sourceMetadata":["2017(论, 【重要程度: 】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":10,"excerpts":[{"page":162,"src":"./assets/environment/env838-6b83abfd76fb98bb-162.webp"}]},{"id":"env838-2b57e25f2f8fd054","subject":"环境学导论","chapter":"第10章 能源与环境","originalChapter":"第10章 能源与环境","originalChapterNumber":10,"section":"","originalSection":"","category":"knowledge","title":"水电对环境的影响","question":"水电对环境的影响","type":"简答题","answer":"①自然方面\n巨大的水库可能引起地面沉降、地表活动加剧、甚至诱发地震；\n此外它还会引起流域水文上的改变，如下游河流水位降低甚至断流，\n从而造成土壤盐碱化，或来自上游河流的泥沙减少，补偿不了海浪对\n河口一带的冲刷作用，使三角洲受到侵蚀；水库建成后，由于蒸发量\n大，降雨量减少，气候凉爽且稳定，使水库地区的小气候大为改观。\n②地球化学方面\n流入、流出水库的水在颜色和气味等物理化学性质方面发生改变\n，而且水库中各层水的密度、温度甚至溶解氧等都有所不同。深层水\n的水温低，而且沉积库底的有机物不能充分氧化而处于厌氧状态，使\n水体中的二氧化碳浓度显著升高明显增强。\n③生物方面\n这与水库的地理位置和季节有关。总之，会影响水库周围的生物\n分布。\n④社会经济方面\n修建水库可改善用水的供应和管理，增加农田灌溉，生产电力，\n发展航运以及产生其他社会、经济效益，但同时亦有不利之处，如居\n民搬迁后重新定居，会对社会结构产生一定的影响。\n自然方面\nar 、 水文地表活\n10-2 水库的环境影响","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2002,2004,2008,2016,2017],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。","含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":162,"sourceRange":{"startPage":162,"startY":531.05,"endPage":163,"endY":660.27},"sourceKind":"original","originalOrdinal":"5","sourceMetadata":["2002(简--水力发电的缺点、2004(简、2008(简、2016(简) 、2017(论, 【重要程度"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":10,"excerpts":[{"page":162,"src":"./assets/environment/env838-2b57e25f2f8fd054-162.webp"},{"page":163,"src":"./assets/environment/env838-2b57e25f2f8fd054-163.webp"}]},{"id":"env838-5451ea1c7ba4b0b0","subject":"环境学导论","chapter":"第10章 能源与环境","originalChapter":"第10章 能源与环境","originalChapterNumber":10,"section":"","originalSection":"","category":"knowledge","title":"结合三峡工程论述如何减轻水力发电对环境的影响","question":"结合三峡工程论述如何减轻水力发电对环境的影响","type":"简答题","answer":"①采取蓄清排浑的运行方式，防止泥沙迅速淤积而使水库报废，\n实现长期保持水库库容；\n②采取正确的移民措施，保持社会稳定；\n③及时放空水库以减少战争破坏带来的灾难；\n④提前发掘与迁建文物古迹；\n⑤把环境影响的补偿投资打入建库计划中，使不利于库区的生态\n与环境影响控制到最小程度，实现经济建设与环境建设的三同步。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":163,"sourceRange":{"startPage":163,"startY":660.27,"endPage":164,"endY":212.42},"sourceKind":"original","originalOrdinal":"6","sourceMetadata":["【重要程度："],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":10,"excerpts":[{"page":163,"src":"./assets/environment/env838-5451ea1c7ba4b0b0-163.webp"},{"page":164,"src":"./assets/environment/env838-5451ea1c7ba4b0b0-164.webp"}]},{"id":"env838-a34e5f1bd72a8d83","subject":"环境学导论","chapter":"第10章 能源与环境","originalChapter":"第10章 能源与环境","originalChapterNumber":10,"section":"","originalSection":"","category":"knowledge","title":"如何利用生态学原理解决能源问题","question":"如何利用生态学原理解决能源问题","type":"简答题","answer":"①控制人口，减少能源消耗。控制人口增长的同时，控制个人的\n能源消耗，使能耗和环境所能提供的能量相协调；\n②太阳能是重要的能源。多利用太阳能这种洁净的、用之不尽的\n可再生能源，解决能源需求；\n③多渠道解决能源供求。生态学告诉我们，稳定的食物网，其能\n量流动是多通道的。不可能有任何一种能源可以独立满足人类社会庞\n大的能源需求，而需要多种能源同时并用；\n④充分利用能源并减少浪费。通过系统分析，全面比较产品的使\n用意义、能源消耗和经济效益，仔细规划一次使用和经久耐用的产品\n类别和产量，以减少能源的浪费。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":164,"sourceRange":{"startPage":164,"startY":212.42,"endPage":164,"endY":586.82},"sourceKind":"original","originalOrdinal":"7","sourceMetadata":["【重要程度："],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":10,"excerpts":[{"page":164,"src":"./assets/environment/env838-a34e5f1bd72a8d83-164.webp"}]},{"id":"env838-be3cf7909bae617d","subject":"环境学导论","chapter":"第10章 能源与环境","originalChapter":"第10章 能源与环境","originalChapterNumber":10,"section":"","originalSection":"","category":"knowledge","title":"太阳能的直接利用","question":"太阳能的直接利用","type":"简答题","answer":"太阳辐射是地球上生物得以存在的最重要的因素。太阳辐射不仅\n温暖了地球，带来了光明，而且为人们所广泛利用。太阳辐射可以直\n接转变为热和电，供建筑物采暖、空调、食品冷藏等。直接利用太阳\n能的主要设备有太阳能集热器、蓄热水箱、太阳灶、太阳能热电转换\n系统等。\n10-3 太阳能的利用途径","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。","含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":164,"sourceRange":{"startPage":164,"startY":586.82,"endPage":165,"endY":311.77},"sourceKind":"original","originalOrdinal":"8","sourceMetadata":["【重要程度： 】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":10,"excerpts":[{"page":164,"src":"./assets/environment/env838-be3cf7909bae617d-164.webp"},{"page":165,"src":"./assets/environment/env838-be3cf7909bae617d-165.webp"}]},{"id":"env838-0d16167e1ba2735a","subject":"环境学导论","chapter":"第10章 能源与环境","originalChapter":"第10章 能源与环境","originalChapterNumber":10,"section":"","originalSection":"","category":"knowledge","title":"太阳能利用系统对环境的影响","question":"太阳能利用系统对环境的影响","type":"简答题","answer":"优点：\n①无有毒气体排出，也没有影响地球气候的二氧化碳的排出；\n②占地面积与化石燃料及核能电站相当；\n③余热的排出低于其他热电站；\n缺点：\n①大阳能集热系统吸收太阳能后，减少了地面、建筑物等反射回\n空间的能量，结果影响了大气中的温度、梯度、大气组成、云层和风\n等；\n②巨大的集热系统、聚光装置，严重影响景观，以致改变建筑风\n格和建筑设计规范。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":1,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":165,"sourceRange":{"startPage":165,"startY":311.77,"endPage":165,"endY":686.28},"sourceKind":"original","originalOrdinal":"9","sourceMetadata":["【重要程度: ★☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":10,"excerpts":[{"page":165,"src":"./assets/environment/env838-0d16167e1ba2735a-165.webp"}]},{"id":"env838-36e9023718dd3177","subject":"环境学导论","chapter":"第10章 能源与环境","originalChapter":"第10章 能源与环境","originalChapterNumber":10,"section":"","originalSection":"","category":"knowledge","title":"生物质能","question":"生物质能","type":"简答题","answer":"生物体直接或间接吸收太阳能并不断进行转化，成为维持生命活\n动的能源，就是生物质能。\n植物的叶绿体在阳光的作用下，把水、二氧化碳、无机盐等转变\n为简单的小分子物质，再合成糖类、蛋白质、脂肪等较复杂的大分子\n，以ATP的形式，把能量储存起来。通常作为能源消耗掉的生物质能\n，包括薪柴、木炭、农副产品的下脚料或废弃物、能源树、杂草、人\n畜粪便以及上述物质经过一定的工艺过程而制成的醇类、沼气等。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2021],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":165,"sourceRange":{"startPage":165,"startY":686.28,"endPage":166,"endY":271.26},"sourceKind":"original","originalOrdinal":"10","sourceMetadata":["2021 ( 名, 【重要程度:"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":10,"excerpts":[{"page":165,"src":"./assets/environment/env838-36e9023718dd3177-165.webp"},{"page":166,"src":"./assets/environment/env838-36e9023718dd3177-166.webp"}]},{"id":"env838-b35d48f928c6c426","subject":"环境学导论","chapter":"第10章 能源与环境","originalChapter":"第10章 能源与环境","originalChapterNumber":10,"section":"","originalSection":"","category":"knowledge","title":"人工沼气","question":"人工沼气","type":"简答题","answer":"是指利用城市垃圾、污水、污泥、人畜粪便、庄稼秸秆、杂草等\n废弃物经好氧分解和厌氧分解两个阶段而得到的混合气体。其组成为\n甲烷、二氧化碳、氮、氢、氧和硫化氢等。\n(PS：只有人工生产的沼气才会有人为的好氧过程，自然沼气是严格\n厌氧的)\n沼气的形成包括好氧分解与厌氧分解两个过程的作用。其中好氧\n分解就是在产酸菌的作用下，把较复杂的大分子有机物转变成较简单\n的小分子物质，进而在甲烷菌的作用下经厌氧分解，而最后得到沼气\n。沼气产生时适宜pH为6.7-7.0,碳氮比一般控制在(30-35):1的范围\n内，密封、缺氧状态。\n[待核对] ----------# ROM ema\n[待核对] iy Ce Ha RAD\n[待核对] pea | CRE ”一一 Mh\n物脂肪酸丙酸\n图 10-4 沼气的形成过程","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2004,2010],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。","含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":166,"sourceRange":{"startPage":166,"startY":271.26,"endPage":167,"endY":287.32},"sourceKind":"original","originalOrdinal":"11","sourceMetadata":["2004(选,2010(选--组成成分,【重要程度:"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":10,"excerpts":[{"page":166,"src":"./assets/environment/env838-b35d48f928c6c426-166.webp"},{"page":167,"src":"./assets/environment/env838-b35d48f928c6c426-167.webp"}]},{"id":"env838-8d73fe84a6251664","subject":"环境学导论","chapter":"第10章 能源与环境","originalChapter":"第10章 能源与环境","originalChapterNumber":10,"section":"","originalSection":"","category":"knowledge","title":"风能","question":"风能","type":"简答题","answer":"①风能的来源\n它直接来自太阳能。由于地球表面各处情况不同，接受太阳辐射\n能不同，各地区的温差或气压也不同，结果形成了风。太阳传给地球\n的辐射能约有1%被转换成风能。风能属洁净的、取之不尽的能源。\n②风能利用的环境影响，主要是噪声；风车布置不当时，也会影\n响景观，甚至造成鸟类撞击伤亡而破坏生态平衡。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":167,"sourceRange":{"startPage":167,"startY":287.32,"endPage":167,"endY":553.48},"sourceKind":"original","originalOrdinal":"12","sourceMetadata":["【重要程度： 】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":10,"excerpts":[{"page":167,"src":"./assets/environment/env838-8d73fe84a6251664-167.webp"}]},{"id":"env838-92785502167a28a4","subject":"环境学导论","chapter":"第10章 能源与环境","originalChapter":"第10章 能源与环境","originalChapterNumber":10,"section":"","originalSection":"","category":"knowledge","title":"地热能","question":"地热能","type":"简答题","answer":"地热能是地球内部蕴藏的热能，它源于地球的熔融岩浆和放射性\n物质的衰变。地热资源的利用对环境会产生一定的污染，主要表现在\n大气污染、水的利用和污染、二氧化碳的排放、周边土壤与地下水受\n污染等方面。\n[待核对] eee an a Ped\n[待核对] Cans\n图 10-5 地热能来源","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":0,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。","含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":167,"sourceRange":{"startPage":167,"startY":553.48,"endPage":168,"endY":314.79},"sourceKind":"original","originalOrdinal":"13","sourceMetadata":["【重要程度: ☆☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":10,"excerpts":[{"page":167,"src":"./assets/environment/env838-92785502167a28a4-167.webp"},{"page":168,"src":"./assets/environment/env838-92785502167a28a4-168.webp"}]},{"id":"env838-164fef79b4a983c3","subject":"环境学导论","chapter":"第10章 能源与环境","originalChapter":"第10章 能源与环境","originalChapterNumber":10,"section":"","originalSection":"","category":"knowledge","title":"海洋能","question":"海洋能","type":"简答题","answer":"海洋能是海洋中海水所具有的能量，通常包括波浪能、潮：汐能、\n温差能、海流能和盐度差能。这些能源在利用过程中基本不会对环境\n造成污染，因此也属于清洁能源。海洋能利用形式主要有潮汐发电、\n海流发电、波浪发电、海洋温差发电、盐差发电等。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":0,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":168,"sourceRange":{"startPage":168,"startY":314.79,"endPage":168,"endY":513.61},"sourceKind":"original","originalOrdinal":"14","sourceMetadata":["【重要程度:☆☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":10,"excerpts":[{"page":168,"src":"./assets/environment/env838-164fef79b4a983c3-168.webp"}]},{"id":"env838-1212ab075f5aa18e","subject":"环境学导论","chapter":"第10章 能源与环境","originalChapter":"第10章 能源与环境","originalChapterNumber":10,"section":"","originalSection":"","category":"knowledge","title":"我国能源的现状","question":"我国能源的现状","type":"简答题","answer":"①能源丰富而人均消费量少。我国能源丰富，但分布很不均匀且\n人均消费量少；\n②能源构成以煤为主\n③燃煤严重污染环境\n④农村能源供应短缺。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2019],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":168,"sourceRange":{"startPage":168,"startY":513.61,"endPage":169,"endY":52.35},"sourceKind":"original","originalOrdinal":"15","sourceMetadata":["2019(论, 【重要程度:"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":10,"excerpts":[{"page":168,"src":"./assets/environment/env838-1212ab075f5aa18e-168.webp"},{"page":169,"src":"./assets/environment/env838-1212ab075f5aa18e-169.webp"}]},{"id":"env838-f6d4525ed51a8ee6","subject":"环境学导论","chapter":"第10章 能源与环境","originalChapter":"第10章 能源与环境","originalChapterNumber":10,"section":"","originalSection":"","category":"knowledge","title":"我国能源需求的预测","question":"我国能源需求的预测","type":"简答题","answer":"能源需求是社会经济发展、经济结构的变化、技术进步、节能政\n策和实施效果、能源结构等多方因素的共同作用所得到的结果。不同\n的经济发展道路，对能源需求有显著的影响。\n①能源需求总量巨大，结构明显改善；\n②终端能源趋向优质化；\n③国民经济电气化程度大大提高；\n④人均能耗仍将很低。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":0,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":169,"sourceRange":{"startPage":169,"startY":52.35,"endPage":169,"endY":348.24},"sourceKind":"original","originalOrdinal":"16","sourceMetadata":["【重要程度:☆☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":10,"excerpts":[{"page":169,"src":"./assets/environment/env838-f6d4525ed51a8ee6-169.webp"}]},{"id":"env838-517cb31be0338bdb","subject":"环境学导论","chapter":"第10章 能源与环境","originalChapter":"第10章 能源与环境","originalChapterNumber":10,"section":"","originalSection":"","category":"knowledge","title":"如何解决我国的能源问题","question":"如何解决我国的能源问题","type":"简答题","answer":"[1]煤的综合利用与燃烧技术的改进\n①煤的气化和综合利用。即把煤转化为气体燃料和液体燃料，转\n化为化工产品，加以综合利用，从而提高热效率和经济效益，并防止\n污染和减轻运输负担；\n②改进煤的燃烧技术。改革燃煤用炉灶的设计，同时还应立刻停\n止生产效率低和污染严重的炉窖。\n[2]保护农村生态平衡的能源政策\n根据我国农村的具体情况，采取因地制宜，多能互补的方针政策\n，积极利用沼气，营造薪炭林，推广速生树种，以利于绿化，制止水\n土流失，保护土壤肥力和延长水库寿命。\n①因地制宜开发多种能源\n我国土地辽阔，各种自然条件和能源储量差别很大。因此，能源\n开发也要采取因地制宜的方针，除在华北、东北和沿海大陆架地区继\n续积极开发煤和石油外，还应在西南和华南地区大力利用水力资源，\n发展水电事业；在缺乏矿物能源和水力资源的东南沿海地区，则应注\n意发展利用核电能、风能、潮汐能等；具有丰富太阳能的西北和华北\n地区，可以充分利用太阳能。\n②节约能源，保护环境的其他技术措施\n提高热和电的利用率。措施有集中供暖和联片供热；加速热机新\n技术和发展高效率的电热并供装置；发展炊事用电等。\n③合理利用石油资源\n④加强能源软科学的研究。能源软科学指的是通过大范围的调查\n研究和综合分析，提出科学的对能源问题的决策依据。\n总之，要满足我国未来的能源需求而又有利于环境保护，就一定\n要依靠科学技术，根据我国各地区的自然地理和资源状况，进行综合\n研究，制定适合我国国情的能源政策和规划。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2006,2013],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":169,"sourceRange":{"startPage":169,"startY":348.24,"endPage":171,"endY":58.84},"sourceKind":"original","originalOrdinal":"17","sourceMetadata":["2006(论、2013(简, 【重要程度:"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":10,"excerpts":[{"page":169,"src":"./assets/environment/env838-517cb31be0338bdb-169.webp"},{"page":170,"src":"./assets/environment/env838-517cb31be0338bdb-170.webp"},{"page":171,"src":"./assets/environment/env838-517cb31be0338bdb-171.webp"}]},{"id":"env838-f8566ae226d34555","subject":"环境学导论","chapter":"第10章 能源与环境","originalChapter":"第10章 能源与环境","originalChapterNumber":10,"section":"第2节 课后习题","originalSection":"第2节 课后习题","category":"exercise","title":"化石燃料的使用对环境会造成什么影响?","question":"化石燃料的使用对环境会造成什么影响?","type":"简答题","answer":"开采阶段：煤矿、油气田及配套工程占地、破坏植被和生境，可能引起地面沉降、水污染及甲烷逸散。\n加工储运阶段：产生粉尘、废水和固废，泄漏、溢油及事故带来生态风险。\n使用阶段：燃烧排放CO₂、NOₓ、SO₂、颗粒物等，造成气候变化、空气污染与酸沉降；不完全燃烧还产生CO等。\n全生命周期：灰渣、废设施、耗水和资源消耗也需管理。\n防治应结合节能、能源替代、清洁工艺与排放控制，避免只计算燃烧端排放而忽略开采及供应链影响。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":171,"sourceRange":{"startPage":171,"startY":96.55,"endPage":171,"endY":174.41},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":10,"excerpts":[{"page":171,"src":"./assets/environment/env838-f8566ae226d34555-171.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=159"},{"title":"中国的能源转型白皮书（英文全文）","url":"https://english.www.gov.cn/archive/whitepaper/202408/29/content_WS66d012e8c6d0868f4e8ea52e.html","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-00221414d5cd38f3","subject":"环境学导论","chapter":"第10章 能源与环境","originalChapter":"第10章 能源与环境","originalChapterNumber":10,"section":"第2节 课后习题","originalSection":"第2节 课后习题","category":"exercise","title":"简述当今世界的能源结构特点。","question":"简述当今世界的能源结构特点。","type":"简答题","answer":"当今能源结构可概括为：①化石能源在全球能源供给中仍有重要地位，存量基础设施和产业需求使转型具有长期性；②可再生能源增长较快，电气化以及核电等低排放电源的重要性上升；③不同地区的资源禀赋、能源可及性和结构差异明显；④能源安全、价格和供应链风险与减排目标共同影响选择。\n时间说明：IEA《Global Energy Review 2026》总结的是2025年情况，其中太阳能成为全球能源需求增量的重要来源，低排放能源承担了较大增量。不能把“增量占比”当作“全部能源存量占比”。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":171,"sourceRange":{"startPage":171,"startY":174.41,"endPage":171,"endY":253.43},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":10,"excerpts":[{"page":171,"src":"./assets/environment/env838-00221414d5cd38f3-171.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=159"},{"title":"IEA：Global Energy Review 2026主要结论","url":"https://www.iea.org/reports/global-energy-review-2026/key-findings","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-641bf48b6fbce553","subject":"环境学导论","chapter":"第10章 能源与环境","originalChapter":"第10章 能源与环境","originalChapterNumber":10,"section":"第2节 课后习题","originalSection":"第2节 课后习题","category":"exercise","title":"试分析当今世界能源消耗与供应的特点。","question":"试分析当今世界能源消耗与供应的特点。","type":"简答题","answer":"消费特点：总需求受人口、收入、产业、气候及效率影响；发展阶段与人均消费差异较大，工业化、交通及电气化持续改变需求结构。\n供应特点：资源地理分布与消费中心不一致，跨区域运输和贸易重要；化石能源与低排放能源并存，基础设施、储能和电网约束影响转型。\n矛盾：需求增长与资源环境约束、能源安全与国际市场波动、减排与成本之间需要协调。\n发展方向：提高能效，扩大清洁能源供给和互联互通，提升供应链与系统韧性。讨论“当前”趋势时须标明报告年份，区分能源消费与电力消费。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":171,"sourceRange":{"startPage":171,"startY":253.43,"endPage":171,"endY":333.19},"sourceKind":"original","originalOrdinal":"3","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":10,"excerpts":[{"page":171,"src":"./assets/environment/env838-641bf48b6fbce553-171.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=159"},{"title":"IEA：Global Energy Review 2026主要结论","url":"https://www.iea.org/reports/global-energy-review-2026/key-findings","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-e800496d2938471e","subject":"环境学导论","chapter":"第10章 能源与环境","originalChapter":"第10章 能源与环境","originalChapterNumber":10,"section":"第2节 课后习题","originalSection":"第2节 课后习题","category":"exercise","title":"能源的分类有哪些?其对环境有怎样的影响?","question":"能源的分类有哪些?其对环境有怎样的影响?","type":"简答题","answer":"按形成可分一次能源和二次能源：前者如煤、石油、天然气、太阳辐射等，后者如电力、成品燃料等。\n按可更新性可分可再生与不可再生能源；按利用形式还可分燃料、动力及热能等。分类维度可以交叉。\n环境影响：化石能源存在开采破坏、污染和碳排放；水电可能改变河流连通性和生境；核能需管理放射性废物及事故风险；风光能运行排放较低，但仍涉及土地、材料、制造和退役；生物质能需关注土地竞争及燃烧排放。\n应采用生命周期视角，不能把“可再生”理解为没有环境影响。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":171,"sourceRange":{"startPage":171,"startY":333.19,"endPage":171,"endY":413.43},"sourceKind":"original","originalOrdinal":"4","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":10,"excerpts":[{"page":171,"src":"./assets/environment/env838-e800496d2938471e-171.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=159"},{"title":"中国的能源转型白皮书（英文全文）","url":"https://english.www.gov.cn/archive/whitepaper/202408/29/content_WS66d012e8c6d0868f4e8ea52e.html","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-169e85a334f5010e","subject":"环境学导论","chapter":"第10章 能源与环境","originalChapter":"第10章 能源与环境","originalChapterNumber":10,"section":"第2节 课后习题","originalSection":"第2节 课后习题","category":"exercise","title":"简述主要的清洁能源种类及其特征发展趋势。","question":"简述主要的清洁能源种类及其特征发展趋势。","type":"简答题","answer":"主要类型：太阳能、风能、水能、地热、海洋能、可持续利用的生物质能，以及核能等低碳电源。天然气燃烧的一些常规污染排放较低，但仍属于化石能源，不能等同于零碳能源。\n特点：风光资源丰富但存在时空波动；水电具有调节价值但受水文及生态约束；地热和部分生物质利用需因地制宜；核能运行碳排放较低但安全、废物及成本管理重要。\n趋势：与储能、电网、需求响应及多能互补结合，推动电气化、技术降本和全生命周期环境管理。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":171,"sourceRange":{"startPage":171,"startY":413.43,"endPage":171,"endY":493.16},"sourceKind":"original","originalOrdinal":"5","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":10,"excerpts":[{"page":171,"src":"./assets/environment/env838-169e85a334f5010e-171.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=159"},{"title":"IEA：Global Energy Review 2026主要结论","url":"https://www.iea.org/reports/global-energy-review-2026/key-findings","accessedOn":"2026-11-09"},{"title":"中国的能源转型白皮书（英文全文）","url":"https://english.www.gov.cn/archive/whitepaper/202408/29/content_WS66d012e8c6d0868f4e8ea52e.html","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-e230a32065cb75ca","subject":"环境学导论","chapter":"第10章 能源与环境","originalChapter":"第10章 能源与环境","originalChapterNumber":10,"section":"第2节 课后习题","originalSection":"第2节 课后习题","category":"exercise","title":"简述我国面临的能源问题。","question":"简述我国面临的能源问题。","type":"简答题","answer":"①需求规模及增长压力：工业、建筑和交通等部门持续需要可靠能源服务。\n②结构压力：煤炭等传统能源仍有重要地位，产业深度脱碳难度大。\n③空间错配：资源、可再生能源潜力与负荷中心分布不一致，输送及消纳能力需要提升。\n④安全风险：部分油气依赖外部供应，国际市场、运输及极端天气影响系统韧性。\n⑤效率及环境约束：部分环节能效不足，污染、碳排放、水及土地约束需要统筹。\n⑥转型挑战：新型电力系统、储能、关键技术及公平转型仍需持续建设。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":171,"sourceRange":{"startPage":171,"startY":493.16,"endPage":171,"endY":572.54},"sourceKind":"original","originalOrdinal":"6","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":10,"excerpts":[{"page":171,"src":"./assets/environment/env838-e230a32065cb75ca-171.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=159"},{"title":"中国的能源转型白皮书（英文全文）","url":"https://english.www.gov.cn/archive/whitepaper/202408/29/content_WS66d012e8c6d0868f4e8ea52e.html","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-4ce11dd91f7e524d","subject":"环境学导论","chapter":"第10章 能源与环境","originalChapter":"第10章 能源与环境","originalChapterNumber":10,"section":"第2节 课后习题","originalSection":"第2节 课后习题","category":"exercise","title":"目前解决我国的能源问题有哪些措施?","question":"目前解决我国的能源问题有哪些措施?","type":"简答题","answer":"①节能优先：提升工业、建筑和交通能效，减少损失及不合理需求。\n②能源转型：扩大可再生能源和其他适宜低碳供给，推动电气化并有序降低高排放能源依赖。\n③系统建设：发展电网互联、储能、调峰和需求响应，提高新能源消纳与供能可靠性。\n④安全保障：多元供应、合理储备和风险预警，提升国内供应及基础设施韧性。\n⑤制度科技：完善市场、价格、标准、碳核算与创新，推动绿色产业发展。\n⑥生态约束：实施全生命周期环境管理，兼顾土地、水资源、生物多样性与转型中的民生。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":171,"sourceRange":{"startPage":171,"startY":572.54,"endPage":172,"endY":76.49},"sourceKind":"original","originalOrdinal":"7","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":10,"excerpts":[{"page":171,"src":"./assets/environment/env838-4ce11dd91f7e524d-171.webp"},{"page":172,"src":"./assets/environment/env838-4ce11dd91f7e524d-172.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=159"},{"title":"中国的能源转型白皮书（英文全文）","url":"https://english.www.gov.cn/archive/whitepaper/202408/29/content_WS66d012e8c6d0868f4e8ea52e.html","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-1f6f816278ec284b","subject":"环境学导论","chapter":"第10章 能源与环境","originalChapter":"第10章 能源与环境","originalChapterNumber":10,"section":"","originalSection":"","category":"supplement","title":"节能与减排","question":"节能与减排","type":"简答题","answer":"节能即能源消耗的节约，指在能源开采、运输、加工、转换、使用等各个环\n节减少损失和浪费，提高利用效率。\n一、交通节能减排\n中国交通节能措施主要包括建设光伏电站、推广绿色出行方式、优化运输组\n织结构、建设绿色交通基础设施、推广清洁低碳运输装备、引导绿色低碳出行方\n式、深化交通与能源融合发展等方面。\n（1）小汽车节能\n小汽车节能已在世界各国实施，具备较好的节能效果和环境效益。相关节能\n技术可减少燃料消耗和污染物产生，降低对环境的影响。\n（2）建设光伏电站\n在交通枢纽建设光伏电站，可为站内设施提供电力，利用清洁能源减少碳排\n放。\n（3）建设绿色交通基础设施，推广绿色低碳出行方式\n通过建设绿色公路、绿色港口等提高基础设施能效；通过优化运输组织结构，\n推广清洁低碳出行方式，减少对化石燃料的依赖，降低能源消耗。\n（4）推广清洁低碳运输装备\n鼓励使用电动车辆、混合动力车辆等清洁能源交通工具，减少传统燃油车辆\n的使用。\n二、家电节能减排\n节能家电是生活中广泛应用的节能技术产品，中国在家电节能减排方面采取\n系列措施，旨在通过技术创新、政策引导和市场机制推动家电行业绿色转型，提\n高能源利用效率，减少碳排放，促进可持续发展，助力实现碳达峰、碳中和目标。\n（1）推广高效家电\n中国鼓励使用各类高效家电，这类家电采用先进技术以降低能耗、提高能效。\n（2）技术创新\n在家电技术创新方面，中国推动环保材料和高效技术的应用，以提高能效并\n减少对环境的负面影响。\n（3）绿色智造升级 能效标准与标识\n在家电制造端推动绿色智造升级，实现智能制造与绿色制造结合，提高资源\n利用效率，减少废弃物排放。同时中国实施能效标识制度，为消费者提供产品能\n效信息，引导选择高能效产品，通过能效标准推动家电产品能效提升。\n（4）家电下乡和以旧换新政策\n通过实施相关政策，鼓励消费者更换能效更高的家电，促进家电行业升级换\n代，减少能源消耗和碳排放。\n三、能源的梯级利用\n能源的梯级利用包括按质用能和逐级多次利用两个方面。\n（1）按质用能\n按质用能是尽可能不使用高质能源去做低质能源可完成的工作。使用高温热\n源加热时需尽可能减少传热温差；仅有高温热源但仅需低温加热的场景，应先用\n高温热源发电，再利用发电装置的低温余热加热。\n（2）逐级多次利用\n逐级多次利用的原理是高质能源的能量不一定能在一个设备或过程中全部\n用完，能源使用过程中能质会逐渐下降，而每种设备都有经济合理的使用温度范\n围。当高质能源在一个装置中能质降至经济适用范围外时，可转至另一个适配较\n低能质的装置中使用，使能源利用率达到最高水平。\n四、 建筑节能\n建筑能耗有狭义和广义之分。狭义的建筑能耗指建筑物在使用过程中消耗的\n能量，包括供热、通风、照明等多类能耗。广义的建筑能耗除使用能耗外，还包\n括建筑材料生产、建筑物修建过程中的能耗，对应的建筑节能技术即绿色建筑。\n建筑节能包括三个方面。\n（1）建筑本体的节能\n建筑本体的节能一般涵盖建筑规划与设计、围护结构设计、建筑材料使用等\n方面，可采用节能建筑材料、节能设备及可再生能源利用系统等。国家要求房地\n产开发企业在销售房屋时，需向购买人明示房屋节能措施、保温工程保修期等信\n息，并对其真实性、准确性负责。\n（2）建筑系统的节能\n建筑系统节能一般包括空调采暖与制冷系统等设备的节能。新建或既有建筑\n节能改造，需按规定安装用热计量、室内温度调控及供热系统调控等装置。\n（3）能源管理\n通过规范管理实现合理用能，管控建筑物使用过程中供暖、通风、空调、照\n明等多方面的能耗。\n五、 余热利用\n余热是在一定经济技术条件下，能源利用设备中未被利用的多余、废弃能源，\n包含多种类型。余热的利用主要包括直接利用、间接利用、综合利用三个方面。\n（1）直接利用\n可利用余热预热空气以提高燃烧效率、节约燃料；利用余热干燥工业材料和\n部件；利用中低温余热生产热水和蒸汽，满足生产与生活需求；利用低温余热实\n现制冷。\n（2）间接利用\n可利用余热锅炉产生蒸汽推动汽轮发电机组发电；高温余热可作为燃气轮机\n的热源实现发电；低温余热可利用低沸点工质达到发电目的。\n（3）综合利用\n余热的综合利用是根据工业余热温度的高低采用不同利用方法，实现余热的\n梯级利用，达到 “热尽其用” 的目的。","source":"环导变动137718728584015123.1eae00877280d3e.pdf","sourceUrl":"https://drive.google.com/file/d/11CjvWmrS4poAVMmBBWnsJPRCmD1-JkRJ/view","version":"new","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":25,"sourceRange":{"startPage":25,"startY":472.98,"endPage":28,"endY":429.06},"sourceKind":"changes","originalOrdinal":"energy","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":10,"excerpts":[{"page":25,"src":"./assets/environment/env838-1f6f816278ec284b-25.webp"},{"page":26,"src":"./assets/environment/env838-1f6f816278ec284b-26.webp"},{"page":27,"src":"./assets/environment/env838-1f6f816278ec284b-27.webp"},{"page":28,"src":"./assets/environment/env838-1f6f816278ec284b-28.webp"}]},{"id":"env838-fe67be3088702a78","subject":"环境学导论","chapter":"第11章 自然资源的开发利用与环境","originalChapter":"第11章 自然资源的开发利用与环境","originalChapterNumber":11,"section":"第1节 自然资源的概述","originalSection":"第1节 自然资源的概述","category":"knowledge","title":"自然资源的定义","question":"自然资源的定义","type":"简答题","answer":"自然资源指的是，凡是自然物质经过人类的发现，被输入生产过\n程，或直接进入消耗过程，变成有用途的，或能给人以舒适感，从而\n产生经济价值以提高人类当前和未来福利的物质与能量的总称。联合\n国环境规划署对自然资源的定义：在一定时间和一定条件下，能产生\n经济效益，以提高人类当前和未来福利的自然因素和条件。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2025],"needsReview":false,"reviewReasons":[],"verified":false,"page":173,"sourceRange":{"startPage":173,"startY":186.26,"endPage":173,"endY":422.98},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":["2025( 名), 【重要程度:"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":11,"excerpts":[{"page":173,"src":"./assets/environment/env838-fe67be3088702a78-173.webp"}]},{"id":"env838-156695569bdc3584","subject":"环境学导论","chapter":"第11章 自然资源的开发利用与环境","originalChapter":"第11章 自然资源的开发利用与环境","originalChapterNumber":11,"section":"第1节 自然资源的概述","originalSection":"第1节 自然资源的概述","category":"knowledge","title":"自然资源分类","question":"自然资源分类","type":"简答题","answer":"自然资源分类方法有很多种，按属性分类可以分为生物资源、农\n业资源、森林资源、国土资源、气候资源、能源资源、水资源等几种\n生物资源是在目前社会经济技术条件下人类可以利用与可能利\n用的生物，包括动植物资源和微生物资源等。\n植物资源包括陆地、湖泊、海洋中的一般植物和一些珍稀濒危植\n物。\n动物资源包括陆地、湖泊、海洋中的一般动物和一些珍稀濒危动\n物。\n微生物资源是可以利用与可能利用的以菌类为主的微生物，所提\n供的物质，在人类生活和工业、农业、医药诸方面能发挥特殊的作用","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":1,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":173,"sourceRange":{"startPage":173,"startY":422.98,"endPage":174,"endY":160.66},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":["【重要程度: ★☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":11,"excerpts":[{"page":173,"src":"./assets/environment/env838-156695569bdc3584-173.webp"},{"page":174,"src":"./assets/environment/env838-156695569bdc3584-174.webp"}]},{"id":"env838-e7b1db62325836fe","subject":"环境学导论","chapter":"第11章 自然资源的开发利用与环境","originalChapter":"第11章 自然资源的开发利用与环境","originalChapterNumber":11,"section":"第2节 自然资源开发与环境问题","originalSection":"第2节 自然资源开发与环境问题","category":"knowledge","title":"开发带来的环境问题","question":"开发带来的环境问题","type":"简答题","answer":"[1]矿产资源开发对环境的不利影响\n矿产开发使环境地质发生变化，特别是地下开采会造成地面沉降\n甚至诱发地震。露天剥离、废石尾矿堆放，不但破坏地表植被，还会\n改变野生动物的栖息环境，造成水土流失，使自然灾害增多。同时，\n矿藏开发产生的废矿、尾矿会造成水体污染、土壤污染等。采矿产生\n的“三废”进入自然界后，可通过食物链逐级传递，最后影响到人体\n健康。\n[2]交通工程项目对环境的不利影响\n铁路和公路的交通运输建设，造成地面分割，使生物的栖息环境\n发生一定的变化，对陆地生态系统、地面径流产生影响。港口、码头\n的建设改变了水动力条件，会引起水生生态系统变化。此外，交通工\n程项目一般都会产生噪声、尾气等污染物，影响周围环境。\n[3]森林、草原资源开发对环境的不利影响\n森林、草原资源的不合理开发，破坏生态系统原有的平衡，使动\n植物的栖息环境发生变化，部分物种分布面积、数量急剧减少甚至消\n亡，生物承载力发生变化，严重时可能使整个生态系统类型发生改变\n，如生物多样性消失和物种灭绝，森林生态系统转化为草甸生态系统\n等。草原地区的不合理垦殖或过度放牧，可导致荒漠化和区域气候的\n变化等。\n[4]土地资源开发对环境的不利影响\n土地资源的开发是以农田、城镇等人工生态系统取代原生态系统\n为特征，其结果是多种自然植被和野生动物减少或消失，生物多样性\n降低，代之以结构单一、不完整的农田生态系统、家畜动物体系和城\n市生态系统。\n[5]旅游资源开发对环境的不利影响\n旅游资源的开发一般都在自然条件良好的区域进行。这类地区一\n旦开发，将修建一些人工设施，形成新的布局与结构，不仅改变原来\n的自然生态景观，而且改变生物的栖息环境。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":174,"sourceRange":{"startPage":174,"startY":202.27,"endPage":175,"endY":396.73},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":["【重要程度："],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":11,"excerpts":[{"page":174,"src":"./assets/environment/env838-e7b1db62325836fe-174.webp"},{"page":175,"src":"./assets/environment/env838-e7b1db62325836fe-175.webp"}]},{"id":"env838-7c5a6ad4f9349177","subject":"环境学导论","chapter":"第11章 自然资源的开发利用与环境","originalChapter":"第11章 自然资源的开发利用与环境","originalChapterNumber":11,"section":"第3节 森林资源的利用","originalSection":"第3节 森林资源的利用","category":"knowledge","title":"森林资源定义","question":"森林资源定义","type":"简答题","answer":"森林资源是林地及其所生长的森林有机体的总称。这里以林木资\n源为主，还包括林中和林下植物、野生动物、土壤微生物及其他自然\n环境因子等资源。林地包括乔木林地、疏林地、灌木林地、林中空地\n、采伐迹地、火烧迹地、苗圃地和国家规划宜林地。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":175,"sourceRange":{"startPage":175,"startY":440.43,"endPage":175,"endY":641.95},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":["【重要程度："],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":11,"additionalSources":[{"source":"环境学导论.pdf","page":177,"sourceRange":{"startPage":177,"startY":437.82,"endPage":177,"endY":635.37}}],"excerpts":[{"page":175,"src":"./assets/environment/env838-7c5a6ad4f9349177-175.webp"}]},{"id":"env838-47167a53b32da32f","subject":"环境学导论","chapter":"第11章 自然资源的开发利用与环境","originalChapter":"第11章 自然资源的开发利用与环境","originalChapterNumber":11,"section":"第3节 森林资源的利用","originalSection":"第3节 森林资源的利用","category":"knowledge","title":"森林资源的作用","question":"森林资源的作用","type":"简答题","answer":"森林资源是地球上最重要的资源之一，是生物多样化的基础，①\n它不仅能够为生产和生活提供多种宝贵的木材和原材料，还能够为人\n类经济生活提供多种物品，②更重要的是森林能够调节气候、保持水\n土、防止和减轻旱涝、风沙、冰雹等自然灾害；③另外，森林还有净\n化空气、消除噪声等功能，同时森林还是天然的动植物园，哺育着各\n种飞禽走兽和生长着多种珍贵林木和药材。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2000,2005,2009,2014],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":175,"sourceRange":{"startPage":175,"startY":641.95,"endPage":176,"endY":152.14},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":["2000(论、2005(论、2009(简、2014(简,【重要程度:"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":11,"additionalSources":[{"source":"环境学导论.pdf","page":177,"sourceRange":{"startPage":177,"startY":635.37,"endPage":178,"endY":161.0}}],"excerpts":[{"page":175,"src":"./assets/environment/env838-47167a53b32da32f-175.webp"},{"page":176,"src":"./assets/environment/env838-47167a53b32da32f-176.webp"}]},{"id":"env838-30f58c33746d9d03","subject":"环境学导论","chapter":"第11章 自然资源的开发利用与环境","originalChapter":"第11章 自然资源的开发利用与环境","originalChapterNumber":11,"section":"第4节 土地资源的利用","originalSection":"第4节 土地资源的利用","category":"knowledge","title":"土地资源利用存在的问题及处置措施","question":"土地资源利用存在的问题及处置措施","type":"简答题","answer":"一、存在的问题\n(1 )土地辽阔，总量巨大，但人均量偏低。我国耕地面积居世\n界第4位，林地居第8位，草地居第2位，但人均占有量很低。尽管我\n国已解决世界1/5人口的温饱问题，但也应注意到，我国非农业用地逐\n年增加，人均耕地逐年减少，土地的人口压力将愈来愈大。\n(2)地域跨度大、区域差异显著。我国地跨赤道带、热带、亚热\n带、暖温带、温带和寒温带，其中亚热带、暖温带、温带合计约占国\n土面积的71.7% 。从东到西又可分为湿润地区、半湿润地区、半干旱\n地区、干旱地区。\n(3 )难以开发利用土地比例较大。我国有相当一部分土地是难\n以开发利用的。在全国国土面积中，沙漠、戈壁、石质裸岩、冰川与\n永久积雪，加上居民点、道路占用的，不能供农林牧业利用的土地占\n全国土地面积的26.9% 。此外，还有一部分土地质量较差。\n(4)土地浪费严重。城市及农村人均用地均比我国目前规定人\n均用地控制指标高出近30% ，并且建设项目用地普遍征多用少，闲置\n浪费严重。\n(5 )土地污染严重。化肥、农药的使用，大量地残留在土壤中，\n导致了土壤板结、酸化、养分失调、保肥保水性能下降等问题。\n二、处置措施\n①建立健全土地法律法规体系，把土地工作纳入法制轨道；\n②节约集约利用土地：\n③深化土地管理制度改革；\n④保护土地生态环境，因地制宜，用养结合，防止土地污染。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":1,"pastExamYears":[2026],"needsReview":false,"reviewReasons":[],"verified":false,"page":178,"sourceRange":{"startPage":178,"startY":201.02,"endPage":179,"endY":214.82},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":["2026 (简, 【重要程度:★☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":11,"additionalSources":[{"source":"环境学导论.pdf","page":176,"sourceRange":{"startPage":176,"startY":194.83,"endPage":177,"endY":53.43}}],"excerpts":[{"page":178,"src":"./assets/environment/env838-30f58c33746d9d03-178.webp"},{"page":179,"src":"./assets/environment/env838-30f58c33746d9d03-179.webp"}]},{"id":"env838-dbdc28fc7fc2fb3b","subject":"环境学导论","chapter":"第11章 自然资源的开发利用与环境","originalChapter":"第11章 自然资源的开发利用与环境","originalChapterNumber":11,"section":"第5节 矿产资源的利用","originalSection":"第5节 矿产资源的利用","category":"knowledge","title":"矿产的定义","question":"矿产的定义","type":"简答题","answer":"矿物是指存在于地壳中的自然化合物，存在方式有固体、液体和\n气体，以固体居多，具有开采价值的矿物称为矿产。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":1,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":179,"sourceRange":{"startPage":179,"startY":258.74,"endPage":179,"endY":404.79},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":["【重要程度: ★☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":11,"excerpts":[{"page":179,"src":"./assets/environment/env838-dbdc28fc7fc2fb3b-179.webp"}]},{"id":"env838-2e33dd68e29a7708","subject":"环境学导论","chapter":"第11章 自然资源的开发利用与环境","originalChapter":"第11章 自然资源的开发利用与环境","originalChapterNumber":11,"section":"第5节 矿产资源的利用","originalSection":"第5节 矿产资源的利用","category":"knowledge","title":"采矿所引起的环境问题","question":"采矿所引起的环境问题","type":"简答题","answer":"(1)露天采矿造成的环境问题\n露天采场的采坑边帮稳定性差，采坑内无植被，容易造成滑坡、\n水土流失，干燥季节易造成尘土飞扬；排土场占用土地，岩石崩落，\n滑塌，造成水土流失，干燥季节尘土飞扬等。\n(2)地下开采造成的环境问题\n矿坑水排放造成地面塌陷，破坏建筑物，危害农田，影响河流和\n交通干线，使地表水漏失和地下水资源枯竭，影响植物生长，人畜饮\n水困难，引起井下流沙、溃决等；地下采空区造成地表开裂、沉降、\n塌陷。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":4,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":179,"sourceRange":{"startPage":179,"startY":404.79,"endPage":180,"endY":51.48},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":["【重要程度: ★★★★☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":11,"excerpts":[{"page":179,"src":"./assets/environment/env838-2e33dd68e29a7708-179.webp"},{"page":180,"src":"./assets/environment/env838-2e33dd68e29a7708-180.webp"}]},{"id":"env838-53bc76267d26df04","subject":"环境学导论","chapter":"第11章 自然资源的开发利用与环境","originalChapter":"第11章 自然资源的开发利用与环境","originalChapterNumber":11,"section":"第5节 矿产资源的利用","originalSection":"第5节 矿产资源的利用","category":"knowledge","title":"矿产利用过程中带来的环境问题","question":"矿产利用过程中带来的环境问题","type":"简答题","answer":"矿物资源在利用过程中主要带来的环境影响是工业“三度”的排\n放，下面以有色金属为例来具体说明。\n(1) 废气的排放\n有色金属工业废气，成分复杂，治理难度大。采、选工业废气主\n要为工业粉尘，有色金属冶炼废气主要含S、F、Cl等，有色金属加工\n废气含酸、碱和油雾等，有的还含有多种重金属，治理困难。\n(2) 废水的排放\n废水中含有害元素和重金属，大多未经充分处理直接排放，有些\n企业甚至是直接外排。许多矿山周边的河流、湖泊都受到严重污染，\n水资源、水环境受到严重破坏，部分矿山甚至出现饮用水源受到污染\n，出现饮水困难。周边农田土壤地球化学组成被严重破坏，导致作物\n减产、作物品质下降。生态环境整体质量下滑，部分矿山甚至由此出\n现地方病，恶性疾病发病率急剧上升。\n(3) 固废的排放\n一般来说，有色金属在矿石中的含量相对较低，生产1吨有色金\n属可产生上百吨甚至几百吨固体废物。固体废物不但占用土地资源，\n往往会占用农田、耕地，破坏植被，而且其淋滤水中有毒有害元素超\n标，对环境的破坏无异于是定时炸弹。大量的固体废物往往还是泥石\n流的物源，直接威胁人民生命财产安全。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":180,"sourceRange":{"startPage":180,"startY":51.48,"endPage":180,"endY":684.84},"sourceKind":"original","originalOrdinal":"3","sourceMetadata":["【重要程度："],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":11,"excerpts":[{"page":180,"src":"./assets/environment/env838-53bc76267d26df04-180.webp"}]},{"id":"env838-2100cc4abc75d829","subject":"环境学导论","chapter":"第11章 自然资源的开发利用与环境","originalChapter":"第11章 自然资源的开发利用与环境","originalChapterNumber":11,"section":"第5节 矿产资源的利用","originalSection":"第5节 矿产资源的利用","category":"knowledge","title":"治理矿产资源带来的环境问题应采取的措施","question":"治理矿产资源带来的环境问题应采取的措施","type":"简答题","answer":"(1)固体废弃物的治理和利用\n矿山尾矿、废石综合治理的关键问题是综合利用，使其数量得以\n减少，危害得到消除或控制，还能变废为宝，收到效益。因此，“资\n源化、减量化和无害化”是矿山尾矿、废石综合治理的原则。\n(2 )废水的治理\n采取强制措施对矿山和冶炼过程中产生的废水进行处理，实现达\n标排放。\n(3 )土地复垦\n土地复垦是指在生产建设过程中，对因挖损、塌陷、压占等造成\n破坏的土地采取整治措施，使其恢复到可供利用状态的活动。土地复\n垦对保护环境和缓解耕地供需矛盾非常必要。\n(4)法制建设\n加强法规和制度化建设，全面推进矿产资源开发利用的环境保护\n工作；制订矿山环境保护规划，科学、有序地开展矿山环境保护与治\n理；实施矿山环境恢复与土地复垦保证金制度；依靠科技进步，提高\n矿产资源开发利用的效率，贯彻“两种资源、两个市场”战略，减缓\n矿山环境压力。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":1,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":180,"sourceRange":{"startPage":180,"startY":684.84,"endPage":182,"endY":66.71},"sourceKind":"original","originalOrdinal":"4","sourceMetadata":["【重要程度:★☆☆☆☆)】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":11,"excerpts":[{"page":180,"src":"./assets/environment/env838-2100cc4abc75d829-180.webp"},{"page":181,"src":"./assets/environment/env838-2100cc4abc75d829-181.webp"},{"page":182,"src":"./assets/environment/env838-2100cc4abc75d829-182.webp"}]},{"id":"env838-d0ba2db363bdc4ed","subject":"环境学导论","chapter":"第11章 自然资源的开发利用与环境","originalChapter":"第11章 自然资源的开发利用与环境","originalChapterNumber":11,"section":"第6节 课后习题","originalSection":"第6节 课后习题","category":"exercise","title":"什么是自然资源，请列举出几种常见的自然资源。","question":"什么是自然资源，请列举出几种常见的自然资源。","type":"简答题","answer":"自然资源是自然界中能够直接或间接为人类利用、具有现实或潜在价值的物质、能量及环境条件。\n例子：水、土地、森林、草地、野生生物、矿产，以及太阳能、风能等。\n可按更新特征区分可再生、不可再生及持续可利用的自然能流等；也可按资源类型、用途和开发状态分类。\n“自然存在”与“可以无限利用”不同。可再生资源的利用若超过更新能力，同样会衰退甚至丧失；资源价值也受技术、需求和生态约束影响。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":182,"sourceRange":{"startPage":182,"startY":104.82,"endPage":182,"endY":181.4},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":11,"excerpts":[{"page":182,"src":"./assets/environment/env838-d0ba2db363bdc4ed-182.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=172"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-403e55e2178c41e4","subject":"环境学导论","chapter":"第11章 自然资源的开发利用与环境","originalChapter":"第11章 自然资源的开发利用与环境","originalChapterNumber":11,"section":"第6节 课后习题","originalSection":"第6节 课后习题","category":"exercise","title":"简述对环境影响较大的自然资源的特征。","question":"简述对环境影响较大的自然资源的特征。","type":"简答题","answer":"与环境影响密切相关的资源特征可从以下方面说明：\n①有限性：储量、质量或更新速度有限，过度利用会产生资源与生态压力。\n②区域性：空间分布不均，开发容易形成区域集中及跨区域输送影响。\n③整体性：水、土、生物等资源相互联系，改变一种资源会影响其他要素。\n④多用途与竞争性：同一土地、水体可有生产、生活和生态等用途，分配失当引发矛盾。\n⑤可更新性差异：矿产需重视节约和替代，森林、水土等需维持再生与循环过程。\n因此应评价开发强度、累积影响及生态代价，而不只评价可采量。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":182,"sourceRange":{"startPage":182,"startY":181.4,"endPage":182,"endY":259.03},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":11,"excerpts":[{"page":182,"src":"./assets/environment/env838-403e55e2178c41e4-182.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=172"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-3ed4569cb50a4a79","subject":"环境学导论","chapter":"第11章 自然资源的开发利用与环境","originalChapter":"第11章 自然资源的开发利用与环境","originalChapterNumber":11,"section":"第6节 课后习题","originalSection":"第6节 课后习题","category":"exercise","title":"简述我国森林资源的破坏情况以及保护措施。","question":"简述我国森林资源的破坏情况以及保护措施。","type":"简答题","answer":"破坏及压力：不合理采伐、占地和生境破碎化，火灾、病虫害及气候压力等，可能降低森林质量、生物多样性、水源涵养与水土保持功能。\n认识现状：我国森林恢复和保护已取得进展，不能把历史“持续锐减”的描述直接当作全部当前趋势；应同时关注面积、质量、结构和连通性。\n措施：保护天然林和重要生境，控制非法采伐与不合理占用；推进科学营林和近自然恢复，优先适地适树与乡土物种；完善防火、有害生物防控和监测；通过保护地、生态补偿及社区参与协调保护与生计。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":182,"sourceRange":{"startPage":182,"startY":259.03,"endPage":182,"endY":338.37},"sourceKind":"original","originalOrdinal":"3","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":11,"excerpts":[{"page":182,"src":"./assets/environment/env838-3ed4569cb50a4a79-182.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=172"},{"title":"生态环境部：2024中国生态环境状况公报","url":"https://www.mee.gov.cn/ywgz/sthjjcgl/hjzljcypj/202506/t20250605_1120773.shtml","accessedOn":"2026-11-09"},{"title":"中国生物多样性保护战略与行动计划（2023—2030年）发布说明","url":"https://www.mee.gov.cn/xxgk/hjyw/202401/t20240118_1064111.shtml","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-a528fad46069e1b0","subject":"环境学导论","chapter":"第11章 自然资源的开发利用与环境","originalChapter":"第11章 自然资源的开发利用与环境","originalChapterNumber":11,"section":"第6节 课后习题","originalSection":"第6节 课后习题","category":"exercise","title":"简述我国土地资源的破坏情况以及保护措施。","question":"简述我国土地资源的破坏情况以及保护措施。","type":"简答题","answer":"主要问题：①部分区域耕地被占及破碎化，人地矛盾突出；②水土流失、荒漠化和盐渍化等退化；③土壤污染、养分与有机质下降；④建设用地粗放低效及不合理开发，损害生态空间。\n保护措施：严格用途管制与耕地、生态空间保护，推进节约集约利用；科学安排城镇和产业布局，盘活存量土地；实施水土保持、合理排灌和保护性耕作；控制污染源，对受污染土地分类管控和修复；建立调查监测、责任及公众监督机制。\n应区分不同地区的限制条件，避免用同一工程模式处理全部退化土地。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":182,"sourceRange":{"startPage":182,"startY":338.37,"endPage":182,"endY":417.95},"sourceKind":"original","originalOrdinal":"4","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":11,"excerpts":[{"page":182,"src":"./assets/environment/env838-a528fad46069e1b0-182.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=172"},{"title":"生态环境部：土壤污染风险管控与绿色低碳修复解读","url":"https://www.mee.gov.cn/ywdt/zbft/202405/t20240506_1072343.shtml","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-d90b2903058c2d3e","subject":"环境学导论","chapter":"第11章 自然资源的开发利用与环境","originalChapter":"第11章 自然资源的开发利用与环境","originalChapterNumber":11,"section":"第6节 课后习题","originalSection":"第6节 课后习题","category":"exercise","title":"简述我国矿产资源开发对环境的影响或者破坏。","question":"简述我国矿产资源开发对环境的影响或者破坏。","type":"简答题","answer":"①占地与生态：露天采场、道路、排土场及尾矿设施破坏植被、生境和景观，并可能加剧水土流失。\n②地质与水文：地下开采可引发地面沉降、地裂缝及含水层扰动；疏干和排水影响水资源。\n③污染：粉尘、矿坑水、选冶废水、尾矿及废石可能释放金属、酸性排水或其他有害物。\n④利用阶段：冶炼和加工消耗能源，产生废气、废水、固废及碳排放。\n防治应贯穿勘查、开采、选冶、闭矿全过程，实施减扰动、清洁生产、废物安全管理、生态修复与长期监测。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":182,"sourceRange":{"startPage":182,"startY":417.95,"endPage":183,"endY":44.98},"sourceKind":"original","originalOrdinal":"5","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":11,"excerpts":[{"page":182,"src":"./assets/environment/env838-d90b2903058c2d3e-182.webp"},{"page":183,"src":"./assets/environment/env838-d90b2903058c2d3e-183.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=172"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-e3dfc86b87994c67","subject":"环境学导论","chapter":"第12章 环境污染与公众健康","originalChapter":"第12章 战争与环境","originalChapterNumber":12,"section":"第1节 战争对环境的影响","originalSection":"第1节 战争对环境的影响","category":"knowledge","title":"古代战争的危害","question":"古代战争的危害","type":"简答题","answer":"(1 )对人类的危害\n古代战争对人类的危害，最主要表现在交战双方在博弈过程中而\n伤亡的士兵，此外，战争还间接影响人类的发展，战后由于尸体、物\n资等的堆积腐化后大量细菌的滋生，导致疾病的蔓延等，直接或间接\n影响人类的生活和健康。\n(2)对社会的危害\n古代战争主要依靠人力的支撑，部队的壮大需要大量的士兵，士\n兵源自百姓，从而有“抓壮丁”这样的强制征兵手段。壮丁入伍导致\n务农劳动力减少，从而农作物产量也随之而下降。由于军费的需求，\n需要征收大量的钱粮物资，导致百姓的艰苦生活，社会发展也受到极\n大影响。\n(3 ) 对自然的破坏\n古代战争崇尚的是“天时、地利、人和”，因此常常会利用自然\n界的气象因素和地理因素作为战争的制胜之道。许多大型战役都以火\n攻作为制胜之道，破坏敌方的生态环境有时也成为赢得战争的手段，\n或者作为对战败者的惩罚。这种破坏没有对生态环境系统构成深层的\n、大规模的、系统性的破坏，因而遭受破坏的环境经过较短时间的休\n养生息、或经过简单的人工补救就可以恢复。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"removed","importance":0,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":184,"sourceRange":{"startPage":184,"startY":83.1,"endPage":184,"endY":698.77},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":["【重要程度: ☆☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":12,"versionReason":"变动PDF第1、28页明确整章替换。","excerpts":[{"page":184,"src":"./assets/environment/env838-e3dfc86b87994c67-184.webp"}]},{"id":"env838-2cb66b6abd606d86","subject":"环境学导论","chapter":"第12章 环境污染与公众健康","originalChapter":"第12章 战争与环境","originalChapterNumber":12,"section":"第1节 战争对环境的影响","originalSection":"第1节 战争对环境的影响","category":"knowledge","title":"现代战争的环境污染","question":"现代战争的环境污染","type":"简答题","answer":"(1 ) 化学污染\n军用装备往往会添注一些对环境危害极大的化学物质，以提高武\n器的杀伤力和燃料的利用效率。这些化学物质有的是高毒性化合物，\n具有致癌作用，长期接触会引起肝脏损害和痤疮样皮炎，有的会对臭\n氢层造成破坏、是引起臭氧层空洞的因素之一，等等。\n(2 )放射性污染\n现代战争中使用的贫铀弹会造成严重的放射性污染。虽然贫铀的\n放射性强度不到天然铀的一半，但放射性毕竟存在，长期接触对健康\n也会有影响。贫铀粒子可污染土壤达10年之久，通过食物链、皮肤吸\n收特别是呼吸系统进入人体形成内照射，对人体健康造成巨大影响。\n(3 ) 生物污染\n炭疽杆菌、波特淋菌毒素、沙林毒气、芥子气和VX神经毒剂等生\n物武器试剂可通过多种方式进行传播，最常见的就是在空气中随风飘\n散，也可能进入饮用水水源，让人防不胜防。\n(4 )噪声污染\n世界上大多数国家规定的噪声环境卫生标准为40dB，超过40dB\n的噪声被认为是有害噪声。在现代战争中，各种飞机、坦克、舰艇等\n的投入使用，作战平台产生的噪声，再加上炸弹的爆炸声、枪弹声等\n，远远超过这个标准。\n(5 )电磁辐射污染\n在高科技的条件下，现代战争是立体战争、信息战争，交战双方\n都会千方百计使用高强度、宽频率电磁波去干扰、摧毁对方的雷达、\n声呐以及其他通讯设备。强烈的电磁辐射污染，引起对方人员身体器\n官不适，诱发各种疾病，严重时能引起致畸、致突变、致癌效应，直\n接危害健康和生命。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"removed","importance":1,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":184,"sourceRange":{"startPage":184,"startY":698.77,"endPage":186,"endY":67.94},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":["【重要程度: ★☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":12,"versionReason":"变动PDF第1、28页明确整章替换。","excerpts":[{"page":184,"src":"./assets/environment/env838-2cb66b6abd606d86-184.webp"},{"page":185,"src":"./assets/environment/env838-2cb66b6abd606d86-185.webp"},{"page":186,"src":"./assets/environment/env838-2cb66b6abd606d86-186.webp"}]},{"id":"env838-d1c91cd54e08044b","subject":"环境学导论","chapter":"第12章 环境污染与公众健康","originalChapter":"第12章 战争与环境","originalChapterNumber":12,"section":"第1节 战争对环境的影响","originalSection":"第1节 战争对环境的影响","category":"knowledge","title":"现代战争的环境破坏","question":"现代战争的环境破坏","type":"简答题","answer":"(1 ) 对资源的消耗\n据英国伦敦战略研究所统计，在一些主要战争中，仅消耗的金属\n资源就相当惊人：第一次世界大战为5000 万余吨，第二次世界大战则\n高达1亿吨。\n(2)对自然资源的破坏\n第二次世界大战中，各种爆炸物掀起的良田表层土壤达3.5亿立\n方米，造成许多良田贫瘠，有些地方成为沙漠和砾石戈壁，各种大型\n动物死伤数量也极为惊人。大量坦克纵横行驶在内陆沙漠，破坏了已\n固化的沙漠表层，使风沙飞扬的天气大大增加。\n(3 ) 对环境的破坏\n战争造成的大气污染尤为严重，同时也会带来海洋污染和周边环\n境的核污染。在1989年的海湾战争中，石油燃烧释放的烟雾影响了亚\n洲季风，导致印度和东南亚干旱；沉积在海湾地区的250万吨硫黄和\n氧化氮，给当地农业造成灾难性的危害；使珠穆朗玛峰地区降黑雪，\n污染物甚至漂浮到南极。\n(4 )对生态系统的破坏\n例如越南战争已经过去近40年，但本来生长在这些土地上的树木\n却毫无自然再生的迹象。现在，遭受影响的土地杂草丛生，动物也很\n贫乏，同战前情景相比面目全非。落叶剂的影响不只是自然环境遭到\n破坏，而且对人员的伤害也很惨重。在越南，出生了大量连体儿和畸\n形儿。\n(5 )改变地质结构\n轰炸会对地壳的稳定性产生强烈的影响，地下爆炸产生的震动比\n地表爆炸要强烈得多，更容易诱发地震。\n(6 )环境后遗症\n战争需要运输大量物资，而战争结束后剩下的物资大部分无法运\n回，或者是参战国不愿意花费大量资金去处理。这些物资多是有毒、\n有害、易燃易爆的物品，直接遗弃于战场上，会造成严重的环境污染\n和危害。由战争造成的环境破坏加快了水土流失，严重影响生态系统","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"removed","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":186,"sourceRange":{"startPage":186,"startY":67.94,"endPage":187,"endY":315.06},"sourceKind":"original","originalOrdinal":"3","sourceMetadata":["【重要程度："],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":12,"versionReason":"变动PDF第1、28页明确整章替换。","excerpts":[{"page":186,"src":"./assets/environment/env838-d1c91cd54e08044b-186.webp"},{"page":187,"src":"./assets/environment/env838-d1c91cd54e08044b-187.webp"}]},{"id":"env838-3f24fa7b0856991b","subject":"环境学导论","chapter":"第12章 环境污染与公众健康","originalChapter":"第12章 战争与环境","originalChapterNumber":12,"section":"第2节 战争与环境伦理","originalSection":"第2节 战争与环境伦理","category":"knowledge","title":"战争与环境的关系","question":"战争与环境的关系","type":"简答题","answer":"战争与环境的关系，实质是人与环境的关系，是人与自然的关系\n。人类的自然观影响战争观。从征服自然到敬畏生命，人类开始认识\n大自然的价值和权利，人类的自然观也从人类中心主义向生态中心主\n义转变。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"removed","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":187,"sourceRange":{"startPage":187,"startY":356.67,"endPage":188,"endY":75.88},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":["【重要程度： ☆"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":12,"versionReason":"变动PDF第1、28页明确整章替换。","excerpts":[{"page":187,"src":"./assets/environment/env838-3f24fa7b0856991b-187.webp"},{"page":188,"src":"./assets/environment/env838-3f24fa7b0856991b-188.webp"}]},{"id":"env838-af9618dfaaaf006a","subject":"环境学导论","chapter":"第12章 环境污染与公众健康","originalChapter":"第12章 战争与环境","originalChapterNumber":12,"section":"第3节 课后习题","originalSection":"第3节 课后习题","category":"exercise","title":"战争对环境的破坏有哪些?","question":"战争对环境的破坏有哪些?","type":"简答题","answer":"①直接破坏：爆炸、火灾、军事工程和车辆活动损毁植被、生境、土壤与地形。\n②污染：弹药、燃料、废弃装备和受损工业设施可污染空气、地表水、地下水及土壤。\n③基础设施损坏：供水、排污、供电和废物处理设施中断，放大公共卫生和环境风险。\n④长期影响：未爆弹药、废墟、有害物残留与治理能力下降，延缓生态恢复及安全返乡。\n⑤资源压力：人口迁移与生计中断可能增加局地资源消耗。\n本题属于旧版保留章节，参考答案按环境影响的直接、间接及长期路径组织。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"removed","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":188,"sourceRange":{"startPage":188,"startY":114.36,"endPage":188,"endY":189.78},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":12,"versionReason":"变动PDF第1、28页明确整章替换。","excerpts":[{"page":188,"src":"./assets/environment/env838-af9618dfaaaf006a-188.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=183"},{"title":"UNEP：减少战争和武装冲突的环境影响","url":"https://www.unep.org/en/news-and-stories/statements/curbing-negative-environmental-impacts-war-and-armed-conflict","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-4e437b4446aeb75e","subject":"环境学导论","chapter":"第12章 环境污染与公众健康","originalChapter":"第12章 战争与环境","originalChapterNumber":12,"section":"第3节 课后习题","originalSection":"第3节 课后习题","category":"exercise","title":"军事基地和军事演习的污染有哪些?","question":"军事基地和军事演习的污染有哪些?","type":"简答题","answer":"军事基地的日常运行可产生燃料及化学品泄漏、车辆和飞机排放、生活污水与固废、噪声及危险废物；弹药生产、储存和报废设施还具有事故风险。\n军事演习可造成：①爆破、射击与装备运行的噪声、扬尘和废气；②弹药成分及残骸进入土壤水体；③车辆碾压、训练工程和火灾损伤植被生境；④水土流失及未爆弹药遗留风险。\n管理包括合理选址和环境评估，划定敏感区，规范物料、废物及污染设施管理，开展事故预防、监测、场地调查和修复。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"removed","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":188,"sourceRange":{"startPage":188,"startY":189.78,"endPage":188,"endY":265.69},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":12,"versionReason":"变动PDF第1、28页明确整章替换。","excerpts":[{"page":188,"src":"./assets/environment/env838-4e437b4446aeb75e-188.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=183"},{"title":"UNEP：减少战争和武装冲突的环境影响","url":"https://www.unep.org/en/news-and-stories/statements/curbing-negative-environmental-impacts-war-and-armed-conflict","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-33d9b9062c42191e","subject":"环境学导论","chapter":"第12章 环境污染与公众健康","originalChapter":"第12章 战争与环境","originalChapterNumber":12,"section":"第3节 课后习题","originalSection":"第3节 课后习题","category":"exercise","title":"美国“9·11”恐怖袭击事件的根源在哪里?","question":"美国“9·11”恐怖袭击事件的根源在哪里?","type":"简答题","answer":"本题为开放讨论题，可区分事件直接原因、组织背景和制度性失误。\n①直接原因：基地组织及相关策划者筹划并实施恐怖袭击，以袭击平民和民用设施达到其极端政治目的。\n②组织背景：极端意识形态、跨国招募训练及资金网络，以及阿富汗等地的庇护条件，为计划实施提供支持。\n③国际环境：地区冲突及地缘政治矛盾构成背景，但背景解释不构成对袭击的正当化。\n④防范失误：情报共享、威胁识别和航空安全等存在问题，影响预防能力。\n以上据9·11调查委员会报告归纳，不能将袭击归结为单一宗教、民族或未经证实的阴谋。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"removed","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":188,"sourceRange":{"startPage":188,"startY":265.69,"endPage":188,"endY":342.66},"sourceKind":"original","originalOrdinal":"3","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":12,"versionReason":"变动PDF第1、28页明确整章替换。","excerpts":[{"page":188,"src":"./assets/environment/env838-33d9b9062c42191e-188.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=183"},{"title":"美国9·11调查委员会报告第五章","url":"https://911commission.gov/report/911Report_Ch5.htm","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-12c1dd425a2a3db6","subject":"环境学导论","chapter":"第12章 环境污染与公众健康","originalChapter":"第12章 战争与环境","originalChapterNumber":12,"section":"第3节 课后习题","originalSection":"第3节 课后习题","category":"exercise","title":"讨论现代战争对人类、社会、经济和环境的破坏。","question":"讨论现代战争对人类、社会、经济和环境的破坏。","type":"简答题","answer":"人类层面：伤亡、残疾、精神创伤、疾病与流离失所。\n社会层面：教育、医疗、供水和治理服务中断，社区解体与社会信任受损，脆弱人群负担加重。\n经济层面：资产与基础设施损毁，生产和贸易受阻，资源投入转向战争及重建，形成长期财政负担。\n环境层面：爆炸、火灾、污染物及废墟造成水、土、气污染和生态破坏；环境监测与执法能力下降又加剧风险。\n各方面相互作用：污染与资源短缺影响健康和生计，重建若缺乏环境管理可能形成新的锁定效应。应加强冲突中的环境保护及战后调查修复。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"removed","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":188,"sourceRange":{"startPage":188,"startY":342.66,"endPage":189,"endY":49.86},"sourceKind":"original","originalOrdinal":"4","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":12,"versionReason":"变动PDF第1、28页明确整章替换。","excerpts":[{"page":188,"src":"./assets/environment/env838-12c1dd425a2a3db6-188.webp"},{"page":189,"src":"./assets/environment/env838-12c1dd425a2a3db6-189.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=183"},{"title":"UNEP：减少战争和武装冲突的环境影响","url":"https://www.unep.org/en/news-and-stories/statements/curbing-negative-environmental-impacts-war-and-armed-conflict","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-1f5ebb42a5cf7e18","subject":"环境学导论","chapter":"第12章 环境污染与公众健康","originalChapter":"第12章 战争与环境","originalChapterNumber":12,"section":"第4节 环境污染的健康风险评价方法","originalSection":"第4节 环境污染的健康风险评价方法","category":"supplement","title":"环境、污染、健康、风险、评价的相关概念","question":"环境、污染、健康、风险、评价的相关概念","type":"简答题","answer":"环境健康的定义：\n欧洲《环境与健康宪章》最早将环境健康定义为 “由环境要素所决定的人\n类健康和疾病”。\n韩国《环境健康法》规定，环境健康是指调查、评估、预防和控制环境污染\n以及有毒化学品（“环境风险因子”）对公众健康和生态系统的影响。\n健康风险的定义：\n健康风险是指在一定条件下，环境中有害因素导致暴露人群中出现不良健康\n效应（伤病、死亡）的概率。\n环境健康风险的定义：\n环境健康风险指环境污染（生物、化学和物理）对公众健康造成不良影响的\n可能性，对这种可能性进行定性或定量的估计称为环境健康风险评估。\n也有学者将其定义为：由自发的自然原因和人类活动引起的，通过环境介质\n传播对人群健康造成危害或者累积性不良影响的概率及其后果。\n环境健康风险评价的定义：\n环境健康风险评价是将环境污染与人体健康相关联的评价方法，主要通过估\n算有害因子对人体产生不良影响的概率，评价暴露于该因子下人体健康所受的影\n响；也指从定性和定量两个方面，对长期累积的化学物质导致的人体健康不良影\n响的轻重程度和发生概率进行估计和评定的过程。","source":"环导变动137718728584015123.1eae00877280d3e.pdf","sourceUrl":"https://drive.google.com/file/d/11CjvWmrS4poAVMmBBWnsJPRCmD1-JkRJ/view","version":"new","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":28,"sourceRange":{"startPage":28,"startY":705.09,"endPage":29,"endY":525.06},"sourceKind":"changes","originalOrdinal":"1","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":12,"excerpts":[{"page":28,"src":"./assets/environment/env838-1f5ebb42a5cf7e18-28.webp"},{"page":29,"src":"./assets/environment/env838-1f5ebb42a5cf7e18-29.webp"}]},{"id":"env838-ebbff09e8aa93af2","subject":"环境学导论","chapter":"第12章 环境污染与公众健康","originalChapter":"第12章 战争与环境","originalChapterNumber":12,"section":"第4节 环境污染的健康风险评价方法","originalSection":"第4节 环境污染的健康风险评价方法","category":"supplement","title":"健康风险评价常见方法","question":"健康风险评价常见方法","type":"简答题","answer":"目前，健康风险评价常见方法有 NAS 四步法、MES 法、生命周期分析法\n等。\n一、四步法\n主要包含四个核心环节：\n① 暴露评估：确定是否存在暴露及暴露的程度；\n② 危害识别：确定是否发生健康危害及不良健康效应的类型和特点；\n③ 剂量 - 效应（或反应）关系评估：在危害识别的基础上，定量评价其危\n害；\n④ 风险特征分析：估计可能产生健康危害的程度。\n该方法适用于污染物质对人体长期慢性危害的风险评估，不适用于环境污染\n突发事故的风险评估。\n二、MES 法\nMES 法是通过特定危害事件的后果（S）、人体暴露于危险环境的频繁程度\n及时间（E）和控制措施状态（M）三个要素衡量健康风险程度的方法，计算公\n式为：\nR = L·S = M·E·S\n其中 L 为特定危害性事件发生的可能性，主要取决于 E 和 S 两个因素。\n该方法通过对暴露等级、控制措施等级、事故后果等级分别划分级别并赋值，\n计算危害发生的风险值，再根据风险值大小评价风险发生的可能性。\n三、生命周期分析\n生命周期分析（LCA）指对产品系统的环境行为从原材料开采到废弃物的最\n终处置进行全面的环境影响分析和评价，是重要的决策和可持续发展支持工具，\n被纳入 ISO 14000 环境管理标准体系。\n国际环境毒理学和化学学会将 LCA 定义为对某种产品系统或行为相关的\n环境负荷进行量化评价的过程。它首先辨识和量化所使用的物质、能量和对环境\n的排放，再评价这些使用和排放的影响。评价覆盖产品或行为的整个生命周期，\n包括原材料采集加工、产品制造、营销、使用、回收、维护、循环利用、最终处\n理及所有相关运输过程。\n利用污染物生命周期分析方法，通过归趋分析 - 效应分析 - 危害分析，可\n研究排放物通过不同介质和途径对人体健康的影响，定量计算污染物对人体健康\n的危害。\n四、 风险表征方法\n常用的健康风险主要从致癌风险和非致癌风险两个角度进行表征。","source":"环导变动137718728584015123.1eae00877280d3e.pdf","sourceUrl":"https://drive.google.com/file/d/11CjvWmrS4poAVMmBBWnsJPRCmD1-JkRJ/view","version":"new","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["健康风险评价MES说明称L取决于E和S，与所列公式M·E·S不一致；原文保留待核对。"],"verified":false,"page":29,"sourceRange":{"startPage":29,"startY":525.06,"endPage":31,"endY":78.97},"sourceKind":"changes","originalOrdinal":"2","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":12,"excerpts":[{"page":29,"src":"./assets/environment/env838-ebbff09e8aa93af2-29.webp"},{"page":30,"src":"./assets/environment/env838-ebbff09e8aa93af2-30.webp"},{"page":31,"src":"./assets/environment/env838-ebbff09e8aa93af2-31.webp"}]},{"id":"env838-754eb51396919242","subject":"环境学导论","chapter":"第13章 生态学基础","originalChapter":"第13章 生态学基础","originalChapterNumber":13,"section":"第1节 生态学的含义及其发展","originalSection":"第1节 生态学的含义及其发展","category":"knowledge","title":"生态学的定义","question":"生态学的定义","type":"简答题","answer":"生态学是研究生物及其与环境之间相互关系的科学。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":1,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":190,"sourceRange":{"startPage":190,"startY":342.41,"endPage":190,"endY":454.7},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":["【重要程度:★☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":13,"excerpts":[{"page":190,"src":"./assets/environment/env838-754eb51396919242-190.webp"}]},{"id":"env838-43fac7b8462c2e05","subject":"环境学导论","chapter":"第13章 生态学基础","originalChapter":"第13章 生态学基础","originalChapterNumber":13,"section":"第1节 生态学的含义及其发展","originalSection":"第1节 生态学的含义及其发展","category":"knowledge","title":"生态学的发展历史和发展趋势","question":"生态学的发展历史和发展趋势","type":"简答题","answer":"生态学是人们在认识自然界的过程中逐渐发展起来的。生态学的\n发展大致可以分为4个时期：萌芽时期、建立时期、巩固时期和现代\n生态学时期。\n(1) 萌芽时期\n16世纪前是生态学的萌芽时期。人类在和自然的斗争中，认识到\n环境和气候对生物生长的影响，以及生物和生物之间关系的重要性。\n也有学者注意到气候、土壤与植被生长与病害的关系，同时还注意到\n不同地区植物群落的差异。这些都孕育着朴素的生态学思想。\n(2) 生态学的建立时期\n17~19世纪末是生态学的建立时期。这一时期，生态学作为一门\n学科井始出现，有科学家在1670年发表的低气压对动物影响的试验，\n标志着动物生理生态学的开端。后续也有人分析了人口增长与食物生\n产的关系、植物分布与环境条件的关系。达尔文出版了著名的《物种\n起源》，提出生物进化论、对生物与环境的关系作了深入探讨。1866\n年，H. Haeckel首次提出生态学定义，标志着生态学的诞生。到19世纪\n朱，生态学已正式成为一门独立的学科。\n(3)生态学的巩固时期\n20世纪初至20世纪50年代是生态学的巩固时期。这一时期，植物\n和动物生态学得到长足的发展，各种著作和教材相继出版。在动物生\n态学方面，20世纪初关于生理生态学、动物行为学和动物群落学等的\n研究cal得较大进展。20世纪20~50年代，开始了种群研究，并将统计\n学引入生态学，这一时期的另一重要特征是生态学从描述、解释走向\n机理研究。\n(4)现代生态学时期\n进入20世纪60年代，生态学得到快速发展。一是因为生态学自身\n的学科积累已到了一定程度，形成了自己独特的理论体系和方法论；\n二是高精度的分析测试技术、电子计算机技术、遥感技术和地理信息\n系统技术的发展，为现代生态学的发展提供了物质基础和技术条件；\n三是社会的需求。由于工业的高度发展和人口的大量增长，出现了许\n多全球性的人口、环境、资源、能源等问题。这些问题的解决都需要\n借助生态学理论，因而生态学引起社会各界的兴趣，从而刺激了现代\n生态学的发展。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":0,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":190,"sourceRange":{"startPage":190,"startY":454.7,"endPage":192,"endY":60.63},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":["【重要程度:☆☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":13,"excerpts":[{"page":190,"src":"./assets/environment/env838-43fac7b8462c2e05-190.webp"},{"page":191,"src":"./assets/environment/env838-43fac7b8462c2e05-191.webp"},{"page":192,"src":"./assets/environment/env838-43fac7b8462c2e05-192.webp"}]},{"id":"env838-1a1f94ebc3ab20f9","subject":"环境学导论","chapter":"第13章 生态学基础","originalChapter":"第13章 生态学基础","originalChapterNumber":13,"section":"第1节 生态学的含义及其发展","originalSection":"第1节 生态学的含义及其发展","category":"knowledge","title":"现代生态学的发展特点和趋势","question":"现代生态学的发展特点和趋势","type":"简答题","answer":"①研究层面向更宏观与更微观的方向发展。\n传统的生态学以个体、种群、群落为主要研究对象，现代生态学\n已发展到生态系统、景观和全球水平。现代生态学在向宏观方向发展\n的同时，在微观方向也取得不少进展，20世纪末分子生态学的产生是\n最重要的标志之一。分子生态学是以分子遗传为标志研究和解决生态\n学和进化问题的学科。用分子生态学的方法来研究生态学的现象，大\n大提高了生态学的科学性。\n②研究手段不断更新。\n传统生态学侧重对研究对象的描述，现代生态学已广泛应用野外\n自记电子仪器、同位素示踪、稳定同位素、遥感与地理信息系统、生\n态建模等技术，这些技术支持了现代生态学的发展。\n③应用生态学迅速发展。\n自20世纪60年代以来，人口危机、能源危机、资源危机、环境危\n机等日益严重，而生态学被认为是解决这些危机的科学基础。生态学\n与人类环境问题的结合成为20世纪70年代后生态学的最重要研究领\n域，与人类生存密切相关的许多环境问题都成为现代生态学研究的热\n点问题，生态学越来越融合于环境科学中。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":192,"sourceRange":{"startPage":192,"startY":60.63,"endPage":192,"endY":631.66},"sourceKind":"original","originalOrdinal":"3","sourceMetadata":["【重要程度："],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":13,"excerpts":[{"page":192,"src":"./assets/environment/env838-1a1f94ebc3ab20f9-192.webp"}]},{"id":"env838-80c4be8c6164ae82","subject":"环境学导论","chapter":"第13章 生态学基础","originalChapter":"第13章 生态学基础","originalChapterNumber":13,"section":"第1节 生态学的含义及其发展","originalSection":"第1节 生态学的含义及其发展","category":"knowledge","title":"生态学的研究内容","question":"生态学的研究内容","type":"简答题","answer":"现代生态学具有明显的时代特色，除保持原有的研究领域外，还\n涌现出一批新的研究方向和热点问题，包括全球变化、可持续发展、\n生物多样性、湿地生态学、景观生态学、脆弱与退化生态学、恢复与\n重建及保护生态学、生态系统健康、生态工程与生态设计、生态经济\n与人文生态学等新兴研究领域。这些研究领域是以全球变化为起点和\n主题，以恢复重建为内容和手段，以可持续发展为目标相互交织在一\n起而构成的一个“生态学三角形研究框架”。其他研究热点大多是围\n绕这三个轴心而展开的。\n(1) 全球变化\n全球变化研究主要集中在以下几个方面：①全球变化的科学性问\n题：②全球变化的幅度及其生态效应的预测研究；③温室效应气体释\n放机理研究：④生态系统碳库与汇估测；⑤全球变化高新技术产业的\n开发与利用研究；⑥全球变化陆地样带研究。\n(2) 可持续发展\n可持续发展领域的研究多停留在概念或内涵的定性探讨上，可操\n作性差。今后，可持续发展研究主要集中在以下几个方面：①可持续\n发展的内涵、发展观等探讨；②可持续发展的量化研究；③可持续发\n展模式与规划研究。\n(3) 生物多样性\n生物多样性是人类社会得以存在和持续发展的物质基础和必要\n保证。研究主要包括以下几个核心领域：①生物多样性的起源、维持\n与丧失；②生物多样性的生态系统功能；③生物多样性的编目、分类\n及其相互关系；④生物多样性评价与监测；⑤生物多样性保护、恢复\n与持续利用。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":0,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":192,"sourceRange":{"startPage":192,"startY":631.66,"endPage":193,"endY":665.9},"sourceKind":"original","originalOrdinal":"4","sourceMetadata":["【重要程度:☆☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":13,"excerpts":[{"page":192,"src":"./assets/environment/env838-80c4be8c6164ae82-192.webp"},{"page":193,"src":"./assets/environment/env838-80c4be8c6164ae82-193.webp"}]},{"id":"env838-ce35730a51c69c51","subject":"环境学导论","chapter":"第13章 生态学基础","originalChapter":"第13章 生态学基础","originalChapterNumber":13,"section":"第1节 生态学的含义及其发展","originalSection":"第1节 生态学的含义及其发展","category":"knowledge","title":"生态学的研究方法","question":"生态学的研究方法","type":"简答题","answer":"(1) 原地观测\n原地观测是指在自然界原生境对生物与环境关系的考察。原地观\n测包括野外考察、定位观测和原地实验等方法。①野外考察。野外考\n察是考察特定种群或群落与自然地理环境空间分布的关系。②定位观\n测。定位观测是考察某个体或某种群或群落结构功能与其生境关系的\n时态变化。③原地实验。原地实验是在自然条件下采取某些措施获得\n有关某个因素的变化对种群或群落及其影响。\n(2) 受控实验\n受控实验是在模拟自然生态系统的受控生态实验系统中研究单\n项或多项因子相互作用，及其对种群或群落影响的方法技术。\n(3)生态学研究的综合方法\n生态学研究的综合方法是指对原地观测或受控生态实验的大量\n资料和数据进行综合归纳分析，从而表达各种变量间存在的种种相互\n关系，反映客观生态规律性的方法。①资料归纳和分析。②生态学的\n数值分类和排序。③生态模型与模拟。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":0,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":193,"sourceRange":{"startPage":193,"startY":665.9,"endPage":194,"endY":473.83},"sourceKind":"original","originalOrdinal":"5","sourceMetadata":["【重要程度: ☆☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":13,"excerpts":[{"page":193,"src":"./assets/environment/env838-ce35730a51c69c51-193.webp"},{"page":194,"src":"./assets/environment/env838-ce35730a51c69c51-194.webp"}]},{"id":"env838-9d9991b6e8ee07f3","subject":"环境学导论","chapter":"第13章 生态学基础","originalChapter":"第13章 生态学基础","originalChapterNumber":13,"section":"第2节 生态系统的概念与功能","originalSection":"第2节 生态系统的概念与功能","category":"knowledge","title":"生态系统的概念","question":"生态系统的概念","type":"简答题","answer":"生态系统是指一定时间和空间范围内，生物群落与非生物环境通\n过能量流动和物质循环所形成的一个相互影响、相互作用并具有自调\n节功能的自然整体。生态系统也可简单地表述为：生态系统=生物群\n落十非生物环境。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2001,2011,2019],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":194,"sourceRange":{"startPage":194,"startY":515.8,"endPage":194,"endY":691.66},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":["2001(名、2011(名--群落、2019(名,【重要程度:"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":13,"excerpts":[{"page":194,"src":"./assets/environment/env838-9d9991b6e8ee07f3-194.webp"}]},{"id":"env838-f9771f7196c711f3","subject":"环境学导论","chapter":"第13章 生态学基础","originalChapter":"第13章 生态学基础","originalChapterNumber":13,"section":"第2节 生态系统的概念与功能","originalSection":"第2节 生态系统的概念与功能","category":"knowledge","title":"生态系统的组成","question":"生态系统的组成","type":"简答题","answer":"生态系统的组成主要包括必要的和非必要的两部分 。\n外必要的部分又分为生物成分和非生物成分两种 。\n生物成分包括生产者 、 分解者和转变者 ， 生产者以绿色植物为主 ， 还有一些能借光合\n作用而营生的菌类 ; 分解者包括一部分细菌和贵菌 ， 能使生物体分解为无机物质 ; 转\n变者也是细菌 ， 其作用是将分解后的无机物转变为可供植物利用的营养分 。\n非生物成分主要包括阳光和养分 ， 供生产者合成有机物之用 ;\n旬 “ 非必要部分主要是各级消费者 ， 它是依靠生产者生产的有机物质为生的 。\n总的来说 ， 生产者 、 消费者 、 分解者 、 转变者以及无机养分是生态系统的四个基本组\n[待核对] RAD","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2000,2001,2005,2008,2014],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。","含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":194,"sourceRange":{"startPage":194,"startY":691.66,"endPage":195,"endY":238.18},"sourceKind":"original","originalOrdinal":"supp-1","sourceMetadata":["2000 CH. 2001 CHM, 2005 Chi. 2008 (fi, 2014 〈 简 ，【 重要程度 ， 太妇女娘广 】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":13,"excerpts":[{"page":194,"src":"./assets/environment/env838-f9771f7196c711f3-194.webp"},{"page":195,"src":"./assets/environment/env838-f9771f7196c711f3-195.webp"}]},{"id":"env838-bbf7c0fe89a82cb8","subject":"环境学导论","chapter":"第13章 生态学基础","originalChapter":"第13章 生态学基础","originalChapterNumber":13,"section":"第2节 生态系统的概念与功能","originalSection":"第2节 生态系统的概念与功能","category":"knowledge","title":"食物链 、 食物网的概念","question":"食物链 、 食物网的概念","type":"简答题","answer":"ORME: 就是一种生物以另一种生物为食 ， 彼此形成的一个以食物连接起来的链锁\n关系 。\n@ 食物网 : 在一个生态系统中 ， 食物关系往往很复杂 ， 各种食物链相互交错 ， 形成食\n物网 。\n[待核对] 惟一加\n[待核对] 加生产并 《浮游植物 )\n[待核对] BS ORE (浮游动特 )\n13-2 池塘生态系统示意图","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2004,2009,2014],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。","含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":195,"sourceRange":{"startPage":195,"startY":238.18,"endPage":196,"endY":357.87},"sourceKind":"original","originalOrdinal":"supp-2","sourceMetadata":["2004 (4%. 2009 (4, 2014 (4%, (BEBE: 妈妈妇妇六】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":13,"excerpts":[{"page":195,"src":"./assets/environment/env838-bbf7c0fe89a82cb8-195.webp"},{"page":196,"src":"./assets/environment/env838-bbf7c0fe89a82cb8-196.webp"}]},{"id":"env838-67916ca9faf77aa5","subject":"环境学导论","chapter":"第13章 生态学基础","originalChapter":"第13章 生态学基础","originalChapterNumber":13,"section":"第2节 生态系统的概念与功能","originalSection":"第2节 生态系统的概念与功能","category":"knowledge","title":"生态系统的特点","question":"生态系统的特点","type":"简答题","answer":"①是生态学上的一个结构和功能单位，属生态学上的最高层次；\n②内部具有自调节、自组织、自更新能力；\n③具能量流动、物质循环和信息传递三大功能；\n④营养级数目有限；\n⑤是一个动态系统。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":196,"sourceRange":{"startPage":196,"startY":357.87,"endPage":196,"endY":593.16},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":["【重要程度："],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":13,"excerpts":[{"page":196,"src":"./assets/environment/env838-67916ca9faf77aa5-196.webp"}]},{"id":"env838-5e3b81a7780e25d2","subject":"环境学导论","chapter":"第13章 生态学基础","originalChapter":"第13章 生态学基础","originalChapterNumber":13,"section":"第2节 生态系统的概念与功能","originalSection":"第2节 生态系统的概念与功能","category":"knowledge","title":"生态系统中能量流动遵循的原理","question":"生态系统中能量流动遵循的原理","type":"简答题","answer":"(1)严格遵循热力学定律\n生态系统中能量的传递和转化都遵循热力学定律。热力学第一定\n律指出，自然界能量可以由一种形式转化为另一种形式，在转化过程\n中严格按当量比例，能量既不能消灭，也不能凭空创造。热力学第二\n定律指出，生态系统的能量从一种形式转化为另一种形式时，总有一\n部分能量转化为不能利用的热能而耗散。当进入生态系统中的能量在\n生产者、消费者和分解者之间进行流动和传递时，一部分能量同样转\n变为热，剩下的能量才用于做功，并合成新的生物组织作为潜能贮存\n下来。\n(2)生态系统中的能量流动是单向流\n能量以光能的形式进入生态系统后，就不能再以光的形式存在，\n而是以热的形式不断地逸散于环境中。就总的能流途径而言，能量只\n是一次性流经生态系统，是不可逆的。因此，能量在生态系统中的流\n动是单向的，不能返回，只能称为能量流动。\n(3)能量流动逐级递减\n从太阳辐射能到被生产者固定，再经草食动物到肉食动物再到大\n型肉食动物，能量是逐步递减的。这是因为：①各营养级消费者不可\n能百分之百地利用前一营养级的生物量；②各营养级的同化作用也不\n是百分之百的；③生物在维持生命过程中进行新陈代谢，总要消耗一\n部分能量，这部分能量变成热能而耗散掉。\n执 a\n[待核对] IS -级消费者 8 三级消费者 ， 热\n[待核对] ( 二级肉食动物\n(分解者 )\n图 13-3 生态系统能量流动示意图","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。","含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":196,"sourceRange":{"startPage":196,"startY":593.16,"endPage":198,"endY":40.08},"sourceKind":"original","originalOrdinal":"3","sourceMetadata":["【重要程度："],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":13,"excerpts":[{"page":196,"src":"./assets/environment/env838-5e3b81a7780e25d2-196.webp"},{"page":197,"src":"./assets/environment/env838-5e3b81a7780e25d2-197.webp"},{"page":198,"src":"./assets/environment/env838-5e3b81a7780e25d2-198.webp"}]},{"id":"env838-5d7e44234b77aae0","subject":"环境学导论","chapter":"第13章 生态学基础","originalChapter":"第13章 生态学基础","originalChapterNumber":13,"section":"第2节 生态系统的概念与功能","originalSection":"第2节 生态系统的概念与功能","category":"knowledge","title":"生态地球化学循环的定义","question":"生态地球化学循环的定义","type":"简答题","answer":"生态系统从大气、水体和土壤等环境中获得的营养物质，通过绿\n色植物吸收，进入生态系统，被其他生物重复利用，最后再回归到环\n境中，称为物质循环，又称生物地球化学循环。这种循环可发生在不\n同层次、不同大小的生态系统内，乃至生物圈中。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":2,"pastExamYears":[2022],"needsReview":false,"reviewReasons":[],"verified":false,"page":198,"sourceRange":{"startPage":198,"startY":40.08,"endPage":198,"endY":241.6},"sourceKind":"original","originalOrdinal":"4","sourceMetadata":["2022( 名, 【重要程度:★★☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":13,"excerpts":[{"page":198,"src":"./assets/environment/env838-5d7e44234b77aae0-198.webp"}]},{"id":"env838-effaa3ad01df136e","subject":"环境学导论","chapter":"第13章 生态学基础","originalChapter":"第13章 生态学基础","originalChapterNumber":13,"section":"第2节 生态系统的概念与功能","originalSection":"第2节 生态系统的概念与功能","category":"knowledge","title":"物质循环","question":"物质循环","type":"简答题","answer":"物质循环包括地质大循环和生物小循环。地质大循环是指物质或\n元素经生物体的吸收作用，从环境进入生物有机体内，然后生物有机\n体以死体、残体或排泄物形式将物质或元素返回环境，进入大气、水\n、岩石、土壤和生物五大自然圈层的循环。地质大循环的时间长、范\n围广，是闭合式循环。生物小循环指环境中元素经生物体吸收，在生\n态系统中被多层次利用，然后经过分解者的作用，再为生产者吸收利\n用。生物小循环时间短，范围小，是开放式循环。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":1,"pastExamYears":[2026],"needsReview":false,"reviewReasons":[],"verified":false,"page":198,"sourceRange":{"startPage":198,"startY":241.6,"endPage":198,"endY":538.27},"sourceKind":"original","originalOrdinal":"5","sourceMetadata":["2026(名—物质循环【重要程度: ★☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":13,"excerpts":[{"page":198,"src":"./assets/environment/env838-effaa3ad01df136e-198.webp"}]},{"id":"env838-f8cb430330c2b3ee","subject":"环境学导论","chapter":"第13章 生态学基础","originalChapter":"第13章 生态学基础","originalChapterNumber":13,"section":"第2节 生态系统的概念与功能","originalSection":"第2节 生态系统的概念与功能","category":"knowledge","title":"物质循环的类型","question":"物质循环的类型","type":"简答题","answer":"物质循环可分为3种类型，即水循环、气体型循环和沉积型循环\n(1) 水循环\n水是自然的驱使者，生态系统中所有的物质循环都是在水循环的\n推动下完成的。没有水循环就没有物质循环，就没有生态系统的功能\n，也就没有生命。\n光合作用\n[待核对] Hei\na\n图 13-4 水循环示意图\n(2) 气体型循环\n气体型循环的贮存库主要是大气和海洋，气体循环与大气和海洋\n密切相关，循环性能完善，具有明显的全球性。凡属于气体型循环的\n物质，其分子或某些化合物常以气体的形式参与循环过程。属于这一\n类循环的物质有碳、氮和氧等。气体型循环与全球性的3个环境问题\n(温室效应、酸雨、臭氧层破坏)密切相关。\n水生物光合作\n用 、 呼鹃作用\n[待核对] wits\n图 13-5 碳循环示意图\n[待核对] BOM / weer\n[待核对] Waa\n[待核对] mana”\n图 13-6 氢循环示意图\n[待核对] amy\n[待核对] they\n[待核对] eesereEe 海马和鱼\n[待核对] HK\ny 天然侵蚀\n浅海沉积层 f 食物链\n原生质合成磷酸盐\n\\ 化细菌\n}\n[待核对] PRAT BR BR rh\n图 13-7 磷循环示意图\n(3) 沉积型循环\n沉积型循环的贮存库主要是岩石、沉积物和土壤，循环物质分子\n或化合物主要通过岩石的风化作用和沉积物的溶解作用，才能转变成\n可供生态系统利用的营养物质。循环过程缓慢，循环是非全球性的。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":2,"pastExamYears":[2003,2004,2006,2011,2020],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。","含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":198,"sourceRange":{"startPage":198,"startY":538.27,"endPage":201,"endY":53.32},"sourceKind":"original","originalOrdinal":"6","sourceMetadata":["2003(填--氮循环、2004(简--氮循环、2011(判--氮循环、2020(简--氮循环、2006(论","—碳循环、2003(简—磷循环,【重要程度:★★☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":13,"excerpts":[{"page":198,"src":"./assets/environment/env838-f8cb430330c2b3ee-198.webp"},{"page":199,"src":"./assets/environment/env838-f8cb430330c2b3ee-199.webp"},{"page":200,"src":"./assets/environment/env838-f8cb430330c2b3ee-200.webp"},{"page":201,"src":"./assets/environment/env838-f8cb430330c2b3ee-201.webp"}]},{"id":"env838-48bb3b19a54c4b24","subject":"环境学导论","chapter":"第13章 生态学基础","originalChapter":"第13章 生态学基础","originalChapterNumber":13,"section":"第2节 生态系统的概念与功能","originalSection":"第2节 生态系统的概念与功能","category":"knowledge","title":"生态系统稳定性","question":"生态系统稳定性","type":"简答题","answer":"生态系统的稳定性应包括以下三个类型：群落或生态系统达到演\n替顶极后出现的能够进行自我更新和维持并使群落的结构、功能长期\n保持在一个较高水平、波动较小的现象；群落或生态系统在受到干扰\n后维持其原来结构状态的能力；群落和生态系统受到干扰后回到原来\n状态的能力。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":1,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":201,"sourceRange":{"startPage":201,"startY":53.32,"endPage":201,"endY":287.3},"sourceKind":"original","originalOrdinal":"7","sourceMetadata":["【重要程度: ★☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":13,"excerpts":[{"page":201,"src":"./assets/environment/env838-48bb3b19a54c4b24-201.webp"}]},{"id":"env838-87293481034203b9","subject":"环境学导论","chapter":"第13章 生态学基础","originalChapter":"第13章 生态学基础","originalChapterNumber":13,"section":"第3节 生态问题与可持续发展","originalSection":"第3节 生态问题与可持续发展","category":"knowledge","title":"森林资源变化的特点","question":"森林资源变化的特点","type":"简答题","answer":"①森林总量持续增长；\n②森林质量不断提高；\n③天然林稳步增长；\n④人工林快速发展；\n⑤森林采伐中人工林比重继续上升。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":0,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":201,"sourceRange":{"startPage":201,"startY":330.56,"endPage":201,"endY":558.6},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":["【重要程度:☆☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":13,"excerpts":[{"page":201,"src":"./assets/environment/env838-87293481034203b9-201.webp"}]},{"id":"env838-a6fa252be2b8d3e3","subject":"环境学导论","chapter":"第13章 生态学基础","originalChapter":"第13章 生态学基础","originalChapterNumber":13,"section":"第3节 生态问题与可持续发展","originalSection":"第3节 生态问题与可持续发展","category":"knowledge","title":"中国生态问题","question":"中国生态问题","type":"简答题","answer":"(1 )大气污染严重，大气质量恶化。全国工业废气排放量增加，\nSO2、 、粉尘排放量很大，并且酸雨污染也较为严重。\n(2)水体污染明显加重，水资源短缺形势严峻。由于我国废水\n处理率低，大部分废水未经处理直接或间接排入水体，水体污染问题\n十分突出。此外，我国水资源短缺严重，人均水资源量处在中度缺水\n标准水平。同时，我国水资源时空分布不均。总体来看，时间上。夏\n秋多、冬春少；空间上，南方多、北方少。\n(3 )固体废弃物不断上升，城市噪声污染严重。我国工业固像\n废弃物和城市垃圾日益增加，年产量高但综合利用率却较低，并且我\n国城市的环境噪声多数处于高声级，声环境超标现象严重。\n(4)沙漠化迅速发展。中国是世界上沙漠化受害最深的国家之\n一。北方荒漠化地区植被总体上仍处于初步恢复阶段，自我调节能力\n仍较弱稳定性仍较差，难以在短期内形成稳定的生态系统。人为活动\n对荒漠植被的负面影响远未消除，超载放牧、盲目开垦、滥采滥挖和\n不合理利用水资源等破坏植被行为依然存在。气候变化导致极端气象\n灾害(如持续干旱等)频繁发生，对植被建设和恢复影响甚大，\n(5 )水土流失严重。我国水土流失呈现分布范围广、面积大的\n特点，且侵蚀形式多样、类型复杂，水力侵蚀、风力侵蚀、冻融侵蚀\n及滑坡泥石流等重力侵蚀特点各异，相互交错，成因复杂，难于控制\n，水土保持仍面临较大压力。\n(6 )森林资源锐减。中国历史上曾是森林资源丰富的国家，但\n经历代的砍伐破坏，许多主要林区森林面积大幅度减少。森林资源总\n量相对不足、质量不高、分布不均的状况仍未得到根本改变，林业发\n展还面临着巨大的压力和挑战。\n(7 )草原退化加剧。长期以来，对草原掠夺性的粗放经营，破\n坏草地生态平衡，使我国草地生态系统严重恶化。\n(8 )生物物种加速灭绝。由于森林砍伐、草原退化、环境污染、\n自然灾害、过度捕猎等，大量野生动植物的生境受到极大破坏，很多\n物种已经灭绝或濒临灭绝，生物多样性逐渐减少。\n(9)环境污染向农村蔓延。1978年以前，农村环境污染主要是\n化肥、农药等：1978年以后，乡镇企业成为农村主要污染源。乡镇企\n业的发展使农村经济发生了巨大变化，也带来众多环境问题。乡镇工\n业与农业环境连接紧密，排放的污染物直接威胁农田和作物，给农村\n带来生态环境更大范围的污染，对农业资源、矿产资源造成更为严重\n的浪费。\n(10)自然灾害与环境事故频繁。我国大部分地区受季风影响，\n灾害频繁，损失巨大。研究表明，地球上每年的旱、涝灾害，对生态\n环境构成了巨大威胁，其经济损失占各类自然灾害总损失的一半以上","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":1,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":201,"sourceRange":{"startPage":201,"startY":558.6,"endPage":203,"endY":355.97},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":["【重要程度:★☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":13,"excerpts":[{"page":201,"src":"./assets/environment/env838-a6fa252be2b8d3e3-201.webp"},{"page":202,"src":"./assets/environment/env838-a6fa252be2b8d3e3-202.webp"},{"page":203,"src":"./assets/environment/env838-a6fa252be2b8d3e3-203.webp"}]},{"id":"env838-2fe1075501aee5a4","subject":"环境学导论","chapter":"第13章 生态学基础","originalChapter":"第13章 生态学基础","originalChapterNumber":13,"section":"第3节 生态问题与可持续发展","originalSection":"第3节 生态问题与可持续发展","category":"knowledge","title":"草原总体生态环境脆弱表现的方面","question":"草原总体生态环境脆弱表现的方面","type":"简答题","answer":"①草原生态恢复的长期性\n我国草原多分布在干旱地区，这些地区年降水总量少，而且年际\n间、季节间波动大。同时，与森林相比，草原生态系统动植物种类更\n少，群落结构也更简单，因此草原生态系统的种群和群落结构容易发\n生非常剧烈的变化。这些特点决定了退化草原生态的恢复注定是一个\n长期的过程。\n②草原生态保护建设任务的艰巨性\n过去几十年的过度利用和气候变化等因素，造成我国草原出现大\n面积的退化、沙化、盐渍化，其退化范围之广和退化程度之大都是难\n以想象的。在这种形势下进行草原保护建设，必须要付出非常艰辛的\n努力。\n③草原生态恢复的复杂性。\n长期以来，人们过于强调草原的生产功能，忽视草原的生态功能\n，由此造成人、畜、草关系持续失衡，这是导致草原生态难以走出恶\n性循环的根本原因。近年来，草原保护投入的增幅很大，但由于草原\n面积广阔，单位面积投入远低于耕地、林地，加之牧区经济和畜牧业\n基础设施落后，在这种条件下，在所有草原地区转变发展思路，开展\n草原生态恢复还是相当复杂的。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":0,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":203,"sourceRange":{"startPage":203,"startY":355.97,"endPage":204,"endY":235.6},"sourceKind":"original","originalOrdinal":"3","sourceMetadata":["【重要程度:☆☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":13,"excerpts":[{"page":203,"src":"./assets/environment/env838-2fe1075501aee5a4-203.webp"},{"page":204,"src":"./assets/environment/env838-2fe1075501aee5a4-204.webp"}]},{"id":"env838-74fe19fa9f595099","subject":"环境学导论","chapter":"第13章 生态学基础","originalChapter":"第13章 生态学基础","originalChapterNumber":13,"section":"第3节 生态问题与可持续发展","originalSection":"第3节 生态问题与可持续发展","category":"knowledge","title":"环境污染问题总述","question":"环境污染问题总述","type":"简答题","answer":"①由于我国工业基础薄弱，不少工厂设备陈旧，生产技术工艺落\n后，技术改造和设备更新赶不上生产发展需要，对自然资源的开发强\n度不断加大。此外，目前我国主要为粗放型的经济增长方式，技术水\n平和管理水平比较落后，再加上管理混乱，跑、冒、滴、漏现象严重\n，资源利用率低，废物排放量大，造成对生态环境的污染。\n②我国自然生态环境脆弱，生态环境恶化的趋势还没有遏制住。\n水土流失日趋严重，荒漠化土地面积不断扩大，天然植被遭到破坏，\n毁林开垦、陡坡种植、围湖造田等加重了自然灾害造成的损失。草地\n退化、沙化和碱化(以下简称“三化”)现象严重，生物多样性受到\n严重破坏。日益恶化的生态环境，给我国经济和社会带来极大危害，\n严重影响可持续发展。\n③我国是自然灾害频繁而又严重的国家，一些地区遭受干旱、洪\n涝、滑坡、泥石流、台风等灾害的袭击，地震灾害也时有发生，给人\n民生命财产造成严重损失。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":204,"sourceRange":{"startPage":204,"startY":235.6,"endPage":204,"endY":711.01},"sourceKind":"original","originalOrdinal":"4","sourceMetadata":["【重要程度：★★"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":13,"excerpts":[{"page":204,"src":"./assets/environment/env838-74fe19fa9f595099-204.webp"}]},{"id":"env838-1ed7d8dfa09cb54c","subject":"环境学导论","chapter":"第13章 生态学基础","originalChapter":"第13章 生态学基础","originalChapterNumber":13,"section":"第3节 生态问题与可持续发展","originalSection":"第3节 生态问题与可持续发展","category":"knowledge","title":"生态系统的五大规律","question":"生态系统的五大规律","type":"简答题","answer":"[待核对] 2008〈 简 、2010 CG, 2014 GH, 2021 (fi, (BBB todo]\n人相互依存与制约\n相互依存与相互制约规律 ， 反映了生物间的协调关系 ， 是构成生物群落的基础 。 生物\n间的这种协调关系 ， 主要分为两类 。\n普遍的相互依存与制约 ， 亦称物物相关规律 。 即生物间的相互依存与制约关系 ， 无论\n动物 、 植物 、 微生物中 ， 或在它们之间 ， 都是普遍存在的 。\n通过食物而相互联系与制约的协调关系 ， 亦称相生相克规律 。 即每一种生物在食物链\n或食物网中都占据一定的位置 ， 具有特定的作用 ， 各生物之间相互依赖 、 彼此制约协\n同进化 。 生物间的这种相生相克作用 ， 使生物保持数量上的相对稳定 ， 这是生态平衡\n的一个重要方面\n@ 物质循环转化与再生规律\n生态系统中 ， 动物 、 植物 、 微生物和非生物成分 ， 借助能量的不停流动 ， 一方面不断\n从自然界提取物质并合成新的物质 ， 另一方面又随时分解为原来的简单物质 ， 即所谓\n再生 ， 重新被植物所吸收 ， 进行着不停顿的物质循环 ;\n@@ 物质输入与输出的动态平衡规律\n当一个自然生态系统不受人类活动干扰时 ， 生物与环境之间的输入与输出 ， 是相互对\n立的关系 ， 生物体进行输入时 ， 环境必然进行输出 ， 反之亦然 。 如果生态系统输入不\n足或者输出过多都会造成生态系统失去平衡 ;\n@@ 相互适应与补偿的协同进化规律\n生物与环境之间存在着作用与反作用的过程 。 生物给环境以影响 ， 反过来环境也会影\n响生物 。 生物与环境就是反复的相互适应和补偿 ， 最终获得协同进化的结果 ;\n@@ 环境资源的有效极限规律\n生态系统中作为生物赖以生存的各种环境资源 ， 在质量 、 数量 、 时间 、 空间等方面都\n有一定的限度 ， 不能无限制的供给 ， 因而生物生产力通常都有一个大致的上限 。\nSAE | | 输入与输出 | | 相互适应协 | | 物质循环 | | 相互制约\n极限规律 | | 半衔规律 | | 同进化规律 | | 转化规律 | | 协调规律\n图 13-8 五大规律与生态系统的关系","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。","含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":204,"sourceRange":{"startPage":204,"startY":711.01,"endPage":206,"endY":60.94},"sourceKind":"original","originalOrdinal":"supp-1","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":13,"excerpts":[{"page":204,"src":"./assets/environment/env838-1ed7d8dfa09cb54c-204.webp"},{"page":205,"src":"./assets/environment/env838-1ed7d8dfa09cb54c-205.webp"},{"page":206,"src":"./assets/environment/env838-1ed7d8dfa09cb54c-206.webp"}]},{"id":"env838-be31a878d30d2396","subject":"环境学导论","chapter":"第13章 生态学基础","originalChapter":"第13章 生态学基础","originalChapterNumber":13,"section":"第4节 课后习题","originalSection":"第4节 课后习题","category":"exercise","title":"简述生态学的概念以及生态学的研究内容和研究方法。","question":"简述生态学的概念以及生态学的研究内容和研究方法。","type":"简答题","answer":"生态学研究生物与生物之间、生物与环境之间的相互关系及其规律。\n研究层次包括个体、种群、群落、生态系统以及景观和更大尺度；主要内容涉及分布与适应、种群动态、种间关系、群落演替、能量流动、物质循环及生态系统功能等。\n研究方法：①野外调查、定位监测及原地观察；②在自然或受控条件下开展实验，识别关键因子的作用；③对资料进行统计分析、模型模拟及综合归纳。\n方法应相互验证，注意对照、空间与时间尺度及因果推断，不能把相关关系直接等同于因果关系。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":206,"sourceRange":{"startPage":206,"startY":96.77,"endPage":206,"endY":174.62},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":13,"excerpts":[{"page":206,"src":"./assets/environment/env838-be31a878d30d2396-206.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=189"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-d36427e9511b2f1a","subject":"环境学导论","chapter":"第13章 生态学基础","originalChapter":"第13章 生态学基础","originalChapterNumber":13,"section":"第4节 课后习题","originalSection":"第4节 课后习题","category":"exercise","title":"什么是生态系统?举例说明生态系统的物质循环有哪几种类型。","question":"什么是生态系统?举例说明生态系统的物质循环有哪几种类型。","type":"简答题","answer":"生态系统是在一定时间和空间内，生物群落与非生物环境通过能量流动、物质循环等相互联系形成的功能整体。\n按主要储库和循环路径，教学上常区分：①气体型循环，如碳、氮循环，主要储库涉及大气或海洋，具有较明显的全球联系；②沉积型循环，如磷循环，主要储库在岩石和沉积物中，地质尺度过程较慢；③水循环，在大气、陆地和海洋之间通过蒸发、降水、径流等交换。\n不同元素的具体循环并不完全相同，分类是便于理解的框架，应说明储库、迁移及生物参与过程。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":206,"sourceRange":{"startPage":206,"startY":174.62,"endPage":206,"endY":281.65},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":13,"excerpts":[{"page":206,"src":"./assets/environment/env838-d36427e9511b2f1a-206.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=189"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-9b9aa7f26973c60c","subject":"环境学导论","chapter":"第13章 生态学基础","originalChapter":"第13章 生态学基础","originalChapterNumber":13,"section":"第4节 课后习题","originalSection":"第4节 课后习题","category":"exercise","title":"我国存在的生态问题有哪些?请举例说明。","question":"我国存在的生态问题有哪些?请举例说明。","type":"简答题","answer":"主要生态问题：①部分地区水土流失、荒漠化及土地退化；②森林、草地和湿地质量或功能受损；③生境丧失、破碎化及生物多样性下降；④河湖水生态退化、生态流量不足及富营养化；⑤外来物种和气候变化等压力。\n例子：坡地植被受破坏后，暴雨径流更易剥蚀表土，造成耕地肥力下降和河库泥沙负担；城市建设切割生境，可能阻碍野生动物移动。\n治理应统筹山水林田湖草沙，优先保护完整生态系统，因地制宜恢复自然过程，并用持续监测评估效果。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":206,"sourceRange":{"startPage":206,"startY":281.65,"endPage":206,"endY":360.25},"sourceKind":"original","originalOrdinal":"3","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":13,"excerpts":[{"page":206,"src":"./assets/environment/env838-9b9aa7f26973c60c-206.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=189"},{"title":"生态环境部：2024中国生态环境状况公报","url":"https://www.mee.gov.cn/ywgz/sthjjcgl/hjzljcypj/202506/t20250605_1120773.shtml","accessedOn":"2026-11-09"},{"title":"中国生物多样性保护战略与行动计划（2023—2030年）发布说明","url":"https://www.mee.gov.cn/xxgk/hjyw/202401/t20240118_1064111.shtml","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-4b6af58706c17851","subject":"环境学导论","chapter":"第13章 生态学基础","originalChapter":"第13章 生态学基础","originalChapterNumber":13,"section":"第4节 课后习题","originalSection":"第4节 课后习题","category":"exercise","title":"生态系统中物质循环与能量流动有何特点?","question":"生态系统中物质循环与能量流动有何特点?","type":"简答题","answer":"能量流动：主要由太阳能等外部输入，经生产者、消费者和分解者传递，过程中不断以热的形式耗散，呈单向流动和逐级减少的总体特征，不能在生态系统内闭合再循环。\n物质循环：元素在生物与非生物组分之间反复迁移和转化，包括生物、地球化学及地质过程，可跨生态系统交换。\n联系：能量驱动物质的合成、运输和分解，物质又是能量传递的载体；两者通过食物网相联系。\n应用：提高能量利用与物质回收效率需要合理的系统结构，不能把“能量梯级利用”理解为能量无损循环。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":206,"sourceRange":{"startPage":206,"startY":360.25,"endPage":206,"endY":439.86},"sourceKind":"original","originalOrdinal":"4","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":13,"excerpts":[{"page":206,"src":"./assets/environment/env838-4b6af58706c17851-206.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=189"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-a3d186282dc6e99a","subject":"环境学导论","chapter":"第13章 生态学基础","originalChapter":"第13章 生态学基础","originalChapterNumber":13,"section":"第4节 课后习题","originalSection":"第4节 课后习题","category":"exercise","title":"简述生态系统的稳定性。","question":"简述生态系统的稳定性。","type":"简答题","answer":"整理答案（按教材对应知识点摘录）：\n\n生态系统稳定性：\n生态系统的稳定性应包括以下三个类型：群落或生态系统达到演\n替顶极后出现的能够进行自我更新和维持并使群落的结构、功能长期\n保持在一个较高水平、波动较小的现象；群落或生态系统在受到干扰\n后维持其原来结构状态的能力；群落和生态系统受到干扰后回到原来\n状态的能力。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["根据所列知识点摘录整理，未逐题人工审定。"],"verified":false,"page":206,"sourceRange":{"startPage":206,"startY":439.86,"endPage":206,"endY":520.63},"sourceKind":"original","originalOrdinal":"5","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":13,"references":[{"id":"env838-48bb3b19a54c4b24","title":"生态系统稳定性","source":"环境学导论.pdf","page":201}],"excerpts":[{"page":206,"src":"./assets/environment/env838-a3d186282dc6e99a-206.webp"}]},{"id":"env838-4ea1fe54ba69f763","subject":"环境学导论","chapter":"第13章 生态学基础","originalChapter":"第13章 生态学基础","originalChapterNumber":13,"section":"第4节 课后习题","originalSection":"第4节 课后习题","category":"exercise","title":"什么是可持续发展?走可持续发展道路的意义是什么?","question":"什么是可持续发展?走可持续发展道路的意义是什么?","type":"简答题","answer":"可持续发展强调满足当代人的合理需要，同时不损害后代满足其需要的能力。\n核心是协调经济发展、社会进步与生态环境保护，在资源环境约束下实现长期的人类福祉。\n意义：①减少以资源耗竭和环境损害换取短期增长的代价；②维护代际公平与不同群体的发展机会；③保护生态系统、资源基础和公共健康；④推动效率提升、技术创新和绿色转型；⑤提高面对灾害、气候及资源供应冲击的韧性。\n实践中既要提高资源效率，也要合理控制总量并完善制度，不能仅靠末端污染处理。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":206,"sourceRange":{"startPage":206,"startY":520.63,"endPage":206,"endY":600.01},"sourceKind":"original","originalOrdinal":"6","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":13,"excerpts":[{"page":206,"src":"./assets/environment/env838-4ea1fe54ba69f763-206.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=189"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-b1133d0404af64a0","subject":"环境学导论","chapter":"第13章 生态学基础","originalChapter":"第13章 生态学基础","originalChapterNumber":13,"section":"第4节 课后习题","originalSection":"第4节 课后习题","category":"exercise","title":"查阅并讨论生态学的环境保护实践案例。","question":"查阅并讨论生态学的环境保护实践案例。","type":"简答题","answer":"可用浙江湖州桑基鱼塘系统作为生态学实践案例。\n结构：塘基种桑、桑叶养蚕、池塘养鱼，生产环节在空间上组合。\n过程：部分生产副产物经适当利用进入其他环节，塘泥等回到陆地生产，体现食物链联系与养分循环。\n作用：协调水陆利用，形成多样化产品及生计，并保存地方生态文化与适应性管理经验。\n讨论：其有效性依赖合理密度、水质、物料负荷和长期管理；现代推广应监测养分及病原风险，不能把传统生态模式等同于没有污染可能或可无限增加投入。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":206,"sourceRange":{"startPage":206,"startY":600.01,"endPage":207,"endY":50.27},"sourceKind":"original","originalOrdinal":"7","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":13,"excerpts":[{"page":206,"src":"./assets/environment/env838-b1133d0404af64a0-206.webp"},{"page":207,"src":"./assets/environment/env838-b1133d0404af64a0-207.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=189"},{"title":"FAO：浙江湖州桑基鱼塘系统","url":"https://www.fao.org/giahs/around-the-world/detail/china-zhejiang-system/zh","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-974861e49cb889d9","subject":"环境学导论","chapter":"第14章 生物多样性","originalChapter":"第14章 生物多样性","originalChapterNumber":14,"section":"第1节 生物多样性","originalSection":"第1节 生物多样性","category":"knowledge","title":"生物多样性的定义","question":"生物多样性的定义","type":"简答题","answer":"生物多样性是生物及其与环境形成的生态复合体以及与此相关\n的各种生态过程的总和，由遗传(基因)多样性，物种多样性和生态\n系统多样性三个层次组成。\n遗传(基因)多样性指生物体内决定性状的遗传因子及其组合的\n多样性。物种多样性是生物多样性在物种上的表现形式，也是生物多\n样性的关键，它既体现生物之间及环境之间的复杂关系，又体现生物\n资源的丰富性。生态系统多样性指生物圈内生境、生物群落和生态过\n程的多样性。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2006],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":208,"sourceRange":{"startPage":208,"startY":94.57,"endPage":208,"endY":407.78},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":["2006(名, 【重要程度:"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":14,"excerpts":[{"page":208,"src":"./assets/environment/env838-974861e49cb889d9-208.webp"}]},{"id":"env838-e2ca30dd22bca360","subject":"环境学导论","chapter":"第14章 生物多样性","originalChapter":"第14章 生物多样性","originalChapterNumber":14,"section":"第1节 生物多样性","originalSection":"第1节 生物多样性","category":"knowledge","title":"生物多样性的价值","question":"生物多样性的价值","type":"简答题","answer":"①直接价值：为人类提供食物、纤维、建筑和家具材料及其他生\n活、生产原料。\n②间接价值：具有重要的生态功能。在生态系统中，野生生物之\n间具有相互依存和相互制约的关系，它们共同维系着生态系统的结构\n和功能，为人类生存提供基本条件，保护人类免受自然灾害和疾病之\n苦。野生生物一旦减少，生态系统的稳定性就会遭到破坏，人类的生\n存环境也会受到影响。\n③潜在价值：人类对野生生物做过比较充分研究的只是极少数，\n大量野生生物的使用价值目前还不清楚。一种野生生物一旦从地球上\n消失就无法再生，它的潜在使用价值也就不复存在。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":1,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":208,"sourceRange":{"startPage":208,"startY":407.78,"endPage":209,"endY":46.25},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":["【重要程度:★☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":14,"excerpts":[{"page":208,"src":"./assets/environment/env838-e2ca30dd22bca360-208.webp"},{"page":209,"src":"./assets/environment/env838-e2ca30dd22bca360-209.webp"}]},{"id":"env838-2cf19892745b43cb","subject":"环境学导论","chapter":"第14章 生物多样性","originalChapter":"第14章 生物多样性","originalChapterNumber":14,"section":"第1节 生物多样性","originalSection":"第1节 生物多样性","category":"knowledge","title":"生物多样性对人类社会的重要作用","question":"生物多样性对人类社会的重要作用","type":"简答题","answer":"①食用价值：生物多样性为人类提供食物的来源，作为人类基本\n食物的农作物、家禽和家畜等均源自生物。\n②药用价值：生物多样性为人类提供药物资源。发展中国家80%\n的人口食用传统医药，这些医药多是动植物，如中药用到5100多个物\n种的动植物，世界上现有药品配方的一半来自野生生物。\n③生态价值：维系自然界能量流动、物质循环、改良土壤、涵养\n水源。\n④调节气候：生物多样性是维持生态系统平衡的必要条件，某些\n物种的消亡可能引起整个系统的失衡，甚至崩溃。\n⑤工业价值：人类利用生物多样性提供各种工业原料，如木材、\n纤维、橡胶、造纸原料、淀粉、油、树脂、染料、醋、蜡、杀虫剂和\n其他许多化合物。\n⑥新品种培育价值：野生物种是培育新品种不可缺少的原材料，\n特别是随着近代遗传工程的兴起和发展，物种的保存有着更深远的意\n义，如大熊猫数量目前不足2千头，保护它们的遗传基因多样性成了\n当务之急。\n⑦艺术价值：多姿多彩的自然环境与生物给人类带来美的享受，\n是艺术创造和科学发明的源泉。艺术家们以生物为源头创作出大量的\n艺术作品\n⑧科研价值：物种多样性对科学技术的发展是不可或缺的，仿生\n学的发展离不开丰富而奇异的生物世界。例如，飞机来自人们对鸟类\n的模仿，船和潜艇来自人们对鱼类和海豚的模仿，火箭升空利用的是\n水母、墨鱼的反冲原理。\n⑨娱乐和旅游价值：人们采用不同的方式利用生物资源开展娱乐\n活动和旅游活动，如参观动物园和保护区、野外观鸟、赏花、森林浴\n等。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":0,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":209,"sourceRange":{"startPage":209,"startY":46.25,"endPage":210,"endY":158.02},"sourceKind":"original","originalOrdinal":"3","sourceMetadata":["【重要程度: ☆☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":14,"excerpts":[{"page":209,"src":"./assets/environment/env838-2cf19892745b43cb-209.webp"},{"page":210,"src":"./assets/environment/env838-2cf19892745b43cb-210.webp"}]},{"id":"env838-869fce9a9629a351","subject":"环境学导论","chapter":"第14章 生物多样性","originalChapter":"第14章 生物多样性","originalChapterNumber":14,"section":"第2节 我国的生物多样性","originalSection":"第2节 我国的生物多样性","category":"knowledge","title":"我国生物多样性的特点","question":"我国生物多样性的特点","type":"简答题","answer":"(1) 物种高度丰富\n(2) 特有属、种多\n(3) 区系起源古老\n(4)栽培植物，家养动物及其野生亲缘的种质资源异常丰富\n(5) 生态系统丰富多彩\n(6)空间格局反复多样性","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":210,"sourceRange":{"startPage":210,"startY":198.56,"endPage":210,"endY":458.09},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":["【重要程度："],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":14,"excerpts":[{"page":210,"src":"./assets/environment/env838-869fce9a9629a351-210.webp"}]},{"id":"env838-239b52d046a7d8fc","subject":"环境学导论","chapter":"第14章 生物多样性","originalChapter":"第14章 生物多样性","originalChapterNumber":14,"section":"第2节 我国的生物多样性","originalSection":"第2节 我国的生物多样性","category":"knowledge","title":"生物多样性受威胁现状","question":"生物多样性受威胁现状","type":"简答题","answer":"(1)部分生态系统功能不断退化。我国人工林树种单一，抗病\n虫害能力差。90%的草原存在不同程度的退化现象。内陆淡水生态系\n统受到威胁，部分重要湿地退化。海洋及海岸带物种及其栖息地不断\n丧失，海洋渔业资源减少。\n(2)物种濒危程度加剧。我国野生高等植物濒危比例达15%~\n20%，野生动物濒危程度不断加剧，非国家重点保护野生动物种群下\n降趋势明显。\n(3)遗传资源不断丧失和流失。一些农作物野生近缘种的生存\n环境遭受破坏，栖息地丧失，野生稻原有分布点中的60%~70%已经\n消失或萎缩，部分珍贵和特有的农作物、林木、花卉、畜、禽、鱼等\n种质资源流失严重，一些地方传统和稀有品种资源丧失。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":0,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":210,"sourceRange":{"startPage":210,"startY":458.09,"endPage":211,"endY":126.26},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":["【重要程度:☆☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":14,"excerpts":[{"page":210,"src":"./assets/environment/env838-239b52d046a7d8fc-210.webp"},{"page":211,"src":"./assets/environment/env838-239b52d046a7d8fc-211.webp"}]},{"id":"env838-db2cffa66b024dc6","subject":"环境学导论","chapter":"第14章 生物多样性","originalChapter":"第14章 生物多样性","originalChapterNumber":14,"section":"第3节 生物多样性损失及其原因","originalSection":"第3节 生物多样性损失及其原因","category":"knowledge","title":"生物多样性损失的主要原因","question":"生物多样性损失的主要原因","type":"简答题","answer":"生物多样性的丧失，既有自然发生的，也有非自然发生的，人类\n活动是生物多样性损失的最主要原因。此外，制度特别是法律制度的\n不健全，则是引起损失的另一主要原因。\n(1)自然原因。自然原因包括物种本身的生物学特性和环境突\n变：①物种本身的生物学特性决定的。物种对环境的适应能力或变异\n性、适应性比较差，在环境发生较大变化时难以适应，因此而面临灭\n绝的危险。②环境突变(天灾)，如地震、水灾、火灾、暴风雪、干\n旱等自然灾害造成的。\n(2) 人为原因\n人类对生物多样性的重要性认识不够，同时又过于重视经济发展\n，导致生境破坏时有发生。对生物资源开发过度(有些甚至是掠夺式\n的开发)、环境污染严重、对外来物种入侵问题重视不够以及制度的\n不健全等，都是导致生物多样性减少的主要原因。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":0,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":211,"sourceRange":{"startPage":211,"startY":168.38,"endPage":211,"endY":630.22},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":["【重要程度: ☆☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":14,"excerpts":[{"page":211,"src":"./assets/environment/env838-db2cffa66b024dc6-211.webp"}]},{"id":"env838-f392ebcf82d2127e","subject":"环境学导论","chapter":"第14章 生物多样性","originalChapter":"第14章 生物多样性","originalChapterNumber":14,"section":"第3节 生物多样性损失及其原因","originalSection":"第3节 生物多样性损失及其原因","category":"knowledge","title":"生境的碎片化和退化的定义","question":"生境的碎片化和退化的定义","type":"简答题","answer":"生境碎片化指1个面积大而连续的生境被分割成2个或更多小块\n残片并逐渐缩小的过程。人类活动都可能导致生境的碎片化，生境的\n碎片化还有助于外来物种的入侵，进而威胁到原有物种的生存。\n生境退化则是生境部分的失去原有功能，如过度放牧等使草场退\n化严重，引起草原生物生理机能衰退，从而对其生存构成威胁。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":1,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":211,"sourceRange":{"startPage":211,"startY":630.22,"endPage":212,"endY":127.76},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":["【重要程度:★☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":14,"excerpts":[{"page":211,"src":"./assets/environment/env838-f392ebcf82d2127e-211.webp"},{"page":212,"src":"./assets/environment/env838-f392ebcf82d2127e-212.webp"}]},{"id":"env838-ef099e964177fde1","subject":"环境学导论","chapter":"第14章 生物多样性","originalChapter":"第14章 生物多样性","originalChapterNumber":14,"section":"第3节 生物多样性损失及其原因","originalSection":"第3节 生物多样性损失及其原因","category":"knowledge","title":"多样性受威胁的制度原因","question":"多样性受威胁的制度原因","type":"简答题","answer":"①虽然国家已把环境保护的成效纳入政绩考核之中，但有些地方\n政府并未把此真正纳入工作计划。\n②对生物多样性有影响的重要部门(如农业、林业、渔业、科研\n机构等)对此缺少相关具体实施细则、行动及专业人员。\n③自然保护区是保护物种及其生境的有效方法，我国已建立数目\n众多的保护区，但相对于国土总面积而言是不够的，而且部分保护区\n管理混乱、土地权属不清等也需要完善\n④在法律制度方面，《自然保护区条例》虽已实施多年，但毕竟\n在法律效力上位阶较低，调整面窄，处罚力度不够，故需要进行新的\n立法以保护自然保护区、物种及其生境。\n⑤在外来生物入侵问题上，虽有一些法规涉及，如《进出境动物\n检疫法》，但没有专门法规对此做相应调整，法律漏洞较大。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":0,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":212,"sourceRange":{"startPage":212,"startY":127.76,"endPage":212,"endY":558.92},"sourceKind":"original","originalOrdinal":"3","sourceMetadata":["【重要程度: ☆☆☆☆☆)"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":14,"excerpts":[{"page":212,"src":"./assets/environment/env838-ef099e964177fde1-212.webp"}]},{"id":"env838-332aecb0e7a91efe","subject":"环境学导论","chapter":"第14章 生物多样性","originalChapter":"第14章 生物多样性","originalChapterNumber":14,"section":"第4节 生物多样性保护","originalSection":"第4节 生物多样性保护","category":"knowledge","title":"自然保护区定义","question":"自然保护区定义","type":"简答题","answer":"自然保护区是指对有代表性的自然生态系统、珍稀濒危野生动植\n物物种的天然集中分布、有特殊意义的自然遗迹等保护对象所在的陆\n地、陆地水域或海域，依法划出一定面积予以特殊保护和管理的区域","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2005],"needsReview":false,"reviewReasons":[],"verified":false,"page":212,"sourceRange":{"startPage":212,"startY":601.9,"endPage":213,"endY":41.57},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":["2005(名,【重要程度:"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":14,"excerpts":[{"page":212,"src":"./assets/environment/env838-332aecb0e7a91efe-212.webp"},{"page":213,"src":"./assets/environment/env838-332aecb0e7a91efe-213.webp"}]},{"id":"env838-fc3302fa165246a3","subject":"环境学导论","chapter":"第14章 生物多样性","originalChapter":"第14章 生物多样性","originalChapterNumber":14,"section":"第4节 生物多样性保护","originalSection":"第4节 生物多样性保护","category":"knowledge","title":"自然保护区的类型","question":"自然保护区的类型","type":"简答题","answer":"①严格自然保护区：一片拥有出众或具代表性的生态系统、地质\n学的或生理学的特色或物种的陆地或海洋区域，可主要用作科学研究\n或环境监察。\n②荒野区：一大片未被人类活动所更动或只被轻微更动过的陆地\n或海洋区域，仍保留着其自然的特点和影响，没有永久性的或显著的\n人类聚居地，受到保护和管理以保存其自然状态。\n③国家公园：一片陆地或海洋的自然区域，即a.保护一个或多个\n生态系统于现今及后代的生态完整性；b.禁止不利于该区域的指定目\n的的开发或侵占；c.为精神的、科学的、教育的、休闲的以及参观的\n机会提供基础，所有机会必须是环境上及文化上兼容的。\n④自然纪念物：一片拥有一个或多个独特的自然或自然文化的特\n色区域，该特色因其固有的珍稀性、代表性、审美性等特质或文化上\n的重要性而具有突出或独特的价值。\n⑤生境/物种管理区：一片因管理目的而受到积极干预以确保生\n物环境的维护与或达到某物种的需求陆地或海洋区域。\n⑥陆地/海洋保护景观：一片陆地及合适的海岸、海洋区域，在该\n区域内人类与自然界的长时间互动使该区拥有重大的审美的、生态的\n或有与众不同的文化价值的特征，并经常有高度的生物多样性。\n⑦资源管理保护区：一个区域拥有占优势地未经更动的自然系统\n，设法确保生物多样性受到长期保护和维持，而同时提供自然产物及\n服务的可持续性供应以满足社区的需要。\n拓展知识 : 中国现行自然保护地体系为 “国家公园、 自然保护区 、 自然公园 ?”\n三大类 。 而书上列出的 7 类是世界自然保护联盟 (IUCN) 的自然保护地管理分\n类体系 ， 典型代表有 :\n@ 严格自然保护区 (IUCN | ak)\n> 陕西周至国家级自然保护区 : 秦岭中段核心区域 ， 保护大熊猫 、 川金丝获\n及其原始森林栖息地 ， 森林履盖率达 96%， 是中国具有全球意义的 A 级像\n护区 ， 核心区几乎无人类干预 ， 主要用于科研监测 。\n> 云南户牢山国家级自然保护区 : 保存我国最完整的中亚热带原始常绿阔叶\n林生态系统 ， 核心区为无人区 ， 是全球生物多样性关键区域 ， 长期用于森\n林生态 、 气候变化等基础研究 。\n> 湖北五峰后河国家级自然保护区 : 武陵山脉生物多样性核心区 ， 保存有中\n国罕见的原始珍贵树种群落 ， 核心区严格管控 ， 是华中地区重要的物种基\n[待核对] AER.\n@ #3B (IUCN 1b 类 )\n> 青海可可西里国家级自然保护区核心区 :青藏高原核心无人区 ,总面积 3.74\n万平方公里 ， 几乎无现代人类活动痕迹 ， 是全球保存最完整的高原荒野生\n态系统 ， 也是藏冷羊等高原特有物种的核心栖息地 。\n> 西藏兑塘国家级自然保护区核心区 : 我国面积最大的自然保护区核心地带\n， 为高原芒漠无人区 ， 无永久居民 ， 完整保存了野将牛 、 藏野驴等大型兽\n类的原始荒野栖息地 。\n> 内蒙古汗马国家级自然保护区核心区 : 我国保存最完整的寒温带原始明亮\n针叶林区 ， 无永久人类聚居地 ， 素加林与闲土复合生态系统保持原生状态\n， 几乎未受人为扰动 。\n@ 国家公园 (IUCN IK) ， 我国五大国家公园\n> 三江源国家公园 ; 我国面积最大的国家公园 ， 保护长江 、 黄河 、 澜沧江源\n头的高原生态系统 ， 兼顾生态保护 、 牧民社区共生与生态体验功能 。\n> 大熊猫国家公园 ; 跨四川 、 陕西 、 甘肃三省 ， 保护大熊猫完整栖息地与亚\n热带森林生态完整性 ， 同时开展自然教育 、 生态旅游等环境兼容活动 。\n> ARLARAB: 世界文化与自然效遗产地 ， 保看完整的亚热带森林生态\n系统 ， 最自生态保护 、 科研教育与生态游移功能 ， 是我国 [| 类保护地的标\n[待核对] He\n[待核对] > HARFSRHEAD: AORZEWORPARLAAR, RPRAKRF\n狭等极度泪危物种 ， 同时支持雨林料普 、 生态体验活动 。\n> 东北虎的国家公园 : 跨吉林 、 黑龙江两省 ， 与俄罗斯 、 朝鲜毗邻 ， 以保护\n野生东北虎 、 东北葛种咯及其温带森林生态系统为核心 ， 总面积 1.41 万\n平方公里 。\n@@ 自然纪念物 (IUCN IX)\n> “云南温江古生物化石群国家级自然保护区 : 寒武纪生命大爆发的核心化石\n产地 ， 是全球独一无二的古生物自然纪念物 ， 记录了早期生命演化的关键\n[待核对] ike.\n> QNSKERADRAARRPE: 欧亚大陆纬度最北 、 海拔最高的天然\nRK, HAWES” 具有极高的演化生物学价值 ， 是珍稀物种类\n自然纪念物代表 。\n[待核对] > 贵州可净山国家级自然保护区 : MABHHERS FT EXRSBSERH\n有物种 ， 兼具地质独特性 、 物种珍稀性与文化价值 ， 是世界自然遗产级别\n的自然纪念物 。\n> ”广东丹霞山世界地质公园 : 丹起地貌的命名地与典型代表 ， 以独特的红层\n峰林地狐为核心自然纪念物 ， 兼具地质科学与美学价值 。\n© 生境 /物种管理区 (IUCN VR)\n> 江苏盐城湿地珍禽国家级自然保护区 : 东亚 - 澳大利西亚候鸟迁飞通道核心\n节点 ， 以丹顶鹤等珍稀水禽为核心保护对象 ， 通过湿地补水 、 生境改造 、\n种群监测实现主动管理 ， 丹顶物种群数量显著提升 。\n> 湖南张家界大够国家级自然保护区 : 全球最大的野生大鲍种群栖息地 ， 通\n过溪流生境修复 、 人工紫育野化 、 流域水质管控等措施 ， 针对性保护中国\n[待核对] 大鲍及其生境 。\n> 黑龙江扎龙国家级自然保护区 : LARBARSEP FH, GLHwR\n[待核对] ALKA, AFGKFLHERFA, PHBA E BERR\n康 。\n© 陆地 /海洋保护景观 (IUCN VA)\n> 黄山国家级风景名胜区 : 世界文化与自然效遗产 ， 干年以来形成了自然景\n观与人文底草融合的山地景观 ， 以花岗岩中林 、 云海禁松为核心特色 ， 是\n我国保护景观的典型代表 ， 已入选 ITUCN 绿色名录 。\n九寨沟国家级风景名胜区 : 以高山湖泊群 、 钙化漯布群为核心的高原景观\n， 融合了藏族人文与自然生态 ， 是世界自然遗产级别的陆地保护景观 。\n新疆天山博格达片区 : 集委直自然景观带 、 游牧文化于一体的山地保护景\n观 , 完整保存了干旱区山地生态系统与人文互动的特征 ,入选 IUCN 绿色名\n录 。\n杭州西溪国家湿地公园 : 城市湿地与江南水乡文化融合的代表 ， 是人与自\n然长期互动形成的湿地景观 ， 兼顾生态保护与生态游趟 。\n@ 资源管理保护区 (IUCN VI 类 )\n> 东北重点国有天然林保护区 : 全面停止商业来伐 ， 保护森林生态系统与水\n源涵养功能 ， 同时通过林下经济 、 生态补偿 、 生态公益岗位实现社区可持\n续发展 ， 是我国面积最大的 VI 类保护地体系 。\n长江流域十年禁渔区 ;: 以保护长江水生生物多样性为核心目标 ， 通过禁兆\n管控恢复渔业资源 ， 同时配套转产安置 、 生态补奖政策 ， 保障沿岸社区生\n计 ， 实现水生资源的长期可持续管理 。\n国家重点公益林区 : 履盖全国的大面积公益林 ， 以保护水源涵养 、 土壤保\n持 、 生物多样性为核心 ， 同时允许适度的非木质林产品采集 、 生态旅游等\n可持续利用方式 。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":1,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。","含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":213,"sourceRange":{"startPage":213,"startY":41.57,"endPage":216,"endY":661.96},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":["【重要程度:★☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":14,"excerpts":[{"page":213,"src":"./assets/environment/env838-fc3302fa165246a3-213.webp"},{"page":214,"src":"./assets/environment/env838-fc3302fa165246a3-214.webp"},{"page":215,"src":"./assets/environment/env838-fc3302fa165246a3-215.webp"},{"page":216,"src":"./assets/environment/env838-fc3302fa165246a3-216.webp"}]},{"id":"env838-0bb04460b2b2a782","subject":"环境学导论","chapter":"第14章 生物多样性","originalChapter":"第14章 生物多样性","originalChapterNumber":14,"section":"第4节 生物多样性保护","originalSection":"第4节 生物多样性保护","category":"knowledge","title":"生物多样性的保护措施","question":"生物多样性的保护措施","type":"简答题","answer":"[1]建设自然保护区完善保护制度\n保护生物多样性，最有效的方法之一是划定保护区。建立自然公\n园和自然保护区已成为世界各国保护自然生态和野生动植物免于灭\n绝并得以繁衍的主要手段。我国的神农架、卧龙等自然保护区，对金\n丝猴、熊猫等珍稀、濒危物种的保护和繁殖发挥了重要的作用。\n[2]外来入侵物种防治和建立外来物种管理法规体系\n外来物种入侵不仅对当地生物构成威胁，同时对经济和人体健康带\n来不可估量的损失， 因此一些国家对此进行了立法\n[3]生态示范区建设\n[4]国际合作与行动\n在生物多样性问题上，世界各国的共识是生物多样性问题不是局部\n的、地区的问题，而是全球性的问题。积极开展国际合作，并制定相\n关的实施计划与细则，在必要的情况下制定相关行政法规或法律。\n[5]增强宣传和保护生物多样性\n加强民众教育，广泛、通俗、持之以恒地开展与环境相关的文化教\n育、法律宣传，培育本地化的亲生态人口，利用当地文化、习俗、传\n统、信仰、宗教和习惯中的环保意识和思想进行宣传教育。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2025],"needsReview":false,"reviewReasons":[],"verified":false,"page":216,"sourceRange":{"startPage":216,"startY":661.96,"endPage":217,"endY":542.17},"sourceKind":"original","originalOrdinal":"3","sourceMetadata":["2025(简—出自课后题)，【重要程度： 】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":14,"excerpts":[{"page":216,"src":"./assets/environment/env838-0bb04460b2b2a782-216.webp"},{"page":217,"src":"./assets/environment/env838-0bb04460b2b2a782-217.webp"}]},{"id":"env838-dd32138118e11f75","subject":"环境学导论","chapter":"第14章 生物多样性","originalChapter":"第14章 生物多样性","originalChapterNumber":14,"section":"第5节 生物多样性保护优先领域与行动","originalSection":"第5节 生物多样性保护优先领域与行动","category":"knowledge","title":"生物多样性保护战略目标","question":"生物多样性保护战略目标","type":"简答题","answer":"(1)近期目标。力争使重点区域生物多样性下降的趋势得到有\n效遏制。初步建立生物多样性监测、评估与预警体系、生物物种资源\n出入境管理制度以及生物遗传资源获取与惠益共享制度。\n(2)中期目标。努力使生物多样性的丧失与流失得到基本控制\n。生物多样性保护优先区域的本底调查与评估全面完成，并实施有效\n-197。\n监控。基本建成布局合理、功能完善的自然保护区体系，国家级自然\n保护区功能稳定，主要保护对象得到有效保护。生物多样性监测、评\n估与预警体系、生物物种资源出入境管理制度以及生物遗传资源获取\n与惠益共享制度得到完善。\n(3 )远景目标。使生物多样性得到切实保护。各类保护区域数\n量和面积达到合理水平，生态系统、物种和遗传多样性得到有效保护\n。形成完善的生物多样性保护政策法律体系和生物资源可持续利用机\n制，保护生物多样性成为公众的自觉行动。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":0,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":217,"sourceRange":{"startPage":217,"startY":584.58,"endPage":219,"endY":71.85},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":["【重要程度: ☆☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":14,"excerpts":[{"page":217,"src":"./assets/environment/env838-dd32138118e11f75-217.webp"},{"page":218,"src":"./assets/environment/env838-dd32138118e11f75-218.webp"},{"page":219,"src":"./assets/environment/env838-dd32138118e11f75-219.webp"}]},{"id":"env838-e1182462a87f2462","subject":"环境学导论","chapter":"第14章 生物多样性","originalChapter":"第14章 生物多样性","originalChapterNumber":14,"section":"第6节 课后习题","originalSection":"第6节 课后习题","category":"exercise","title":"什么是生物多样性?","question":"什么是生物多样性?","type":"简答题","answer":"整理答案（按教材对应知识点摘录）：\n\n生物多样性的概念：\n生物多样性是指在一定时间和一定地区所有生物物种及其遗传\n变异和生态系统的复杂性的总称。它包括基因多样性、物种多样性和\n生态系统多样性三个层次。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["根据所列知识点摘录整理，未逐题人工审定。"],"verified":false,"page":219,"sourceRange":{"startPage":219,"startY":112.13,"endPage":219,"endY":192.95},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":14,"references":[{"id":"env838-8090a1831d837c12","title":"生物多样性的概念","source":"环境学导论.pdf","page":42}],"excerpts":[{"page":219,"src":"./assets/environment/env838-e1182462a87f2462-219.webp"}]},{"id":"env838-a7f1fa6f08247e79","subject":"环境学导论","chapter":"第14章 生物多样性","originalChapter":"第14章 生物多样性","originalChapterNumber":14,"section":"第6节 课后习题","originalSection":"第6节 课后习题","category":"exercise","title":"生物多样性的价值有哪些?","question":"生物多样性的价值有哪些?","type":"简答题","answer":"①直接使用价值：食物、木材、药用物质、遗传育种资源，以及旅游和文化体验等。\n②间接使用价值：授粉、水质净化、气候调节、水土保持、营养循环及灾害缓冲等生态系统服务。\n③选择价值：保留未来利用或认识遗传资源及物种的机会。\n④非使用价值：人们对物种存在及留给后代的重视，也体现自然保护的伦理意义。\n不同价值可能难以完整货币化。保护决策应关注生态系统整体及不可逆损失，不能只比较眼前市场收入。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":219,"sourceRange":{"startPage":219,"startY":192.95,"endPage":219,"endY":273.26},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":14,"excerpts":[{"page":219,"src":"./assets/environment/env838-a7f1fa6f08247e79-219.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=207"},{"title":"中国生物多样性保护战略与行动计划（2023—2030年）发布说明","url":"https://www.mee.gov.cn/xxgk/hjyw/202401/t20240118_1064111.shtml","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-13b1659c53f71135","subject":"环境学导论","chapter":"第14章 生物多样性","originalChapter":"第14章 生物多样性","originalChapterNumber":14,"section":"第6节 课后习题","originalSection":"第6节 课后习题","category":"exercise","title":"我国生物多样性的特点是什么?生物多样性受到了何种威胁?","question":"我国生物多样性的特点是什么?生物多样性受到了何种威胁?","type":"简答题","answer":"特点：我国地域广、气候和地形复杂，生物区系与生态系统类型多样，物种及遗传资源丰富，特有和古老类群较多，重要生境空间差异明显。\n威胁：生境丧失、退化和破碎化，部分物种过度利用，污染与不合理开发，外来入侵，以及气候变化等。\n这些压力会相互叠加，并通过食物网和生态服务影响社会经济。\n保护重点不只是增加某一物种数量，还应保护其生境、遗传多样性及生态过程，兼顾保护地外的农业、城市和其他利用空间。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":219,"sourceRange":{"startPage":219,"startY":273.26,"endPage":219,"endY":355.08},"sourceKind":"original","originalOrdinal":"3","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":14,"excerpts":[{"page":219,"src":"./assets/environment/env838-13b1659c53f71135-219.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=207"},{"title":"中国生物多样性保护战略与行动计划（2023—2030年）发布说明","url":"https://www.mee.gov.cn/xxgk/hjyw/202401/t20240118_1064111.shtml","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-5fe0ecba337fafe1","subject":"环境学导论","chapter":"第14章 生物多样性","originalChapter":"第14章 生物多样性","originalChapterNumber":14,"section":"第6节 课后习题","originalSection":"第6节 课后习题","category":"exercise","title":"我国生物多样性保护的战略目标是什么?","question":"我国生物多样性保护的战略目标是什么?","type":"简答题","answer":"可按《中国生物多样性保护战略与行动计划（2023—2030年）》的总体方向回答：保护生物多样性，促进可持续利用和惠益分享，并将保护要求纳入发展与治理。\n2030年阶段应重点推进：完善政策法规、调查监测和评价，保护重要物种与生境，提高保护地及生态空间的保护效果，修复受损生态系统，控制污染、过度利用和入侵等压力，提升全社会参与及履约能力。\n长远目标是维护生态系统结构、功能与服务，推进人与自然和谐共生。\n若题目要求某一旧版规划的具体指标，应标明规划名称和年份，避免把不同阶段的数字混用。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":219,"sourceRange":{"startPage":219,"startY":355.08,"endPage":219,"endY":435.35},"sourceKind":"original","originalOrdinal":"4","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":14,"excerpts":[{"page":219,"src":"./assets/environment/env838-5fe0ecba337fafe1-219.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=207"},{"title":"中国生物多样性保护战略与行动计划（2023—2030年）发布说明","url":"https://www.mee.gov.cn/xxgk/hjyw/202401/t20240118_1064111.shtml","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-e8253f9015a1091b","subject":"环境学导论","chapter":"第14章 生物多样性","originalChapter":"第14章 生物多样性","originalChapterNumber":14,"section":"第6节 课后习题","originalSection":"第6节 课后习题","category":"exercise","title":"目前我国有哪些生物多样性保护区域?","question":"目前我国有哪些生物多样性保护区域?","type":"简答题","answer":"保护区域可从两方面回答：\n①自然保护地体系：以国家公园为主体，自然保护区为基础，各类自然公园为补充，保护典型生态系统、珍稀濒危物种及重要自然遗迹等。\n②其他重要生态空间：生态保护红线区域、重要湿地、关键物种栖息地及生态廊道等；这些空间与保护地可能重叠，不能简单相加。\n实例：三江源、大熊猫、东北虎豹、海南热带雨林和武夷山等国家公园。\n还应通过植物园、种质资源库等迁地保护补充就地保护；迁地设施不是自然保护区的同义概念。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":219,"sourceRange":{"startPage":219,"startY":435.35,"endPage":219,"endY":516.48},"sourceKind":"original","originalOrdinal":"5","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":14,"excerpts":[{"page":219,"src":"./assets/environment/env838-e8253f9015a1091b-219.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=207"},{"title":"中国生物多样性保护战略与行动计划（2023—2030年）发布说明","url":"https://www.mee.gov.cn/xxgk/hjyw/202401/t20240118_1064111.shtml","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-8b90323bd557a1e3","subject":"环境学导论","chapter":"第14章 生物多样性","originalChapter":"第14章 生物多样性","originalChapterNumber":14,"section":"第6节 课后习题","originalSection":"第6节 课后习题","category":"exercise","title":"生物多样性损失的原因有哪些?如何保护生物多样性?","question":"生物多样性损失的原因有哪些?如何保护生物多样性?","type":"简答题","answer":"原因：①土地利用变化造成生境丧失、退化和破碎化；②过度捕捞、采集或其他利用；③污染；④外来入侵；⑤气候变化，以及监管、经济激励和知识信息等方面的不足。\n措施：优先保护关键生境和生态过程，完善保护地及生态廊道；恢复退化生态系统，控制污染和不合理利用；加强入侵预防及生物安全；开展濒危物种、遗传资源和迁地保护；完善调查监测、执法、生态补偿及社区参与。\n保护应兼顾基因、物种与生态系统三个层次，而不是只关注少数旗舰物种。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":219,"sourceRange":{"startPage":219,"startY":516.48,"endPage":219,"endY":598.99},"sourceKind":"original","originalOrdinal":"6","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":14,"excerpts":[{"page":219,"src":"./assets/environment/env838-8b90323bd557a1e3-219.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=207"},{"title":"中国生物多样性保护战略与行动计划（2023—2030年）发布说明","url":"https://www.mee.gov.cn/xxgk/hjyw/202401/t20240118_1064111.shtml","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-7d5d80a2169b898f","subject":"环境学导论","chapter":"第14章 生物多样性","originalChapter":"第14章 生物多样性","originalChapterNumber":14,"section":"第6节 课后习题","originalSection":"第6节 课后习题","category":"exercise","title":"举例说明我国生物多样性的保护措施。","question":"举例说明我国生物多样性的保护措施。","type":"简答题","answer":"①国家公园和自然保护区：通过空间保护、巡护及栖息地管理，保护关键生态系统和物种。\n②生态廊道与修复：提高破碎生境连通性，修复湿地、河湖或退化森林等自然过程。\n③物种及遗传资源保护：就地保护结合种质保存、繁育及适宜的野外恢复。\n④治理与参与：防控非法利用、污染和入侵，加强监测及社区共同管理。\n案例答法：以大熊猫国家公园说明跨区域整合栖息地保护，以海南热带雨林国家公园说明热带森林及珍稀物种保护；讨论其效果时应使用实际监测资料，不编造种群增幅。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":219,"sourceRange":{"startPage":219,"startY":598.99,"endPage":220,"endY":46.99},"sourceKind":"original","originalOrdinal":"7","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":14,"excerpts":[{"page":219,"src":"./assets/environment/env838-7d5d80a2169b898f-219.webp"},{"page":220,"src":"./assets/environment/env838-7d5d80a2169b898f-220.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=207"},{"title":"中国生物多样性保护战略与行动计划（2023—2030年）发布说明","url":"https://www.mee.gov.cn/xxgk/hjyw/202401/t20240118_1064111.shtml","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-4d6558a55391de12","subject":"环境学导论","chapter":"第15章 工农业生态系统保护","originalChapter":"第15章 工业生态系统构建","originalChapterNumber":15,"section":"第1节 工业生态","originalSection":"第1节 工业生态学与工业生态系统的概念","category":"knowledge","title":"工业生态学的定义","question":"工业生态学的定义","type":"简答题","answer":"工业生态学是一种工具。在经济、文化和技术不断进步的情况下\n，利用这种工具，通过精心策划、合理安排，使环境负荷保持在所希\n望的水平上。为此，要把工业系统同它周围的环境协调起来，而不是\n把它看成孤立于环境之外的独立系统。\n拓展知识点一丹去卡伦堡生态工业园 ]\n[待核对] FAME RIN Ath Ih, BLK 05 fo ah — Re at\n[待核对] HELE, BERS RH\" ERT ALLL RR\": RRRSKS\n[待核对] HERR, RAPLWS ELSES RT RRA, 1B LODE EEK\n泥厂 。 国区里苗制药厂产生的有枫污泥雪成肥衬 。 炼油厂的废气送给发电厂当\n撕衬 。 就舍这种 \"你家的垃圾是我家的宝页 \"的模式 ， 整个园区每年省油 1.9 万吨\n、 省煤 3 万吨 、 减 CO? BAe 企业省了钱 ; 环境减了压 ， 居民享了福 -一经济\n效益 、 生太效益 、 社会效益全齐了 :是工业生态学的活教材。\n15-1 卡伦堡生态工业园物质循环示意图","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":1,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。","含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":221,"sourceRange":{"startPage":221,"startY":99.55,"endPage":222,"endY":59.56},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":["【重要程度: ★☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":15,"newSectionOrder":1,"newPointOrder":1,"excerpts":[{"page":221,"src":"./assets/environment/env838-4d6558a55391de12-221.webp"},{"page":222,"src":"./assets/environment/env838-4d6558a55391de12-222.webp"}]},{"id":"env838-bddeaa79a0146500","subject":"环境学导论","chapter":"第15章 工农业生态系统保护","originalChapter":"第15章 工业生态系统构建","originalChapterNumber":15,"section":"第1节 工业生态","originalSection":"第1节 工业生态学与工业生态系统的概念","category":"knowledge","title":"工业生态系统概念","question":"工业生态系统概念","type":"简答题","answer":"工业生态系统是依据生态学、经济学、技术科学以及系统科学的\n基本原理与方法来经营，和管理工业经济活动，并以节约资源、保护\n生态环境和提高物质综合利用为特征的现代工业发展模式，是由社会\n、经济、环境三个子系统复合而成的有机整体。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":222,"sourceRange":{"startPage":222,"startY":529.12,"endPage":222,"endY":730.85},"sourceKind":"original","originalOrdinal":"3","sourceMetadata":["【重要程度："],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":15,"newSectionOrder":1,"newPointOrder":2,"excerpts":[{"page":222,"src":"./assets/environment/env838-bddeaa79a0146500-222.webp"}]},{"id":"env838-2265b3ccfe244dba","subject":"环境学导论","chapter":"第15章 工农业生态系统保护","originalChapter":"第15章 工业生态系统构建","originalChapterNumber":15,"section":"第1节 工业生态","originalSection":"第2节 工业生态系统的特征","category":"knowledge","title":"工业生态系统的特征","question":"工业生态系统的特征","type":"简答题","answer":"工业生态系统兼有社会属性和自然属性两方面的特征。从自然属\n性看，工业作为复合生态系统的重要组成部分，既是复合系统持续的\n重要力量，又是复合系统遭受毁灭的力量，工业系统及其中人、组织\n的行为不能违背自然生态系统的规律，都应受到自然条件的负反馈约\n束和调节。从社会属性来看，工业系统中的人及其组织之间的关系是\n复杂的利益关系，人及其组织为了最大可能地获取经济利益往往损害\n自然生态系统。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":0,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":226,"sourceRange":{"startPage":226,"startY":568.61,"endPage":227,"endY":130.77},"sourceKind":"original","originalOrdinal":"6","sourceMetadata":["【重要程度: ☆☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":15,"newSectionOrder":1,"newPointOrder":3,"excerpts":[{"page":226,"src":"./assets/environment/env838-2265b3ccfe244dba-226.webp"},{"page":227,"src":"./assets/environment/env838-2265b3ccfe244dba-227.webp"}]},{"id":"env838-4afb8240ac13da0a","subject":"环境学导论","chapter":"第15章 工农业生态系统保护","originalChapter":"第15章 工业生态系统构建","originalChapterNumber":15,"section":"第1节 工业生态","originalSection":"第1节 工业生态学与工业生态系统的概念","category":"knowledge","title":"工业生态系统的组成","question":"工业生态系统的组成","type":"简答题","answer":"与自然生态系统相似，工业生态系统主要由生产者、消费者、分\n解者和非生物环境4种基本成分组成。\n(1) 生产者\n工业系统中的生产者可分为初级生产者和高级生产者。初级生产\n者为利用基本环境要素(空气、水、矿物质等自然资源)生产初级产\n品，如采矿厂、冶炼厂、热电厂等：高级生产者进行初级产品的深度\n加工和高级产品生产，如化工、肥料制造、服装和食品加工等。\n(2) 消费者\n不直接生产“物质化”产品，但利用生产者提供的产品，供自身\n运行发展，同时产生生产力和服务功能等，如行政、商业、服务业等\n(3) 分解者\n把工业企业产生的废产品和“废物”进行处理、转化、再利用等\n，如废物回收公司、资源再生公司等。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":222,"sourceRange":{"startPage":222,"startY":730.85,"endPage":223,"endY":481.39},"sourceKind":"original","originalOrdinal":"4","sourceMetadata":["【重要程度："],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":15,"newSectionOrder":1,"newPointOrder":4,"excerpts":[{"page":222,"src":"./assets/environment/env838-4afb8240ac13da0a-222.webp"},{"page":223,"src":"./assets/environment/env838-4afb8240ac13da0a-223.webp"}]},{"id":"env838-0cb26ff207a9f532","subject":"环境学导论","chapter":"第15章 工农业生态系统保护","originalChapter":"第15章 工业生态系统构建","originalChapterNumber":15,"section":"第1节 工业生态","originalSection":"第2节 工业生态系统的特征","category":"knowledge","title":"工业生态系统与自然生态系统的相似性","question":"工业生态系统与自然生态系统的相似性","type":"简答题","answer":"(1 )两者都包含物质循环和能量流动。工业生态系统也存在着\n物质、能量和信息的流动与储存，形成互利共生网络，实现物质闭路\n循环和能量多级利用。\n(2)两者均存在的“内在动力”。自然生态系统中的各个物种\n的存在目的主要是为了自己的生存和繁衍，工业生态系统中各个企业\n存在的主要目的在于降低成本，提高竞争力获得最大利润，更好、更\n有利地占领市场。\n(3 )两者的演化过程都是动态的。工业生态系统各成员通过相\n互间的合作与竞争实现共同进化，通过系统员或子系统之间协同作用\n，使互相依存的各子系统交互运动、自我调节、协同进化，最后形成\n新的有序结构。工业生态系统一直处在变化之中，这种连续的变化可\n以称之为工业生态系统的动态演替。\n(4)两者都有一个“关键种”。“关键种企业”，它们使用和传\n输的物质最多、能量流动的规模最为庞大，能为该工业生态系统其他\n成员提供关键性的利润。“关键种”企业在工业生态系统中有着举足\n轻重的地位，它拥有特殊的能力和资源，往往决定着整个企业生态系\n统的形成与完善，影响生态系统功能的发挥。\n(5)两者的系统成员间都存在共生关系。工业共生是指不同企\n业通过合作，共同提高企业的生存及获利能力，同时实现对资源的节\n约和对环境的保护。企业共生也能产生“一加一大于二”的效果，这\n表现为共生企业竞争力的增强。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":227,"sourceRange":{"startPage":227,"startY":368.13,"endPage":228,"endY":334.49},"sourceKind":"original","originalOrdinal":"8","sourceMetadata":["【重要程度："],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":15,"newSectionOrder":1,"newPointOrder":5,"excerpts":[{"page":227,"src":"./assets/environment/env838-0cb26ff207a9f532-227.webp"},{"page":228,"src":"./assets/environment/env838-0cb26ff207a9f532-228.webp"}]},{"id":"env838-6cf5f9946c11a404","subject":"环境学导论","chapter":"第15章 工农业生态系统保护","originalChapter":"第15章 工业生态系统构建","originalChapterNumber":15,"section":"第1节 工业生态","originalSection":"第2节 工业生态系统的特征","category":"knowledge","title":"工业生态系统的双重性的定义","question":"工业生态系统的双重性的定义","type":"简答题","answer":"工业生态系统的双重性指工业生态系统不仅受到生态学规律的\n约束，同时更受到市场经济规律的制约。人类通过社会、经济、技术\n力量干预物质、能量、技术的输入和产品的输出的生活过程，在进行\n物质生产的同时，也进行经济再生产过程，不仅要有较高的物质生产\n量，而且也要有较高的经济效益。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":227,"sourceRange":{"startPage":227,"startY":130.77,"endPage":227,"endY":368.13},"sourceKind":"original","originalOrdinal":"7","sourceMetadata":["【重要程度:☆☆☆☆"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":15,"newSectionOrder":1,"newPointOrder":6,"excerpts":[{"page":227,"src":"./assets/environment/env838-6cf5f9946c11a404-227.webp"}]},{"id":"env838-aa475663f2ba90a4","subject":"环境学导论","chapter":"第15章 工农业生态系统保护","originalChapter":"第15章 工业生态系统构建","originalChapterNumber":15,"section":"第2节 生态工业","originalSection":"第3节 工业生态系统的构建","category":"knowledge","title":"生态工业的定义","question":"生态工业的定义","type":"简答题","answer":"生态工业是一种根据工业生态学基本原理建立的、符合生态系统\n环境承载能力、物质和能量高效组合利用以及工业生态功能稳定协调\n的新型工业组合和发展形态。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":228,"sourceRange":{"startPage":228,"startY":377.43,"endPage":228,"endY":552.66},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":["【重要程度："],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":15,"newSectionOrder":2,"newPointOrder":1,"excerpts":[{"page":228,"src":"./assets/environment/env838-aa475663f2ba90a4-228.webp"}]},{"id":"env838-6e0b746bbe0ee381","subject":"环境学导论","chapter":"第15章 工农业生态系统保护","originalChapter":"第15章 工业生态系统构建","originalChapterNumber":15,"section":"第2节 生态工业","originalSection":"第3节 工业生态系统的构建","category":"knowledge","title":"生态效率的定义","question":"生态效率的定义","type":"简答题","answer":"提供有价格竞争优势的、满足人类需求和保证生活质量的产品或\n服务，同时能逐步降低产品或服务生命周期的生态影响和资源强度，\n其降低程度要与估算的地球承载力相一致。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":0,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":228,"sourceRange":{"startPage":228,"startY":552.66,"endPage":228,"endY":723.24},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":["【重要程度:☆☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":15,"newSectionOrder":2,"newPointOrder":2,"excerpts":[{"page":228,"src":"./assets/environment/env838-6e0b746bbe0ee381-228.webp"}]},{"id":"env838-90cedaf48d939e8d","subject":"环境学导论","chapter":"第15章 工农业生态系统保护","originalChapter":"第15章 工业生态系统构建","originalChapterNumber":15,"section":"第2节 生态工业","originalSection":"第3节 工业生态系统的构建","category":"knowledge","title":"工业生态系统的构建措施","question":"工业生态系统的构建措施","type":"简答题","answer":"(1)污染趋零排放。生态工业的最高目标是使所有物质都能循\n环利用，向环境中排放的污染物极小或零排放。\n(2)物质闭路循环。从技术经济合理的角度，物质的闭路循环\n应该是有限度的。一方面，过高的闭路循环会显著增加企业的生产成\n本，降低企业产品的市场竞争力；另一方面，与自然生态系统的闭路\n循环相反，生态工业系统的闭路循环会降低产品的质量。\n(3)废物资源利用。生态工业要求把一些企业的副产品作为另\n一些企业的原料或资源加以重新利用，而不是把它作为“废物”废弃\n掉。相对污染零排放和闭路循环利用而言，资源重新利用在技术上比\n较容易解决。\n(4)消耗性污染降低。消耗性污染指产品在使用消耗过程中产\n生的污染。防止消耗性污染主要有3种手段：一是改变生产原料，从\n源头降低污染的潜在机会；二是在技术方法上回收利用，根据“分子\n租用”的概念，用户只购买产品的功能，而不购买产品的分子本身；\n三是直接用无害化合物替代有害物质材料，对某些危害或风险极大的\n污染物质禁止使用。\n(5)产品与服务的非物质化。生态工业中非物质化的概念指通\n过小型化、轻型化、使用循环材料和部件以及提高产品寿命，在相同\n甚至更少的物质基础上获取最大的产品和服务，或者在获取相同的产\n品和服务功能时，实现物质和能量的投入最小化。\n(6)园区生态管理。生态工业园区是生态工业发展的最佳组合\n模式，而管理模式的选择将直接影响园区的生态工业特性。建立工业\n园区的生态管理体系可以从以下三个层次着手：第一个层次是产品层\n次，要求园区企业尽可能根据产品生命周期分析、生态设计和环境标\n志产品要求，开发和生产低能耗、低消耗、低(或无)污染、经久耐\n用、可维修、可再循环和能够进行安全处置的产品；第二个层次是园\n区的企业，尽可能在企业本身实现清洁生产和污染零排放，同时建立\n环境管理体系；第三个层次是园区层次，建立园区水平上的环境管理\n体系、园区APELL计划、园区废物交换系统以及园区的生态信息公告\n制度等。\n(7)管理制度完善。目前与生态工业有关的法规有2类：一是从\n正面提倡和要求建立生态工业；二是从反面约束和控制非生态工业的\n副作用。实际上，两者都对生态工业的建立起到促进作用。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":0,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":229,"sourceRange":{"startPage":229,"startY":194.17,"endPage":230,"endY":512.07},"sourceKind":"original","originalOrdinal":"4","sourceMetadata":["【重要程度: ☆☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":15,"newSectionOrder":2,"newPointOrder":3,"excerpts":[{"page":229,"src":"./assets/environment/env838-90cedaf48d939e8d-229.webp"},{"page":230,"src":"./assets/environment/env838-90cedaf48d939e8d-230.webp"}]},{"id":"env838-a12eb287d7489b8f","subject":"环境学导论","chapter":"第15章 工农业生态系统保护","originalChapter":"第15章 工业生态系统构建","originalChapterNumber":15,"section":"第2节 生态工业","originalSection":"第3节 工业生态系统的构建","category":"knowledge","title":"生态工业园的定义","question":"生态工业园的定义","type":"简答题","answer":"生态工业园是保持自然与经济资源，减少生产、材料、能源、保\n险与治理费用和负债，提高操作效率、质量、工人健康和公众形象，\n提供废料利用及其规模的收益机会的工业系统。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":1,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":230,"sourceRange":{"startPage":230,"startY":512.07,"endPage":230,"endY":684.65},"sourceKind":"original","originalOrdinal":"5","sourceMetadata":["【重要程度:★☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":15,"newSectionOrder":2,"newPointOrder":4,"excerpts":[{"page":230,"src":"./assets/environment/env838-a12eb287d7489b8f-230.webp"}]},{"id":"env838-4df876d9a92972f3","subject":"环境学导论","chapter":"第15章 工农业生态系统保护","originalChapter":"第15章 工业生态系统构建","originalChapterNumber":15,"section":"第2节 生态工业","originalSection":"第3节 工业生态系统的构建","category":"knowledge","title":"生态工业园区特征","question":"生态工业园区特征","type":"简答题","answer":"①主题明确.但不只是围绕单一主题而设计、运行，在设计工业\n园同时考虑社区：\n②通过毒物替代、 吸收、材料交换和废物统一处理来减少环\n境影响或生态破坏.但生态工业园不单纯是环境技术公司或绿色产品\n公司的集合：\n③通过能源层叠实现能量效率最大化；\n④通过回收、再生和循环对材料进行可持续利用；\n⑤在生态工业园定位的社区以供求关系形成网络，而不是单一的\n副产物或废物交换模式或交换网络；\n⑥具有环境基础设施或建设，企业、工业园和整个社区的环境状\n况得到持续改善；\n⑦拥有规范体系，允许一定灵活性而且鼓励成员适应整体运行目\n标：\n⑧应用减废减污的经济型设备：\n⑨应用便于能量和物质在密封管线内流动的信息管理系统；\n⑩准确定位生态工业园及其成员市场，同时吸收那些能填补适当\n位置和开展其他业务环节的企业。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":230,"sourceRange":{"startPage":230,"startY":684.65,"endPage":231,"endY":564.24},"sourceKind":"original","originalOrdinal":"6","sourceMetadata":["【重要程度: ★★★★】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":15,"newSectionOrder":2,"newPointOrder":5,"excerpts":[{"page":230,"src":"./assets/environment/env838-4df876d9a92972f3-230.webp"},{"page":231,"src":"./assets/environment/env838-4df876d9a92972f3-231.webp"}]},{"id":"env838-620d82da08664cf4","subject":"环境学导论","chapter":"第15章 工农业生态系统保护","originalChapter":"第15章 工业生态系统构建","originalChapterNumber":15,"section":"第2节 生态工业","originalSection":"第3节 工业生态系统的构建","category":"knowledge","title":"生态工业园的规划设计原则","question":"生态工业园的规划设计原则","type":"简答题","answer":"(1)生态链原则。设计生态工业园必须首先考虑生态工业园成\n员间在物质和能量的使用上是否形成类似自然生态系统的生态链或\n食物链，只有这样才能实现物质与能量的封闭循环和废物最少化。\n(2)整体性与个体性统一原则。生态工业园既追求工业园整体\n乃至整个区域的经济和环境效益，也追求成员自身的经济效益和环境\n~211.\n绩效。从操作、运行和管理上，使物质和能量流动以发信息变流荏璧\n个园区内形成快捷、顺畅的网络，成员间以市场原则进行联系以像现\n个性。\n(3)多样性原则。园区成员组成和相互间的联系要多样化，品\n且要有创新性，不能一成不变，这样才能保证工业生态系统的平衡和\n稳定发展。\n(4)多功能性原则。经济、社会和环境的和谐是可持续发展的\n基础，是工业生态学的基本目标。因此，生态工业园必须兼备经济、\n社会和环境的多种功能和多重效益，\n(5)组织和联系的高效性原则。生态工业园的设计在于形成高\n效的工作系统，其内部有着很好的友邻关系。园区通道和管道应靠近\n副产物、废物或能量的供应者和利用者，在保证物资流通的同时保证\n信息交流的顺畅。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":0,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":231,"sourceRange":{"startPage":231,"startY":564.24,"endPage":232,"endY":449.23},"sourceKind":"original","originalOrdinal":"7","sourceMetadata":["【重要程度:☆☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":15,"newSectionOrder":2,"newPointOrder":6,"excerpts":[{"page":231,"src":"./assets/environment/env838-620d82da08664cf4-231.webp"},{"page":232,"src":"./assets/environment/env838-620d82da08664cf4-232.webp"}]},{"id":"env838-6276211c7eb7eedc","subject":"环境学导论","chapter":"第15章 工农业生态系统保护","originalChapter":"第15章 工业生态系统构建","originalChapterNumber":15,"section":"第2节 生态工业","originalSection":"第3节 工业生态系统的构建","category":"knowledge","title":"生态工业园区的规划设计内容","question":"生态工业园区的规划设计内容","type":"简答题","answer":"(1)能源利用。有效的能源利用是削减费用和环境负担的主要\n战略。在生态工业园中，不仅单个公司寻求各自的电能、蒸汽或热水\n等使用的更大效率，而且在相互间实现所谓“能量层叠”，如蒸汽在\n工厂与同一地区家庭用户间的连接。\n(2)物质流动。把废物作为潜在的原料，在生态工业园的成员\n间相互利用或推销其他企业使用。不论对成员个体或整个社区，都应\n当优化所有物质的使用和减少有毒物质的使用。生态工业园基础设施\n应当为成员提供中间产品转移的功能，提供库存场所和普通毒物的处\n理设施。\n(3)水流动。整个生态工业园所需用水的大部分应当在基础设\n施中流动和层叠，这样有利于提高水循环使用的效率。而且，生态工\n业园在设计时应当考虑建立具有收集和使用雨水的设施。\n(4)管理与支持服务。要具有较传统工业园更复杂的管理和支\n持系统管理支持各企业之间副产物的交换，具有同区域副产物交换场\n所的联系和本区域范围内的远程通讯系统。生态工业园还应包括培训\n中心、日常保健中心、运输后勤办公室等。公司可以通过这些服务的\n共享来进一步节省开支。\n(5)其他。此外，生态工业园还应有土地使用和景观学方面的\n设计内容，即对生态工业园的土地使用、建筑、基础设施、视觉效果\n、环境质量、绿化、土壤、水文、景观、照明、交通和周边环境等多\n方面加以考虑和设计。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":0,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":232,"sourceRange":{"startPage":232,"startY":449.23,"endPage":234,"endY":49.41},"sourceKind":"original","originalOrdinal":"8","sourceMetadata":["【重要程度:☆☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":15,"newSectionOrder":2,"newPointOrder":7,"excerpts":[{"page":232,"src":"./assets/environment/env838-6276211c7eb7eedc-232.webp"},{"page":233,"src":"./assets/environment/env838-6276211c7eb7eedc-233.webp"},{"page":234,"src":"./assets/environment/env838-6276211c7eb7eedc-234.webp"}]},{"id":"env838-ff9362071a0be0e3","subject":"环境学导论","chapter":"第15章 工农业生态系统保护","originalChapter":"第16章 农业生态系统","originalChapterNumber":16,"section":"第3节 农业生态","originalSection":"第1节 农业生态系统","category":"knowledge","title":"农业生态系统的概念/定义","question":"农业生态系统的概念/定义","type":"简答题","answer":"由一定农业地域内相互作用的生物因素和非生物因素构成的功\n能整体，人类生产活动干预下形成的人工生态系统。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":1,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":236,"sourceRange":{"startPage":236,"startY":191.34,"endPage":236,"endY":334.26},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":["【重要程度:★☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":15,"newSectionOrder":3,"newPointOrder":1,"excerpts":[{"page":236,"src":"./assets/environment/env838-ff9362071a0be0e3-236.webp"}]},{"id":"env838-ac61b1b1d5fbcf9b","subject":"环境学导论","chapter":"第15章 工农业生态系统保护","originalChapter":"第16章 农业生态系统","originalChapterNumber":16,"section":"第3节 农业生态","originalSection":"第1节 农业生态系统","category":"knowledge","title":"生态农业的意义","question":"生态农业的意义","type":"简答题","answer":"建立合理的农业生态系统，对于农业资源的有效利用、农业\n生产的持续发展以及维护良好的人类生存环境具有重要作用。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":0,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":236,"sourceRange":{"startPage":236,"startY":334.26,"endPage":236,"endY":479.42},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":["【重要程度:☆☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":15,"newSectionOrder":3,"newPointOrder":2,"excerpts":[{"page":236,"src":"./assets/environment/env838-ac61b1b1d5fbcf9b-236.webp"}]},{"id":"env838-0e5d0d9171a6de8d","subject":"环境学导论","chapter":"第15章 工农业生态系统保护","originalChapter":"第16章 农业生态系统","originalChapterNumber":16,"section":"第3节 农业生态","originalSection":"第1节 农业生态系统","category":"knowledge","title":"农业生态系统的组成","question":"农业生态系统的组成","type":"简答题","answer":"生产者\n| 生物组分消费者\n分解者\n[待核对] 辐射\n无机物质\n环境组分\n有机物质\n土体 、 水 、 空气\n1.生物组分：\n①生产者：能利用简单的无机物合成有机物的自养生物。能够通\n过光合作用把太阳能转化为化学能，或通过化学能合成作用，把无机\n物转化为有机物，不仅供给自身的发育生长，也为其他生物提供物质\n和能量。\n②消费者：是自然界中的一个生物群落，属于异养型生物，\n包括食草动物和食肉动物。顾名思义，消费者不能直接利用太阳能来\n生产食物，只能直接或间接地以绿色植物为食获得能量。\n③分解者：是生态系统中将动植物残体、排泄物等所含的\n有机物质转换为简单的无机物的生物。\n2.环境组分：\n①辐射：短波辐射、长波辐射(热辐射)、宇宙辐射、核辐射。\n②无机物质：与机体无关的化合物(少数与机体有关的化合物也\n是无机化合物，如水)，与有机化合物对应，通常指不含碳元素的\n化合物，但包括碳的氧化物、碳酸盐、氰化物等，简称无机物。\n③有机物质：有机化合物主要由氢元素、碳元素组成，通常指\n含碳的化合物，但不包括一氧化碳、二氧化碳和以碳酸根结尾的物\n质。有机物是生命产生的物质基础，所有的生命体都含有机化合物。\n生物体内的新陈代谢和生物的遗传现象，都涉及有机化合物的转变。\n④土体、水、空气。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。","含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":236,"sourceRange":{"startPage":236,"startY":479.42,"endPage":237,"endY":666.7},"sourceKind":"original","originalOrdinal":"3","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":15,"newSectionOrder":3,"newPointOrder":3,"excerpts":[{"page":236,"src":"./assets/environment/env838-0e5d0d9171a6de8d-236.webp"},{"page":237,"src":"./assets/environment/env838-0e5d0d9171a6de8d-237.webp"}]},{"id":"env838-cbe31ce6beef20fd","subject":"环境学导论","chapter":"第15章 工农业生态系统保护","originalChapter":"第16章 农业生态系统","originalChapterNumber":16,"section":"第3节 农业生态","originalSection":"第1节 农业生态系统","category":"knowledge","title":"农业生态系统的特点","question":"农业生态系统的特点","type":"简答题","answer":"①社会性：农业生态系统作为一种人工生态系统，同人类的社会\n经济领域密不可分。大量的农产品离开农业系统，源源不断地进入社\n会经济领域，而大量的农用物资包括化肥、农药、农业机械等又作为\n辅助能量，源源不断地从社会经济领域投入农业系统。由此决定了农\n业生态系统的社会性，它不仅受自然规律支配，而且受社会经济规律\n的支配。\n②波动性：农业生态系统的生物种群构成是人类选择的结果。只\n有符合人类经济要求的生物学性状诸如高产性、优质性等被保留和发\n展，并只能在特定的环境条件和管理措施下才能得到表现。一旦环境\n条件发生剧烈变化，或管理措施不能及时得到满足，它们的生长发育\n就会由于失去原有的适应性和抗逆性而受到影响，导致产量和品质下\n降。\n③综合性：农业生态系统结构因社会(人类)的需要、经济效\n益而发生变化，故实际上是社会一经济—自然生态系统组成的复合\n系统。所以，人们对农业生态系统的影响，可能是积极的建设作用，\n也可能是消极的破坏作用。\n④选择性：农业是人类社会的一种生产活动，不但受自然规律的\n制约，经济因素也是一个重要的选择性因素。\n⑤开放性：农业生态系统，为满足社会日益增长的需要，须对城\n市、工矿等提供大量的商品食物和工业原料。大量农畜产品输出使\n营养元素的回收和保持能力下降。在农畜产品输出的同时，必须\n有相应物质和能量的输入，以维持生态系统的平衡。\n⑥经济性：农业生态系统中的农业生物具有较高的净生产力，较\n高的经济价值和较低的抗逆性。农业生态系统是在人类的干预下发展\n的，因而同自然生态系统下生物种群的自然演化不同，一些符合人类\n需要的生物种群可提供远远高于自然条件下的产量。\n16-1 菲律宾玛雅农场的废物循环途径","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":0,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。","含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":237,"sourceRange":{"startPage":237,"startY":666.7,"endPage":239,"endY":428.34},"sourceKind":"original","originalOrdinal":"4","sourceMetadata":["【重要程度:☆☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":15,"newSectionOrder":3,"newPointOrder":4,"excerpts":[{"page":237,"src":"./assets/environment/env838-cbe31ce6beef20fd-237.webp"},{"page":238,"src":"./assets/environment/env838-cbe31ce6beef20fd-238.webp"},{"page":239,"src":"./assets/environment/env838-cbe31ce6beef20fd-239.webp"}]},{"id":"env838-8514a73009fd7363","subject":"环境学导论","chapter":"第15章 工农业生态系统保护","originalChapter":"第16章 农业生态系统","originalChapterNumber":16,"section":"第3节 农业生态","originalSection":"第2节 生态农业的问题","category":"knowledge","title":"农业生态的环境问题","question":"农业生态的环境问题","type":"简答题","answer":"[1]化肥污染\n农田所施用的任何种类和形态的化肥，都不可能全部被植物吸\n收利用。用量过大，或使用虽正常，但由于其他自然或人为原因，都\n会使化肥大量流失。未被植物及时利用的氮化合物，若以不能被土壤\n胶体吸附的氨氮形式存在，就可能造成污染。\n化肥污染引起的环境问题主要有：河川、湖泊、内海的富营养\n化；土壤受到污染，土壤物理性质恶化；食品、饲料和饮用水中有毒\n成分增加；大气中氮氧化物含量增加。\n[2]农药污染\n农药污染指农药或其有害代谢物、降解物对环境和生物产生的污\n染，农药及其在自然环境中的降解产物，会污染大气、水体和土壤，\n从而破坏生态系统，并引起人和动物、植物的急性或慢性中毒。\n农药施用后，一部分附着于植物体上，或渗人植物体内残留下来\n，使粮、菜、水果等受到污染；另一部分散落在土壤上(有时则是\n直接施于土壤中)，或蒸发、散逸到空气中，或随雨水及农田排\n水流入河湖，污染水体和水生生物。\n农药污染的分类：农药并非都有残留毒性问题，同一类型不同\n品种的农药对环境的危害也不一样。农药的不同剂型在土壤中流失\n、渗漏和吸附的物理性质并不相同，因而它们在土壤中的残留能力也\n有差异。\n①农药污染主要是有机氯农药污染、有机磷农药污染和有机氮\n农药污染。人从环境中摄入农药主要是通过饮食。植物性食品中含有\n农药的原因，一是药剂的直接沾污，二是作物从周围环境中吸收药剂\n。动物性食品中含有农药是动物通过食物链或直接从水体中摄入的。\n环境中农药的残留浓度一般都很低，但通过食物链和生物富集可使\n生物体内的农药浓度提高至几千倍，甚至几万倍。\n②土壤污染：由于农药的大量、大面积使用，不当滥用，以及\n农药的难降解性，对地球造成严重的污染，由此威胁着人类的安全。\n③环境污染：由于农药的施用通常采用喷雾的方式，农药中的\n有机溶剂和部分农药飘浮在空气中，污染大气。农田被雨水冲刷，\n农药则进入江河，进而污染海洋。这样，农药就由气流和水流带到世\n界各地，残留土壤中的农药则可通过渗透作用到达地层深处，从而污\n染地下水。\n④生态破坏：农药的不当滥用，导致害虫、病菌的抗药性。抗\n药性的产生造成用药量的增加，乐果、敌敌畏等常用农药的稀释\n浓度已大大增加，大量和高浓度使用杀虫剂、杀菌剂的同时，杀伤\n许多害虫天敌，破坏了自然界的生态平衡，使过去未构成严重危害\n的病虫害大量发生。此外，农药也可以直接造成害虫迅速繁殖，这\n种使用农药的恶性循环，不仅使防治成本增高、效益降低，更严重\n的是造成人畜中毒事故增加。长期大量使用化学农药不仅误杀害虫天\n敌，还杀伤对人类无害的昆虫，影响以昆虫为生的鸟、鱼、蛙等生物","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2025],"needsReview":false,"reviewReasons":[],"verified":false,"page":242,"sourceRange":{"startPage":242,"startY":92.88,"endPage":243,"endY":707.98},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":["2025 (简—出自课后题，其解决措施即化肥污染、农药污染的防治措施)【重要程度："],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":15,"newSectionOrder":3,"newPointOrder":5,"excerpts":[{"page":242,"src":"./assets/environment/env838-8514a73009fd7363-242.webp"},{"page":243,"src":"./assets/environment/env838-8514a73009fd7363-243.webp"}]},{"id":"env838-5fcfaa01fa9a7f8a","subject":"环境学导论","chapter":"第15章 工农业生态系统保护","originalChapter":"第16章 农业生态系统","originalChapterNumber":16,"section":"第4节 生态农业","originalSection":"第2节 生态农业的问题","category":"knowledge","title":"生态农业技术的概念","question":"生态农业技术的概念","type":"简答题","answer":"一、定义\n生态农业技术是按照生态学原理和经济学原理，运用现代科\n学技术成果和现代管理手段，以及传统农业的有效经验建立起来的\n，能获得较高的经济效益、生态效益和社会效益的现代化高效农业技\n术。\n二、分类\n①面源污染控制技术：根据农业面源污染本身的特殊性，结合实\n际情况，在控源减流的前提下，实行分区、分类控制和途径控制相结\n合，经济措施、政策措施和先进技术措施并举的综合治理策略。控源\n是指减少源头污染物的排放量，减流是指减少地表径流和地下渗漏量\n②城乡过渡带面源污染控制：城乡结合部地区是我国经济\n发展最为迅速，农村城镇化进程最快的地带，是城市肉、蛋、奶\n、菜、果、花等农副产品的主要供应地区。因此，畜禽养殖和菜果花\n的种植成为城乡过渡带农业面源污染物的主要来源。城乡过渡带基本\n都处于近水域地带，人口和小型的乡镇企业较为密集，处于这一地区\n的绝大多数城镇没有排污管网；同时，因为距离农区较远，难以通过\n农田施肥消解城镇生活、生产产生的固液废弃物。因此，对于城乡过\n渡带面源污染控制的主要措施是进行基础设施建设，在新形成的城区\n铺设排污管网，改造老城区超负荷、陈旧的排污管网，兴建污水处理\n厂。在此基础上，再结合其他的技术、经济、政策等措施来进一步实\n现其农业面源污染的控制。\n③农村面源污染控制：农村面源污染主要包括农村人和畜禽排\n泄物中的氮磷、随农田径流和淋洗移出的氮磷、水产养殖投入的饵\n料、农村生活污水和固体废弃物。与城乡过渡带面源的控制相比，农\n村源的控制相对比较困难，特别是人和畜禽排泄物的处理和利用难度\n更大。根据我国农村的具体情况，对农村面源污染应采用源头控制\n策略。其具体控制策略可归纳为以下5个方面：①加快发展规模化养\n殖，特别是家禽的规模化养殖，这将便于粪便的集中处理，同时尽可\n能促使畜禽粪便还田。②在全流域范围内大力推广农田最佳养分管\n理，杜绝农田N、P肥料的过量施用，搞好土壤养分的管理，平衡养\n分的投入和产出，减少其流失量。③通过免耕、少耕、间套复种技\n术、“一退双还”工程、转换土地利用方式等措施搞好流域的水土保持\n工作，尽量减少水土流失。④对现有河网分步实施清淤，把河底污泥\n返回农田，实现农田氮的良性循环。⑤因地制宜建立适合当地条件的\n污水、固体废弃物处理和回收系统。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":0,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":245,"sourceRange":{"startPage":245,"startY":567.47,"endPage":247,"endY":234.45},"sourceKind":"original","originalOrdinal":"6","sourceMetadata":["【重要程度: ☆☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":15,"newSectionOrder":4,"newPointOrder":1,"excerpts":[{"page":245,"src":"./assets/environment/env838-5fcfaa01fa9a7f8a-245.webp"},{"page":246,"src":"./assets/environment/env838-5fcfaa01fa9a7f8a-246.webp"},{"page":247,"src":"./assets/environment/env838-5fcfaa01fa9a7f8a-247.webp"}]},{"id":"env838-6e13be1e97e55957","subject":"环境学导论","chapter":"第15章 工农业生态系统保护","originalChapter":"第16章 农业生态系统","originalChapterNumber":16,"section":"第4节 生态农业","originalSection":"第2节 生态农业的问题","category":"knowledge","title":"污染土壤生物修复技术","question":"污染土壤生物修复技术","type":"简答题","answer":"土壤生物修复技术，包括植物修复、微生物修复、生物联合修复\n等技术\n①植物修复技术：植物修复技术包括利用植物超积累或积累性功\n能的植物吸取修复、利用植物根系控制污染扩散和恢复生态功能的植\n物稳定修复、利用植物代谢功能的植物降解修复、利用植物转化功\n能的植物挥发修复、利用植物根系吸附的植物过滤修复等技术。\n②微生物修复技术：微生物能以有机污染物为唯一碳源和能\n源或者与其他有机物质进行共代谢而降解有机污染物。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":1,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":247,"sourceRange":{"startPage":247,"startY":234.45,"endPage":247,"endY":547.24},"sourceKind":"original","originalOrdinal":"7","sourceMetadata":["【重要程度:★☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":15,"newSectionOrder":4,"newPointOrder":2,"excerpts":[{"page":247,"src":"./assets/environment/env838-6e13be1e97e55957-247.webp"}]},{"id":"env838-7d097953c283879d","subject":"环境学导论","chapter":"第15章 工农业生态系统保护","originalChapter":"第16章 农业生态系统","originalChapterNumber":16,"section":"第4节 生态农业","originalSection":"第2节 生态农业的问题","category":"knowledge","title":"污染土壤物理修复技术","question":"污染土壤物理修复技术","type":"简答题","answer":"物理修复是指通过各种物理过程将污染物从土壤中去除或\n分离的技术。\n①热脱附技术：热脱附是用直接或间接加热土壤中有机污染组\n分到足够高的温度，使其蒸发并与土壤介质相分离的过程。热脱附\n技术具有污染物处理范围宽、设备可移动、修复后土壤可再利用等优\n点，特别对多氯联苯这类含氯有机物，非氧化燃烧的处理方式可显等\n减少二噁英生成。\n②蒸汽浸提技术：土壤蒸气浸提(简称SVE ) 技术是去隆土壤\n中挥发性有机污染物(VOCs )的一种原位修复技术。它将新鲜空\n气通过注射井注入污染区域，利用真空泵产生负压.空气流经污染\n区域时，解吸并夹带土壤孔隙中的VOCs 经由抽取井流回地上.再\n经活性炭吸附法以及生物处理法等净化处理，可排放到大气或重新\n注入地下循环使用。SVE 具有成本低、可操作性强、可采用标准设备\n、处理有机物的范围宽、不破坏土壤结构和不引起二次污染等优点。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":0,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":247,"sourceRange":{"startPage":247,"startY":547.24,"endPage":248,"endY":333.71},"sourceKind":"original","originalOrdinal":"8","sourceMetadata":["【重要程度: ☆☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":15,"newSectionOrder":4,"newPointOrder":3,"excerpts":[{"page":247,"src":"./assets/environment/env838-7d097953c283879d-247.webp"},{"page":248,"src":"./assets/environment/env838-7d097953c283879d-248.webp"}]},{"id":"env838-1d1168bd8c0204c7","subject":"环境学导论","chapter":"第15章 工农业生态系统保护","originalChapter":"第16章 农业生态系统","originalChapterNumber":16,"section":"第4节 生态农业","originalSection":"第2节 生态农业的问题","category":"knowledge","title":"污染土壤化学/物化修复技术","question":"污染土壤化学/物化修复技术","type":"简答题","answer":"相对于物理修复，污染土壤的化学修复技术发展较早，主要有土\n壤固化-稳定化技术、淋洗技术、氧化还原技术、光催化降解技术和电\n动力学修复等。\n①固化技术：固化技术是将污染物在污染介质中固定，使其处\n于长期稳定状态，是较普遍应用于土壤重金属污染的快速控制修复\n方法，对同时处理多种重金属复合污染土壤具有明显的优势。\n固化技术具有工艺操作简单、价格低廉、固化剂易得等优\n点，但常规固化技术也具有以下缺点，如固化反应后土壤体积\n有不同程度的增加，固化体的长期稳定性较差等。\n②淋洗技术：土壤淋洗修复技术是将水或含有冲洗助剂的水溶\n液、酸/碱溶液、络合剂或表面活性剂等淋洗剂注入污染土壤或沉积\n物中，洗脱和清洗土壤中的污染物的过程。淋洗废水经处理后达标排\n放，处理后的土壤可以再安全利用。\n③氧化-还原技术：土壤氧化—还原技术是通过向土壤中投加\n化学氧化剂或还原剂，使其与污染物质发生化学反应来实现净化土\n壤的目的。\n④光催化降解技术：土壤光催化降解(光解)技术是一项新兴\n的深度土壤氧化修复技术，可应用于农药等污染土壤的修复。\n⑤电动力学修复：电动力学修复( 简称电动修复) 是通过电\n化学和电动力学的复合作用(电渗、电迁移和电泳等)驱动污染\n物富集到电极区，进行集中处理或分离的过程。电动修复技术已进\n入现场修复应用。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":1,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":248,"sourceRange":{"startPage":248,"startY":333.71,"endPage":249,"endY":325.85},"sourceKind":"original","originalOrdinal":"9","sourceMetadata":["【重要程度：★☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":15,"newSectionOrder":4,"newPointOrder":4,"excerpts":[{"page":248,"src":"./assets/environment/env838-1d1168bd8c0204c7-248.webp"},{"page":249,"src":"./assets/environment/env838-1d1168bd8c0204c7-249.webp"}]},{"id":"env838-3c496fc84a572ea9","subject":"环境学导论","chapter":"第15章 工农业生态系统保护","originalChapter":"第16章 农业生态系统","originalChapterNumber":16,"section":"第4节 生态农业","originalSection":"第2节 生态农业的问题","category":"knowledge","title":"污染土壤联合修复技术","question":"污染土壤联合修复技术","type":"简答题","answer":"协同两种或两种以上修复方法，形成联合修复技术，不仅可提高\n单一污染土壤的修复速率与效率，而且可克服单项修复技术的局限\n性，实现对多种污染物的复合污染土壤的修复，已成为土壤修复技\n术中的重要研究内容。\n①微生物/动物-植物联合修复技术：微生物一植物、动物(蚯蚓\n)—植物联合修复是土壤生物修复技术研究的新内容。筛选有较强\n降解能力的菌根真菌和适宜的共生植物是菌根生物修复的关键。种植\n紫花苜蓿可以大幅度降低土壤中多氯联苯浓度，根瘤菌和菌根真菌双\n接种能强化紫花苜蓿对多氯联苯的修复作用。利用能促进植物生长的\n根际细菌或真菌，发展植物—降解菌群协同修复、动物—微生物协同\n修复及其根际强化技术，促进有机污染物的吸收、代谢和降解将是生\n物修复技术新的研究方向。\n②化学/物化-生物联合修复技术：发挥化学或物理化学修复的快\n速优势，结合非破坏性的生物修复特点，发展基于化学一生物修复\n技术是最具应用潜力的污染土壤修复方法之一。化学淋洗—生物\n联合修复是基于化学淋溶剂作用，通过增加污染物的生物可利用性\n而提高生物修复效率。利用有机络合剂的配位溶出，增加土壤溶液中\n重金属浓度，提高植物有效性，从而实现强化诱导植物吸取修复。化\n学预氧化一生物降解和臭氧氧化一生物降解等联合技术已应用于污\n染土壤中多环芳烃的修复。电动力学—微生物修复技术可以克服单独\n的电动技术或生物修复技术的缺点，在不破坏土壤质量的前提下，加\n快土壤修复进程。电动力学—芬顿联合技术已用来去除污染黏土矿物\n中的菲，硫氧化细菌与电动综合修复技术用于强化污染土壤中铜的去\n除。应用光降解—生物联合修复技术可以提高石油中多环芳烃的去除\n效率。\n③物理-化学联合修复技术：土壤物理—化学联合修复技术是适\n用于污染土壤异位处理的修复技术。溶剂萃取一光降解联合修复技\n术是利用有机溶剂或表面活性剂提取有机污染物后进行光解的一项\n新的物理—化学联合修复技术。例如，利用环己烷和乙醇将污染土壤\n中的多环芳烃提取出来后进行光催化降解，也可以利用光调节的\n二氧化钛催化修复农药污染土壤。\n④化学处理：应用阴离子聚丙烯酰胺(PAM)防治水土流失，\n已成为国际普遍采用的化学处理措施。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":1,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":249,"sourceRange":{"startPage":249,"startY":325.85,"endPage":250,"endY":674.11},"sourceKind":"original","originalOrdinal":"10","sourceMetadata":["【重要程度: ★☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":15,"newSectionOrder":4,"newPointOrder":5,"excerpts":[{"page":249,"src":"./assets/environment/env838-3c496fc84a572ea9-249.webp"},{"page":250,"src":"./assets/environment/env838-3c496fc84a572ea9-250.webp"}]},{"id":"env838-8e7628925742d3a5","subject":"环境学导论","chapter":"第15章 工农业生态系统保护","originalChapter":"第16章 农业生态系统","originalChapterNumber":16,"section":"第4节 生态农业","originalSection":"第2节 生态农业的问题","category":"knowledge","title":"水土流失","question":"水土流失","type":"简答题","answer":"水土流失是指人类对土地的利用，特别是对水土资源不合理的开\n发和经营，使土壤的覆盖物遭受破坏，裸露的土壤受水力冲蚀，流失\n量大于母质层育化成土壤的量，土壤流失由表土流失、心土流失而至\n母质流失，终使岩石暴露。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":1,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":243,"sourceRange":{"startPage":243,"startY":707.98,"endPage":244,"endY":186.79},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":["【重要程度: ★☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":15,"newSectionOrder":4,"newPointOrder":6,"excerpts":[{"page":243,"src":"./assets/environment/env838-8e7628925742d3a5-243.webp"},{"page":244,"src":"./assets/environment/env838-8e7628925742d3a5-244.webp"}]},{"id":"env838-0562b1db4fa2efbd","subject":"环境学导论","chapter":"第15章 工农业生态系统保护","originalChapter":"第16章 农业生态系统","originalChapterNumber":16,"section":"第4节 生态农业","originalSection":"第2节 生态农业的问题","category":"knowledge","title":"水土流失类型","question":"水土流失类型","type":"简答题","answer":"根据产生水土流失的“动力”，分布最广泛的水土流失可分为水力\n侵蚀、重力侵蚀和风力侵蚀3种类型。\n①水力侵蚀：分布最广泛、在山区、丘陵区和一切有坡度的地\n面，暴雨时都会产生水力侵蚀。它的特点是以地面的水为动力冲走土\n壤，如黄河流域。\n②重力侵蚀：主要分布在山区、丘陵区的沟壑和陡坡上，在陡\n坡和沟的两岸沟壁，其中一部分下部被水流淘空，由于土壤及其成\n土母质自身的重力作用，不能继续保留在原来的位置，分散地或成片\n地塌落。\n③风力侵蚀：主要分布在中国西北、华北和东北的沙漠、沙地\n和丘陵盖沙地区，其次是东南沿海沙地，再次是河南、安徽、江苏\n几省的“黄泛区”。它的特点是由于风力扬起沙粒，离开原来的位置，\n随风飘浮到另外的地方降落，如河西走廊、黄土高原。\n另外还可以分为冻融侵蚀、冰川侵蚀、混合侵蚀、风力侵蚀、植\n物侵蚀和化学侵蚀。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":0,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":244,"sourceRange":{"startPage":244,"startY":186.79,"endPage":244,"endY":710.28},"sourceKind":"original","originalOrdinal":"3","sourceMetadata":["【重要程度:☆☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":15,"newSectionOrder":4,"newPointOrder":7,"excerpts":[{"page":244,"src":"./assets/environment/env838-0562b1db4fa2efbd-244.webp"}]},{"id":"env838-c6a8e561b8824d10","subject":"环境学导论","chapter":"第15章 工农业生态系统保护","originalChapter":"第16章 农业生态系统","originalChapterNumber":16,"section":"第4节 生态农业","originalSection":"第2节 生态农业的问题","category":"knowledge","title":"水土流失成因","question":"水土流失成因","type":"简答题","answer":"中国是个多山国家，山地面积占国土面积的2/3，又是世界上\n黄土分布最广的国家。黄土或松散的风化壳在缺乏植被保护情况下\n极易发生侵蚀。大部分地区属于季风气候，降水量集中，雨季降水量\n常达年降水量的60% ~80%，且多暴雨。这些因素是造成中国发生水\n土流失的主要原因。\n中国人口多，粮食、民用燃料需求等压力大，在生产力水平不高\n的情况下，对土地实行掠夺性开垦，片面强调粮食产量，忽视因地制\n宜的农林牧综合发展，把只适合林、牧业利用的土地也辟为农田。大\n量开垦陡坡，以至陡坡越开越贫，越贫越垦，生态系统恶性循环；滥\n砍滥伐森林，甚至乱挖树根、草坪，树木锐减，使地表裸露。另外，\n某些基本建设不符合水土保持要求，破坏植被，使边坡稳定性降\n低，引起滑坡、塌方、泥石流等更严重的地质灾害。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":0,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":244,"sourceRange":{"startPage":244,"startY":710.28,"endPage":245,"endY":419.02},"sourceKind":"original","originalOrdinal":"4","sourceMetadata":["【重要程度: ☆☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":15,"newSectionOrder":4,"newPointOrder":8,"excerpts":[{"page":244,"src":"./assets/environment/env838-c6a8e561b8824d10-244.webp"},{"page":245,"src":"./assets/environment/env838-c6a8e561b8824d10-245.webp"}]},{"id":"env838-cefa6ebd64e81001","subject":"环境学导论","chapter":"第15章 工农业生态系统保护","originalChapter":"第16章 农业生态系统","originalChapterNumber":16,"section":"第4节 生态农业","originalSection":"第2节 生态农业的问题","category":"knowledge","title":"水土流失危害","question":"水土流失危害","type":"简答题","answer":"①土地生产力下降甚至丧失。\n②淤积河道、湖泊、水库。\n③污染水质影响生态平衡。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":245,"sourceRange":{"startPage":245,"startY":419.02,"endPage":245,"endY":567.47},"sourceKind":"original","originalOrdinal":"5","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":15,"newSectionOrder":4,"newPointOrder":9,"excerpts":[{"page":245,"src":"./assets/environment/env838-cefa6ebd64e81001-245.webp"}]},{"id":"env838-fd1957950c0d30ee","subject":"环境学导论","chapter":"第15章 工农业生态系统保护","originalChapter":"第16章 农业生态系统","originalChapterNumber":16,"section":"第4节 生态农业","originalSection":"第2节 生态农业的问题","category":"knowledge","title":"水土流失的预防措施","question":"水土流失的预防措施","type":"简答题","answer":"①减少坡面径流量：\n在采取防治措施时，应从地表径流形成地段开始，沿径流运\n动路线，因地制宜，步步设防治理，实行预防和治理相结合\n，以预防为主；\n治坡与治沟相结合，以治坡为主；\n工程措施与生物措施相结合，以生物措施为主，采取各种措施\n综合治理。\n充分发挥生态的自然修复能力，依靠科技进步，示范引导，实施\n分区防治战略，加强管理，突出保护，依靠深化改革，实行机制\n创新，加大行业监管力度，为经济社会的可持续发展创造良\n好的生态环境。\n②强化造林治理：主要用于水土流失严重，面积集中，植被稀疏\n，无法采用封禁措施治理的侵蚀区，其治理技术要点是：适地、适\n树、营养袋育苗，整地施肥，高密度、多层次造林，争取快速成林\n、快速覆盖。对流失严重、坡度过陡、造林不易成功的陡坡地，应\n辅以培地埂、挖水平沟、修水平台地等工程强化措施。\n③加强预防监督职能：各有关部门、企业在经济开发和项目\n建设时，要充分考虑对周围水土保持的影响，严格执行水土保持\n有关法律法规。严格控制在生态环境脆弱的地区开垦土地，坚决制\n止毁坏林地、草地以及污染水资源等造成新的水土流失发生的行为。\n④兼顾生态效益与社会经济效益的关系：只有强调减蚀减\n沙效益与经济效益相结合，才能发动广大群众参与水土保持工作。\n但是，从水土流失地区可持续发展要求来看，除了必须把土壤侵蚀\n减小到允许的程度外，还需要建立流域允许产沙量的考核指标。\n⑤提高科学治理水平：实施科教兴国的战略，提高水保科技\n含量，提高科学技术在水土保持治理开发中的贡献率，是达到高起点\n、高速度、高标准、高效益的有效途径，是加快实现由分散治理向规\n模治理、由防护型治理向开发型治理、由粗放型治理向集约型治理\n开发转变的重要措施。就目前情况看，科技投入少是一个突出的问\n题。加强水土保持的科技投入和对水保人才的重视，是提高水土保\n持治理水平的关键之一。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":0,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":250,"sourceRange":{"startPage":250,"startY":674.11,"endPage":252,"endY":229.88},"sourceKind":"original","originalOrdinal":"11","sourceMetadata":["【重要程度:☆☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":15,"newSectionOrder":4,"newPointOrder":10,"excerpts":[{"page":250,"src":"./assets/environment/env838-fd1957950c0d30ee-250.webp"},{"page":251,"src":"./assets/environment/env838-fd1957950c0d30ee-251.webp"},{"page":252,"src":"./assets/environment/env838-fd1957950c0d30ee-252.webp"}]},{"id":"env838-9b9e998659e0680f","subject":"环境学导论","chapter":"第15章 工农业生态系统保护","originalChapter":"第16章 农业生态系统","originalChapterNumber":16,"section":"第4节 生态农业","originalSection":"第3节 生态农业","category":"knowledge","title":"生态农业的类型","question":"生态农业的类型","type":"简答题","answer":"(1)立体农业生态系统：模拟天然生态系统的立体结构，设\n计、建设具有立体层次的人工生态系统。由于立体农业生态系统比\n较充分地利用和转化太阳能，因此可提高经济效益，并增加生态\n系统的稳定性，从而提高环境效益。立体农业的类型很多，主要包\n括：①农作物的轮作、间作和套种；②农林间作；③林药间作；④茶\n胶间作；⑤种植业与食用菌栽培相结合；⑥农林牧相结合。\n学长解读 ; 立体农业就是我们要 \"向上要空间 \"。 因里不是只能种一层 。 上层是\n高大的果树 、 中层是灌木型的经济作物 〈 茶树 、 咖啡 ) 、 下层是续小的蔬莱药\n材 ， 地下还有食用菌 。 像搭积木一样 ， 一层一层往上生 ， 充分利用三维空间里\n的阳光 、 水分和养分 。 间作套种轮作一玉米行间套种大豆 、 收了小支马上种\n玉米 ， 核心就是 \"不浪费每一续阳光 \"。\n(2) 物种共生农业生态系统：将植物栽培与动物养殖有机\n地组合于同一空间，形成物种共生的生态系统，更充分地利用物质和\n能量，提高经济效益和环境效益，以满足人类的需要。物种共生的生\n态系统目前主要包括4种，即稻田养鱼、莲塘养鱼、稻田养鸡和林蛙\n共生。\n[待核对] 学长解读 : MHLARDML 1412\", HSM KS Go Oy MH fo\n[待核对] Ek, GED, GHAMAKAM MBER, KAAS MRE RHE. B\n[待核对] GSHAZRRRSORRARI HR\" SREZRM TH FR\". AH G_\n[待核对] BAK LMI”, LER. CHE, MEKPMRA, BRUAGH. G\n田不需要打农药 、 不需要除草剂一网子全包了 。 莲塘养鱼 、 林蛙共生 ， 都是\n一样的逻辑 : 找一个 \" 搭子 \"， 互相帮和衬 ， 各取所需 。\n(3)物质和能量多层次利用的农业生态系统：物质和能量\n的多层次利用.可以提高资源的利用率和经济效益，还可以改善环\n境质量，其主要类型如下：①基塘生态系统，②种植业与养殖业结合\n的生态系统，③以沼气为纽带的物质多层次利用系统。\n[待核对] 学长解读 : AERA (ALE) ARBZRH—BBHKS, BALHAM,\n委叶咀委 ， 委沙咀鱼 ， 塘泥捞起来肥柔 。 五个环节头尾相接 ， 一图下来什么也\n没浪费 。 以沼气为纽带的系统 〈 猪一沼一果 、 猪一沼一菜 ) 一一猪类进沼气池\n产生沼气铸饭照明 ， 沼渣沼液做有机肥种果树种蔬莱 。\n(4)多功能农工联营生态系统：综合利用农业生态学的理\n论和方法，实行种植业、养殖业、加工工业三者密切结合，建立多功\n能的农工联营生态系统，其生态效益、经济效益和社会效益都很\n明显，而且也很协调，值得大力推广，也是乡镇企业的一个发展方向\n。主要类型包括：①农、林、牧、渔全面发展的农工联营生态系统；\n②以林特产为主的农工联营生态系统；③以水产养殖为主的农工联营\n生态系统；④以粮食加工为主的农工联营生态系统。\n学长解读 : 多功能农工联营就是说我们要 \"种养加一条龙 \"。 这不是单家独户能\n和干的事 ， 需要有一定规模的产业基础 。 种出来的东西就地加工 〈 粮食加工厂 、\n木材加工厂 、 水产加工厂 ) ， 加工的下肚料再回来咀牲口或者做肥料 。 从 \"内\n卖原料 \"升级到 \"也卖加工品 \"%， 从 \"只赚种地的钱 \"升级到 \" 赚加工的钱 + 品牌的\n钱 \"。 这是乡镇企业升级的方向一不是简单地把工厂搬进农村 ， 而是让工厂\n和农业形成 \"共生 \"。\n[待核对] L__ |","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":0,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。","含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":252,"sourceRange":{"startPage":252,"startY":270.24,"endPage":254,"endY":74.93},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":["【重要程度:☆☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":15,"newSectionOrder":4,"newPointOrder":11,"excerpts":[{"page":252,"src":"./assets/environment/env838-9b9e998659e0680f-252.webp"},{"page":253,"src":"./assets/environment/env838-9b9e998659e0680f-253.webp"},{"page":254,"src":"./assets/environment/env838-9b9e998659e0680f-254.webp"}]},{"id":"env838-1be8ac83026cae3c","subject":"环境学导论","chapter":"第15章 工农业生态系统保护","originalChapter":"第16章 农业生态系统","originalChapterNumber":16,"section":"第4节 生态农业","originalSection":"第3节 生态农业","category":"knowledge","title":"生态农业十大模式","question":"生态农业十大模式","type":"简答题","answer":"这十大典型模式和配套技术是：\n北方“四位一体”生态模式及配套境规\n南方“猪—沼—果”生态模式及配套技米\n平原农林牧复合生态模式及配套技术\n草地生态恢复与持续利用生态模式及配套技术\n生态种植模式及配套技术\n生态畜牧业生产模式及配套技术\n生态渔业模式及配套技术\n丘陵山区小流域综合治理模式及配套技术\n设施生态农业模式及配套技术\n观光生态农业模式及配套技术\n其中，“四位一体”生态模式是在自然调控与人工调控相结合条\n件下，利用可再生能源(沼气、太阳能)、保护地栽培(大棚蔬菜\n)、日光温室养猪及厕所4个因子，通过合理配置形成以太阳能、\n沼气为能源，以沼渣、沼液为肥源，实现种植业、养殖业相结合的能\n流、物流良性循环系统，这是一种资源高效利用，综合效益明显的生\n态农业模式。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":0,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":254,"sourceRange":{"startPage":254,"startY":74.93,"endPage":254,"endY":627.25},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":["【重要程度:☆☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":15,"newSectionOrder":4,"newPointOrder":12,"excerpts":[{"page":254,"src":"./assets/environment/env838-1be8ac83026cae3c-254.webp"}]},{"id":"env838-96e3ff0d7c1fdd8f","subject":"环境学导论","chapter":"第15章 工农业生态系统保护","originalChapter":"第16章 农业生态系统","originalChapterNumber":16,"section":"第4节 生态农业","originalSection":"第3节 生态农业","category":"knowledge","title":"生态农业模式类型","question":"生态农业模式类型","type":"简答题","answer":"①时空结构型：这是一种根据生物种群的生物学、生态学特征和\n生物之间的互利共生关系而合理组建的农业生态系统，使处于不同\n生态位置的生物种群在系统中各得其所，更加充分的利用太阳能\n、水分和矿物质营养元素，是时间多序列、空间多层次的三维结构，\n其经济效益和生态效益均佳。具体有果林地立体间套模式、农田立体\n间套模式、水域立体养殖模式，农户庭院立体种养模式等。\n②食物链型：这是一种按照农业生态系统的能量流动和物质循环\n规律而设计的一种良性循环的农业生态系统。系统中一个生产环节\n的产出是另一个生产环节的投入，使系统中的废弃物多次循环利用，\n从而提高能量的转换率和资源利用率，获得较大的经济效益，并有效\n防止农业废弃物对农业生态环境的污染。具体有种植业内部物质循\n环利用模式、养殖业内部物质循环利用模式、种养加工三结合的物质\n循环利用模式等。\n③时空食物链综合型：这是时空结构型和食物链型的有机结合，\n使系统中的物质得以高效生产和多次利用，是一种适度投入、高产出\n、少废物、无污染、高效益的模式类型。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":254,"sourceRange":{"startPage":254,"startY":627.25,"endPage":255,"endY":438.79},"sourceKind":"original","originalOrdinal":"3","sourceMetadata":["【重要程度："],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":15,"newSectionOrder":4,"newPointOrder":13,"excerpts":[{"page":254,"src":"./assets/environment/env838-96e3ff0d7c1fdd8f-254.webp"},{"page":255,"src":"./assets/environment/env838-96e3ff0d7c1fdd8f-255.webp"}]},{"id":"env838-a69a022a347208d7","subject":"环境学导论","chapter":"第15章 工农业生态系统保护","originalChapter":"第16章 农业生态系统","originalChapterNumber":16,"section":"第4节 生态农业","originalSection":"第3节 生态农业","category":"knowledge","title":"世界生态农业发展趋势","question":"世界生态农业发展趋势","type":"简答题","answer":"①生态农业将会成为21世纪世界农业的主导模式\n②生产和贸易的相互促进\n③各国生态食品的标准及认证体系将进一步统一","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":0,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":255,"sourceRange":{"startPage":255,"startY":438.79,"endPage":255,"endY":608.27},"sourceKind":"original","originalOrdinal":"4","sourceMetadata":["【重要程度: ☆☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":15,"newSectionOrder":4,"newPointOrder":14,"excerpts":[{"page":255,"src":"./assets/environment/env838-a69a022a347208d7-255.webp"}]},{"id":"env838-5c663bb109f4e370","subject":"环境学导论","chapter":"第15章 工农业生态系统保护","originalChapter":"第16章 农业生态系统","originalChapterNumber":16,"section":"第4节 生态农业","originalSection":"第3节 生态农业","category":"knowledge","title":"中国生态农业的发展趋势分析","question":"中国生态农业的发展趋势分析","type":"简答题","answer":"①经过多年的科学研究和广泛的农业实践，我国已经基本\n解决温饱问题，农业综合生产能力提高，农产品基本实现总量\n平衡，且丰年有余，农业生产正在从数量向质量为主要目标转变\n。当前急待解决的任务是如何通过调整农业生产的结构，引进和开发\n适用技术，提高农业生产效益，提高农产品的质量与食品安全\n，加强农产品的国际竞争能力，发展农村经济，增强抵御自然\n灾害的能力。\n②农业资源环境形势依然严峻，局部改善总体恶化的基本\n格局没有实质性改变，但人们的环境意识普遍提高。我国在生\n态环境建设方面加大了投资和实施力度，我国正处在从生态赤字走\n向生态恢复与保育的转折点，改善农村和农业生态环境，促进农村\n社会的可持续发展是当前的一个主要任务。\n③科学技术的迅速发展，特别是以信息技术、生物技术为\n代表的高新技术，将会极大地促进生态农业的发展。与此同时\n，生态农业的发展也面临着这些高新技术应用所可能带来的一些新\n问题，因此，应当重视转基因技术、信息技术和其他技术对农业生\n态系统影响的研究，特别是针对其潜在的负面影响应及时采取防\n范措施。\n④20世纪90年代以来，各国对食品卫生和质量的监控越来\n越严，标准也越来越高，尤其是对与农产品生产和贸易有关的\n环保技术和产品卫生安全标准要求更加严格。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":0,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":255,"sourceRange":{"startPage":255,"startY":608.27,"endPage":257,"endY":66.17},"sourceKind":"original","originalOrdinal":"5","sourceMetadata":["【重要程度: ☆☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":15,"newSectionOrder":4,"newPointOrder":15,"excerpts":[{"page":255,"src":"./assets/environment/env838-5c663bb109f4e370-255.webp"},{"page":256,"src":"./assets/environment/env838-5c663bb109f4e370-256.webp"},{"page":257,"src":"./assets/environment/env838-5c663bb109f4e370-257.webp"}]},{"id":"env838-2f86498d88ecdde4","subject":"环境学导论","chapter":"第15章 工农业生态系统保护","originalChapter":"第15章 工业生态系统构建","originalChapterNumber":15,"section":"第1节 工业生态学与工业生态系统的概念","originalSection":"第1节 工业生态学与工业生态系统的概念","category":"knowledge","title":"工业生态学的主要特征","question":"工业生态学的主要特征","type":"简答题","answer":"(1)整体性。从全局和整体的视角，研究工业系统组成部分及\n其与自然生态系统的相互关系和相互作用。\n(2)全程性。充分考虑产品、工艺或服务整个生命周期的环境\n影响\n(3)长远性。着眼于人类与生态环境的长远利益，关注工业生\n产、产品使用和再循环利用等技术未来潜在的环境影响。\n(4)全球化。不仅考虑人类工业活动对局部地区的环境影响，\n而且还要考虑区域性和全球性的重大影响。\n(5)科技进步。科技进步是工业系统进化的决定性因素之一，\n工业应从自然生态系统的进化规律中获得知识，把现有工业系统改造\n成为符合可持续发展要求的系统。\n(6)多学科综合。工业生态学具有典型的多学科性特点，涉及\n自然科学、工业技术和人文科学等许多学科。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"removed","importance":0,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":222,"sourceRange":{"startPage":222,"startY":59.56,"endPage":222,"endY":529.12},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":["【重要程度: ☆☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":15,"versionReason":"未列入变动PDF第31—32页新版知识点保留清单；原内容与真题信息保留。","excerpts":[{"page":222,"src":"./assets/environment/env838-2f86498d88ecdde4-222.webp"}]},{"id":"env838-5237873a56a88db2","subject":"环境学导论","chapter":"第15章 工农业生态系统保护","originalChapter":"第15章 工业生态系统构建","originalChapterNumber":15,"section":"第2节 工业生态系统的特征","originalSection":"第2节 工业生态系统的特征","category":"knowledge","title":"物质循环与能量流动的关系","question":"物质循环与能量流动的关系","type":"简答题","answer":"物质循环和能量流动是生态系统的主要功能，二者同时进行，相\n互依存，不可分割。能量的固定、储存、转移和释放，都离不开物质\n的合成和分解等过程。物质作为能量的载体，使能量沿着食物链或食\n物网流动；能量作为动力，使物质能够不断地在生物群落和无机环境\n之间循环往返。生态系统中的各种组成成分，正是通过能量流动和物\n质循环，才紧密地联系在一起，形成统一的整体。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"removed","importance":1,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":223,"sourceRange":{"startPage":223,"startY":523.58,"endPage":224,"endY":62.74},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":["【重要程度:★☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":15,"versionReason":"未列入变动PDF第31—32页新版知识点保留清单；原内容与真题信息保留。","excerpts":[{"page":223,"src":"./assets/environment/env838-5237873a56a88db2-223.webp"},{"page":224,"src":"./assets/environment/env838-5237873a56a88db2-224.webp"}]},{"id":"env838-0f9560af7164f6ed","subject":"环境学导论","chapter":"第15章 工农业生态系统保护","originalChapter":"第15章 工业生态系统构建","originalChapterNumber":15,"section":"第2节 工业生态系统的特征","originalSection":"第2节 工业生态系统的特征","category":"knowledge","title":"经济系统的物质循环与能量流动特征","question":"经济系统的物质循环与能量流动特征","type":"简答题","answer":"(1)经济系统与生态系统之间的原料与能量交换\n在某种意义上说，地球系统是一个封闭系统。在这个系统内，物\n质的储藏量是恒定的，物质的运动是平衡的，物质的输入与输出维持\n一种动态平衡，并且这种原料与能量的交换是缓慢的，这是地球亿万\n年演化的结果。但是，自从人类进入工业文明以后，人类的经济活动\n，特别是工业活动，能够大量、快速地把物质从该系统内的某一储库\n运动至另一储库，使物质从一种存在形态转化为另一种形态，经济系\n统与全球生态系统之间的原料与能量的交换量大而快速，从而产生对\n地球系统的扰动。\n(2)经济系统内原料与能量流动迅速\n为了满足经济生活的需要，在工业系统内，大量的原料与能源被\n使用，通过不同的企业，生产各种各样的产品，物质在不同的工业部\n门快进快出，经济子系统内原料与能量的流动相当快，这是经济子系\n统原料与能量流动的一个特点。\n(3)经济系统内物质利用效率低下\n与自然系统不同，工业系统各企业和部门之间的物质供应是一线\n性开放系统，“食物”关系呈线性状态，除了共同为争夺资源参与竞\n争外，各企业或部门之间的相互作用和联系很小。由原材料制成的产\n品，使用一次后大部分便被扔掉，一般不参与再循环；从自然环境中\n提取的高品位的能源物质，经工业企业使用后变成降阶的物质，最后\n作为废弃物返回自然环境。废弃物即使参与再循环也是微乎其微，而\n且循环方式其本身往往也是污染、消耗性的。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"removed","importance":0,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":224,"sourceRange":{"startPage":224,"startY":62.74,"endPage":225,"endY":60.35},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":["【重要程度: ☆☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":15,"versionReason":"未列入变动PDF第31—32页新版知识点保留清单；原内容与真题信息保留。","excerpts":[{"page":224,"src":"./assets/environment/env838-0f9560af7164f6ed-224.webp"},{"page":225,"src":"./assets/environment/env838-0f9560af7164f6ed-225.webp"}]},{"id":"env838-dcfc4cf9825b0a65","subject":"环境学导论","chapter":"第15章 工农业生态系统保护","originalChapter":"第15章 工业生态系统构建","originalChapterNumber":15,"section":"第2节 工业生态系统的特征","originalSection":"第2节 工业生态系统的特征","category":"knowledge","title":"工业生态系统的物质循环","question":"工业生态系统的物质循环","type":"简答题","answer":"工业经济系统中，有3个层面上的循环：①小循环。企业内部的\n物质循环。例如，下游工序的废物返回上游工序，作为原料重新利用\n：水在企业内的循环：其他消耗品、副产品等在企业内的循环。②中\n循环。企业之间的物质循环。例如，下游工业的废物返回上游工业，\n作为原料重新利用；或者扩而广之，某一工业的废物、余能，送往其\n他工业区加以利用。③大循环。工业产品经使用报废后，部分物质返\n回原工业部门作为原料重新利用。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"removed","importance":1,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":225,"sourceRange":{"startPage":225,"startY":60.35,"endPage":225,"endY":353.16},"sourceKind":"original","originalOrdinal":"3","sourceMetadata":["【重要程度: ★☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":15,"versionReason":"未列入变动PDF第31—32页新版知识点保留清单；原内容与真题信息保留。","excerpts":[{"page":225,"src":"./assets/environment/env838-dcfc4cf9825b0a65-225.webp"}]},{"id":"env838-6f92fae730f5cbdc","subject":"环境学导论","chapter":"第15章 工农业生态系统保护","originalChapter":"第15章 工业生态系统构建","originalChapterNumber":15,"section":"第2节 工业生态系统的特征","originalSection":"第2节 工业生态系统的特征","category":"knowledge","title":"原料与能量流动分析的基本方法","question":"原料与能量流动分析的基本方法","type":"简答题","answer":"(1)质量平衡法。质量平衡法是原料流动研究的方法之一，这\n种方法叙述某种特殊要素在不同时间与地点的流动，包括向环境的散\n失。通过估计在原料流动系统的每一阶段的输入和输出，质量平衡研\n究提出与原料相连的全部途径的分析观点。\n(2)输入—输出分析法。输入一输出分析为标准的经济工具，\n描述部门间按照货币或商品量的相互交付，通常被用于分析国家水平\n的结构图和经济部门之间的相互交付关系，并鉴别经济和商品在经济\n系统内的主要流动。\n(3)生命周期分析与评价法。生命周期分析与评价是一种对产\n品、工艺或活动所产生的环境问题的评估，从原料采集，到产品生产\n、运输、销售、使用、回用、维护和最终处置整个生命周期阶段有关\n环境负荷的过程。它首先辨识和量化产品整个生命周期中原料与能量\n的消耗以及环境释放，然后评价这些消耗和释放对环境的影响，最后\n辨识和评价减少这些影响的机会。\n(4)工业代谢分析法。工业代谢是把原料和能源以及劳动在一\n种稳态条件下转化为最终产品和废物的所有物理过程完整的集合。工\n业代谢认为经济系统是一些企业的集合，它们通过管理制度、工人、\n消费者以及货币和普通的政策控制而结合在一起。一个企业通常被认\n为是经济分析的一个标准单元，一个从事加工制造的企业就是把原材\n料转变成产品和废物的单位。因此，整个经济系统的运行，就涉及在\n自然生态系统内物质和能量的大流动。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"removed","importance":0,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":225,"sourceRange":{"startPage":225,"startY":353.16,"endPage":226,"endY":340.0},"sourceKind":"original","originalOrdinal":"4","sourceMetadata":["【重要程度: ☆☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":15,"versionReason":"未列入变动PDF第31—32页新版知识点保留清单；原内容与真题信息保留。","excerpts":[{"page":225,"src":"./assets/environment/env838-6f92fae730f5cbdc-225.webp"},{"page":226,"src":"./assets/environment/env838-6f92fae730f5cbdc-226.webp"}]},{"id":"env838-34bb7734ffe9bd04","subject":"环境学导论","chapter":"第15章 工农业生态系统保护","originalChapter":"第15章 工业生态系统构建","originalChapterNumber":15,"section":"第2节 工业生态系统的特征","originalSection":"第2节 工业生态系统的特征","category":"knowledge","title":"工业生态系统的定义","question":"工业生态系统的定义","type":"简答题","answer":"工业生态系统是指在一定的区域或范围内，由制造业企业和服务\n业企业组成，通过企业间物质循环和能量流动的功能流相互作用、相\n互联系而形成的生态工业体系。即把工业经济活动视为一种类似于自\n然生态系统的循环体系，其中一个企业产生的废物作为下一个企业的\n原料，形成企业“群落”(工业链)。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"removed","importance":0,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":226,"sourceRange":{"startPage":226,"startY":340.0,"endPage":226,"endY":568.61},"sourceKind":"original","originalOrdinal":"5","sourceMetadata":["【重要程度: ☆☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":15,"versionReason":"未列入变动PDF第31—32页新版知识点保留清单；原内容与真题信息保留。","excerpts":[{"page":226,"src":"./assets/environment/env838-34bb7734ffe9bd04-226.webp"}]},{"id":"env838-7dd6c85049219083","subject":"环境学导论","chapter":"第15章 工农业生态系统保护","originalChapter":"第15章 工业生态系统构建","originalChapterNumber":15,"section":"第3节 工业生态系统的构建","originalSection":"第3节 工业生态系统的构建","category":"knowledge","title":"企业共生原则","question":"企业共生原则","type":"简答题","answer":"构建工业生态系统的企业共生原则指仿照自然生态系统食物链\n和食物网，使一家企业的废物(输出)，变成另一家企业的原材料(\n输入)，形成“共生工业链”，实现系统物质流和能量流综合协同的\n封闭循环。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"removed","importance":0,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":228,"sourceRange":{"startPage":228,"startY":723.24,"endPage":229,"endY":194.17},"sourceKind":"original","originalOrdinal":"3","sourceMetadata":["【重要程度:☆☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":15,"versionReason":"未列入变动PDF第31—32页新版知识点保留清单；原内容与真题信息保留。","excerpts":[{"page":228,"src":"./assets/environment/env838-7dd6c85049219083-228.webp"},{"page":229,"src":"./assets/environment/env838-7dd6c85049219083-229.webp"}]},{"id":"env838-38b311af978a3a1a","subject":"环境学导论","chapter":"第15章 工农业生态系统保护","originalChapter":"第15章 工业生态系统构建","originalChapterNumber":15,"section":"第4节 课后习题","originalSection":"第4节 课后习题","category":"exercise","title":"什么是工业生态学?工业生态学的主要特征有哪些?","question":"什么是工业生态学?工业生态学的主要特征有哪些?","type":"简答题","answer":"工业生态学借鉴生态学原理，从工业系统与自然环境的关系出发，研究物质、能量和信息流，优化产品、企业及产业网络，以减少资源消耗和环境负荷。\n本资料强调六个特征：①整体性，考察系统及其相互关系；②全程性，关注生命周期；③长远性，考虑长期影响；④全球化视角，关注跨区域与全球影响；⑤科技进步，促进系统改进；⑥多学科综合，结合自然科学、工程与社会经济知识。\n目的在于改善整个系统的生态效率，避免只把污染从一个企业转移给另一个企业。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":234,"sourceRange":{"startPage":234,"startY":88.45,"endPage":234,"endY":168.28},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":15,"excerpts":[{"page":234,"src":"./assets/environment/env838-38b311af978a3a1a-234.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=220"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-eb5fedc926d6d281","subject":"环境学导论","chapter":"第15章 工农业生态系统保护","originalChapter":"第15章 工业生态系统构建","originalChapterNumber":15,"section":"第4节 课后习题","originalSection":"第4节 课后习题","category":"exercise","title":"工业生态系统的组成有哪些?有什么主要特点?","question":"工业生态系统的组成有哪些?有什么主要特点?","type":"简答题","answer":"组成可类比自然生态系统：①生产者，利用自然资源生产原料或产品的企业；②消费者，使用产品并提供服务的机构或其他利用环节；③分解／再生者，回收、处理和再利用废物的主体；④非生物环境，即资源、能源、土地、水及相关环境条件。\n特点：具有明显人工组织与控制，物质流、能量流和信息流相联系，系统结构可以通过规划和技术调整；同时受生态约束与市场经济规律影响，存在经济效益和环境效益的双重要求。\n类比用于理解功能关系，不能将工业过程与自然系统看作完全相同。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":234,"sourceRange":{"startPage":234,"startY":168.28,"endPage":234,"endY":249.6},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":15,"excerpts":[{"page":234,"src":"./assets/environment/env838-eb5fedc926d6d281-234.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=220"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-d87016a50a0fc9e5","subject":"环境学导论","chapter":"第15章 工农业生态系统保护","originalChapter":"第15章 工业生态系统构建","originalChapterNumber":15,"section":"第4节 课后习题","originalSection":"第4节 课后习题","category":"exercise","title":"简述工业生态系统与自然生态系统的相似性。","question":"简述工业生态系统与自然生态系统的相似性。","type":"简答题","answer":"相似性：①都由相互联系的功能组分组成；②存在物质、能量与信息交换；③不同组分可形成类似食物链或网络的联系；④资源利用与废物接纳受环境条件约束；⑤网络结构和反馈会影响系统效率、稳定性和适应能力。\n启示：可通过副产品交换、废物资源化、能量梯级利用和信息协作，减少外部资源投入及最终排放。\n差异：工业网络依赖人为设计、市场、技术及制度，能量仍会耗散，物料循环也存在损失和污染风险，不能把“模仿自然”当作自动无害化。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":234,"sourceRange":{"startPage":234,"startY":249.6,"endPage":234,"endY":331.52},"sourceKind":"original","originalOrdinal":"3","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":15,"excerpts":[{"page":234,"src":"./assets/environment/env838-d87016a50a0fc9e5-234.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=220"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-e507c2c4cc9f05ac","subject":"环境学导论","chapter":"第15章 工农业生态系统保护","originalChapter":"第15章 工业生态系统构建","originalChapterNumber":15,"section":"第4节 课后习题","originalSection":"第4节 课后习题","category":"exercise","title":"工业生态系统中物质循环与能量流动的特点是什么?","question":"工业生态系统中物质循环与能量流动的特点是什么?","type":"简答题","answer":"物质循环：原料进入生产，形成产品、副产品及废物，再通过回收、再制造、再生利用等重新进入其他生产环节。工业系统常存在较强的线性输入输出，应提高循环程度并控制有害物累积。\n能量流动：外部能源输入后，经转化、使用及余热利用逐级降低可利用品质，最终以热耗散；可以梯级利用，但不能无损闭合循环。\n联系：物料处理消耗能量，能源利用也产生物料排放。优化应同时考虑全生命周期的物质和能量收支，避免资源回收所需能耗及二次污染超过收益。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":234,"sourceRange":{"startPage":234,"startY":331.52,"endPage":234,"endY":413.31},"sourceKind":"original","originalOrdinal":"4","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":15,"excerpts":[{"page":234,"src":"./assets/environment/env838-e507c2c4cc9f05ac-234.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=220"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-369426f8dcf28a5a","subject":"环境学导论","chapter":"第15章 工农业生态系统保护","originalChapter":"第15章 工业生态系统构建","originalChapterNumber":15,"section":"第4节 课后习题","originalSection":"第4节 课后习题","category":"exercise","title":"工业生态系统的构建原则是什么?","question":"工业生态系统的构建原则是什么?","type":"简答题","answer":"①系统和生命周期原则：统筹企业、园区与区域，避免污染转移。\n②资源效率原则：节约原材料与能源，发展清洁生产、再使用和再生利用。\n③共生与耦合原则：使企业的副产品、余热、再生水等在安全可行的条件下互补利用。\n④多样性和韧性原则：避免过度依赖单一交换对象，提高网络适应市场变化的能力。\n⑤因地制宜原则：符合当地资源禀赋、环境容量、产业及社会条件。\n⑥经济和管理可行性：明确责任、质量标准、信息共享和风险保障，形成可持续运行机制。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":234,"sourceRange":{"startPage":234,"startY":413.31,"endPage":234,"endY":494.32},"sourceKind":"original","originalOrdinal":"5","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":15,"excerpts":[{"page":234,"src":"./assets/environment/env838-369426f8dcf28a5a-234.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=220"},{"title":"生态环境部：批准苏州等国家生态工业示范园区的通知","url":"https://www.mee.gov.cn/gkml/hbb/bwj/200910/t20091022_174590.htm","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-c030487d98f2af31","subject":"环境学导论","chapter":"第15章 工农业生态系统保护","originalChapter":"第15章 工业生态系统构建","originalChapterNumber":15,"section":"第4节 课后习题","originalSection":"第4节 课后习题","category":"exercise","title":"生态工业园区的特征有哪些?分为哪几种类型?","question":"生态工业园区的特征有哪些?分为哪几种类型?","type":"简答题","answer":"特征：以生态工业和循环经济理念组织企业及公共设施，开展资源、能源和副产品协同利用；强调园区整体绩效、清洁生产、环境管理和产业共生，兼顾经济、环境与社会收益。\n按本教材常见教学分类，可分：①行业类，以某一行业及关联产业为主；②综合类，多行业通过物料、能源或服务关系耦合；③静脉产业类，以废旧资源回收、再生和相关利用为重要功能。\n上述为教学分类，具体行政认定和标准应按对应时期文件理解；园区拥有污水厂并不足以单独证明已形成有效共生网络。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":234,"sourceRange":{"startPage":234,"startY":494.32,"endPage":234,"endY":574.0},"sourceKind":"original","originalOrdinal":"6","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":15,"excerpts":[{"page":234,"src":"./assets/environment/env838-c030487d98f2af31-234.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=220"},{"title":"生态环境部：批准苏州等国家生态工业示范园区的通知","url":"https://www.mee.gov.cn/gkml/hbb/bwj/200910/t20091022_174590.htm","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-a007dc76e10a6b4d","subject":"环境学导论","chapter":"第15章 工农业生态系统保护","originalChapter":"第15章 工业生态系统构建","originalChapterNumber":15,"section":"第4节 课后习题","originalSection":"第4节 课后习题","category":"exercise","title":"生态工业园区的规划设计原则是什么?规划设计内容和实施途径有哪些?","question":"生态工业园区的规划设计原则是什么?规划设计内容和实施途径有哪些?","type":"简答题","answer":"原则：系统协调、资源高效、环境安全、因地制宜、经济可行及持续改进。\n规划内容：①调查产业、资源环境和污染负荷；②明确目标、指标与承载约束；③设计产业链及物质能量交换网络；④安排土地、交通、公共能源、水务和废物设施；⑤设置环境监测、风险防范和管理机制。\n实施途径：清洁生产审核与企业技改，绿色招商和准入，基础设施共享，副产品及再生水交换，信息平台、资金与技术服务，以及分阶段评估和纠偏。\n应明确交换物料的质量、安全及法律责任，避免将废物名义上的利用当成实际减排。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":234,"sourceRange":{"startPage":234,"startY":574.0,"endPage":234,"endY":678.58},"sourceKind":"original","originalOrdinal":"7","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":15,"excerpts":[{"page":234,"src":"./assets/environment/env838-a007dc76e10a6b4d-234.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=220"},{"title":"苏州市政府：苏州工业园区能源绿色转型与循环经济实践","url":"https://www.suzhou.gov.cn/szsrmzf/qxkx/202412/9bd49c92296c4630896923230d23dae4.shtml","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-468bca7d23d36656","subject":"环境学导论","chapter":"第15章 工农业生态系统保护","originalChapter":"第15章 工业生态系统构建","originalChapterNumber":15,"section":"第4节 课后习题","originalSection":"第4节 课后习题","category":"exercise","title":"举例说明我国的生态工业示范园区。","question":"举例说明我国的生态工业示范园区。","type":"简答题","answer":"可举苏州工业园区、苏州高新技术产业开发区和天津经济技术开发区。生态环境部相关通知确认其国家生态工业示范园区建设及验收情况。\n以苏州工业园区为例：组织清洁生产及企业节能改造，促进公共设施和资源协同利用，发展绿色能源。苏州市政府介绍了将污水、污泥、餐厨及园林绿化垃圾处理与热电联产、沼气利用衔接的循环经济产业园实践。\n分析要点：把“一个环节的副产物—另一环节的投入”与物料、能量收支联系起来，评价节约、排放与运行风险；不编造企业之间未被资料确认的交换关系或减排量。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":234,"sourceRange":{"startPage":234,"startY":678.58,"endPage":235,"endY":59.31},"sourceKind":"original","originalOrdinal":"8","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":15,"excerpts":[{"page":234,"src":"./assets/environment/env838-468bca7d23d36656-234.webp"},{"page":235,"src":"./assets/environment/env838-468bca7d23d36656-235.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=220"},{"title":"生态环境部：批准苏州等国家生态工业示范园区的通知","url":"https://www.mee.gov.cn/gkml/hbb/bwj/200910/t20091022_174590.htm","accessedOn":"2026-11-09"},{"title":"苏州市政府：苏州工业园区能源绿色转型与循环经济实践","url":"https://www.suzhou.gov.cn/szsrmzf/qxkx/202412/9bd49c92296c4630896923230d23dae4.shtml","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-90953818140859ff","subject":"环境学导论","chapter":"第15章 工农业生态系统保护","originalChapter":"第16章 农业生态系统","originalChapterNumber":16,"section":"第1节 农业生态系统","originalSection":"第1节 农业生态系统","category":"knowledge","title":"农业生态系统的能量流动","question":"农业生态系统的能量流动","type":"简答题","answer":"在生态系统中，能量流动主要是从初级生产者向初级消费者流动\n。能量的流动渠道主要通过“食物链”与“食物网”来实现。\n在农业生态系统中，能量流动的主要渠道通常有3种形式：捕食\n食物链、寄生食物链和腐生食物链。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"removed","importance":1,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":239,"sourceRange":{"startPage":239,"startY":428.34,"endPage":239,"endY":624.36},"sourceKind":"original","originalOrdinal":"5","sourceMetadata":["【重要程度: ★☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":15,"versionReason":"未列入变动PDF第31—32页新版知识点保留清单；原内容与真题信息保留。","excerpts":[{"page":239,"src":"./assets/environment/env838-90953818140859ff-239.webp"}]},{"id":"env838-f71450550364f5e2","subject":"环境学导论","chapter":"第15章 工农业生态系统保护","originalChapter":"第16章 农业生态系统","originalChapterNumber":16,"section":"第1节 农业生态系统","originalSection":"第1节 农业生态系统","category":"knowledge","title":"生态金字塔/能量金字塔","question":"生态金字塔/能量金字塔","type":"简答题","answer":"由于能量从一个营养级到另一个营养级的流动过程中，有一部\n分被固定下来形成有机物的化学潜能，而另一部分通过多种途径被消\n耗，直到最后耗尽为止。平均每个营养级的能量转化效率为10% ，这\n就是著名的“1/10定律”。因此，营养级由低级到高级，形成底宽而顶\n尖的金字塔形，称之为生态金字塔或能量金字塔，即顺着营养级位\n序列(食物链)向上，能量急剧递减。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"removed","importance":1,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":239,"sourceRange":{"startPage":239,"startY":624.36,"endPage":240,"endY":459.47},"sourceKind":"original","originalOrdinal":"6","sourceMetadata":["【重要程度: ★☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":15,"versionReason":"未列入变动PDF第31—32页新版知识点保留清单；原内容与真题信息保留。","excerpts":[{"page":239,"src":"./assets/environment/env838-f71450550364f5e2-239.webp"},{"page":240,"src":"./assets/environment/env838-f71450550364f5e2-240.webp"}]},{"id":"env838-7c6b7f1c5238e6d0","subject":"环境学导论","chapter":"第15章 工农业生态系统保护","originalChapter":"第16章 农业生态系统","originalChapterNumber":16,"section":"第1节 农业生态系统","originalSection":"第1节 农业生态系统","category":"knowledge","title":"能量流动中能量的来源","question":"能量流动中能量的来源","type":"简答题","answer":"①太阳能：地球上能量的原始与主要的来源，太阳每年向外辐\n射约 丿 能量，农业生产通过绿色植物来固定太阳光能，\n但也仅能利用太阳光能的1% ~3% ，理论上最大利用率仅5%\n。因此在农业生产中合理利用，充分提高太阳光能利用率的潜力很\n大。\n②辅助能：辅助能是太阳能的一种变换形式，不过在农业生产中\n，我们把除太阳能以外人类可以利用的能源，包括工业能、生物能、\n自然能等都称之为辅助能。辅助能的使用主要用于改善农业生产环境\n， 趙壽仵紛篩列鉤举发繩量鲆化熒率，用于灌溉、排水、施肥、耕作\n马爽网寨本建设，接育器夨、田间管理、收获和贮藏加工。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"removed","importance":1,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":240,"sourceRange":{"startPage":240,"startY":459.47,"endPage":241,"endY":131.66},"sourceKind":"original","originalOrdinal":"7","sourceMetadata":["【重要程度: ★☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":15,"versionReason":"未列入变动PDF第31—32页新版知识点保留清单；原内容与真题信息保留。","excerpts":[{"page":240,"src":"./assets/environment/env838-7c6b7f1c5238e6d0-240.webp"},{"page":241,"src":"./assets/environment/env838-7c6b7f1c5238e6d0-241.webp"}]},{"id":"env838-bbb6abcfedb9d911","subject":"环境学导论","chapter":"第15章 工农业生态系统保护","originalChapter":"第16章 农业生态系统","originalChapterNumber":16,"section":"第1节 农业生态系统","originalSection":"第1节 农业生态系统","category":"knowledge","title":"物质揚环","question":"物质揚环","type":"简答题","answer":"【董零程,☆☆☆☆☆】\n农业生粉为了自身的生长、发育、繁殖必须从周围环境中吸收营\n柴绮质知能量、主要有C、H、O、N等构成有机体的元素，还有 Ca、\nMg,P,K,Na,S 等大量元素以及 Cu,Zn,Mn,B,Mo,Co,Fe,\nF、I等衡量元素、同时从空气中吸收CO2并利用日光能制造各种有机\n物，\n一般地.各种化学元素从环境到生物体，再从生物体到环境以及\n生悉系线之间进行流动和转化的运动，称为物质的生物地球化学循\n环，或简称为“环”。在循环过程中物质被暂时固定、贮存的场所，称\n为物质贮存的“库”。而物和能量以一定的数量由一个库转移到另一个\n其中。这个过程叫做\"流\"，即所谓的物质流和能量流。\n目前在农业生态系统中物质的循环以3种类型为主，即水循环、\n气态循环和沉积循环。\n[待核对] FEME: |\n[待核对] | RAR —ARR RE, FO, RAT, BRR.\n[待核对] UR\" 2.0K,\n[待核对] | \\& R$ KR. REAKLLAKAUP AON A\", ede CES EO\n各植物级收一变成要食一被人吃撞一变成排泄物一回到土壤一被微生物转\n化成番气一回到大气 ，\n沉积抑环一一确 、 钾 、 僵等元素主要在土壤和岩石中 \" 存 \" 和 \" 走 \"。 它们不会\n变成气体飞走 ， 只能靠水流和地质运动搬运 。\n·221·","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"removed","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。","含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":241,"sourceRange":{"startPage":241,"startY":131.66,"endPage":242,"endY":52.33},"sourceKind":"original","originalOrdinal":"5","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":15,"versionReason":"未列入变动PDF第31—32页新版知识点保留清单；原内容与真题信息保留。","excerpts":[{"page":241,"src":"./assets/environment/env838-bbb6abcfedb9d911-241.webp"},{"page":242,"src":"./assets/environment/env838-bbb6abcfedb9d911-242.webp"}]},{"id":"env838-f3c253313ae07268","subject":"环境学导论","chapter":"第15章 工农业生态系统保护","originalChapter":"第16章 农业生态系统","originalChapterNumber":16,"section":"第4节 课后习题","originalSection":"第4节 课后习题","category":"exercise","title":"简述农业生态系统的概念与组成。","question":"简述农业生态系统的概念与组成。","type":"简答题","answer":"农业生态系统是人类为获取农产品，对一定地域内生物群落及其非生物环境进行组织和调控形成的生态—经济系统。\n组成：①农业生物，包括作物、林木、畜禽、水产动物、微生物及其他相关生物；②非生物环境，包括土壤、水、空气、光热和养分等；③人类投入与管理，包括劳动、技术、设施、能源及组织制度。\n各组分通过食物链、物质循环和能量流动联系，农业生产又与外部市场及社会系统交换产品、资源和信息。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":257,"sourceRange":{"startPage":257,"startY":101.7,"endPage":257,"endY":178.47},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":15,"excerpts":[{"page":257,"src":"./assets/environment/env838-f3c253313ae07268-257.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=235"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-3cca3c231860b486","subject":"环境学导论","chapter":"第15章 工农业生态系统保护","originalChapter":"第16章 农业生态系统","originalChapterNumber":16,"section":"第4节 课后习题","originalSection":"第4节 课后习题","category":"exercise","title":"农业生态系统的特点是什么?","question":"农业生态系统的特点是什么?","type":"简答题","answer":"①人工性：物种配置、耕作与收获受人类强烈控制。\n②生产性：以满足人类对食物和其他农产品的需要为重要目标，经济与生态过程耦合。\n③开放性：持续输入辅助能、物质和技术，并输出农产品及其他物料。\n④结构相对简化：部分集约系统物种和食物网较简单，调节能力可能较弱。\n⑤时空及地域性：受季节、气候、土壤和生产制度影响明显。\n⑥可调控性与风险：科学管理可提高产出，但不合理高投入、过度利用可能损害土水环境及长期生产力。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":257,"sourceRange":{"startPage":257,"startY":178.47,"endPage":257,"endY":256.85},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":15,"excerpts":[{"page":257,"src":"./assets/environment/env838-3cca3c231860b486-257.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=235"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-4707c01b7683898e","subject":"环境学导论","chapter":"第15章 工农业生态系统保护","originalChapter":"第16章 农业生态系统","originalChapterNumber":16,"section":"第4节 课后习题","originalSection":"第4节 课后习题","category":"exercise","title":"农业生态系统面临的环境问题有哪些?","question":"农业生态系统面临的环境问题有哪些?","type":"简答题","answer":"①土壤：侵蚀、压实、有机质下降、酸化、盐渍化及污染。\n②水环境：化肥农药流失、畜禽粪污及养殖排水，可能引起富营养化或其他风险；不合理灌溉还会增加用水压力。\n③大气与气候：氨挥发、部分生产及粪污过程的温室气体排放，秸秆不当焚烧等。\n④生物多样性：单一化经营、生境丧失及不合理用药可能损害天敌与授粉等生态服务。\n⑤废弃物：农膜、包装及生产残余物管理不足。\n应通过养分高效利用、综合病虫害管理、节水、粪污资源化和生态化布局综合应对。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":257,"sourceRange":{"startPage":257,"startY":256.85,"endPage":257,"endY":334.79},"sourceKind":"original","originalOrdinal":"3","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":15,"excerpts":[{"page":257,"src":"./assets/environment/env838-4707c01b7683898e-257.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=235"},{"title":"FAO：浙江湖州桑基鱼塘系统","url":"https://www.fao.org/giahs/around-the-world/detail/china-zhejiang-system/zh","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-56f76c4d0463a071","subject":"环境学导论","chapter":"第15章 工农业生态系统保护","originalChapter":"第16章 农业生态系统","originalChapterNumber":16,"section":"第4节 课后习题","originalSection":"第4节 课后习题","category":"exercise","title":"农业生态系统的水平结构其影响因素是什么?","question":"农业生态系统的水平结构其影响因素是什么?","type":"简答题","answer":"水平结构是农业生态系统内不同生物、生产单元和土地利用方式在平面上的分布、组合及空间联系，例如农田、林带、鱼塘、牧地和居民点的布局。\n影响因素：①气候、地形地貌、土壤、水源与排灌等自然条件；②作物、畜禽及其他生物的生态需求；③交通、市场、劳动力、技术和经营规模；④产权、规划及政策等制度条件；⑤不同单元间的养分、能量与污染输送关系。\n优化应兼顾生产效率与生态连通，减少水土流失和污染，并使布局与当地承载条件匹配。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":257,"sourceRange":{"startPage":257,"startY":334.79,"endPage":257,"endY":412.83},"sourceKind":"original","originalOrdinal":"4","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":15,"excerpts":[{"page":257,"src":"./assets/environment/env838-56f76c4d0463a071-257.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=235"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-79f3a229b84cc458","subject":"环境学导论","chapter":"第15章 工农业生态系统保护","originalChapter":"第16章 农业生态系统","originalChapterNumber":16,"section":"第4节 课后习题","originalSection":"第4节 课后习题","category":"exercise","title":"农业生态系统的辅助形式有哪些?","question":"农业生态系统的辅助形式有哪些?","type":"简答题","answer":"按本章“能量来源”知识点理解，农业生产的辅助能是太阳能直接固定之外、人类为调控生产而投入或利用的能量。\n常见形式：①工业辅助能，如电力、燃料以及机械、化肥等投入品所包含的能量；②生物辅助能，如人畜劳动、饲料和有机肥等投入；③可利用的其他自然能，如风、水力等。\n用途包括耕作、灌溉、排水、施肥、田间管理、收获与加工贮运。\n应提高投入产出效率，避免辅助能和物质投入过量带来的污染。题干“辅助形式”表述不完整，此处按辅助能解释，仍应对照原书确认。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["原题“辅助形式”疑省略“能”，按本章辅助能知识点解释，保留待核对。"],"verified":false,"page":257,"sourceRange":{"startPage":257,"startY":412.83,"endPage":257,"endY":490.39},"sourceKind":"original","originalOrdinal":"5","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":15,"excerpts":[{"page":257,"src":"./assets/environment/env838-79f3a229b84cc458-257.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=235"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-5a6e34cf2539359d","subject":"环境学导论","chapter":"第15章 工农业生态系统保护","originalChapter":"第16章 农业生态系统","originalChapterNumber":16,"section":"第4节 课后习题","originalSection":"第4节 课后习题","category":"exercise","title":"简述生态农业的主要发展模式。","question":"简述生态农业的主要发展模式。","type":"简答题","answer":"主要模式可按生态耦合方式理解：①时空复合，如间作、套作、轮作和农林复合，提高光热与土地利用；②物种共生，如稻鱼、稻鸭等，在适当密度下利用互补关系；③种养循环，如种植—养殖—粪污处理—肥料利用；④基塘系统，如桑基鱼塘，结合水陆生产；⑤流域或村域综合治理，将水土保持、能源和生活环境管理结合。\n选择模式须符合水土、气候、市场及经营条件，明确养分和污染负荷，不能不加控制地将所有副产物直接还田或入水。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":257,"sourceRange":{"startPage":257,"startY":490.39,"endPage":257,"endY":568.37},"sourceKind":"original","originalOrdinal":"6","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":15,"excerpts":[{"page":257,"src":"./assets/environment/env838-5a6e34cf2539359d-257.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=235"},{"title":"FAO：浙江湖州桑基鱼塘系统","url":"https://www.fao.org/giahs/around-the-world/detail/china-zhejiang-system/zh","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-831d877d2de3112a","subject":"环境学导论","chapter":"第15章 工农业生态系统保护","originalChapter":"第16章 农业生态系统","originalChapterNumber":16,"section":"第4节 课后习题","originalSection":"第4节 课后习题","category":"exercise","title":"举例说明中国生态农业的发展现状和发展趋势。","question":"举例说明中国生态农业的发展现状和发展趋势。","type":"简答题","answer":"实例：浙江湖州桑基鱼塘通过种桑、养蚕和养鱼形成水陆复合生产系统，体现物种、空间及物质循环联系。\n现状特点：我国生态农业既有传统复合模式，也有现代节水、精准投入、种养结合和循环利用实践；不同地区发展水平与资源条件差异较大。\n发展趋势：以绿色优质产品为导向，重视减肥减药、节水与土壤健康；强化种养匹配、资源回收和环境风险管理；与数字监测、标准认证、产业链及社会化服务结合。\n生态农业需要可验证的经济和环境绩效，不能只因挂有“生态”名称就推定可持续。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":257,"sourceRange":{"startPage":257,"startY":568.37,"endPage":258,"endY":73.17},"sourceKind":"original","originalOrdinal":"7","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":15,"excerpts":[{"page":257,"src":"./assets/environment/env838-831d877d2de3112a-257.webp"},{"page":258,"src":"./assets/environment/env838-831d877d2de3112a-258.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=235"},{"title":"FAO：浙江湖州桑基鱼塘系统","url":"https://www.fao.org/giahs/around-the-world/detail/china-zhejiang-system/zh","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-73c62a7ad4cc5295","subject":"环境学导论","chapter":"第16章 城乡生态系统保护","originalChapter":"第17章 城市生态学系统保护","originalChapterNumber":17,"section":"第1节 城市生态系统","originalSection":"第1节 概述","category":"knowledge","title":"城市生态系统概念","question":"城市生态系统概念","type":"简答题","answer":"城市生态系统是城市人类与周围生物和非生物环境相互作用而\n形成的一类具有一定功能的网络结构，也是人类在改造和适应自然环\n境的基础上建立起来的特殊的人工生态系统。由自然系统、经济系统\n和社会系统所组成。\n17-1 城市生态系统营养结构","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2007,2013,2025],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。","含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":259,"sourceRange":{"startPage":259,"startY":95.56,"endPage":259,"endY":482.98},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":["2007(名、2013(名, 2025( 名), 【重要程度: 】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":16,"newSectionOrder":1,"newPointOrder":1,"excerpts":[{"page":259,"src":"./assets/environment/env838-73c62a7ad4cc5295-259.webp"}]},{"id":"env838-db97f0d53ed9b428","subject":"环境学导论","chapter":"第16章 城乡生态系统保护","originalChapter":"第17章 城市生态学系统保护","originalChapterNumber":17,"section":"第1节 城市生态系统","originalSection":"第1节 概述","category":"knowledge","title":"城市生态系统的功能","question":"城市生态系统的功能","type":"简答题","answer":"、\n周北海的书上讲城市生态系统有三大基本功能 : (D) 生产功能 ， 即为人类提供丰\n富的物质产品 、 信息产品和知识产品 。(2) 社会消费功能 ， 即为城市居民提供方\n便的生活条件和舒适的栖息环境 。(3) 还原功能 ,， 即通过物质和能量的代谢保证\n自然资源的永续利用和社会经济系统的协调 、 持续与稳定发展 。 总之 ， 城市生\n态系统的 3 种功能是依靠生态系统各组分之间的人口流 、 物质流 、 能量流 、 信\n息流和资金流来实现的 。\n城市生态系统最基本的功能就是系统内部以及系统与外界间能\n量、物质和信息等的交换。\n①能量流：自然生态系统的能量主要来自于太阳辐射，而城市生\n态系统要维持其生产功能和社会消费功能，除了直接利用或间接利用\n太阳能量以外。还必须源源不断地从外部系统输入大量的人工辅助能\n量，如煤炭、石油、电力、液化气等。这些人工能量在城市生态系统\n中流动、转移、使用和消耗，最终以热能的形式排入环境。\n17-2 城市生态系统能流的基本过程\n②物质流\n包括资源流、货物流、人口流、劳力流、智力流。\n人口流：一种特殊的物质流，包括人口在时间上和空间上的\n变化，前者即为人口的自然增长和机械增长：后者是反映城市\n与外部之间人口流动中的过往人流和反映城市内部人口流动\n的交通人流；\n劳力流：是特殊的人口流，包括劳力在时间上的变化，即由\n于就业、退休等导致劳力数量的变动和劳力在空间上的变化\n，即劳力在各职业部门的分配情况的变化；\n智力流：是特殊的劳力流，智力在开发过程中(入学、就读\n、毕业、升学)是智力在时间上的变化，反映着城市智力结\n构的改变过程；而智力在空间上的变化则反映在智力(人才\n)不同部门的改变；\n货物流：货物流最为复杂，它不是简单的输入与输出，其中\n还经过生产(形态、功能的改变)、消耗、累积及排放出废\n弃物等过程。\n③信息流：城市的重要功能之一，就是输入分散的无序的信息，\n输出经过加工的，集中的有序的信息。因此，城市的输出物中，除了\n物质产品和废物外，还有精神产品，这就要靠信息流完成。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。","含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":260,"sourceRange":{"startPage":260,"startY":284.73,"endPage":262,"endY":178.16},"sourceKind":"original","originalOrdinal":"3","sourceMetadata":["【重要程度："],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":16,"newSectionOrder":1,"newPointOrder":2,"excerpts":[{"page":260,"src":"./assets/environment/env838-db97f0d53ed9b428-260.webp"},{"page":261,"src":"./assets/environment/env838-db97f0d53ed9b428-261.webp"},{"page":262,"src":"./assets/environment/env838-db97f0d53ed9b428-262.webp"}]},{"id":"env838-7ee6c9b5c5478c44","subject":"环境学导论","chapter":"第16章 城乡生态系统保护","originalChapter":"第17章 城市生态学系统保护","originalChapterNumber":17,"section":"第1节 城市生态系统","originalSection":"第1节 概述","category":"knowledge","title":"城市生态系统特点","question":"城市生态系统特点","type":"简答题","answer":"①城市生态系统是人工生态系统：城市生态系统是通过人的劳动\n和智慧创造出来的，人工控制对该系统的存在与发展起着决定性的作\n用。\n②城市生态系统是以人为主体的生态系统：在城市生态系统中，\n人口高度集中，其他生物的种类和数量都很少。\n③城市生态系统是不完全的生态系统：城市生态系统中生产者不\n仅数量少，而且其作用也发生了改变。城市中的植物，其主要任务是\n美化景观、消除污染和净化空气等。由于植物不能满足当地消费者的\n粮食需要，必须从城市生态系统以外输入。在城市生态系统中，还往\n往需要异地分解废弃物。\n④城市生态系统是高度开放的生态系统：城市生态系统具有大量\n高速的输入输出流，能量、物质和信息在系统中高度浓集、高速转化\n，转化功率是所有生态系统中最高的。\n⑤城市生态系统是多层次的复杂系统：可分在三个层次的子系统\n：生物(人)-自然环境系统；工业-经济系统；文化-社会系统。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":1,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":259,"sourceRange":{"startPage":259,"startY":482.98,"endPage":260,"endY":284.73},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":["【重要程度:★☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":16,"newSectionOrder":1,"newPointOrder":3,"excerpts":[{"page":259,"src":"./assets/environment/env838-7ee6c9b5c5478c44-259.webp"},{"page":260,"src":"./assets/environment/env838-7ee6c9b5c5478c44-260.webp"}]},{"id":"env838-c57476b0e333b5b0","subject":"环境学导论","chapter":"第16章 城乡生态系统保护","originalChapter":"第17章 城市生态学系统保护","originalChapterNumber":17,"section":"第2节 城市生态系统存在的问题","originalSection":"第2节 城市生态系统存在的问题","category":"knowledge","title":"城市生态系统中各子系统存在的问题及解决措施","question":"城市生态系统中各子系统存在的问题及解决措施","type":"简答题","answer":"城市居民\n[待核对] 生生统家和\n野生生物\n住宅与公共建筑物\n道路设施\n城市生态系统工厂\n人工物质系统 ] 交通运输\n通信设施\n市政管网设施\n非生物系统 ae\n统 ] AR\n环境资源系统 ] 十地\n矿产\n生物能 (食物等 )\n[待核对] fem a\n化石燃料\n17-3 城市生态系统的结构\n子系统 生物系统 人工物质系统 环境资源系统 能源系统\n改变原有的地形地\n大量增加人口 生物能转化后排\n貌；大量使用资源，\n密度：野生动 承纳污染物，改变出大量废物；自然\n消耗能源，排出废弃\n环境特点物稀缺；微生 理化状态；大量消能源属清洁能源；\n物；信息提高生产率\n物活动受到限 耗资源，造成枯竭化石能源利用后\n；管网输送污物改造\n制 排出废弃物\n环境\n破坏自然界的物\n使得环境自净改变自然界的物质\n质循环；降低环境\n能力降低；生平衡；人工物质大量 产生大量污染物\n环境问题 的调节机能；资源\n态系统遭受破在城市中积累；环境 质；环境质量下降\n枯竭，影响系统的\n坏 质量下降\n发展\n编制城市环境规划；\n建立城市系统与\n合理安排生产布局； 改革工艺设备；发\n控制城市人口 其他系统的联系；\n措施 合理利用资源进行 展净化设备；寻找\n；绿化城市 调动区域净化能\n区域环境综合治理； 新能源\n力；合理利用资源\n改革工艺；治理三废","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":0,"pastExamYears":[2004,2024],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。","含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":262,"sourceRange":{"startPage":262,"startY":219.7,"endPage":263,"endY":506.33},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":["2004、2024(论) , 【重要程度:☆☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":16,"newSectionOrder":2,"newPointOrder":1,"excerpts":[{"page":262,"src":"./assets/environment/env838-c57476b0e333b5b0-262.webp"},{"page":263,"src":"./assets/environment/env838-c57476b0e333b5b0-263.webp"}]},{"id":"env838-9303e4298fc309c9","subject":"环境学导论","chapter":"第16章 城乡生态系统保护","originalChapter":"第17章 城市生态学系统保护","originalChapterNumber":17,"section":"第3节 城市生态系统的发展方向","originalSection":"第3节 城市生态系统的发展方向","category":"knowledge","title":"城市的园林绿化","question":"城市的园林绿化","type":"简答题","answer":"城市园林绿化是指通过工程技术和艺术手段，采用改造地形种植\n树木花草、营造建筑和布置园林小路等方式，将园林艺术与城市生活\n相结合的环境绿化工程。随着科技发展和生态宜居城市建设，园林绿\n化的范围扩大到森林公园、名胜风景区、自然保护区、国家公园和度\n假区。\n城市园林绿化建设首先应遵循生态原则。从最大限度改善城市生\n态环境出发，因地制宜，选择绿化树种、灌木的搭配及花卉的点缀等\n；其次是遵循文化原则。充分考虑不同城市的文化特点、历史脉络、\n地域风俗，并将其融入园林绿化之中，使城市园林绿化向着充满人文\n内涵品位的方向发展。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":1,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":263,"sourceRange":{"startPage":263,"startY":548.64,"endPage":264,"endY":226.21},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":["【重要程度:★☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":16,"newSectionOrder":3,"newPointOrder":1,"excerpts":[{"page":263,"src":"./assets/environment/env838-9303e4298fc309c9-263.webp"},{"page":264,"src":"./assets/environment/env838-9303e4298fc309c9-264.webp"}]},{"id":"env838-0516e8da48fed651","subject":"环境学导论","chapter":"第16章 城乡生态系统保护","originalChapter":"第17章 城市生态学系统保护","originalChapterNumber":17,"section":"第3节 城市生态系统的发展方向","originalSection":"第3节 城市生态系统的发展方向","category":"knowledge","title":"城市生物多样性的概念","question":"城市生物多样性的概念","type":"简答题","answer":"生物多样性是生物及其环境形成的生态复合体以及与此相关的\n各种生态过程的综合，包括动物、植物、微生物和它们所拥有的基因\n以及它们与其生存环境形成的复杂的生态系统。\n城市生物多样性保护的实质，可以分为三个层次：\n在城市层次上，城市作为人类聚集中心，其生物多样性是为\n城市中人的生存、发展、休闲之需要面建立和维护城市生态\n系统高效、平衡的生态学标志；\n在区域层次上，城市作为经济中心，具有特殊的地理背景、\n城市中的绿地与农耕生产无关，从这层意义上看，城市生物多\n样性保护是对城市中尚存的本地物种及其生境、生态系统的\n保护；\n在全球层次上，城市作为科技与教育中心，有义务参与珍稀\n、濒危生物的保存、培育和宣传教育。这些都是需要城市承担\n的生物多样性保护义务。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":264,"sourceRange":{"startPage":264,"startY":226.21,"endPage":264,"endY":726.28},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":["【重要程度："],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":16,"newSectionOrder":3,"newPointOrder":2,"excerpts":[{"page":264,"src":"./assets/environment/env838-0516e8da48fed651-264.webp"}]},{"id":"env838-129a748ef0b0dfaf","subject":"环境学导论","chapter":"第16章 城乡生态系统保护","originalChapter":"第17章 城市生态学系统保护","originalChapterNumber":17,"section":"第3节 城市生态系统的发展方向","originalSection":"第3节 城市生态系统的发展方向","category":"knowledge","title":"城市生物多样性保护的措施","question":"城市生物多样性保护的措施","type":"简答题","answer":"①通过城市生物多样性的保护与重建，改善人与绿地系统之间、\n绿地系统内部生物与环境之间的关系。\n②依据城市地理分布的地带性及其在生态区系中的特殊生境条\n件，以自然迁徙物种的生境、本地特殊的生态类型为重点的生态层次\n的多样性保护。\n③借助城市植物园、动物园、苗圃等条件以及技术优势，以濒危\n、珍稀动植物移地保护、优势物种驯化为重点的物种层次的多样性\n保护。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":0,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":266,"sourceRange":{"startPage":266,"startY":223.54,"endPage":266,"endY":529.39},"sourceKind":"original","originalOrdinal":"5","sourceMetadata":["【重要程度: ☆☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":16,"newSectionOrder":3,"newPointOrder":3,"excerpts":[{"page":266,"src":"./assets/environment/env838-129a748ef0b0dfaf-266.webp"}]},{"id":"env838-95e1fcacf1a73844","subject":"环境学导论","chapter":"第16章 城乡生态系统保护","originalChapter":"第17章 城市生态学系统保护","originalChapterNumber":17,"section":"第3节 城市生态系统的发展方向","originalSection":"第3节 城市生态系统的发展方向","category":"knowledge","title":"宜居城市的构建","question":"宜居城市的构建","type":"简答题","answer":"学长提示 : 在老版的蔬上把这个概念叫做生态城市","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。","含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":266,"sourceRange":{"startPage":266,"startY":529.39,"endPage":266,"endY":582.5},"sourceKind":"original","originalOrdinal":"6","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":16,"newSectionOrder":3,"newPointOrder":4,"excerpts":[{"page":266,"src":"./assets/environment/env838-95e1fcacf1a73844-266.webp"}]},{"id":"env838-acd66245d8b8f25b","subject":"环境学导论","chapter":"第16章 城乡生态系统保护","originalChapter":"第18章 农村生态系统保护","originalChapterNumber":18,"section":"第4节 农村生态系统","originalSection":"第1节 概述","category":"knowledge","title":"农村生态系统概念","question":"农村生态系统概念","type":"简答题","answer":"农村生态系统是指在农村地域内以一定形式的物质与能量交换\n而联系起来的相互制约、相互作用的生命与非生命共同有机体，是由\n农田生态系统、森林生态系统、草原生态系统、水域生态系统以及其\n他自然的或人工的生态系统组成的复合生态系统。\n从组成上看，农村生态系统是一个复合系统，由自然生态子\n系统、农业生态子系统、村镇生态子系统三部分组成。\n学长解读 :\n一 、 自然生态子系统 ， 是自然界选择和适应过程的产物 ， 生物物种拥有环境允\n许的最大多桩性 。 复杂相互作用可有效调控生物种群水平 ， 系统有抵御外界变\n化的缓冲能力和较高综合生产力 。 能合流动是绿色植物自我启动的自持续过程\n， 运行主要由太阳能与生物能支配 ， 表现出强烈的自然节律性 。 (农村里的山\n水林田湖是大自然自己演化出来的 ， 靠太阳能驱动 ,不用人管就能自己运转几\n千万年 。 这是整个农村生态系统的底盘 。 底盘不散 ， 上面盖的农田和村镇才有\n根基 。)\n二 、 农业生态子系统 ， 是自然与人类交互作用的结合区 ， 既受自然规律制约又\n受经济规律支配 。 生产者和消费者在空间上是分离的一 ”种的粮食拉到城里被\n吃掉了 ， 养分就被带走了 ， 必须靠施肥补回来 ， 所以具有明显的开放性 。\n农业子系统是天在中间的那个一老天符管着你能不能丰收 ,市场管着你种什\n么能赚钱 。 你想种水稻但今年干旱你就种不了 ,你想种经济作物但价格跌了你\n就不敢种 。 自然的手和市场的手同时在操纵这块因地 。\n三 、 村镇生态子系统 ， 其属性与城市生态系统相接近 ， 由乡镇及农村非农活动\n组成 ， 系统演变发展主要受人类社会经济规律主宰 ， 化石能是系统运行的主要\n能源 。 原有的自然生态系统结构与功能发生根本变化 ， 人类社会经济活动及人\n类自身再生产成为影响系统的决定性国素 , 因此村镇生态子系统具有人工杀绕\n的典型特征 。 村镇说白了就是农村里的微型城市 。 有人口聚集 、 有商店工厂 、\n有简单的基础设施 ， 靠煤油电驱动 。 和城市比只是规模小一城市几百方人在\n高楼大厦里 ， 村镇几百几千人在低类房子里 。 但它面临的问题和域市是同一性\n质一一垃圾怎么收 、 污水怎么排 、 能源从哪来 。 最要命的是村镇有域市的问题\n却没有城市的解决方案一没有下水道 、 没有污水处理厂 、 没有坟圾转运体系","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":0,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。","含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":271,"sourceRange":{"startPage":271,"startY":101.66,"endPage":272,"endY":251.81},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":["【重要程度: ☆☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":16,"newSectionOrder":4,"newPointOrder":1,"excerpts":[{"page":271,"src":"./assets/environment/env838-acd66245d8b8f25b-271.webp"},{"page":272,"src":"./assets/environment/env838-acd66245d8b8f25b-272.webp"}]},{"id":"env838-9ec7a58deedb2b0a","subject":"环境学导论","chapter":"第16章 城乡生态系统保护","originalChapter":"第18章 农村生态系统保护","originalChapterNumber":18,"section":"第4节 农村生态系统","originalSection":"第1节 概述","category":"knowledge","title":"农村生态系统的特点","question":"农村生态系统的特点","type":"简答题","answer":"在农村生态系统中，自然生态子系统是基础，农业生态子系统是\n主体，村镇生态子系统则是不可缺少的重要组成。与农村生态系统\n这一特殊的结构相关联的是该系统本身的独特性，具体表现在如下\n几个方面：\n(1 )目的性：农村生态系统是在自然生态系统的基础上，经\n过人类的改造而形成的适合人类生存的高级生态系统。人类经济活\n动贯穿于整个系统的运行过程之中，利益是该系统的核心目标。\n(2 )非自律性：农村生态系统内部那种简单的食物链结构不\n复存在，取而代之的是一种复杂的生态——经济结构。农村生态系统\n仅仅依靠自然能(太阳能、生物能)已无法满足系统的正常运转，\n而必须从其他生态系统(如城市生态系统等)输入能量，并且系统\n产出也以一定的形式(如农产品)向其他系统输出。\n(3 )自然节律性；农村是以农业生产为基础的社会经济实\n体，农业生态子系统是农村生态系统的主体结构。农业生产以动植\n物的再生产为基础，以开发利用光、热、水、土、气和各种营养元素\n为起点，其每个环节都包含着大量的自然过程，再加上农业生产\n布局具有大面积、分散的特点，深受自然界各因素的影响，表\n现出明显的自然节律性( 如季节性) 。\n(4 )地域差异性：我国疆域辽阔，地形地势复杂，又地处温、\n热两带，自然条件具有明显的地域差异。要促使农村生态系统的正常\n运转，寻求经济的持续发展，必须遵循因地制宜的原则。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":0,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":272,"sourceRange":{"startPage":272,"startY":251.81,"endPage":273,"endY":204.48},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":["【重要程度: ☆☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":16,"newSectionOrder":4,"newPointOrder":2,"excerpts":[{"page":272,"src":"./assets/environment/env838-9ec7a58deedb2b0a-272.webp"},{"page":273,"src":"./assets/environment/env838-9ec7a58deedb2b0a-273.webp"}]},{"id":"env838-c9e201b409856641","subject":"环境学导论","chapter":"第16章 城乡生态系统保护","originalChapter":"第18章 农村生态系统保护","originalChapterNumber":18,"section":"第4节 农村生态系统","originalSection":"第1节 概述","category":"knowledge","title":"农村生态系统的功能","question":"农村生态系统的功能","type":"简答题","answer":"(1 ) 供给功能(基础支撑)\n作为基础生产单元，承担物质生产核心职能。通过初级/次级生产\n为城乡居民提供生活资料，支撑城乡社会经济发展，是城市生态系统\n的物质供给源。\n(2) 调节功能(空间载体)\n兼具居住承载与文化传承双重作用：既为居民提供生产生活空间\n，维系社区稳定；又作为传统文化存续载体，吸纳人口聚居形成乡村\n社区单元。\n(3) 文化功能(价值载体)\n保存民族文化基因库，维系传统文化多样性。作为现代知识教育\n实践场域，兼具美学价值与休闲功能，是城乡文化互动的重要纽带。\n(4) 生态功能(环境屏障)\n发挥区域生态安全保障作用：通过气候调节、水土保持、污染净\n化等生态服务，构建城乡生态屏障。其广域分布特征使其成为国家生\n态安全格局的关键支撑。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":273,"sourceRange":{"startPage":273,"startY":204.48,"endPage":273,"endY":722.54},"sourceKind":"original","originalOrdinal":"3","sourceMetadata":["【重要程度:☆☆☆☆"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":16,"newSectionOrder":4,"newPointOrder":3,"excerpts":[{"page":273,"src":"./assets/environment/env838-c9e201b409856641-273.webp"}]},{"id":"env838-23610257595d15da","subject":"环境学导论","chapter":"第16章 城乡生态系统保护","originalChapter":"第18章 农村生态系统保护","originalChapterNumber":18,"section":"第4节 农村生态系统","originalSection":"第1节 概述","category":"knowledge","title":"农村生态系统存在的问题及保护","question":"农村生态系统存在的问题及保护","type":"简答题","answer":"农村生态系统存在的问题有自然生态环境的破坏、土地占用和土\n壤变化、水污染、生活垃圾污染和其他污染。\n[1]自然生态环境的破坏\n生态破坏主要指由于开发利用农村生态系统中的资源不当而导\n致该生态系统功能退化或质量下降的现象。如资源开发过度或不当导\n致森林草原湖泊农田等生态系统退化，抗干扰与破坏的能力下降，适\n应与抵抗各种新情况尤其是自然灾害的能力差；生物的生存环境恶化\n，多样性逐渐减少，食物网链的某些环节薄弱化趋势明显等。\n[2]土地利用失衡土地占用和土壤变化\n(1 )违反自然规律的开发导致土地流失或土壤退化。不当开发\n就是开发利用不符合土地自然性质和结构。一是大量农药化肥造成土\n壤板结丧失自组织能力和天然肥力；二是为在有限土地上获得更多作\n物把轮作周期从几十年缩短到几年甚至连年耕作、过度精耕加快矿物\n质和有机质枯竭、破坏土壤结构；三是增加的畜牧集中在逐渐缩小的\n牧场上加大放牧负载，在原本优良的牧场留下大片荒漠区。\n(2)人为侵占导致土地流失。人口增长、交通工具发展、基础\n设施建设、通信系统延伸缩短了城乡距离，加上农村地价便宜，开发\n大片住宅成为可能，大量农业用地转为农村住宅用地。\n[3]水环境污染\n我国大部分地区农村都属原发建成的自然村落，缺乏整体规划，\n公共排污及治污设施不健全，基本上处于污水乱流、垃圾乱倒、粪土\n乱堆的状态。近年随着农村产业结构进一步调整，农业产业化工业化\n进程加快，农产品加工小企业、规模养殖和种植业迅速发展。由于缺\n乏基本的污水和固体垃圾回收处理系统，固体垃圾和人畜粪便大多直\n接露天堆放，生活污水和生产污水大多直接排放到村边沟壕或村庄地\n·254-\n面，降雨时被冲刷渗透到地下水或河流湖泊中，由点到面逐渐扩张和\n蔓延。\n[4]固废污染加剧\n①农民环境意识较差，柴草乱堆、污水乱流、粪土乱丢、垃圾乱\n倒、杂物乱放、畜禽散养——不仅影响村容村貌，还对水源造成污染\n②垃圾成分发生很大变化。以前农村产生的生活垃圾可以就地\n化解循环使用——菜叶喂猪、剩饭喂鸡、草木灰还田。现在生活水平\n提高方式发生大变化，塑料和电子产品产生的难以降解的废品占比越\n来越大。\n③农村成为城市垃圾的转移地。因为天地广阔管理松散，往往成\n为城市转移生活建筑垃圾、有毒有害工业医疗垃圾的选择地。\n[5]复合型污染\n(1 )农业面源污染。种类主要有畜禽粪便污染、农药化肥过量\n使用加剧环境污染、收获时节秸秆焚烧造成大气污染。\n(2)生物质燃烧导致大气污染。广大农村由于生存条件限制，\n燃料问题突出，大多以秸秆甚至乡间杂草为主要燃料，燃烧时释放大\n量烟尘。\n(3 )土壤污染加剧。为追求农作物高产短期经济效益，过量施\n用化肥农药除草剂非降解地膜现象普遍。化肥导致土地固化、团粒结\n构破坏、氮磷钾比例失调、地力下降。农药喷洒大部分附着于作物外\n表也会因风雨进入土壤。除草剂含砷化物和重金属离子。非降解地膜\n回收率低，大量废旧农膜残留在耕层中破坏结构引起板结。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":0,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":273,"sourceRange":{"startPage":273,"startY":722.54,"endPage":276,"endY":68.24},"sourceKind":"original","originalOrdinal":"4","sourceMetadata":["【重要程度:☆☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":16,"newSectionOrder":4,"newPointOrder":4,"excerpts":[{"page":273,"src":"./assets/environment/env838-23610257595d15da-273.webp"},{"page":274,"src":"./assets/environment/env838-23610257595d15da-274.webp"},{"page":275,"src":"./assets/environment/env838-23610257595d15da-275.webp"},{"page":276,"src":"./assets/environment/env838-23610257595d15da-276.webp"}]},{"id":"env838-e385e118a7d227df","subject":"环境学导论","chapter":"第16章 城乡生态系统保护","originalChapter":"第18章 农村生态系统保护","originalChapterNumber":18,"section":"第5节 农村生态系统健康的基本内涵","originalSection":"第2节 农村生态系统健康的基本内涵","category":"knowledge","title":"生态系统健康","question":"生态系统健康","type":"简答题","answer":"生态系统健康已不单纯是一个生态学的定义，而是一个将生态\n—社会经济一人类健康3个领域整合在一起的综合理念，即生态系\n统健康应该包含两方面内涵：满足人类社会合理要求的能力和生态\n系统本身自我维持与更新的能力。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":1,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":276,"sourceRange":{"startPage":276,"startY":106.23,"endPage":276,"endY":301.48},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":["【重要程度: ★☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":16,"newSectionOrder":5,"newPointOrder":1,"excerpts":[{"page":276,"src":"./assets/environment/env838-e385e118a7d227df-276.webp"}]},{"id":"env838-9302fd848966ac2b","subject":"环境学导论","chapter":"第16章 城乡生态系统保护","originalChapter":"第18章 农村生态系统保护","originalChapterNumber":18,"section":"第5节 农村生态系统健康的基本内涵","originalSection":"第2节 农村生态系统健康的基本内涵","category":"knowledge","title":"农业生态系统健康","question":"农业生态系统健康","type":"简答题","answer":"农业生态系统健康指农业生态系统免受发生“失调综合征”、处\n理胁迫的状态和满足持续生产农产品的能力。健康的农业生态系统具\n有良好的生态环境与农业生物、合理的时空结构、清洁的生产方式，\n以及具有适度的生物多样性和持续农业生产力的一种系统状态或动\n态过程。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":1,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":276,"sourceRange":{"startPage":276,"startY":301.48,"endPage":276,"endY":531.08},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":["【重要程度: ★☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":16,"newSectionOrder":5,"newPointOrder":2,"excerpts":[{"page":276,"src":"./assets/environment/env838-9302fd848966ac2b-276.webp"}]},{"id":"env838-01a8e31ff701a34c","subject":"环境学导论","chapter":"第16章 城乡生态系统保护","originalChapter":"第18章 农村生态系统保护","originalChapterNumber":18,"section":"第5节 农村生态系统健康的基本内涵","originalSection":"第2节 农村生态系统健康的基本内涵","category":"knowledge","title":"城市生态系统健康","question":"城市生态系统健康","type":"简答题","answer":"城市生态系统健康指为人类提供服务的自然环境和人工环境组\n成的生态系统是健康和完整的，也包括城市居住者的健康和社会健康","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":276,"sourceRange":{"startPage":276,"startY":531.08,"endPage":276,"endY":671.15},"sourceKind":"original","originalOrdinal":"3","sourceMetadata":["【重要程度：^"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":16,"newSectionOrder":5,"newPointOrder":3,"excerpts":[{"page":276,"src":"./assets/environment/env838-01a8e31ff701a34c-276.webp"}]},{"id":"env838-1f50ccbd6cae1831","subject":"环境学导论","chapter":"第16章 城乡生态系统保护","originalChapter":"第18章 农村生态系统保护","originalChapterNumber":18,"section":"第5节 农村生态系统健康的基本内涵","originalSection":"第2节 农村生态系统健康的基本内涵","category":"knowledge","title":"农村生态系统健康","question":"农村生态系统健康","type":"简答题","answer":"农村生态系统健康指农村生态系统能够实现农村环境健康目标、\n生态系统活力目标、农业生产与乡镇企业发展目标的能力。健康的农\n村生态系统具有稳定性和可持续性，所包含的各类生态系统通过相互\n补充而具有一定的自我调节和对胁迫受损的恢复能力。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":1,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":276,"sourceRange":{"startPage":276,"startY":671.15,"endPage":277,"endY":133.38},"sourceKind":"original","originalOrdinal":"4","sourceMetadata":["【重要程度: ★☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":16,"newSectionOrder":5,"newPointOrder":4,"excerpts":[{"page":276,"src":"./assets/environment/env838-1f50ccbd6cae1831-276.webp"},{"page":277,"src":"./assets/environment/env838-1f50ccbd6cae1831-277.webp"}]},{"id":"env838-af2cbd9993a57660","subject":"环境学导论","chapter":"第16章 城乡生态系统保护","originalChapter":"第18章 农村生态系统保护","originalChapterNumber":18,"section":"第6节 生态村建设","originalSection":"第3节 生态村建设","category":"knowledge","title":"环境污染治理","question":"环境污染治理","type":"简答题","answer":"针对农村存在的环境问题，积极开展农村环境污染综合治理，重\n点抓好水污染治理、饮用水源保护、固体废弃物治理、人畜粪便污染\n治理和综合利用。加大农村环保执法力度，对污染和破坏农村环境的\n违法行为依法查处。对高能耗、污染严重的乡镇企业进行环境污染状\n况评估，对不符合治污排污标准的厂矿企业停产整顿，达不到治污标\n准的企业必须关停。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":277,"sourceRange":{"startPage":277,"startY":343.68,"endPage":277,"endY":578.63},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":16,"newSectionOrder":6,"newPointOrder":1,"excerpts":[{"page":277,"src":"./assets/environment/env838-af2cbd9993a57660-277.webp"}]},{"id":"env838-0e1277a3ccdf1a78","subject":"环境学导论","chapter":"第16章 城乡生态系统保护","originalChapter":"第18章 农村生态系统保护","originalChapterNumber":18,"section":"第6节 生态村建设","originalSection":"第3节 生态村建设","category":"knowledge","title":"生态经济建设","question":"生态经济建设","type":"简答题","answer":"农业标准化融技术、经济、管理于一体，是“科技兴农”的载体和\n基础，是农业增长方式由粗放型向集约型转变的重要内容之一。全面\n推进农业标准化技术的推广，大力发展农村循环经济和推行清洁生产\n，把农村产业结构的调整和推广清洁生产工艺、实用治理技术、发展\n环保产业结合起来，全面推进农村生态环境建设。\n学长解读 :农业标准化就是把怎么种地变成一套规范流程一什么时伟播种 、\n施多少肥 、 怎么防虫 、 什么时候收割 。 标准化种出来的东西品质稳定可以追涛\n能够卖出更高的价格 。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。","含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":277,"sourceRange":{"startPage":277,"startY":578.63,"endPage":278,"endY":168.79},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":16,"newSectionOrder":6,"newPointOrder":2,"excerpts":[{"page":277,"src":"./assets/environment/env838-0e1277a3ccdf1a78-277.webp"},{"page":278,"src":"./assets/environment/env838-0e1277a3ccdf1a78-278.webp"}]},{"id":"env838-459cad0bcdc6409b","subject":"环境学导论","chapter":"第16章 城乡生态系统保护","originalChapter":"第18章 农村生态系统保护","originalChapterNumber":18,"section":"第6节 生态村建设","originalSection":"第3节 生态村建设","category":"knowledge","title":"人居环境建设","question":"人居环境建设","type":"简答题","answer":"农村人居环境是由农村社会环境、自然环境和人工环境共同组\n成的，是对农村的生态、环境、社会等各方面的综合反映，是城乡\n人居环境中的重要内容，其规划对于指导农村经济、环境、社会协\n调发展以及区域整体协调发展具有重要的意义。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":278,"sourceRange":{"startPage":278,"startY":168.79,"endPage":278,"endY":341.28},"sourceKind":"original","originalOrdinal":"3","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":16,"newSectionOrder":6,"newPointOrder":3,"excerpts":[{"page":278,"src":"./assets/environment/env838-459cad0bcdc6409b-278.webp"}]},{"id":"env838-1ace241d1ae285ee","subject":"环境学导论","chapter":"第16章 城乡生态系统保护","originalChapter":"第18章 农村生态系统保护","originalChapterNumber":18,"section":"第6节 生态村建设","originalSection":"第3节 生态村建设","category":"knowledge","title":"农村人居环境规划内容","question":"农村人居环境规划内容","type":"简答题","answer":"(1)村庄道路硬化：村庄之间、村庄内部的道路具有公共产\n品属性，是方便农民生活、提升居住质量、支撑农村经济社会发展最\n基本的硬件条件。\n(2)村镇生活垃圾污水治理：近年来，不少村庄的垃圾随意\n堆弃，污水不处理，肆意排放，严重影响村容村貌。在社会主义新农\n村建设中，要将创建公共卫生放在重要地位，加强农村生活污染治理\n。可结合各地实际，积极推进生活垃圾的分类收集和就地回收利用，\n坚持减量化、无害化，推行“户分类、村收集、乡运输、县处理”的农\n村生活垃圾处理方式。\n(3)加强农居安全：在村庄整治中，应引导农房建设逐渐从\n单纯追求面积向不断完善功能转变，从单纯注重住房建设向注重改善\n居住环境转变，从简单模仿建筑和装修形式向更加注重安全和乡土特\n色转变，既满足抗震、通风、采光、保暖、消防、安全等建筑结构要\n求，也要适应现代农村发展，妥善考虑储藏、晾晒、团聚等方面的需\n要。\n(4 )改善人居生态环境：充分利用村庄原有的设施和条件，\n按照公益性、急需性和可承受性的原则，改善农民最基本的生产生活\n条件，重点解决农村喝干净水、用卫生厕、走平坦路、住安全房的问\n题。加大村庄整治力度，要按照城乡统筹、以城带乡，政府引导、\n农民主体、社会参与，科学规划、分步实施，分类指导、务求实效\n的原则，充分依托县域小城镇经济社会的发展优势，推动村庄整治由\n点向片区、面上和县域扩展。\n(5 )优先发展重点镇：重点镇对于带动现代农业、为农村特\n色产业服务、改善农村人居环境作用明显。需要加大资金、政策支持\n力度，优先支持重点镇供水、排水、供电、供气、道路、通信、广播\n电视等基础设施和学校、卫生院、文化站、幼儿园、福利院等公共服\n务设施的建设，积极引导社会资金参与重点小城镇建设，改善人居生\n态环境，增强集聚产业和吸纳人口、繁荣县域经济的能力","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":278,"sourceRange":{"startPage":278,"startY":341.28,"endPage":279,"endY":442.0},"sourceKind":"original","originalOrdinal":"4","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":16,"newSectionOrder":6,"newPointOrder":4,"excerpts":[{"page":278,"src":"./assets/environment/env838-1ace241d1ae285ee-278.webp"},{"page":279,"src":"./assets/environment/env838-1ace241d1ae285ee-279.webp"}]},{"id":"env838-7335612640d01091","subject":"环境学导论","chapter":"第16章 城乡生态系统保护","originalChapter":"第18章 农村生态系统保护","originalChapterNumber":18,"section":"第6节 生态村建设","originalSection":"第3节 生态村建设","category":"knowledge","title":"生态文化建设","question":"生态文化建设","type":"简答题","answer":"生态文明是社会文明体系的基础，是人类遵循自然生态系统\n规律，以人与自然、人与人、人与社会和谐共生、全面发展、持续\n繁荣为基本宗旨的文化伦理形态。目前，我国农村生态文明的建设比\n较薄弱，形势严峻。由于农村工业化的迅速加快，农村的生态破坏、\n环境污染、资源浪费等现象非常突出，成为危及农民身体健康和财产\n安全的重要因素，制约了农村经济的可持续发展。因此，必须牢固树\n立生态文明观，重视人与自然、人与人、人与社会的和谐，不断化解\n冲突和生态危机，全面推进农村生态文明健康协调的发展。\n(1 )大力提升农村基层干部的生态意识：农村干部是基层\n农村的政治核心人物，是农民的带头人和主心骨。因此，必须强化农\n村干部的生态意识和绿色GDP意识，同时把选派到农村任职的大\n学生村官当作生态建设的生力军。各级政府既要大力倡导生态文\n明建设，更要身体力行，率先做出榜样。切实倡导“保住青山绿水\n也是政绩”的政绩观，把生态建设和保护成效作为首要标志纳入干部\n的实际考核评价体系中，将可持续发展的生态理念贯穿于实践行动中\n，以期真正达到上行下效，蔚然成风。\n(2)增强群众生态保护观念：建设生态文明，目的是让人民\n群众在良好的生态环境下生活得更舒适、更幸福。要在全社会牢固树\n立生态文明的观念，充分利用各级政府及新闻传媒等多种渠道和各\n种载体，加大对生态思想的宣传教育力度，牢固树立生态文明观、道\n德观、价值观、消费观，强化农民生态保护意识，维护绿色环境，倡\n导科学、文明、健康的生活方式，让文明进步、.积极向上、保护生\n态的观念深入人心，并潜移默化地落实到人们自觉的行动中去，使他\n们积极地承担起参与生态环境建设的责任和义务\n(3)积极推进农村生态环境建设，提高农民生活质量：生态文\n明观的核心是“人与自然协调发展”。统筹人与自然和谐发展，是保\n持我国经济、社会持续健康发展的迫切要求，也是保证人类健康的生\n存环境、保证人的全面发展的迫切要求。农村的生态环境建设是搞好\n新农村建设的基础和保障，事关农民的切身利益，事关农村的和谐稳\n定。\n(4)切实制定和抓好农村环境保护的法规条例：凡事预则\n立，立则行。推进农村生态环境建设，加大环保管理力度，加强环境\n立法的完整性和执法的具体操作性，推进环保规范化、制度化，切实\n做到农村环保有章可循、有法可依，依法可行，在生态建设的全局\n上处于主动地位，有条不紊地发展。\n(5 )加大对农村环境保护的技术和资金投入：要真正落实\n保护好农村的生态环境，必须明确目标，加大资金投入，加强污染防\n治；增加技术含量，研究和推广高新农业技术，降低农药、化肥、农\n膜污染的影响，改善土壤、水体和空气环境质量；严格控制农村企业\n的工业污染，抓出实效。此外，应建立有效的应急系统，提高抵御自\n然灾害和人为灾害的应急能力，从而真正推进农村生态环境的综合整\n治，切实解决危害农村群众健康和影响农业可持续发展的突出环境问\n题。同时，也要建立健全部门协调机制，以保障农村环境保护目标最\n终实现。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":279,"sourceRange":{"startPage":279,"startY":442.0,"endPage":281,"endY":336.01},"sourceKind":"original","originalOrdinal":"5","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":16,"newSectionOrder":6,"newPointOrder":5,"excerpts":[{"page":279,"src":"./assets/environment/env838-7335612640d01091-279.webp"},{"page":280,"src":"./assets/environment/env838-7335612640d01091-280.webp"},{"page":281,"src":"./assets/environment/env838-7335612640d01091-281.webp"}]},{"id":"env838-214f9151a4f8afbd","subject":"环境学导论","chapter":"第16章 城乡生态系统保护","originalChapter":"第18章 农村生态系统保护","originalChapterNumber":18,"section":"第6节 生态村建设","originalSection":"第3节 生态村建设","category":"knowledge","title":"生态文明村建设","question":"生态文明村建设","type":"简答题","answer":"(1 )以样板为表率，深入推进生态文明村的创建\n创建“生态文明村”是农村发展的目标和动力，是改变农村落后的\n生活方式、改善人居环境，推进农村小康社会的有效载体。要进一步\n深化干部群众对生态文明村创建的认识，做好推广普及工作。\n(2)进一步发展和完善生态文明村的硬件建设，加快“三农”发展步\n伐\n以生态文明村为载体，加大对生态文明村硬件建设的投入，搞\n好农村道路硬底化建设。道路硬底化建设不仅能改善生产生活条件，\n解决当地农民群众的行路难，更能改善农村的投资环境，带动农业生\n态产业化发展，推动农村经济发展和农民收入的提高。\n(3 )以创建生态文明村为载体，提升农民的文明程度和知识水平\n创建生态文明村不只是村容村貌的巨变，更要注重农民思想观\n念的改变。要通过多种方式和手段开展生态文明知识的宣传活动，以\n“文明化、生态化、知识化”为目标，紧紧抓住“文化、科技、卫生`三\n太资源方将期塞yNyA 数YS 月作为\n下乡'”活动的契机，深入指导和帮助农民成为新时代者更论、考能\n力、讲文明的社会主义新型农民。\n(4 )大力加强农村生态文化建设、砌筑理背部炎圩文明复盟\n文明乡风是生态文化的内在组成部分、直播休现普炎\u0000的人史\u0000\n神，反映着农民的精神风貌。加强农村坐态文化建设，培育患悉天明\n乡风，是文脉的延续，更是文明的需求。\n(5 )牢固树立生态文化观念，发挥其引导启发作用\n发展农村和谐文化，倡导生态文化理念，在农村干部群众中宰图\n树立生态文化意识，注重生态道德教育和义务教育。观念是行动的先\n导，观念形成习惯。发展农村生态文化是新农村文明社会生存并保持\n活力的精神支柱。\n(6 )着力完善农村生态文化基础设施建设\n基础设施是条件和保障，要营造良好的农村文化环境，规范农村\n文化大院，建设成为集娱乐、休闲、体育、培训为一体的综合性大院\n；完善各级生态文化建设的硬件设施，如垃圾分类箱、节水节电指示\n牌等标志性设施；建立生态文化教育基地，设置生态文化宣传栏、制\n作生态文化墙等。\n(7 )开展生态文化创建活动，培育文明乡风\n乡风文明是新农村的灵魂，农民是推动生态文化、培育文明乡风\n的实践者、创造者。真正做到用生态文化建设生态文明，就要讲实效\n、落实处，培育文明乡风，使崇尚和谐的生态文化内化为农民的思维\n方式和行为习惯。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":281,"sourceRange":{"startPage":281,"startY":336.01,"endPage":283,"endY":57.07},"sourceKind":"original","originalOrdinal":"6","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":16,"newSectionOrder":6,"newPointOrder":6,"excerpts":[{"page":281,"src":"./assets/environment/env838-214f9151a4f8afbd-281.webp"},{"page":282,"src":"./assets/environment/env838-214f9151a4f8afbd-282.webp"},{"page":283,"src":"./assets/environment/env838-214f9151a4f8afbd-283.webp"}]},{"id":"env838-e8cd8c425ea8ce04","subject":"环境学导论","chapter":"第16章 城乡生态系统保护","originalChapter":"第18章 农村生态系统保护","originalChapterNumber":18,"section":"第7节 生态村建设模式","originalSection":"第4节 生态村建设模式","category":"knowledge","title":"生态村建设模式","question":"生态村建设模式","type":"简答题","answer":"[1]生态农业主导型生态村\n生态农业园区是伴随着生态农业产业化进程而出现的一种产物，\n利用最新的生态农业技术，在一定的地区内以市场为导向，进行农业\n最新科技成果的试验、展示、推广与销售，综介组织科研、旅游、试\n验等多种功能，是传统农业向现代农业进行转变的方式之一，能够在\n保证生态效益和社会效益的同时提高农业生产的收益，并带动所\n在地区生态农业的整体发展。主要形式为农业生态生产园区、农业\n生态观光园区、农业生态示范园区等。\n[2]旅游文化依托型生态村\n旅游文化依托型生态村，以农事活动为基础，以农业生产经营为\n特色，将农业经营、民俗文化及旅游资源融为一体，吸引游客前来观\n赏、品尝、购物、体验、休闲和度假。这类生态村主要凭借区位优势\n与便利的交通条件，打生态农业旅游和生态民俗文化牌。该类村庄的\n共同特点是与旅游景区毗邻，部分村庄已形成较分散的服务区，为前\n来景区旅游的游客提供住宿、餐饮、购物等便利条件。\n[3]特色产品开发型生态村\n特色产品开发型生态村以发展特色产业为主，适合经济基础相对\n较好、村民思想观念较为先进且有独特优势资源的乡村。要依托本\n村的资源优势，开发出适合本村发展的特色产品。当特色产品做大\n做强后，形成优势产业，并带动本村其他产业的发展，以此提高村民\n的收入，改善人居环境。\n[4]工业型生态村\n工业型生态村的特点是具有较好的矿产资源，村办企业发达，经\n济状况良好，但开山采石破坏了生态环境，且矿产生产带来的扬尘污\n染较重，村庄生态环境恶劣。\n[5]社区型生态村\n社区型村庄特点是种植特色果木品种，以水果自由采摘为主，以\n开展农家乐主题的农业观光游，生态农庄初具规模。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":0,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":283,"sourceRange":{"startPage":283,"startY":97.06,"endPage":285,"endY":77.5},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":["【重要程度:☆☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":16,"newSectionOrder":7,"newPointOrder":1,"excerpts":[{"page":283,"src":"./assets/environment/env838-e8cd8c425ea8ce04-283.webp"},{"page":284,"src":"./assets/environment/env838-e8cd8c425ea8ce04-284.webp"},{"page":285,"src":"./assets/environment/env838-e8cd8c425ea8ce04-285.webp"}]},{"id":"env838-3e0091a953deec6c","subject":"环境学导论","chapter":"第16章 城乡生态系统保护","originalChapter":"第17章 城市生态学系统保护","originalChapterNumber":17,"section":"第3节 城市生态系统的发展方向","originalSection":"第3节 城市生态系统的发展方向","category":"knowledge","title":"城市生物多样性面临的威胁","question":"城市生物多样性面临的威胁","type":"简答题","answer":"过度掠取：过度掠取指掠取速度超过一个种群繁殖更新的速度\n。当该物种受到法律保护时，这种掠取就成了偷猎，历史上不少大型\n动物就是因此而绝灭的。\n栖息地丧失：栖息地丧失通常是指多样性极其丰富的自然生\n态系统向多样性极其单调的农业生态系统转变。一个地区自然植被面\n积的陡然下降，常导致生物栖息地被隔离开来，形成一个个孤立的生\n态环境，限制种内基因的交流，遗传多样性因此丧失一部分，该种群\n对疾病、猎捕以及偶发灾变的抵抗力随之下降，这样该种群就有可能\n走下坡路。\n环境污染：环境污染对生物构成广泛而严重的威胁。废水、废\n气、固废、噪声等不仅对周围生境中的生物有极大的生存影响，而且\n对人类身体健康的影响也备受关注。环境污染中的重金属元素、微尘\n、有毒有害有机物等通过生物富集等各种途径进入人体，人类在破坏\n环境、危害其他生物的同时也在谋杀自己。\n气候变化：气候变化是又一个威胁生物生存的因素，它常与区\n域性植被格局的改变有关。涉及全球 浓度升高、区域性厄尔尼诺\n效应和季风规律以及地方性火灾对北方森林、珊瑚礁、红树林、湿\n地等会有强烈影响。\n物种引进：物种引进是不容忽视的问题。在许多海岛上，引进\n植物已取代当地土著植物，这种现象称为生态入侵。引进植物已被认\n为是美国国家公园所面临的最大威胁，引进鱼种使具有极高特有种的\n非洲裂谷一些湖泊里的土著鱼种濒临绝灭边缘。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"removed","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":264,"sourceRange":{"startPage":264,"startY":726.28,"endPage":265,"endY":700.63},"sourceKind":"original","originalOrdinal":"3","sourceMetadata":["【重要程度： l"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":16,"versionReason":"未列入变动PDF第31—32页新版知识点保留清单；原内容与真题信息保留。","excerpts":[{"page":264,"src":"./assets/environment/env838-3e0091a953deec6c-264.webp"},{"page":265,"src":"./assets/environment/env838-3e0091a953deec6c-265.webp"}]},{"id":"env838-2d2a343253c348a2","subject":"环境学导论","chapter":"第16章 城乡生态系统保护","originalChapter":"第17章 城市生态学系统保护","originalChapterNumber":17,"section":"第3节 城市生态系统的发展方向","originalSection":"第3节 城市生态系统的发展方向","category":"knowledge","title":"城市生物多样性保护的意义","question":"城市生物多样性保护的意义","type":"简答题","answer":"作为城市生态系统中的动植物和微生物，一方面它们自身的生存\n与发展受着城市环境的严重制约；另一方面，它们的种类和群体水\n平对城市环境起着积极的不可替代的改善作用。保护城市生物多样\n性，实际上就是保护人居环境，保护人类自己，并促进城市生态系统\n健康有序地发展。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"removed","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":265,"sourceRange":{"startPage":265,"startY":700.63,"endPage":266,"endY":223.54},"sourceKind":"original","originalOrdinal":"4","sourceMetadata":["【重要程度: ★☆☆☆ )"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":16,"versionReason":"未列入变动PDF第31—32页新版知识点保留清单；原内容与真题信息保留。","excerpts":[{"page":265,"src":"./assets/environment/env838-2d2a343253c348a2-265.webp"},{"page":266,"src":"./assets/environment/env838-2d2a343253c348a2-266.webp"}]},{"id":"env838-bf10102a5c1c7042","subject":"环境学导论","chapter":"第16章 城乡生态系统保护","originalChapter":"第17章 城市生态学系统保护","originalChapterNumber":17,"section":"第3节 城市生态系统的发展方向","originalSection":"第3节 城市生态系统的发展方向","category":"knowledge","title":"生态城市的概念","question":"生态城市的概念","type":"简答题","answer":"[待核对] ZAR AR—-PBEFRA, HAD, RS. KR, BRAH, ASARABRA\n分融合 ， MORRIS, RK, Fi, 从而最大程度地发挥人的创造力 ， 并促使城\n市文明程度不断提高的 ， 稳定 、 协调与实现资源利用代际公平的 ， 持续发展的复合生\n态系统 。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"removed","importance":null,"pastExamYears":[2007,2013],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。"],"verified":false,"page":266,"sourceRange":{"startPage":266,"startY":582.5,"endPage":266,"endY":715.34},"sourceKind":"original","originalOrdinal":"supp-1","sourceMetadata":["2007 (4, 2013 4%, (BEBE: wit)"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":16,"versionReason":"未列入变动PDF第31—32页新版知识点保留清单；原内容与真题信息保留。","excerpts":[{"page":266,"src":"./assets/environment/env838-bf10102a5c1c7042-266.webp"}]},{"id":"env838-7760c4ca6d550f13","subject":"环境学导论","chapter":"第16章 城乡生态系统保护","originalChapter":"第17章 城市生态学系统保护","originalChapterNumber":17,"section":"第3节 城市生态系统的发展方向","originalSection":"第3节 城市生态系统的发展方向","category":"knowledge","title":"生态城市的特点","question":"生态城市的特点","type":"简答题","answer":"| 。 (D 和谐性 : 生态城市的构建是人类最大限度的利用自然资源 ， 寻求人与自然良性\n循环发展的新规律 ， 体现了人与自然 、 建筑环境与自然环境 、 经济社会发展与自然环\n境保护之间的和谐共生 、 高效有序 ;\n@ 整体性 : 生态城市是由自然 、 经济 、 社会等诸多环节整合成的复合生态系统 ，\n拥有整体效益运作与发展模式 ， 重视环境质量 ， 注意区域之间的协调发展 ， 体现了人\n与自然和谐为本的域市环境设计原则 ;\nOTHE: 可持续发展是生态城市建设的长期目标 ， 建立生态竞争机制 ， 通过\n自生和再生原理调节系统的影响因素 ,充分合理的运用和配置资源以适应系统发展的\n目标 。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"removed","importance":null,"pastExamYears":[2009,2014],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。","含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":266,"sourceRange":{"startPage":266,"startY":715.34,"endPage":267,"endY":258.32},"sourceKind":"original","originalOrdinal":"supp-2","sourceMetadata":["2009〈 简 、2014〈 论 ，【 重要程度 ， 太妈妈六广 】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":16,"versionReason":"未列入变动PDF第31—32页新版知识点保留清单；原内容与真题信息保留。","excerpts":[{"page":266,"src":"./assets/environment/env838-7760c4ca6d550f13-266.webp"},{"page":267,"src":"./assets/environment/env838-7760c4ca6d550f13-267.webp"}]},{"id":"env838-0f787749ed22050b","subject":"环境学导论","chapter":"第16章 城乡生态系统保护","originalChapter":"第17章 城市生态学系统保护","originalChapterNumber":17,"section":"第3节 城市生态系统的发展方向","originalSection":"第3节 城市生态系统的发展方向","category":"knowledge","title":"生态城市的建设","question":"生态城市的建设","type":"简答题","answer":"生态城市建设是运用可持续发展和生态经济学原理 ,通过综合协调人类经济社会\n活动与资源环境之间的关系 ， 促进改善环境质量和经济发展方式的转变 ， 实现社会经\n济和资源环境良性循环 、 协调持续发展的一种有效组织形式 。\n具体措施为 :\nG@O 摘好生态城市的规划和设计\n© 把自然生态规律和经济发展规律结合起来 ， 把人与自然看成一个整体系统进\n行规划 ， 从而使生态城市向着更加有序 、 更加稳定的方向发展 。\n© 有要把城市区域规划和国家不同层次的规划结合起来 ,使城市的发展与区域经\n济的发展相协调 ， 达到与区域共存 ， 与自然共生 ;\n© 把空间环境与生态经济体系规划相结合 ,寻求区域复合生态系统可持续发展\n的最佳途径和整体最优化方案 ， 追求整个城市经济 、 社会环境的最佳效益 。\n@ 更新观念 ， 实现三个转变\n曲 ” 一是人对自然的统治关系转变为和谐统一的共生关系 ;\n二是向自然单纯的索取转变为补偿和索取相结合 ;\n三是统一人对自然的权利和任务 ， 包括利用自然 ， 也包括保护自然 。 只有实\n现三个转变 ， 才能使城市有限的资源得到充分的利用和保护 。\n@@ 创新技术 ， 使经济发展与生态环境相协调\n建设生态城市 ， 必须进行技术创新 。 运用现代生态的技术 ， 优化产业结构 ， 并建\n立生态化的产业体系 ， 从而使城市经济发展向着生态化方向转变 ， 以实现城市生态系\n统的供需平衡 ， 使自然生态环境的生产能力 、 自我恢复能力和补偿能力始终保持较高\n的水平 ， 实现经济 、 资源 、 环境的协调发展 。\n图不断完善城市基础设施 ， 加强城市园林绿化建设\n要把城市的能源系统 、 污水处理系统 、 食物供应系统结合起来 ， 从而使完善的基\n础设施 ， 能够修复经济发展对环境破坏 。 同时 ， 要加强城市园林绿化建设 。 首先应遵\n循生态原则 。 从最大限度改善城市生态环境出发 ， 因地制宜 ， 选择绿化树种 、 灌木的\n搭配及花开的点缓等 ; 其次是遵循文化原则 。 充分考虑不同城市的文化特点 、 历史脉\n络 、 地域风俗 ， 并将其融入园林绿化之中 ， 使城市园林绿化向着充满人文内涵品位的\n方向发展 。\n@@ 运用法规体系\n强化公民和政府的环保意识 。 生态城市应该有高度的生态文明 ， 树立生态文明观\n。 一是靠救育 ， 二是靠法制 。 通过教育宣传使环境保护这项基本国策家喻户晓 、 人人\n臂知 ， 对严重破坏生态环境的行为要给予法律制裁 。 只有全民的环境保护意识得以形\n成并强化 ， 生态城市建设才会发展 ， 整个国家的生态环境才能得到改善 。\n同时 ， 必须加强政府决策者的环保意识 ， 只有决策者的环保意识提高了 ， 才能有\n效完成对生态环境的宏观保护 ， 使生态城市建设的目标落到实处 。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"removed","importance":null,"pastExamYears":[2007,2009],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。","含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":267,"sourceRange":{"startPage":267,"startY":258.32,"endPage":269,"endY":92.21},"sourceKind":"original","originalOrdinal":"supp-3","sourceMetadata":["2007 CH. 2009 〈 简 ，【 重要程度 ， 娘六六交文 】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":16,"versionReason":"未列入变动PDF第31—32页新版知识点保留清单；原内容与真题信息保留。","excerpts":[{"page":267,"src":"./assets/environment/env838-0f787749ed22050b-267.webp"},{"page":268,"src":"./assets/environment/env838-0f787749ed22050b-268.webp"},{"page":269,"src":"./assets/environment/env838-0f787749ed22050b-269.webp"}]},{"id":"env838-4df34ceb307a281e","subject":"环境学导论","chapter":"第16章 城乡生态系统保护","originalChapter":"第17章 城市生态学系统保护","originalChapterNumber":17,"section":"课后习题","originalSection":"课后习题","category":"exercise","title":"什么是城市生态系统?","question":"什么是城市生态系统?","type":"简答题","answer":"城市生态系统是城市人类与周围生物和非生物环境相互作用形成的、具有一定结构和功能的复合生态系统。\n由自然、经济和社会等子系统共同组成，通过物质流、能量流、信息流及人口活动联系。\n与相对自然的系统相比，它的人工调控更强、人口和资源消费集中、对外部资源与能源依赖较大，同时向外输出产品、服务和废物。\n研究城市生态系统需同时考虑生态过程、人类福祉及城市与周边区域的联系，不能只把城市绿地看作全部城市生态系统。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":269,"sourceRange":{"startPage":269,"startY":126.15,"endPage":269,"endY":202.2},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":16,"excerpts":[{"page":269,"src":"./assets/environment/env838-4df34ceb307a281e-269.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=258"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-d62888a74a39f25c","subject":"环境学导论","chapter":"第16章 城乡生态系统保护","originalChapter":"第17章 城市生态学系统保护","originalChapterNumber":17,"section":"课后习题","originalSection":"课后习题","category":"exercise","title":"城市生态系统的功能和特点有哪些?","question":"城市生态系统的功能和特点有哪些?","type":"简答题","answer":"功能：①组织生产、生活与社会服务；②加工和交换物质、能量及信息；③通过绿地、水体等提供调节、游憩和生境等生态服务。\n特点：人工性强，以人为主体；人口、建筑与经济活动密集；生产与消费高度开放，常依赖外部水、食物、能源和物资；物质和能量通量大，污染与废热集中；空间异质性及自然、经济、社会子系统耦合明显。\n健康城市应协调资源效率、环境质量、生态功能和居民公平获得公共服务的机会。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":269,"sourceRange":{"startPage":269,"startY":202.2,"endPage":269,"endY":280.17},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":16,"excerpts":[{"page":269,"src":"./assets/environment/env838-d62888a74a39f25c-269.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=258"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-d0de032dad0d0c40","subject":"环境学导论","chapter":"第16章 城乡生态系统保护","originalChapter":"第17章 城市生态学系统保护","originalChapterNumber":17,"section":"课后习题","originalSection":"课后习题","category":"exercise","title":"城市生态系统存在哪些问题?","question":"城市生态系统存在哪些问题?","type":"简答题","answer":"①资源与能源：水、能源和物资需求集中，对外部地区依赖大。\n②污染与废物：交通、工业、建筑及生活活动排放废气、污水、固废和噪声。\n③空间与生境：土地硬化、生境破碎化、植被不足及不合理扩张，降低生态连通性。\n④水热与气候：热岛、雨洪径流和内涝风险，极端天气进一步放大影响。\n⑤社会治理：住房、交通、绿地和环境服务分配不均，部门管理与区域协调不足。\n解决应结合紧凑合理布局、绿色交通、节能、基础设施完善及蓝绿网络建设。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":269,"sourceRange":{"startPage":269,"startY":280.17,"endPage":269,"endY":358.15},"sourceKind":"original","originalOrdinal":"3","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":16,"excerpts":[{"page":269,"src":"./assets/environment/env838-d0de032dad0d0c40-269.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=258"},{"title":"武汉市政府：海绵城市从试点走向示范","url":"https://www.wuhan.gov.cn/whyw/bmdt/202209/t20220930_2051486.shtml","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-63b92b485a0fc830","subject":"环境学导论","chapter":"第16章 城乡生态系统保护","originalChapter":"第17章 城市生态学系统保护","originalChapterNumber":17,"section":"课后习题","originalSection":"课后习题","category":"exercise","title":"城市生态系统的研究方向包括哪几方面?","question":"城市生态系统的研究方向包括哪几方面?","type":"简答题","answer":"①结构研究：分析自然、经济、社会子系统及其空间组织，识别关键生境和资源网络。\n②过程研究：核算城市物质、能量、信息及水循环，识别输入输出和污染热点。\n③功能与健康研究：评价生态服务、承载条件、暴露风险及居民福祉。\n④演变与韧性研究：研究城市化、气候变化及其他扰动下的响应和恢复能力。\n⑤规划管理研究：将生态原理用于国土空间、交通、产业及蓝绿基础设施规划，开展政策与治理效果评价。\n方法上应结合监测、遥感、调查、模型及多尺度综合分析。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":269,"sourceRange":{"startPage":269,"startY":358.15,"endPage":269,"endY":436.38},"sourceKind":"original","originalOrdinal":"4","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":16,"excerpts":[{"page":269,"src":"./assets/environment/env838-63b92b485a0fc830-269.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=258"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-d0f83bc89cebea29","subject":"环境学导论","chapter":"第16章 城乡生态系统保护","originalChapter":"第17章 城市生态学系统保护","originalChapterNumber":17,"section":"课后习题","originalSection":"课后习题","category":"exercise","title":"结合自己所学知识，举例说明如何保护城市生物多样性。","question":"结合自己所学知识，举例说明如何保护城市生物多样性。","type":"简答题","answer":"①保护现有自然生境、老树、湿地和河湖岸带，优先避免破坏。\n②建立连续的公园、河流、林带及小微绿地网络，提高生境连通性。\n③因地制宜配置乡土植物和多层次植被，提供食物、隐蔽与繁殖条件，避免不合理单一化绿化。\n④减少污染、过度修剪、不必要的农药及夜间照明，防范外来入侵。\n⑤开展物种调查、长期监测、公众参与和生态教育。\n举例：滨河绿地改造时保留自然岸线与缓冲植被，在防洪安全前提下连接公园和湿地，并监测鸟类与授粉昆虫响应。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":269,"sourceRange":{"startPage":269,"startY":436.38,"endPage":269,"endY":514.75},"sourceKind":"original","originalOrdinal":"5","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":16,"excerpts":[{"page":269,"src":"./assets/environment/env838-d0f83bc89cebea29-269.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=258"},{"title":"中国生物多样性保护战略与行动计划（2023—2030年）发布说明","url":"https://www.mee.gov.cn/xxgk/hjyw/202401/t20240118_1064111.shtml","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-332556dd4585c24f","subject":"环境学导论","chapter":"第16章 城乡生态系统保护","originalChapter":"第17章 城市生态学系统保护","originalChapterNumber":17,"section":"课后习题","originalSection":"课后习题","category":"exercise","title":"简述我国一个城市的宜居城市构建思路和实施方法。","question":"简述我国一个城市的宜居城市构建思路和实施方法。","type":"简答题","answer":"可用武汉海绵城市建设为例。\n思路：针对老城区积水、硬化和水环境问题，以流域和排水分区为单元，统筹防洪排涝、生态修复及居民公共空间。\n实施：青山等区域开展社区、校园、道路及公园的海绵化改造，结合雨水花园、透水铺装、调蓄和河渠整治；完善排水设施与运行维护，并听取居民需求。\n评价：关注积水风险、径流污染、绿地服务及维护效果，而不是只看新增景观面积。\n该案例说明宜居城市需要蓝绿空间与灰色工程、生态目标与民生服务协同；局部“海绵”设施不能替代完整排水和防灾体系。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":269,"sourceRange":{"startPage":269,"startY":514.75,"endPage":270,"endY":73.3},"sourceKind":"original","originalOrdinal":"6","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":16,"excerpts":[{"page":269,"src":"./assets/environment/env838-332556dd4585c24f-269.webp"},{"page":270,"src":"./assets/environment/env838-332556dd4585c24f-270.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=258"},{"title":"武汉市政府：海绵城市从试点走向示范","url":"https://www.wuhan.gov.cn/whyw/bmdt/202209/t20220930_2051486.shtml","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-dc4944bd7ab438fa","subject":"环境学导论","chapter":"第16章 城乡生态系统保护","originalChapter":"第18章 农村生态系统保护","originalChapterNumber":18,"section":"第5节 课后习题","originalSection":"第5节 课后习题","category":"exercise","title":"简述农村生态系统的概念及其特点。","question":"简述农村生态系统的概念及其特点。","type":"简答题","answer":"农村生态系统是农村地域内的人类、农业及其他生物与自然和人工环境相互作用形成的复合系统，连接生产、生活和生态功能。\n特点：①与土地、水和气候联系紧密，地域与季节差异明显；②农业生产占重要地位，种植、养殖与聚落相互联系；③传统管理与现代技术共同调控；④与城镇交换劳动力、产品、物资及信息；⑤既有循环利用潜力，也可能面临污染、资源约束和基础设施不足。\n评价农村生态系统应同时关注生态健康、农业持续生产与居民生活质量。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":285,"sourceRange":{"startPage":285,"startY":115.5,"endPage":285,"endY":193.05},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":16,"excerpts":[{"page":285,"src":"./assets/environment/env838-dc4944bd7ab438fa-285.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=270"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-470362db2c2cc06d","subject":"环境学导论","chapter":"第16章 城乡生态系统保护","originalChapter":"第18章 农村生态系统保护","originalChapterNumber":18,"section":"第5节 课后习题","originalSection":"第5节 课后习题","category":"exercise","title":"农村生态系统的功能有哪些?","question":"农村生态系统的功能有哪些?","type":"简答题","answer":"整理答案（按教材对应知识点摘录）：\n\n农村生态系统的功能：\n(1 ) 供给功能(基础支撑)\n作为基础生产单元，承担物质生产核心职能。通过初级/次级生产\n为城乡居民提供生活资料，支撑城乡社会经济发展，是城市生态系统\n的物质供给源。\n(2) 调节功能(空间载体)\n兼具居住承载与文化传承双重作用：既为居民提供生产生活空间\n，维系社区稳定；又作为传统文化存续载体，吸纳人口聚居形成乡村\n社区单元。\n(3) 文化功能(价值载体)\n保存民族文化基因库，维系传统文化多样性。作为现代知识教育\n实践场域，兼具美学价值与休闲功能，是城乡文化互动的重要纽带。\n(4) 生态功能(环境屏障)\n发挥区域生态安全保障作用：通过气候调节、水土保持、污染净\n化等生态服务，构建城乡生态屏障。其广域分布特征使其成为国家生\n态安全格局的关键支撑。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["根据所列知识点摘录整理，未逐题人工审定。"],"verified":false,"page":285,"sourceRange":{"startPage":285,"startY":193.05,"endPage":285,"endY":270.44},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":16,"references":[{"id":"env838-c9e201b409856641","title":"农村生态系统的功能","source":"环境学导论.pdf","page":273}],"excerpts":[{"page":285,"src":"./assets/environment/env838-470362db2c2cc06d-285.webp"}]},{"id":"env838-4e8d0cc45fc52a5a","subject":"环境学导论","chapter":"第16章 城乡生态系统保护","originalChapter":"第18章 农村生态系统保护","originalChapterNumber":18,"section":"第5节 课后习题","originalSection":"第5节 课后习题","category":"exercise","title":"农村生态系统存在哪些问题?","question":"农村生态系统存在哪些问题?","type":"简答题","answer":"整理答案（按教材对应知识点摘录）：\n\n农村生态系统存在的问题及保护：\n农村生态系统存在的问题有自然生态环境的破坏、土地占用和土\n壤变化、水污染、生活垃圾污染和其他污染。\n[1]自然生态环境的破坏\n生态破坏主要指由于开发利用农村生态系统中的资源不当而导\n致该生态系统功能退化或质量下降的现象。如资源开发过度或不当导\n致森林草原湖泊农田等生态系统退化，抗干扰与破坏的能力下降，适\n应与抵抗各种新情况尤其是自然灾害的能力差；生物的生存环境恶化\n，多样性逐渐减少，食物网链的某些环节薄弱化趋势明显等。\n[2]土地利用失衡土地占用和土壤变化\n(1 )违反自然规律的开发导致土地流失或土壤退化。不当开发\n就是开发利用不符合土地自然性质和结构。一是大量农药化肥造成土\n壤板结丧失自组织能力和天然肥力；二是为在有限土地上获得更多作\n物把轮作周期从几十年缩短到几年甚至连年耕作、过度精耕加快矿物\n质和有机质枯竭、破坏土壤结构；三是增加的畜牧集中在逐渐缩小的\n牧场上加大放牧负载，在原本优良的牧场留下大片荒漠区。\n(2)人为侵占导致土地流失。人口增长、交通工具发展、基础\n设施建设、通信系统延伸缩短了城乡距离，加上农村地价便宜，开发\n大片住宅成为可能，大量农业用地转为农村住宅用地。\n[3]水环境污染\n我国大部分地区农村都属原发建成的自然村落，缺乏整体规划，\n公共排污及治污设施不健全，基本上处于污水乱流、垃圾乱倒、粪土\n乱堆的状态。近年随着农村产业结构进一步调整，农业产业化工业化\n进程加快，农产品加工小企业、规模养殖和种植业迅速发展。由于缺\n乏基本的污水和固体垃圾回收处理系统，固体垃圾和人畜粪便大多直\n接露天堆放，生活污水和生产污水大多直接排放到村边沟壕或村庄地\n·254-\n面，降雨时被冲刷渗透到地下水或河流湖泊中，由点到面逐渐扩张和\n蔓延。\n[4]固废污染加剧\n①农民环境意识较差，柴草乱堆、污水乱流、粪土乱丢、垃圾乱\n倒、杂物乱放、畜禽散养——不仅影响村容村貌，还对水源造成污染\n②垃圾成分发生很大变化。以前农村产生的生活垃圾可以就地\n化解循环使用——菜叶喂猪、剩饭喂鸡、草木灰还田。现在生活水平\n提高方式发生大变化，塑料和电子产品产生的难以降解的废品占比越\n来越大。\n③农村成为城市垃圾的转移地。因为天地广阔管理松散，往往成\n为城市转移生活建筑垃圾、有毒有害工业医疗垃圾的选择地。\n[5]复合型污染\n(1 )农业面源污染。种类主要有畜禽粪便污染、农药化肥过量\n使用加剧环境污染、收获时节秸秆焚烧造成大气污染。\n(2)生物质燃烧导致大气污染。广大农村由于生存条件限制，\n燃料问题突出，大多以秸秆甚至乡间杂草为主要燃料，燃烧时释放大\n量烟尘。\n(3 )土壤污染加剧。为追求农作物高产短期经济效益，过量施\n用化肥农药除草剂非降解地膜现象普遍。化肥导致土地固化、团粒结\n构破坏、氮磷钾比例失调、地力下降。农药喷洒大部分附着于作物外\n表也会因风雨进入土壤。除草剂含砷化物和重金属离子。非降解地膜\n回收率低，大量废旧农膜残留在耕层中破坏结构引起板结。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["根据所列知识点摘录整理，未逐题人工审定。"],"verified":false,"page":285,"sourceRange":{"startPage":285,"startY":270.44,"endPage":285,"endY":347.09},"sourceKind":"original","originalOrdinal":"3","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":16,"references":[{"id":"env838-23610257595d15da","title":"农村生态系统存在的问题及保护","source":"环境学导论.pdf","page":273}],"excerpts":[{"page":285,"src":"./assets/environment/env838-4e8d0cc45fc52a5a-285.webp"}]},{"id":"env838-d9496a9553574766","subject":"环境学导论","chapter":"第16章 城乡生态系统保护","originalChapter":"第18章 农村生态系统保护","originalChapterNumber":18,"section":"第5节 课后习题","originalSection":"第5节 课后习题","category":"exercise","title":"如何保护农村生态系统?","question":"如何保护农村生态系统?","type":"简答题","answer":"整理答案（按教材对应知识点摘录）：\n\n农村生态系统存在的问题及保护：\n农村生态系统存在的问题有自然生态环境的破坏、土地占用和土\n壤变化、水污染、生活垃圾污染和其他污染。\n[1]自然生态环境的破坏\n生态破坏主要指由于开发利用农村生态系统中的资源不当而导\n致该生态系统功能退化或质量下降的现象。如资源开发过度或不当导\n致森林草原湖泊农田等生态系统退化，抗干扰与破坏的能力下降，适\n应与抵抗各种新情况尤其是自然灾害的能力差；生物的生存环境恶化\n，多样性逐渐减少，食物网链的某些环节薄弱化趋势明显等。\n[2]土地利用失衡土地占用和土壤变化\n(1 )违反自然规律的开发导致土地流失或土壤退化。不当开发\n就是开发利用不符合土地自然性质和结构。一是大量农药化肥造成土\n壤板结丧失自组织能力和天然肥力；二是为在有限土地上获得更多作\n物把轮作周期从几十年缩短到几年甚至连年耕作、过度精耕加快矿物\n质和有机质枯竭、破坏土壤结构；三是增加的畜牧集中在逐渐缩小的\n牧场上加大放牧负载，在原本优良的牧场留下大片荒漠区。\n(2)人为侵占导致土地流失。人口增长、交通工具发展、基础\n设施建设、通信系统延伸缩短了城乡距离，加上农村地价便宜，开发\n大片住宅成为可能，大量农业用地转为农村住宅用地。\n[3]水环境污染\n我国大部分地区农村都属原发建成的自然村落，缺乏整体规划，\n公共排污及治污设施不健全，基本上处于污水乱流、垃圾乱倒、粪土\n乱堆的状态。近年随着农村产业结构进一步调整，农业产业化工业化\n进程加快，农产品加工小企业、规模养殖和种植业迅速发展。由于缺\n乏基本的污水和固体垃圾回收处理系统，固体垃圾和人畜粪便大多直\n接露天堆放，生活污水和生产污水大多直接排放到村边沟壕或村庄地\n·254-\n面，降雨时被冲刷渗透到地下水或河流湖泊中，由点到面逐渐扩张和\n蔓延。\n[4]固废污染加剧\n①农民环境意识较差，柴草乱堆、污水乱流、粪土乱丢、垃圾乱\n倒、杂物乱放、畜禽散养——不仅影响村容村貌，还对水源造成污染\n②垃圾成分发生很大变化。以前农村产生的生活垃圾可以就地\n化解循环使用——菜叶喂猪、剩饭喂鸡、草木灰还田。现在生活水平\n提高方式发生大变化，塑料和电子产品产生的难以降解的废品占比越\n来越大。\n③农村成为城市垃圾的转移地。因为天地广阔管理松散，往往成\n为城市转移生活建筑垃圾、有毒有害工业医疗垃圾的选择地。\n[5]复合型污染\n(1 )农业面源污染。种类主要有畜禽粪便污染、农药化肥过量\n使用加剧环境污染、收获时节秸秆焚烧造成大气污染。\n(2)生物质燃烧导致大气污染。广大农村由于生存条件限制，\n燃料问题突出，大多以秸秆甚至乡间杂草为主要燃料，燃烧时释放大\n量烟尘。\n(3 )土壤污染加剧。为追求农作物高产短期经济效益，过量施\n用化肥农药除草剂非降解地膜现象普遍。化肥导致土地固化、团粒结\n构破坏、氮磷钾比例失调、地力下降。农药喷洒大部分附着于作物外\n表也会因风雨进入土壤。除草剂含砷化物和重金属离子。非降解地膜\n回收率低，大量废旧农膜残留在耕层中破坏结构引起板结。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["根据所列知识点摘录整理，未逐题人工审定。"],"verified":false,"page":285,"sourceRange":{"startPage":285,"startY":347.09,"endPage":285,"endY":423.3},"sourceKind":"original","originalOrdinal":"4","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":16,"references":[{"id":"env838-23610257595d15da","title":"农村生态系统存在的问题及保护","source":"环境学导论.pdf","page":273}],"excerpts":[{"page":285,"src":"./assets/environment/env838-d9496a9553574766-285.webp"}]},{"id":"env838-835a92fbcd38f179","subject":"环境学导论","chapter":"第16章 城乡生态系统保护","originalChapter":"第18章 农村生态系统保护","originalChapterNumber":18,"section":"第5节 课后习题","originalSection":"第5节 课后习题","category":"exercise","title":"简述农村生态系统健康评价框架体系的形成。","question":"简述农村生态系统健康评价框架体系的形成。","type":"简答题","answer":"可按以下步骤构建农村生态系统健康评价框架：\n①明确对象、空间边界和目标，将生态系统自身维持能力与人类合理需求结合。\n②建立维度：生态环境及资源基础、生态活力与组织、受扰恢复能力、农业和相关产业持续性，以及居民健康和公共服务等。\n③选择可测、代表性强且不过度重复的指标，如土壤水质、生境状况、养分收支、污染负荷和服务可及性等。\n④确定基准、权重和评价方法，结合实测、调查及专家判断，开展敏感性分析。\n⑤用时间序列和管理反馈校正框架。不存在对所有农村都通用的一套固定权重。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":285,"sourceRange":{"startPage":285,"startY":423.3,"endPage":285,"endY":499.06},"sourceKind":"original","originalOrdinal":"5","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":16,"excerpts":[{"page":285,"src":"./assets/environment/env838-835a92fbcd38f179-285.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=270"},{"title":"生态系统健康及其评价指标和方法（原始研究）","url":"https://www.jnr.ac.cn/CN/abstract/article/1000-3037/26529","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-9d98bc9c89769747","subject":"环境学导论","chapter":"第16章 城乡生态系统保护","originalChapter":"第18章 农村生态系统保护","originalChapterNumber":18,"section":"第5节 课后习题","originalSection":"第5节 课后习题","category":"exercise","title":"生态村建设主要包括哪几方面内容?","question":"生态村建设主要包括哪几方面内容?","type":"简答题","answer":"①环境污染治理：生活污水、垃圾、畜禽粪污、农膜及农业面源污染等。\n②生态经济建设：资源高效利用、种养匹配、绿色产业及合理生计。\n③人居环境建设：饮水、道路、厕所、住房周边和公共空间等基本服务。\n④生态文化建设：环境教育、地方生态知识保护、村规民约和公众参与。\n⑤生态文明及治理建设：规划、责任、投入、运行维护和监督机制，形成持续管理能力。\n实施应与村庄规模、地形、水土和经济条件相适应，重视设施长期有人管理和有经费运行，避免只做一次性景观工程。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":285,"sourceRange":{"startPage":285,"startY":499.06,"endPage":286,"endY":64.6},"sourceKind":"original","originalOrdinal":"6","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":16,"excerpts":[{"page":285,"src":"./assets/environment/env838-9d98bc9c89769747-285.webp"},{"page":286,"src":"./assets/environment/env838-9d98bc9c89769747-286.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=270"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-1290eceab517a544","subject":"环境学导论","chapter":"第17章 生态文明理论与实践","originalChapter":"第19章 生态文明理论与实践","originalChapterNumber":19,"section":"第1节 生态文明理论","originalSection":"第1节 生态文明理论","category":"knowledge","title":"生态文明的含义","question":"生态文明的含义","type":"简答题","answer":"生态文明由生态和文明两个概念复合而来。简单地说，生态就\n是指一切生物的生存状态，以及它们之间和它与环境之间环环相扣\n的关系。从人类社会实践活动来讲，文明则是人类改造自然、改造\n社会和自我改造的结晶。\n把两个词合在一起，生态文明就是人类在追求社会进步的过程中\n，以尊重自然为前提，以和谐共生为宗旨，通过改造自然改造社会改\n造自我所取得的成果总和。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2025],"needsReview":false,"reviewReasons":[],"verified":false,"page":286,"sourceRange":{"startPage":286,"startY":530.1,"endPage":287,"endY":148.86},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":["2025(名),【重要程度:"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":17,"excerpts":[{"page":286,"src":"./assets/environment/env838-1290eceab517a544-286.webp"},{"page":287,"src":"./assets/environment/env838-1290eceab517a544-287.webp"}]},{"id":"env838-270876ebc6cf78a1","subject":"环境学导论","chapter":"第17章 生态文明理论与实践","originalChapter":"第19章 生态文明理论与实践","originalChapterNumber":19,"section":"第1节 生态文明理论","originalSection":"第1节 生态文明理论","category":"knowledge","title":"生态文明与原始文明、农业文明、工业文明","question":"生态文明与原始文明、农业文明、工业文明","type":"简答题","answer":"(1) 原始文明\n原始文明是人类文明发展的萌芽阶段。人类发明了人工取火、弓\n箭等，出现了群居以及语言，具备了社会的最初形式，创造出人类最\n初的文明。人与自然的关系：人们只能被动地适应自然、盲目地崇拜\n自然、顺从自然，人受制于自然，人类寄生于大自然，始终以自然为\n中心。\n学长解读 : 原始文明时期 ， 人类受制于自然 ， 始终以自然为中心 。 打雷以为是\n老天符发脾气 ， 洪水以为是妖怪作崇 。 这个时期的人对自然的影响可以忽略不\n计一一就像妈蚁对一栋大楼的影响 。\n(2) 农业文明\n从本质上讲，农业文明所使用的生产和生活资料基本上属于可再\n生能源。土地是有限的和稀缺的，当一个地区的人口增长达到一定限\n度，其赖以生存的土地就难以承载人口的压力。于是，人们开始毁林\n开荒，围湖造田，这种做法确实能够获得短期效益，但最终导致局部\n地区的水土流失、旱涝频繁、气候变异等生态灾难的发生。\n综上所述，农业文明时期，生产力水平相对于原始文明有了一定\n的发展，人类为了自身的生存与发展对大自然进行开发与改造，但由\n于当时的生产力水平并不高，人类使用的生产工具还比较简单，使用\n的能源也仅仅是人力、畜力、风力以及水力等可再生资源，并没有从\n根本上破坏自然生态系统的平衡。人与自然的关系是：自然处于主导\n地位，人类处于从属地位，人与自然基本和谐。人类的一切行为都要\n依赖于自然界，但人类也在积极地利用自然为自身服务、改善自身生\n活水平。\n学长解读 : 该时期人与自然的关系是一一自然主导 ， 人类从属 ， 基本和谐 。 这\n个和谐不是因为人类觉悟高 ， 是因为人类的破坏能力还不够 。 一旦终了人类忒\n汽机 ， 这种脆弱和谐立刻土户瓦解 。\n(3) 工业文明\n英国科学家瓦特改进蒸汽机，成为工业文明的显著标志。工业文\n明是以工业化为重要标志、机械化大生产占主导地位的一种现代社会\n文明状态。工业文明时期，科学技术发展迅速，人类利用先进的工业\n技术给自身带来了前所未有的物质享受，但也带来了前所未有的生态\n破坏以及相应的自然灾害。这一时期的基本理念是“人是自然的主人\n，自然是人类的奴隶，自然资源是取自不尽、用之不竭的”，根本不顾\n自然的承受能力与可持续发展。\n学长解读 : 工业时期 ， 科学技术发展迅速 ， 人类获得了前所未有的物质享受一\n一但也带来了前所未有的生态破坏和自然灾害 。 这个时期的基本理念是 “人是\n自然的主人 ， 自然是人类的奴未 ， 自然资源取之不尽用之不音 ， 根本不顾自然\n的承受能力和可持续发展 ”。 两百年来我们把地球亿万年形成的地下矿藏一次\n性挖出来烧掉 。 结果就是酸雨 、 雾禾 、 全球变暖 、 物种加速灭绝 。 工业文明让\n人类一夜暴富 ， 也让地球千瘤百孔 。\n(4)生态文明——重寻人与自然和谐相处\n生态文明是对传统的工业文明进行批判性反思的结果，是通过人\n类重塑自然权威，以尊重自然、维护自然、顺应自然为前提，以人与\n人、人与自然、人与社会和谐共生为宗旨，以建立资源节约型、环境\n友好型社会和与之适应的经济增长方式、消费方式为基础，以引导人\n们走持续发展、和谐发展的道路为着眼点的一种全新的文明形态。\n学长解读 : 大家注意全新两个字 ， 说明生态文明不是工业文明的修修补补 。 不\n是烟向上装个脱硫装置就叫生态文明 。 是从价值观到经济模式到消费方式到社\n会制度的系统重构 。 重塑自然权威不是说要回到原始社会跪兰自然， 而是人类\n主动给自然赋予应有的法律地位和道德地位 。\n表格速览：\n文\n明\n核心特征 人与自然的关系 生产工具与能源 结果/影响\n类\n型\n原\n萌芽阶 被动适应、盲目崇 简陋工具( 石器\n始 人类寄生自然，\n段，社会 拜、顺从自然，以 等) ，依赖自然\n文 未破坏生态平衡\n初步形成 自然为中心 能源\n明\n农 依赖土 自然主导，人类从 土地过度开发导\n简单工具( 人\n业 地，可再 属，基本和谐；局 致生态问题，但\n力、畜力、水\n文 生能源为 部生态破坏(如水 未根本破坏自然\n力、风力)\n明 主 土流失) 平衡\n工 人类征服自然，视 生态破坏( 污\n工业化、\n业 自然为奴隶；资源 机械工具，依赖 染、灾害频\n机械化大\n文 掠夺式开发，忽视 化石能源 发)，人与自然\n生产\n明 可持续发展 对立\n生 可持续发\n尊重、顺应、维护 建立资源节\n态 展，人与 绿色技术，可再\n自然；人与自然、 约型社会，实现\n文 自然和谐 生能源\n社会和谐共生 可持续发展\n明 共生","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":0,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。","含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":287,"sourceRange":{"startPage":287,"startY":148.86,"endPage":290,"endY":48.72},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":["【重要程度: ☆☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":17,"excerpts":[{"page":287,"src":"./assets/environment/env838-270876ebc6cf78a1-287.webp"},{"page":288,"src":"./assets/environment/env838-270876ebc6cf78a1-288.webp"},{"page":289,"src":"./assets/environment/env838-270876ebc6cf78a1-289.webp"},{"page":290,"src":"./assets/environment/env838-270876ebc6cf78a1-290.webp"}]},{"id":"env838-e627def78419ab3f","subject":"环境学导论","chapter":"第17章 生态文明理论与实践","originalChapter":"第19章 生态文明理论与实践","originalChapterNumber":19,"section":"第1节 生态文明理论","originalSection":"第1节 生态文明理论","category":"knowledge","title":"生态文明与物质文明、政治文明和精神文明","question":"生态文明与物质文明、政治文明和精神文明","type":"简答题","answer":"一、定义与特点\n(1) 生态文明\n生态文明是指人类文明发展的新阶段和新形态，是人们在改造客\n观物质世界的同时，不断克服改造过程中的负面效应，积极改善和优\n化人与自然、人与人、人与社会的关系，建设人类社会整体的生态运\n行机制和良好的生态环境所取得的物质、精神、制度方面成果的总和\n(2) 物质文明\n物质文明是指人类物质生活的进步状况，主要表现为物质生产方\n式和经济生活的进步。 物质文明越高，表明人类离开野蛮的状态愈\n远，依赖自然的程度愈小，控制自然的能力愈强。物质文明的高度发\n展给人类改造自然，征服宇宙，推动人类社会本身的进步创造了优越\n的、必要的、先决的条件。\n(3) 精神文明\n精神文明指的是人类精神生活的进步状态。按性质，精神文明可\n以分为两大类：一类指科学教育、文化艺术、卫生体育事业的发展\n规模和水平，一类指思想、情操、理想、伦理、道德、风尚、习惯等\n社会意识形态的状况。前者是直接同社会的物质生产相联系，直接反\n映物质文明的程度，直接为物质文明条件所制约；后者不是直接同社\n会生产相联系，而是同社会经济制度的性质相联系；\n(4) 政治文明\n政治文明是指人类改造社会的政治成果的总和，是人类社会文明\n的重要组成部分，是人类政治活动的进步状况和发展程度的标志，它\n是与政治蒙昧和政治野蛮相对立的范畴。政治文明其本质是一种回归\n主体性的文明，强调每一个公民都拥有参与管理国家事务的权力。“\n十六大”报告在一系列论述“民享”的基础上，提出政治文明，其核心意\n义就在于“民治”，也就是让公民真正成为能够决定自己命运的政治上\n的主人。\n学长解读 : 生态文明是物质 、 精神 、 制度三方面成果的总和 。 所以生态文明不\n是什么新创了第五个文明出来独立成章 ， 而是渗选到已有的三大文明里面去的\n， 这就好比 :\n物质文明是公司的硬实力一你能生产什么产品 。\n精神文明是公司的软实力一一你的员工素质和企业文化 。\n政治文明是公司的制度力一你的治理结构和决策机制 。\n生态文明是公司的可持续力一你现在赚钱的方式能不能十年二十年后还在赚\nReo\n四个缺一不可 。 硬实力强但软实力差是暴发户 ， 制度力差是家族企业做不大 ，\n可持续力盖是今天风光明天倒闭。\n表格速览：\n文明\n定义 核心特点\n类型\n人类改造自然中实现人与自然和谐\n生态 强调生态保护、可持续发展；注\n的新形态，涵盖物质、精神、制度\n文明 重代际公平与生态伦理。\n成果的总和。\n物质 依赖自然改造能力，追求经济增\n物质生产与生活方式的进步。\n文明 长，需与生态协调。\n分为物质关联型(受生产力制\n精神 精神生活的进步，包括科学教育、\n约)与意识形态型 (与社会制度\n文明 思想道德等。\n相关)。\n文明\n定义 核心特点\n类型\n政治 政治成果的总和，体现公民参与与 核心是“民治”，强调民主法治与\n文明 制度进步。 公民权利。\n二、区别\n首先，它们包含着各自不同的内容：物质文明是人们在改造客观\n世界的实践活动中形成的有益成果，表现为物质生产方式和物质生活\n的进步；政治文明是人们在政治实践活动中形成的有益成果，表现为\n社会政治制度和政治生活的进步；精神文明是人们在改造客观世界的\n同时改造主观世界中形成的有益成果，表现为社会精神产品和精神生\n活的进步；生态文明是人类在改造自然以造福自身的过程中，为实现\n人与自然之间的和谐所做的全部努力和所取得的全部成果，表征人与\n自然相互关系的进步状态。\n其次，它们包含着各自不同的处理关系：物质文明体现人类在改\n造自然过程中处理的人与自然的关系；政治文明体现人类在改造社会\n过程中处理的人与人的关系；精神文明体现人类在改造主观世界的过\n程中处理的主观与客观、人与自我的关系；生态文明体现的是不仅改\n造人与自然的关系，消除社会不公，使人与人的关系协调发展，而且\n还把许多新观念、新内容引进精神领域，全面推进人类文明的发展和\n进步。\n维度 生态文明 物质文明 精神文明 政治文明\n核心 人与自然的关 人与自我、主 人与人的社\n人与自然的关系\n关系 系 观世界的关系 会关系\n维度 生态文明 物质文明 精神文明 政治文明\n关注 可持续发展、生 经济增长、物 思想道德、文 民主法治、\n重点 态平衡 质丰富 化教育 制度建设\n成果 生态机制、环保 生产力提升、 精神产品( 如 法律法规、\n表现 技术、绿色消费 物质财富积累 科学、艺术) 民主制度\n三、联系\n生态文明建设并非独立于三大文明之外再建设一种新的文明出\n来，而是在三大文明建设的实践中建设。总的来说，自近代以来的人\n类工业文明，从价值导向、方针政策，到规章制度、行为规范，以及\n种种产品、设备、工作条件或生活环境等物质形态，无不渗透着人类\n中心主义等反自然或非生态化的思想观念及其消极影响。因此，要建\n设生态文明，就应对被近代工业文明所深深污染的三大文明在内容和\n形式进行“生态化”改造，将生态文明的理念和要求由内而外地贯彻到\n人类的思想意识、方针政策、法律法规、规章制度、行为规范、生产\n方式、行为方式、生活方式等人类社会的一切方面和细节中，以生态\n文明的理念和精神来引导、规范、限制和制约三大文明建设。\n从物质文明方面来说，生态文明为物质文明建设明确规定了环保\n、节能、护生等生态化发展方向，要求物质生产力的职责不只是要认\n识自然、改造自然，而且要承担起保护自然、节省资源、健康卫生、\n创造美好环境的责任，即发展绿色生产力不能再像过去那样以牺牲环\n境和资源为代价来换取经济的快速增长。特别是应当大力建设如循环\n经济那样从全程控制污染物产生、最大限度利用资源的生态型经济，\n这是现代物质文明建设得以可持续发展的前提，以此来取代传统“三高\n一低”的线性经济模式；同时，还要以生态化方向调整产业结构，大力\n发展生态化的工业、农业、旅游业、信息业等产业，在消费上实\u0000效\n以消费享乐主义为主导的消费模式向绿色、适度、可持续的坐态型滞\n费模式转变，开创出一条科技含量高、经济效益好、资源消耗低、跥\n境污染少、人力资源优势得到充分发挥的新型工业化道路。\n在精神文明的生态化建设方面，应树立和倡导生态化的价值观和\n思维方式，并对传统工业文明的各种错误观念和思维方式进行变革。\n具体来说，应树立起人与自然的和谐发展观，代际代内发展上的平等\n观，尊重一切生命的生态伦理观，循环利用资源的资源观，全面注重\n经济、社会、生态诸方面效益的综合效益观，环保节约、适度消费、\n精神至上的可持续消费观，批判和破除奴役自然的人类中心主义、片\n面追求经济效益的狭隘政绩观，以及物本主义、消费享乐主义、物质\n主义等错误价值观念，用基于生态文明理念的思维方式来取代过去那\n种片面追求功利而置资源和环境于不顾的思维方式，倡导以环保为价\n值取向的技术创新观，使生态文明理念成为全社会公认的社会责任意\n识。\n在政治文明(或制度文明)的生态化建设方面，应大力制定和实\n施有利于建设“资源节约型、环境保护型”社会的法律法规，坚持以生\n态文明理念来指导制度创新，努力建设“节约型政府”。节约型政府即\n生态型政府，即要“追求实现对一个政府的目标、法律、政策、职能、\n体制、机构、能力、文化等诸方面的生态化”。\n四、作用与支持\n①生态文明的作用(生态文明给三大文明带来了什么新东西)\n从物质文明方面——增加经济社会环境资源各方面协调发展的内\n容，消费方式增加环保节能减排卫生健康等绿色消费内容，生活环境\n依照自然规律建设和优化健康舒适安全人性化的环境空间。\n小榜学决——双串通奖攻略\n双精神文明方面——生态文明标志着人类处理人与自然关系的一\n种新视角、新思路和新行为模式。为人类发展提供了代际代内皆平等\n的可持续发展思想，并便敬畏自然吴爱万物环保节约等生态伦理成为\n人类道德建设的重要内容。培育生态人成为学校教育和社会教育的新\n目标。\n从政治文明方面——生态文明要求建立涵盖经济社会人文环境等\n内容的绿色GDP干部业绩考核制度。要求建立节约型政府。这些都是\n在原有的政治文明框架里塞进去的生态内容。\n②三大文明的支持(三大文明也为生态文明建设提供了有力的支持)\n从物质文明方面——为生态文明建设提供基础性的物质支持。解\n决环境问题离不开人财物的投入，特别是组织科研力量对新能源新材\n料新技术新产品进行自主创新。建设生态经济也需要将生态与发展经\n济结合起来，实现环保与市场经济发展的良性互动和价值双赢。\n从精神文明方面——为生态文明建设提供精神动力、思想保障和\n智力支持。绿色消费、循环经济、可持续发展等新思想，本身就是有\n强烈社会责任感的人士提出来的。生态文明建设离不开精神文明建设\n在价值观世界观认识论方法论方面的大力支持。\n从政治文明方面——为生态文明建设提供强有力的制度保障和促\n进作用。政治文明具有决策民主、调控性强、督导性强、执行力强、\n影响面宽等特点。通过法律法规、行政强制、税收杠杆、舆论宣传、\n基层民主等手段，在目标、法律、政策、组织、机制等方面为生态文\n明建设提供有力保障。\n学长解读 ; 生态文明是站在三个巨人肩膀上的一物质文明给它垫底 〈 出钱出\nBA) ， 精神文明给它导航 〈 出思想出观念 ) ， 政治文明给它撑腰 〈 出制度出\n‐275 ▾\n表格速览：\n文明\n生态文明的作用 对生态文明的支持\n类型\n物质 引导绿色生产(循环经济)、消 提供技术、资金支持(新能源研\n文明 费模式转型(可持续消费)。 发)；经济基础保障。\n精神 推动生态伦理观、绿色价值观普 提供思想动力(环保意识)、文化\n文明 及；批判人类中心主义。 创新(生态教育)。\n政治 要求制定生态政策(如绿色GDP 通过法律强制力、制度设计(如生\n文明 考核)、完善环保法规。 态补偿机制)保障生态目标实现。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":0,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。","含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":290,"sourceRange":{"startPage":290,"startY":48.72,"endPage":296,"endY":373.89},"sourceKind":"original","originalOrdinal":"3","sourceMetadata":["【重要程度: ☆☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":17,"excerpts":[{"page":290,"src":"./assets/environment/env838-e627def78419ab3f-290.webp"},{"page":291,"src":"./assets/environment/env838-e627def78419ab3f-291.webp"},{"page":292,"src":"./assets/environment/env838-e627def78419ab3f-292.webp"},{"page":293,"src":"./assets/environment/env838-e627def78419ab3f-293.webp"},{"page":294,"src":"./assets/environment/env838-e627def78419ab3f-294.webp"},{"page":295,"src":"./assets/environment/env838-e627def78419ab3f-295.webp"},{"page":296,"src":"./assets/environment/env838-e627def78419ab3f-296.webp"}]},{"id":"env838-bbafd09e401d5b67","subject":"环境学导论","chapter":"第17章 生态文明理论与实践","originalChapter":"第19章 生态文明理论与实践","originalChapterNumber":19,"section":"第2节 生态文明建设实践","originalSection":"第2节 生态文明建设实践","category":"knowledge","title":"排污权交易","question":"排污权交易","type":"简答题","answer":"[1] 定义\n排污权交易是指在一定区域内，在污染物排放总量不超过允许排\n放量的前提下，内部污染源之间通过货币交换的方式相互调剂排污量\n，从而达到减少排污量、保护环境的目的。\n[2] 具体做法\n①首先由政府部门确定出一定区域的环境质量目标，并据此评估\n该区域的环境容量。\n②推算污染物的最大允许排放量，并将最大允许排放量分割\n成若干规定的排放量，即若干排污权。\n③政府可以选择不同方式分配这些权利，并通过建立排污权\n交易市场使这种权利能合法地买卖。在排污权市场上，排污者从其\n利益出发，自主决定污染治理程度，从而买入或卖出排污权。\n[3]存在的问题\n①排污权交易以污染物总量控制为前提，而污染物排放总量\n应当基于当地环境容量也就是自净能力确定。但实际确定的污染物\n总量更多时候表现为最优污染排放量(由边际私人纯收益和边际外部\n成本共同决定)。也就是说，如果排污权交易建立在最优污染排放量\n基础上，污染物排放总量极大可能超出环境容量，毫无疑问会构成对\n环境的破坏。\n②环境标准似乎体现了污染源之间的公平，但实际上对于不同\n的排污企业，可能因为背景水平、治理难度等的差异并未公平地分摊\n削减污染的负荷。\n③排污权交易原则上禁止功能区之间排污许可证的转让，但\n在特殊情况下可以。这就是当环境污染压力大的地区向污染压力小\n的地区转让排污权时，适用两地环保部门协商制定的“兑换率”。然而\n，由于兑换率直接涉及两地的经济利益，可以想见达成一致是非常困\n难的，又会增加政府的管理成本。\n④非排污者可以进入市场购买排污权，从理论上来说违反了\n污染者付费原则。实际上将一部分责任转嫁给无辜的非排污者，由\n于非污染者的原因减少了污染，意味着在环境自净能力许可范围内\n又可以多排放，极不公平，长此以往，后患无穷。\n⑤如果节省的排污权在同一时期使用，又恰好遇到自净能力差\n的时期，就等同于超标排放。\n⑥由于许可证数量有限，持有者会产生囤积、投机的行为，许\n可证还可能成为行业或地区生产垄断一种方式。\n[学长解读 : 排污权交易 (Emissions Trading) 是典型的基于市场的环境经济政\n策工具 ， 核心远辑是在污染物排放总量控制的前提下 ， 将排污权量化为可交易\n的生产要素 ， 通过市场定价实现环境资源的优化配置 ， 以最低社会成本达成减\n排目标 。\n排污权交易的完整实践最早诞生于美国 ， 美国之后 ， 德国 、 英国 、 澳大利\n亚等国相继在大气 、 水污染物治理中引入排污权交易机制 。 我国最时的有关排\n污权交易的实践始于 1987 年 , 上海闵行区在黄浦江上游水源保护中开展水污染\n物排污指标有偿转让 ， 是国内最早的排污权交易实践探索 。\n截至 2024 年 11 月 ,我国排污权有偿使用和交易累计金额达 376.7 亿元 ,其中\n有偿使用金额 142.1 亿元 ， 市场化交易金额 234.6 亿元 ， 在多方面发挥了积极\n作用 :\n© 减排激励作用显现 : 企业通过技术改造减排可获得配额出售收益 ， 倒禹高\n污染企业转型升级 ， 推动环境资源向高效益产业流动 。\n© 区域发展形成标杆 : 浙江省交易规模长期居全国首位 ，2025 年全年成交额\n达 7.77 亿元 ; 山西 、 江苏 、 福建等地企业间交易占比高 ， 市场化程度更突\n出 。\n© 制度价值持续延伸 : 排污权从单纯的减排工具 ， 逐步成为要素市场化配置\n、 生态产品价值实现的重要载体 。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":1,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。","含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":296,"sourceRange":{"startPage":296,"startY":415.17,"endPage":298,"endY":585.89},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":["【重要程度:★☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":17,"excerpts":[{"page":296,"src":"./assets/environment/env838-bbafd09e401d5b67-296.webp"},{"page":297,"src":"./assets/environment/env838-bbafd09e401d5b67-297.webp"},{"page":298,"src":"./assets/environment/env838-bbafd09e401d5b67-298.webp"}]},{"id":"env838-b7220e10d69199ac","subject":"环境学导论","chapter":"第17章 生态文明理论与实践","originalChapter":"第19章 生态文明理论与实践","originalChapterNumber":19,"section":"第2节 生态文明建设实践","originalSection":"第2节 生态文明建设实践","category":"knowledge","title":"生态文明建设的中国实践","question":"生态文明建设的中国实践","type":"简答题","answer":"党的“十七大”报告提出“建设生态文明，基本形成节约能源资源\n和保护生态环境的产业结构、增长方式、消费模式”。这标志着我国\n开始了生态文明建设的实践探索。\n党的“十八大”，把生态文明建设纳入中国特色社会主义事业\n“五位一体”总体布局，首次把“美丽中国”作为生态文明建设的宏伟目\n标，将“中国共产党领导人民建设社会主义生态文明”写入党章，\n作为行动纲领。\n十八届三中全会提出加快建立系统完整的生态文明制度体系；\n十八届四中全会要求用严格的法律制度保护生态环境；\n十八届五中全会提出“五大发展理念”，将绿色发展作为“十三五\n”乃至更长时期经济社会发展的一个重要理念。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":0,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":298,"sourceRange":{"startPage":298,"startY":585.89,"endPage":300,"endY":63.06},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":["【重要程度: ☆☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":17,"excerpts":[{"page":298,"src":"./assets/environment/env838-b7220e10d69199ac-298.webp"},{"page":299,"src":"./assets/environment/env838-b7220e10d69199ac-299.webp"},{"page":300,"src":"./assets/environment/env838-b7220e10d69199ac-300.webp"}]},{"id":"env838-55178e5f65fa6025","subject":"环境学导论","chapter":"第17章 生态文明理论与实践","originalChapter":"第19章 生态文明理论与实践","originalChapterNumber":19,"section":"第3节 课后习题","originalSection":"第3节 课后习题","category":"exercise","title":"什么是生态文明?","question":"什么是生态文明?","type":"简答题","answer":"整理答案（按教材对应知识点摘录）：\n\n生态文明的含义：\n生态文明由生态和文明两个概念复合而来。简单地说，生态就\n是指一切生物的生存状态，以及它们之间和它与环境之间环环相扣\n的关系。从人类社会实践活动来讲，文明则是人类改造自然、改造\n社会和自我改造的结晶。\n把两个词合在一起，生态文明就是人类在追求社会进步的过程中\n，以尊重自然为前提，以和谐共生为宗旨，通过改造自然改造社会改\n造自我所取得的成果总和。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["根据所列知识点摘录整理，未逐题人工审定。"],"verified":false,"page":300,"sourceRange":{"startPage":300,"startY":99.81,"endPage":300,"endY":177.78},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":17,"references":[{"id":"env838-1290eceab517a544","title":"生态文明的含义","source":"环境学导论.pdf","page":286}],"excerpts":[{"page":300,"src":"./assets/environment/env838-55178e5f65fa6025-300.webp"}]},{"id":"env838-9c144d48f7a0a7eb","subject":"环境学导论","chapter":"第17章 生态文明理论与实践","originalChapter":"第19章 生态文明理论与实践","originalChapterNumber":19,"section":"第3节 课后习题","originalSection":"第3节 课后习题","category":"exercise","title":"生态文明与原始文明、农业文明和工业文明的区别是什么?","question":"生态文明与原始文明、农业文明和工业文明的区别是什么?","type":"简答题","answer":"原始文明：生产力水平较低，人类对自然的直接依赖强，局地利用以采集、狩猎等为主。\n农业文明：依靠土地和生物生产，通过耕作、灌溉等扩大自然改造，同时可能带来侵蚀及生态退化。\n工业文明：机械化及化石能源显著提高生产力，也扩大资源消耗、污染和生态影响。\n生态文明：在吸收既有文明成果的基础上，强调尊重自然规律、资源节约、环境友好和人与自然协调，将生态要求融入生产、生活及制度。\n上述是分析文明关系的概括，不代表不同历史阶段完全没有保护或破坏自然的差异。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":300,"sourceRange":{"startPage":300,"startY":177.78,"endPage":300,"endY":257.92},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":17,"excerpts":[{"page":300,"src":"./assets/environment/env838-9c144d48f7a0a7eb-300.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=286"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-23eaea78a68da793","subject":"环境学导论","chapter":"第17章 生态文明理论与实践","originalChapter":"第19章 生态文明理论与实践","originalChapterNumber":19,"section":"第3节 课后习题","originalSection":"第3节 课后习题","category":"exercise","title":"生态文明与物质文明、政治文明和精神文明文明的区别和联系是什么?","question":"生态文明与物质文明、政治文明和精神文明文明的区别和联系是什么?","type":"简答题","answer":"区别在于侧重点：物质文明主要关注生产力及物质生活条件，政治文明关注制度、治理和政治生活，精神文明关注思想、文化和道德，生态文明关注人与自然关系以及发展的生态基础和约束。\n联系：良好生态环境支撑生产生活；制度与法治保障生态保护；文化、伦理及知识影响公众行为；绿色技术和产业为生态改善提供物质能力。\n因此，生态文明应融入经济、政治和文化建设，其他文明建设也应在资源环境约束下发展。它们是相互支撑的维度，而非互相替代的同一概念。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":300,"sourceRange":{"startPage":300,"startY":257.92,"endPage":300,"endY":369.06},"sourceKind":"original","originalOrdinal":"3","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":17,"excerpts":[{"page":300,"src":"./assets/environment/env838-23eaea78a68da793-300.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=286"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-e76f85d62914c4a9","subject":"环境学导论","chapter":"第17章 生态文明理论与实践","originalChapter":"第19章 生态文明理论与实践","originalChapterNumber":19,"section":"第3节 课后习题","originalSection":"第3节 课后习题","category":"exercise","title":"举例说明我国生态文明建设的内容和特点。","question":"举例说明我国生态文明建设的内容和特点。","type":"简答题","answer":"可从制度、产业、空间和社会实践举例：\n①制度：完善生态环境法律、监管、信息公开与责任机制，例如生态环境法典的实施。\n②产业和能源：推动节能、清洁生产、循环利用和能源绿色转型。\n③空间与生态：生态保护红线、国家公园及重要生态系统保护修复。\n④城乡生活：绿色交通、垃圾分类、农村环境治理及公共生态空间建设。\n特点：强调系统治理、保护与发展协调、全社会参与以及长期责任。答题应把具体措施与改善环境质量和保障民生的效果联系起来，不以口号替代分析。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":300,"sourceRange":{"startPage":300,"startY":369.06,"endPage":300,"endY":449.48},"sourceKind":"original","originalOrdinal":"4","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":17,"excerpts":[{"page":300,"src":"./assets/environment/env838-e76f85d62914c4a9-300.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=286"},{"title":"生态环境部：2026年生态环境法典及施行说明","url":"https://www.mee.gov.cn/xxgk2018/xxgk/xxgk03/202604/t20260408_1148465.html","accessedOn":"2026-11-09"},{"title":"中国生物多样性保护战略与行动计划（2023—2030年）发布说明","url":"https://www.mee.gov.cn/xxgk/hjyw/202401/t20240118_1064111.shtml","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-24e7da4cdcca5ae6","subject":"环境学导论","chapter":"第17章 生态文明理论与实践","originalChapter":"第19章 生态文明理论与实践","originalChapterNumber":19,"section":"第3节 课后习题","originalSection":"第3节 课后习题","category":"exercise","title":"根据自己的理解，简要指出我国与国际生态文明建设的联系与区别。","question":"根据自己的理解，简要指出我国与国际生态文明建设的联系与区别。","type":"简答题","answer":"联系：我国生态文明建设与国际可持续发展实践都关注生态系统保护、资源效率、污染治理、气候变化、代际责任及公众参与，并可通过多边环境公约和科技合作相互促进。\n区别：我国有自身的发展阶段、人口资源条件、产业结构和治理制度，强调把生态要求贯穿现代化与系统治理；各国在责任分配、政策工具、消费水平和执行能力上也有不同。\n答题重点：从共同目标与具体路径差异分析，既借鉴国际有效经验，也根据国情选择措施；不把“国际”视为一种完全一致、没有内部差异的模式。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":300,"sourceRange":{"startPage":300,"startY":449.48,"endPage":301,"endY":70.01},"sourceKind":"original","originalOrdinal":"5","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":17,"excerpts":[{"page":300,"src":"./assets/environment/env838-24e7da4cdcca5ae6-300.webp"},{"page":301,"src":"./assets/environment/env838-24e7da4cdcca5ae6-301.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=286"},{"title":"中国生物多样性保护战略与行动计划（2023—2030年）发布说明","url":"https://www.mee.gov.cn/xxgk/hjyw/202401/t20240118_1064111.shtml","accessedOn":"2026-11-09"},{"title":"中国的能源转型白皮书（英文全文）","url":"https://english.www.gov.cn/archive/whitepaper/202408/29/content_WS66d012e8c6d0868f4e8ea52e.html","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-0b4725c3abcef706","subject":"环境学导论","chapter":"第18章 可持续发展","originalChapter":"第20章 可持续发展","originalChapterNumber":20,"section":"第1节 概述","originalSection":"第1节 概述","category":"knowledge","title":"可持续发展概念","question":"可持续发展概念","type":"简答题","answer":"既能满足当代人的需要，又不对后代人满足其需要的能力构成\n危害的发展，即实现代际公平。\n[ 学长解读 ; 这个定义用一句话把横纵两个维度都框进去了 。 横向维度一 “这一代人内\n部要公平 。 你不能让发达国家继续把污染转嫁给发展中国家 ， 也不能让富人消费穷人\n买单 。 纵向维度 _ 这一代人和下一代人之间要公平 。 你不能为了今天的 GDP 把地下\n[待核对] RMF. HAKKL, RERFUUAHBELAML SC,\n有关可持续发展的定义有 100 多种 ， 但归纳起来五个核心要素 : (上 ) 环境与经济的\n紧密联系一 “不能把环保和挣钱当成二选一 ; @) 代际公平一下一代的命也是命 ; G@)\n代内公平一 “同一代人不管你生在哪个国家什么阶层都应享有同等的发展权利和环\nKARA; @ 生活质量提高与生态保护同步 -一发展不只是 GDP 增长 ,还包括天蓝不蓝\n水清不清空气好不好 ; (6) 公众参与环保不能光儒政府和企业 ， 每个公民都有责任\n也有权利参与 。\n可持续发展是一个集生态 、 环境 、 经济和政治为一体的综合性概念 。 它不是某一\n| 个领域的事 ， 是把所有这些领域串在一起的总纲 。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。","含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":302,"sourceRange":{"startPage":302,"startY":111.23,"endPage":302,"endY":552.61},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":["【重要程度："],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":18,"excerpts":[{"page":302,"src":"./assets/environment/env838-0b4725c3abcef706-302.webp"}]},{"id":"env838-5f71079a17af853d","subject":"环境学导论","chapter":"第18章 可持续发展","originalChapter":"第20章 可持续发展","originalChapterNumber":20,"section":"第1节 概述","originalSection":"第1节 概述","category":"knowledge","title":"可持续发展的三大原则","question":"可持续发展的三大原则","type":"简答题","answer":"(1) 公平性原则\n一个地区的发展不应以损害其他地区的发展为代价，既满足当\n代人的需要，又不损害后代的发展能力。\n(2) 持续性原则\n人类经济和社会的发展不能超越资源和环境的承载能力。在满足\n需要的同时必须有限制因素，即发展的概念中包含着制约的因素，\n因此，在满足人类需要的过程中，必然有限制因素的存在。\n(3)共同性原则\n各国可持续发展的模式虽然不同，但公平性和持续性原则是共同\n的。各个国家要实现可持续发展都需要适当调整国内和国际政策。\n只有全人类共同努力，才能实现可持续发展的总目标，从而将人类\n的局部利益与整体利益结合起来。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":0,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":302,"sourceRange":{"startPage":302,"startY":552.61,"endPage":303,"endY":313.57},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":["【重要程度: ☆☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":18,"excerpts":[{"page":302,"src":"./assets/environment/env838-5f71079a17af853d-302.webp"},{"page":303,"src":"./assets/environment/env838-5f71079a17af853d-303.webp"}]},{"id":"env838-6252494617b85d92","subject":"环境学导论","chapter":"第18章 可持续发展","originalChapter":"第20章 可持续发展","originalChapterNumber":20,"section":"第1节 概述","originalSection":"第1节 概述","category":"knowledge","title":"可持续发展的基本内涵","question":"可持续发展的基本内涵","type":"简答题","answer":"可持续发展的内涵可以归纳如下几点。\n①突出发展的主题。发展与经济增长有根本区别，发展是\n集社会、科技、文化、环境等多项因素于一体的完整现象，是\n人类共同的和普遍的权利，发达国家和发展中国家都享有平等的\n发展权利。\n②发展的可持续性。人类的经济和社会的发展不能超越资源\n和环境的承载能力。\n③人与人关系的公平性。当代人在发展与消费应努力做到使\n后代人有同样的发展机会，同一代人中一部分人的发展不应当损\n害另一部分人的利益。\n④人与自然的协调共生。人类必须建立新的道德观念和价\n值标准，尊重自然，师法自然，保护自然，与之和谐相处。\n学长解读 : 这四条内涵四条串起来就是 : 我们要发展 〈 不能停 ) 、 要能\n持续 (不能竭泽而渔 ) 、 要公平 (对后人对同代都公平 ) 、 要和谐 〈 对\n自然也讲公平 ) 。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":0,"pastExamYears":[],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。","含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":303,"sourceRange":{"startPage":303,"startY":313.57,"endPage":304,"endY":58.76},"sourceKind":"original","originalOrdinal":"3","sourceMetadata":["【重要程度: ☆☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":18,"excerpts":[{"page":303,"src":"./assets/environment/env838-6252494617b85d92-303.webp"},{"page":304,"src":"./assets/environment/env838-6252494617b85d92-304.webp"}]},{"id":"env838-841c1ae90fbc65d7","subject":"环境学导论","chapter":"第18章 可持续发展","originalChapter":"第20章 可持续发展","originalChapterNumber":20,"section":"第2节 循环经济","originalSection":"第2节 循环经济","category":"knowledge","title":"循环经济的概念","question":"循环经济的概念","type":"简答题","answer":"循环经济即物质闭环流动型经济，指在人、自然资源和科学技术\n的大系统内，在资源投入、企业生产、产品消费及其废弃的全过程中\n，把传统的依赖资源消耗的线形增长经济，转变为依靠生态型资源循\n环来发展的经济。\n其目的是通过资源高效和循环利用，实现污染的低排放甚至零排\n放，保护环境，实现社会、经济与环境的可持续发展。\n[待核对] 重油 - ert 低压燕汽 、 部分高压蒸汽\n[待核对] DR Oe eR\n[待核对] ARAMA AE 制建材\n20-1 某造纸厂循环工艺示意图","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2024],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。","含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":304,"sourceRange":{"startPage":304,"startY":146.84,"endPage":304,"endY":624.96},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":["2024(简—简述循环经济的原则)，【重要程度："],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":18,"excerpts":[{"page":304,"src":"./assets/environment/env838-841c1ae90fbc65d7-304.webp"}]},{"id":"env838-2dbd7c6960df71be","subject":"环境学导论","chapter":"第18章 可持续发展","originalChapter":"第20章 可持续发展","originalChapterNumber":20,"section":"第2节 循环经济","originalSection":"第2节 循环经济","category":"knowledge","title":"循环经济的原则","question":"循环经济的原则","type":"简答题","answer":"循环经济要求以“3R原则”为经济活动的行为准则。3R原则为减\n量化(Reduce) 原则、再使用(Reuse) 原则和再循环(Recycle) 原\n则。\n(1) 减量化原则\n减量化原则要求用较少的原料和能源投入来达到既定的生产目\n的或消费目的，进而到从经济活动的源头就注意节约资源和减少污\n染。\n(2) 再使用原则\n再使用原则要求制造产品和包装容器能够以初始的形式被反复\n使用。再使用原则要求抵制当今世界一次性用品的泛滥，生产者应\n该将制品及其包装当作一种日常生活器具来设计，使其像餐具和背\n包一样可以被再三使用。再使用原则还要求尽量延长产品的使用期，\n而不是非常快地更新换代。\n(3) 再循环原则\n再循环原则要求生产出来的物品在完成其使用功能后再变成可\n以利用的资源，而不是不可恢复的垃圾。按照循环经济的思想，再循\n环有两种情况，一种是原级再循环，即废品被循环用来产生同种类型\n的新产品，如报纸再生报纸、易拉罐再生易拉罐等；另一种是次级再\n循环，即将废物资源转化成其他产品的原料。原级再循环在减少原材\n料消耗上面达到的效率要比次级再循环高得多，是循环经济追求的理\n想境界。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2024],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":304,"sourceRange":{"startPage":304,"startY":624.96,"endPage":305,"endY":569.47},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":["2024(简—简述循环经济的原则)，【重要程度： 】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":18,"excerpts":[{"page":304,"src":"./assets/environment/env838-2dbd7c6960df71be-304.webp"},{"page":305,"src":"./assets/environment/env838-2dbd7c6960df71be-305.webp"}]},{"id":"env838-20324c10f1d29947","subject":"环境学导论","chapter":"第18章 可持续发展","originalChapter":"第20章 可持续发展","originalChapterNumber":20,"section":"第2节 循环经济","originalSection":"第2节 循环经济","category":"knowledge","title":"循环经济与传统经济的区别","question":"循环经济与传统经济的区别","type":"简答题","answer":"传统经济是一种由“资源—产品—污染排放”所构成的物质单向\n流动的经济。在这种经济中，人们以越来越高的强度把地球上的物质\n和能源开发出来，在生产加工和消费过程中又把污染和废物大量地排\n放到环境中去，对资源的利用常常是粗放的和一次性的，通过把资源\n持续不断地变成废物来实现经济的数量型增长，导致许多自然资源的\n短缺与枯竭，并酿成灾难性环境污染后果。\n循环经济倡导的是一种建立在物质不断循环利用基础上的经济\n发展模式，组织成一个“资源—产品—再生资源”的物质反复循环流动\n的过程，使得整个经济系统以及生产和消费的过程基本上不产生或者\n只产生很少的废弃物，只有放错地方的资源，而没有真正的废弃物，\n其特征是自然资源的低投入、高利用和废弃物的低排放，从而\n根本上消解长期以来环境与发展之间的尖锐冲突。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":1,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":305,"sourceRange":{"startPage":305,"startY":569.47,"endPage":306,"endY":308.44},"sourceKind":"original","originalOrdinal":"3","sourceMetadata":["【重要程度: ★☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":18,"excerpts":[{"page":305,"src":"./assets/environment/env838-20324c10f1d29947-305.webp"},{"page":306,"src":"./assets/environment/env838-20324c10f1d29947-306.webp"}]},{"id":"env838-8ad1f1b71e55db41","subject":"环境学导论","chapter":"第18章 可持续发展","originalChapter":"第20章 可持续发展","originalChapterNumber":20,"section":"第3节 清洁生产","originalSection":"第3节 清洁生产","category":"knowledge","title":"治理工业污染无法从根本上解决的原因","question":"治理工业污染无法从根本上解决的原因","type":"简答题","answer":"①随着生产的发展以及人们环境意识的提高，工业污染物\n的种类检测越来越多，规定控制的污染物(特别是有毒有害污染物\n)的排放标准也越来越严格，从而对污染治理与控制的要求也越来\n越高。\n②由于污染治理技术有限，治理污染实质上很难达到彻底\n消除污染的目的。\n③只着眼于末端处理的办法，不仅需要投资，而且使一些可\n回收的资源得不到有效的回收利用而流失，使企业原材料消耗增\n高，产品成本增加，经济效益下降，从而影响企业治理污染的积\n极性和主动性。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":0,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":306,"sourceRange":{"startPage":306,"startY":351.7,"endPage":306,"endY":722.22},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":["【重要程度: ☆☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":18,"excerpts":[{"page":306,"src":"./assets/environment/env838-8ad1f1b71e55db41-306.webp"}]},{"id":"env838-08c8f8b23de4b441","subject":"环境学导论","chapter":"第18章 可持续发展","originalChapter":"第20章 可持续发展","originalChapterNumber":20,"section":"第3节 清洁生产","originalSection":"第3节 清洁生产","category":"knowledge","title":"清洁生产的概念","question":"清洁生产的概念","type":"简答题","answer":"清洁生产是这样一种生产产品的方法，借助这种方法，所有的原\n料和能量在原料资源-生产-消费-二次原料资源的循环中得到最合理\n和综合的利用，同时对环境的任何作用都不致破坏它的正常功能。这\n种生产的实际活动对环境所造成的影响不超过允许的环境卫生标准，\n同时，部分原材料可能转化成长期存放或埋藏的废料。\n清洁生产的定义包含2个全过程控制：生产全过程和产品整个生\n命周期全过程。对生产过程而言，清洁生产包括节约原材料与能源，\n尽可能不用有毒原材料并在生产过程中就减少它们的数量和毒性；\n对产品而言，则是从原材料获取到产品最终处置过程中，尽可能将对\n环境的影响减小到最低。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2014,2015,2025],"needsReview":true,"reviewReasons":["含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":306,"sourceRange":{"startPage":306,"startY":722.22,"endPage":307,"endY":366.08},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":["2014、2015(名) , 2025( 简) , 【重要程度: 】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":18,"excerpts":[{"page":306,"src":"./assets/environment/env838-08c8f8b23de4b441-306.webp"},{"page":307,"src":"./assets/environment/env838-08c8f8b23de4b441-307.webp"}]},{"id":"env838-5c54402f3b2947e6","subject":"环境学导论","chapter":"第18章 可持续发展","originalChapter":"第20章 可持续发展","originalChapterNumber":20,"section":"第3节 清洁生产","originalSection":"第3节 清洁生产","category":"knowledge","title":"清洁生产的内涵","question":"清洁生产的内涵","type":"简答题","answer":"清洁生产本质上是一种对生产过程与产品采取整体预防的环境\n策略，以减少或者消除它们对人类和环境的可能危害，同时充分满足\n人类需要，使社会经济效益最大化的一种生产模式。\n清洁生产的观念主要强调3个重点：①清洁能源，包括开发节能\n技术，尽可能开发利用再生能源以及合理利用常规能源；②清洁生\n产过程，包括尽可能不用或少用有毒有害原料和中间产品；对原材料\n和中间产品进行回收，改善管理，提高效率；③清洁产品，包括以不\n危害人体健康和生态环境为主导因素来考虑产品的制造过程甚至使\n用之后的回收利用，减少原材料和能源使用。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":307,"sourceRange":{"startPage":307,"startY":366.08,"endPage":307,"endY":704.85},"sourceKind":"original","originalOrdinal":"3","sourceMetadata":["【重要程度："],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":18,"excerpts":[{"page":307,"src":"./assets/environment/env838-5c54402f3b2947e6-307.webp"}]},{"id":"env838-7d83063cbc3e025f","subject":"环境学导论","chapter":"第18章 可持续发展","originalChapter":"第20章 可持续发展","originalChapterNumber":20,"section":"第3节 清洁生产","originalSection":"第3节 清洁生产","category":"knowledge","title":"清洁生产的基本内容","question":"清洁生产的基本内容","type":"简答题","answer":"清洁生产的基本内容包括清洁过程控制、清洁生产目标和清洁生\n产审核。\n[1]清洁过程控制\n清洁生产的定义包含了两个清洁过程控制：生产全过程和产品\n周期全过程。对生产过程而言，清洁生产包括节约原材料和能源，淘\n汰有毒有害的原材料，并在全部排放物和废物离开生产过程以前，尽\n可能减少它们的排放量和毒性。对产品而言，清洁生产旨在减少产品\n整个生命周期过程中从原料的提取到产品的最终处置对人类和环境\n的影响。\n[2]清洁生产目标\n根据经济可持续发展对资源和环境的要求，清洁生产谋求达到\n2个目标：①通过资源的综合利用，短缺资源的代用，二次能源的利\n用，以及节能、降耗、节水，合理利用自然资源，减缓资源的耗竭；\n②减少废物和污染物的排放，促进工业产品的生产、消耗过程与环境\n相融，降低工业活动对人类和环境的风险。\n[3]清洁生产审核\n清洁生产审核，是审核人员按照一定的程序对正在运行的生产过\n程进行系统分析和评价的过程，也是审核人员通过对企业的具体生\n产工艺、设备和操作的诊断，找出能耗高、物耗高、污染重的原因，\n掌握废物的种类、数量以及原因的详尽资料，提出减少有毒和有害物\n料的使用、产生以及废物产生的备选方案，经过对备选方案的技术经\n济及环境可行性分析，选定可供实施的清洁生产方案的分析和评估过\n程。\n学长解读 : 三者的关系可以这样理解一过程控制是手段 (你用什么方法做到\n清洁 ) ， 目标是方向 〈 你做到什么程度算清洁达标 ) ， 审核是保障 〈 你怎么检\n查和持续改进 ) 。 缺了过程控制就是空谈目标 ， 缺了目标就是谋目行动 ， 缺了\n审核就是不知道自己做得好不好 。 三者构成 PDCA 御环一 “Plan GRAM)\n、Do (过程控制 ) 、Check (审核评估 ) 、Aect (改进提升 ) 。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[2025],"needsReview":true,"reviewReasons":["含图片OCR文字；低置信度及图表请以对应原图核对。","含图片、公式或图示星级；无法可靠转写的位置请结合对应原图核对。"],"verified":false,"page":307,"sourceRange":{"startPage":307,"startY":704.85,"endPage":309,"endY":123.33},"sourceKind":"original","originalOrdinal":"4","sourceMetadata":["2025( 简), 【重要程度: 】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":18,"excerpts":[{"page":307,"src":"./assets/environment/env838-7d83063cbc3e025f-307.webp"},{"page":308,"src":"./assets/environment/env838-7d83063cbc3e025f-308.webp"},{"page":309,"src":"./assets/environment/env838-7d83063cbc3e025f-309.webp"}]},{"id":"env838-5d48d0321643acdd","subject":"环境学导论","chapter":"第18章 可持续发展","originalChapter":"第20章 可持续发展","originalChapterNumber":20,"section":"第3节 清洁生产","originalSection":"第3节 清洁生产","category":"knowledge","title":"我国清洁生产审核实践","question":"我国清洁生产审核实践","type":"简答题","answer":"我国推进清洁生产的过程大体可以分为3个阶段。\n①清洁生产的启动阶段。1992~ 1997年是我国启动清洁生产的阶\n段，这个阶段的基本特征是以宣传示范推动清洁生产。\n②清洁生产的政策实践。1997~ 2003年是清洁生产的政策实践阶\n段，这个阶段的基本特征是在继续清洁生产培训和审核示范\n活动基础上，转向促进清洁生产的政策机制建立。\n③清洁生产的深化发展。2003 年以后至现在，随着《中\n华人民共和国清洁生产促进法》的颁布实施( 2003 年1月1 日)，\n我国清洁生产进入一个新的阶段，这个阶段的基本特征是清洁生产\n正以多样性和内涵拓展的方式深化发展。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":309,"sourceRange":{"startPage":309,"startY":123.33,"endPage":309,"endY":496.14},"sourceKind":"original","originalOrdinal":"5","sourceMetadata":["【重要程度: ☆☆☆"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":18,"excerpts":[{"page":309,"src":"./assets/environment/env838-5d48d0321643acdd-309.webp"}]},{"id":"env838-fc71655305df8e2b","subject":"环境学导论","chapter":"第18章 可持续发展","originalChapter":"第20章 可持续发展","originalChapterNumber":20,"section":"第3节 清洁生产","originalSection":"第3节 清洁生产","category":"knowledge","title":"《清洁生产审核暂行办法》的原则","question":"《清洁生产审核暂行办法》的原则","type":"简答题","answer":"①以企业为主体。清洁生产审核的对象是企业，是围绕企业开展\n的，离开企业，所有工作都无法开展。\n②自愿审核与强制审核相结合。对污染物排放达到国家和地\n方规定的排放标准以及总量控制指标的企业，可按照自愿原则开展\n清洁生产审核；对于污染物排放超过国家和地方规定的标准或者总\n量控制指标的企业，以及使用有毒、有害原料进行生产或者在生产中\n排放有毒、有害物质的企业，应依法强制实施清洁生产审核。\n③企业自主审核与外部协助审核相结合。企业对自身的产品、\n原料、生产工艺、资源能源利用效率、污染物排放以及内部管理状况\n比较熟悉，可根据对清洁生产审核方法和程序的掌握程度以及人员\n力量情况，全部或部分开展自主审核。如果企业没有能力自主审核，\n可寻求外部专家的指导和帮助。\n④因地制宜、注重实效、逐步开展。各地区经济发展很不均衡，\n不同地区、不同行业的企业在工艺技术、资源消耗、污染排放等方面\n的情况千差万别，在实施清洁生产审核时应结合本地实际情况，因地\n制宜地开展工作。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":0,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":309,"sourceRange":{"startPage":309,"startY":496.14,"endPage":310,"endY":340.0},"sourceKind":"original","originalOrdinal":"6","sourceMetadata":["【重要程度:☆☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":18,"excerpts":[{"page":309,"src":"./assets/environment/env838-fc71655305df8e2b-309.webp"},{"page":310,"src":"./assets/environment/env838-fc71655305df8e2b-310.webp"}]},{"id":"env838-a3aad97a7355ec1d","subject":"环境学导论","chapter":"第18章 可持续发展","originalChapter":"第20章 可持续发展","originalChapterNumber":20,"section":"第3节 清洁生产","originalSection":"第3节 清洁生产","category":"knowledge","title":"我国清洁生产发展存在的问题","question":"我国清洁生产发展存在的问题","type":"简答题","answer":"(1 )对清洁生产认识的高度不够\n一些地方对清洁生产的本质认识不够清楚，没有完全认识到清洁\n生产在转变经济发展方式，提高经济增长质量，建设资源节约型、环\n境友好型社会中的重要作用。清洁生产工作更注重在大型企业开展，\n忽视了中小企业。企业普遍缺乏依法实施清洁生产的主动意识，对源\n头预防、过程控制的清洁生产理念认识不够，重末端治理。\n(2)清洁生产没有全面展开\n实施清洁生产审核的企业数量比例偏低。\n(3 )清洁生产科技开发投入不够\n清洁生产科技开发投入不够，重金属污染减量、有毒有害原料\n替代和主要污染物削减等领域缺乏先进有效的技术。同时，成熟\n适用技术推广应用不够，制约了清洁生产技术水平的提升。\n(4)政策机制有待进一步健全完善\n清洁生产促进法规定的一些制度还没有真正建立，如清\n洁生产信息系统和技术咨询服务体系，清洁生产的技术研发、成\n果转化和推广机制等有待健全；同时清洁生产推行过程中，\n尚未充分发挥市场机制的作用。大量消耗资源的产品和包装物强制回\n收目录和具体回收办法还没有出台。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":0,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":310,"sourceRange":{"startPage":310,"startY":340.0,"endPage":312,"endY":67.54},"sourceKind":"original","originalOrdinal":"7","sourceMetadata":["【重要程度: ☆☆☆☆☆】"],"history":[],"next":0,"interval":0,"star":false,"master":false,"chapterNumber":18,"excerpts":[{"page":310,"src":"./assets/environment/env838-a3aad97a7355ec1d-310.webp"},{"page":311,"src":"./assets/environment/env838-a3aad97a7355ec1d-311.webp"},{"page":312,"src":"./assets/environment/env838-a3aad97a7355ec1d-312.webp"}]},{"id":"env838-63f0145ae377ea0e","subject":"环境学导论","chapter":"第18章 可持续发展","originalChapter":"第20章 可持续发展","originalChapterNumber":20,"section":"第4节 课后习题","originalSection":"第4节 课后习题","category":"exercise","title":"什么是可持续发展?可持续发展的原则和基本内涵分别是什么?","question":"什么是可持续发展?可持续发展的原则和基本内涵分别是什么?","type":"简答题","answer":"可持续发展是满足当代人需要、同时不损害后代满足自身需要能力的发展。\n本资料概括三大原则：①公平性，包括代内和代际公平；②持续性，发展活动应维持资源、环境和生态系统的长期支持能力；③共同性，全球性问题需要各国及社会主体合作。\n基本内涵：协调经济发展、社会进步和生态环境保护，以人的福祉为目标，在资源环境约束下改善发展质量，并兼顾不同地区和群体的机会。\n实践应结合节约高效利用、清洁生产、生态保护、社会保障和制度创新，避免只追求短期产出。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":312,"sourceRange":{"startPage":312,"startY":103.79,"endPage":312,"endY":208.55},"sourceKind":"original","originalOrdinal":"1","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":18,"excerpts":[{"page":312,"src":"./assets/environment/env838-63f0145ae377ea0e-312.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=301"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-ab9b27a508de1193","subject":"环境学导论","chapter":"第18章 可持续发展","originalChapter":"第20章 可持续发展","originalChapterNumber":20,"section":"第4节 课后习题","originalSection":"第4节 课后习题","category":"exercise","title":"循环经济的由来是什么?有哪些技术经济特征?","question":"循环经济的由来是什么?有哪些技术经济特征?","type":"简答题","answer":"由来：传统线性经济大量取用资源、生产消费后排放废物，造成资源与环境压力；生态系统循环利用的启示、清洁生产及资源回收实践推动了循环经济理念发展。\n技术经济特征：①把资源消耗和废物产生纳入全过程管理；②优先减量，提高材料和能源效率；③延长产品寿命并促进再使用、维修、再制造；④将适合的废物转化为可用资源；⑤通过企业、园区、区域网络形成协同；⑥综合考虑环境收益、经济成本及社会条件。\n循环并非百分之百无损，必须关注能耗、品质及有害物累积。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":312,"sourceRange":{"startPage":312,"startY":208.55,"endPage":312,"endY":288.23},"sourceKind":"original","originalOrdinal":"2","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":18,"excerpts":[{"page":312,"src":"./assets/environment/env838-ab9b27a508de1193-312.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=301"},{"title":"循环经济促进法","url":"https://www.miit.gov.cn/zwgk/zcwj/flfg/art/2020/art_a9e2ed15775d4cb68c0cebd597f41cd2.html","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-8c426d34cc285eb7","subject":"环境学导论","chapter":"第18章 可持续发展","originalChapter":"第20章 可持续发展","originalChapterNumber":20,"section":"第4节 课后习题","originalSection":"第4节 课后习题","category":"exercise","title":"循环经济与传统经济的区别是什么?","question":"循环经济与传统经济的区别是什么?","type":"简答题","answer":"传统线性经济通常表现为“资源获取—生产—消费—废弃”，价值与物质在废弃环节大量流失，容易把环境损害作为外部成本。\n循环经济重视全生命周期：在设计和生产阶段减量，在使用阶段延寿、维修和再使用，在适合条件下回收再生，并通过产业协作提高资源效率。\n比较重点：资源流动由单向为主转向多层循环；管理由末端处理拓展到源头及全过程；评价由短期产出拓展到资源、环境及长期效益。\n最终仍需对不可避免的残余物安全处置，不能把回收率提升当成全部环境绩效。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":312,"sourceRange":{"startPage":312,"startY":288.23,"endPage":312,"endY":369.45},"sourceKind":"original","originalOrdinal":"3","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":18,"excerpts":[{"page":312,"src":"./assets/environment/env838-8c426d34cc285eb7-312.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=301"},{"title":"循环经济促进法","url":"https://www.miit.gov.cn/zwgk/zcwj/flfg/art/2020/art_a9e2ed15775d4cb68c0cebd597f41cd2.html","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-48636fcfdef3d639","subject":"环境学导论","chapter":"第18章 可持续发展","originalChapter":"第20章 可持续发展","originalChapterNumber":20,"section":"第4节 课后习题","originalSection":"第4节 课后习题","category":"exercise","title":"结合所学知识，举例说明“3R”原则的内容。","question":"结合所学知识，举例说明“3R”原则的内容。","type":"简答题","answer":"①减量化（Reduce）：从源头减少资源消耗和废物产生，如轻量化设计、提高成材率、避免过度包装。\n②再利用（Reuse）：在不改变或适当修复产品基本用途的情况下重复使用，如周转箱、可维修设备和可重复使用容器。\n③资源化（Recycle）：把适合的废物加工为再生资源，如废金属回炉、合规废纸再生和再生水利用。\n三者应按具体生命周期收益协调，通常优先预防和减量；再利用需保证卫生、安全与实际周转次数，资源化需管理能耗及二次污染。不能为了“回收”而鼓励不必要的消费。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":312,"sourceRange":{"startPage":312,"startY":369.45,"endPage":312,"endY":449.76},"sourceKind":"original","originalOrdinal":"4","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":18,"excerpts":[{"page":312,"src":"./assets/environment/env838-48636fcfdef3d639-312.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=301"},{"title":"循环经济促进法","url":"https://www.miit.gov.cn/zwgk/zcwj/flfg/art/2020/art_a9e2ed15775d4cb68c0cebd597f41cd2.html","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-51a83bbee7332f52","subject":"环境学导论","chapter":"第18章 可持续发展","originalChapter":"第20章 可持续发展","originalChapterNumber":20,"section":"第4节 课后习题","originalSection":"第4节 课后习题","category":"exercise","title":"清洁生产的内涵和目标是什么?","question":"清洁生产的内涵和目标是什么?","type":"简答题","answer":"清洁生产强调持续改进设计、工艺、原辅料、能源和管理，在生产及产品服务的全过程预防或减少污染。\n内涵：①源头削减，减少有毒有害原料及不合理消耗；②过程控制，提高物料与能源利用率；③产品和服务生命周期优化；④将技术措施与管理、员工参与及审核持续改进结合。\n目标：减少资源和能源消耗、污染物及废物产生，降低人类健康与环境风险，同时改善企业效率和竞争力。\n它与末端治理相互补充，但不能把仅安装污水或废气处理设施等同于已经实现全过程清洁生产。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":312,"sourceRange":{"startPage":312,"startY":449.76,"endPage":312,"endY":529.63},"sourceKind":"original","originalOrdinal":"5","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":18,"excerpts":[{"page":312,"src":"./assets/environment/env838-51a83bbee7332f52-312.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=301"},{"title":"生态环境部：啤酒制造业清洁生产标准","url":"https://www.mee.gov.cn/ywgz/fgbz/bz/bzwb/other/qjscbz/200610/t20061001_78198.shtml","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-32b683964c7e43de","subject":"环境学导论","chapter":"第18章 可持续发展","originalChapter":"第20章 可持续发展","originalChapterNumber":20,"section":"第4节 课后习题","originalSection":"第4节 课后习题","category":"exercise","title":"什么叫清洁生产工艺?试举一例加以说明。","question":"什么叫清洁生产工艺?试举一例加以说明。","type":"简答题","answer":"清洁生产工艺是在满足产品功能与质量要求的前提下，通过原辅料选择、反应及加工路线、设备和操作控制等改进，减少资源消耗、污染产生及风险的生产方式。\n工艺示例：在适宜的啤酒或饮料生产环节，优化清洗程序与用水控制，分流回收可利用水，减少高浓度物料进入下水道，并对余热和适合副产物开展利用。\n分析应说明“原损失点—工艺改进—资源与污染收益”，并核实食品卫生和产品质量。示例为工艺思路，不代表未经验证就可直接套用于任一工厂。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":312,"sourceRange":{"startPage":312,"startY":529.63,"endPage":312,"endY":608.48},"sourceKind":"original","originalOrdinal":"6","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":18,"excerpts":[{"page":312,"src":"./assets/environment/env838-32b683964c7e43de-312.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=301"},{"title":"生态环境部：啤酒制造业清洁生产标准","url":"https://www.mee.gov.cn/ywgz/fgbz/bz/bzwb/other/qjscbz/200610/t20061001_78198.shtml","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"},{"id":"env838-34b4e3bb8ef059ac","subject":"环境学导论","chapter":"第18章 可持续发展","originalChapter":"第20章 可持续发展","originalChapterNumber":20,"section":"第4节 课后习题","originalSection":"第4节 课后习题","category":"exercise","title":"举例说明我国清洁生产的特点和存在问题。","question":"举例说明我国清洁生产的特点和存在问题。","type":"简答题","answer":"特点：我国清洁生产实践把企业审核、技术改造、重点行业管理与节能减排等相结合，既包括单个企业效率改善，也与园区及产业链循环协作衔接。\n实例：食品制造优化清洗与物料回收；生态工业园通过公共设施及副产品利用减少系统资源负担。\n问题：部分企业重末端、轻预防；审核与实际改进脱节；中小企业资金、人员及技术能力有限；基础数据不足；跨企业交换存在质量、市场和责任障碍。\n改进：把物料能量平衡、可量化目标、持续监测和长效管理结合，提供技术及融资支持，避免仅形成纸面审核报告。","source":"环境学导论.pdf","sourceUrl":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view","version":"shared","importance":null,"pastExamYears":[],"needsReview":false,"reviewReasons":[],"verified":false,"page":312,"sourceRange":{"startPage":312,"startY":608.48,"endPage":312,"endY":798},"sourceKind":"original","originalOrdinal":"7","sourceMetadata":[],"history":[],"next":0,"interval":0,"star":false,"master":false,"answerKind":"compiled","chapterNumber":18,"excerpts":[{"page":312,"src":"./assets/environment/env838-34b4e3bb8ef059ac-312.webp"}],"answerRevision":"exercise-research-2026-11-09-v1","answerSources":[{"title":"环境学导论：对应章节知识点","url":"https://drive.google.com/file/d/1PU17frjos8-m8u2OiRKgXwy2QO-ofBgi/view#page=301"},{"title":"生态环境部：啤酒制造业清洁生产标准","url":"https://www.mee.gov.cn/ywgz/fgbz/bz/bzwb/other/qjscbz/200610/t20061001_78198.shtml","accessedOn":"2026-11-09"},{"title":"苏州市政府：苏州工业园区能源绿色转型与循环经济实践","url":"https://www.suzhou.gov.cn/szsrmzf/qxkx/202412/9bd49c92296c4630896923230d23dae4.shtml","accessedOn":"2026-11-09"}],"answerStatus":"教材与公开资料整理，非原书标准答案"}];
